CREATE OR REPLACE FUNCTION truss.accepted_document(selected_document text, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;captured_revision int;archive truss.schema_doc%ROWTYPE;module jsonb;source jsonb;request truss.catalog_registration_request%ROWTYPE;encoded bytea;
BEGIN
 PERFORM truss.runtime_person(false);
 IF selected_document IS NULL OR octet_length(selected_document) NOT BETWEEN 1 AND 4096 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN RAISE EXCEPTION 'bounded document selection required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'selected runtime required' USING ERRCODE='0A000';END IF;
 IF current_setting('transaction_read_only')='on' THEN
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 ELSE
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 END IF;
 IF captured_revision<1 THEN RAISE EXCEPTION 'accepted catalog required' USING ERRCODE='0A000';END IF;
 SELECT * INTO archive FROM truss.schema_doc WHERE rev<=captured_revision AND doc_id=selected_document ORDER BY rev DESC LIMIT 1;
 IF NOT FOUND OR jsonb_array_length(archive.document::jsonb->'modules')=0 THEN RAISE EXCEPTION 'authorized document required' USING ERRCODE='42501';END IF;
 FOR module IN SELECT value FROM jsonb_array_elements(archive.document::jsonb->'modules') LOOP
  IF NOT truss.runtime_can_read(selected_document,module->>'id') THEN RAISE EXCEPTION 'authorized document required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF octet_length(archive.document)>maximum_bytes THEN RAISE EXCEPTION 'document byte limit' USING ERRCODE='54000';END IF;
 IF encode(sha256(convert_to(archive.document,'UTF8')),'hex') IS DISTINCT FROM archive.content_sha256 THEN RAISE EXCEPTION 'exact accepted source required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT request FROM truss.catalog_registration_request WHERE catalog_registration_request.revision=archive.rev;
 SELECT value INTO STRICT source FROM jsonb_array_elements(convert_from(request.input_bytes,'UTF8')::jsonb->'documents') WHERE value->>'documentId'=selected_document;
 IF source->>'documentRevision' IS DISTINCT FROM archive.doc_revision OR source->'artifact'->>'sha256' IS DISTINCT FROM archive.content_sha256 OR (CASE WHEN (convert_from(request.input_bytes,'UTF8')::jsonb)->>'interfaceVersion'='truss-acceptance-input/0.2.0' THEN source->'artifact' ? 'bytesBase64'
  ELSE decode(source->'artifact'->>'bytesBase64','base64') IS DISTINCT FROM convert_to(archive.document,'UTF8') END) THEN RAISE EXCEPTION 'original accepted source required' USING ERRCODE='55000';END IF;
 encoded:=convert_to((jsonb_build_object('documentId',selected_document,'documentRevision',archive.doc_revision,'artifactIdentity',source->'artifact'->>'identity','contentBase64',encode(convert_to(archive.document,'UTF8'),'base64'),'sha256',archive.content_sha256,'catalogRevision',captured_revision,'sourceCatalogRevision',archive.rev,'registrationId',request.registration_id::text,'validation',archive.validation->'sourceValidation')
  ||CASE WHEN archive.validation ? 'dddValidation' THEN jsonb_build_object('dddProfile',archive.validation->'dddProfile','dddValidation',archive.validation->'dddValidation') ELSE '{}'::jsonb END)::text,'UTF8');
 IF octet_length(encoded)>maximum_bytes THEN RAISE EXCEPTION 'encoded document byte limit' USING ERRCODE='54000';END IF;
 FOR module IN SELECT value FROM jsonb_array_elements(archive.document::jsonb->'modules') LOOP
  IF NOT truss.runtime_can_read(selected_document,module->>'id') THEN RAISE EXCEPTION 'current reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 PERFORM truss.runtime_person(false);
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN
  RAISE EXCEPTION 'catalog changed during document observation' USING ERRCODE='55P03';END IF;
 RETURN encoded;
END;
$function$

CREATE OR REPLACE FUNCTION truss.acknowledge_feed(selected_consumer text, expected_prior bytea, target bytea, payload_sha256 text, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE consumer truss.runtime_feed_consumer%ROWTYPE;result jsonb;frontier numeric;target_json jsonb;
BEGIN
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 SELECT * INTO STRICT consumer FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer FOR UPDATE NOWAIT;
 IF consumer.checkpoint_bytes=target AND consumer.last_prior=expected_prior AND consumer.last_target=target AND consumer.last_payload_sha256=payload_sha256 THEN
  RETURN convert_to(jsonb_build_object('outcome','equal','checkpointBase64',replace(encode(target,'base64'),chr(10),''))::text,'UTF8');END IF;
 IF consumer.checkpoint_bytes IS DISTINCT FROM expected_prior THEN RAISE EXCEPTION 'feed checkpoint conflict' USING ERRCODE='P1001';END IF;
 IF target IS NULL OR octet_length(target) NOT BETWEEN 1 AND 16384 OR payload_sha256 IS NULL OR payload_sha256 !~ '^[0-9a-f]{64}$'
 OR (convert_from(target,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'exact delivered boundary required' USING ERRCODE='22023';END IF;
 target_json:=convert_from(target,'UTF8')::jsonb;
 IF jsonb_typeof(target_json->'nextXid') IS DISTINCT FROM 'string' OR target_json->>'nextXid' !~ '^(0|[1-9][0-9]{0,19})$' THEN RAISE EXCEPTION 'exact delivered position required' USING ERRCODE='22023';END IF;
 frontier:=(target_json->>'nextXid')::numeric;
 IF frontier>pg_snapshot_xmin(pg_current_snapshot())::text::numeric THEN RAISE EXCEPTION 'committed interval required' USING ERRCODE='55000';END IF;
 result:=convert_from(truss.runtime_feed_page(selected_consumer,expected_prior,frontier,65536,16777216),'UTF8')::jsonb;
 IF decode(result->>'nextBase64','base64') IS DISTINCT FROM target OR result->>'sha256' IS DISTINCT FROM payload_sha256 THEN
  RAISE EXCEPTION 'complete delivered interval required' USING ERRCODE='55000';END IF;
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 IF target=expected_prior THEN
  RETURN convert_to(jsonb_build_object('outcome','equal','checkpointBase64',replace(encode(target,'base64'),chr(10),''))::text,'UTF8');END IF;
 UPDATE truss.runtime_feed_consumer SET checkpoint_bytes=target,last_prior=expected_prior,last_target=target,last_payload_sha256=payload_sha256 WHERE consumer_id=selected_consumer;
 RETURN convert_to(jsonb_build_object('outcome','advanced','checkpointBase64',replace(encode(target,'base64'),chr(10),''))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.acknowledge_feed_with_receipt(selected_consumer text, prior bytea, target bytea, feed_sha text, destination text, request_sha text, publication text, receipt bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE selected jsonb;stored truss.runtime_feed_ack_receipt%ROWTYPE;c truss.runtime_feed_consumer%ROWTYPE;ack jsonb;checkpoint bytea;
BEGIN
 selected:=truss.feed_ack_receipt_binding(selected_consumer,prior,target,feed_sha,destination,request_sha,publication,receipt,expected_release,expected_digest);
 SELECT * INTO STRICT c FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer FOR UPDATE NOWAIT;
 SELECT * INTO stored FROM truss.runtime_feed_ack_receipt WHERE registration_id=c.registration_id
 AND prior_sha256=encode(sha256(prior),'hex') AND target_sha256=encode(sha256(target),'hex');
 IF FOUND THEN
  IF stored.prior_bytes IS DISTINCT FROM prior OR stored.target_bytes IS DISTINCT FROM target OR stored.binding IS DISTINCT FROM selected OR stored.receipt_bytes IS DISTINCT FROM receipt
  THEN RAISE EXCEPTION 'immutable ACK receipt conflict' USING ERRCODE='P1001';END IF;
  checkpoint:=c.checkpoint_bytes;
  IF checkpoint IS DISTINCT FROM truss.runtime_feed_cursor(selected_consumer,convert_from(checkpoint,'UTF8')::jsonb->>'nextXid')
   OR (convert_from(checkpoint,'UTF8')::jsonb->>'nextXid')::numeric<(convert_from(target,'UTF8')::jsonb->>'nextXid')::numeric
  THEN RAISE EXCEPTION 'ACK receipt checkpoint correspondence required' USING ERRCODE='55000';END IF;
  ack:=jsonb_build_object('outcome','equal');
 ELSE
  IF prior=target THEN RAISE EXCEPTION 'first ACK receipt requires nonempty interval' USING ERRCODE='22023';END IF;
  IF c.checkpoint_bytes IS DISTINCT FROM prior THEN RAISE EXCEPTION 'ACK receipt cannot backfill prior acknowledgement' USING ERRCODE='P1001';END IF;
  ack:=convert_from(truss.acknowledge_feed(selected_consumer,prior,target,feed_sha,expected_release,expected_digest),'UTF8')::jsonb;
  INSERT INTO truss.runtime_feed_ack_receipt VALUES(c.registration_id,encode(sha256(prior),'hex'),encode(sha256(target),'hex'),prior,target,selected,receipt);
  SELECT checkpoint_bytes INTO STRICT checkpoint FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer;
  IF checkpoint IS DISTINCT FROM target OR NOT EXISTS(SELECT 1 FROM truss.runtime_feed_ack_receipt r WHERE r.registration_id=c.registration_id AND r.prior_bytes=prior AND r.target_bytes=target AND r.binding=selected AND r.receipt_bytes=receipt)
  THEN RAISE EXCEPTION 'atomic ACK receipt poststate required' USING ERRCODE='55000';END IF;
 END IF;
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 RETURN convert_to(jsonb_build_object('outcome',ack->>'outcome','binding',selected,'priorBase64',replace(encode(prior,'base64'),chr(10),''),
 'nextBase64',replace(encode(target,'base64'),chr(10),''),'checkpointBase64',replace(encode(checkpoint,'base64'),chr(10),''),'receiptBase64',replace(encode(receipt,'base64'),chr(10),''))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.admin_install_recovery()
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE actor record;installation truss.catalog_runtime_installation%ROWTYPE;
 owner_name text;registrar_name text;has_owner boolean;
BEGIN
 SELECT oid,rolname::text,rolcanlogin,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolinherit,
  current_setting('role')='none' AS original_role INTO STRICT actor
 FROM pg_catalog.pg_roles WHERE rolname=session_user;
 IF actor.rolcanlogin IS NOT TRUE OR actor.original_role IS NOT TRUE
  OR NOT (actor.rolsuper OR actor.rolcreaterole) THEN
  RAISE EXCEPTION 'direct installation administrator required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT installation FROM truss.catalog_runtime_installation WHERE singleton;
 IF NOT actor.rolsuper THEN
  WITH RECURSIVE inherited(role_oid) AS (
   SELECT actor.oid UNION SELECT m.roleid FROM pg_catalog.pg_auth_members m
    JOIN inherited i ON m.member=i.role_oid WHERE m.inherit_option)
  SELECT EXISTS(SELECT 1 FROM inherited WHERE role_oid=installation.owner_oid) INTO has_owner;
  IF has_owner IS NOT TRUE THEN RAISE EXCEPTION 'installation owner administration required' USING ERRCODE='42501';END IF;
 END IF;
 SELECT rolname::text INTO owner_name FROM pg_catalog.pg_roles WHERE oid=installation.owner_oid
  AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole
  AND NOT rolreplication AND NOT rolbypassrls AND NOT rolinherit;
 IF owner_name IS NULL THEN RAISE EXCEPTION 'installation owner profile is incompatible' USING ERRCODE='0A000';END IF;
 SELECT rolname::text INTO registrar_name FROM pg_catalog.pg_roles WHERE oid=installation.registrar_oid
  AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole
  AND NOT rolreplication AND NOT rolbypassrls AND NOT rolinherit;
 IF registrar_name IS NULL THEN RAISE EXCEPTION 'installation registrar profile is incompatible' USING ERRCODE='0A000';END IF;
 IF installation.owner_oid=installation.registrar_oid OR owner_name IS NULL OR registrar_name IS NULL THEN
  RAISE EXCEPTION 'installation role profile is incompatible' USING ERRCODE='0A000';END IF;
 RETURN convert_to(jsonb_build_object('outcome','recovered','ownerRole',owner_name,
  'registrarRole',registrar_name)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.apply_create_group_qualified(original_input bytea, original_documents bytea, original_keys bytea, original_request bytea, expected_release text, expected_digest text, qualified_actor oid, selected_attempt uuid DEFAULT NULL::uuid, selected_original bytea DEFAULT NULL::bytea, selected_input jsonb DEFAULT NULL::jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
<<creation_leaf>>
DECLARE selected_owned boolean;changed_rows bigint;
 planned_items jsonb[]:='{}';planned_key_items jsonb[]:='{}';component_cells jsonb[];member_key_items jsonb[];prior_generations bigint[]:='{}';
 input jsonb;request jsonb;key_inputs jsonb;metadata jsonb;context jsonb;installation truss.catalog_runtime_installation%ROWTYPE;
 source_pin record;actor_oid oid;writer xid8;group_uuid uuid:=gen_random_uuid();current_index int:=0;operation jsonb;operation_meta jsonb;
 selected_type truss.type_def%ROWTYPE;property truss.prop_def%ROWTYPE;key_definition truss.key_def%ROWTYPE;
 supplied_value jsonb;props jsonb;retained jsonb;planned jsonb:='[]';planned_keys jsonb:='[]';key_plan jsonb;key_input jsonb;
 values_text text[];values_cells jsonb;key_facets jsonb;component record;namespace bytea;transport bytea;tuple_bytes bytea;owner_receipt jsonb;
 route record;observed record;planned_row jsonb;actual_row jsonb;object_row truss.object%ROWTYPE;
 object_identity jsonb;properties_json jsonb;retained_json jsonb;after_record jsonb;event jsonb;event_bytes bytea;origin_bytes bytea;
 journal_row truss.journal%ROWTYPE;expected_journal jsonb;actual_journal jsonb;event_digest text;
 expected_transition jsonb;actual_transition jsonb;actual_progress record;physical_journal jsonb;stored_result jsonb;
 results jsonb:='[]';aliases jsonb:='[]';members jsonb:='[]';member_keys jsonb;
 membership truss.object_key_bucket%ROWTYPE;reservation truss.object_key_reservation_bucket%ROWTYPE;
 semantic jsonb;semantic_bytes bytea;new_generation bigint;
 captured_revision int;outcome jsonb;outer_attempt record;
 type_metadata jsonb;key_codec jsonb;owned_plan jsonb;owned_state jsonb;root_reference text;root_identity jsonb;root_object truss.object%ROWTYPE;selected_history text;
BEGIN
 selected_owned:=coalesce(selected_attempt IS NOT NULL AND selected_input->'mutationProfile'=truss.runtime_owned_profile(),false);
 -- Private create execution: request admission, replay and rollback belong to
 -- the outer group. Keep its one public exception boundary around all operations.
 IF original_input IS NULL OR octet_length(original_input) NOT BETWEEN 1 AND 1048576
  OR original_documents IS NULL OR octet_length(original_documents) NOT BETWEEN 1 AND 4194304 THEN
  RAISE EXCEPTION 'bounded original create source required' USING ERRCODE='54000';END IF;
 -- The selected owned caller supplies engine-built operation bytes and the
 -- immutable begin-admitted documents. Standalone calls retain admission.
 IF NOT selected_owned AND ((convert_from(original_input,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
  OR (selected_attempt IS NULL AND
   (convert_from(original_documents,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE)) THEN
  RAISE EXCEPTION 'unique original create source required' USING ERRCODE='22023';END IF;
 context:=convert_from(truss.group_context_qualified(expected_release,expected_digest,qualified_actor),'UTF8')::jsonb;
 actor_oid:=qualified_actor;writer:=pg_current_xact_id();
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF original_keys IS NULL OR octet_length(original_keys) NOT BETWEEN 1 AND 8388608
 OR original_request IS NULL OR octet_length(original_request) NOT BETWEEN 1 AND 65536 THEN
  RAISE EXCEPTION 'bounded group keys and request required' USING ERRCODE='54000'; END IF;
 IF (convert_from(original_keys,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE OR (convert_from(original_request,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'unique key/request JSON members required' USING ERRCODE='22023'; END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;request:=convert_from(original_request,'UTF8')::jsonb;
 key_inputs:=convert_from(original_keys,'UTF8')::jsonb;
 IF key_inputs<>'[]'::jsonb THEN RAISE EXCEPTION 'client key encoding is no longer accepted' USING ERRCODE='22023';END IF;
 IF input-ARRAY['interfaceVersion','layoutProfile','mutationProfile','valueProfile','catalog','operations','assertedOrigin']<>'{}'::jsonb
 OR input->'assertedOrigin'->>'kind' IS DISTINCT FROM 'map' OR jsonb_typeof(input->'assertedOrigin'->'entries') IS DISTINCT FROM 'array'
 OR (input->'assertedOrigin')-ARRAY['kind','entries']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'closed selected group and origin required' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e
  WHERE jsonb_typeof(e.value->'key') IS DISTINCT FROM 'string' OR e.value-ARRAY['key','value']<>'{}'::jsonb
  OR (e.value->'value'='{"kind":"null"}'::jsonb OR (e.value->'value'->>'kind'='string'
   AND jsonb_typeof(e.value->'value'->'text')='string' AND (e.value->'value')-ARRAY['kind','text']='{}'::jsonb)) IS NOT TRUE)
 OR (SELECT count(*) FROM jsonb_array_elements(input->'assertedOrigin'->'entries'))
  <>(SELECT count(DISTINCT e.value->>'key') FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e) THEN
  RAISE EXCEPTION 'exact unique scalar asserted origin required' USING ERRCODE='22023'; END IF;
 IF request IS DISTINCT FROM '{"state":"none"}'::jsonb THEN
  RAISE EXCEPTION 'outer group owns request identity and replay' USING ERRCODE='22023';END IF;
 IF selected_owned THEN
  SELECT a.id,a.next_index,a.actor_oid,a.writer_xid INTO STRICT outer_attempt FROM truss.runtime_object_attempt a
   WHERE a.id=selected_attempt AND a.writer_xid=writer AND a.actor_oid=creation_leaf.actor_oid AND NOT a.complete
    AND a.context->'creationTransitionProfile'=creation_leaf.context->'creationTransitionProfile'
   FOR UPDATE NOWAIT;
  owned_plan:=truss.runtime_owned_plan(outer_attempt.id,outer_attempt.next_index);
  owned_state:=owned_plan->'afterNodes'->(owned_plan->>'primary');
  SELECT * INTO STRICT selected_type FROM truss.type_def WHERE type_id=(owned_state->'identity'->>'typeId')::int;
  SELECT t.metadata INTO STRICT type_metadata FROM truss.runtime_type_schema t
   WHERE t.rev=captured_revision AND t.type_id=selected_type.type_id;
  PERFORM truss.runtime_module_writer_qualified(selected_type.document_id,selected_type.module,qualified_actor);
  IF NOT truss.runtime_object_values_readable_qualified(selected_type.type_id,qualified_actor) THEN
   RAISE EXCEPTION 'current property and item interpretation reader required' USING ERRCODE='42501';END IF;
  metadata:=jsonb_build_array(jsonb_build_object('typeId',selected_type.type_id::text,
   'documentId',selected_type.document_id,'moduleId',selected_type.module));
 ELSE
  metadata:=convert_from(truss.group_create_metadata_qualified(original_input,original_documents,expected_release,expected_digest,qualified_actor),'UTF8')::jsonb;
 SELECT a.id,a.next_index,a.actor_oid,a.writer_xid,a.results,a.aliases INTO STRICT outer_attempt FROM truss.runtime_object_attempt a
 WHERE a.writer_xid=writer AND a.actor_oid=creation_leaf.actor_oid AND NOT a.complete
  AND a.context->'creationTransitionProfile'=creation_leaf.context->'creationTransitionProfile'
  AND a.documents_bytes=original_documents
  AND CASE WHEN input->'mutationProfile'=truss.runtime_owned_profile() THEN
   a.results='[]'::jsonb AND a.aliases='[]'::jsonb AND
   (SELECT count(*) FROM truss.runtime_owned_operation p WHERE p.attempt_id=a.id AND p.result IS NOT NULL)=a.next_index
   ELSE jsonb_array_length(a.results)=a.next_index END
  AND ((selected_attempt IS NULL AND
   convert_to(jsonb_set(convert_from(a.input_bytes,'UTF8')::jsonb-'preconditions',
      '{operations}',jsonb_build_array(convert_from(a.input_bytes,'UTF8')::jsonb->'operations'->a.next_index))::text,'UTF8')=original_input
   AND convert_from(a.input_bytes,'UTF8')::jsonb->'operations'->a.next_index->>'operation'='create_object')
   -- The sole selected-path caller, runtime_owned_group_step_in_input,
   -- checked this attempt's exact input bytes immediately before invocation.
   -- Its intervening registered calls are read-only; retain all leaf scope,
   -- progress and original-operation reconstruction checks without detoasting
   -- the same complete batch a second time. NULL selectors keep the old path.
   OR (selected_attempt IS NOT NULL AND a.id=selected_attempt AND selected_original IS NOT NULL
    AND jsonb_extract_path(selected_input,'operations',a.next_index::text)->>'operation'='create_object'
    AND convert_to(((selected_input-ARRAY['preconditions','operations'])||jsonb_build_object('operations',
      jsonb_build_array(jsonb_extract_path(selected_input,'operations',a.next_index::text))))::text,'UTF8')=original_input))
  AND request='{"state":"none"}'::jsonb
 FOR UPDATE NOWAIT;
 END IF;
 selected_history:=CASE WHEN input->'mutationProfile'=truss.runtime_owned_profile() THEN 'truss-native-owned-create/0.1' ELSE 'truss-native-scalar-create/0.2' END;
 LOCK TABLE truss.object IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 LOCK TABLE truss.edge IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 IF input->'mutationProfile'=truss.runtime_owned_profile() THEN
  IF NOT selected_owned THEN
  owned_plan:=truss.runtime_owned_plan(outer_attempt.id,outer_attempt.next_index);
  IF owned_plan->'operation' IS DISTINCT FROM input->'operations'->0
   OR owned_plan->>'primary' IS DISTINCT FROM 'create:'||outer_attempt.next_index::text
   OR (owned_plan->'beforeNodes') ? (owned_plan->>'primary') THEN
   RAISE EXCEPTION 'original ordered create plan required' USING ERRCODE='55000';END IF;
  END IF;
  owned_state:=owned_plan->'afterNodes'->(owned_plan->>'primary');root_reference:=owned_state->>'root';
  IF owned_state IS NULL OR owned_state->'deleted' IS DISTINCT FROM 'false'::jsonb THEN
   RAISE EXCEPTION 'original live create state required' USING ERRCODE='55000';END IF;
  IF root_reference IS NOT NULL THEN
   root_identity:=truss.runtime_owned_identity(outer_attempt.id,outer_attempt.next_index,root_reference,'object');
   IF selected_owned THEN
    SELECT o.root_id,o.root_type INTO STRICT root_object.root_id,root_object.root_type FROM truss.object o
     WHERE o.id=(root_identity->>'id')::bigint AND o.type_id=(root_identity->>'typeId')::int;
   ELSE
    SELECT * INTO STRICT root_object FROM truss.object WHERE id=(root_identity->>'id')::bigint AND type_id=(root_identity->>'typeId')::int;
   END IF;
   IF root_object.root_id IS NOT NULL OR root_object.root_type IS NOT NULL
    OR NOT selected_owned AND to_jsonb(root_object)-ARRAY['created_at','updated_at'] IS DISTINCT FROM
     truss.runtime_owned_object_image(outer_attempt.id,outer_attempt.next_index,root_reference,'before') THEN
    RAISE EXCEPTION 'original live rootless aggregate root state required' USING ERRCODE='55000';END IF;
  END IF;
 END IF;
 -- Modern creates are bounded by their admitted immutable outer attempt.
 -- Retain the published legacy transaction ceiling on its original profile.
 IF input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
 IF (SELECT count(*) FROM (SELECT 1 FROM truss.runtime_object_transition WHERE writer_xid=writer AND before_object IS NULL LIMIT 129) g)>=128 THEN
  RAISE EXCEPTION 'bounded groups per transaction required' USING ERRCODE='54000'; END IF;
 END IF;
 IF jsonb_typeof(key_inputs) IS DISTINCT FROM 'array' OR jsonb_array_length(key_inputs)>512 THEN
  RAISE EXCEPTION 'bounded original key inventory required' USING ERRCODE='54000'; END IF;
 IF (SELECT value FROM truss.setting WHERE key='key_reuse') IS DISTINCT FROM '"forbid"'::jsonb
 OR (SELECT value FROM truss.setting WHERE key='journal_mode') IS DISTINCT FROM '"engine"'::jsonb THEN
  RAISE EXCEPTION 'selected engine key/history settings required' USING ERRCODE='0A000'; END IF;
 -- Complete all logical plans before native IDs or canonical writes.
 FOR operation IN SELECT value FROM jsonb_array_elements(input->'operations') LOOP
  operation_meta:=metadata->current_index;
  SELECT * INTO STRICT selected_type FROM truss.type_def WHERE type_id=(operation_meta->>'typeId')::int;
  IF NOT selected_owned THEN
  IF operation-ARRAY['operation','typeDefinitionPin','values','ownership','alias']<>'{}'::jsonb
   OR jsonb_typeof(operation->'values') IS DISTINCT FROM 'array' OR jsonb_array_length(operation->'values')>1024
   OR (operation ? 'alias' AND (jsonb_typeof(operation->'alias')<>'string' OR octet_length(operation->>'alias') NOT BETWEEN 1 AND 1024)) THEN
   RAISE EXCEPTION 'closed bounded create operation required' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM truss.rel_endpoint e JOIN truss.rel_def r USING(rel_type_id)
   WHERE r.retired_rev IS NULL AND ((e.source_type=selected_type.type_id AND r.target_min>0)
    OR (e.target_type=selected_type.type_id AND r.source_min>0))) AND NOT EXISTS(
    SELECT 1 FROM truss.runtime_object_attempt a WHERE a.writer_xid=writer AND a.actor_oid=qualified_actor AND NOT a.complete
    AND convert_from(a.input_bytes,'UTF8')::jsonb->'operations'->a.next_index=operation
    AND a.documents_bytes=original_documents) THEN
   RAISE EXCEPTION 'mandatory relationship unsupported by create-only profile' USING ERRCODE='0A000'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(operation->'values') v WHERE jsonb_typeof(v.value->'name') IS DISTINCT FROM 'string'
   OR octet_length(v.value->>'name') NOT BETWEEN 1 AND 4096 OR v.value-ARRAY['name','value']<>'{}'::jsonb
   OR truss.valid_flat_cell(v.value->'value') IS NOT TRUE)
   OR jsonb_array_length(operation->'values')<>(SELECT count(DISTINCT v.value->>'name') FROM jsonb_array_elements(operation->'values') v) THEN
   RAISE EXCEPTION 'unique exact scalar authored values required' USING ERRCODE='22023'; END IF;
  END IF;
  IF owned_state IS NOT NULL THEN
   -- Native capture already validated and canonicalized this immutable image.
   -- Retain source/actor/key checks and final settlement; do not replan values.
   props:=owned_state->'image'->'props';
   retained:=coalesce(nullif(owned_state->'image'->'retained','null'::jsonb),'{}'::jsonb);
  ELSE
  props:='{}';retained:='{}';
  FOR property IN SELECT * FROM truss.prop_def WHERE type_id=selected_type.type_id AND retired_rev IS NULL ORDER BY prop_id LOOP
   IF truss.valid_property_definition(property) IS NOT TRUE THEN
    RAISE EXCEPTION 'selected scalar property profile required' USING ERRCODE='0A000'; END IF;
   SELECT v.value->'value' INTO supplied_value FROM jsonb_array_elements(operation->'values') v WHERE v.value->>'name'=property.name;
   IF NOT FOUND THEN
    IF property.nullability='required' THEN RAISE EXCEPTION 'missing required value' USING ERRCODE='22023'; END IF;
   ELSE
    IF truss.valid_property_value(supplied_value,property) IS NOT TRUE THEN
     RAISE EXCEPTION 'exact property family and value required' USING ERRCODE='22023'; END IF;
    props:=props||jsonb_build_object(property.prop_id::text,truss.canonical_flat_cell(supplied_value));
   END IF;
  END LOOP;
  SELECT coalesce(jsonb_object_agg(v.value->>'name',truss.canonical_flat_cell(v.value->'value')),'{}'::jsonb) INTO retained
   FROM jsonb_array_elements(operation->'values') v WHERE NOT EXISTS(SELECT 1 FROM truss.prop_def p
    WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL AND p.name=v.value->>'name');
  END IF;
  IF NOT selected_owned THEN
   planned_items[cardinality(planned_items)+1]:=jsonb_build_object('typeId',selected_type.type_id,'props',props,'retained',retained);END IF;
  FOR key_definition IN SELECT * FROM truss.key_def WHERE type_id=selected_type.type_id AND retired_rev IS NULL ORDER BY key_num LOOP
   IF selected_owned THEN
    SELECT coalesce(jsonb_agg(props->i.prop_id::text ORDER BY i.ordinal),'[]'::jsonb) INTO values_cells
     FROM unnest(key_definition.prop_ids) WITH ORDINALITY i(prop_id,ordinal);
