  IF truss.runtime_module_writer_qualified(operation_meta->>'documentId',operation_meta->>'moduleId',qualified_actor) IS DISTINCT FROM outer_attempt.actor_oid THEN
   RAISE EXCEPTION 'original current create actor required' USING ERRCODE='42501';END IF;
  IF NOT truss.runtime_object_values_readable_qualified((operation_meta->>'typeId')::int,qualified_actor) THEN RAISE EXCEPTION 'current property and item interpretation reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF root_identity IS NOT NULL AND NOT truss.runtime_can_read_qualified(root_identity->'owner'->>'documentId',root_identity->'owner'->>'moduleId',qualified_actor) THEN
  RAISE EXCEPTION 'current create root reader required' USING ERRCODE='42501';END IF;
 RETURN convert_to(jsonb_build_object('outcome','success','disposition','applied','durability','pending','semantic',semantic)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.apply_group_prepared(original_input bytea, original_documents bytea, original_request bytea, expected_release text, expected_digest text, app_prepared jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE opened jsonb;attempt_id uuid;operation_index int:=0;operation_count int;result jsonb;failure_result jsonb;input_text text;
 failure_operation_index int;operation_local_failure boolean:=false;
 native_state text;native_detail text;native_detail_json jsonb;failure_code text;unavailable_reason text;parsed_input jsonb;
BEGIN
 -- Read only a guarded count hint before admission so a trusted conflict
 -- ordinal raised during group-begin can be bounded. The original bytes still
 -- enter the normal admission function unchanged; malformed input leaves the
 -- hint unset and receives its established admission outcome.
 BEGIN
  IF original_input IS NOT NULL AND octet_length(original_input) BETWEEN 1 AND 1048576 THEN
   input_text:=convert_from(original_input,'UTF8');
   IF input_text IS JSON OBJECT WITH UNIQUE KEYS THEN
    parsed_input:=input_text::jsonb;
    IF jsonb_typeof(parsed_input->'operations')='array'
     AND jsonb_array_length(parsed_input->'operations') BETWEEN 1 AND 1024 THEN
     operation_count:=jsonb_array_length(parsed_input->'operations');
    END IF;
   END IF;
  END IF;
 EXCEPTION WHEN others THEN
  parsed_input:=NULL;operation_count:=NULL;
 END;
 opened:=convert_from(truss.object_group_begin_prepared(original_input,original_documents,original_request,expected_release,expected_digest,convert_to('[]','UTF8'),false,app_prepared),'UTF8')::jsonb;
 IF opened->>'outcome'<>'execute' THEN RETURN convert_to(opened::text,'UTF8');END IF;
 attempt_id:=(opened->>'attemptId')::uuid;
 parsed_input:=convert_from(original_input,'UTF8')::jsonb;
 operation_count:=jsonb_array_length(parsed_input->'operations');
 IF parsed_input->'mutationProfile'=truss.runtime_owned_profile() AND NOT EXISTS(
  SELECT 1 FROM jsonb_array_elements(parsed_input->'operations') o
  WHERE o.value->>'operation' IS DISTINCT FROM 'create_object'
   OR o.value->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb) THEN
  PERFORM truss.runtime_owned_create_batch(attempt_id);
 ELSIF parsed_input->'mutationProfile'=truss.runtime_owned_profile() AND NOT EXISTS(
  SELECT 1 FROM jsonb_array_elements(parsed_input->'operations') o
  WHERE o.value->>'operation' IS DISTINCT FROM 'create_edge'
   OR o.value->'source'->>'state' IS DISTINCT FROM 'stored'
   OR o.value->'target'->>'state' IS DISTINCT FROM 'stored') AND NOT EXISTS(
  SELECT 1 FROM truss.runtime_owned_operation p JOIN truss.rel_def r
   ON r.rel_type_id=(p.plan->'afterEdges'->(p.plan->>'primary')->'identity'->>'typeId')::int
  WHERE p.attempt_id=(opened->>'attemptId')::uuid AND r.lifecycle<>'independent') THEN
  PERFORM truss.runtime_owned_edge_create_batch(attempt_id);
 ELSIF parsed_input->'mutationProfile'=truss.runtime_owned_profile() AND NOT EXISTS(
  SELECT 1 FROM jsonb_array_elements(parsed_input->'operations') o
  WHERE o.value->>'operation' IS DISTINCT FROM 'update_object'
   OR o.value->'target'->>'state' IS DISTINCT FROM 'stored' OR o.value ? 'ownershipChange')
  AND (SELECT count(DISTINCT plan->>'primary') FROM truss.runtime_owned_operation p WHERE p.attempt_id=(opened->>'attemptId')::uuid)=operation_count THEN
  PERFORM truss.runtime_owned_update_batch(attempt_id);
 ELSE
 FOR step_index IN 0..operation_count-1 LOOP
  operation_index:=step_index;
  operation_local_failure:=true;
  PERFORM truss.runtime_owned_group_step_in_input(attempt_id,operation_index,convert_to('[]','UTF8'),original_input,parsed_input);
  operation_local_failure:=false;
 END LOOP;
 END IF;
 operation_local_failure:=false;
 operation_index:=operation_count-1;
 result:=convert_from(truss.object_group_finish(attempt_id),'UTF8')::jsonb;
 -- Internal import provenance attaches to the same completed attempt. This field
 -- is outside the public semantic result and does not alter receipt bytes.
 RETURN convert_to((result||jsonb_build_object('attemptId',attempt_id::text))::text,'UTF8');
EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '23505' OR SQLSTATE 'P1001' OR SQLSTATE 'P1003'
 OR SQLSTATE 'P1004' OR SQLSTATE 'P1005' OR SQLSTATE '42501' OR SQLSTATE '0A000'
 OR SQLSTATE '54000' OR SQLSTATE '55P03' THEN
 GET STACKED DIAGNOSTICS native_state=RETURNED_SQLSTATE,native_detail=PG_EXCEPTION_DETAIL;
 IF operation_local_failure THEN failure_operation_index:=operation_index;END IF;
 -- Batched key preflight reports the original colliding operation in the
 -- exception raised while the graph writer gate is still held. Keep this
 -- mapping in the same native decision; never guess by rereading catalog rows.
 IF native_state='23505' AND native_detail IS NOT NULL
  AND native_detail IS JSON OBJECT WITH UNIQUE KEYS THEN
  native_detail_json:=native_detail::jsonb;
  IF native_detail_json-ARRAY['operationIndex']='{}'::jsonb
   AND jsonb_typeof(native_detail_json->'operationIndex')='number' THEN
   IF (native_detail_json->>'operationIndex') ~ '^(0|[1-9][0-9]{0,3})$' THEN
    IF (native_detail_json->>'operationIndex')::int<operation_count THEN
     failure_operation_index:=(native_detail_json->>'operationIndex')::int;
    END IF;
   END IF;
  END IF;
 END IF;
 -- This exception block has rolled back admission, every step and finalization.
 -- Cancellation, deadlock and serialization errors propagate to host settlement.
 unavailable_reason:=CASE native_state WHEN '0A000' THEN 'profile' WHEN '54000' THEN 'resource' WHEN '55P03' THEN 'observation' END;
 IF unavailable_reason IS NOT NULL THEN
  RETURN convert_to(jsonb_build_object('outcome','unavailable','reason',unavailable_reason)::text,'UTF8');END IF;
 failure_code:=CASE native_state WHEN '22023' THEN 'invalid_input' WHEN '23505' THEN 'key_conflict'
  WHEN 'P1001' THEN 'request_conflict' WHEN 'P1003' THEN 'expected_version' WHEN 'P1004' THEN 'not_found'
  WHEN 'P1005' THEN 'dependencies' WHEN '42501' THEN 'unauthorized_person' END;
 failure_result:=jsonb_build_object('outcome','failed','code',failure_code,'nativeState',native_state);
 IF failure_operation_index IS NOT NULL THEN
  failure_result:=failure_result||jsonb_build_object('operationIndex',failure_operation_index::text);
 END IF;
 RETURN convert_to(failure_result::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.build_import_records(original_drafts bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
 DECLARE drafts jsonb;draft jsonb;context jsonb;metadata jsonb;cache jsonb:='{}';cache_key text;
 identity jsonb;component jsonb;components jsonb;matches int;cell jsonb;payload jsonb;payload_bytes bytea;
 records jsonb[]:='{}';item jsonb;selected_type int;definition truss.prop_def%ROWTYPE;
BEGIN
 context:=convert_from(truss.batched_import_context(expected_release,expected_digest),'UTF8')::jsonb;
 IF original_drafts IS NULL OR octet_length(original_drafts)>8388608 THEN RAISE EXCEPTION 'bounded import drafts required' USING ERRCODE='54000';END IF;
 IF (convert_from(original_drafts,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'unique original import drafts required' USING ERRCODE='22023';END IF;
 drafts:=convert_from(original_drafts,'UTF8')::jsonb;
 IF jsonb_array_length(drafts)>1024 THEN RAISE EXCEPTION 'bounded import drafts required' USING ERRCODE='54000';END IF;
 FOR draft IN SELECT value FROM jsonb_array_elements(drafts) LOOP
  IF (draft->>'kind' IN ('object','edge')) IS NOT TRUE OR jsonb_typeof(draft->'values') IS DISTINCT FROM 'array'
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['documentId','moduleId']) k WHERE jsonb_typeof(draft->k) IS DISTINCT FROM 'string' OR octet_length(draft->>k) NOT BETWEEN 1 AND 4096)
   THEN RAISE EXCEPTION 'closed exact import draft required' USING ERRCODE='22023';END IF;
  PERFORM truss.runtime_module_writer(draft->>'documentId',draft->>'moduleId');
  cache_key:=jsonb_build_array(draft->>'kind',draft->>'documentId',draft->>'moduleId',draft->>'recordId',draft->>'relationshipId')::text;
  metadata:=cache->cache_key;
  IF draft->>'kind'='object' THEN
   IF draft-ARRAY['kind','documentId','moduleId','recordId','values','source']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed object import draft required' USING ERRCODE='22023';END IF;
   IF metadata IS NULL THEN
    metadata:=convert_from(truss.import_key_selection(draft->>'documentId',draft->>'moduleId',draft->>'recordId',expected_release,expected_digest),'UTF8')::jsonb;
    cache:=cache||jsonb_build_object(cache_key,metadata);
   END IF;
   selected_type:=(metadata->'type'->>'typeId')::int;components:='[]';
   FOR component IN SELECT value FROM jsonb_array_elements(metadata->'components') LOOP
    SELECT count(*),jsonb_agg(v.value->'value')->0 INTO matches,cell FROM jsonb_array_elements(draft->'values') v WHERE v.value->>'name'=component->>'name';
    IF matches<>1 THEN RAISE EXCEPTION 'complete original primary values required' USING ERRCODE='22023';END IF;
    SELECT * INTO STRICT definition FROM truss.prop_def WHERE type_id=selected_type AND prop_id=(component->>'propertyId')::int AND retired_rev IS NULL;
    IF NOT truss.runtime_can_read(draft->>'documentId',definition.declaration_module) THEN RAISE EXCEPTION 'current primary reader required' USING ERRCODE='42501';END IF;
    components:=components||jsonb_build_array(jsonb_build_object('propertyId',component->>'propertyId','definitionPin',component->>'definitionPin','value',cell));
   END LOOP;
   identity:=jsonb_build_object('operation','object_key','type',metadata->'type','keyNumber',metadata->>'keyNumber',
    'keyDefinitionPin',metadata->>'keyDefinitionPin','keyEncodingProfile',metadata->'keyEncodingProfile','components',components);
   payload:=jsonb_build_object('interfaceVersion','truss-import-payload/0.1.0','kind','object','values',draft->'values','ownership',jsonb_build_object('state','rootless'));
  ELSE
   IF draft-ARRAY['kind','documentId','moduleId','relationshipId','sourceEndpoint','targetEndpoint','values','orderKey','source']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed edge import draft required' USING ERRCODE='22023';END IF;
   IF metadata IS NULL THEN
    metadata:=convert_from(truss.group_relationship_reference(draft->>'documentId',draft->>'moduleId',draft->>'relationshipId',expected_release,expected_digest),'UTF8')::jsonb;
    IF metadata IS NULL THEN RAISE EXCEPTION 'accepted relationship required' USING ERRCODE='22023';END IF;
    cache:=cache||jsonb_build_object(cache_key,metadata);
   END IF;
   identity:=jsonb_build_object('relationshipDefinitionPin',metadata->>'definitionPin','source',draft->'sourceEndpoint','target',draft->'targetEndpoint');
   payload:=jsonb_build_object('interfaceVersion','truss-import-payload/0.1.0','kind','edge','values',draft->'values','orderKey',draft->'orderKey');
  END IF;
  IF draft->'source' IS NOT NULL AND draft->'source'<>'null'::jsonb THEN payload:=payload||jsonb_build_object('source',draft->'source');END IF;
  payload_bytes:=convert_to(payload::text,'UTF8');
  IF octet_length(payload_bytes)>1048576 THEN RAISE EXCEPTION 'bounded record payload required' USING ERRCODE='54000';END IF;
  records:=array_append(records,jsonb_build_object('kind',draft->>'kind','identity',identity,'payloadProfile',context->'importPayloadProfile',
   'payload',jsonb_build_object('identity',encode(sha256(payload_bytes),'hex'),'bytesBase64',replace(encode(payload_bytes,'base64'),E'\n',''),'sha256',encode(sha256(payload_bytes),'hex'))));
 END LOOP;
 -- Repeat each cached definition's original authority proof before publishing.
 FOR draft IN SELECT DISTINCT ON (value->>'kind',value->>'documentId',value->>'moduleId',value->>'recordId',value->>'relationshipId') value FROM jsonb_array_elements(drafts) LOOP
  cache_key:=jsonb_build_array(draft->>'kind',draft->>'documentId',draft->>'moduleId',draft->>'recordId',draft->>'relationshipId')::text;
  IF draft->>'kind'='object' THEN
   IF convert_from(truss.import_key_selection(draft->>'documentId',draft->>'moduleId',draft->>'recordId',expected_release,expected_digest),'UTF8')::jsonb IS DISTINCT FROM cache->cache_key THEN RAISE EXCEPTION 'original builder definition changed' USING ERRCODE='42501';END IF;
  ELSE
   IF convert_from(truss.group_relationship_reference(draft->>'documentId',draft->>'moduleId',draft->>'relationshipId',expected_release,expected_digest),'UTF8')::jsonb IS DISTINCT FROM cache->cache_key THEN RAISE EXCEPTION 'original relationship authority changed' USING ERRCODE='42501';END IF;
  END IF;
 END LOOP;
 RETURN convert_to(jsonb_build_object('context',context,'records',to_jsonb(records))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.canonical_flat_cell(cell jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF truss.valid_flat_cell(cell) IS NOT TRUE THEN RAISE EXCEPTION 'bounded exact container value required' USING ERRCODE='22023';END IF;
 IF cell->>'kind'='map' THEN RETURN jsonb_build_object('kind','map','entries',
  (SELECT coalesce(jsonb_agg(jsonb_build_object('key',value->'key','value',truss.canonical_flat_cell(value->'value')) ORDER BY value->>'key' COLLATE "C"),'[]') FROM jsonb_array_elements(cell->'entries')));END IF;
 IF cell->>'kind'='sequence' THEN RETURN jsonb_build_object('kind','sequence','items',
  (SELECT coalesce(jsonb_agg(truss.canonical_flat_cell(value) ORDER BY ordinality),'[]') FROM jsonb_array_elements(cell->'items') WITH ORDINALITY));END IF;
 RETURN cell;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_accept_with_keys(input_bytes bytea, documents_bytes bytea, declarations_bytes bytea, source_bytes bytea, origin_bytes bytea, request_key text, key_receipts bytea, preview_mode boolean, expected_revision integer, expected_documents bytea)
 RETURNS TABLE(revision text, registration_id text, report_bytes bytea, replayed boolean, unchanged boolean, actor_name text, violations_bytes bytea)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE actor oid; installation truss.catalog_runtime_installation%ROWTYPE;
 request truss.catalog_registration_request%ROWTYPE; existing truss.catalog_registration_request%ROWTYPE;
 alias_request truss.catalog_unchanged_request%ROWTYPE;
 expected jsonb; prior_expected jsonb; origin bytea; original_report bytea; table_name text; columns text; assignments text;identity_column text;conflict_columns text; rows jsonb; raw bytea; total bigint:=0; request_count bigint;
 expected_docs jsonb; expected_doc jsonb;
 prior_revision int;new_revision int;type_start int;property_start int;relationship_start int;component_index int:=0;component_limit int;compact boolean;violations bytea;key_candidates jsonb;verified_keys jsonb;
BEGIN
 IF preview_mode IS NULL THEN RAISE EXCEPTION 'explicit catalog mode required' USING ERRCODE='22023';END IF;
 compact:=(convert_from(input_bytes,'UTF8')::jsonb)->>'interfaceVersion'='truss-acceptance-input/0.2.0';
 IF compact AND declarations_bytes<>''::bytea THEN RAISE EXCEPTION 'source-only catalog request required' USING ERRCODE='22023';END IF;
 actor:=truss.catalog_actor();
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id<>'truss-catalog-runtime/0.72-candidate' OR request_key IS NULL OR octet_length(request_key) NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'selected catalog release and request key required' USING ERRCODE='22023'; END IF;
 FOREACH raw IN ARRAY ARRAY[input_bytes,documents_bytes,declarations_bytes,source_bytes,origin_bytes] LOOP
  component_index:=component_index+1;
  component_limit:=CASE WHEN component_index=5 THEN 1048576 WHEN component_index=4 THEN 4194304 ELSE 16777216 END;
  IF raw IS NULL OR NOT (compact AND component_index=3 AND octet_length(raw)=0) AND octet_length(raw) NOT BETWEEN 1 AND component_limit THEN
   RAISE EXCEPTION 'catalog input byte limit exceeded' USING ERRCODE='22023'; END IF;
  total:=total+octet_length(raw);
 END LOOP;
 IF total>16777216 OR jsonb_typeof(convert_from(origin_bytes,'UTF8')::jsonb) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'bounded catalog request required' USING ERRCODE='22023'; END IF;
 IF expected_revision IS NOT NULL AND expected_revision NOT BETWEEN -1 AND 2147483647
  OR expected_documents IS NULL OR octet_length(expected_documents) NOT BETWEEN 2 AND 1048576 THEN
  RAISE EXCEPTION 'bounded catalog source expectations required' USING ERRCODE='22023';END IF;
 -- The private host's immutable semantic-parameter lane excludes SQL NULL.
 -- Normalize its -1 sentinel immediately so custody and replay remain byte-for-byte
 -- identical to historical no-CAS requests.
 IF expected_revision=-1 THEN expected_revision:=NULL;END IF;
 expected_docs:=convert_from(expected_documents,'UTF8')::jsonb;
 IF jsonb_typeof(expected_docs) IS DISTINCT FROM 'array' OR jsonb_array_length(expected_docs)>512 THEN
  RAISE EXCEPTION 'catalog source expectations required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(expected_docs)>0 THEN
  IF jsonb_array_length(expected_docs)<>jsonb_array_length(convert_from(documents_bytes,'UTF8')::jsonb)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(expected_docs) e
    WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(e.value))<>2
     OR jsonb_typeof(e.value->'documentId') IS DISTINCT FROM 'string'
     OR octet_length(e.value->>'documentId') NOT BETWEEN 1 AND 4096
     OR jsonb_typeof(e.value->'sourceCatalogRevision') IS DISTINCT FROM 'number'
     OR (e.value->>'sourceCatalogRevision') !~ '^(0|[1-9][0-9]*)$'
     OR (e.value->>'sourceCatalogRevision')::numeric>2147483647)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(expected_docs) e GROUP BY e.value->>'documentId' HAVING count(*)<>1)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(documents_bytes,'UTF8')::jsonb) d GROUP BY d.value->>'documentId' HAVING count(*)<>1)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(documents_bytes,'UTF8')::jsonb) d
    WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(expected_docs) e WHERE e.value->>'documentId'=d.value->>'documentId')) THEN
   RAISE EXCEPTION 'exact submitted document expectation set required' USING ERRCODE='22023';END IF;
 END IF;
 IF compact THEN declarations_bytes:=truss.runtime_owned_catalog_declarations(documents_bytes);END IF;
 -- Bound concurrency without an automatic retry loop.
 SELECT rev INTO STRICT prior_revision FROM truss.schema_head WHERE id=1 FOR UPDATE NOWAIT;
 prior_expected:=truss.catalog_all_expected_records();
 SELECT count(*) INTO request_count FROM (
  SELECT 1 FROM truss.catalog_registration_request r WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key
  UNION ALL SELECT 1 FROM truss.catalog_unchanged_request r WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key) requests;
 IF request_count>1 THEN RAISE EXCEPTION 'unambiguous catalog request required' USING ERRCODE='55000'; END IF;
 SELECT * INTO existing FROM truss.catalog_registration_request r WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key;
 IF FOUND THEN
  IF existing.input_bytes IS DISTINCT FROM input_bytes OR existing.expected_revision IS DISTINCT FROM expected_revision OR existing.expected_documents IS DISTINCT FROM expected_documents OR (CASE WHEN octet_length(existing.document_bytes)=0 THEN
    convert_from(truss.runtime_owned_request_documents(existing),'UTF8')::jsonb IS DISTINCT FROM convert_from(documents_bytes,'UTF8')::jsonb
   ELSE existing.document_bytes IS DISTINCT FROM documents_bytes OR existing.declaration_bytes IS DISTINCT FROM declarations_bytes END) OR existing.origin_bytes IS DISTINCT FROM origin_bytes THEN
   RAISE EXCEPTION 'request key reused with different registration input' USING ERRCODE='P1001'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN QUERY SELECT existing.revision::text,existing.registration_id::text,r.report_bytes,true,false,existing.actor_name,NULL::bytea FROM truss.catalog_acceptance_report r WHERE r.rev=existing.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'original registration report missing' USING ERRCODE='55000'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN;
 END IF;
 SELECT * INTO alias_request FROM truss.catalog_unchanged_request r
  WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key;
 IF FOUND THEN
  SELECT * INTO STRICT existing FROM truss.catalog_registration_request r WHERE r.registration_id=alias_request.registration_id;
  IF existing.input_bytes IS DISTINCT FROM input_bytes OR (CASE WHEN octet_length(existing.document_bytes)=0 THEN
    convert_from(truss.runtime_owned_request_documents(existing),'UTF8')::jsonb IS DISTINCT FROM convert_from(documents_bytes,'UTF8')::jsonb
   ELSE existing.document_bytes IS DISTINCT FROM documents_bytes OR existing.declaration_bytes IS DISTINCT FROM declarations_bytes END)
   OR alias_request.origin_bytes IS DISTINCT FROM origin_bytes OR alias_request.expected_revision IS DISTINCT FROM expected_revision
   OR alias_request.expected_documents IS DISTINCT FROM expected_documents THEN
   RAISE EXCEPTION 'request key reused with different registration input' USING ERRCODE='P1001'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN QUERY SELECT existing.revision::text,existing.registration_id::text,r.report_bytes,true,true,alias_request.actor_name,NULL::bytea
   FROM truss.catalog_acceptance_report r WHERE r.rev=existing.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'original registration report missing' USING ERRCODE='55000'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN;
 END IF;
 -- Source and optional global CAS checks happen only after exact authorized
 -- replay resolution, under the same schema-head serialization lock.
 IF expected_revision IS NOT NULL AND prior_revision IS DISTINCT FROM expected_revision THEN
  RAISE EXCEPTION 'expected catalog revision changed' USING ERRCODE='P1011';END IF;
 IF jsonb_array_length(expected_docs)>0 THEN
  FOR expected_doc IN SELECT value FROM jsonb_array_elements(expected_docs) LOOP
   IF coalesce((SELECT max(rev) FROM truss.schema_doc WHERE doc_id=expected_doc->>'documentId'),0)
     IS DISTINCT FROM (expected_doc->>'sourceCatalogRevision')::int THEN
    RAISE EXCEPTION 'expected document source revision changed' USING ERRCODE='P1011';END IF;
  END LOOP;
 END IF;
 -- Ordinary registration keeps one validation summary per original document.
 -- Semantic source/declaration checks and atomic publication remain native.
 IF (convert_from(source_bytes,'UTF8')::jsonb)->>'sourceFormat' ='truss-registration-summary/2.0' THEN
  DECLARE
   summary jsonb:=convert_from(source_bytes,'UTF8')::jsonb;
   original_input jsonb:=convert_from(input_bytes,'UTF8')::jsonb;
   original_docs jsonb:=convert_from(documents_bytes,'UTF8')::jsonb;
   doc jsonb; validation jsonb; selected_doc jsonb; ddd_profile jsonb; ddd_validation jsonb; ddd_known boolean; doc_index int:=0;
  BEGIN
   IF (SELECT count(*) FROM jsonb_object_keys(summary))<>3
    OR jsonb_typeof(summary->'umf') IS DISTINCT FROM 'array'
    OR jsonb_typeof(summary->'documentValidations') IS DISTINCT FROM 'array'
    OR jsonb_array_length(summary->'documentValidations')<>jsonb_array_length(original_docs)
    OR original_input->'binding' IS DISTINCT FROM '{"state":"absent"}'::jsonb
    OR original_input->'transforms' IS DISTINCT FROM '[]'::jsonb THEN
    RAISE EXCEPTION 'original native registration summary required' USING ERRCODE='22023';END IF;
   FOR doc IN SELECT value FROM jsonb_array_elements(original_docs) LOOP
    validation:=summary->'documentValidations'->doc_index;
    selected_doc:=original_input->'documents'->doc_index;
    ddd_known:=((doc->>'originalText')::jsonb->'vocabularies'->'umf.ddd'->>'version')='0.1.0';
    ddd_profile:=validation->'dddProfile';ddd_validation:=validation->'dddValidation';
    IF (SELECT count(*) FROM jsonb_object_keys(validation))<>
      (CASE WHEN ddd_known THEN 5 ELSE 3 END)
      OR validation->>'documentId' IS DISTINCT FROM doc->>'documentId'
      OR validation->>'contentSha256' IS DISTINCT FROM selected_doc->'artifact'->>'sha256'
      OR selected_doc->'ingress' IS DISTINCT FROM '{"kind":"native"}'::jsonb
      OR validation->'validation' IS DISTINCT FROM doc->'validation'->'sourceValidation'
      OR validation->'validation'->'valid' IS DISTINCT FROM 'true'::jsonb
      OR jsonb_typeof(validation->'validation'->'complete') IS DISTINCT FROM 'boolean'
      OR jsonb_typeof(validation->'validation'->'diagnostics') IS DISTINCT FROM 'array'
      OR ddd_known AND (ddd_profile IS DISTINCT FROM jsonb_build_object('identity','umf-ddd-document-validation',
       'version',original_input->'validatorProfile'->>'version','sha256',original_input->'validatorProfile'->>'sha256')
       OR ddd_profile IS DISTINCT FROM doc->'validation'->'dddProfile'
       OR ddd_validation IS DISTINCT FROM doc->'validation'->'dddValidation'
       OR ddd_validation->'valid' IS DISTINCT FROM 'true'::jsonb
       OR jsonb_typeof(ddd_validation->'complete') IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(ddd_validation->'diagnostics') IS DISTINCT FROM 'array')
      OR NOT ddd_known AND (validation ? 'dddProfile' OR validation ? 'dddValidation'
       OR doc->'validation' ? 'dddProfile' OR doc->'validation' ? 'dddValidation') THEN
      RAISE EXCEPTION 'original document validation summary required' USING ERRCODE='22023';END IF;
    doc_index:=doc_index+1;
   END LOOP;
  END;
 ELSE
  RAISE EXCEPTION 'Current registration summary required' USING ERRCODE='22023';
 END IF;

 SELECT r.* INTO existing FROM truss.catalog_registration_request r
  WHERE pg_catalog.sha256(r.input_bytes)=pg_catalog.sha256(catalog_accept_with_keys.input_bytes)
  AND r.input_bytes=catalog_accept_with_keys.input_bytes AND CASE WHEN octet_length(r.document_bytes)=0 THEN
   convert_from(truss.runtime_owned_request_documents(r),'UTF8')::jsonb=convert_from(catalog_accept_with_keys.documents_bytes,'UTF8')::jsonb
  ELSE r.document_bytes=catalog_accept_with_keys.documents_bytes AND r.declaration_bytes=catalog_accept_with_keys.declarations_bytes END
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(catalog_accept_with_keys.documents_bytes,'UTF8')::jsonb) d
   WHERE NOT EXISTS(SELECT 1 FROM truss.schema_doc current_doc WHERE current_doc.doc_id=d.value->>'documentId'
    AND current_doc.rev=(SELECT max(latest.rev) FROM truss.schema_doc latest WHERE latest.doc_id=current_doc.doc_id)
    AND current_doc.document=d.value->>'originalText' AND current_doc.doc_revision=d.value->>'revision'));
 IF FOUND THEN
  PERFORM truss.catalog_require_sources(input_bytes,documents_bytes,declarations_bytes);
  IF NOT preview_mode THEN
  INSERT INTO truss.catalog_unchanged_request(installation_id,actor_oid,actor_name,request_key,registration_id,origin_bytes,expected_revision,expected_documents)
   VALUES(installation.installation_id,actor,session_user::text,request_key,existing.registration_id,origin_bytes,expected_revision,expected_documents);
  IF NOT FOUND THEN RAISE EXCEPTION 'unchanged request not stored' USING ERRCODE='55000';END IF;
  END IF;
  alias_request.actor_name:=session_user::text;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN QUERY SELECT existing.revision::text,existing.registration_id::text,r.report_bytes,false,true,alias_request.actor_name,NULL::bytea
   FROM truss.catalog_acceptance_report r WHERE r.rev=existing.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'original registration report missing' USING ERRCODE='55000'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN;
 END IF;
 PERFORM truss.catalog_require_sources(input_bytes,documents_bytes,declarations_bytes);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(documents_bytes,'UTF8')::jsonb) d
  JOIN truss.schema_doc s ON s.doc_id=d.value->>'documentId') THEN
  IF NOT truss.catalog_ddd_optional_evolution_supported(documents_bytes) THEN
   RAISE EXCEPTION 'known DDD source evolution is outside optional-member compatibility' USING ERRCODE='0A000';END IF;
  violations:=truss.catalog_scalar_violations_with_sources(declarations_bytes,documents_bytes);
  IF violations IS NOT NULL THEN
   PERFORM truss.catalog_actor();
   RETURN QUERY SELECT prior_revision::text,NULL::text,NULL::bytea,false,false,session_user::text,violations;
   RETURN;
  END IF;
 END IF;
 IF prior_revision<> (SELECT coalesce(max(r.revision),0) FROM truss.catalog_registration_request r) THEN
  RAISE EXCEPTION 'complete current catalog head required' USING ERRCODE='55000';END IF;
 IF prior_revision=2147483647 THEN RAISE EXCEPTION 'catalog revision exhausted' USING ERRCODE='54000';END IF;
 new_revision:=prior_revision+1;
 SELECT coalesce(max(type_id),0) INTO type_start FROM truss.type_def;
 SELECT coalesce(max(prop_id),0) INTO property_start FROM truss.prop_def;
 SELECT coalesce(max(rel_type_id),0) INTO relationship_start FROM truss.rel_def;
 IF type_start>2147418111 OR property_start>2147418111 OR relationship_start>2147418111 THEN
  RAISE EXCEPTION 'catalog identity range exhausted' USING ERRCODE='54000';END IF;
 origin:=convert_to((convert_from(origin_bytes,'UTF8')::jsonb||jsonb_build_object('actor',session_user::text,'db_role',session_user::text))::text,'UTF8');
 expected:=truss.catalog_revision_plan(prior_expected,truss.catalog_expected_records(declarations_bytes,documents_bytes,origin,transaction_timestamp(),installation.genesis_at,new_revision,0,0,0));
 -- Input and public-view wire budgets apply to their actual carriers. Source
 -- archives and immutable history are not another request or a rendered view.
 IF jsonb_array_length(expected->'type_def')+jsonb_array_length(expected->'prop_def')+jsonb_array_length(expected->'key_def')+jsonb_array_length(expected->'rel_def')>65536
  THEN RAISE EXCEPTION 'complete catalog resource limit' USING ERRCODE='54000';END IF;
 violations:=truss.catalog_rebind_violations(expected,new_revision);
 IF violations IS NOT NULL THEN
  PERFORM truss.catalog_actor();
  RETURN QUERY SELECT prior_revision::text,NULL::text,NULL::bytea,false,false,session_user::text,violations;RETURN;
 END IF;
 key_candidates:=truss.catalog_key_backfill_candidates(expected,new_revision);
 IF preview_mode THEN
  RETURN QUERY SELECT prior_revision::text,NULL::text,
   convert_to(jsonb_build_object('interfaceVersion','truss-catalog-key-candidates/0.1','candidates',key_candidates)::text,'UTF8'),
   false,false,session_user::text,NULL::bytea;RETURN;
 END IF;
 verified_keys:=truss.catalog_key_backfill_verify(expected,new_revision,coalesce(key_receipts,convert_to('[]','UTF8')));
 violations:=truss.catalog_key_backfill_violations(verified_keys);
 IF violations IS NOT NULL THEN
  PERFORM truss.catalog_actor();
  RETURN QUERY SELECT prior_revision::text,NULL::text,NULL::bytea,false,false,session_user::text,violations;RETURN;
 END IF;
 FOREACH table_name IN ARRAY ARRAY['schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint','schema_change'] LOOP
  rows:=expected->table_name;
  SELECT string_agg(format('%I',a.attname),',' ORDER BY a.attnum),string_agg(format('%I=EXCLUDED.%I',a.attname,a.attname),',' ORDER BY a.attnum) INTO columns,assignments FROM pg_attribute a
   WHERE a.attrelid=to_regclass('truss.'||table_name) AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated='';
  IF table_name='schema_change' THEN
   -- The planner supplies only this new revision's changes.
   INSERT INTO truss.schema_change SELECT p.* FROM truss.catalog_planned_changes(rows) p;
  ELSIF table_name IN ('type_def','prop_def','rel_def') THEN
   identity_column:=CASE table_name WHEN 'type_def' THEN 'type_id' WHEN 'prop_def' THEN 'prop_id' ELSE 'rel_type_id' END;
   EXECUTE format('INSERT INTO truss.%I AS stored(%s) SELECT %s FROM jsonb_populate_recordset(NULL::truss.%I,$1) ON CONFLICT(%I) DO UPDATE SET %s WHERE stored IS DISTINCT FROM EXCLUDED',table_name,columns,columns,table_name,identity_column,assignments) USING rows;
  ELSE
   conflict_columns:=CASE table_name WHEN 'schema_rev' THEN 'rev' WHEN 'schema_doc' THEN 'rev,ord'
    WHEN 'key_def' THEN 'type_id,key_id' WHEN 'relationship_lineage' THEN 'rel_type_id'
    WHEN 'rel_endpoint' THEN 'rel_type_id,source_type,target_type' END;
   EXECUTE format('INSERT INTO truss.%I(%s) SELECT %s FROM jsonb_populate_recordset(NULL::truss.%I,$1) ON CONFLICT(%s) DO NOTHING',table_name,columns,columns,table_name,conflict_columns) USING rows;
  END IF;
 END LOOP;
 request.registration_id:=gen_random_uuid();request.installation_id:=installation.installation_id;
 request.actor_oid:=actor;request.actor_name:=session_user::text;request.request_key:=request_key;
 request.writer_xid:=pg_current_xact_id();request.accepted_at:=transaction_timestamp();request.revision:=new_revision;
 request.expected_revision:=expected_revision;request.expected_documents:=expected_documents;
 request.type_offset:=type_start;request.property_offset:=property_start;request.relationship_offset:=relationship_start;
 request.input_bytes:=input_bytes;request.document_bytes:=CASE WHEN compact THEN ''::bytea ELSE documents_bytes END;
 request.declaration_bytes:=CASE WHEN compact THEN ''::bytea ELSE declarations_bytes END;
 IF compact THEN
  request.source_bytes:=convert_to(jsonb_build_object('sourceFormat','truss-registration-summary/2.0',
   'umf',(convert_from(source_bytes,'UTF8')::jsonb)->'umf',
   'runtimeRelease',jsonb_build_object('id',installation.release_id,'sha256',installation.release_sha256),
   'validationLocation','schema_doc.validation',
   'documentValidations',(SELECT jsonb_agg(jsonb_build_object('documentId',v.value->>'documentId',
    'contentSha256',v.value->>'contentSha256','valid',v.value->'validation'->'valid','complete',v.value->'validation'->'complete') ORDER BY v.ordinality)
    FROM jsonb_array_elements((convert_from(source_bytes,'UTF8')::jsonb)->'documentValidations') WITH ORDINALITY v))::text,'UTF8');
 ELSE request.source_bytes:=source_bytes;END IF;
 request.origin_bytes:=origin_bytes;
 PERFORM truss.catalog_rebind_objects(request,expected);
 PERFORM truss.catalog_key_backfill_apply(request,verified_keys);
 PERFORM truss.catalog_rebind_report_reader(request.registration_id,expected);
 original_report:=truss.catalog_make_report(request,expected);request.report_sha256:=sha256(original_report);
 IF octet_length(original_report)>16777216 THEN RAISE EXCEPTION 'bounded original registration report required' USING ERRCODE='54000';END IF;
 INSERT INTO truss.catalog_acceptance_report VALUES(new_revision,original_report);
 INSERT INTO truss.catalog_registration_request SELECT request.*;
 PERFORM truss.catalog_actor();
 UPDATE truss.schema_head SET rev=new_revision WHERE id=1 AND rev=prior_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'complete head transition required' USING ERRCODE='55000'; END IF;
 -- Property and key rebinds do not change the graph. Only changed bounded
 -- relationships need a census; a removed max-one bound also needs marker cleanup.
 IF EXISTS(SELECT 1 FROM truss.rel_def r LEFT JOIN truss.schema_change c
   ON c.rev=new_revision AND c.kind='rel' AND c.def_id=r.rel_type_id
   WHERE (r.since_rev=new_revision OR c.def_id IS NOT NULL)
    AND (r.source_min>0 OR r.target_min>0 OR r.source_max IS NOT NULL OR r.target_max IS NOT NULL
     OR (c.before->>'source_max')::int=1 OR (c.before->>'target_max')::int=1)) THEN
  PERFORM truss.runtime_graph_validate(true);
 END IF;
 PERFORM truss.catalog_rebind_report_reader(request.registration_id);
 RETURN QUERY SELECT request.revision::text,request.registration_id::text,original_report,false,false,request.actor_name,NULL::bytea;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_ddd_optional_evolution_supported(documents_bytes bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE candidate jsonb;candidate_source jsonb;original jsonb;old_module jsonb;new_module jsonb;old_record jsonb;new_record jsonb;
 old_ddd jsonb;new_ddd jsonb;old_fields jsonb;new_fields jsonb;appended_member jsonb;added_name text;
 field_module text;field_id text;field_element jsonb;core_scalar text;ddd_scalar text;old_count int;member_index int;
BEGIN
 FOR candidate IN SELECT value FROM jsonb_array_elements(convert_from(documents_bytes,'UTF8')::jsonb) LOOP
  SELECT document::jsonb INTO original FROM truss.schema_doc
   WHERE doc_id=candidate->>'documentId' ORDER BY rev DESC LIMIT 1;
  IF NOT FOUND OR original IS NULL THEN CONTINUE;END IF;
  candidate_source:=(candidate->>'originalText')::jsonb;
  IF original->'vocabularies'->'umf.ddd' IS DISTINCT FROM candidate_source->'vocabularies'->'umf.ddd'
    OR original->'extensions'->'umf.ddd' IS DISTINCT FROM candidate_source->'extensions'->'umf.ddd' THEN RETURN false;END IF;
  FOR old_module IN SELECT value FROM jsonb_array_elements(coalesce(original->'modules','[]'::jsonb)) LOOP
   SELECT value INTO new_module FROM jsonb_array_elements(coalesce(candidate_source->'modules','[]'::jsonb)) WHERE value->>'id'=old_module->>'id';
   IF NOT FOUND THEN
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(old_module->'elements','[]'::jsonb)) e
      WHERE e.value->>'kind'='record' AND e.value->'extensions' ? 'umf.ddd') THEN RETURN false;END IF;
    CONTINUE;
   END IF;
   IF old_module->'extensions'->'umf.ddd' IS DISTINCT FROM new_module->'extensions'->'umf.ddd' THEN RETURN false;END IF;
   FOR old_record IN SELECT value FROM jsonb_array_elements(coalesce(old_module->'elements','[]'::jsonb))
    WHERE value->>'kind'='record' LOOP
    SELECT value INTO new_record FROM jsonb_array_elements(coalesce(new_module->'elements','[]'::jsonb))
     WHERE value->>'id'=old_record->>'id' AND value->>'kind'='record';
    old_ddd:=old_record->'extensions'->'umf.ddd';
    IF NOT FOUND THEN IF old_ddd IS NOT NULL THEN RETURN false;END IF;CONTINUE;END IF;
    new_ddd:=new_record->'extensions'->'umf.ddd';
    IF old_ddd IS NOT DISTINCT FROM new_ddd THEN
     IF old_ddd IS NOT NULL AND (original->'vocabularies'->'umf.ddd'->>'version' IS DISTINCT FROM candidate_source->'vocabularies'->'umf.ddd'->>'version'
       OR original->'vocabularies'->'umf.ddd'->>'version' IS DISTINCT FROM '0.1.0') THEN RETURN false;END IF;
     IF old_ddd ? 'fields' AND old_record->'members' IS DISTINCT FROM new_record->'members' THEN RETURN false;END IF;
     CONTINUE;
    END IF;
    old_fields:=old_ddd->'fields';new_fields:=new_ddd->'fields';
    IF original->>'umf' IS DISTINCT FROM '0.10.0'
      OR candidate_source->>'umf' IS DISTINCT FROM '0.10.0'
      OR original->'vocabularies'->'umf.ddd'->>'version' IS DISTINCT FROM '0.1.0'
      OR candidate_source->'vocabularies'->'umf.ddd'->>'version' IS DISTINCT FROM '0.1.0'
      OR jsonb_typeof(old_fields) IS DISTINCT FROM 'object' OR jsonb_typeof(new_fields) IS DISTINCT FROM 'object' THEN
      RETURN false;
    END IF;
    IF (new_record-ARRAY['members','extensions']) IS DISTINCT FROM (old_record-ARRAY['members','extensions'])
      OR ((new_record->'extensions')-'umf.ddd'::text) IS DISTINCT FROM ((old_record->'extensions')-'umf.ddd'::text)
      OR (new_ddd-'fields'::text) IS DISTINCT FROM (old_ddd-'fields'::text)
      OR (SELECT count(*) FROM jsonb_object_keys(new_fields))<>(SELECT count(*) FROM jsonb_object_keys(old_fields))+1
      OR jsonb_array_length(coalesce(new_record->'members','[]'::jsonb))<>jsonb_array_length(coalesce(old_record->'members','[]'::jsonb))+1
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(old_fields) AS k(key) WHERE new_fields->(k.key) IS DISTINCT FROM old_fields->(k.key)) THEN
      RETURN false;
    END IF;
    old_count:=jsonb_array_length(old_record->'members');
    IF old_count>0 THEN
     FOR member_index IN 0..old_count-1 LOOP
      IF old_record->'members'->member_index IS DISTINCT FROM new_record->'members'->member_index THEN RETURN false;END IF;
     END LOOP;
    END IF;
    appended_member:=new_record->'members'->old_count;
    IF jsonb_typeof(appended_member) IS DISTINCT FROM 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(appended_member))<>2
      OR jsonb_typeof(appended_member->'module') IS DISTINCT FROM 'string'
      OR jsonb_typeof(appended_member->'element') IS DISTINCT FROM 'string' THEN RETURN false;END IF;
    added_name:=NULL;
    SELECT k.key INTO added_name FROM jsonb_object_keys(new_fields) AS k(key) WHERE NOT (old_fields ? k.key);
    IF added_name IS NULL OR old_fields ? added_name THEN RETURN false;END IF;
    field_module:=appended_member->>'module';field_id:=appended_member->>'element';
    SELECT element.value INTO field_element
     FROM jsonb_array_elements(coalesce(candidate_source->'modules','[]'::jsonb)) module(value)
     CROSS JOIN LATERAL jsonb_array_elements(coalesce(module.value->'elements','[]'::jsonb)) element(value)
     WHERE module.value->>'id'=field_module AND element.value->>'id'=field_id;
    IF NOT FOUND OR field_element->>'kind' IS DISTINCT FROM 'field'
      OR field_element->>'name' IS DISTINCT FROM added_name
      OR field_element->>'nullability' IS DISTINCT FROM 'absent-allowed'
      OR field_element->>'cardinality' IS DISTINCT FROM 'one' THEN RETURN false;END IF;
    core_scalar:=field_element->>'scalarType';
    ddd_scalar:=CASE core_scalar WHEN 'string' THEN 'string' WHEN 'boolean' THEN 'boolean'
      WHEN 'integer' THEN 'integer' WHEN 'decimal' THEN 'decimal' WHEN 'timestamp' THEN 'date-time' WHEN 'binary' THEN 'bytes' END;
    IF ddd_scalar IS NULL OR jsonb_typeof(new_fields->added_name) IS DISTINCT FROM 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(new_fields->added_name)) NOT BETWEEN 2 AND 3
      OR ((new_fields->added_name)-ARRAY['type','cardinality','description']) IS DISTINCT FROM '{}'::jsonb
      OR jsonb_typeof(new_fields->added_name->'cardinality') IS DISTINCT FROM 'string'
      OR new_fields->added_name->>'cardinality' IS DISTINCT FROM 'optional'
      OR jsonb_typeof(new_fields->added_name->'type') IS DISTINCT FROM 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(new_fields->added_name->'type'))<>2
      OR new_fields->added_name->'type'->>'kind' IS DISTINCT FROM 'scalar'
      OR new_fields->added_name->'type'->>'name' IS DISTINCT FROM ddd_scalar
      OR new_fields->added_name ? 'description' AND jsonb_typeof(new_fields->added_name->'description') IS DISTINCT FROM 'string' THEN
      RETURN false;
    END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_ddd_optional_record_addition(old_document jsonb, new_document jsonb, selected_module text, old_record jsonb, new_record jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE old_module jsonb;new_module jsonb;old_ddd jsonb;new_ddd jsonb;old_source_document jsonb;new_source_document jsonb;
 old_fields jsonb;new_fields jsonb;added_name text;member jsonb;field jsonb;
BEGIN
 old_source_document:=(old_document->>'document')::jsonb;new_source_document:=(new_document->>'document')::jsonb;
 IF old_source_document IS NULL OR new_source_document IS NULL
  OR old_source_document->>'umf' IS DISTINCT FROM '0.10.0' OR new_source_document->>'umf' IS DISTINCT FROM '0.10.0'
  OR old_source_document->'vocabularies'->'umf.ddd'->>'version' IS DISTINCT FROM '0.1.0'
  OR new_source_document->'vocabularies'->'umf.ddd'->>'version' IS DISTINCT FROM '0.1.0'
  OR old_document->'validation'->'dddProfile' IS DISTINCT FROM new_document->'validation'->'dddProfile'
  OR old_document->'validation'->'dddProfile'->>'identity' IS DISTINCT FROM 'umf-ddd-document-validation'
  OR old_document->'validation'->'dddValidation'->'valid' IS DISTINCT FROM 'true'::jsonb
  OR new_document->'validation'->'dddValidation'->'valid' IS DISTINCT FROM 'true'::jsonb THEN RETURN false;END IF;
 SELECT value INTO old_module FROM jsonb_array_elements(old_source_document->'modules') WHERE value->>'id'=selected_module;
 SELECT value INTO new_module FROM jsonb_array_elements(new_source_document->'modules') WHERE value->>'id'=selected_module;
 IF old_module IS NULL OR new_module IS NULL
  OR old_module->'extensions'->'umf.ddd' IS DISTINCT FROM new_module->'extensions'->'umf.ddd' THEN RETURN false;END IF;
 old_ddd:=old_record->'extensions'->'umf.ddd';new_ddd:=new_record->'extensions'->'umf.ddd';
 old_fields:=old_ddd->'fields';new_fields:=new_ddd->'fields';
 IF jsonb_typeof(old_fields) IS DISTINCT FROM 'object' OR jsonb_typeof(new_fields) IS DISTINCT FROM 'object'
  OR (new_record-ARRAY['members','extensions']) IS DISTINCT FROM (old_record-ARRAY['members','extensions'])
  OR ((new_record->'extensions')-'umf.ddd'::text) IS DISTINCT FROM ((old_record->'extensions')-'umf.ddd'::text)
  OR (new_ddd-'fields'::text) IS DISTINCT FROM (old_ddd-'fields'::text)
  OR (SELECT count(*) FROM jsonb_object_keys(new_fields))<>(SELECT count(*) FROM jsonb_object_keys(old_fields))+1
  OR jsonb_array_length(coalesce(new_record->'members','[]'::jsonb))<>jsonb_array_length(coalesce(old_record->'members','[]'::jsonb))+1
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(old_fields) AS k(key) WHERE new_fields->(k.key) IS DISTINCT FROM old_fields->(k.key)) THEN
  RETURN false;
 END IF;
 IF jsonb_array_length(coalesce(old_record->'members','[]'::jsonb))>0 AND EXISTS(
   SELECT 1 FROM jsonb_array_elements(old_record->'members') WITH ORDINALITY old_member(value,ordinality)
   JOIN jsonb_array_elements(new_record->'members') WITH ORDINALITY new_member(value,ordinality) USING(ordinality)
   WHERE old_member.value IS DISTINCT FROM new_member.value) THEN RETURN false;END IF;
 member:=new_record->'members'->jsonb_array_length(coalesce(old_record->'members','[]'::jsonb));
 IF jsonb_typeof(member) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(member))<>2
  OR member->>'module' IS DISTINCT FROM selected_module THEN RETURN false;END IF;
 added_name:=NULL;
 SELECT k.key INTO added_name FROM jsonb_object_keys(new_fields) AS k(key) WHERE NOT (old_fields ? k.key);
 IF added_name IS NULL OR old_fields ? added_name THEN RETURN false;END IF;
 SELECT element.value INTO field FROM jsonb_array_elements(new_module->'elements') element(value)
  WHERE element.value->>'id'=member->>'element';
 IF NOT FOUND OR field->>'kind' IS DISTINCT FROM 'field' OR field->>'name' IS DISTINCT FROM added_name
  OR field->>'nullability' IS DISTINCT FROM 'absent-allowed' OR field->>'cardinality' IS DISTINCT FROM 'one' THEN RETURN false;END IF;
 IF jsonb_typeof(new_fields->added_name) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(new_fields->added_name)) NOT BETWEEN 2 AND 3
  OR ((new_fields->added_name)-ARRAY['type','cardinality','description']) IS DISTINCT FROM '{}'::jsonb
  OR new_fields->added_name->>'cardinality' IS DISTINCT FROM 'optional'
  OR new_fields->added_name->'type'->>'kind' IS DISTINCT FROM 'scalar' THEN RETURN false;END IF;
 RETURN CASE field->>'scalarType' WHEN 'string' THEN new_fields->added_name->'type'->>'name'='string'
  WHEN 'boolean' THEN new_fields->added_name->'type'->>'name'='boolean'
  WHEN 'integer' THEN new_fields->added_name->'type'->>'name'='integer'
  WHEN 'decimal' THEN new_fields->added_name->'type'->>'name'='decimal'
  WHEN 'timestamp' THEN new_fields->added_name->'type'->>'name'='date-time'
  WHEN 'binary' THEN new_fields->added_name->'type'->>'name'='bytes' ELSE false END;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_item_definition_indexed(source_index jsonb, selected_document text, selected_revision integer, selected_ordinal integer, reference jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE source_digest text;umf_version text;pointer text;original bytea;pin_input text;result jsonb;declaration jsonb;
 selected_reference jsonb:=reference;seen jsonb:='[]';chain jsonb:='[]';node jsonb;entry jsonb;fragment_text text;
 module_index int;element_index int;depth int:=0;
BEGIN
 IF jsonb_typeof(source_index) IS DISTINCT FROM 'object'
  OR jsonb_typeof(source_index->'definitions') IS DISTINCT FROM 'object'
  OR jsonb_typeof(source_index->'sourceSha256') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'original item source index required' USING ERRCODE='22023';END IF;
 source_digest:=source_index->>'sourceSha256';umf_version:=source_index->>'umfVersion';
 LOOP
  depth:=depth+1;
  IF depth>32 THEN RAISE EXCEPTION 'item definition depth limit' USING ERRCODE='54000';END IF;
  IF jsonb_typeof(selected_reference) IS DISTINCT FROM 'object' OR selected_reference-ARRAY['module','element']<>'{}'::jsonb
   OR jsonb_typeof(selected_reference->'module') IS DISTINCT FROM 'string' OR jsonb_typeof(selected_reference->'element') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'explicit qualified item Field required' USING ERRCODE='0A000';END IF;
  IF seen @> jsonb_build_array(selected_reference) THEN RAISE EXCEPTION 'acyclic item definition chain required' USING ERRCODE='0A000';END IF;
  seen:=seen||jsonb_build_array(selected_reference);
  entry:=source_index->'definitions'->jsonb_build_array(selected_reference->>'module',selected_reference->>'element')::text;
  IF entry IS NULL THEN RAISE NO_DATA_FOUND;END IF;
  module_index:=(entry->>'moduleOrdinal')::int;element_index:=(entry->>'elementOrdinal')::int;
  fragment_text:=entry->>'originalFragment';declaration:=entry->'declaration';
  IF declaration->>'kind' IS DISTINCT FROM 'field' OR declaration->>'nullability' IS DISTINCT FROM 'required' THEN
   RAISE EXCEPTION 'required original item Field required' USING ERRCODE='0A000';END IF;
  IF declaration->>'cardinality'='one' THEN
   IF coalesce(declaration->>'scalarType','') NOT IN ('string','integer','decimal','boolean','timestamp','binary','date') OR declaration ? 'itemType'
    OR truss.known_scalar_facets(declaration->>'scalarType',declaration->'facets') IS NOT TRUE THEN
    RAISE EXCEPTION 'required exact scalar leaf Field required' USING ERRCODE='0A000';END IF;
  ELSIF declaration->>'cardinality' IN ('array','map') THEN
   IF declaration ? 'scalarType' OR coalesce(declaration->'facets','{}'::jsonb)<>'{}'::jsonb OR NOT declaration ? 'itemType' THEN
    RAISE EXCEPTION 'explicit unfaceted container item Field required' USING ERRCODE='0A000';END IF;
  ELSE RAISE EXCEPTION 'supported item Field cardinality required' USING ERRCODE='0A000';END IF;
  pointer:='/modules/'||module_index||'/elements/'||element_index;original:=convert_to(fragment_text,'UTF8');
  pin_input:='['||selected_revision||','||selected_ordinal||',"'||source_digest||'","'||pointer
   ||'",{"identity":"truss-original-json-definition","sha256":"08c2ec8c520b39ded40f270be0b26812db1d240d5bac1a00339b437200a2f58d","version":"0.1"},"'||encode(sha256(original),'hex')||'"]';
  node:=jsonb_build_object('reference',selected_reference,'documentId',selected_document,'catalogRevision',selected_revision::text,'documentOrdinal',selected_ordinal::text,
   'umfVersion',umf_version,'sourceSha256',source_digest,'originalPointer',pointer,'originalFragment',fragment_text,'definitionPin',encode(sha256(convert_to(pin_input,'UTF8')),'hex'),'declaration',declaration);
  chain:=chain||jsonb_build_array(node);
  EXIT WHEN declaration->>'cardinality'='one';
  selected_reference:=declaration->'itemType';
 END LOOP;
 result:=chain->0;
 IF jsonb_array_length(chain)>1 THEN
  result:=result||jsonb_build_object('descendants',(SELECT jsonb_agg(value ORDER BY ordinality) FROM jsonb_array_elements(chain) WITH ORDINALITY WHERE ordinality>1));
 END IF;
 IF octet_length(result::text)>65536 THEN RAISE EXCEPTION 'item definition byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_item_meaning(item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE nodes jsonb;node jsonb;result jsonb:='[]';
BEGIN
 IF item IS NULL OR jsonb_typeof(item) IS DISTINCT FROM 'object'
  OR jsonb_typeof(coalesce(item->'descendants','[]'::jsonb)) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'complete original item definition chain required' USING ERRCODE='22023';END IF;
 nodes:=jsonb_build_array(item)||coalesce(item->'descendants','[]'::jsonb);
 IF jsonb_array_length(nodes)>32 THEN RAISE EXCEPTION 'item definition depth limit' USING ERRCODE='54000';END IF;
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) LOOP
  IF jsonb_typeof(node->'reference') IS DISTINCT FROM 'object'
   OR jsonb_typeof(node->'declaration') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'complete authored item meaning required' USING ERRCODE='22023';END IF;
  result:=result||jsonb_build_array(jsonb_build_object('reference',node->'reference','declaration',node->'declaration'));
 END LOOP;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_key_backfill_apply(request truss.catalog_registration_request, verified_receipts jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE selected record;entry jsonb;owner truss.type_def%ROWTYPE;object_row truss.object%ROWTYPE;
 definition truss.key_def%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;pin record;observed record;
 original_image jsonb;keys jsonb;effects jsonb;values_cells jsonb;facets jsonb;property truss.prop_def%ROWTYPE;component int;
 ns bytea;transport bytea;context_bytes bytea;reservation_bytes bytea;member_id bigint;reservation_id bigint;prior_generation bigint;membership truss.object_key_bucket%ROWTYPE;reservation truss.object_key_reservation_bucket%ROWTYPE;actual_row jsonb;
BEGIN
 IF request.actor_oid IS DISTINCT FROM truss.catalog_actor() OR request.actor_name IS DISTINCT FROM session_user::text
  OR request.writer_xid IS DISTINCT FROM pg_current_xact_id() OR request.registration_id IS NULL THEN
  RAISE EXCEPTION 'current original catalog key registration required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF truss.catalog_key_backfill_violations(verified_receipts) IS NOT NULL THEN
  RAISE EXCEPTION 'unique complete backfill tuples required' USING ERRCODE='23505';END IF;
 FOR selected IN SELECT DISTINCT (r.value->>'typeId')::int type_id,(r.value->>'objectId')::bigint object_id
  FROM jsonb_array_elements(verified_receipts) r ORDER BY 1,2 LOOP
  SELECT * INTO STRICT owner FROM truss.type_def WHERE type_id=selected.type_id AND retired_rev IS NULL;
  PERFORM truss.runtime_module_writer(owner.document_id,owner.module);
  IF truss.runtime_object_values_readable(owner.type_id) IS NOT TRUE THEN
   RAISE EXCEPTION 'current key backfill reader required' USING ERRCODE='42501';END IF;
  SELECT * INTO STRICT object_row FROM truss.object WHERE id=selected.object_id AND type_id=selected.type_id FOR UPDATE;
  original_image:=to_jsonb(object_row);effects:='[]';
  FOR entry IN SELECT r.value FROM jsonb_array_elements(verified_receipts) r
   WHERE r.value->>'typeId'=selected.type_id::text AND r.value->>'objectId'=selected.object_id::text
   ORDER BY (r.value->>'keyNumber')::smallint LOOP
   IF encode(sha256(convert_to(original_image::text,'UTF8')),'hex') IS DISTINCT FROM entry->>'objectImageSha256'
    AND NOT EXISTS(SELECT 1 FROM truss.runtime_catalog_rebind_transition t WHERE t.registration_id=request.registration_id
     AND t.object_id=selected.object_id AND t.type_id=selected.type_id AND t.after_object=original_image
     AND encode(sha256(convert_to(t.before_object::text,'UTF8')),'hex')=entry->>'objectImageSha256') THEN
    RAISE EXCEPTION 'original locked backfill object image required' USING ERRCODE='55000';END IF;
   SELECT * INTO STRICT definition FROM truss.key_def WHERE type_id=selected.type_id AND key_num=(entry->>'keyNumber')::smallint
    AND key_id=entry->>'keyId' AND since_rev=request.revision AND retired_rev IS NULL AND NOT is_primary;
   values_cells:='[]';facets:='[]';
   FOREACH component IN ARRAY definition.prop_ids LOOP
    SELECT * INTO STRICT property FROM truss.prop_def WHERE type_id=selected.type_id AND prop_id=component AND retired_rev IS NULL;
    values_cells:=values_cells||jsonb_build_array(object_row.props->component::text);facets:=facets||jsonb_build_array(coalesce(property.facets,'{}'));
   END LOOP;
   IF values_cells IS DISTINCT FROM entry->'values' OR truss.verify_umf_scalar_key_tuple(decode(entry->>'tupleHex','hex'),values_cells,facets) IS NOT TRUE THEN
    RAISE EXCEPTION 'unchanged exact final key values required' USING ERRCODE='55000';END IF;
   SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',selected.type_id,definition.key_num);
   ns:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,
    'sourceEpoch',installation.source_epoch::text,'typeId',selected.type_id::text,'keyNumber',definition.key_num::text,
    'definitionPin',pin.definition_pin,'encoding','umf-key-tuple-v1')::text,'UTF8');
   transport:=convert_to('umf-key-tuple-v1:hex:'||(entry->>'tupleHex'),'UTF8');
   SELECT * INTO STRICT observed FROM truss.lock_string_key_bucket(ns,transport);prior_generation:=observed.generation;
   IF cardinality(observed.member_ids)>0 OR cardinality(observed.reservation_ids)>0 THEN
    RAISE EXCEPTION 'new key already allocated or reserved' USING ERRCODE='23505';END IF;
   context_bytes:=convert_to(jsonb_build_object('profile','truss-catalog-key-backfill-context/0.2','registrationId',request.registration_id::text,
    'objectId',selected.object_id::text,'xid',request.writer_xid::text,'derivation','postgresql-umf-key-tuple-v1')::text,'UTF8');
   reservation_bytes:=convert_to(jsonb_build_object('profile','truss-catalog-key-backfill-reservation/0.1','registrationId',request.registration_id::text,
    'objectId',selected.object_id::text,'typeId',selected.type_id::text,'keyNumber',definition.key_num::text,'xid',request.writer_xid::text)::text,'UTF8');
   membership.storage_row_id:=nextval('truss.key_storage_row_seq');membership.type_id:=selected.type_id;
   membership.key_num:=definition.key_num;membership.object_id:=selected.object_id;membership.namespace_bytes:=ns;
   membership.key_bytes:=transport;membership.original_context_bytes:=context_bytes;
   membership.namespace_sha256:=sha256(ns);membership.key_sha256:=sha256(transport);member_id:=membership.storage_row_id;
   INSERT INTO truss.object_key_bucket(storage_row_id,type_id,key_num,object_id,namespace_bytes,key_bytes,original_context_bytes)
    VALUES(member_id,selected.type_id,definition.key_num,selected.object_id,ns,transport,context_bytes) RETURNING to_jsonb(object_key_bucket) INTO actual_row;
   IF actual_row IS DISTINCT FROM to_jsonb(membership) THEN RAISE EXCEPTION 'exact backfill membership insert required' USING ERRCODE='55000';END IF;
   reservation.storage_row_id:=nextval('truss.key_storage_row_seq');reservation.namespace_bytes:=ns;reservation.key_bytes:=transport;
   reservation.original_reservation_bytes:=reservation_bytes;reservation.namespace_sha256:=sha256(ns);reservation.key_sha256:=sha256(transport);reservation_id:=reservation.storage_row_id;
   INSERT INTO truss.object_key_reservation_bucket(storage_row_id,namespace_bytes,key_bytes,original_reservation_bytes)
    VALUES(reservation_id,ns,transport,reservation_bytes) RETURNING to_jsonb(object_key_reservation_bucket) INTO actual_row;
   IF actual_row IS DISTINCT FROM to_jsonb(reservation) THEN RAISE EXCEPTION 'exact backfill reservation insert required' USING ERRCODE='55000';END IF;
   UPDATE truss.key_bucket_guard SET generation=generation+1 WHERE namespace_sha256=sha256(ns) AND key_sha256=sha256(transport);
   SELECT * INTO STRICT observed FROM truss.lock_string_key_bucket(ns,transport);
   IF observed.generation IS DISTINCT FROM prior_generation+1 OR observed.member_ids IS DISTINCT FROM ARRAY[member_id]
    OR observed.reservation_ids IS DISTINCT FROM ARRAY[reservation_id] THEN
    RAISE EXCEPTION 'exact applied backfill key bucket required' USING ERRCODE='55000';END IF;
   effects:=effects||jsonb_build_array(jsonb_build_object('keyId',definition.key_id,'keyNumber',definition.key_num::text,
    'definitionPin',pin.definition_pin,'namespaceBase64',replace(encode(ns,'base64'),chr(10),''),'tupleHex',entry->>'tupleHex',
    'derivation','postgresql-umf-key-tuple-v1','memberId',member_id::text,'reservationId',reservation_id::text,
    'priorGeneration',prior_generation::text,'generation',observed.generation::text,
    'contextBase64',replace(encode(context_bytes,'base64'),chr(10),''),'reservationBase64',replace(encode(reservation_bytes,'base64'),chr(10),'')));
  END LOOP;
  IF (SELECT to_jsonb(o) FROM truss.object o WHERE o.id=selected.object_id AND o.type_id=selected.type_id) IS DISTINCT FROM original_image THEN
   RAISE EXCEPTION 'key-only backfill preserves exact object image' USING ERRCODE='55000';END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY k.key_num),'[]') INTO keys FROM truss.object_key_bucket k
   WHERE k.object_id=selected.object_id AND k.type_id=selected.type_id;
  INSERT INTO truss.runtime_catalog_key_backfill(registration_id,writer_xid,actor_oid,revision,object_id,type_id,object_image,after_keys,effects)
   VALUES(request.registration_id,request.writer_xid,request.actor_oid,request.revision,selected.object_id,selected.type_id,original_image,keys,effects);
 END LOOP;
 PERFORM truss.catalog_actor();
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_key_backfill_candidates(planned_basis jsonb, selected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE definition truss.key_def%ROWTYPE;owner truss.type_def%ROWTYPE;property truss.prop_def%ROWTYPE;
 object_row truss.object%ROWTYPE;component int;values_cells jsonb;archive truss.schema_doc%ROWTYPE;result jsonb:='[]';candidate_count int:=0;head int;selected_cell jsonb;
BEGIN
 PERFORM truss.catalog_actor();
 SELECT rev INTO STRICT head FROM truss.schema_head WHERE id=1 FOR UPDATE NOWAIT;
 IF selected_revision IS DISTINCT FROM head+1 OR planned_basis IS NULL THEN
  RAISE EXCEPTION 'original locked next catalog basis required' USING ERRCODE='55000';END IF;
 FOR definition IN SELECT k.* FROM jsonb_populate_recordset(NULL::truss.key_def,planned_basis->'key_def') k
  WHERE k.since_rev=selected_revision AND EXISTS(SELECT 1 FROM truss.type_def t WHERE t.type_id=k.type_id)
  AND NOT EXISTS(SELECT 1 FROM truss.key_def old WHERE old.type_id=k.type_id AND old.key_id=k.key_id)
  ORDER BY k.type_id,k.key_num LOOP
  IF definition.is_primary OR cardinality(definition.prop_ids) NOT BETWEEN 1 AND 127 THEN
   RAISE EXCEPTION 'new bounded alternate key required' USING ERRCODE='0A000';END IF;
  SELECT * INTO STRICT owner FROM truss.type_def WHERE type_id=definition.type_id AND retired_rev IS NULL;
  PERFORM truss.runtime_module_writer(owner.document_id,owner.module);
  IF truss.runtime_object_values_readable(owner.type_id) IS NOT TRUE THEN
   RAISE EXCEPTION 'current key backfill reader required' USING ERRCODE='42501';END IF;
  FOREACH component IN ARRAY definition.prop_ids LOOP
   SELECT * INTO STRICT property FROM jsonb_populate_recordset(NULL::truss.prop_def,planned_basis->'prop_def') p WHERE p.prop_id=component AND p.type_id=owner.type_id AND p.retired_rev IS NULL;
   IF property.nullability IS DISTINCT FROM 'required' OR property.cardinality IS DISTINCT FROM 'one'
    OR property.scalar_type NOT IN ('string','integer','decimal','boolean','binary') THEN
    RAISE EXCEPTION 'required scalar key components required' USING ERRCODE='0A000';END IF;
   IF truss.runtime_can_read(owner.document_id,property.declaration_module) IS NOT TRUE THEN
    RAISE EXCEPTION 'current planned key component reader required' USING ERRCODE='42501';END IF;
  END LOOP;
  SELECT * INTO STRICT archive FROM jsonb_populate_recordset(NULL::truss.schema_doc,planned_basis->'schema_doc') d
   WHERE d.rev=definition.definition_rev AND d.ord=definition.definition_doc_ord AND d.doc_id=definition.definition_document_id;
  IF archive.content_sha256 IS DISTINCT FROM encode(sha256(convert_to(archive.document,'UTF8')),'hex') THEN
   RAISE EXCEPTION 'original planned document bytes required' USING ERRCODE='55000';END IF;
  FOR object_row IN SELECT o.* FROM truss.object o WHERE o.type_id=owner.type_id ORDER BY o.id FOR UPDATE LOOP
   candidate_count:=candidate_count+1;values_cells:='[]';
   PERFORM truss.runtime_history_ownership(jsonb_build_object(
    'identity',jsonb_build_object('id',object_row.id::text,'typeId',object_row.type_id::text),
    'catalogRevision',object_row.rev,'ownership',truss.runtime_object_ownership_at(to_jsonb(object_row))));
   IF candidate_count>10000 THEN RAISE EXCEPTION 'bounded key backfill inventory required' USING ERRCODE='54000';END IF;
   FOREACH component IN ARRAY definition.prop_ids LOOP
    SELECT * INTO STRICT property FROM jsonb_populate_recordset(NULL::truss.prop_def,planned_basis->'prop_def') p WHERE p.prop_id=component AND p.type_id=owner.type_id;
    IF EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.prop_id=component AND p.type_id=owner.type_id) THEN
     selected_cell:=object_row.props->component::text;
    ELSE
     IF property.since_rev IS DISTINCT FROM selected_revision OR object_row.props ? component::text THEN
      RAISE EXCEPTION 'genuinely new absent key destination required' USING ERRCODE='55000';END IF;
     selected_cell:=object_row.retained->property.name;
    END IF;
    IF truss.valid_scalar_property(selected_cell,property.scalar_type,false,property.facets) IS NOT TRUE THEN
     RAISE EXCEPTION 'valid complete key candidate values required' USING ERRCODE='22023';END IF;
    values_cells:=values_cells||jsonb_build_array(selected_cell);
   END LOOP;
   result:=result||jsonb_build_array(jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module,
    'recordId',owner.element,'keyId',definition.key_id,'keyNumber',definition.key_num::text,'typeId',owner.type_id::text,
    'objectId',object_row.id::text,'objectVersion',object_row.ver::text,'sourceRevision',archive.rev::text,'sourceOrdinal',archive.ord::text,
    'sourceDocumentId',archive.doc_id,'sourceSha256',archive.content_sha256,
    'objectImageSha256',encode(sha256(convert_to(to_jsonb(object_row)::text,'UTF8')),'hex'),'values',values_cells));
   IF octet_length(convert_to(result::text,'UTF8'))>8388608 THEN
    RAISE EXCEPTION 'bounded original key candidate bytes required' USING ERRCODE='54000';END IF;
  END LOOP;
 END LOOP;
 PERFORM truss.catalog_actor();
 FOR owner IN SELECT t.* FROM truss.type_def t WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result) c WHERE c.value->>'typeId'=t.type_id::text) ORDER BY t.type_id LOOP
  PERFORM truss.runtime_module_writer(owner.document_id,owner.module);
  IF truss.runtime_object_values_readable(owner.type_id) IS NOT TRUE THEN
   RAISE EXCEPTION 'current key backfill disclosure reader required' USING ERRCODE='42501';END IF;
  FOR object_row IN SELECT o.* FROM truss.object o WHERE o.type_id=owner.type_id AND o.root_id IS NOT NULL LOOP
   PERFORM truss.runtime_history_ownership(jsonb_build_object(
    'identity',jsonb_build_object('id',object_row.id::text,'typeId',object_row.type_id::text),
    'catalogRevision',object_row.rev,'ownership',truss.runtime_object_ownership_at(to_jsonb(object_row))));
  END LOOP;
 END LOOP;
 FOR property IN SELECT p.* FROM jsonb_populate_recordset(NULL::truss.prop_def,planned_basis->'prop_def') p
  WHERE EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::truss.key_def,planned_basis->'key_def') k
   WHERE k.since_rev=selected_revision AND k.type_id=p.type_id AND p.prop_id=ANY(k.prop_ids)
    AND NOT k.is_primary
    AND EXISTS(SELECT 1 FROM truss.type_def t WHERE t.type_id=k.type_id)
    AND NOT EXISTS(SELECT 1 FROM truss.key_def old WHERE old.type_id=k.type_id AND old.key_id=k.key_id)) LOOP
  SELECT * INTO STRICT owner FROM truss.type_def WHERE type_id=property.type_id;
  IF truss.runtime_can_read(owner.document_id,property.declaration_module) IS NOT TRUE THEN
   RAISE EXCEPTION 'current planned key component disclosure reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_key_backfill_report_reader(selected_registration uuid, planned_basis jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE transition truss.runtime_catalog_key_backfill%ROWTYPE;
BEGIN
 FOR transition IN SELECT * FROM truss.runtime_catalog_key_backfill WHERE registration_id=selected_registration LOOP
  PERFORM truss.catalog_key_backfill_transition_reader(transition,planned_basis);
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_key_backfill_transition_reader(transition truss.runtime_catalog_key_backfill, planned_basis jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE basis jsonb;owner truss.type_def%ROWTYPE;definition truss.key_def%ROWTYPE;property truss.prop_def%ROWTYPE;
 effect jsonb;component int;pin record;
BEGIN
 basis:=coalesce(planned_basis,truss.catalog_all_expected_records(transition.revision));
 SELECT * INTO STRICT owner FROM jsonb_populate_recordset(NULL::truss.type_def,basis->'type_def') t WHERE t.type_id=transition.type_id;
 IF truss.runtime_can_read(owner.document_id,owner.module) IS NOT TRUE THEN
  RAISE EXCEPTION 'current original backfill owner reader required' USING ERRCODE='42501';END IF;
 PERFORM truss.runtime_history_ownership(jsonb_build_object(
  'identity',jsonb_build_object('id',transition.object_image->>'id','typeId',transition.object_image->>'type_id'),
  'catalogRevision',transition.object_image->'rev',
  'ownership',truss.runtime_object_ownership_at(transition.object_image)));
 FOR effect IN SELECT value FROM jsonb_array_elements(transition.effects) LOOP
  SELECT * INTO STRICT definition FROM jsonb_populate_recordset(NULL::truss.key_def,basis->'key_def') k
   WHERE k.type_id=transition.type_id AND k.key_num=(effect->>'keyNumber')::smallint AND k.key_id=effect->>'keyId';
  SELECT * INTO STRICT pin FROM truss.catalog_rebind_definition('key',transition.type_id,definition.key_num,basis);
  IF pin.definition_pin IS DISTINCT FROM effect->>'definitionPin' THEN
   RAISE EXCEPTION 'original backfill key definition required' USING ERRCODE='55000';END IF;
  FOREACH component IN ARRAY definition.prop_ids LOOP
   SELECT * INTO STRICT property FROM jsonb_populate_recordset(NULL::truss.prop_def,basis->'prop_def') p WHERE p.prop_id=component AND p.type_id=transition.type_id;
   IF truss.runtime_can_read(owner.document_id,property.declaration_module) IS NOT TRUE THEN
    RAISE EXCEPTION 'current original key component reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_key_backfill_verify(planned_basis jsonb, selected_revision integer, original_receipts bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE candidates jsonb;entry jsonb;result jsonb:='[]';tuple_bytes bytea;
BEGIN
 IF original_receipts IS NOT NULL AND original_receipts<>convert_to('[]','UTF8') THEN
  RAISE EXCEPTION 'client key receipts are no longer accepted' USING ERRCODE='22023';END IF;
 candidates:=truss.catalog_key_backfill_candidates(planned_basis,selected_revision);
 FOR entry IN SELECT value FROM jsonb_array_elements(candidates) LOOP
  tuple_bytes:=truss.derive_catalog_key_tuple((entry->>'typeId')::int,(entry->>'keyNumber')::smallint,entry->'values',planned_basis);
  result:=result||jsonb_build_array(entry||jsonb_build_object('tupleHex',encode(tuple_bytes,'hex')));
  IF octet_length(result::text)>8388608 THEN RAISE EXCEPTION 'bounded native key backfill required' USING ERRCODE='54000';END IF;
 END LOOP;
 IF truss.catalog_key_backfill_candidates(planned_basis,selected_revision) IS DISTINCT FROM candidates THEN
  RAISE EXCEPTION 'key candidates changed during native derivation' USING ERRCODE='55000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_make_report(request truss.catalog_registration_request, planned_basis jsonb DEFAULT NULL::jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET bytea_output TO 'hex'
AS $function$
DECLARE report jsonb; source jsonb; basis jsonb;rebind_profile text;profile_count int;
BEGIN
  source:=convert_from(request.source_bytes,'UTF8')::jsonb;
  report:=jsonb_build_object('interfaceVersion','truss-catalog-registration-report/0.6',
   'registrationId',request.registration_id::text,'installationId',request.installation_id::text,
   'revision',request.revision::text,'actor',request.actor_name,'actorOid',request.actor_oid::text,
   'writerXid',request.writer_xid::text,'requestKey',request.request_key,
   'acceptedAt',to_char(request.accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'release',source->'runtimeRelease','acceptedInput',convert_from(request.input_bytes,'UTF8')::jsonb,
   'source',source,'assertedOrigin',convert_from(request.origin_bytes,'UTF8')::jsonb,
   'effects',jsonb_build_object(
    'reboundObjects',(SELECT count(*) FROM truss.runtime_catalog_rebind_transition WHERE registration_id=request.registration_id),
    'keyBackfills',(SELECT count(*) FROM truss.runtime_catalog_key_backfill WHERE registration_id=request.registration_id)));
  -- Compact receipts keep effect payloads in their native history homes, but
  -- must still identify the original encoding used by those effects.
  IF EXISTS(SELECT 1 FROM truss.runtime_catalog_rebind_transition t WHERE t.registration_id=request.registration_id) THEN
   SELECT min(truss.catalog_rebind_profile(t.journal)),count(DISTINCT truss.catalog_rebind_profile(t.journal))
    INTO rebind_profile,profile_count FROM truss.runtime_catalog_rebind_transition t WHERE t.registration_id=request.registration_id;
   IF profile_count<>1 THEN RAISE EXCEPTION 'one original registration rebind profile required' USING ERRCODE='55000';END IF;
   report:=report||jsonb_build_object('rebindProfile',rebind_profile);
  END IF;
  IF EXISTS(SELECT 1 FROM truss.runtime_catalog_key_backfill t WHERE t.registration_id=request.registration_id) THEN
   basis:=coalesce(planned_basis,truss.catalog_all_expected_records(request.revision));
   report:=report||jsonb_build_object('keyBackfillProfile',CASE WHEN EXISTS(
    SELECT 1 FROM truss.runtime_catalog_key_backfill b CROSS JOIN LATERAL jsonb_array_elements(b.effects) e
    JOIN jsonb_populate_recordset(NULL::truss.key_def,basis->'key_def') k ON k.type_id=b.type_id AND k.key_num=(e.value->>'keyNumber')::smallint
    JOIN jsonb_populate_recordset(NULL::truss.prop_def,basis->'prop_def') p ON p.type_id=k.type_id AND p.prop_id=ANY(k.prop_ids)
    WHERE b.registration_id=request.registration_id AND p.since_rev=request.revision)
    THEN 'truss-catalog-key-backfill/0.2' ELSE 'truss-catalog-key-backfill/0.1' END);
  END IF;
  report:=report||jsonb_build_object('enforcement',truss.catalog_enforcement(request.revision));
  RETURN convert_to(report::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_definition(selected_kind text, selected_type integer, selected_number integer, planned_basis jsonb)
 RETURNS TABLE(definition_pin text, original_fragment bytea, original_pointer text, document_id text, module_id text, element_id text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE basis jsonb;definition jsonb; archive truss.schema_doc%ROWTYPE; native_type truss.type_def%ROWTYPE;
 source_module text;source_element text;module_json json;module_index int;element_json json;element_index int;
 key_json json;key_index int;fragment json;pointer text;pin_input text;
BEGIN
 IF planned_basis IS NULL THEN
  SELECT * INTO STRICT native_type FROM truss.type_def WHERE type_id=selected_type AND NOT provisional AND retired_rev IS NULL;
 ELSE
  basis:=planned_basis;
  SELECT * INTO STRICT native_type FROM jsonb_populate_recordset(NULL::truss.type_def,basis->'type_def') t WHERE t.type_id=selected_type;
 END IF;
 IF selected_kind='type' THEN
  definition:=to_jsonb(native_type);source_module:=native_type.module;source_element:=native_type.element;
 ELSIF selected_kind='property' THEN
  IF planned_basis IS NULL THEN
   SELECT to_jsonb(p),p.declaration_module,p.element INTO STRICT definition,source_module,source_element FROM truss.prop_def p WHERE p.type_id=selected_type AND p.prop_id=selected_number AND p.retired_rev IS NULL;
  ELSE
   SELECT to_jsonb(p),p.declaration_module,p.element INTO STRICT definition,source_module,source_element FROM jsonb_populate_recordset(NULL::truss.prop_def,basis->'prop_def') p WHERE p.type_id=selected_type AND p.prop_id=selected_number;
  END IF;
 ELSIF selected_kind='key' THEN
  IF planned_basis IS NULL THEN
   SELECT to_jsonb(k) INTO STRICT definition FROM truss.key_def k WHERE k.type_id=selected_type AND k.key_num=selected_number AND k.retired_rev IS NULL;
  ELSE
   SELECT to_jsonb(k) INTO STRICT definition FROM jsonb_populate_recordset(NULL::truss.key_def,basis->'key_def') k WHERE k.type_id=selected_type AND k.key_num=selected_number;
  END IF;
  source_module:=native_type.module;source_element:=native_type.element;
 ELSE RAISE EXCEPTION 'supported definition kind required' USING ERRCODE='22023'; END IF;
 IF definition->>'definition_source_kind'<>'accepted_document' OR (definition->>'definition_rev')::int<1 THEN
  RAISE EXCEPTION 'original accepted definition source required' USING ERRCODE='0A000'; END IF;
 SELECT * INTO STRICT archive FROM truss.schema_doc d WHERE d.rev=(definition->>'definition_rev')::int AND d.ord=(definition->>'definition_doc_ord')::int
  AND d.doc_id=definition->>'definition_document_id';
 SELECT m.value,m.ordinality::int-1 INTO STRICT module_json,module_index
  FROM json_array_elements(archive.document::json->'modules') WITH ORDINALITY m WHERE m.value->>'id'=source_module;
 SELECT e.value,e.ordinality::int-1 INTO STRICT element_json,element_index
  FROM json_array_elements(module_json->'elements') WITH ORDINALITY e WHERE e.value->>'id'=source_element;
 fragment:=element_json;pointer:='/modules/'||module_index||'/elements/'||element_index;
 IF selected_kind='key' THEN
  SELECT k.value,k.ordinality::int-1 INTO STRICT key_json,key_index
   FROM json_array_elements(element_json->'keys') WITH ORDINALITY k WHERE k.value->>'id'=definition->>'key_id';
  fragment:=key_json;pointer:=pointer||'/keys/'||key_index;
 END IF;
 original_fragment:=convert_to(fragment::text,'UTF8');original_pointer:=pointer;
 pin_input:='['||archive.rev||','||archive.ord||',"'||archive.content_sha256||'","'||pointer
  ||'",{"identity":"truss-original-json-definition","sha256":"08c2ec8c520b39ded40f270be0b26812db1d240d5bac1a00339b437200a2f58d","version":"0.1"},"'
  ||encode(sha256(original_fragment),'hex')||'"]';
 definition_pin:=encode(sha256(convert_to(pin_input,'UTF8')),'hex');
 document_id:=native_type.document_id;module_id:=native_type.module;element_id:=native_type.element;
 RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_history(object_image jsonb, identity jsonb, planned_basis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE properties jsonb;property_buffer jsonb[]:=ARRAY[]::jsonb[];retained jsonb;ownership jsonb:='{"state":"rootless"}';property truss.prop_def%ROWTYPE;pin record;basis jsonb;written_revision int:=(object_image->>'rev')::int;
BEGIN
 basis:=planned_basis;
 SELECT * INTO STRICT pin FROM truss.catalog_rebind_definition('type',(object_image->>'type_id')::int,NULL,planned_basis);
 identity:=jsonb_set(identity,'{definitionPin}',to_jsonb(pin.definition_pin));
 FOR property IN SELECT * FROM jsonb_populate_recordset(NULL::truss.prop_def,basis->'prop_def') p WHERE p.type_id=(object_image->>'type_id')::int ORDER BY prop_id LOOP
  IF object_image->'props' ? property.prop_id::text THEN
   SELECT * INTO STRICT pin FROM truss.catalog_rebind_definition('property',property.type_id,property.prop_id,planned_basis);
   property_buffer:=array_append(property_buffer,jsonb_build_object('propertyId',property.prop_id::text,'definitionPin',pin.definition_pin,'value',object_image->'props'->property.prop_id::text));
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',key,'value',value) ORDER BY key COLLATE "C"),'[]'::jsonb) INTO retained FROM jsonb_each(coalesce(nullif(object_image->'retained','null'::jsonb),'{}'));
 IF (object_image->>'root_id' IS NULL) IS DISTINCT FROM (object_image->>'root_type' IS NULL) THEN
  RAISE EXCEPTION 'complete rebound root pair required' USING ERRCODE='55000';END IF;
 IF object_image->>'root_id' IS NOT NULL THEN
  SELECT * INTO STRICT pin FROM truss.catalog_rebind_definition('type',(object_image->>'root_type')::int,NULL,planned_basis);
  ownership:=jsonb_build_object('state','owned','root',jsonb_build_object(
   'id',object_image->>'root_id','typeId',object_image->>'root_type','definitionPin',pin.definition_pin,
   'owner',jsonb_build_object('documentId',pin.document_id,'moduleId',pin.module_id)));
 END IF;
 properties:=to_jsonb(property_buffer);
 RETURN jsonb_build_object('interfaceVersion','truss-history-record/0.1.0','kind','object','identity',identity,
  'recordVersion',object_image->>'ver','catalogRevision',object_image->>'rev',
  'createdAt',to_char((object_image->>'created_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'updatedAt',to_char((object_image->>'updated_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'properties',properties,'retained',retained,'ownership',ownership);
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_history_group(entity jsonb, writer xid8, version bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE transition truss.runtime_catalog_rebind_transition%ROWTYPE;request truss.catalog_registration_request%ROWTYPE;
 basis jsonb;entry jsonb;event jsonb;before_record jsonb;after_record jsonb;identity jsonb;
 history_profile text;moved_props jsonb;moved_retained jsonb;seen text[]:='{}';metadata_count int:=0;physical jsonb;
BEGIN
 SELECT * INTO STRICT transition FROM truss.runtime_catalog_rebind_transition t
  WHERE t.object_id=(entity->>'id')::bigint AND t.type_id=(entity->>'typeId')::int AND t.writer_xid=writer AND (t.after_object->>'ver')::bigint=version;
 SELECT * INTO STRICT request FROM truss.catalog_registration_request r WHERE r.registration_id=transition.registration_id;
 IF request.writer_xid IS DISTINCT FROM writer OR request.actor_oid IS DISTINCT FROM transition.actor_oid OR request.revision IS DISTINCT FROM transition.revision
  OR (transition.before_object->>'ver')::bigint+1<>version THEN RAISE EXCEPTION 'original registration-owned history transition required' USING ERRCODE='55000';END IF;
 PERFORM truss.catalog_rebind_transition_reader(transition);
 history_profile:=truss.catalog_rebind_profile(transition.journal);
 basis:=truss.catalog_all_expected_records(request.revision);
 identity:=jsonb_build_object('id',entity->>'id','typeId',entity->>'typeId','owner',jsonb_build_object('documentId',entity->>'documentId','moduleId',entity->>'moduleId'));
 before_record:=truss.runtime_object_history(transition.before_object,identity);
 after_record:=truss.catalog_rebind_history(transition.after_object,identity,basis);
 moved_props:=transition.before_object->'props';moved_retained:=coalesce(nullif(transition.before_object->'retained','null'::jsonb),'{}');
 FOR entry IN SELECT value FROM jsonb_array_elements(transition.journal) LOOP
  SELECT to_jsonb(j) INTO STRICT physical FROM truss.journal j WHERE j.xid=writer AND j.seq=(entry->>'seq')::bigint;
  IF physical IS DISTINCT FROM entry THEN RAISE EXCEPTION 'original registration journal row required' USING ERRCODE='55000';END IF;
  event:=convert_from(decode(entry->'new_value'->>'bytesBase64','base64'),'UTF8')::jsonb;
  IF event->>'historyProfile' IS DISTINCT FROM history_profile OR event->'origin'->>'databaseRole' IS DISTINCT FROM request.actor_name OR event->'origin'->'asserted' IS DISTINCT FROM convert_from(request.origin_bytes,'UTF8')::jsonb THEN
   RAISE EXCEPTION 'original registration history actor and origin required' USING ERRCODE='55000';END IF;
  IF event->>'operation'='rebind' THEN
   IF event->>'propertyId'=ANY(seen) OR NOT moved_retained ? (event->>'retainedName') OR moved_props ? (event->>'propertyId')
    OR event->>'beforeDefinitionContext' IS DISTINCT FROM before_record->'identity'->>'definitionPin'
    OR event->'retainedBefore' IS DISTINCT FROM jsonb_build_object('present',true,'value',moved_retained->(event->>'retainedName'))
    OR event->'retainedAfter' IS DISTINCT FROM '{"present":false}'::jsonb
    OR event->'propertyBefore' IS DISTINCT FROM '{"present":false}'::jsonb
    OR event->'propertyAfter' IS DISTINCT FROM event->'retainedBefore' THEN RAISE EXCEPTION 'exact original rebind presence facts required' USING ERRCODE='55000';END IF;
   PERFORM truss.runtime_history_property(transition.type_id,(event->>'propertyId')::int,request.revision,event->>'afterDefinitionPin');
   moved_props:=moved_props||jsonb_build_object(event->>'propertyId',moved_retained->(event->>'retainedName'));
   moved_retained:=moved_retained-(event->>'retainedName');seen:=array_append(seen,event->>'propertyId');
  ELSIF event->>'operation'='metadata' THEN
   metadata_count:=metadata_count+1;
   IF event->'before' IS DISTINCT FROM before_record OR event->'after' IS DISTINCT FROM after_record THEN RAISE EXCEPTION 'original complete rebind metadata witness required' USING ERRCODE='55000';END IF;
  ELSE RAISE EXCEPTION 'registration rebind-only journal required' USING ERRCODE='55000';END IF;
 END LOOP;
 IF metadata_count<>1 OR cardinality(seen)<>jsonb_array_length(transition.effects)
  OR moved_props IS DISTINCT FROM transition.after_object->'props'
  OR nullif(moved_retained,'{}'::jsonb) IS DISTINCT FROM nullif(transition.after_object->'retained','null'::jsonb) THEN
  RAISE EXCEPTION 'complete original rebind home transition required' USING ERRCODE='55000';END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_objects(request truss.catalog_registration_request, planned_basis jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE object_row truss.object%ROWTYPE;original jsonb;after_image jsonb;identity jsonb;before_record jsonb;after_record jsonb;
 owner truss.type_def%ROWTYPE;property truss.prop_def%ROWTYPE;pin record;installation truss.catalog_runtime_installation%ROWTYPE;
 observed_after jsonb;effects jsonb;effects_buffer jsonb[];events jsonb;event jsonb;event_buffer jsonb[];decorated_events jsonb[];journals jsonb;journal_buffer jsonb[];journal truss.journal%ROWTYPE;keys jsonb;group_digest text;property_count int;object_count int:=0;selected_profile text;
BEGIN
 IF request.actor_oid IS DISTINCT FROM truss.catalog_actor() OR request.actor_name IS DISTINCT FROM session_user::text
  OR request.writer_xid IS DISTINCT FROM pg_current_xact_id() OR request.registration_id IS NULL THEN
  RAISE EXCEPTION 'current original catalog registration required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 selected_profile:=CASE WHEN EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.since_rev=request.revision AND p.cardinality IN ('array','map') AND p.item ? 'descendants')
  THEN 'truss-native-catalog-rebind/0.4' WHEN EXISTS(
  SELECT 1 FROM truss.key_def k CROSS JOIN LATERAL unnest(k.prop_ids) member(prop_id)
  JOIN truss.prop_def p ON p.type_id=k.type_id AND p.prop_id=member.prop_id
  WHERE k.since_rev=request.revision AND NOT k.is_primary AND p.since_rev=request.revision)
  THEN 'truss-native-catalog-rebind/0.3' ELSE 'truss-native-catalog-rebind/0.2' END;
 FOR object_row IN SELECT o.* FROM truss.object o WHERE EXISTS(SELECT 1 FROM truss.prop_def p
  WHERE p.type_id=o.type_id AND p.since_rev=request.revision AND o.retained ? p.name) ORDER BY o.type_id,o.id FOR UPDATE LOOP
  object_count:=object_count+1;
  IF object_count>10000 OR object_row.ver=9223372036854775807 THEN RAISE EXCEPTION 'bounded catalog rebinding required' USING ERRCODE='54000';END IF;
  SELECT * INTO STRICT owner FROM truss.type_def WHERE type_id=object_row.type_id;
  PERFORM truss.runtime_module_writer(owner.document_id,owner.module);
  IF truss.runtime_object_values_readable(object_row.type_id) IS NOT TRUE THEN RAISE EXCEPTION 'current rebind interpretation reader required' USING ERRCODE='42501';END IF;
  PERFORM truss.runtime_history_ownership(jsonb_build_object(
   'identity',jsonb_build_object('id',object_row.id::text,'typeId',object_row.type_id::text),
   'catalogRevision',object_row.rev,'ownership',truss.runtime_object_ownership_at(to_jsonb(object_row))));
  original:=to_jsonb(object_row);effects_buffer:=ARRAY[]::jsonb[];event_buffer:=ARRAY[]::jsonb[];decorated_events:=ARRAY[]::jsonb[];journal_buffer:=ARRAY[]::jsonb[];property_count:=0;
  SELECT definition_pin INTO STRICT pin FROM truss.catalog_rebind_definition('type',object_row.type_id,NULL,planned_basis);
  identity:=jsonb_build_object('id',object_row.id::text,'typeId',object_row.type_id::text,
   'definitionPin',pin.definition_pin,'owner',jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module));
  before_record:=truss.runtime_object_history(original,identity);
  FOR property IN SELECT * FROM truss.prop_def p WHERE p.type_id=object_row.type_id AND p.since_rev=request.revision
   AND object_row.retained ? p.name ORDER BY p.prop_id LOOP
   property_count:=property_count+1;
   IF property_count>127 OR property.nullability NOT IN ('required','absent-allowed') OR object_row.props ? property.prop_id::text
    OR EXISTS(SELECT 1 FROM truss.key_def k WHERE k.type_id=property.type_id AND property.prop_id=ANY(k.prop_ids)
     AND (k.since_rev IS DISTINCT FROM request.revision OR k.is_primary IS DISTINCT FROM false
      OR property.nullability IS DISTINCT FROM 'required' OR property.cardinality IS DISTINCT FROM 'one'
      OR property.scalar_type NOT IN ('string','integer','decimal','boolean','binary')))
    OR truss.valid_property_definition(property) IS NOT TRUE OR truss.valid_property_value(object_row.retained->property.name,property) IS NOT TRUE THEN
    RAISE EXCEPTION 'valid absent catalog rebind destination required' USING ERRCODE='22023';END IF;
   SELECT definition_pin INTO STRICT pin FROM truss.catalog_rebind_definition('property',property.type_id,property.prop_id,planned_basis);
   effects_buffer:=array_append(effects_buffer,jsonb_build_object('propertyId',property.prop_id::text,'originalName',property.name,
    'definitionPin',pin.definition_pin,'value',object_row.retained->property.name));
   event_buffer:=array_append(event_buffer,jsonb_build_object('operation','rebind','propertyId',property.prop_id::text,
    'retainedName',property.name,'beforeDefinitionContext',before_record->'identity'->>'definitionPin','afterDefinitionPin',pin.definition_pin,
    'retainedBefore',jsonb_build_object('present',true,'value',object_row.retained->property.name),
    'retainedAfter',jsonb_build_object('present',false),'propertyBefore',jsonb_build_object('present',false),
    'propertyAfter',jsonb_build_object('present',true,'value',object_row.retained->property.name)));
   object_row.props:=object_row.props||jsonb_build_object(property.prop_id::text,object_row.retained->property.name);
   object_row.retained:=object_row.retained-property.name;
  END LOOP;
  IF octet_length(convert_to(jsonb_build_object('props',object_row.props,'retained',object_row.retained)::text,'UTF8'))>1048576 THEN
   RAISE EXCEPTION 'bounded rebound object values required' USING ERRCODE='54000';END IF;
  object_row.retained:=nullif(object_row.retained,'{}'::jsonb);object_row.ver:=object_row.ver+1;
  object_row.rev:=request.revision;object_row.updated_at:=clock_timestamp();after_image:=to_jsonb(object_row);
  after_record:=truss.catalog_rebind_history(after_image,identity,planned_basis);
  event_buffer:=array_append(event_buffer,jsonb_build_object('operation','metadata','before',before_record,'after',after_record));
  FOR event_index IN 1..cardinality(event_buffer) LOOP
   event:=event_buffer[event_index]||jsonb_build_object('interfaceVersion','truss-history-event/0.2.0-proposal',
    'historyProfile',selected_profile,'sourceEpoch',installation.source_epoch::text,
    'xid',request.writer_xid::text,'seq',nextval('truss.journal_seq')::text,
    'identity',identity,'eventVersion',object_row.ver::text,'eventCatalogRevision',request.revision::text,
    'origin',jsonb_build_object('asserted',convert_from(request.origin_bytes,'UTF8')::jsonb,'databaseRole',session_user::text));
   decorated_events:=array_append(decorated_events,event);
  END LOOP;
  events:=to_jsonb(decorated_events);effects:=to_jsonb(effects_buffer);
  group_digest:=encode(sha256(convert_to(events::text,'UTF8')),'hex');
  FOR event IN SELECT value FROM jsonb_array_elements(events) LOOP
   event:=event||jsonb_build_object('mutationGroup',jsonb_build_object('profile','truss-history-group/0.1.0',
    'eventCount',jsonb_array_length(events)::text,'orderedEventDigest',group_digest));
   journal.seq:=(event->>'seq')::bigint;journal.at:=clock_timestamp();journal.xid:=request.writer_xid;
   journal.entity_kind:='o';journal.entity_id:=object_row.id;journal.entity_type:=object_row.type_id;journal.ver:=object_row.ver;
   journal.op:=event->>'operation';journal.prop_id:=(event->>'propertyId')::int;journal.old_value:=NULL;
   journal.new_value:=truss.runtime_exact_wrapper('event',convert_to(event::text,'UTF8'));journal.rev:=request.revision;
   journal.origin:=truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8'));
   INSERT INTO truss.journal SELECT (jsonb_populate_record(NULL::truss.journal,to_jsonb(journal))).*;
   journal_buffer:=array_append(journal_buffer,to_jsonb(journal));
  END LOOP;
  journals:=to_jsonb(journal_buffer);
  SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY k.key_num),'[]'::jsonb) INTO keys FROM truss.object_key_bucket k
   WHERE k.object_id=object_row.id AND k.type_id=object_row.type_id;
  UPDATE truss.object o SET props=object_row.props,retained=object_row.retained,ver=object_row.ver,rev=object_row.rev,updated_at=object_row.updated_at
   WHERE id=object_row.id AND type_id=object_row.type_id RETURNING to_jsonb(o) INTO observed_after;
  IF NOT FOUND OR observed_after IS DISTINCT FROM after_image THEN RAISE EXCEPTION 'exact applied catalog rebind image required' USING ERRCODE='55000';END IF;
  INSERT INTO truss.runtime_catalog_rebind_transition(registration_id,writer_xid,actor_oid,revision,object_id,type_id,before_object,after_object,after_keys,journal,effects)
   VALUES(request.registration_id,request.writer_xid,request.actor_oid,request.revision,object_row.id,object_row.type_id,original,after_image,keys,journals,effects);
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_profile(journal jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE entry jsonb;event jsonb;original bytea;selected text;candidate text;
BEGIN
 IF jsonb_typeof(journal) IS DISTINCT FROM 'array' OR jsonb_array_length(journal) NOT BETWEEN 2 AND 128 THEN
  RAISE EXCEPTION 'bounded original rebind group required' USING ERRCODE='55000';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(journal) LOOP
  original:=decode(entry->'new_value'->>'bytesBase64','base64');
  IF entry->'new_value' IS DISTINCT FROM truss.runtime_exact_wrapper('event',original)
   OR (convert_from(original,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
   RAISE EXCEPTION 'original rebind profile bytes required' USING ERRCODE='55000';END IF;
  event:=convert_from(original,'UTF8')::jsonb;candidate:=event->>'historyProfile';
  IF event->>'interfaceVersion' IS DISTINCT FROM 'truss-history-event/0.2.0-proposal'
   OR (candidate IN ('truss-native-catalog-rebind/0.1','truss-native-catalog-rebind/0.2','truss-native-catalog-rebind/0.3','truss-native-catalog-rebind/0.4')) IS NOT TRUE
   OR selected IS NOT NULL AND selected IS DISTINCT FROM candidate THEN
   RAISE EXCEPTION 'one supported original rebind profile required' USING ERRCODE='55000';END IF;
  selected:=candidate;
 END LOOP;
 RETURN selected;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_report_reader(selected_registration uuid, planned_basis jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE transition truss.runtime_catalog_rebind_transition%ROWTYPE;
BEGIN
 PERFORM truss.catalog_key_backfill_report_reader(selected_registration,planned_basis);
 FOR transition IN SELECT * FROM truss.runtime_catalog_rebind_transition WHERE registration_id=selected_registration LOOP
  PERFORM truss.catalog_rebind_transition_reader(transition,planned_basis);
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_transition_reader(transition truss.runtime_catalog_rebind_transition, planned_basis jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE owner truss.type_def%ROWTYPE;property truss.prop_def%ROWTYPE;basis jsonb;property_id text;image jsonb;
BEGIN
  basis:=coalesce(planned_basis,truss.catalog_all_expected_records(transition.revision));
  SELECT * INTO STRICT owner FROM jsonb_populate_recordset(NULL::truss.type_def,basis->'type_def') t WHERE t.type_id=transition.type_id;
  IF truss.runtime_can_read(owner.document_id,owner.module) IS NOT TRUE THEN RAISE EXCEPTION 'current original rebind owner reader required' USING ERRCODE='42501';END IF;
  FOR image IN SELECT value FROM jsonb_array_elements(jsonb_build_array(transition.before_object,transition.after_object)) LOOP
   PERFORM truss.runtime_history_ownership(jsonb_build_object(
    'identity',jsonb_build_object('id',image->>'id','typeId',image->>'type_id'),
    'catalogRevision',image->'rev','ownership',truss.runtime_object_ownership_at(image)));
  END LOOP;
  FOR property_id IN SELECT jsonb_object_keys(transition.before_object->'props') LOOP
   PERFORM truss.runtime_history_property(transition.type_id,property_id::int,(transition.before_object->>'rev')::int,
    (SELECT definition_pin FROM truss.runtime_owned_definition_metadata('property',transition.type_id,property_id::int,(transition.before_object->>'rev')::int)));
  END LOOP;
  FOR property_id IN SELECT jsonb_object_keys(transition.after_object->'props') LOOP
   SELECT * INTO STRICT property FROM jsonb_populate_recordset(NULL::truss.prop_def,basis->'prop_def') p WHERE p.type_id=transition.type_id AND p.prop_id=property_id::int;
   IF truss.runtime_can_read(owner.document_id,property.declaration_module) IS NOT TRUE
    OR property.cardinality IN ('array','map') AND truss.runtime_item_chain_readable(property.item) IS NOT TRUE THEN
    RAISE EXCEPTION 'current original rebind property/item reader required' USING ERRCODE='42501';END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_rebind_violations(planned_basis jsonb, revision integer)
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE property truss.prop_def%ROWTYPE;owner truss.type_def%ROWTYPE;object_row truss.object%ROWTYPE;affected bigint;missing bigint;violations jsonb;violation_buffer jsonb[]:=ARRAY[]::jsonb[];owner_index jsonb;
BEGIN
 SELECT coalesce(jsonb_object_agg(t.value->>'type_id',t.value),'{}'::jsonb) INTO owner_index FROM jsonb_array_elements(planned_basis->'type_def') t;
 FOR property IN SELECT * FROM jsonb_populate_recordset(NULL::truss.prop_def,planned_basis->'prop_def') p WHERE p.since_rev=revision LOOP
  SELECT * INTO STRICT owner FROM jsonb_populate_record(NULL::truss.type_def,owner_index->property.type_id::text) t WHERE t.type_id=property.type_id;
  IF NOT EXISTS(SELECT 1 FROM truss.type_def WHERE type_id=property.type_id) THEN CONTINUE;END IF;
  IF truss.runtime_can_read(owner.document_id,owner.module) IS NOT TRUE
   OR truss.runtime_can_read(owner.document_id,property.declaration_module) IS NOT TRUE
   OR property.cardinality IN ('array','map') AND truss.runtime_item_chain_readable(property.item) IS NOT TRUE THEN
   RAISE EXCEPTION 'original candidate owner/property/item readers required' USING ERRCODE='42501';END IF;
  IF truss.valid_property_definition(property) IS NOT TRUE THEN RAISE EXCEPTION 'supported planned rebind property required' USING ERRCODE='0A000';END IF;
  FOR object_row IN SELECT o.* FROM truss.object o WHERE o.type_id=property.type_id
   AND (o.root_id IS NOT NULL OR o.root_type IS NOT NULL)
   AND (property.nullability='required' OR coalesce(o.retained ? property.name,false)) LOOP
  PERFORM truss.runtime_history_ownership(jsonb_build_object(
   'identity',jsonb_build_object('id',object_row.id::text,'typeId',object_row.type_id::text),
   'catalogRevision',object_row.rev,'ownership',truss.runtime_object_ownership_at(to_jsonb(object_row))));
  END LOOP;
  SELECT count(*) INTO missing FROM truss.object o WHERE o.type_id=property.type_id AND property.nullability='required'
   AND (coalesce(o.retained ? property.name,false) IS NOT TRUE OR o.retained->property.name='{"kind":"null"}'::jsonb);
  IF missing>0 THEN
   violation_buffer:=array_append(violation_buffer,jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module,
    'recordId',owner.element,'fieldModuleId',property.declaration_module,'fieldId',property.element,
    'rule','property.required','affectedObjectCount',missing::text));
  END IF;
  SELECT count(*) INTO affected FROM truss.object o WHERE o.type_id=property.type_id AND coalesce(o.retained ? property.name,false)
   AND NOT (property.nullability='required' AND o.retained->property.name='{"kind":"null"}'::jsonb)
   AND (property.nullability NOT IN ('required','absent-allowed') OR o.props ? property.prop_id::text
    OR EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::truss.key_def,planned_basis->'key_def') k WHERE k.type_id=property.type_id AND property.prop_id=ANY(k.prop_ids)
     AND (k.since_rev IS DISTINCT FROM revision OR k.is_primary IS DISTINCT FROM false
      OR property.nullability IS DISTINCT FROM 'required' OR property.cardinality IS DISTINCT FROM 'one'
      OR property.scalar_type NOT IN ('string','integer','decimal','boolean','binary')))
    OR truss.valid_property_value(o.retained->property.name,property) IS NOT TRUE);
  IF truss.runtime_can_read(owner.document_id,owner.module) IS NOT TRUE
   OR truss.runtime_can_read(owner.document_id,property.declaration_module) IS NOT TRUE
   OR property.cardinality IN ('array','map') AND truss.runtime_item_chain_readable(property.item) IS NOT TRUE THEN
   RAISE EXCEPTION 'original candidate owner/property/item readers required' USING ERRCODE='42501';END IF;
  IF affected>0 THEN
   violation_buffer:=array_append(violation_buffer,jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module,
    'recordId',owner.element,'fieldModuleId',property.declaration_module,'fieldId',property.element,
    'rule','property.rebind_value','affectedObjectCount',affected::text));
  END IF;
 END LOOP;
 FOR property IN SELECT * FROM jsonb_populate_recordset(NULL::truss.prop_def,planned_basis->'prop_def') p WHERE p.since_rev=revision AND EXISTS(SELECT 1 FROM truss.type_def t WHERE t.type_id=p.type_id) LOOP
  SELECT * INTO STRICT owner FROM jsonb_populate_record(NULL::truss.type_def,owner_index->property.type_id::text) t WHERE t.type_id=property.type_id;
  IF truss.runtime_can_read(owner.document_id,owner.module) IS NOT TRUE
   OR truss.runtime_can_read(owner.document_id,property.declaration_module) IS NOT TRUE
   OR property.cardinality IN ('array','map') AND truss.runtime_item_chain_readable(property.item) IS NOT TRUE THEN
   RAISE EXCEPTION 'original candidate owner/property/item readers required' USING ERRCODE='42501';END IF;
  FOR object_row IN SELECT o.* FROM truss.object o WHERE o.type_id=property.type_id
   AND (o.root_id IS NOT NULL OR o.root_type IS NOT NULL)
   AND (property.nullability='required' OR coalesce(o.retained ? property.name,false)) LOOP
  PERFORM truss.runtime_history_ownership(jsonb_build_object(
   'identity',jsonb_build_object('id',object_row.id::text,'typeId',object_row.type_id::text),
   'catalogRevision',object_row.rev,'ownership',truss.runtime_object_ownership_at(to_jsonb(object_row))));
  END LOOP;
 END LOOP;
 violations:=to_jsonb(violation_buffer);
 IF violations='[]'::jsonb THEN RETURN NULL;END IF;
 RETURN convert_to(violations::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_report(selected_revision integer)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE original bytea;
BEGIN
 PERFORM truss.catalog_actor();
 PERFORM truss.catalog_rebind_report_reader((SELECT registration_id FROM truss.catalog_registration_request WHERE revision=selected_revision));
 SELECT report_bytes INTO STRICT original FROM truss.catalog_acceptance_report WHERE rev=selected_revision;
 PERFORM truss.catalog_actor();
 PERFORM truss.catalog_rebind_report_reader((SELECT registration_id FROM truss.catalog_registration_request WHERE revision=selected_revision));
 RETURN original;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_revision(expected_release text, expected_digest text, selected_document text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;revision int;archive truss.schema_doc%ROWTYPE;module jsonb;
BEGIN
 PERFORM truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected runtime required' USING ERRCODE='0A000';END IF;
 -- No share lock: this is a cache key, not admission of a write.
 SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 IF revision<1 THEN RAISE EXCEPTION 'accepted catalog required' USING ERRCODE='0A000';END IF;
 IF selected_document IS NULL THEN RETURN convert_to(jsonb_build_object('catalogRevision',revision::text)::text,'UTF8');END IF;
 IF octet_length(selected_document) NOT BETWEEN 1 AND 4096 THEN RAISE EXCEPTION 'bounded document selection required' USING ERRCODE='22023';END IF;
 SELECT * INTO archive FROM truss.schema_doc WHERE rev<=revision AND doc_id=selected_document ORDER BY rev DESC LIMIT 1;
 IF NOT FOUND OR jsonb_array_length(archive.document::jsonb->'modules')=0 THEN RAISE EXCEPTION 'authorized document required' USING ERRCODE='42501';END IF;
 FOR module IN SELECT value FROM jsonb_array_elements(archive.document::jsonb->'modules') LOOP
  IF NOT truss.runtime_can_read(selected_document,module->>'id') THEN RAISE EXCEPTION 'authorized document required' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN convert_to(jsonb_build_object('catalogRevision',revision::text,'documentId',selected_document,'documentRevision',archive.doc_revision,'sourceCatalogRevision',archive.rev::text)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_revision_plan(prior jsonb, fresh jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET bytea_output TO 'hex'
AS $function$
DECLARE result jsonb:=prior;types jsonb:=coalesce(prior->'type_def','[]');properties jsonb:=coalesce(prior->'prop_def','[]');
 keys jsonb:=coalesce(prior->'key_def','[]');relations jsonb:=coalesce(prior->'rel_def','[]');
 lineages jsonb:=coalesce(prior->'relationship_lineage','[]');endpoints jsonb:=coalesce(prior->'rel_endpoint','[]');
 changes jsonb:=coalesce(prior->'schema_change','[]');type_map jsonb:='{}';property_map jsonb:='{}';relationship_map jsonb:='{}';
 prior_type_identity jsonb;prior_property_identity jsonb;prior_relation_identity jsonb;
 prior_type_id jsonb;prior_property_id jsonb;prior_property_name jsonb;prior_key_identity jsonb;
 prior_key_property jsonb;prior_key_max jsonb;prior_lineage_id jsonb;prior_endpoint_id jsonb;prior_revision_id jsonb;
 current_property_id jsonb;source_index jsonb;fresh_key_number jsonb;fresh_document_ids jsonb;fresh_type_identities jsonb;fresh_relation_identities jsonb;
 next_types jsonb[]:=ARRAY[]::jsonb[];next_properties jsonb[]:=ARRAY[]::jsonb[];next_relations jsonb[]:=ARRAY[]::jsonb[];
 next_keys jsonb[]:=ARRAY[]::jsonb[];next_lineages jsonb[]:=ARRAY[]::jsonb[];next_endpoints jsonb[]:=ARRAY[]::jsonb[];next_changes jsonb[]:=ARRAY[]::jsonb[];
 removed_type_ids int[]:=ARRAY[]::int[];removed_property_ids int[]:=ARRAY[]::int[];removed_relation_ids int[]:=ARRAY[]::int[];
 row jsonb;old jsonb;candidate jsonb;old_source jsonb;new_source jsonb;old_document jsonb;new_document jsonb;component jsonb;remapped jsonb;
 tightening boolean;facet_map jsonb;compact_insertions boolean;
 assigned int;type_next int;property_next int;relationship_next int;key_next int;sequence int:=0;revision int;
BEGIN
 -- Original archives plus normalized rows already preserve newly inserted definitions.
 -- Retained-row changes still keep their complete before/after history.
 compact_insertions:=NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fresh->'schema_doc') d
  WHERE d.value->'validation'->>'storageFormat' IS DISTINCT FROM 'truss-catalog-source/2');
 -- On the empty genesis there are no old identities to remap or evolve.
 -- Materialize each normalized source row and insertion event once.
 IF prior->'type_def'='[]'::jsonb AND prior->'prop_def'='[]'::jsonb AND prior->'key_def'='[]'::jsonb
  AND prior->'rel_def'='[]'::jsonb AND prior->'schema_doc'='[]'::jsonb
  AND prior->'relationship_lineage'='[]'::jsonb AND prior->'rel_endpoint'='[]'::jsonb
  AND prior->'schema_change'='[]'::jsonb AND jsonb_array_length(prior->'schema_rev')=1
  AND prior->'schema_rev'->0=fresh->'schema_rev'->0
  AND jsonb_array_length(fresh->'schema_rev')=2 AND fresh->'schema_rev'->1->>'rev'='1' THEN
  IF compact_insertions THEN RETURN fresh||jsonb_build_object('schema_change','[]'::jsonb);END IF;
  WITH events AS (
   SELECT 0 family,r.ordinality ordinal,'type' kind,(r.value->>'type_id')::int def_id,
    to_jsonb(jsonb_populate_record(NULL::truss.type_def,r.value)) after FROM jsonb_array_elements(fresh->'type_def') WITH ORDINALITY r
   UNION ALL
   SELECT 1,r.ordinality,'prop',(r.value->>'prop_id')::int,to_jsonb(jsonb_populate_record(NULL::truss.prop_def,r.value))
    FROM jsonb_array_elements(fresh->'prop_def') WITH ORDINALITY r
   UNION ALL
   SELECT 2,r.ordinality,'rel',(r.value->>'rel_type_id')::int,to_jsonb(jsonb_populate_record(NULL::truss.rel_def,r.value))
    FROM jsonb_array_elements(fresh->'rel_def') WITH ORDINALITY r),
  numbered AS (SELECT *,row_number() OVER(ORDER BY family,ordinal) seq FROM events)
  SELECT coalesce(jsonb_agg(jsonb_build_object('rev',1,'seq',seq,'kind',kind,'def_id',def_id,'before',NULL,'after',after) ORDER BY seq),'[]'::jsonb)
   INTO changes FROM numbered;
  RETURN fresh||jsonb_build_object('schema_change',changes);
 END IF;
 SELECT coalesce(max((v.value->>'type_id')::int),0) INTO type_next FROM jsonb_array_elements(types) v;
 SELECT coalesce(max((v.value->>'prop_id')::int),0) INTO property_next FROM jsonb_array_elements(properties) v;
 SELECT coalesce(max((v.value->>'rel_type_id')::int),0) INTO relationship_next FROM jsonb_array_elements(relations) v;
 SELECT coalesce(jsonb_object_agg(jsonb_build_array(v.value->>'document_id',v.value->>'module',v.value->>'element')::text,v.value),'{}'::jsonb),
        coalesce(jsonb_object_agg(v.value->>'type_id',v.value),'{}'::jsonb)
  INTO prior_type_identity,prior_type_id FROM jsonb_array_elements(types) v;
 WITH prop_rows AS (SELECT value FROM jsonb_array_elements(properties)),names AS (
  SELECT jsonb_build_array(value->>'type_id',value->>'name')::text name_key,jsonb_agg(value->>'prop_id') prop_ids FROM prop_rows GROUP BY 1
 ) SELECT (SELECT coalesce(jsonb_object_agg(jsonb_build_array(value->>'type_id',value->>'declaration_module',value->>'element')::text,value),'{}'::jsonb) FROM prop_rows),
          (SELECT coalesce(jsonb_object_agg(value->>'prop_id',value),'{}'::jsonb) FROM prop_rows),
          coalesce((SELECT jsonb_object_agg(name_key,prop_ids) FROM names),'{}'::jsonb)
  INTO prior_property_identity,prior_property_id,prior_property_name;
 SELECT coalesce(jsonb_object_agg(jsonb_build_array(v.value->>'document_id',v.value->>'module',v.value->>'rel_id')::text,v.value),'{}'::jsonb)
  INTO prior_relation_identity FROM jsonb_array_elements(relations) v;
 SELECT coalesce(jsonb_object_agg(jsonb_build_array(v.value->>'type_id',v.value->>'key_id')::text,v.value),'{}'::jsonb),
        coalesce(jsonb_object_agg(jsonb_build_array(v.value->>'type_id',p.value#>>'{}')::text,'true'::jsonb),'{}'::jsonb),
        coalesce(jsonb_object_agg(v.value->>'type_id',to_jsonb(v.max_num)),'{}'::jsonb)
  INTO prior_key_identity,prior_key_property,prior_key_max
  FROM (SELECT k.value,max((k.value->>'key_num')::int) OVER(PARTITION BY k.value->>'type_id') max_num
         FROM jsonb_array_elements(keys) k) v
  LEFT JOIN LATERAL jsonb_array_elements(v.value->'prop_ids') p ON true;
 SELECT coalesce(jsonb_object_agg(v.value->>'rel_type_id','true'::jsonb),'{}'::jsonb)
  INTO prior_lineage_id FROM jsonb_array_elements(lineages) v;
 SELECT coalesce(jsonb_object_agg(jsonb_build_array(v.value->>'rel_type_id',v.value->>'source_type',v.value->>'target_type')::text,'true'::jsonb),'{}'::jsonb)
  INTO prior_endpoint_id FROM jsonb_array_elements(endpoints) v;
 SELECT coalesce(jsonb_object_agg(v.value->>'rev',v.value),'{}'::jsonb)
  INTO prior_revision_id FROM jsonb_array_elements(coalesce(prior->'schema_rev','[]'::jsonb)) v;
 -- Index immutable source declarations once for the whole revision. Public catalog preparation
 -- has already validated unique document/module/declaration identities.
 WITH documents AS (
  SELECT d.value->>'rev' rev,d.value->>'ord' ord,d.value->>'doc_id' doc_id,(d.value->>'document')::jsonb document
   FROM jsonb_array_elements(coalesce(prior->'schema_doc','[]'::jsonb)) d
  UNION ALL
  SELECT d.value->>'rev',d.value->>'ord',d.value->>'doc_id',(d.value->>'document')::jsonb
   FROM jsonb_array_elements(coalesce(fresh->'schema_doc','[]'::jsonb)) d
 ),source_rows AS (
  SELECT d.rev,d.ord,d.doc_id,m.value->>'id' module,'element' kind,e.value->>'id' authored_id,e.value source
   FROM documents d CROSS JOIN LATERAL jsonb_array_elements(d.document->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(coalesce(m.value->'elements','[]'::jsonb)) e
  UNION ALL
  SELECT d.rev,d.ord,d.doc_id,m.value->>'id','relationship',e.value->>'id',e.value
   FROM documents d CROSS JOIN LATERAL jsonb_array_elements(d.document->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(coalesce(m.value->'relationships','[]'::jsonb)) e
 ) SELECT coalesce(jsonb_object_agg(jsonb_build_array(rev,ord,doc_id,module,kind,authored_id)::text,source),'{}'::jsonb)
   INTO source_index FROM source_rows;
 -- Resolve every fresh identity and allocate new IDs in input order before validation. Loops below
 -- still perform each semantic decision and append history in the original type/property/relation order.
 WITH fresh_rows AS (
  SELECT f.value,f.ordinality,
   jsonb_build_array(f.value->>'document_id',f.value->>'module',f.value->>'element')::text identity_key
   FROM jsonb_array_elements(fresh->'type_def') WITH ORDINALITY f
 ),matched AS (
  SELECT f.*,p.value->>'type_id' existing_id FROM fresh_rows f LEFT JOIN jsonb_each(prior_type_identity) p ON p.key=f.identity_key
 ),assigned AS (
  SELECT *,CASE WHEN existing_id IS NULL THEN type_next+sum((existing_id IS NULL)::int) OVER(ORDER BY ordinality)
   ELSE existing_id::int END assigned_id FROM matched
 ) SELECT coalesce(jsonb_object_agg(value->>'type_id',to_jsonb(assigned_id)),'{}'::jsonb)
   INTO type_map FROM assigned;
 WITH fresh_rows AS (
  SELECT f.value,f.ordinality,(type_map->>(f.value->>'type_id'))::int assigned_type,
   jsonb_build_array(type_map->>(f.value->>'type_id'),f.value->>'declaration_module',f.value->>'element')::text identity_key
   FROM jsonb_array_elements(fresh->'prop_def') WITH ORDINALITY f
 ),matched AS (
  SELECT f.*,p.value->>'prop_id' existing_id,p.value existing_row FROM fresh_rows f LEFT JOIN jsonb_each(prior_property_identity) p ON p.key=f.identity_key
 ),assigned AS (
  SELECT *,CASE WHEN existing_id IS NULL THEN property_next+sum((existing_id IS NULL)::int) OVER(ORDER BY ordinality)
   ELSE existing_id::int END assigned_id FROM matched
 ) SELECT coalesce(jsonb_object_agg(value->>'prop_id',to_jsonb(assigned_id)),'{}'::jsonb),
          coalesce(jsonb_object_agg(jsonb_build_array(assigned_type::text,assigned_id::text)::text,
           value||jsonb_build_object('type_id',assigned_type,'prop_id',assigned_id,
   'since_rev',coalesce(existing_row->'since_rev',value->'since_rev'),'doc_ord',coalesce(existing_row->'doc_ord',value->'doc_ord'))),'{}'::jsonb)
   INTO property_map,current_property_id FROM assigned;
 WITH fresh_rows AS (
  SELECT f.value,f.ordinality,jsonb_build_array(f.value->>'document_id',f.value->>'module',f.value->>'rel_id')::text identity_key
   FROM jsonb_array_elements(fresh->'rel_def') WITH ORDINALITY f
 ),matched AS (
  SELECT f.*,p.value->>'rel_type_id' existing_id FROM fresh_rows f LEFT JOIN jsonb_each(prior_relation_identity) p ON p.key=f.identity_key
 ),assigned AS (
  SELECT *,CASE WHEN existing_id IS NULL THEN relationship_next+sum((existing_id IS NULL)::int) OVER(ORDER BY ordinality)
   ELSE existing_id::int END assigned_id FROM matched
 ) SELECT coalesce(jsonb_object_agg(value->>'rel_type_id',to_jsonb(assigned_id)),'{}'::jsonb)
   INTO relationship_map FROM assigned;
 WITH fresh_rows AS (
  SELECT f.value,f.ordinality,(type_map->>(f.value->>'type_id'))::int assigned_type,
   jsonb_build_array(type_map->>(f.value->>'type_id'),f.value->>'key_id')::text identity_key
   FROM jsonb_array_elements(fresh->'key_def') WITH ORDINALITY f
 ),matched AS (
  SELECT f.*,p.value->>'key_num' existing_num,coalesce((prior_key_max->>f.assigned_type::text)::int,0) max_num
   FROM fresh_rows f LEFT JOIN jsonb_each(prior_key_identity) p ON p.key=f.identity_key
 ),assigned AS (
  SELECT *,CASE WHEN existing_num IS NOT NULL THEN existing_num::int
   WHEN prior_type_id ? assigned_type::text THEN max_num+sum((existing_num IS NULL)::int) OVER(PARTITION BY assigned_type ORDER BY ordinality)
   ELSE (value->>'key_num')::int END assigned_num FROM matched
 ) SELECT coalesce(jsonb_object_agg(identity_key,to_jsonb(assigned_num)),'{}'::jsonb)
   INTO fresh_key_number FROM assigned;
 SELECT coalesce(jsonb_object_agg(d.value->>'doc_id','true'::jsonb),'{}'::jsonb) INTO fresh_document_ids
  FROM jsonb_array_elements(coalesce(fresh->'schema_doc','[]'::jsonb)) d;
 SELECT coalesce(jsonb_object_agg(identity_key,'true'::jsonb),'{}'::jsonb) INTO fresh_type_identities
  FROM (SELECT jsonb_build_array(v.value->>'document_id',v.value->>'module',v.value->>'element')::text identity_key
    FROM jsonb_array_elements(fresh->'type_def') v) q;
 SELECT coalesce(jsonb_object_agg(identity_key,'true'::jsonb),'{}'::jsonb) INTO fresh_relation_identities
  FROM (SELECT jsonb_build_array(v.value->>'document_id',v.value->>'module',v.value->>'rel_id')::text identity_key
    FROM jsonb_array_elements(fresh->'rel_def') v) q;
 SELECT max((v.value->>'rev')::int) INTO STRICT revision FROM jsonb_array_elements(fresh->'schema_rev') v;
 -- A submitted document cannot implicitly retire an omitted declaration.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(types) p WHERE fresh_document_ids ? (p.value->>'document_id')
  AND NOT fresh_type_identities ? jsonb_build_array(p.value->>'document_id',p.value->>'module',p.value->>'element')::text) THEN
  RAISE EXCEPTION 'record retirement requires explicit support' USING ERRCODE='0A000';END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(fresh->'type_def') LOOP
  assigned:=(type_map->>(row->>'type_id'))::int;
  old:=prior_type_identity->jsonb_build_array(row->>'document_id',row->>'module',row->>'element')::text;
  candidate:=row||jsonb_build_object('type_id',assigned);
  IF old IS NOT NULL THEN
   old_source:=source_index->jsonb_build_array(old->>'definition_rev',old->>'definition_doc_ord',old->>'definition_document_id',old->>'module','element',old->>'element')::text;
   new_source:=source_index->jsonb_build_array(row->>'definition_rev',row->>'definition_doc_ord',row->>'definition_document_id',row->>'module','element',row->>'element')::text;
   IF old_source IS NULL OR new_source IS NULL THEN RAISE NO_DATA_FOUND;END IF;
   IF old_source=new_source THEN CONTINUE;END IF;
   SELECT value INTO old_document FROM jsonb_array_elements(prior->'schema_doc')
    WHERE value->>'rev'=old->>'definition_rev' AND value->>'ord'=old->>'definition_doc_ord'
     AND value->>'doc_id'=old->>'definition_document_id';
   SELECT value INTO new_document FROM jsonb_array_elements(fresh->'schema_doc')
    WHERE value->>'rev'=row->>'definition_rev' AND value->>'ord'=row->>'definition_doc_ord'
     AND value->>'doc_id'=row->>'definition_document_id';
   IF (old_source-ARRAY['members','name','keys'] IS DISTINCT FROM new_source-ARRAY['members','name','keys']
       AND NOT truss.catalog_ddd_optional_record_addition(old_document,new_document,row->>'module',old_source,new_source))
    OR EXISTS(SELECT value FROM jsonb_array_elements(coalesce(old_source->'keys','[]')) EXCEPT
              SELECT value FROM jsonb_array_elements(coalesce(new_source->'keys','[]')))
    OR EXISTS(SELECT value FROM jsonb_array_elements(old_source->'members') EXCEPT ALL
              SELECT value FROM jsonb_array_elements(new_source->'members')) THEN
    RAISE EXCEPTION 'existing record keys, meaning and retained members require explicit evolution support' USING ERRCODE='0A000';END IF;
   candidate:=candidate||jsonb_build_object('since_rev',old->'since_rev','doc_ord',old->'doc_ord');
   removed_type_ids[cardinality(removed_type_ids)+1]:=assigned;
  END IF;
  next_types[cardinality(next_types)+1]:=candidate;sequence:=sequence+1;
  IF old IS NOT NULL OR NOT compact_insertions THEN
  next_changes[cardinality(next_changes)+1]:=jsonb_build_object('rev',revision,'seq',sequence,'kind','type','def_id',assigned,'before',CASE WHEN old IS NULL THEN 'null'::jsonb ELSE to_jsonb(jsonb_populate_record(NULL::truss.type_def,old)) END,'after',to_jsonb(jsonb_populate_record(NULL::truss.type_def,candidate)));
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY family,ordinal),'[]'::jsonb) INTO types FROM (
  SELECT v.value,0 family,v.ordinality ordinal FROM jsonb_array_elements(coalesce(prior->'type_def','[]'::jsonb)) WITH ORDINALITY v
   LEFT JOIN (SELECT DISTINCT id FROM unnest(removed_type_ids) AS removed(id)) removed ON removed.id=(v.value->>'type_id')::int
   WHERE removed.id IS NULL
  UNION ALL SELECT n.value,1,n.ordinality FROM unnest(next_types) WITH ORDINALITY n(value,ordinality)) merged;
 FOR row IN SELECT value FROM jsonb_array_elements(fresh->'prop_def') LOOP
  assigned:=(type_map->> (row->>'type_id'))::int;
  old:=prior_property_identity->jsonb_build_array(assigned::text,row->>'declaration_module',row->>'element')::text;
  IF old IS NULL THEN
   IF prior_type_id ? assigned::text AND row->>'nullability' NOT IN ('required','absent-allowed') THEN
    RAISE EXCEPTION 'supported new field nullability required' USING ERRCODE='0A000';END IF;
  END IF;
  candidate:=row||jsonb_build_object('type_id',assigned,'prop_id',(property_map->> (row->>'prop_id'))::int);
  IF coalesce(prior_property_name ? jsonb_build_array(assigned::text,candidate->>'name')::text,false)
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(prior_property_name->jsonb_build_array(assigned::text,candidate->>'name')::text) old_name
    WHERE old_name.value#>>'{}' IS DISTINCT FROM candidate->>'prop_id') THEN
   RAISE EXCEPTION 'field name occupied in prior catalog' USING ERRCODE='0A000';END IF;
  IF old IS NOT NULL THEN
   IF old->>'cardinality' IN ('array','map') THEN
    IF truss.catalog_item_meaning(old->'item') IS DISTINCT FROM truss.catalog_item_meaning(candidate->'item') THEN RAISE EXCEPTION 'container item evolution requires explicit support' USING ERRCODE='0A000';END IF;
    candidate:=candidate||jsonb_build_object('item',old->'item');
   END IF;
   IF old->'_originalField'=row->'_originalField' THEN CONTINUE;END IF;
   -- Name-only changes retain storage and key identities.
   IF ((old->'_originalField') - 'name') = ((row->'_originalField') - 'name') THEN
    NULL; -- Storage meaning and retained key components are unchanged.
   ELSE
   tightening:=(old->>'nullability'='absent-allowed' AND row->>'nullability'='required') IS TRUE;
   IF tightening THEN
    IF ((old->>'cardinality'='one' AND row->>'cardinality'='one' AND old->>'scalar_type' IN ('string','integer','decimal','boolean','timestamp','binary','date') AND row->>'scalar_type'=old->>'scalar_type') OR (old->>'cardinality' IN ('array','map') AND row->>'cardinality'=old->>'cardinality' AND truss.valid_property_definition(jsonb_populate_record(NULL::truss.prop_def,candidate)) IS TRUE)) IS DISTINCT FROM TRUE THEN
     RAISE EXCEPTION 'required tightening requires a supported retained scalar or flat container' USING ERRCODE='0A000';END IF;
    FOREACH facet_map IN ARRAY ARRAY[coalesce(old->'_originalField'->'facets','{}'::jsonb),coalesce(row->'_originalField'->'facets','{}'::jsonb)] LOOP
     IF truss.known_scalar_facets(old->>'scalar_type',facet_map) IS NOT TRUE THEN
      RAISE EXCEPTION 'required tightening needs known scalar facets' USING ERRCODE='0A000';END IF;
    END LOOP;
   END IF;
   -- Historical nullability-only folds keep their original admission. Actual
   -- facet changes require both maps to belong to this explicit native subset.
   IF coalesce(old->'_originalField'->'facets','{}'::jsonb) IS DISTINCT FROM coalesce(row->'_originalField'->'facets','{}'::jsonb) THEN
    IF truss.known_scalar_facets(old->>'scalar_type',old->'_originalField'->'facets') IS NOT TRUE
     OR truss.known_scalar_facets(row->>'scalar_type',row->'_originalField'->'facets') IS NOT TRUE THEN
     RAISE EXCEPTION 'known native scalar facet transition required' USING ERRCODE='0A000';END IF;
   END IF;
   IF ((old->'_originalField')-ARRAY['nullability','facets']) IS DISTINCT FROM ((row->'_originalField')-ARRAY['nullability','facets'])
    OR NOT (old->>'nullability'=row->>'nullability' OR old->>'nullability'='required' AND row->>'nullability'='absent-allowed' OR tightening)
    OR prior_key_property ? jsonb_build_array(assigned::text,old->>'prop_id')::text THEN
    RAISE EXCEPTION 'existing field change requires explicit evolution support' USING ERRCODE='0A000';END IF;
   END IF;
   candidate:=candidate||jsonb_build_object('since_rev',old->'since_rev','doc_ord',old->'doc_ord');
   removed_property_ids[cardinality(removed_property_ids)+1]:=(old->>'prop_id')::int;
  END IF;
  -- Public source validation already rejects duplicate property names within a type. The
  -- immutable prior-name map above preserves the planner's cross-revision collision refusal.
  next_properties[cardinality(next_properties)+1]:=candidate;sequence:=sequence+1;
  IF old IS NOT NULL OR NOT compact_insertions THEN
  next_changes[cardinality(next_changes)+1]:=jsonb_build_object('rev',revision,'seq',sequence,'kind','prop','def_id',(candidate->>'prop_id')::int,'before',CASE WHEN old IS NULL THEN 'null'::jsonb ELSE to_jsonb(jsonb_populate_record(NULL::truss.prop_def,old)) END,'after',to_jsonb(jsonb_populate_record(NULL::truss.prop_def,candidate)));
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY family,ordinal),'[]'::jsonb) INTO properties FROM (
  SELECT v.value,0 family,v.ordinality ordinal FROM jsonb_array_elements(coalesce(prior->'prop_def','[]'::jsonb)) WITH ORDINALITY v
   LEFT JOIN (SELECT DISTINCT id FROM unnest(removed_property_ids) AS removed(id)) removed ON removed.id=(v.value->>'prop_id')::int
   WHERE removed.id IS NULL
  UNION ALL SELECT n.value,1,n.ordinality FROM unnest(next_properties) WITH ORDINALITY n(value,ordinality)) merged;
 FOR row IN SELECT value FROM jsonb_array_elements(fresh->'key_def') LOOP
  assigned:=(type_map->> (row->>'type_id'))::int;remapped:='[]';
  SELECT coalesce(jsonb_agg(to_jsonb((property_map->>(p.value#>>'{}'))::int) ORDER BY p.ordinality),'[]'::jsonb)
   INTO remapped FROM jsonb_array_elements(row->'prop_ids') WITH ORDINALITY p;
  old:=prior_key_identity->jsonb_build_array(assigned::text,row->>'key_id')::text;
  IF old IS NOT NULL THEN
   IF old->'prop_ids' IS DISTINCT FROM remapped OR old->'is_primary' IS DISTINCT FROM row->'is_primary' THEN RAISE EXCEPTION 'existing key change requires backfill support' USING ERRCODE='0A000';END IF;
  ELSE
   IF prior_type_id ? assigned::text THEN
    IF (row->>'is_primary')::boolean IS NOT FALSE OR EXISTS(SELECT 1 FROM jsonb_array_elements(remapped) component
     CROSS JOIN LATERAL (SELECT current_property_id->jsonb_build_array(assigned::text,component.value#>>'{}')::text current_row,
       prior_property_id->>(component.value#>>'{}') prior_row) p
     WHERE p.current_row IS NULL
      OR p.current_row->>'nullability'<>'required' OR p.current_row->>'cardinality'<>'one'
      OR p.current_row->>'scalar_type' NOT IN ('string','integer','decimal','boolean','binary')
      OR NOT ((p.prior_row IS NOT NULL AND p.prior_row::jsonb->>'type_id'=assigned::text
         AND p.prior_row::jsonb->>'nullability'='required' AND p.prior_row::jsonb->>'cardinality'='one'
         AND p.prior_row::jsonb->>'scalar_type' IN ('string','integer','decimal','boolean','binary'))
       OR (p.current_row->>'since_rev')::int=revision AND p.prior_row IS NULL)) THEN
     RAISE EXCEPTION 'new alternate key requires existing or newly rebound required scalar components' USING ERRCODE='0A000';END IF;
   END IF;
   key_next:=(fresh_key_number->>jsonb_build_array(assigned::text,row->>'key_id')::text)::int;
   IF key_next>32767 THEN RAISE EXCEPTION 'owner-local key range exhausted' USING ERRCODE='54000';END IF;
   next_keys[cardinality(next_keys)+1]:=row||jsonb_build_object('type_id',assigned,'prop_ids',remapped,'key_num',key_next);
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY family,ordinal),'[]'::jsonb) INTO keys FROM (
  SELECT v.value,0 family,v.ordinality ordinal FROM jsonb_array_elements(coalesce(prior->'key_def','[]'::jsonb)) WITH ORDINALITY v
  UNION ALL SELECT n.value,1,n.ordinality FROM unnest(next_keys) WITH ORDINALITY n(value,ordinality)) merged;
 -- Relationship IDs and lineage remain stable; independent multiplicity evolution retains endpoints.
 FOR row IN SELECT value FROM jsonb_array_elements(fresh->'rel_def') LOOP
  assigned:=(relationship_map->>(row->>'rel_type_id'))::int;
  old:=prior_relation_identity->jsonb_build_array(row->>'document_id',row->>'module',row->>'rel_id')::text;
  candidate:=row||jsonb_build_object('rel_type_id',assigned);
  candidate:=to_jsonb(jsonb_populate_record(NULL::truss.rel_def,candidate));
  IF old IS NOT NULL THEN
   old_source:=source_index->jsonb_build_array(old->>'definition_rev',old->>'definition_doc_ord',old->>'definition_document_id',old->>'module','relationship',old->>'rel_id')::text;
   new_source:=source_index->jsonb_build_array(row->>'definition_rev',row->>'definition_doc_ord',row->>'definition_document_id',row->>'module','relationship',row->>'rel_id')::text;
   IF old_source IS NULL OR new_source IS NULL THEN RAISE NO_DATA_FOUND;END IF;
   IF old_source=new_source THEN CONTINUE;END IF;
   IF (old_source-ARRAY['name','inverse','source','target','sourceMultiplicity','targetMultiplicity']) IS DISTINCT FROM (new_source-ARRAY['name','inverse','source','target','sourceMultiplicity','targetMultiplicity'])
    OR (old_source ? 'inverse') IS DISTINCT FROM (new_source ? 'inverse')
    OR (old_source->'name' IS DISTINCT FROM new_source->'name' AND (jsonb_typeof(old_source->'name') IS DISTINCT FROM 'string' OR jsonb_typeof(new_source->'name') IS DISTINCT FROM 'string'))
    OR (old_source->'inverse' IS DISTINCT FROM new_source->'inverse' AND (jsonb_typeof(old_source->'inverse') IS DISTINCT FROM 'string' OR jsonb_typeof(new_source->'inverse') IS DISTINCT FROM 'string'))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(old_source->'source') x
              WHERE NOT ((new_source->'source') @> jsonb_build_array(x.value)))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(old_source->'target') x
              WHERE NOT ((new_source->'target') @> jsonb_build_array(x.value))) THEN
    RAISE EXCEPTION 'relationship source meaning must be retained' USING ERRCODE='0A000';END IF;
   IF ((candidate->>'source_min')::int>(old->>'source_min')::int OR (candidate->>'target_min')::int>(old->>'target_min')::int
    OR candidate->'source_max'<>'null'::jsonb AND (old->'source_max'='null'::jsonb OR (candidate->>'source_max')::int<(old->>'source_max')::int)
    OR candidate->'target_max'<>'null'::jsonb AND (old->'target_max'='null'::jsonb OR (candidate->>'target_max')::int<(old->>'target_max')::int))
    AND (old_source->'source' IS DISTINCT FROM new_source->'source' OR old_source->'target' IS DISTINCT FROM new_source->'target') THEN
    RAISE EXCEPTION 'tightening requires unchanged endpoint declarations' USING ERRCODE='0A000';END IF;
   IF old->>'lifecycle' IS DISTINCT FROM 'independent' OR candidate->>'lifecycle' IS DISTINCT FROM 'independent'
    OR (old-ARRAY['name','source_min','source_max','target_min','target_max','definition_rev','definition_doc_ord','definition_document_id','doc_ord','since_rev']) IS DISTINCT FROM (candidate-ARRAY['name','source_min','source_max','target_min','target_max','definition_rev','definition_doc_ord','definition_document_id','doc_ord','since_rev'])
 THEN
    RAISE EXCEPTION 'relationship change requires unchanged independent endpoints and meaning' USING ERRCODE='0A000';END IF;
   candidate:=candidate||jsonb_build_object('since_rev',old->'since_rev','doc_ord',old->'doc_ord');
   removed_relation_ids[cardinality(removed_relation_ids)+1]:=assigned;
  END IF;
  next_relations[cardinality(next_relations)+1]:=candidate;sequence:=sequence+1;
  IF old IS NOT NULL OR NOT compact_insertions THEN
  next_changes[cardinality(next_changes)+1]:=jsonb_build_object('rev',revision,'seq',sequence,'kind','rel','def_id',assigned,'before',CASE WHEN old IS NULL THEN 'null'::jsonb ELSE to_jsonb(jsonb_populate_record(NULL::truss.rel_def,old)) END,'after',to_jsonb(jsonb_populate_record(NULL::truss.rel_def,candidate)));
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY family,ordinal),'[]'::jsonb) INTO relations FROM (
  SELECT v.value,0 family,v.ordinality ordinal FROM jsonb_array_elements(coalesce(prior->'rel_def','[]'::jsonb)) WITH ORDINALITY v
   LEFT JOIN (SELECT DISTINCT id FROM unnest(removed_relation_ids) AS removed(id)) removed ON removed.id=(v.value->>'rel_type_id')::int
   WHERE removed.id IS NULL
  UNION ALL SELECT n.value,1,n.ordinality FROM unnest(next_relations) WITH ORDINALITY n(value,ordinality)) merged;
 FOR row IN SELECT value FROM jsonb_array_elements(fresh->'relationship_lineage') LOOP
  assigned:=(relationship_map->> (row->>'rel_type_id'))::int;
  IF NOT prior_lineage_id ? assigned::text THEN next_lineages[cardinality(next_lineages)+1]:=row||jsonb_build_object('rel_type_id',assigned);END IF;
 END LOOP;
 FOR row IN SELECT value FROM jsonb_array_elements(fresh->'rel_endpoint') LOOP
  candidate:=jsonb_build_object('rel_type_id',(relationship_map->> (row->>'rel_type_id'))::int,'source_type',(type_map->> (row->>'source_type'))::int,'target_type',(type_map->> (row->>'target_type'))::int);
  IF NOT prior_endpoint_id ? jsonb_build_array(candidate->>'rel_type_id',candidate->>'source_type',candidate->>'target_type')::text THEN
   next_endpoints[cardinality(next_endpoints)+1]:=candidate;END IF;
 END LOOP;
 WITH additions AS (
  SELECT n.value,n.ordinality,row_number() OVER(PARTITION BY n.value->>'rel_type_id' ORDER BY n.ordinality) duplicate_rank
   FROM unnest(next_lineages) WITH ORDINALITY n(value,ordinality)
 ) SELECT coalesce(jsonb_agg(value ORDER BY family,ordinal),'[]'::jsonb) INTO lineages FROM (
  SELECT v.value,0 family,v.ordinality ordinal FROM jsonb_array_elements(coalesce(prior->'relationship_lineage','[]'::jsonb)) WITH ORDINALITY v
  UNION ALL SELECT a.value,1,a.ordinality FROM additions a WHERE a.duplicate_rank=1) merged;
 WITH additions AS (
  SELECT n.value,n.ordinality,row_number() OVER(PARTITION BY n.value->>'rel_type_id',n.value->>'source_type',n.value->>'target_type' ORDER BY n.ordinality) duplicate_rank
   FROM unnest(next_endpoints) WITH ORDINALITY n(value,ordinality)
 ) SELECT coalesce(jsonb_agg(value ORDER BY family,ordinal),'[]'::jsonb) INTO endpoints FROM (
  SELECT v.value,0 family,v.ordinality ordinal FROM jsonb_array_elements(coalesce(prior->'rel_endpoint','[]'::jsonb)) WITH ORDINALITY v
  UNION ALL SELECT a.value,1,a.ordinality FROM additions a WHERE a.duplicate_rank=1) merged;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(relations) p WHERE fresh_document_ids ? (p.value->>'document_id')
  AND NOT fresh_relation_identities ? jsonb_build_array(p.value->>'document_id',p.value->>'module',p.value->>'rel_id')::text) THEN
  RAISE EXCEPTION 'relationship retirement requires explicit support' USING ERRCODE='0A000';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(fresh->'schema_rev') f JOIN jsonb_each(prior_revision_id) p ON p.key=f.value->>'rev' WHERE p.value IS DISTINCT FROM f.value) THEN
  RAISE EXCEPTION 'original revision history required' USING ERRCODE='55000';END IF;
 SELECT coalesce(jsonb_agg(f.value ORDER BY f.ordinality),'[]'::jsonb) INTO remapped FROM jsonb_array_elements(fresh->'schema_rev') WITH ORDINALITY f
  WHERE NOT prior_revision_id ? (f.value->>'rev');
 SELECT coalesce(jsonb_agg(n.value ORDER BY n.ordinality),'[]'::jsonb) INTO changes FROM unnest(next_changes) WITH ORDINALITY n(value,ordinality);
 changes:=coalesce(prior->'schema_change','[]'::jsonb)||changes;
 result:=result||jsonb_build_object('schema_rev',coalesce(prior->'schema_rev','[]')||remapped,'schema_doc',coalesce(prior->'schema_doc','[]')||(fresh->'schema_doc'),
  'type_def',types,'prop_def',properties,'key_def',keys,'rel_def',relations,'relationship_lineage',lineages,'rel_endpoint',endpoints,'schema_change',changes);
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_scalar_violations(declarations_bytes bytea)
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE rec jsonb;field jsonb;node jsonb;selected_type int;property_id int;missing_count bigint;family_count bigint;retained_count bigint;facet_count bigint;
 rel jsonb;old_relation jsonb;tightening boolean;selected_relation truss.rel_def%ROWTYPE;side text;minimum int;maximum int;low_count bigint;high_count bigint;
 violations jsonb[]:=ARRAY[]::jsonb[];scope jsonb;scopes jsonb[]:=ARRAY[]::jsonb[];owner record;original_item jsonb;property_meta record;result bytea;
 field_checks jsonb[];field_ordinal int;candidate_name text;check_required boolean;check_family boolean;check_facets boolean;check_name boolean;counts record;
 stored_values_bytes bigint:=0;remaining_stored_values_bytes bigint;
BEGIN
 -- The caller holds the exclusive head lock, excluding supported graph writers.
 FOR rec IN SELECT r.value FROM jsonb_array_elements(convert_from(declarations_bytes,'UTF8')::jsonb) d
  CROSS JOIN LATERAL jsonb_array_elements(d.value->'records') r LOOP
  SELECT type_id INTO selected_type FROM truss.type_def t WHERE t.document_id=rec->>'documentId'
   AND t.module=rec->>'moduleId' AND t.element=rec->>'elementId' AND t.retired_rev IS NULL;
  IF NOT FOUND THEN CONTINUE;END IF;
  IF NOT truss.runtime_can_read(rec->>'documentId',rec->>'moduleId') THEN
   RAISE EXCEPTION 'current module read authority required for compatibility counts' USING ERRCODE='42501';END IF;
  scopes:=array_append(scopes,jsonb_build_object('documentId',rec->>'documentId','moduleId',rec->>'moduleId'));
  field_checks:=ARRAY[]::jsonb[];field_ordinal:=0;
  FOR field IN SELECT value FROM jsonb_array_elements(rec->'fields') LOOP
   field_ordinal:=field_ordinal+1;
   IF NOT truss.runtime_can_read(rec->>'documentId',field->>'fieldModule') THEN
    RAISE EXCEPTION 'current field module read authority required for compatibility counts' USING ERRCODE='42501';END IF;
   scopes:=array_append(scopes,jsonb_build_object('documentId',rec->>'documentId','moduleId',field->>'fieldModule'));
   IF field->'declaration'->>'cardinality' IN ('array','map') THEN
    IF truss.runtime_can_read(rec->>'documentId',field->'declaration'->'itemType'->>'module') IS NOT TRUE THEN RAISE EXCEPTION 'current item module read authority required for compatibility counts' USING ERRCODE='42501';END IF;
    scopes:=array_append(scopes,jsonb_build_object('documentId',rec->>'documentId','moduleId',field->'declaration'->'itemType'->>'module'));
   END IF;
   property_id:=NULL;original_item:=NULL;
   SELECT p.prop_id,p.item,p.name,p.nullability,p.cardinality,p.scalar_type,p.facets
    INTO property_meta FROM truss.prop_def p WHERE p.type_id=selected_type
    AND p.declaration_module=field->>'fieldModule' AND p.element=field->>'fieldId' AND p.retired_rev IS NULL;
   IF FOUND THEN property_id:=property_meta.prop_id;IF property_meta.cardinality IN ('array','map') THEN original_item:=property_meta.item;END IF;END IF;
   IF original_item IS NOT NULL THEN
    IF truss.runtime_item_chain_readable(original_item) IS NOT TRUE THEN RAISE EXCEPTION 'complete current item readers required for compatibility counts' USING ERRCODE='42501';END IF;
    FOR node IN SELECT value FROM jsonb_array_elements(jsonb_build_array(original_item)||coalesce(original_item->'descendants','[]'::jsonb)) LOOP
     scopes:=array_append(scopes,jsonb_build_object('documentId',node->>'documentId','moduleId',node->'reference'->>'module'));
    END LOOP;
   END IF;
   candidate_name:=coalesce(field->'declaration'->>'name',field->'declaration'->>'id');
   check_required:=property_id IS NOT NULL AND field->'declaration'->>'nullability'='required' AND property_meta.nullability IS DISTINCT FROM 'required';
   check_family:=property_id IS NOT NULL AND field->'declaration'->>'cardinality'='one'
    AND (property_meta.cardinality IS DISTINCT FROM 'one' OR property_meta.scalar_type IS DISTINCT FROM field->'declaration'->>'scalarType');
   check_facets:=property_id IS NOT NULL AND field->'declaration'->>'cardinality'='one'
    AND property_meta.facets IS DISTINCT FROM field->'declaration'->'facets';
   check_name:=property_id IS NOT NULL AND property_meta.name IS DISTINCT FROM candidate_name;
   -- Unchanged native constraints and names cannot invalidate existing rows;
   -- only changed fields enter the one per-type data census below.
   IF check_required OR check_family OR check_facets OR check_name THEN
    field_checks:=array_append(field_checks,jsonb_build_object('ordinal',field_ordinal,'propertyId',property_id,
     'name',candidate_name,'scalarType',field->'declaration'->>'scalarType','facets',field->'declaration'->'facets',
     'fieldModule',field->>'fieldModule','fieldId',field->>'fieldId','checkRequired',check_required,
     'checkFamily',check_family,'checkFacets',check_facets,'checkName',check_name));
   END IF;
  END LOOP;
  IF cardinality(field_checks)>0 THEN
   remaining_stored_values_bytes:=16777216-stored_values_bytes;
   FOR counts IN
    WITH checks AS MATERIALIZED (
     SELECT (c.value->>'ordinal')::int AS ordinal,(c.value->>'propertyId')::int AS property_id,
      c.value->>'name' AS property_name,c.value->>'scalarType' AS scalar_type,
      NULLIF(c.value->'facets','null'::jsonb) AS facets,
      (c.value->>'checkRequired')::boolean AS check_required,(c.value->>'checkFamily')::boolean AS check_family,
      (c.value->>'checkFacets')::boolean AS check_facets,(c.value->>'checkName')::boolean AS check_name,
      c.value->>'fieldModule' AS field_module,c.value->>'fieldId' AS field_id
     FROM jsonb_array_elements(to_jsonb(field_checks)) c(value)),
    objects AS MATERIALIZED (SELECT o.id,o.props,o.retained FROM truss.object o WHERE o.type_id=selected_type),
    cells AS MATERIALIZED (
     SELECT f.ordinal,o.id,c.value AS cell,f.scalar_type,f.facets,f.check_family,f.check_facets
     FROM objects o CROSS JOIN LATERAL jsonb_each(o.props) c
      JOIN checks f ON c.key=f.property_id::text AND (f.check_required OR f.check_family OR f.check_facets)),
    cell_validity AS MATERIALIZED (
     SELECT c.*,
      CASE WHEN c.cell IS NOT NULL AND c.cell<>'{"kind":"null"}'::jsonb AND (c.check_family OR c.check_facets)
       THEN truss.valid_scalar_cell(c.cell,c.scalar_type,true) IS TRUE ELSE false END AS valid_cell
     FROM cells c),
    cell_flags AS MATERIALIZED (
     SELECT c.*,
      c.cell IS NOT NULL AND c.cell<>'{"kind":"null"}'::jsonb AND c.check_family AND c.valid_cell IS NOT TRUE AS invalid_family,
      c.cell IS NOT NULL AND c.cell<>'{"kind":"null"}'::jsonb AND c.check_facets AND c.valid_cell
       AND truss.checked_scalar_facets(c.scalar_type,c.facets) IS TRUE
       AND truss.valid_scalar_property(c.cell,c.scalar_type,true,c.facets) IS NOT TRUE AS invalid_facets,
      c.cell IS NOT NULL AND c.cell<>'{"kind":"null"}'::jsonb AS present_nonnull
     FROM cell_validity c),
    retained_names AS MATERIALIZED (
     SELECT o.id,n.value AS property_name FROM objects o
      CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(o.retained)='object' THEN o.retained ELSE '{}'::jsonb END) n(value)),
    object_count AS (SELECT count(*) AS total FROM objects),
    property_stats AS (
     SELECT f.ordinal,
      count(*) FILTER(WHERE c.invalid_family) AS invalid_family,
      count(*) FILTER(WHERE c.invalid_facets) AS invalid_facets,
      coalesce(sum(octet_length(jsonb_build_object('objectId',c.id::text,'text',c.cell->>'text')::text)::bigint)
       FILTER(WHERE c.invalid_facets AND f.scalar_type IN ('string','binary')),0)::bigint AS stored_entry_bytes,
      count(*) FILTER(WHERE c.invalid_facets AND f.scalar_type IN ('string','binary'))::bigint AS stored_entry_count,
      count(*) FILTER(WHERE c.present_nonnull) AS present_nonnull
     FROM checks f LEFT JOIN cell_flags c ON c.ordinal=f.ordinal GROUP BY f.ordinal),
    budgeted_stats AS MATERIALIZED (
     SELECT s.*,
      CASE WHEN s.stored_entry_count=0 THEN 0 ELSE s.stored_entry_bytes+2*s.stored_entry_count END::bigint AS stored_value_bytes,
      sum(CASE WHEN s.stored_entry_count=0 THEN 0 ELSE s.stored_entry_bytes+2*s.stored_entry_count END)
       OVER(ORDER BY s.ordinal ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_stored_value_bytes
     FROM property_stats s),
    stored_arrays AS (
     SELECT b.ordinal,coalesce(jsonb_agg(jsonb_build_object('objectId',c.id::text,'text',c.cell->>'text') ORDER BY c.id)
       FILTER(WHERE c.invalid_facets AND c.scalar_type IN ('string','binary')
        AND b.cumulative_stored_value_bytes<=remaining_stored_values_bytes),'[]'::jsonb) AS stored_values
     FROM budgeted_stats b LEFT JOIN cell_flags c ON c.ordinal=b.ordinal
     GROUP BY b.ordinal,b.cumulative_stored_value_bytes),
    retained_counts AS (
     SELECT f.ordinal,count(*) AS collisions FROM checks f JOIN retained_names n ON n.property_name=f.property_name
      WHERE f.check_name GROUP BY f.ordinal)
   SELECT f.ordinal,f.field_module,f.field_id,
    CASE WHEN f.check_required THEN greatest(o.total-coalesce(p.present_nonnull,0),0) ELSE 0 END AS missing,
    coalesce(p.invalid_family,0) AS family,coalesce(p.invalid_facets,0) AS facets,
    coalesce(p.stored_value_bytes,0) AS stored_value_bytes,coalesce(a.stored_values,'[]'::jsonb) AS stored_values,
    coalesce(r.collisions,0) AS retained
   FROM checks f CROSS JOIN object_count o LEFT JOIN budgeted_stats p ON p.ordinal=f.ordinal
    LEFT JOIN stored_arrays a ON a.ordinal=f.ordinal
    LEFT JOIN retained_counts r ON r.ordinal=f.ordinal ORDER BY f.ordinal
   LOOP
    IF counts.stored_value_bytes>remaining_stored_values_bytes THEN
     RAISE EXCEPTION 'complete compatibility violation result exceeds byte limit' USING ERRCODE='54000';END IF;
    stored_values_bytes:=stored_values_bytes+counts.stored_value_bytes;
    remaining_stored_values_bytes:=remaining_stored_values_bytes-counts.stored_value_bytes;
    scope:=jsonb_build_object('documentId',rec->>'documentId','moduleId',rec->>'moduleId',
     'recordId',rec->>'elementId','fieldModuleId',counts.field_module,'fieldId',counts.field_id);
    IF counts.missing>0 THEN violations:=array_append(violations,scope||jsonb_build_object('rule','property.required','affectedObjectCount',counts.missing::text));END IF;
    IF counts.family>0 THEN violations:=array_append(violations,scope||jsonb_build_object('rule','property.scalar_type','affectedObjectCount',counts.family::text));END IF;
    IF counts.facets>0 THEN violations:=array_append(violations,scope||jsonb_build_object('rule','property.facets','affectedObjectCount',counts.facets::text)
     ||CASE WHEN counts.stored_values='[]'::jsonb THEN '{}'::jsonb ELSE jsonb_build_object('storedValues',counts.stored_values) END);END IF;
    IF counts.retained>0 THEN violations:=array_append(violations,scope||jsonb_build_object('rule','property.retained_name_collision','affectedObjectCount',counts.retained::text));END IF;
   END LOOP;
  END IF;
 END LOOP;
 -- Existing independent relationship bounds are checked before publication.
 FOR rel IN SELECT r.value FROM jsonb_array_elements(convert_from(declarations_bytes,'UTF8')::jsonb) d
  CROSS JOIN LATERAL jsonb_array_elements(d.value->'relationships') r LOOP
  SELECT * INTO selected_relation FROM truss.rel_def WHERE document_id=rel->>'documentId' AND module=rel->>'moduleId'
   AND rel_id=rel->'declaration'->>'id' AND retired_rev IS NULL;
  IF NOT FOUND THEN CONTINUE;END IF;
  tightening:=(rel->'declaration'->'sourceMultiplicity'->>'min')::int>selected_relation.source_min
   OR (rel->'declaration'->'targetMultiplicity'->>'min')::int>selected_relation.target_min
   OR rel->'declaration'->'sourceMultiplicity'->>'max'<>'*' AND (selected_relation.source_max IS NULL OR (rel->'declaration'->'sourceMultiplicity'->>'max')::int<selected_relation.source_max)
   OR rel->'declaration'->'targetMultiplicity'->>'max'<>'*' AND (selected_relation.target_max IS NULL OR (rel->'declaration'->'targetMultiplicity'->>'max')::int<selected_relation.target_max);
  IF tightening THEN
   SELECT r.value INTO STRICT old_relation FROM truss.schema_doc d CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m
    CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') r WHERE d.rev=selected_relation.definition_rev AND d.ord=selected_relation.definition_doc_ord
    AND d.doc_id=selected_relation.definition_document_id AND m.value->>'id'=selected_relation.module AND r.value->>'id'=selected_relation.rel_id;
   IF old_relation->'source' IS DISTINCT FROM rel->'declaration'->'source' OR old_relation->'target' IS DISTINCT FROM rel->'declaration'->'target' THEN
    RAISE EXCEPTION 'tightening requires unchanged endpoint declarations' USING ERRCODE='0A000';END IF;
  END IF;
  IF truss.runtime_can_read(selected_relation.document_id,selected_relation.module) IS NOT TRUE THEN
   RAISE EXCEPTION 'relationship reader required for compatibility counts' USING ERRCODE='42501';END IF;
  scopes:=array_append(scopes,jsonb_build_object('documentId',selected_relation.document_id,'moduleId',selected_relation.module));
  FOR owner IN SELECT DISTINCT t.document_id,t.module FROM truss.rel_endpoint e JOIN truss.type_def t ON t.type_id IN(e.source_type,e.target_type) WHERE e.rel_type_id=selected_relation.rel_type_id LOOP
   IF truss.runtime_can_read(owner.document_id,owner.module) IS NOT TRUE THEN RAISE EXCEPTION 'complete endpoint reader required for compatibility counts' USING ERRCODE='42501';END IF;
   scopes:=array_append(scopes,jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module));
  END LOOP;
  IF NOT tightening THEN CONTINUE;END IF;
  FOREACH side IN ARRAY ARRAY['source','target'] LOOP
   minimum:=(rel->'declaration'->CASE WHEN side='source' THEN 'targetMultiplicity' ELSE 'sourceMultiplicity' END->>'min')::int;
   maximum:=CASE WHEN rel->'declaration'->CASE WHEN side='source' THEN 'targetMultiplicity' ELSE 'sourceMultiplicity' END->>'max'='*' THEN NULL ELSE (rel->'declaration'->CASE WHEN side='source' THEN 'targetMultiplicity' ELSE 'sourceMultiplicity' END->>'max')::int END;
   IF side='source' AND minimum<=selected_relation.target_min
      AND (maximum IS NULL OR selected_relation.target_max IS NOT NULL AND maximum>=selected_relation.target_max)
    OR side='target' AND minimum<=selected_relation.source_min
      AND (maximum IS NULL OR selected_relation.source_max IS NOT NULL AND maximum>=selected_relation.source_max) THEN CONTINUE;END IF;
   -- Bound each degree probe while retaining exact violation totals.
   IF side='source' THEN
    SELECT count(*) FILTER(WHERE degree<minimum),count(*) FILTER(WHERE maximum IS NOT NULL AND degree>maximum) INTO low_count,high_count FROM (
     SELECT (SELECT count(*) FROM (
      SELECT 1 FROM truss.edge e WHERE e.rel_type_id=selected_relation.rel_type_id AND e.source_id=o.id AND e.source_type=o.type_id
      LIMIT CASE WHEN maximum IS NULL THEN minimum::bigint ELSE maximum::bigint+1 END
     ) matching_edges) AS degree
     FROM truss.object o WHERE EXISTS(SELECT 1 FROM truss.rel_endpoint e WHERE e.rel_type_id=selected_relation.rel_type_id AND e.source_type=o.type_id)) anchors;
   ELSE
    SELECT count(*) FILTER(WHERE degree<minimum),count(*) FILTER(WHERE maximum IS NOT NULL AND degree>maximum) INTO low_count,high_count FROM (
     SELECT (SELECT count(*) FROM (
      SELECT 1 FROM truss.edge e WHERE e.rel_type_id=selected_relation.rel_type_id AND e.target_id=o.id AND e.target_type=o.type_id
      LIMIT CASE WHEN maximum IS NULL THEN minimum::bigint ELSE maximum::bigint+1 END
     ) matching_edges) AS degree
     FROM truss.object o WHERE EXISTS(SELECT 1 FROM truss.rel_endpoint e WHERE e.rel_type_id=selected_relation.rel_type_id AND e.target_type=o.type_id)) anchors;
   END IF;
   scope:=jsonb_build_object('documentId',selected_relation.document_id,'moduleId',selected_relation.module,'relationshipId',selected_relation.rel_id,'side',side);
   IF low_count>0 THEN violations:=array_append(violations,scope||jsonb_build_object('rule','relationship.min','affectedObjectCount',low_count::text));END IF;
   IF high_count>0 THEN violations:=array_append(violations,scope||jsonb_build_object('rule','relationship.max','affectedObjectCount',high_count::text));END IF;
  END LOOP;
 END LOOP;
 FOR owner IN SELECT DISTINCT item.value->>'documentId' AS document_id,item.value->>'moduleId' AS module_id FROM unnest(scopes) AS item(value) LOOP
  IF NOT truss.runtime_can_read(owner.document_id,owner.module_id) THEN
   RAISE EXCEPTION 'current module authority changed during compatibility validation' USING ERRCODE='42501';END IF;
 END LOOP;
 IF cardinality(violations)=0 THEN RETURN NULL;END IF;
 result:=convert_to(to_jsonb(violations)::text,'UTF8');
 IF octet_length(result)>16777216 THEN
  RAISE EXCEPTION 'complete compatibility violation result exceeds byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_scalar_violations_with_sources(declarations_bytes bytea, documents_bytes bytea)
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE rec jsonb;field jsonb;item jsonb;node jsonb;source_indexes jsonb;
 parsed_declarations jsonb;parsed_documents jsonb;scopes jsonb[]:=ARRAY[]::jsonb[];result bytea;
BEGIN
 parsed_declarations:=convert_from(declarations_bytes,'UTF8')::jsonb;
 parsed_documents:=convert_from(documents_bytes,'UTF8')::jsonb;
 WITH needed_documents AS MATERIALIZED (
  SELECT DISTINCT (r.value->>'documentId') COLLATE "C" document_id
  FROM jsonb_array_elements(parsed_declarations) d
  CROSS JOIN LATERAL jsonb_array_elements(d.value->'records') r
  WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(r.value->'fields') f
   WHERE f.value->'declaration'->>'cardinality' IN ('array','map'))
 )
 SELECT coalesce(jsonb_object_agg(d.value->>'documentId',
   truss.catalog_item_source_index(d.value->>'originalText')),'{}'::jsonb)
 INTO source_indexes
 FROM jsonb_array_elements(parsed_documents) d
 JOIN needed_documents n ON n.document_id=d.value->>'documentId' COLLATE "C";
 FOR rec IN SELECT r.value FROM jsonb_array_elements(parsed_declarations) d CROSS JOIN LATERAL jsonb_array_elements(d.value->'records') r LOOP
  IF NOT EXISTS(SELECT 1 FROM truss.type_def t WHERE t.document_id=rec->>'documentId' AND t.module=rec->>'moduleId' AND t.element=rec->>'elementId' AND t.retired_rev IS NULL) THEN CONTINUE;END IF;
  FOR field IN SELECT value FROM jsonb_array_elements(rec->'fields') LOOP
   IF field->'declaration'->>'cardinality' NOT IN ('array','map') THEN CONTINUE;END IF;
   item:=truss.catalog_item_definition_indexed(source_indexes->(rec->>'documentId'),rec->>'documentId',1,0,field->'declaration'->'itemType');
   IF truss.runtime_item_chain_readable(item) IS NOT TRUE THEN RAISE EXCEPTION 'complete candidate item readers required for compatibility counts' USING ERRCODE='42501';END IF;
   FOR node IN SELECT value FROM jsonb_array_elements(jsonb_build_array(item)||coalesce(item->'descendants','[]'::jsonb)) LOOP
    scopes:=array_append(scopes,jsonb_build_object('documentId',node->>'documentId','moduleId',node->'reference'->>'module'));
   END LOOP;
  END LOOP;
 END LOOP;
 result:=truss.catalog_scalar_violations(declarations_bytes);
 FOR node IN SELECT value FROM unnest(scopes) AS item(value) LOOP
  IF truss.runtime_can_read(node->>'documentId',node->>'moduleId') IS NOT TRUE THEN RAISE EXCEPTION 'candidate item authority changed during compatibility counts' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_validate_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE request truss.catalog_registration_request%ROWTYPE; installation truss.catalog_runtime_installation%ROWTYPE;
 expected jsonb; origin bytea; original_report bytea;
BEGIN
 IF TG_TABLE_SCHEMA<>'truss' OR TG_TABLE_NAME<>'schema_head' OR NEW.id<>1 OR NEW.rev<1 THEN
  RAISE EXCEPTION 'selected catalog completion required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 SELECT * INTO STRICT request FROM truss.catalog_registration_request WHERE revision=NEW.rev;
 IF request.actor_oid IS DISTINCT FROM truss.catalog_actor() THEN
  RAISE EXCEPTION 'current original registration authority required' USING ERRCODE='42501'; END IF;
 IF request.installation_id<>installation.installation_id OR NOT EXISTS(SELECT 1 FROM truss.schema_head WHERE id=1 AND rev>=request.revision) THEN
  RAISE EXCEPTION 'complete catalog publication required' USING ERRCODE='55000'; END IF;
 origin:=convert_to((convert_from(request.origin_bytes,'UTF8')::jsonb||jsonb_build_object('actor',request.actor_name,'db_role',request.actor_name))::text,'UTF8');
 SELECT report_bytes INTO STRICT original_report FROM truss.catalog_acceptance_report WHERE rev=request.revision;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_validate_unchanged()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE original truss.catalog_registration_request%ROWTYPE; stored truss.catalog_unchanged_request%ROWTYPE;
 expected jsonb; original_origin bytea; report bytea; request_count bigint;
BEGIN
 IF TG_TABLE_SCHEMA<>'truss' OR TG_TABLE_NAME<>'catalog_unchanged_request'
  OR NEW.actor_oid IS DISTINCT FROM truss.catalog_actor() OR NEW.actor_name IS DISTINCT FROM session_user::text THEN
  RAISE EXCEPTION 'current unchanged request authority required' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT stored FROM truss.catalog_unchanged_request r
  WHERE r.installation_id=NEW.installation_id AND r.actor_oid=NEW.actor_oid AND r.request_key=NEW.request_key;
 IF stored IS DISTINCT FROM NEW THEN RAISE EXCEPTION 'original unchanged request required' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT original FROM truss.catalog_registration_request r WHERE r.registration_id=NEW.registration_id;
 IF original.installation_id IS DISTINCT FROM NEW.installation_id
  OR NOT EXISTS(SELECT 1 FROM truss.runtime_current_installation() i WHERE i.installation_id=NEW.installation_id)
  OR NOT EXISTS(SELECT 1 FROM truss.schema_head h WHERE h.id=1 AND h.rev>=original.revision)
  OR jsonb_typeof(convert_from(NEW.origin_bytes,'UTF8')::jsonb) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'original current registration required' USING ERRCODE='55000'; END IF;
 SELECT count(*) INTO request_count FROM (
  SELECT 1 FROM truss.catalog_registration_request r WHERE r.installation_id=NEW.installation_id AND r.actor_oid=NEW.actor_oid AND r.request_key=NEW.request_key
  UNION ALL SELECT 1 FROM truss.catalog_unchanged_request r WHERE r.installation_id=NEW.installation_id AND r.actor_oid=NEW.actor_oid AND r.request_key=NEW.request_key) requests;
 IF request_count<>1 THEN RAISE EXCEPTION 'unambiguous catalog request required' USING ERRCODE='55000'; END IF;
 original_origin:=convert_to((convert_from(original.origin_bytes,'UTF8')::jsonb||jsonb_build_object('actor',original.actor_name,'db_role',original.actor_name))::text,'UTF8');
 SELECT report_bytes INTO STRICT report FROM truss.catalog_acceptance_report WHERE rev=original.revision;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.catalog_view_basis(selected_revision integer, maximum_count integer, maximum_bytes integer)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET bytea_output TO 'hex'
AS $function$
DECLARE captured_revision int; report_revision int;
 request_installation_id uuid; request_registration_id uuid; request_report_sha256 bytea;
 installation truss.catalog_runtime_installation%ROWTYPE; basis jsonb; encoded bytea; definition_count bigint;
BEGIN
 PERFORM truss.catalog_actor();
 IF current_setting('transaction_read_only')='on' THEN RETURN NULL; END IF;
 IF maximum_count IS NULL OR maximum_bytes IS NULL OR maximum_count NOT BETWEEN 1 AND 65536 OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN
  RAISE EXCEPTION 'bounded catalog view limits required' USING ERRCODE='22023'; END IF;
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 IF selected_revision IS NOT NULL AND selected_revision<>captured_revision THEN RETURN NULL; END IF;
 -- This append-only profile exposes the current complete catalog; genesis is not accepted.
 IF captured_revision<1 THEN RETURN NULL; END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 SELECT q.installation_id,q.registration_id,q.report_sha256
  INTO STRICT request_installation_id,request_registration_id,request_report_sha256
  FROM truss.catalog_registration_request q WHERE q.revision=captured_revision;
 IF request_installation_id<>installation.installation_id THEN
  RAISE EXCEPTION 'installed catalog provenance required' USING ERRCODE='55000'; END IF;
 SELECT r.rev INTO STRICT report_revision FROM truss.catalog_acceptance_report r WHERE r.rev=captured_revision;
 -- Accepted native rows are authoritative; do not replay schema compilation or report construction on load.
 SELECT (SELECT count(*) FROM truss.type_def)+(SELECT count(*) FROM truss.prop_def)
       +(SELECT count(*) FROM truss.key_def)+(SELECT count(*) FROM truss.rel_def) INTO definition_count;
 IF definition_count>maximum_count THEN RAISE EXCEPTION 'catalog definition budget exceeded' USING ERRCODE='54000'; END IF;
 basis:=jsonb_build_object('revision',captured_revision::text,'layoutProfile',installation.layout_profile,
  'installationId',installation.installation_id::text,'registrationId',request_registration_id::text,
  'releaseId',installation.release_id,'releaseSha256',installation.release_sha256,
  'reportSha256',encode(request_report_sha256,'hex'),
  'documents',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY rev,ord),'[]'::jsonb) FROM truss.schema_doc d WHERE rev<=captured_revision),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY type_id),'[]'::jsonb) FROM truss.type_def t),
  'properties',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY prop_id),'[]'::jsonb) FROM truss.prop_def p),
  'keys',(SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY type_id,key_num),'[]'::jsonb) FROM truss.key_def k),
  'relationships',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY rel_type_id),'[]'::jsonb) FROM truss.rel_def r),
  'endpoints',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY rel_type_id,source_type,target_type),'[]'::jsonb) FROM truss.rel_endpoint e));
 encoded:=convert_to(basis::text,'UTF8');
 IF octet_length(encoded)>maximum_bytes THEN RAISE EXCEPTION 'catalog basis budget exceeded' USING ERRCODE='54000'; END IF;
 PERFORM truss.catalog_actor();
 RETURN encoded;
END;
$function$

CREATE OR REPLACE FUNCTION truss.encode_umf_scalar_key_tuple(cells jsonb, facets jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result bytea;cell jsonb;facet jsonb;family text;payload bytea;tag int;position int:=0;
BEGIN
 IF jsonb_typeof(cells) IS DISTINCT FROM 'array' OR jsonb_typeof(facets) IS DISTINCT FROM 'array'
  OR jsonb_array_length(cells) NOT BETWEEN 1 AND 1024 OR jsonb_array_length(cells)<>jsonb_array_length(facets) THEN
  RAISE EXCEPTION 'complete ordered scalar key required' USING ERRCODE='22023';END IF;
 result:=convert_to('UMFK1','UTF8')||truss.umf_key_uleb128(jsonb_array_length(cells));
 FOR cell IN SELECT value FROM jsonb_array_elements(cells) LOOP
  family:=cell->>'kind';facet:=facets->position;position:=position+1;
  IF family IS NULL OR family NOT IN ('string','integer','decimal','boolean','binary')
   OR truss.valid_scalar_property(cell,family,false,facet) IS NOT TRUE THEN
   RAISE EXCEPTION 'admitted exact scalar key component required' USING ERRCODE='22023';END IF;
  CASE family
   WHEN 'string' THEN tag:=4;payload:=convert_to(cell->>'text','UTF8');
   WHEN 'binary' THEN tag:=5;payload:=decode(cell->>'text','base64');
   WHEN 'boolean' THEN tag:=1;payload:=decode(CASE WHEN (cell->>'value')::boolean THEN '01' ELSE '00' END,'hex');
   WHEN 'integer' THEN tag:=2;payload:=convert_to(truss.umf_key_coefficient(cell->>'text',0),'UTF8');
   WHEN 'decimal' THEN
    IF truss.valid_decimal_facets(facet) IS NOT TRUE THEN
     RAISE EXCEPTION 'selected native decimal key domain required' USING ERRCODE='0A000';END IF;
    tag:=3;payload:=truss.umf_key_uleb128((facet->>'scale')::numeric::bigint)||convert_to(truss.umf_key_coefficient(cell->>'text',(facet->>'scale')::numeric::int,(facet->>'precision')::numeric::int),'UTF8');
  END CASE;
  IF octet_length(result)::bigint+octet_length(payload)+8>1048576 THEN RAISE EXCEPTION 'key tuple budget exceeded' USING ERRCODE='54000';END IF;
  result:=result||set_byte(decode('00','hex'),0,tag)||truss.umf_key_uleb128(octet_length(payload))||payload;
 END LOOP;
 -- The stored transport is unchanged and includes two hex bytes per tuple byte.
 IF octet_length(result)::bigint*2+length('umf-key-tuple-v1:hex:')>1048576 THEN
  RAISE EXCEPTION 'key transport budget exceeded' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.feed_ack_receipt_binding(selected_consumer text, prior bytea, target bytea, feed_sha text, destination text, request_sha text, publication text, receipt bytea, expected_release text, expected_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE p jsonb;t jsonb;x numeric;
BEGIN
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 IF prior IS NULL OR target IS NULL OR octet_length(prior) NOT BETWEEN 1 AND 16384 OR octet_length(target) NOT BETWEEN 1 AND 16384
 OR receipt IS NULL OR octet_length(receipt) NOT BETWEEN 1 AND 1048576
 OR destination IS NULL OR octet_length(destination) NOT BETWEEN 1 AND 1024 OR publication IS NULL OR octet_length(publication) NOT BETWEEN 1 AND 4096
 OR feed_sha IS NULL OR feed_sha !~ '^[0-9a-f]{64}$' OR request_sha IS NULL OR request_sha !~ '^[0-9a-f]{64}$'
 OR (convert_from(prior,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
 OR (convert_from(target,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
 THEN RAISE EXCEPTION 'bounded exact ACK receipt binding required' USING ERRCODE='22023';END IF;
 p:=convert_from(prior,'UTF8')::jsonb;t:=convert_from(target,'UTF8')::jsonb;
 FOR x IN SELECT CASE WHEN j->>'nextXid' ~ '^(0|[1-9][0-9]{0,19})$' THEN (j->>'nextXid')::numeric ELSE NULL END FROM unnest(ARRAY[p,t]) j LOOP
  IF x IS NULL OR x>18446744073709551615 THEN RAISE EXCEPTION 'canonical ACK receipt cursor required' USING ERRCODE='22023';END IF;
 END LOOP;
 IF prior IS DISTINCT FROM truss.runtime_feed_cursor(selected_consumer,p->>'nextXid')
 OR target IS DISTINCT FROM truss.runtime_feed_cursor(selected_consumer,t->>'nextXid')
 OR (p->>'nextXid')::numeric>(t->>'nextXid')::numeric
 THEN RAISE EXCEPTION 'current original ACK receipt scope required' USING ERRCODE='22023';END IF;
 RETURN jsonb_build_object('installationId',p->>'installationId','sourceEpoch',p->>'sourceEpoch',
 'consumerId',selected_consumer,'registrationId',p->>'registrationId','feedSha256',feed_sha,
 'destinationId',destination,'requestSha256',request_sha,'publicationId',publication,'receiptSha256',encode(sha256(receipt),'hex'));
END;
$function$

CREATE OR REPLACE FUNCTION truss.feed_reached(selected_consumer text, original_position bytea, maximum_evidence_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE proof jsonb;checkpoint bytea;registration uuid;position jsonb;locator jsonb;next_xid numeric;writer_xid numeric;included boolean;
BEGIN
 -- READ ONLY alone does not prove that an earlier local ACK has committed.
 IF current_setting('transaction_read_only')<>'on' OR pg_current_xact_id_if_assigned() IS NOT NULL THEN RAISE EXCEPTION 'unassigned read-only feed comparison required' USING ERRCODE='0A000';END IF;
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 proof:=convert_from(truss.reached(original_position,maximum_evidence_bytes,expected_release,expected_digest),'UTF8')::jsonb;
 IF proof->>'outcome'<>'available' THEN RETURN convert_to(proof::text,'UTF8');END IF;
 SELECT checkpoint_bytes,registration_id INTO STRICT checkpoint,registration FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer;
 IF octet_length(checkpoint) NOT BETWEEN 1 AND 16384 OR (convert_from(checkpoint,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'original checkpoint required' USING ERRCODE='55000';END IF;
 position:=convert_from(checkpoint,'UTF8')::jsonb;locator:=convert_from(original_position,'UTF8')::jsonb;
 IF jsonb_typeof(position->'nextXid') IS DISTINCT FROM 'string' OR position->>'nextXid' !~ '^(0|[1-9][0-9]{0,19})$' THEN RAISE EXCEPTION 'canonical checkpoint position required' USING ERRCODE='55000';END IF;
 next_xid:=(position->>'nextXid')::numeric;writer_xid:=(locator->>'writerXid')::numeric;
 IF next_xid>18446744073709551615 OR checkpoint IS DISTINCT FROM truss.runtime_feed_cursor(selected_consumer,next_xid::text)
  OR position->>'registrationId' IS DISTINCT FROM registration::text THEN RAISE EXCEPTION 'current registered checkpoint required' USING ERRCODE='55000';END IF;
 included:=next_xid>writer_xid;
 -- Changed registration/checkpoint, missing evidence, or revoked authority refuses.
 proof:=convert_from(truss.reached(original_position,maximum_evidence_bytes,expected_release,expected_digest),'UTF8')::jsonb;
 IF proof->>'outcome'<>'available' THEN RETURN convert_to(proof::text,'UTF8');END IF;
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 IF NOT EXISTS(SELECT 1 FROM truss.runtime_feed_consumer c WHERE c.consumer_id=selected_consumer AND c.registration_id=registration AND c.checkpoint_bytes=checkpoint)
  OR pg_current_xact_id_if_assigned() IS NOT NULL THEN RAISE EXCEPTION 'unchanged committed checkpoint required' USING ERRCODE='55P03';END IF;
 RETURN convert_to(jsonb_build_object('outcome','available','included',included,'comparisonProfile','{"identity":"truss-feed-receipt-visibility","version":"0.1","sha256":"576c7cdc116552fd72448c627e3cc313734ffb87865b268bd73e628784aafd25"}'::jsonb)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.get_object(selected_document text, selected_module text, selected_record text, selected_id bigint, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE actor_oid oid; selected_type truss.type_def%ROWTYPE; current_object truss.object%ROWTYPE;
 property truss.prop_def%ROWTYPE; cell jsonb; values_json jsonb:='[]'; retained_json jsonb:='[]';
 properties truss.prop_def[];has_row_home boolean;definition_pin text;dependency record;frozen record;
 root_object truss.object;root_definition truss.type_def;root_identity jsonb;
 captured_revision int; result bytea; policy truss.module_access%ROWTYPE; installation truss.catalog_runtime_installation%ROWTYPE;
BEGIN
 actor_oid:=truss.runtime_person(false);
 IF selected_document IS NULL OR selected_module IS NULL OR selected_record IS NULL
 OR octet_length(selected_document) NOT BETWEEN 1 AND 4096 OR octet_length(selected_module) NOT BETWEEN 1 AND 4096
 OR octet_length(selected_record) NOT BETWEEN 1 AND 4096 OR selected_id IS NULL OR selected_id<=0
 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN
  RAISE EXCEPTION 'bounded object selection required' USING ERRCODE='22023'; END IF;
 IF current_setting('transaction_read_only')='on' THEN
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 ELSE
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF expected_release IS DISTINCT FROM installation.release_id OR expected_digest IS DISTINCT FROM installation.release_sha256
 OR installation.release_id<>'truss-catalog-runtime/0.72-candidate' THEN
  RAISE EXCEPTION 'selected installed object runtime required' USING ERRCODE='0A000'; END IF;
 IF captured_revision<1 THEN RAISE EXCEPTION 'accepted read catalog required' USING ERRCODE='0A000'; END IF;
 -- No object observation until exact document/module membership is established.
 IF current_setting('transaction_read_only')='on' THEN
 SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module;
 ELSE
 SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module FOR SHARE NOWAIT;
 END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
   SELECT actor_oid UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
   SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid
   WHERE r.rolname::text IN (policy.reader_role,policy.writer_role)) THEN RETURN NULL; END IF;
 SELECT * INTO selected_type FROM truss.type_def WHERE document_id=selected_document AND module=selected_module
   AND element=selected_record AND retired_rev IS NULL AND kind='record' AND NOT provisional AND since_rev<=captured_revision;
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- Require every declaration owner before any object observation.
 IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RETURN NULL;END IF;
 SELECT coalesce(array_agg(p ORDER BY p.prop_id),ARRAY[]::truss.prop_def[]) INTO properties FROM truss.prop_def p WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL;
 SELECT d.definition_pin INTO STRICT definition_pin FROM truss.runtime_owned_definition_metadata('type',selected_type.type_id) d;
 SELECT o AS object,ro AS root_object,rt AS root_definition,
 false AS row_home
 INTO frozen FROM truss.object o
 LEFT JOIN truss.object ro ON ro.id=o.root_id AND ro.type_id=o.root_type
 LEFT JOIN truss.type_def rt ON rt.type_id=ro.type_id AND rt.retired_rev IS NULL AND NOT rt.provisional AND rt.kind='record'
 WHERE o.id=selected_id AND o.type_id=selected_type.type_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 current_object:=frozen.object;has_row_home:=frozen.row_home;
 root_object:=frozen.root_object;root_definition:=frozen.root_definition;
 IF current_object.root_id IS NOT NULL OR current_object.root_type IS NOT NULL THEN
  IF current_object.root_id IS NULL OR current_object.root_type IS NULL OR root_object.id IS NULL OR root_definition.type_id IS NULL
   OR root_object.root_id IS NOT NULL OR root_object.root_type IS NOT NULL OR root_object.id=current_object.id AND root_object.type_id=current_object.type_id
   THEN
   RAISE EXCEPTION 'current aggregate root required' USING ERRCODE='55000';END IF;
  IF root_object.rev>captured_revision OR root_definition.since_rev>captured_revision THEN
   RAISE EXCEPTION 'catalog changed during ownership observation' USING ERRCODE='55P03';END IF;
  IF NOT truss.runtime_can_read(root_definition.document_id,root_definition.module) THEN RETURN NULL;END IF;
  root_identity:=jsonb_build_object('id',root_object.id::text,'typeId',root_object.type_id::text,
   'definitionPin',(SELECT d.definition_pin FROM truss.runtime_owned_definition_metadata('type',root_object.type_id) d),
   'owner',jsonb_build_object('documentId',root_definition.document_id,'moduleId',root_definition.module));
 END IF;
 result:=truss.render_logical_object(current_object,selected_type,properties,has_row_home,definition_pin,captured_revision,maximum_bytes,installation.release_id,installation.release_sha256,root_identity);
 actor_oid:=truss.runtime_person(false);
 IF current_setting('transaction_read_only')='on' THEN
  SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module;
  IF NOT FOUND THEN RETURN NULL; END IF;
 END IF;
 IF NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
   SELECT actor_oid UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
   SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid
   WHERE r.rolname::text IN (policy.reader_role,policy.writer_role)) THEN RETURN NULL; END IF;
 IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RETURN NULL;END IF;
 IF root_identity IS NOT NULL AND NOT truss.runtime_can_read(root_definition.document_id,root_definition.module) THEN RETURN NULL;END IF;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN
  RAISE EXCEPTION 'catalog changed during object observation' USING ERRCODE='55P03';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.group_condition_key_metadata(original_input bytea, original_documents bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE input jsonb;inventory jsonb;entry jsonb;archive truss.schema_doc%ROWTYPE;selected truss.type_def%ROWTYPE;source text;encoded bytea;
BEGIN
 PERFORM truss.group_context(expected_release,expected_digest);
 IF original_input IS NULL OR octet_length(original_input) NOT BETWEEN 1 AND 1048576 OR original_documents IS NULL OR octet_length(original_documents) NOT BETWEEN 1 AND 4194304 THEN RAISE EXCEPTION 'bounded condition source required' USING ERRCODE='54000';END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;inventory:=truss.runtime_condition_inventory(input);
 FOR entry IN SELECT value FROM jsonb_array_elements(inventory) WHERE value->'condition'->>'condition'='key_absent' LOOP
  SELECT * INTO STRICT selected FROM truss.type_def WHERE type_id=(entry->>'typeId')::int;
  SELECT * INTO STRICT archive FROM truss.schema_doc WHERE doc_id=selected.document_id ORDER BY rev DESC LIMIT 1;
  SELECT value->>'sourceText' INTO STRICT source FROM jsonb_array_elements(convert_from(original_documents,'UTF8')::jsonb) WHERE value->>'documentId'=archive.doc_id;
  IF convert_to(source,'UTF8') IS DISTINCT FROM convert_to(archive.document,'UTF8') THEN RAISE EXCEPTION 'original key document required' USING ERRCODE='22023';END IF;
 END LOOP;
 encoded:=convert_to((SELECT coalesce(jsonb_agg(value),'[]') FROM jsonb_array_elements(inventory) WHERE value->'condition'->>'condition'='key_absent')::text,'UTF8');
 PERFORM truss.runtime_condition_inventory(input);
 RETURN encoded;
END;
$function$

CREATE OR REPLACE FUNCTION truss.group_context_qualified(expected_release text, expected_digest text, qualified_actor oid)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE person oid;installation truss.catalog_runtime_installation%ROWTYPE;revision int;
BEGIN
 person:=qualified_actor;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected installed group runtime required' USING ERRCODE='0A000'; END IF;
 SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 IF revision<1 THEN RAISE EXCEPTION 'accepted catalog required' USING ERRCODE='0A000'; END IF;
 RETURN convert_to((truss.runtime_group_profiles()||jsonb_build_object('layoutProfile',installation.layout_profile,
  'authorizedScopeIdentity','truss-person:'||installation.installation_id||':'||person::text,
  'installationId',installation.installation_id::text,'sourceEpoch',installation.source_epoch::text,'historyProfile',
   CASE WHEN truss.runtime_group_profiles()->'mutationProfile'=truss.runtime_owned_profile() THEN 'truss-native-owned-create/0.1' ELSE 'truss-native-scalar-create/0.2' END))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.group_create_metadata_qualified(original_input bytea, original_documents bytea, expected_release text, expected_digest text, qualified_actor oid)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE input jsonb;documents jsonb;operation jsonb;context jsonb;selected_type truss.type_def%ROWTYPE;
 source_pin record;archive truss.schema_doc%ROWTYPE;metadata jsonb;metadata_items jsonb[]:='{}';counted int:=0;source_text text;
 source_slots jsonb;source_slot_list jsonb;source_slot int;source_texts text[];source_verified boolean[];
BEGIN
 context:=convert_from(truss.group_context_qualified(expected_release,expected_digest,qualified_actor),'UTF8')::jsonb;
 IF original_input IS NULL OR octet_length(original_input) NOT BETWEEN 1 AND 1048576
 OR original_documents IS NULL OR octet_length(original_documents) NOT BETWEEN 1 AND 4194304 THEN
  RAISE EXCEPTION 'bounded group source required' USING ERRCODE='54000'; END IF;
 IF (convert_from(original_input,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE OR (convert_from(original_documents,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'unique original JSON members required' USING ERRCODE='22023'; END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;documents:=convert_from(original_documents,'UTF8')::jsonb;
 IF input->>'interfaceVersion' IS DISTINCT FROM 'truss-group-input/0.1.0'
 OR input->'layoutProfile' IS DISTINCT FROM context->'layoutProfile'
 OR input->'mutationProfile' IS DISTINCT FROM context->'mutationProfile'
 OR input->'valueProfile' IS DISTINCT FROM context->'valueProfile'
 OR input->'catalog' IS DISTINCT FROM '{"selection":"current"}'::jsonb
 OR jsonb_typeof(input->'operations') IS DISTINCT FROM 'array' OR jsonb_array_length(input->'operations') NOT BETWEEN 1 AND 128
 OR jsonb_typeof(documents) IS DISTINCT FROM 'array' OR jsonb_array_length(documents) NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'selected create group profile required' USING ERRCODE='0A000'; END IF;
 WITH docs AS MATERIALIZED (
  SELECT value,ordinality::int slot,value->>'documentId' document_id
  FROM jsonb_array_elements(documents) WITH ORDINALITY d(value,ordinality)),
 slots AS (
  SELECT document_id COLLATE pg_catalog."C" document_id,jsonb_agg(slot ORDER BY slot) slots
  FROM docs WHERE document_id IS NOT NULL GROUP BY document_id COLLATE pg_catalog."C")
 SELECT coalesce((SELECT jsonb_object_agg(document_id,slots) FROM slots),'{}'::jsonb),
  coalesce(array_agg(value->>'sourceText' ORDER BY slot),'{}'::text[]),
  coalesce(array_agg(false ORDER BY slot),'{}'::boolean[])
 INTO source_slots,source_texts,source_verified FROM docs;
 FOR operation IN SELECT value FROM jsonb_array_elements(input->'operations') LOOP
  IF operation->>'operation' IS DISTINCT FROM 'create_object' OR
   (operation->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb AND
    (input->'mutationProfile'=truss.runtime_owned_profile() AND operation->'ownership'->>'state'='owned'
     AND (operation->'ownership')-ARRAY['state','root']='{}'::jsonb) IS NOT TRUE) THEN
   RAISE EXCEPTION 'explicit selected create ownership required' USING ERRCODE='0A000'; END IF;
  WITH pinned AS MATERIALIZED (
   SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
   WHERE definition_pin=operation->>'typeDefinitionPin' AND kind='element' AND key_id='')
  SELECT t.* INTO STRICT selected_type FROM pinned p JOIN truss.type_def t
   ON t.definition_rev=p.rev AND t.definition_doc_ord=p.ord AND t.definition_document_id=p.doc_id
    AND t.module=p.module_id AND t.element=p.element_id
   WHERE t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL;
  PERFORM truss.runtime_module_writer_qualified(selected_type.document_id,selected_type.module,qualified_actor);
  IF NOT truss.runtime_object_values_readable_qualified(selected_type.type_id,qualified_actor) THEN RAISE EXCEPTION 'current property and item interpretation reader required' USING ERRCODE='42501';END IF;
  source_slot_list:=source_slots->selected_type.document_id;
  IF source_slot_list IS NULL THEN RAISE NO_DATA_FOUND;END IF;
  IF jsonb_array_length(source_slot_list)<>1 THEN RAISE TOO_MANY_ROWS;END IF;
  source_slot:=(source_slot_list->>0)::int;
  IF NOT source_verified[source_slot] THEN
   SELECT * INTO STRICT archive FROM truss.schema_doc d WHERE d.doc_id=selected_type.document_id ORDER BY d.rev DESC LIMIT 1;
   source_text:=source_texts[source_slot];
   IF convert_to(source_text,'UTF8') IS DISTINCT FROM convert_to(archive.document,'UTF8') THEN
    RAISE EXCEPTION 'complete original accepted source required' USING ERRCODE='22023';END IF;
   source_verified[source_slot]:=true;
  END IF;
  counted:=counted+1;
  metadata_items[counted]:=jsonb_build_object('operationIndex',counted-1,'typeId',selected_type.type_id::text,
   'documentId',selected_type.document_id,'moduleId',selected_type.module,'recordId',selected_type.element,
   'keys',(SELECT coalesce(jsonb_agg(jsonb_build_object('keyNumber',k.key_num::text,'keyId',k.key_id,
    'names',(SELECT jsonb_agg(p.name ORDER BY i.ord) FROM unnest(k.prop_ids) WITH ORDINALITY i(prop_id,ord)
      JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=k.type_id)) ORDER BY k.key_num),'[]'::jsonb)
    FROM truss.key_def k WHERE k.type_id=selected_type.type_id AND k.retired_rev IS NULL));
 END LOOP;
 metadata:=to_jsonb(metadata_items);
 RETURN convert_to(metadata::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.group_relationship_reference(selected_document text, selected_module text, selected_relationship text, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE relation truss.rel_def%ROWTYPE;owner record;pin text;encoded bytea;
BEGIN
 PERFORM truss.group_context(expected_release,expected_digest);
 IF selected_document IS NULL OR selected_module IS NULL OR selected_relationship IS NULL OR octet_length(selected_document) NOT BETWEEN 1 AND 4096 OR octet_length(selected_module) NOT BETWEEN 1 AND 4096 OR octet_length(selected_relationship) NOT BETWEEN 1 AND 4096 THEN RAISE EXCEPTION 'qualified bounded relationship selection required' USING ERRCODE='22023';END IF;
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 SELECT * INTO relation FROM truss.rel_def WHERE document_id=selected_document AND module=selected_module AND rel_id=selected_relationship AND retired_rev IS NULL;
 IF NOT FOUND THEN RETURN NULL;END IF;
 FOR owner IN SELECT DISTINCT t.document_id,t.module FROM truss.rel_endpoint e JOIN truss.type_def t ON t.type_id=e.source_type OR t.type_id=e.target_type WHERE e.rel_type_id=relation.rel_type_id LOOP
  IF NOT truss.runtime_can_read(owner.document_id,owner.module) THEN RETURN NULL;END IF;
 END LOOP;
 pin:=truss.runtime_relationship_pin(relation.rel_type_id);
 encoded:=convert_to(jsonb_build_object('kind','relationship','definitionPin',pin,'relationshipId',relation.rel_type_id::text,'authoredIdentity',relation.rel_id,
  'owner',jsonb_build_object('documentId',selected_document,'moduleId',selected_module))::text,'UTF8');
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 FOR owner IN SELECT DISTINCT t.document_id,t.module FROM truss.rel_endpoint e JOIN truss.type_def t ON t.type_id=e.source_type OR t.type_id=e.target_type WHERE e.rel_type_id=relation.rel_type_id LOOP
  IF NOT truss.runtime_can_read(owner.document_id,owner.module) THEN RETURN NULL;END IF;
 END LOOP;
 RETURN encoded;
END;
$function$

CREATE OR REPLACE FUNCTION truss.group_type_reference(selected_document text, selected_module text, selected_record text, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE context jsonb;person oid;policy truss.module_access%ROWTYPE;selected_type truss.type_def%ROWTYPE;source_pin record;
BEGIN
 context:=convert_from(truss.group_context(expected_release,expected_digest),'UTF8')::jsonb;
 IF selected_document IS NULL OR selected_module IS NULL OR selected_record IS NULL
 OR octet_length(selected_document) NOT BETWEEN 1 AND 4096 OR octet_length(selected_module) NOT BETWEEN 1 AND 4096
 OR octet_length(selected_record) NOT BETWEEN 1 AND 4096 THEN
  RAISE EXCEPTION 'bounded qualified type selection required' USING ERRCODE='22023'; END IF;
 person:=truss.runtime_person(false);
 SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module FOR SHARE NOWAIT;
 IF NOT FOUND OR NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
  SELECT person UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
  SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid WHERE r.rolname::text IN(policy.reader_role,policy.writer_role)) THEN RETURN NULL; END IF;
 SELECT * INTO selected_type FROM truss.type_def WHERE document_id=selected_document AND module=selected_module
  AND element=selected_record AND kind='record' AND retired_rev IS NULL AND NOT provisional;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO STRICT source_pin FROM truss.runtime_owned_definition_metadata('type',selected_type.type_id);
 person:=truss.runtime_person(false);
 IF NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
  SELECT person UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
  SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid WHERE r.rolname::text IN(policy.reader_role,policy.writer_role)) THEN RETURN NULL; END IF;
 RETURN convert_to(jsonb_build_object('kind','type','definitionPin',source_pin.definition_pin,'typeId',selected_type.type_id::text,
  'authoredIdentity',selected_type.element,'owner',jsonb_build_object('documentId',selected_document,'moduleId',selected_module))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.import_context(expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE context jsonb;installation truss.catalog_runtime_installation%ROWTYPE;bundle text;profiles jsonb;
BEGIN
 context:=convert_from(truss.group_context(expected_release,expected_digest),'UTF8')::jsonb;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();profiles:=truss.runtime_import_profiles();
 IF (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='key_reuse') IS DISTINCT FROM '"forbid"'::jsonb OR (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='journal_mode') IS DISTINCT FROM '"engine"'::jsonb THEN
  RAISE EXCEPTION 'installed engine/forbid import policy required' USING ERRCODE='0A000';END IF;
 SELECT encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('documentId',doc_id,'revision',doc_revision,'sha256',content_sha256) ORDER BY doc_id COLLATE "C"),'[]')::text,'UTF8')),'hex') INTO bundle
  FROM (SELECT DISTINCT ON(doc_id) doc_id,doc_revision,content_sha256 FROM truss.schema_doc WHERE rev>0 ORDER BY doc_id,rev DESC) documents;
 RETURN convert_to((context||profiles||jsonb_build_object('catalog',jsonb_build_object('revision',(SELECT rev::text FROM truss.schema_head WHERE id=1),'modelBundleSha256',bundle),
  'selectedConfiguration',jsonb_build_object('sourceEpoch',installation.source_epoch::text,'installationId',installation.installation_id::text,
   'generation',installation.import_policy_generation::text,'keyReuse','forbid','journalMode','engine','configurationProfile',profiles->'configurationProfile',
   'installedProducerInventorySha256',installation.release_sha256)))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.import_edge_identity(original_identity bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE context jsonb;identity jsonb;relation truss.rel_def%ROWTYPE;source_definition truss.type_def%ROWTYPE;target_definition truss.type_def%ROWTYPE;key text;edge_row truss.edge%ROWTYPE;result jsonb;matches int;owned_selection boolean:=false;endpoint record;
BEGIN
 -- Selection needs current custody/configuration and the key profile, not a
 -- reconstruction/hash of the complete catalog bundle for every record.
 PERFORM truss.group_context(expected_release,expected_digest);
 IF (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='key_reuse') IS DISTINCT FROM '"forbid"'::jsonb OR (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='journal_mode') IS DISTINCT FROM '"engine"'::jsonb THEN
  RAISE EXCEPTION 'installed engine/forbid import policy required' USING ERRCODE='0A000';END IF;
 context:=truss.runtime_import_profiles();
 IF original_identity IS NULL OR octet_length(original_identity) NOT BETWEEN 1 AND 65536 OR (convert_from(original_identity,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'bounded exact edge import identity required' USING ERRCODE='22023';END IF;
 identity:=convert_from(original_identity,'UTF8')::jsonb;
 IF identity->'profile'=truss.runtime_import_profiles()->'ownedImportProfile'
  AND identity-ARRAY['profile','identity']='{}'::jsonb THEN
  owned_selection:=true;identity:=identity->'identity';
 END IF;

 IF identity-ARRAY['relationshipDefinitionPin','source','target']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed edge import identity required' USING ERRCODE='22023';END IF;
 relation:=truss.runtime_operation_relationship(jsonb_build_object('operation','create_edge','relationshipDefinitionPin',identity->>'relationshipDefinitionPin'),'[]',0);
 PERFORM truss.runtime_module_writer(relation.document_id,relation.module);source_definition:=truss.runtime_condition_type(identity->'source');target_definition:=truss.runtime_condition_type(identity->'target');
 IF NOT truss.runtime_can_read(source_definition.document_id,source_definition.module) OR NOT truss.runtime_can_read(target_definition.document_id,target_definition.module) THEN RAISE EXCEPTION 'edge endpoint readers required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND source_type=source_definition.type_id AND target_type=target_definition.type_id) THEN RAISE EXCEPTION 'admitted edge endpoint pair required' USING ERRCODE='22023';END IF;
 LOCK TABLE truss.object IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 LOCK TABLE truss.edge IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 IF NOT owned_selection AND (relation.lifecycle IS DISTINCT FROM 'independent' OR EXISTS(SELECT 1 FROM truss.object o WHERE
  (o.id=(identity->'source'->>'id')::bigint AND o.type_id=source_definition.type_id OR o.id=(identity->'target'->>'id')::bigint AND o.type_id=target_definition.type_id)
  AND (o.root_id IS NOT NULL OR o.root_type IS NOT NULL))) THEN
  RAISE EXCEPTION 'rootless independent edge import profile required' USING ERRCODE='0A000';END IF;
 IF owned_selection THEN
  IF relation.lifecycle NOT IN ('owned','independent') THEN RAISE EXCEPTION 'supported owned import relationship required' USING ERRCODE='0A000';END IF;
  FOR endpoint IN SELECT DISTINCT t.document_id,t.module FROM truss.object o JOIN truss.type_def t ON t.type_id=o.root_type
   WHERE (o.id=(identity->'source'->>'id')::bigint AND o.type_id=source_definition.type_id
     OR o.id=(identity->'target'->>'id')::bigint AND o.type_id=target_definition.type_id) LOOP
   IF NOT truss.runtime_can_read(endpoint.document_id,endpoint.module) THEN RAISE EXCEPTION 'current imported endpoint root reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 END IF;
 PERFORM 1 FROM truss.object WHERE id=(identity->'source'->>'id')::bigint AND type_id=source_definition.type_id FOR UPDATE NOWAIT;
 PERFORM 1 FROM truss.object WHERE id=(identity->'target'->>'id')::bigint AND type_id=target_definition.type_id FOR UPDATE NOWAIT;
 key:=truss.runtime_edge_business_key(relation.rel_type_id,identity->'source',identity->'target');PERFORM truss.runtime_lock_edge_business_key(key);
 SELECT count(*) INTO matches FROM (SELECT 1 FROM truss.edge WHERE rel_type_id=relation.rel_type_id
  AND source_id=(identity->'source'->>'id')::bigint AND source_type=source_definition.type_id
  AND target_id=(identity->'target'->>'id')::bigint AND target_type=target_definition.type_id LIMIT 2) candidates;
 IF matches>1 THEN RAISE EXCEPTION 'ambiguous endpoint-only edge import identity' USING ERRCODE='22023';END IF;
 SELECT * INTO edge_row FROM truss.edge WHERE rel_type_id=relation.rel_type_id AND source_id=(identity->'source'->>'id')::bigint AND source_type=source_definition.type_id AND target_id=(identity->'target'->>'id')::bigint AND target_type=target_definition.type_id FOR UPDATE NOWAIT;
 IF FOUND THEN result:=jsonb_build_object('state','skipped','reason','live_identity','identity',jsonb_build_object('id',edge_row.id::text,'typeId',relation.rel_type_id::text,'definitionPin',identity->>'relationshipDefinitionPin','owner',jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module)));
 ELSIF EXISTS(SELECT 1 FROM truss.key_tombstone WHERE entity_kind='e' AND type_id=relation.rel_type_id AND key_num=0 AND k=key) THEN result:=jsonb_build_object('state','skipped','reason','reserved_identity');
 ELSE result:=jsonb_build_object('state','eligible','documentId',relation.document_id,'moduleId',relation.module,'relationshipDefinitionPin',identity->>'relationshipDefinitionPin');END IF;
 PERFORM truss.runtime_module_writer(relation.document_id,relation.module);
 IF NOT truss.runtime_can_read(source_definition.document_id,source_definition.module) OR NOT truss.runtime_can_read(target_definition.document_id,target_definition.module) THEN RAISE EXCEPTION 'current endpoint readers required' USING ERRCODE='42501';END IF;
 RETURN convert_to(result::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.import_identity_key_selection(original_identity bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE identity jsonb;selected truss.type_def%ROWTYPE;metadata bytea;parsed jsonb;component jsonb;component_index int:=0;
BEGIN
 IF original_identity IS NULL OR octet_length(original_identity) NOT BETWEEN 1 AND 1048576 OR (convert_from(original_identity,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'bounded unique primary identity required' USING ERRCODE='22023';END IF;
 identity:=convert_from(original_identity,'UTF8')::jsonb;
 IF jsonb_typeof(identity->'type'->'typeId') IS DISTINCT FROM 'string' OR identity->'type'->>'typeId' !~ '^[1-9][0-9]{0,9}$'
  OR length(identity->'type'->>'typeId')=10 AND (identity->'type'->>'typeId') COLLATE "C">'2147483647' THEN RAISE EXCEPTION 'exact import type ID required' USING ERRCODE='22023';END IF;
 SELECT * INTO selected FROM truss.type_def WHERE type_id=(identity->'type'->>'typeId')::int AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'accepted import type required' USING ERRCODE='22023';END IF;
 metadata:=truss.import_key_selection(selected.document_id,selected.module,selected.element,expected_release,expected_digest);
 IF identity->'type' IS DISTINCT FROM convert_from(metadata,'UTF8')::jsonb->'type' THEN RAISE EXCEPTION 'original qualified import type required' USING ERRCODE='22023';END IF;
 parsed:=convert_from(metadata,'UTF8')::jsonb;
 IF jsonb_typeof(identity->'components') IS DISTINCT FROM 'array' OR jsonb_array_length(identity->'components')<>jsonb_array_length(parsed->'components') THEN RAISE EXCEPTION 'complete ordered import key cells required' USING ERRCODE='22023';END IF;
 FOR component IN SELECT value FROM jsonb_array_elements(identity->'components') LOOP
  IF component->>'propertyId' IS DISTINCT FROM parsed->'components'->component_index->>'propertyId'
   OR component->>'definitionPin' IS DISTINCT FROM parsed->'components'->component_index->>'definitionPin'
   OR truss.valid_scalar_property(component->'value',parsed->'components'->component_index->>'scalarType',false,parsed->'components'->component_index->'facets') IS NOT TRUE THEN
   RAISE EXCEPTION 'exact declared import key cell required' USING ERRCODE='22023';END IF;
  component_index:=component_index+1;
 END LOOP;
 RETURN metadata;
END;
$function$

CREATE OR REPLACE FUNCTION truss.import_key_selection(selected_document text, selected_module text, selected_record text, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE context jsonb;selected truss.type_def%ROWTYPE;key_row truss.key_def%ROWTYPE;pin record;property truss.prop_def%ROWTYPE;components jsonb;component_buffer jsonb[]:=ARRAY[]::jsonb[];type_pin text;key_pin text;
BEGIN
 -- Selection needs current custody/configuration and the key profile, not a
 -- reconstruction/hash of the complete catalog bundle for every record.
 PERFORM truss.group_context(expected_release,expected_digest);
 IF (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='key_reuse') IS DISTINCT FROM '"forbid"'::jsonb OR (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='journal_mode') IS DISTINCT FROM '"engine"'::jsonb THEN
  RAISE EXCEPTION 'installed engine/forbid import policy required' USING ERRCODE='0A000';END IF;
 context:=truss.runtime_import_profiles();
 PERFORM truss.runtime_module_writer(selected_document,selected_module);
 SELECT * INTO selected FROM truss.type_def WHERE document_id=selected_document AND module=selected_module AND element=selected_record AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'accepted import record type required' USING ERRCODE='22023';END IF;
 SELECT * INTO key_row FROM truss.key_def WHERE type_id=selected.type_id AND is_primary AND retired_rev IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'import primary key required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',selected.type_id);type_pin:=pin.definition_pin;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',selected.type_id,key_row.key_num);key_pin:=pin.definition_pin;
 FOR property IN SELECT p.* FROM unnest(key_row.prop_ids) WITH ORDINALITY i(prop_id,ord) JOIN truss.prop_def p ON p.type_id=selected.type_id AND p.prop_id=i.prop_id ORDER BY i.ord LOOP
  IF property.scalar_type NOT IN ('string','integer','decimal','boolean','binary') OR property.scalar_type IS NULL OR property.cardinality<>'one' OR property.nullability<>'required' OR property.home<>'json' OR property.retired_rev IS NOT NULL THEN RAISE EXCEPTION 'selected string primary key required' USING ERRCODE='0A000';END IF;
  IF NOT truss.runtime_can_read(selected_document,property.declaration_module) THEN RAISE EXCEPTION 'primary property reader required' USING ERRCODE='42501';END IF;
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('property',selected.type_id,property.prop_id);
  component_buffer:=array_append(component_buffer,jsonb_build_object('name',property.name,'propertyId',property.prop_id::text,'definitionPin',pin.definition_pin,'scalarType',property.scalar_type,'facets',coalesce(property.facets,'{}'::jsonb)));
 END LOOP;
 FOR property IN SELECT p.* FROM unnest(key_row.prop_ids) i(prop_id) JOIN truss.prop_def p ON p.type_id=selected.type_id AND p.prop_id=i.prop_id LOOP
  IF NOT truss.runtime_can_read(selected_document,property.declaration_module) THEN RAISE EXCEPTION 'current primary declaration reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 PERFORM truss.runtime_module_writer(selected_document,selected_module);
 components:=to_jsonb(component_buffer);
 RETURN convert_to(jsonb_build_object('recordId',selected.element,'type',jsonb_build_object('typeId',selected.type_id::text,'definitionPin',type_pin,'owner',jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module)),
  'keyNumber',key_row.key_num::text,'keyId',key_row.key_id,'keyDefinitionPin',key_pin,'keyEncodingProfile',context->'importKeyProfile','components',components)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.import_object_identity(original_identity bytea, original_document bytea, tuple_bytes bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE identity jsonb;selected truss.type_def%ROWTYPE;metadata jsonb;key_row truss.key_def%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;
 archive truss.schema_doc%ROWTYPE;component jsonb;values_text text[]:=ARRAY[]::text[];values_cells jsonb;values_buffer jsonb[]:=ARRAY[]::jsonb[];key_facets jsonb;facets_buffer jsonb[]:=ARRAY[]::jsonb[];fields jsonb;fields_buffer jsonb[]:=ARRAY[]::jsonb[];component_index int:=0;pin record;namespace bytea;transport bytea;observed record;member truss.object_key_bucket%ROWTYPE;object_row truss.object%ROWTYPE;result jsonb;owned_selection boolean:=false;root_owner record;
BEGIN
 IF original_identity IS NULL OR octet_length(original_identity) NOT BETWEEN 1 AND 1048576 OR (convert_from(original_identity,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'bounded unique import identity required' USING ERRCODE='22023';END IF;
 identity:=convert_from(original_identity,'UTF8')::jsonb;
 IF identity->'profile'=truss.runtime_import_profiles()->'ownedImportProfile'
  AND identity-ARRAY['profile','identity']='{}'::jsonb THEN
  owned_selection:=true;identity:=identity->'identity';
 END IF;

 IF identity-ARRAY['operation','type','keyNumber','keyDefinitionPin','keyEncodingProfile','components']<>'{}'::jsonb OR identity->>'operation' IS DISTINCT FROM 'object_key'
  OR (identity->'type')-ARRAY['typeId','definitionPin','owner']<>'{}'::jsonb OR jsonb_typeof(identity->'type'->'typeId') IS DISTINCT FROM 'string'
  OR identity->'type'->>'typeId' !~ '^[1-9][0-9]{0,9}$' OR length(identity->'type'->>'typeId')=10 AND (identity->'type'->>'typeId') COLLATE "C">'2147483647'
  OR jsonb_typeof(identity->'components') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'closed exact primary identity required' USING ERRCODE='22023';END IF;
 SELECT * INTO selected FROM truss.type_def WHERE type_id=(identity->'type'->>'typeId')::int AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'known import type required' USING ERRCODE='22023';END IF;
 metadata:=convert_from(truss.import_key_selection(selected.document_id,selected.module,selected.element,expected_release,expected_digest),'UTF8')::jsonb;
 IF jsonb_typeof(identity->'keyNumber') IS DISTINCT FROM 'string' OR jsonb_typeof(identity->'keyDefinitionPin') IS DISTINCT FROM 'string' OR identity->'type' IS DISTINCT FROM metadata->'type' OR identity->>'keyNumber' IS DISTINCT FROM metadata->>'keyNumber'
  OR identity->>'keyDefinitionPin' IS DISTINCT FROM metadata->>'keyDefinitionPin' OR (identity->'keyEncodingProfile' IS DISTINCT FROM metadata->'keyEncodingProfile' AND NOT ((identity->'keyEncodingProfile'='{"identity":"truss-selected-umf-string-key","version":"0.1","sha256":"07e1b99b22803e55a378f8068a6b80454b7581129c66eabcb117545746a16625"}'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(identity->'components') c WHERE c.value->'value'->>'kind' IS DISTINCT FROM 'string')) IS TRUE))
  OR jsonb_array_length(identity->'components')<>jsonb_array_length(metadata->'components') THEN RAISE EXCEPTION 'actual complete primary definition required' USING ERRCODE='22023';END IF;
 IF NOT owned_selection THEN
  SELECT * INTO STRICT archive FROM truss.schema_doc WHERE doc_id=selected.document_id ORDER BY rev DESC LIMIT 1;
  IF original_document IS DISTINCT FROM convert_to(archive.document,'UTF8') THEN RAISE EXCEPTION 'caller-known original document required' USING ERRCODE='22023';END IF;
 END IF;
 FOR component IN SELECT value FROM jsonb_array_elements(identity->'components') LOOP
  IF jsonb_typeof(component->'propertyId') IS DISTINCT FROM 'string' OR jsonb_typeof(component->'definitionPin') IS DISTINCT FROM 'string' OR component-ARRAY['propertyId','definitionPin','value']<>'{}'::jsonb OR component->>'propertyId' IS DISTINCT FROM metadata->'components'->component_index->>'propertyId'
   OR component->>'definitionPin' IS DISTINCT FROM metadata->'components'->component_index->>'definitionPin' OR truss.valid_scalar_property(component->'value',metadata->'components'->component_index->>'scalarType',false,metadata->'components'->component_index->'facets') IS NOT TRUE THEN RAISE EXCEPTION 'exact ordered primary component required' USING ERRCODE='22023';END IF;
  values_buffer:=array_append(values_buffer,component->'value');
  facets_buffer:=array_append(facets_buffer,metadata->'components'->component_index->'facets');
  fields_buffer:=array_append(fields_buffer,jsonb_build_object('name',metadata->'components'->component_index->>'name','value',component->'value'));
  component_index:=component_index+1;
 END LOOP;
 values_cells:=to_jsonb(values_buffer);key_facets:=to_jsonb(facets_buffer);fields:=to_jsonb(fields_buffer);
 IF tuple_bytes IS NOT NULL THEN RAISE EXCEPTION 'client key encoding is no longer accepted' USING ERRCODE='22023';END IF;
 tuple_bytes:=truss.derive_catalog_key_tuple(selected.type_id,(metadata->>'keyNumber')::smallint,values_cells);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 namespace:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,'sourceEpoch',installation.source_epoch::text,
  'typeId',metadata->'type'->>'typeId','keyNumber',metadata->>'keyNumber','definitionPin',metadata->>'keyDefinitionPin','encoding','umf-key-tuple-v1')::text,'UTF8');
 LOCK TABLE truss.object IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 LOCK TABLE truss.edge IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 transport:=convert_to('umf-key-tuple-v1:hex:'||encode(tuple_bytes,'hex'),'UTF8');SELECT * INTO STRICT observed FROM truss.lock_string_key_bucket(namespace,transport);
 IF cardinality(observed.member_ids)>1 THEN RAISE EXCEPTION 'unique live primary identity required' USING ERRCODE='55000';END IF;
 IF cardinality(observed.member_ids)=1 THEN
  SELECT * INTO STRICT member FROM truss.object_key_bucket WHERE storage_row_id=observed.member_ids[1];
  SELECT * INTO STRICT object_row FROM truss.object WHERE id=member.object_id AND type_id=selected.type_id FOR UPDATE NOWAIT;
  IF object_row.root_id IS NOT NULL OR object_row.root_type IS NOT NULL THEN
   IF NOT owned_selection THEN RAISE EXCEPTION 'owned object import requires an explicit supported ownership import profile' USING ERRCODE='0A000';END IF;
   SELECT t.document_id,t.module INTO STRICT root_owner FROM truss.type_def t WHERE t.type_id=object_row.root_type;
   IF NOT truss.runtime_can_read(root_owner.document_id,root_owner.module) THEN
    RAISE EXCEPTION 'current imported root reader required' USING ERRCODE='42501';END IF;
  END IF;
  result:=jsonb_build_object('state','skipped','reason','live_identity','identity',jsonb_build_object('id',object_row.id::text,'typeId',selected.type_id::text,'definitionPin',metadata->'type'->>'definitionPin','owner',metadata->'type'->'owner'));
 ELSIF cardinality(observed.reservation_ids)>0 THEN result:=jsonb_build_object('state','skipped','reason','reserved_identity');
 ELSE result:=jsonb_build_object('state','eligible','documentId',selected.document_id,'moduleId',selected.module,'recordId',selected.element,'definitionPin',metadata->'type'->>'definitionPin','primaryFields',fields);END IF;
 PERFORM truss.import_key_selection(selected.document_id,selected.module,selected.element,expected_release,expected_digest);
 PERFORM truss.runtime_module_writer(selected.document_id,selected.module);
 RETURN convert_to(result::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.import_report_record_authority(original_identity bytea, kind text, expected_release text, expected_digest text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE envelope jsonb;outcome_identity jsonb;object_row truss.object;edge_row truss.edge;endpoint record;identity jsonb;relation truss.rel_def%ROWTYPE;source_definition truss.type_def%ROWTYPE;target_definition truss.type_def%ROWTYPE;owned_selection boolean:=false;root_owner record;
BEGIN
 IF original_identity IS NULL OR octet_length(original_identity) NOT BETWEEN 1 AND 2097152
  OR (convert_from(original_identity,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
  RAISE EXCEPTION 'bounded original report selection and outcome required' USING ERRCODE='22023';END IF;
 envelope:=convert_from(original_identity,'UTF8')::jsonb;
 IF envelope-ARRAY['originalIdentity','outcomeIdentity']<>'{}'::jsonb OR NOT envelope ?& ARRAY['originalIdentity','outcomeIdentity']
  OR jsonb_typeof(envelope->'originalIdentity') IS DISTINCT FROM 'object'
  OR jsonb_typeof(envelope->'outcomeIdentity') NOT IN ('object','null') THEN
  RAISE EXCEPTION 'exact original report outcome envelope required' USING ERRCODE='22023';END IF;
 outcome_identity:=nullif(envelope->'outcomeIdentity','null'::jsonb);
 IF outcome_identity IS NOT NULL AND (outcome_identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb
  OR jsonb_typeof(outcome_identity->'id') IS DISTINCT FROM 'string' OR outcome_identity->>'id' !~ '^[1-9][0-9]{0,18}$') THEN
  RAISE EXCEPTION 'retained typed report outcome required' USING ERRCODE='22023';END IF;
 original_identity:=convert_to((envelope->'originalIdentity')::text,'UTF8');
 IF envelope->'originalIdentity'->'profile'=truss.runtime_import_profiles()->'ownedImportProfile'
  AND (envelope->'originalIdentity')-ARRAY['profile','identity']='{}'::jsonb THEN
  owned_selection:=true;original_identity:=convert_to((envelope->'originalIdentity'->'identity')::text,'UTF8');
 END IF;

 IF kind='object' THEN
  IF original_identity IS NULL OR octet_length(original_identity) NOT BETWEEN 1 AND 1048576 OR (convert_from(original_identity,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'bounded unique report identity required' USING ERRCODE='22023';END IF;
  identity:=convert_from(original_identity,'UTF8')::jsonb;
  IF jsonb_typeof(identity->'type'->'typeId') IS DISTINCT FROM 'string' OR identity->'type'->>'typeId' !~ '^[1-9][0-9]{0,9}$'
   OR length(identity->'type'->>'typeId')=10 AND (identity->'type'->>'typeId') COLLATE "C">'2147483647' THEN RAISE EXCEPTION 'exact report type ID required' USING ERRCODE='22023';END IF;
  SELECT t.* INTO source_definition FROM truss.type_def t WHERE t.type_id=(identity->'type'->>'typeId')::int AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'known report type required' USING ERRCODE='22023';END IF;
  IF identity->'type' IS DISTINCT FROM convert_from(truss.import_key_selection(source_definition.document_id,source_definition.module,source_definition.element,expected_release,expected_digest),'UTF8')::jsonb->'type' THEN RAISE EXCEPTION 'original report type identity required' USING ERRCODE='22023';END IF;
  IF outcome_identity IS NOT NULL THEN
   IF outcome_identity-'id' IS DISTINCT FROM identity->'type' THEN RAISE EXCEPTION 'original object report outcome type required' USING ERRCODE='22023';END IF;
   SELECT * INTO object_row FROM truss.object WHERE id=(outcome_identity->>'id')::bigint AND type_id=source_definition.type_id;
   IF FOUND AND (object_row.root_id IS NOT NULL OR object_row.root_type IS NOT NULL) THEN
    IF NOT owned_selection THEN RAISE EXCEPTION 'rootless object import report profile required' USING ERRCODE='0A000';END IF;
    SELECT t.document_id,t.module INTO STRICT root_owner FROM truss.type_def t WHERE t.type_id=object_row.root_type;
    IF NOT truss.runtime_can_read(root_owner.document_id,root_owner.module) THEN RAISE EXCEPTION 'current imported root report reader required' USING ERRCODE='42501';END IF;
   END IF;
  END IF;
  RETURN;
 END IF;
 IF kind<>'edge' THEN RAISE EXCEPTION 'selected report record required' USING ERRCODE='22023';END IF;
 identity:=convert_from(original_identity,'UTF8')::jsonb;
 relation:=truss.runtime_operation_relationship(jsonb_build_object('operation','create_edge','relationshipDefinitionPin',identity->>'relationshipDefinitionPin'),'[]',0);
 PERFORM truss.runtime_module_writer(relation.document_id,relation.module);
 IF owned_selection THEN
  PERFORM truss.runtime_owned_import_reference(convert_to((identity->'source')::text,'UTF8'),expected_release,expected_digest);
  PERFORM truss.runtime_owned_import_reference(convert_to((identity->'target')::text,'UTF8'),expected_release,expected_digest);
  SELECT * INTO STRICT source_definition FROM truss.type_def WHERE type_id=(identity->'source'->'type'->>'typeId')::int;
  SELECT * INTO STRICT target_definition FROM truss.type_def WHERE type_id=(identity->'target'->'type'->>'typeId')::int;
  IF relation.lifecycle NOT IN ('owned','independent') THEN RAISE EXCEPTION 'supported owned import report relationship required' USING ERRCODE='0A000';END IF;
 ELSE
  source_definition:=truss.runtime_condition_type(identity->'source');target_definition:=truss.runtime_condition_type(identity->'target');
  IF relation.lifecycle IS DISTINCT FROM 'independent' THEN RAISE EXCEPTION 'independent import report profile required' USING ERRCODE='0A000';END IF;
 END IF;
 IF outcome_identity IS NOT NULL THEN
  IF outcome_identity->>'typeId' IS DISTINCT FROM relation.rel_type_id::text
   OR outcome_identity->>'definitionPin' IS DISTINCT FROM identity->>'relationshipDefinitionPin'
   OR outcome_identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module) THEN
   RAISE EXCEPTION 'original edge report outcome type required' USING ERRCODE='22023';END IF;
  SELECT * INTO edge_row FROM truss.edge WHERE id=(outcome_identity->>'id')::bigint AND rel_type_id=relation.rel_type_id;
  IF FOUND THEN
   FOR endpoint IN SELECT o.*,t.document_id,t.module FROM truss.object o JOIN truss.type_def t ON t.type_id=o.type_id
    WHERE (o.id=edge_row.source_id AND o.type_id=edge_row.source_type OR o.id=edge_row.target_id AND o.type_id=edge_row.target_type) LOOP
    IF NOT truss.runtime_can_read(endpoint.document_id,endpoint.module) THEN RAISE EXCEPTION 'current retained report endpoint reader required' USING ERRCODE='42501';END IF;
    IF endpoint.root_id IS NOT NULL OR endpoint.root_type IS NOT NULL THEN
     IF NOT owned_selection THEN RAISE EXCEPTION 'rootless endpoint import report profile required' USING ERRCODE='0A000';END IF;
     SELECT t.document_id,t.module INTO STRICT root_owner FROM truss.type_def t WHERE t.type_id=endpoint.root_type;
     IF NOT truss.runtime_can_read(root_owner.document_id,root_owner.module) THEN RAISE EXCEPTION 'current imported endpoint root report reader required' USING ERRCODE='42501';END IF;
    END IF;
   END LOOP;
  END IF;
 END IF;
 IF NOT truss.runtime_can_read(source_definition.document_id,source_definition.module) OR NOT truss.runtime_can_read(target_definition.document_id,target_definition.module) THEN RAISE EXCEPTION 'current report endpoint readers required' USING ERRCODE='42501';END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.key_read_selection(selected_document text, selected_module text, selected_record text, selected_key text, original_document bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;record_type truss.type_def%ROWTYPE;key_definition truss.key_def%ROWTYPE;archive truss.schema_doc%ROWTYPE;component record;counted int:=0;revision int;
BEGIN
 PERFORM truss.runtime_person(false);
 IF selected_document IS NULL OR selected_module IS NULL OR selected_record IS NULL OR selected_key IS NULL
 OR octet_length(selected_document) NOT BETWEEN 1 AND 4096 OR octet_length(selected_module) NOT BETWEEN 1 AND 4096 OR octet_length(selected_record) NOT BETWEEN 1 AND 4096 OR octet_length(selected_key) NOT BETWEEN 1 AND 4096
 OR (original_document IS NOT NULL AND octet_length(original_document) NOT BETWEEN 1 AND 1048576) THEN RAISE EXCEPTION 'bounded key selection required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'selected installed runtime required' USING ERRCODE='0A000';END IF;
 IF current_setting('transaction_read_only')='on' THEN SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 ELSE SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;END IF;
 IF revision<1 THEN RAISE EXCEPTION 'accepted key catalog required' USING ERRCODE='0A000';END IF;
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 SELECT * INTO record_type FROM truss.type_def WHERE document_id=selected_document AND module=selected_module AND element=selected_record AND kind='record' AND NOT provisional AND retired_rev IS NULL AND since_rev<=revision;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF NOT truss.runtime_object_values_readable(record_type.type_id) THEN RETURN NULL;END IF;
 SELECT * INTO key_definition FROM truss.key_def WHERE type_id=record_type.type_id AND key_id=selected_key AND retired_rev IS NULL;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF cardinality(key_definition.prop_ids) NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'bounded complete key required' USING ERRCODE='0A000';END IF;
 FOR component IN SELECT DISTINCT p.declaration_module FROM unnest(key_definition.prop_ids) i(prop_id) JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=record_type.type_id LOOP
  IF NOT truss.runtime_can_read(selected_document,component.declaration_module) THEN RETURN NULL;END IF;
 END LOOP;
 FOR component IN SELECT p.* FROM unnest(key_definition.prop_ids) WITH ORDINALITY k(prop_id,n) JOIN truss.prop_def p ON p.prop_id=k.prop_id AND p.type_id=record_type.type_id ORDER BY k.n LOOP
  counted:=counted+1;
  IF component.scalar_type NOT IN ('string','integer','decimal','boolean','binary') OR component.scalar_type IS NULL OR component.nullability IS DISTINCT FROM 'required' OR component.cardinality IS DISTINCT FROM 'one' OR component.home IS DISTINCT FROM 'json' OR component.retired_rev IS NOT NULL THEN RAISE EXCEPTION 'supported string key required' USING ERRCODE='0A000';END IF;
 END LOOP;
 IF counted<>cardinality(key_definition.prop_ids) THEN RAISE EXCEPTION 'complete native key definition required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT archive FROM truss.schema_doc WHERE doc_id=record_type.document_id ORDER BY rev DESC LIMIT 1;
 IF (original_document IS NOT NULL AND original_document IS DISTINCT FROM convert_to(archive.document,'UTF8')) OR archive.doc_id IS DISTINCT FROM selected_document OR encode(sha256(convert_to(archive.document,'UTF8')),'hex') IS DISTINCT FROM archive.content_sha256 THEN RAISE EXCEPTION 'original accepted key source required' USING ERRCODE='22023';END IF;
 PERFORM truss.runtime_person(false);
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 FOR component IN SELECT DISTINCT p.declaration_module FROM unnest(key_definition.prop_ids) i(prop_id) JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=record_type.type_id LOOP
  IF NOT truss.runtime_can_read(selected_document,component.declaration_module) THEN RETURN NULL;END IF;
 END LOOP;
 PERFORM truss.runtime_person(false);
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM revision THEN
  RAISE EXCEPTION 'catalog changed during key selection' USING ERRCODE='55P03';END IF;
 RETURN convert_to(jsonb_build_object('typeId',record_type.type_id,'keyNumber',key_definition.key_num,'componentCount',counted,'catalogRevision',revision)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.lock_string_key_bucket(original_namespace bytea, canonical_key bytea)
 RETURNS TABLE(generation bigint, member_ids bigint[], reservation_ids bigint[])
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
DECLARE namespace_route bytea;key_route bytea;guard_generation bigint;
 candidate_count bigint;candidate_bytes bigint;
 inserted_namespace bytea;inserted_key bytea;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'current key observation requires READ COMMITTED' USING ERRCODE='0A000'; END IF;
 IF original_namespace IS NULL OR octet_length(original_namespace) NOT BETWEEN 1 AND 65536
  OR canonical_key IS NULL OR octet_length(canonical_key) NOT BETWEEN 1 AND 1048576 THEN
  RAISE EXCEPTION 'bounded original key routing bytes required' USING ERRCODE='22023'; END IF;
 IF convert_from(canonical_key,'UTF8') !~ '^umf-key-tuple-v1:hex:([0-9a-f]{2})+$' THEN
  RAISE EXCEPTION 'selected canonical key transport required' USING ERRCODE='22023'; END IF;
 namespace_route:=sha256(original_namespace);key_route:=sha256(canonical_key);
 -- Graph mutation and catalog key writes share one finite transaction gate.
 -- Row guards still protect exact key identity and membership observations.
 IF NOT pg_try_advisory_xact_lock(1953658227,1735549296) THEN
  RAISE EXCEPTION 'key route is in flight' USING ERRCODE='55P03'; END IF;
 SELECT g.generation INTO guard_generation FROM truss.key_bucket_guard g
  WHERE namespace_sha256=namespace_route AND key_sha256=key_route FOR UPDATE NOWAIT;
 IF NOT FOUND THEN
  INSERT INTO truss.key_bucket_guard(namespace_sha256,key_sha256,generation)
   VALUES(namespace_route,key_route,0)
   RETURNING namespace_sha256,key_sha256,key_bucket_guard.generation INTO inserted_namespace,inserted_key,guard_generation;
  IF NOT FOUND OR inserted_namespace IS DISTINCT FROM namespace_route OR inserted_key IS DISTINCT FROM key_route OR guard_generation IS DISTINCT FROM 0 THEN
   RAISE EXCEPTION 'exact zero-generation native key guard creation required' USING ERRCODE='55000'; END IF;
  SELECT g.generation INTO guard_generation FROM truss.key_bucket_guard g
   WHERE namespace_sha256=namespace_route AND key_sha256=key_route FOR UPDATE NOWAIT;
  IF NOT FOUND OR guard_generation IS DISTINCT FROM 0 THEN
   RAISE EXCEPTION 'exact native key guard readback required' USING ERRCODE='55000'; END IF;
 END IF;
 SELECT count(*),coalesce(sum(size),0) INTO candidate_count,candidate_bytes FROM (
  (SELECT octet_length(namespace_bytes)::bigint+octet_length(key_bytes) AS size
   FROM truss.object_key_bucket WHERE namespace_sha256=namespace_route AND key_sha256=key_route LIMIT 10001)
  UNION ALL
  (SELECT octet_length(namespace_bytes)::bigint+octet_length(key_bytes) AS size
   FROM truss.object_key_reservation_bucket WHERE namespace_sha256=namespace_route AND key_sha256=key_route LIMIT 10001)
 ) candidates;
 IF candidate_count>10000 OR candidate_bytes>16777216 THEN
  RAISE EXCEPTION 'complete collision bucket exceeds limits' USING ERRCODE='54000'; END IF;
 IF guard_generation=9223372036854775807 THEN
  RAISE EXCEPTION 'key guard generation exhausted' USING ERRCODE='54000'; END IF;
 RETURN QUERY SELECT guard_generation,
  ARRAY(SELECT storage_row_id FROM truss.object_key_bucket WHERE namespace_sha256=namespace_route AND key_sha256=key_route
    AND namespace_bytes=original_namespace AND key_bytes=canonical_key ORDER BY storage_row_id),
  ARRAY(SELECT storage_row_id FROM truss.object_key_reservation_bucket WHERE namespace_sha256=namespace_route AND key_sha256=key_route
    AND namespace_bytes=original_namespace AND key_bytes=canonical_key ORDER BY storage_row_id);
END;
$function$

CREATE OR REPLACE FUNCTION truss.logical_scalar_cell(cell jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF truss.valid_scalar_cell(cell) IS NOT TRUE THEN RAISE EXCEPTION 'valid exact scalar cell required' USING ERRCODE='55000';END IF;
 IF cell->>'kind'='null' THEN RETURN 'null'::jsonb;
 ELSIF cell->>'kind'='string' THEN RETURN cell->'text';
 ELSIF cell->>'kind'='boolean' THEN RETURN cell->'value';
 ELSE RETURN cell;END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.lookup_import_source(selection jsonb, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE entity jsonb;kind char(1);ledger truss.runtime_import_source%ROWTYPE;attempt truss.runtime_object_attempt%ROWTYPE;
 identity jsonb;actual jsonb;content bytea;result bytea;creation jsonb;captured_revision int;frontier xid8;
 source_operation jsonb;source_result jsonb;legacy_input jsonb;
BEGIN
 entity:=truss.runtime_history_entity(selection,expected_release,expected_digest);
 captured_revision:=(SELECT rev FROM truss.schema_head WHERE id=1);frontier:=pg_snapshot_xmin(pg_current_snapshot());
 IF maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN RAISE EXCEPTION 'bounded provenance output required' USING ERRCODE='22023';END IF;
 kind:=CASE entity->>'kind' WHEN 'object' THEN 'o' ELSE 'e' END;
 SELECT * INTO ledger FROM truss.runtime_import_source WHERE entity_kind=kind AND entity_id=(entity->>'id')::bigint;
 IF NOT FOUND THEN
  IF EXISTS(SELECT 1 FROM truss.record_source WHERE entity_kind=kind AND entity_id=(entity->>'id')::bigint) THEN
   RAISE EXCEPTION 'original source ledger required' USING ERRCODE='55000';END IF;
  -- Absence is meaningful only for an authorized original committed creation.
  creation:=convert_from(truss.read_history(selection,NULL,1,4096,maximum_bytes,expected_release,expected_digest),'UTF8')::jsonb;
  IF creation->>'outcome' IS DISTINCT FROM 'record' THEN RAISE EXCEPTION 'original committed creation required' USING ERRCODE='P1010';END IF;
  IF creation->'event'->>'writerXid' IS NULL OR (creation->'event'->>'writerXid')::xid8>=frontier THEN
   RAISE EXCEPTION 'creation outside fixed source observation' USING ERRCODE='P1010';END IF;
  IF EXISTS(SELECT 1 FROM truss.runtime_import_source WHERE entity_kind=kind AND entity_id=(entity->>'id')::bigint)
   OR EXISTS(SELECT 1 FROM truss.record_source WHERE entity_kind=kind AND entity_id=(entity->>'id')::bigint) THEN
   RAISE EXCEPTION 'source absence observation changed' USING ERRCODE='55P03';END IF;
  result:=convert_to('{"outcome":"absent"}','UTF8');
 ELSE
  IF ledger.writer_xid>=frontier THEN RAISE EXCEPTION 'committed provenance unavailable' USING ERRCODE='P1010';END IF;
  SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=ledger.group_attempt_id;
  IF attempt.context->'mutationProfile'=truss.runtime_owned_profile() THEN
   SELECT p.plan->'operation',p.result INTO STRICT source_operation,source_result
   FROM truss.runtime_owned_operation p
   WHERE p.attempt_id=attempt.id AND p.operation_index=ledger.operation_index AND p.writer_xid=ledger.writer_xid;
  ELSE
   legacy_input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
   source_operation:=legacy_input->'operations'->ledger.operation_index;
   source_result:=attempt.results->ledger.operation_index;
   IF convert_from(ledger.original_record,'UTF8')::jsonb->'payloadProfile' IS DISTINCT FROM truss.runtime_import_profiles()->'ownedImportPayloadProfile'
    AND attempt.next_index<>1 THEN
    RAISE EXCEPTION 'legacy singleton import creation required' USING ERRCODE='55000';END IF;
  END IF;
  identity:=source_result->'identity';
  IF NOT attempt.complete OR ledger.operation_index<0 OR ledger.operation_index>=attempt.next_index
   OR attempt.writer_xid IS DISTINCT FROM ledger.writer_xid
   OR source_result->>'outcome' IS DISTINCT FROM 'created' OR identity->>'id' IS DISTINCT FROM entity->>'id'
   OR identity->>'typeId' IS DISTINCT FROM entity->>'typeId'
   OR identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',entity->>'documentId','moduleId',entity->>'moduleId')
   OR source_operation->>'operation' IS DISTINCT FROM
      (CASE kind WHEN 'o' THEN 'create_object' ELSE 'create_edge' END) THEN
   RAISE EXCEPTION 'original qualified import creation required' USING ERRCODE='55000';END IF;
  IF NOT truss.runtime_receipt_can_read(attempt.id) THEN RAISE EXCEPTION 'original creation dependency reader required' USING ERRCODE='42501';END IF;
  SELECT to_jsonb(s) INTO actual FROM truss.record_source s WHERE entity_kind=kind AND entity_id=(entity->>'id')::bigint;
  IF actual IS NULL OR actual->>'entity_kind' IS DISTINCT FROM kind::text
   OR actual->>'entity_id' IS DISTINCT FROM entity->>'id' THEN
   RAISE EXCEPTION 'retained native source correspondence required' USING ERRCODE='55000';END IF;
  content:=convert_to(actual::text,'UTF8');
  result:=convert_to(jsonb_build_object('outcome','found','loadId',actual->>'load_id','writerXid',ledger.writer_xid::text,
   'contentBase64',replace(encode(content,'base64'),chr(10),''),'sha256',encode(sha256(content),'hex'))::text,'UTF8');
  IF NOT truss.runtime_receipt_can_read(attempt.id) THEN RAISE EXCEPTION 'current creation dependency reader required' USING ERRCODE='42501';END IF;
 END IF;
 PERFORM truss.runtime_history_entity(selection,expected_release,expected_digest);
 IF captured_revision IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1) THEN RAISE EXCEPTION 'provenance context changed' USING ERRCODE='55P03';END IF;
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'provenance exceeds byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.lookup_string_key(selected_document text, selected_module text, selected_record text, selected_key text, original_document bytea, values_bytes bytea, tuple_bytes bytea, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE selection_bytes bytea;selection jsonb;values_json jsonb;actual_values text[];installation truss.catalog_runtime_installation%ROWTYPE;source_pin record;namespace bytea;transport bytea;candidate_count bigint;candidate_bytes bigint;matches bigint;member truss.object_key_bucket%ROWTYPE;result bytea;component record;candidate record;buffered_values text[];key_facets jsonb;buffered_cells jsonb;
BEGIN
 selection_bytes:=truss.key_read_selection(selected_document,selected_module,selected_record,selected_key,original_document,expected_release,expected_digest);
 IF selection_bytes IS NULL THEN RETURN NULL;END IF;
 selection:=convert_from(selection_bytes,'UTF8')::jsonb;
 IF maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 OR values_bytes IS NULL OR octet_length(values_bytes) NOT BETWEEN 1 AND 1048576 OR tuple_bytes IS NOT NULL THEN RAISE EXCEPTION 'bounded key values required' USING ERRCODE='22023';END IF;
 values_json:=convert_from(values_bytes,'UTF8')::jsonb;
 IF jsonb_typeof(values_json) IS DISTINCT FROM 'array' OR jsonb_array_length(values_json)<>(selection->>'componentCount')::int THEN RAISE EXCEPTION 'ordered exact key values required' USING ERRCODE='22023';END IF;
 -- Retain the original bare-string native entry shape while admitting typed cells.
 SELECT jsonb_agg(CASE WHEN jsonb_typeof(v.value)='string' THEN jsonb_build_object('kind','string','text',v.value) ELSE v.value END ORDER BY v.n)
  INTO values_json FROM jsonb_array_elements(values_json) WITH ORDINALITY v(value,n);
 SELECT jsonb_agg(coalesce(p.facets,'{}'::jsonb) ORDER BY i.ord) INTO key_facets FROM truss.key_def k
  CROSS JOIN LATERAL unnest(k.prop_ids) WITH ORDINALITY i(prop_id,ord) JOIN truss.prop_def p ON p.type_id=k.type_id AND p.prop_id=i.prop_id
  WHERE k.type_id=(selection->>'typeId')::int AND k.key_num=(selection->>'keyNumber')::smallint;
 tuple_bytes:=truss.derive_catalog_key_tuple((selection->>'typeId')::int,(selection->>'keyNumber')::smallint,values_json);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 SELECT * INTO STRICT source_pin FROM truss.runtime_owned_definition_metadata('key',(selection->>'typeId')::int,(selection->>'keyNumber')::int);
 namespace:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,
  'sourceEpoch',installation.source_epoch::text,'typeId',selection->>'typeId','keyNumber',selection->>'keyNumber',
  'definitionPin',source_pin.definition_pin,'encoding','umf-key-tuple-v1')::text,'UTF8');
 transport:=convert_to('umf-key-tuple-v1:hex:'||encode(tuple_bytes,'hex'),'UTF8');
 IF octet_length(transport)>1048576 THEN RAISE EXCEPTION 'key transport budget exceeded' USING ERRCODE='54000';END IF;
 candidate_count:=0;candidate_bytes:=0;matches:=0;
 -- One bounded indexed candidate cursor; its complete route observation is a
 -- single native query snapshot, rather than unbounded follow-up scans.
 FOR candidate IN SELECT storage_row_id,type_id,key_num,object_id,namespace_bytes,key_bytes,
   octet_length(original_context_bytes) AS context_size
   FROM truss.object_key_bucket WHERE namespace_sha256=sha256(namespace) AND key_sha256=sha256(transport)
   ORDER BY storage_row_id LIMIT 10001 LOOP
  candidate_count:=candidate_count+1;
  candidate_bytes:=candidate_bytes+octet_length(candidate.namespace_bytes)+octet_length(candidate.key_bytes)+candidate.context_size;
  IF candidate_count>10000 OR candidate_bytes>16777216 THEN RAISE EXCEPTION 'bounded key route exceeded' USING ERRCODE='54000';END IF;
  IF candidate.namespace_bytes=namespace AND candidate.key_bytes=transport THEN
   matches:=matches+1;
   IF matches>1 THEN RAISE EXCEPTION 'unique exact key membership required' USING ERRCODE='55000';END IF;
   member.storage_row_id:=candidate.storage_row_id;member.type_id:=candidate.type_id;member.key_num:=candidate.key_num;member.object_id:=candidate.object_id;
  END IF;
 END LOOP;
 IF matches=0 THEN RETURN NULL;END IF;
 IF member.type_id<>(selection->>'typeId')::int OR member.key_num<>(selection->>'keyNumber')::smallint THEN RAISE EXCEPTION 'qualified key membership required' USING ERRCODE='55000';END IF;
 IF current_setting('transaction_read_only')<>'on' THEN
  PERFORM 1 FROM truss.object WHERE id=member.object_id AND type_id=member.type_id FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'live member object required' USING ERRCODE='55000';END IF;
 END IF;
 IF truss.verify_object_string_key(member.object_id,member.type_id,member.key_num,tuple_bytes) IS NOT TRUE THEN RAISE EXCEPTION 'current object key membership required' USING ERRCODE='55000';END IF;
 result:=truss.get_object(selected_document,selected_module,selected_record,member.object_id,maximum_bytes,expected_release,expected_digest);
 IF result IS NULL THEN RETURN NULL;END IF;
 IF convert_from(result,'UTF8')::jsonb->>'catalogRevision' IS DISTINCT FROM selection->>'catalogRevision' THEN
  RAISE EXCEPTION 'catalog changed during key observation' USING ERRCODE='55P03';END IF;
 SELECT jsonb_agg(CASE WHEN jsonb_typeof(cell.value->1)='string' THEN jsonb_build_object('kind','string','text',cell.value->1) WHEN jsonb_typeof(cell.value->1)='boolean' THEN jsonb_build_object('kind','boolean','value',cell.value->1) ELSE cell.value->1 END ORDER BY i.n) INTO buffered_cells
  FROM truss.key_def k CROSS JOIN LATERAL unnest(k.prop_ids) WITH ORDINALITY i(prop_id,n)
  JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=k.type_id
  CROSS JOIN LATERAL jsonb_array_elements(convert_from(result,'UTF8')::jsonb->'values') cell(value)
  WHERE k.type_id=member.type_id AND k.key_num=member.key_num AND cell.value->>0=p.name;
 IF truss.verify_umf_scalar_key_tuple(tuple_bytes,buffered_cells,key_facets) IS NOT TRUE THEN RAISE EXCEPTION 'key changed during observation' USING ERRCODE='55P03';END IF;
 -- Do not authorize the buffered object against earlier role membership.
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 FOR component IN SELECT DISTINCT p.declaration_module FROM truss.key_def k CROSS JOIN LATERAL unnest(k.prop_ids) i(prop_id) JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=k.type_id WHERE k.type_id=member.type_id AND k.key_num=member.key_num LOOP
  IF NOT truss.runtime_can_read(selected_document,component.declaration_module) THEN RETURN NULL;END IF;
 END LOOP;
 PERFORM truss.runtime_person(false);
 IF NOT truss.runtime_object_values_readable(member.type_id) THEN RETURN NULL;END IF;
 IF convert_from(result,'UTF8')::jsonb->>'profile'='truss-python-logical-object/0.1' AND NOT truss.runtime_can_read(
  convert_from(result,'UTF8')::jsonb->'root'->'owner'->>'documentId',convert_from(result,'UTF8')::jsonb->'root'->'owner'->>'moduleId') THEN RETURN NULL;END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.object_group_begin_prepared(original_input bytea, original_documents bytea, original_request bytea, expected_release text, expected_digest text, original_condition_keys bytea, replay_only boolean, app_prepared jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE input_operations jsonb;
 input jsonb;documents jsonb;request jsonb;context jsonb;selected record;archive truss.schema_doc%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;head_revision int;head_registration uuid;
 operation jsonb;admission record;source_slots jsonb;source_slot_list jsonb;source_slot int;source_bytes_by_slot bytea[];source_verified boolean[];person oid;writer xid8;ns bytea;rk bytea;route bigint;prior_generation bigint;receipt truss.request_receipt%ROWTYPE;
 raw jsonb;observation bytea;attempt truss.runtime_object_attempt%ROWTYPE;index int:=0;failure_detail text;retained_basis jsonb;retained_count int;
 admission_aliases jsonb;
BEGIN
 IF replay_only IS NULL THEN RAISE EXCEPTION 'explicit replay probe required' USING ERRCODE='22023';END IF;
 context:=convert_from(truss.group_context(expected_release,expected_digest),'UTF8')::jsonb;person:=truss.runtime_person(false);writer:=pg_current_xact_id();
 IF original_input IS NULL OR octet_length(original_input) NOT BETWEEN 1 AND 1048576 OR original_documents IS NULL OR octet_length(original_documents) NOT BETWEEN 1 AND 4194304
  OR original_request IS NULL OR octet_length(original_request) NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION 'bounded group required' USING ERRCODE='54000';END IF;
 IF (convert_from(original_input,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
 OR (convert_from(original_documents,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE
 OR (convert_from(original_request,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'unique original JSON members required' USING ERRCODE='22023';END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;documents:=convert_from(original_documents,'UTF8')::jsonb;request:=convert_from(original_request,'UTF8')::jsonb;
 input_operations:=input->'operations';
 IF replay_only AND request->>'state' IS DISTINCT FROM 'present' THEN RAISE EXCEPTION 'request-present replay probe required' USING ERRCODE='22023';END IF;
 IF input-ARRAY['interfaceVersion','layoutProfile','mutationProfile','valueProfile','catalog','operations','assertedOrigin','preconditions']<>'{}'::jsonb
 OR input->>'interfaceVersion' IS DISTINCT FROM 'truss-group-input/0.1.0' OR input->'catalog' IS DISTINCT FROM '{"selection":"current"}'::jsonb
 OR jsonb_typeof(input_operations) IS DISTINCT FROM 'array'
 OR jsonb_array_length(input_operations) NOT BETWEEN 1 AND (CASE WHEN input->'mutationProfile'=truss.runtime_owned_profile() THEN 1024 ELSE 128 END) OR jsonb_typeof(documents) IS DISTINCT FROM 'array'
 OR jsonb_array_length(documents) NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'selected bounded object group required' USING ERRCODE='0A000';END IF;
 IF input->'assertedOrigin'->>'kind' IS DISTINCT FROM 'map' OR (input->'assertedOrigin')-ARRAY['kind','entries']<>'{}'::jsonb
 OR jsonb_typeof(input->'assertedOrigin'->'entries') IS DISTINCT FROM 'array'
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e WHERE jsonb_typeof(e.value->'key') IS DISTINCT FROM 'string'
 OR e.value-ARRAY['key','value']<>'{}'::jsonb OR (e.value->'value'='{"kind":"null"}'::jsonb OR (e.value->'value'->>'kind'='string'
 AND jsonb_typeof(e.value->'value'->'text')='string' AND (e.value->'value')-ARRAY['kind','text']='{}'::jsonb)) IS NOT TRUE)
 OR (SELECT count(*) FROM jsonb_array_elements(input->'assertedOrigin'->'entries'))<>(SELECT count(DISTINCT e.value->>'key') FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e)
 THEN RAISE EXCEPTION 'closed scalar asserted origin required' USING ERRCODE='22023';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(input_operations) o WHERE o.value ? 'alias')
 <>(SELECT count(DISTINCT o.value->>'alias') FROM jsonb_array_elements(input_operations) o WHERE o.value ? 'alias') THEN RAISE EXCEPTION 'unique aliases required' USING ERRCODE='22023';END IF;
 IF request<>'{"state":"none"}'::jsonb THEN
  IF request->>'state' IS DISTINCT FROM 'present' OR request-ARRAY['state','identity']<>'{}'::jsonb
   OR request->'identity'->>'inputProfile' IS DISTINCT FROM 'truss-group-input/0.1.0'
   OR request->'identity'->>'interfaceVersion' IS DISTINCT FROM 'truss-request-identity/0.1.0'
   OR request->'identity'->>'authorizedScopeIdentity' IS DISTINCT FROM context->>'authorizedScopeIdentity'
   OR jsonb_typeof(request->'identity'->'requestId') IS DISTINCT FROM 'string' OR octet_length(request->'identity'->>'requestId') NOT BETWEEN 1 AND 1024
   OR (request->'identity')-ARRAY['authorizedScopeIdentity','requestId','claimedSha256','inputProfile','interfaceVersion']<>'{}'::jsonb
   OR (request->'identity' ? 'claimedSha256' AND request->'identity'->>'claimedSha256' IS DISTINCT FROM encode(sha256(original_input),'hex')) THEN
   RAISE EXCEPTION 'original request identity required' USING ERRCODE='22023';END IF;
  ns:=convert_to(context->>'authorizedScopeIdentity','UTF8');rk:=convert_to(request->'identity'->>'requestId','UTF8');
  route:=('x'||substr(encode(sha256(convert_to('group-request','UTF8')||sha256(ns)||sha256(rk)),'hex'),1,16))::bit(64)::bigint;
  IF NOT pg_try_advisory_xact_lock(route) THEN RAISE EXCEPTION 'request in flight' USING ERRCODE='55P03';END IF;
  SELECT generation INTO prior_generation FROM truss.request_receipt_route_guard WHERE namespace_sha256=sha256(ns) AND request_sha256=sha256(rk) FOR UPDATE NOWAIT;
  IF NOT FOUND AND NOT replay_only THEN INSERT INTO truss.request_receipt_route_guard VALUES(sha256(ns),sha256(rk),0);END IF;
  IF (SELECT count(*) FROM truss.request_receipt WHERE namespace_sha256=sha256(ns) AND request_sha256=sha256(rk))>10000 THEN RAISE EXCEPTION 'bounded receipt route required' USING ERRCODE='54000';END IF;
  IF (SELECT count(*) FROM truss.request_receipt WHERE namespace_sha256=sha256(ns) AND request_sha256=sha256(rk) AND namespace_identity_utf8=ns AND request_id_utf8=rk)>1 THEN RAISE EXCEPTION 'unique exact receipt required' USING ERRCODE='55000';END IF;
  IF EXISTS(SELECT 1 FROM truss.runtime_object_attempt a WHERE a.writer_xid=writer AND NOT a.complete AND a.context->>'authorizedScopeIdentity'=convert_from(ns,'UTF8')
   AND convert_from(a.request_bytes,'UTF8')::jsonb->'identity'->>'requestId'=request->'identity'->>'requestId') THEN RAISE EXCEPTION 'request already unfinished' USING ERRCODE='55P03';END IF;
  SELECT * INTO receipt FROM truss.request_receipt WHERE namespace_sha256=sha256(ns) AND request_sha256=sha256(rk) AND namespace_identity_utf8=ns AND request_id_utf8=rk;
  IF FOUND THEN
   IF receipt.payload_state<>'complete' THEN RETURN convert_to('{"outcome":"unavailable","reason":"receipt_expired"}','UTF8');END IF;
   raw:=convert_from(receipt.original_receipt_bytes,'UTF8')::jsonb;
   IF raw->>'profile' IS DISTINCT FROM 'truss-object-group-receipt/0.1' THEN RAISE EXCEPTION 'selected receipt required' USING ERRCODE='0A000';END IF;
   IF decode(raw->>'inputBase64','base64') IS DISTINCT FROM original_input THEN RAISE EXCEPTION 'request input changed' USING ERRCODE='P1001';END IF;
   SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=(raw->>'attemptId')::uuid;
   IF NOT attempt.complete OR attempt.receipt_id IS DISTINCT FROM receipt.storage_row_id OR attempt.writer_xid IS DISTINCT FROM receipt.original_writer_xid
    OR (attempt.expected_receipt IS NOT NULL AND to_jsonb(receipt) IS DISTINCT FROM attempt.expected_receipt) OR attempt.input_bytes IS DISTINCT FROM original_input
    OR attempt.position_bytes IS DISTINCT FROM truss.runtime_receipt_position(attempt.context,receipt.storage_row_id,receipt.original_writer_xid)
    OR raw->'semantic' IS DISTINCT FROM jsonb_build_object('interfaceVersion','truss-group-result/0.1.0','executedCatalogRevision',raw->'semantic'->>'executedCatalogRevision',
     'layoutProfile',input->'layoutProfile','mutationProfile',input->'mutationProfile','results',attempt.results,'aliases',attempt.aliases) THEN RAISE EXCEPTION 'original receipt position correspondence required' USING ERRCODE='55000';END IF;
   IF attempt.context->'mutationProfile'=truss.runtime_owned_profile() THEN
    IF NOT truss.runtime_receipt_can_read(attempt.id) THEN
     RAISE EXCEPTION 'current retained dependency reader required' USING ERRCODE='42501';END IF;
    FOR selected IN SELECT DISTINCT r.value->'identity'->'owner'->>'documentId' document_id,
     r.value->'identity'->'owner'->>'moduleId' module FROM jsonb_array_elements(attempt.results) r LOOP
     PERFORM truss.runtime_module_writer_qualified(selected.document_id,selected.module,person);
    END LOOP;
   ELSE
   retained_count:=jsonb_array_length(attempt.results);
   index:=0;FOR operation IN SELECT value FROM jsonb_array_elements(input_operations) LOOP
    IF NOT attempt.complete OR index<0 OR index>=attempt.next_index OR retained_count<>attempt.next_index THEN
     RAISE EXCEPTION 'complete retained operation required' USING ERRCODE='55000';END IF;
    SELECT * INTO STRICT selected FROM truss.runtime_owned_retained_operation_frame(operation,attempt.results->index,
     raw->'semantic'->>'executedCatalogRevision',retained_basis,person);
    retained_basis:=selected.historical_basis;
    PERFORM truss.runtime_module_writer(selected.document_id,selected.module);index:=index+1;
   END LOOP;
   END IF;
   PERFORM truss.runtime_edge_authorize((raw->>'attemptId')::uuid);
   observation:=convert_to(jsonb_build_object('profile','truss-native-create-replay-observation/0.1','sourceEpoch',context->>'sourceEpoch',
    'observingXid',writer::text,'originalWriterXid',receipt.original_writer_xid::text,'receiptStorageId',receipt.storage_row_id::text,
    'receiptGeneration',receipt.lifecycle_generation::text,'receiptSha256',encode(sha256(receipt.original_receipt_bytes),'hex'),
    'actorOid',person::text,'actor',session_user::text,'scopeIdentity',context->>'authorizedScopeIdentity',
    'releaseId',expected_release,'releaseSha256',expected_digest,'basis',CASE WHEN writer=receipt.original_writer_xid THEN 'same_transaction' ELSE 'committed_receipt' END)::text,'UTF8');
   RETURN convert_to(jsonb_build_object('outcome','success','disposition','replayed','durability',CASE WHEN writer=receipt.original_writer_xid THEN 'pending' ELSE 'committed' END,
    'semantic',raw->'semantic','receiptToken',truss.runtime_receipt_token(attempt.position_bytes),'observationBase64',replace(encode(observation,'base64'),chr(10),''),'observationSha256',encode(sha256(observation),'hex'))::text,'UTF8');
  END IF;
 END IF;
 IF input->'layoutProfile' IS DISTINCT FROM context->'layoutProfile' OR input->'mutationProfile' IS DISTINCT FROM context->'mutationProfile' OR input->'valueProfile' IS DISTINCT FROM context->'valueProfile' THEN RAISE EXCEPTION 'current group profile required on receipt miss' USING ERRCODE='0A000';END IF;
 IF replay_only THEN RETURN convert_to('{"outcome":"miss"}','UTF8');END IF;
 -- Build one exact document-ID slot index for this immutable input. The slot
 -- list preserves strict missing/duplicate source failures at first use; the
 -- byte and verification arrays avoid rescanning or recopying source JSON per
 -- owner. This memo is local to the current admission call only.
 WITH docs AS MATERIALIZED (
  SELECT value,ordinality::int slot,value->>'documentId' document_id
  FROM jsonb_array_elements(documents) WITH ORDINALITY d(value,ordinality)),
 slots AS (
  SELECT document_id COLLATE pg_catalog."C" document_id,jsonb_agg(slot ORDER BY slot) slots
  FROM docs WHERE document_id IS NOT NULL GROUP BY document_id COLLATE pg_catalog."C")
 SELECT coalesce((SELECT jsonb_object_agg(document_id,slots) FROM slots),'{}'::jsonb),
  coalesce(array_agg(convert_to(value->>'sourceText','UTF8') ORDER BY slot),'{}'::bytea[]),
  coalesce(array_agg(false ORDER BY slot),'{}'::boolean[])
 INTO source_slots,source_bytes_by_slot,source_verified FROM docs;
 -- Index original alias owners once; an alias target must not rescan all
 -- earlier operations for every owner/type/relationship lookup.
 SELECT coalesce(jsonb_object_agg(o.value->>'alias',jsonb_build_object('operation',o.value->>'operation',
  'typeDefinitionPin',o.value->'typeDefinitionPin','relationshipDefinitionPin',o.value->'relationshipDefinitionPin',
  'operationIndex',o.ordinal-1)),'{}'::jsonb) INTO admission_aliases
 FROM jsonb_array_elements(input_operations) WITH ORDINALITY o(value,ordinal) WHERE o.value ? 'alias';
 -- Authorize the full original owner inventory without requiring live targets.
 person:=truss.runtime_person(false);
 -- CREATE source/owner meaning is constant for each exact definition pin
 -- during this read-only admission phase. Retain every original ordinal for
 -- alias-dependent operations; value/shape admission still checks every row.
 FOR admission IN
  SELECT * FROM (
   SELECT value operation,(ordinal-1)::int operation_index
   FROM jsonb_array_elements(input_operations) WITH ORDINALITY o(value,ordinal)
   WHERE (value->>'operation' IS NULL OR value->>'operation' NOT IN ('create_object','create_edge'))
    AND NOT (coalesce(value->>'operation'='update_object' AND value->'target'->>'state'='stored',false)
     AND NOT (value ? 'ownershipChange'))
   UNION ALL
   SELECT creates.operation,creates.operation_index FROM (
    SELECT DISTINCT ON (value->>'operation',value->>'typeDefinitionPin',value->>'relationshipDefinitionPin',
     CASE WHEN value->>'operation'='update_object' THEN (value->'target'->'identity')-'id' END)
     value operation,(ordinal-1)::int operation_index
    FROM jsonb_array_elements(input_operations) WITH ORDINALITY o(value,ordinal)
    WHERE value->>'operation' IN ('create_object','create_edge')
     OR value->>'operation'='update_object' AND value->'target'->>'state'='stored' AND NOT (value ? 'ownershipChange')
    ORDER BY value->>'operation',value->>'typeDefinitionPin',value->>'relationshipDefinitionPin',
     CASE WHEN value->>'operation'='update_object' THEN (value->'target'->'identity')-'id' END,ordinal) creates
  ) original_owners ORDER BY operation_index
 LOOP
  operation:=admission.operation;index:=admission.operation_index;
  SELECT * INTO STRICT selected FROM truss.runtime_owned_operation_owner_qualified(operation,admission_aliases,index,person);PERFORM truss.runtime_module_writer_qualified(selected.document_id,selected.module,person);
  source_slot_list:=source_slots->selected.document_id;
  IF source_slot_list IS NULL THEN
   SELECT * INTO STRICT archive FROM truss.schema_doc WHERE doc_id=selected.document_id ORDER BY rev DESC LIMIT 1;
   RAISE NO_DATA_FOUND;
  END IF;
  IF jsonb_array_length(source_slot_list)<>1 THEN
   SELECT * INTO STRICT archive FROM truss.schema_doc WHERE doc_id=selected.document_id ORDER BY rev DESC LIMIT 1;
   RAISE TOO_MANY_ROWS;
  END IF;
  source_slot:=(source_slot_list->>0)::int;
  IF source_verified[source_slot] IS DISTINCT FROM true THEN
   SELECT * INTO STRICT archive FROM truss.schema_doc WHERE doc_id=selected.document_id ORDER BY rev DESC LIMIT 1;
   IF source_bytes_by_slot[source_slot] IS DISTINCT FROM convert_to(archive.document,'UTF8') THEN RAISE EXCEPTION 'exact original source required' USING ERRCODE='22023';END IF;
   source_verified[source_slot]:=true;
  END IF;
  index:=index+1;
 END LOOP;
 -- Predicate owners can differ from all operation owners. Preserve exact
 -- original-source correspondence inside the database before evaluating them.
 IF input ? 'preconditions' THEN
  PERFORM truss.group_condition_key_metadata(original_input,original_documents,expected_release,expected_digest);
 END IF;
 -- Conditions observe the locked prestate before operation planning can fail.
 -- Receipt replay and complete owner/source admission above retain their order.
 IF input->'mutationProfile'=truss.runtime_owned_profile() THEN
  IF NOT pg_try_advisory_xact_lock(1953658227,1735549296) THEN
   RAISE EXCEPTION 'graph writer in flight' USING ERRCODE='55P03';END IF;
  LOCK TABLE truss.object IN ROW EXCLUSIVE MODE NOWAIT;
  LOCK TABLE truss.edge IN ROW EXCLUSIVE MODE NOWAIT;
 ELSE
  LOCK TABLE truss.object IN SHARE ROW EXCLUSIVE MODE NOWAIT;
  LOCK TABLE truss.edge IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 END IF;
 PERFORM truss.runtime_evaluate_preconditions(input,original_condition_keys);
 -- Preserve precondition outcome precedence; a stale cache identity is checked
 -- only after the native group has completed the same current admission steps.
 IF app_prepared IS NOT NULL THEN
  SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
  SELECT rev INTO STRICT head_revision FROM truss.schema_head WHERE id=1;
  SELECT r.registration_id INTO STRICT head_registration FROM truss.catalog_registration_request r WHERE r.revision=head_revision;
  IF app_prepared->>'profile' IS DISTINCT FROM 'truss-application-record-preparation/0.1'
   OR app_prepared->'basis' IS DISTINCT FROM jsonb_build_object('installationId',installation.installation_id::text,
    'releaseSha256',installation.release_sha256,'sourceEpoch',installation.source_epoch::text,
    'catalogRevision',head_revision,'registrationId',head_registration::text,'documentsSha256',encode(sha256(original_documents),'hex'))
   OR app_prepared->>'inputSha256' IS DISTINCT FROM encode(sha256(original_input),'hex')
   OR jsonb_typeof(app_prepared->'schemas') IS DISTINCT FROM 'object'
   OR jsonb_typeof(app_prepared->'operations') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'prepared application basis changed' USING ERRCODE='55P03';END IF;
 END IF;
 INSERT INTO truss.runtime_object_attempt(writer_xid,actor_oid,input_bytes,documents_bytes,request_bytes,context)
 VALUES(writer,person,original_input,original_documents,original_request,
  context||jsonb_build_object('originalAssertedOrigin',input->'assertedOrigin')) RETURNING * INTO attempt;
 IF input->'mutationProfile'=truss.runtime_owned_profile() THEN
  IF app_prepared IS NULL THEN PERFORM truss.runtime_owned_capture(attempt.id);
  ELSE PERFORM truss.runtime_owned_capture_application(attempt.id,app_prepared);END IF;
 END IF;
 RETURN convert_to(jsonb_build_object('outcome','execute','attemptId',attempt.id::text)::text,'UTF8');
EXCEPTION WHEN SQLSTATE 'P1006' THEN
 GET STACKED DIAGNOSTICS failure_detail=PG_EXCEPTION_DETAIL;
 -- The function subtransaction rolls back guard setup and all other effects.
 RETURN convert_to(failure_detail,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.object_group_finish(attempt_id uuid)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE input_operations jsonb;
 attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;request jsonb;semantic jsonb;bytes bytea;receipt_bytes bytea;receipt truss.request_receipt%ROWTYPE;
 ns bytea;rk bytea;operation jsonb;selected record;index int:=0;owner record;current_actor oid;sealed record;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id FOR UPDATE NOWAIT;
 IF attempt.writer_xid<>pg_current_xact_id() OR attempt.actor_oid<>truss.runtime_person(false) OR attempt.complete THEN RAISE EXCEPTION 'current unfinished group required' USING ERRCODE='55000';END IF;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;request:=convert_from(attempt.request_bytes,'UTF8')::jsonb;
 input_operations:=input->'operations';
 IF input->'mutationProfile'=truss.runtime_owned_profile() THEN
  IF attempt.results<>'[]'::jsonb OR attempt.aliases<>'[]'::jsonb THEN
   RAISE EXCEPTION 'unassembled original owned attempt required' USING ERRCODE='55000';END IF;
  SELECT coalesce(jsonb_agg(p.result ORDER BY p.operation_index),'[]'::jsonb) results,
   coalesce(jsonb_agg(jsonb_build_object('alias',p.plan->'operation'->>'alias','identity',p.result->'identity') ORDER BY p.operation_index)
    FILTER(WHERE (p.plan->'operation') ? 'alias'),'[]'::jsonb) aliases,
   array_agg(p.operation_index ORDER BY p.operation_index) ordinals,
   count(*) FILTER(WHERE p.result IS NULL) missing,bool_and(p.writer_xid=attempt.writer_xid) writer_matches
  INTO sealed FROM truss.runtime_owned_operation p WHERE p.attempt_id=attempt.id;
  IF sealed.missing<>0 OR sealed.writer_matches IS DISTINCT FROM true
   OR sealed.ordinals IS DISTINCT FROM ARRAY(SELECT generate_series(0,attempt.next_index-1)) THEN
   RAISE EXCEPTION 'complete ordered sealed owned results required' USING ERRCODE='55000';END IF;
  attempt.results:=sealed.results;attempt.aliases:=sealed.aliases;
 END IF;
 IF attempt.next_index<>jsonb_array_length(input_operations) OR jsonb_array_length(attempt.results)<>attempt.next_index THEN RAISE EXCEPTION 'complete ordered results required' USING ERRCODE='55000';END IF;
 IF attempt.context ? 'creationTransitionProfile' THEN
  IF attempt.context->'creationTransitionProfile' IS DISTINCT FROM '{"identity":"truss-unified-create-transition","version":"0.1","sha256":"765d7def5e677dba5d3ed5cdc841b1aa43eb2f4a493f1d2603ff3698536a5396"}'::jsonb AND attempt.context->'creationTransitionProfile' IS DISTINCT FROM '{"identity":"truss-unified-create-transition","version":"0.2","sha256":"073782e2517f2a7e26c8d6479c6266ececf68963681ccfb6a380e9cd16f2e11b"}'::jsonb THEN
   RAISE EXCEPTION 'known original creation storage profile required' USING ERRCODE='55000';END IF;
  IF EXISTS(
   SELECT 1 FROM jsonb_array_elements(input_operations) WITH ORDINALITY o(operation,ordinal)
   LEFT JOIN truss.runtime_object_transition t ON t.attempt_id=attempt.id AND t.operation_index=o.ordinal-1
    AND t.before_object IS NULL AND t.object_id::text=attempt.results->(o.ordinal-1)::int->'identity'->>'id'
    AND t.type_id::text=attempt.results->(o.ordinal-1)::int->'identity'->>'typeId'
   WHERE o.operation->>'operation'='create_object' GROUP BY o.ordinal HAVING count(t.transition_id)<>1) THEN
   RAISE EXCEPTION 'one original transition for every completed create required' USING ERRCODE='55000';END IF;
 ELSIF EXISTS(SELECT 1 FROM truss.runtime_object_transition WHERE runtime_object_transition.attempt_id=attempt.id AND before_object IS NULL) THEN
  RAISE EXCEPTION 'historical attempts have no synthetic creation transitions' USING ERRCODE='55000';END IF;
 IF input->'mutationProfile'=truss.runtime_owned_profile() THEN
  PERFORM truss.runtime_owned_graph_validate_attempt(attempt.id,true);
 ELSE PERFORM truss.runtime_graph_validate(true);END IF;
 IF input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
  PERFORM truss.runtime_edge_authorize(attempt_id);
 END IF;
 -- Marker refresh above can fire triggers. Recheck mutable progress before
 -- reusing the already closed immutable owned result-slot census.
 IF input->'mutationProfile'=truss.runtime_owned_profile() AND NOT EXISTS(
  SELECT 1 FROM truss.runtime_object_attempt a WHERE a.id=attempt.id
   AND a.actor_oid=attempt.actor_oid AND a.writer_xid=attempt.writer_xid
   AND a.next_index=attempt.next_index AND NOT a.complete
   AND a.results='[]'::jsonb AND a.aliases='[]'::jsonb
   AND (SELECT count(*) FROM truss.runtime_owned_operation p
    WHERE p.attempt_id=a.id AND p.result IS NOT NULL)=a.next_index) THEN
  RAISE EXCEPTION 'original unfinished owned settlement progress required' USING ERRCODE='55000';END IF;
 -- Marker refresh and authorization above may execute write triggers. Issue
 -- identity only after them, for this read-only final-edge validation phase.
 -- Each edge still resolves live module policy/membership independently.
 current_actor:=truss.runtime_person(false);
 IF current_actor IS DISTINCT FROM attempt.actor_oid THEN RAISE EXCEPTION 'original current finishing actor required' USING ERRCODE='42501';END IF;
 IF input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
  FOR owner IN SELECT DISTINCT edge_id,rel_type_id FROM truss.runtime_edge_transition WHERE runtime_edge_transition.attempt_id=object_group_finish.attempt_id LOOP
   PERFORM truss.runtime_edge_validate(owner.edge_id,owner.rel_type_id);
  END LOOP;
 END IF;
 semantic:=jsonb_build_object('interfaceVersion','truss-group-result/0.1.0','executedCatalogRevision',(SELECT rev::text FROM truss.schema_head WHERE id=1),
  'layoutProfile',input->'layoutProfile','mutationProfile',input->'mutationProfile','results',attempt.results,'aliases',attempt.aliases);
 bytes:=convert_to(semantic::text,'UTF8');IF octet_length(bytes)>16777216 THEN RAISE EXCEPTION 'bounded complete results required' USING ERRCODE='54000';END IF;
 IF request<>'{"state":"none"}'::jsonb THEN
  ns:=convert_to(attempt.context->>'authorizedScopeIdentity','UTF8');rk:=convert_to(request->'identity'->>'requestId','UTF8');
  IF EXISTS(SELECT 1 FROM truss.request_receipt WHERE namespace_sha256=sha256(ns) AND request_sha256=sha256(rk) AND namespace_identity_utf8=ns AND request_id_utf8=rk) THEN RAISE EXCEPTION 'exact request already settled' USING ERRCODE='P1001';END IF;
  IF (SELECT count(*) FROM truss.runtime_object_attempt a WHERE a.writer_xid=attempt.writer_xid AND NOT a.complete
   AND a.context->>'authorizedScopeIdentity'=attempt.context->>'authorizedScopeIdentity'
   AND convert_from(a.request_bytes,'UTF8')::jsonb->'identity'->>'requestId'=request->'identity'->>'requestId')<>1 THEN RAISE EXCEPTION 'one original request attempt required' USING ERRCODE='55000';END IF;
  receipt_bytes:=convert_to(jsonb_build_object('profile','truss-object-group-receipt/0.1','attemptId',attempt_id::text,
   'inputBase64',replace(encode(attempt.input_bytes,'base64'),chr(10),''),'semantic',semantic)::text,'UTF8');
  INSERT INTO truss.request_receipt(namespace_identity_utf8,request_id_utf8,original_writer_xid,original_writer_context_bytes,lifecycle_generation,payload_state,original_receipt_bytes)
  VALUES(ns,rk,attempt.writer_xid,convert_to(jsonb_build_object('profile','truss-object-group-writer/0.1','attemptId',attempt_id::text,
   'xid',attempt.writer_xid::text,'actorOid',attempt.actor_oid::text,'actor',session_user::text)::text,'UTF8'),0,'complete',receipt_bytes) RETURNING * INTO receipt;
  IF NOT FOUND OR receipt.storage_row_id IS NULL
   OR receipt.namespace_identity_utf8 IS DISTINCT FROM ns OR receipt.request_id_utf8 IS DISTINCT FROM rk
   OR receipt.original_writer_xid IS DISTINCT FROM attempt.writer_xid OR receipt.payload_state IS DISTINCT FROM 'complete'
   OR receipt.original_receipt_bytes IS DISTINCT FROM receipt_bytes THEN
   RAISE EXCEPTION 'exact original request receipt required' USING ERRCODE='55000';END IF;
  UPDATE truss.request_receipt_route_guard SET generation=generation+1 WHERE namespace_sha256=sha256(ns) AND request_sha256=sha256(rk);
 END IF;
 UPDATE truss.runtime_object_attempt SET results=attempt.results,aliases=attempt.aliases,complete=true,receipt_id=receipt.storage_row_id,
  expected_receipt=CASE WHEN receipt.storage_row_id IS NOT NULL AND input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN to_jsonb(receipt) END,
  position_bytes=CASE WHEN receipt.storage_row_id IS NOT NULL THEN truss.runtime_receipt_position(attempt.context,receipt.storage_row_id,attempt.writer_xid) END WHERE id=attempt_id;
 current_actor:=truss.runtime_person(false);
 IF current_actor IS DISTINCT FROM attempt.actor_oid THEN RAISE EXCEPTION 'original current finishing actor required' USING ERRCODE='42501';END IF;
 IF input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
  FOR owner IN SELECT DISTINCT object_id,type_id FROM truss.runtime_object_transition WHERE runtime_object_transition.attempt_id=object_group_finish.attempt_id LOOP
   PERFORM truss.runtime_owned_row_validate_qualified(owner.object_id,owner.type_id,current_actor);
  END LOOP;
 END IF;
 IF input->'mutationProfile'=truss.runtime_owned_profile() THEN
  -- Group settlement rechecks the complete distinct owner/type set. Repeating
  -- the same policy/schema lookup for every operation adds no authority.
  PERFORM truss.runtime_owned_group_validate(attempt.id,true);
 ELSE
  FOR operation IN SELECT value FROM jsonb_array_elements(input_operations) LOOP
   SELECT * INTO STRICT selected FROM truss.runtime_owned_operation_owner_qualified(operation,input_operations,index,current_actor);PERFORM truss.runtime_module_writer_qualified(selected.document_id,selected.module,current_actor);index:=index+1;
  END LOOP;
 END IF;
 RETURN convert_to(jsonb_build_object('outcome','success','disposition','applied','durability','pending','semantic',semantic,
  'receiptToken',CASE WHEN receipt.storage_row_id IS NOT NULL THEN truss.runtime_receipt_token(truss.runtime_receipt_position(attempt.context,receipt.storage_row_id,attempt.writer_xid)) END)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.object_group_metadata(attempt_id uuid, operation_index integer)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE metadata jsonb;encoded bytea;entry jsonb;
BEGIN
 metadata:=truss.runtime_object_metadata(attempt_id,operation_index);encoded:=convert_to(metadata::text,'UTF8');
 PERFORM truss.runtime_module_writer(metadata->>'documentId',metadata->>'moduleId');
 IF NOT metadata ? 'source' AND NOT truss.runtime_object_values_readable((metadata->>'typeId')::int) THEN RAISE EXCEPTION 'current buffered property/item reader required' USING ERRCODE='42501';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(jsonb_build_array(metadata->'oldSource',metadata->'oldTarget',metadata->'source',metadata->'target')) WHERE value<>'null'::jsonb LOOP
  IF NOT truss.runtime_can_read(entry->'owner'->>'documentId',entry->'owner'->>'moduleId') THEN RAISE EXCEPTION 'current endpoint metadata reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN encoded;
END;
$function$

CREATE OR REPLACE FUNCTION truss.object_group_step(attempt_id uuid, operation_index integer, original_keys bytea)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;current_actor oid;
BEGIN
 current_actor:=truss.runtime_person(false);
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id;
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM current_actor OR attempt.complete OR attempt.next_index IS DISTINCT FROM operation_index THEN RAISE EXCEPTION 'current ordered object attempt required' USING ERRCODE='55000';END IF;
 RETURN truss.runtime_owned_group_step_in_input(attempt_id,operation_index,original_keys,attempt.input_bytes,convert_from(attempt.input_bytes,'UTF8')::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION truss.owned_delete_projection(node_count integer, owned_edges jsonb, independent_edges jsonb, delete_node integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE entry jsonb;deleted int[];edge_number int;
 source_node int;target_node int;seen_edges boolean[]:=array_fill(false,ARRAY[1024]);deleted_edges jsonb;
 children jsonb[];visited boolean[];queue int[];head int:=1;tail int:=1;child int;adjacency record;
BEGIN
 IF node_count IS NULL OR node_count NOT BETWEEN 0 AND 1024 THEN
  RAISE EXCEPTION 'bounded local node count required' USING ERRCODE='54000';END IF;
 IF delete_node IS NULL OR delete_node<0 OR delete_node>=node_count THEN
  RAISE EXCEPTION 'existing local delete node required' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(independent_edges) IS DISTINCT FROM 'array'
  OR jsonb_typeof(owned_edges) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'explicit independent incident edges required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(independent_edges)+jsonb_array_length(owned_edges)>1024
  OR octet_length(convert_to(independent_edges::text,'UTF8'))>1048576
  OR octet_length(convert_to(owned_edges::text,'UTF8'))>1048576 THEN
  RAISE EXCEPTION 'bounded complete incident edges required' USING ERRCODE='54000';END IF;
 -- Shape admission only: cycles/multiple parents can exist between ordered
 -- operations. Their final-state validation belongs to the executor.
 FOR entry IN SELECT value FROM jsonb_array_elements(owned_edges) LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'exact owned edge required' USING ERRCODE='22023';END IF;
  IF entry-ARRAY['edge','source','target']<>'{}'::jsonb
   OR jsonb_typeof(entry->'edge') IS DISTINCT FROM 'number'
   OR jsonb_typeof(entry->'source') IS DISTINCT FROM 'number'
   OR jsonb_typeof(entry->'target') IS DISTINCT FROM 'number'
   OR (entry->>'edge') !~ '^(0|[1-9][0-9]{0,3})$'
   OR (entry->>'source') !~ '^(0|[1-9][0-9]{0,3})$'
   OR (entry->>'target') !~ '^(0|[1-9][0-9]{0,3})$' THEN
   RAISE EXCEPTION 'closed bounded owned edge required' USING ERRCODE='22023';END IF;
  edge_number:=(entry->>'edge')::int;
  source_node:=(entry->>'source')::int;target_node:=(entry->>'target')::int;
  IF edge_number>=1024 OR source_node>=node_count OR target_node>=node_count
   OR seen_edges[edge_number+1] THEN
   RAISE EXCEPTION 'unique local edge correspondence required' USING ERRCODE='22023';END IF;
  seen_edges[edge_number+1]:=true;
 END LOOP;
 -- Build adjacency once and visit each reachable vertex/edge once, even
 -- when intermediate ordered states contain a cycle or multiple parents.
 children:=array_fill('[]'::jsonb,ARRAY[node_count]);
 FOR adjacency IN SELECT (value->>'source')::int source,
  jsonb_agg((value->>'target')::int) targets FROM jsonb_array_elements(owned_edges)
  GROUP BY (value->>'source')::int LOOP
  children[adjacency.source+1]:=adjacency.targets;
 END LOOP;
 visited:=array_fill(false,ARRAY[node_count]);visited[delete_node+1]:=true;queue:=ARRAY[delete_node];
 WHILE head<=tail LOOP
  source_node:=queue[head];head:=head+1;
  FOR child IN SELECT value::int FROM jsonb_array_elements_text(children[source_node+1]) LOOP
   IF NOT visited[child+1] THEN
    visited[child+1]:=true;tail:=tail+1;queue[tail]:=child;
   END IF;
  END LOOP;
 END LOOP;
 SELECT array_agg(n ORDER BY n) INTO deleted FROM generate_series(0,node_count-1) n WHERE visited[n+1];
 FOR entry IN SELECT value FROM jsonb_array_elements(independent_edges) LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'exact independent edge required' USING ERRCODE='22023';END IF;
  IF entry-ARRAY['edge','source','target']<>'{}'::jsonb
   OR jsonb_typeof(entry->'edge') IS DISTINCT FROM 'number'
   OR jsonb_typeof(entry->'source') IS DISTINCT FROM 'number'
   OR jsonb_typeof(entry->'target') IS DISTINCT FROM 'number'
   OR (entry->>'edge') !~ '^(0|[1-9][0-9]{0,3})$'
   OR (entry->>'source') !~ '^(0|[1-9][0-9]{0,3})$'
   OR (entry->>'target') !~ '^(0|[1-9][0-9]{0,3})$' THEN
   RAISE EXCEPTION 'closed bounded independent edge required' USING ERRCODE='22023';END IF;
  edge_number:=(entry->>'edge')::int;
  source_node:=(entry->>'source')::int;target_node:=(entry->>'target')::int;
  -- Boundary witnesses occupy the following 256 ordinals. They cannot be
  -- selected for deletion or reached through owned_edges.
  IF edge_number>=1024 OR source_node>=node_count+256 OR target_node>=node_count+256
   OR seen_edges[edge_number+1] THEN
   RAISE EXCEPTION 'unique local edge correspondence required' USING ERRCODE='22023';END IF;
  seen_edges[edge_number+1]:=true;
  IF coalesce(visited[source_node+1],false) OR coalesce(visited[target_node+1],false) THEN
   RAISE EXCEPTION 'independent incident edge prevents owned deletion' USING ERRCODE='22023';END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg((value->>'edge')::int ORDER BY (value->>'edge')::int),'[]'::jsonb)
  INTO deleted_edges FROM jsonb_array_elements(owned_edges)
  WHERE visited[(value->>'source')::int+1] OR visited[(value->>'target')::int+1];
 RETURN jsonb_build_object('deletedNodes',to_jsonb(deleted),'deletedEdges',deleted_edges);
END;
$function$

CREATE OR REPLACE FUNCTION truss.owned_forest_projection(node_count integer, owned_edges jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE parents int[];seen_edges boolean[];entry jsonb;edge_number int;source_node int;target_node int;
 node_number int;ancestor int;path int[];path_count int;path_index int;root_node int;
 marks int[];roots int[];result_json jsonb;
BEGIN
 IF node_count IS NULL OR node_count NOT BETWEEN 0 AND 2048 THEN
  RAISE EXCEPTION 'bounded local node count required' USING ERRCODE='54000';END IF;
 IF jsonb_typeof(owned_edges) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'explicit local owned edges required' USING ERRCODE='22023';END IF;
 IF octet_length(convert_to(owned_edges::text,'UTF8'))>1048576 OR jsonb_array_length(owned_edges)>1024 THEN
  RAISE EXCEPTION 'bounded local owned edges required' USING ERRCODE='54000';END IF;
 parents:=array_fill(-1,ARRAY[node_count]);roots:=array_fill(-1,ARRAY[node_count]);seen_edges:=array_fill(false,ARRAY[1024]);
 marks:=array_fill(0,ARRAY[node_count]);path:=array_fill(-1,ARRAY[node_count]);
 FOR entry IN SELECT value FROM jsonb_array_elements(owned_edges) LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'exact local edge required' USING ERRCODE='22023';END IF;
  IF entry-ARRAY['edge','source','target']<>'{}'::jsonb
   OR jsonb_typeof(entry->'edge') IS DISTINCT FROM 'number'
   OR jsonb_typeof(entry->'source') IS DISTINCT FROM 'number'
   OR jsonb_typeof(entry->'target') IS DISTINCT FROM 'number' THEN
   RAISE EXCEPTION 'closed local edge fields required' USING ERRCODE='22023';END IF;
  IF (entry->>'edge') !~ '^(0|[1-9][0-9]{0,3})$'
   OR (entry->>'source') !~ '^(0|[1-9][0-9]{0,3})$'
   OR (entry->>'target') !~ '^(0|[1-9][0-9]{0,3})$' THEN
   RAISE EXCEPTION 'bounded integer local references required' USING ERRCODE='22023';END IF;
  edge_number:=(entry->>'edge')::int;source_node:=(entry->>'source')::int;target_node:=(entry->>'target')::int;
  IF edge_number>=1024 OR source_node>=node_count OR target_node>=node_count THEN
   RAISE EXCEPTION 'local reference outside complete simulation' USING ERRCODE='22023';END IF;
  IF seen_edges[edge_number+1] THEN
   RAISE EXCEPTION 'duplicate local edge reference' USING ERRCODE='22023';END IF;
  seen_edges[edge_number+1]:=true;
  IF parents[target_node+1]<>-1 AND parents[target_node+1]<>source_node THEN
   RAISE EXCEPTION 'multiple ownership parents' USING ERRCODE='22023';END IF;
  parents[target_node+1]:=source_node;
 END LOOP;
 -- Resolve each parent chain once. A visiting node belongs to this walk;
 -- completed chains already retain the root for every member on their path.
 FOR node_number IN 0..node_count-1 LOOP
  IF marks[node_number+1]=2 THEN CONTINUE;END IF;
  ancestor:=node_number;path_count:=0;
  LOOP
   IF marks[ancestor+1]=2 THEN
    root_node:=CASE WHEN roots[ancestor+1]=-1 THEN ancestor ELSE roots[ancestor+1] END;
    EXIT;
   END IF;
   IF marks[ancestor+1]=1 THEN RAISE EXCEPTION 'ownership cycle' USING ERRCODE='22023';END IF;
   marks[ancestor+1]:=1;path_count:=path_count+1;path[path_count]:=ancestor;
   IF parents[ancestor+1]=-1 THEN root_node:=ancestor;EXIT;END IF;
   ancestor:=parents[ancestor+1];
  END LOOP;
  FOR path_index IN 1..path_count LOOP
   ancestor:=path[path_index];
   roots[ancestor+1]:=CASE WHEN ancestor=root_node THEN -1 ELSE root_node END;
   marks[ancestor+1]:=2;
  END LOOP;
 END LOOP;
 -- Assemble once after validation and the memoized root walk. Repeated JSONB
 -- concatenation and one full edge scan per node made this projection quadratic.
 SELECT coalesce(jsonb_agg(jsonb_build_object('node',n.node,
  'parent',nullif(parents[n.node+1],-1),'root',nullif(roots[n.node+1],-1),
  'incomingEdges',coalesce(incoming.edges,'[]'::jsonb)) ORDER BY n.node),'[]'::jsonb)
 INTO result_json FROM generate_series(0,node_count-1) n(node)
 LEFT JOIN (SELECT (value->>'target')::int target,
  jsonb_agg((value->>'edge')::int ORDER BY (value->>'edge')::int) edges
  FROM jsonb_array_elements(owned_edges) GROUP BY (value->>'target')::int) incoming
 ON incoming.target=n.node;
 IF octet_length(convert_to(result_json::text,'UTF8'))>4194304 THEN
  RAISE EXCEPTION 'bounded complete forest result required' USING ERRCODE='54000';END IF;
 RETURN result_json;
END;
$function$

CREATE OR REPLACE FUNCTION truss.owned_graph_scope(seeds jsonb, include_independent boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE node_keys text[]:='{}';edge_keys text[]:='{}';boundary_keys text[]:='{}';owned_edge_order text[]:='{}';
 nodes jsonb:='{}';node_images jsonb[]:='{}';edges jsonb:='{}';edge_images jsonb[]:='{}';boundary jsonb:='{}';boundary_images jsonb[]:='{}';
 types jsonb:='{}';type_images jsonb[]:='{}';relations jsonb:='{}';relation_images jsonb[]:='{}';node_positions jsonb;
 entry jsonb;image jsonb;relation_image jsonb;witness jsonb;definition jsonb;
 node_key text;edge_key text;root_key text;selected_type int;selected_id bigint;
 selected_node int:=1;projection jsonb;local_edges jsonb:='[]';seed_ordinal int:=0;duplicate_seed_ordinal bigint;
 result_json jsonb;used_bytes bigint:=0;head int;
BEGIN
 IF jsonb_typeof(seeds) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'explicit typed scope seeds required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(seeds) NOT BETWEEN 0 AND 1024 OR octet_length(convert_to(seeds::text,'UTF8'))>1048576 THEN
  RAISE EXCEPTION 'bounded scope seeds required' USING ERRCODE='54000';END IF;
 SELECT min(ordinal) INTO duplicate_seed_ordinal FROM (
  SELECT ordinal,row_number() OVER(PARTITION BY value->>'typeId',value->>'id' ORDER BY ordinal) occurrence
  FROM jsonb_array_elements(seeds) WITH ORDINALITY s(value,ordinal)) repeated WHERE occurrence>1;
 FOR entry IN SELECT value FROM jsonb_array_elements(seeds) WITH ORDINALITY s(value,ordinal) ORDER BY ordinal LOOP
  seed_ordinal:=seed_ordinal+1;
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'typed scope seed required' USING ERRCODE='22023';END IF;
  IF entry-ARRAY['typeId','id']<>'{}'::jsonb OR jsonb_typeof(entry->'typeId') IS DISTINCT FROM 'string'
   OR jsonb_typeof(entry->'id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'exact typed seed fields required' USING ERRCODE='22023';END IF;
  IF entry->>'typeId' !~ '^[1-9][0-9]{0,9}$' OR entry->>'id' !~ '^[1-9][0-9]{0,18}$' THEN
   RAISE EXCEPTION 'positive exact native seed identities required' USING ERRCODE='22023';END IF;
  IF (entry->>'typeId')::bigint>2147483647 OR (entry->>'id')::numeric>9223372036854775807 THEN
   RAISE EXCEPTION 'native seed identity range exceeded' USING ERRCODE='22023';END IF;
  IF seed_ordinal=duplicate_seed_ordinal THEN RAISE EXCEPTION 'duplicate scope seed' USING ERRCODE='22023';END IF;
 END LOOP;
 SELECT rev INTO STRICT head FROM truss.schema_head WHERE id=1;
 -- UNION owns the visited set. Nodes discover incident edge identities and
 -- owned edges discover both endpoints, without copying growing image maps.
 -- A valid component has at most 1024 nodes plus 1024 incident edges.
 WITH RECURSIVE seed_positions AS MATERIALIZED (
  SELECT (s.value->>'typeId')::int type_id,(s.value->>'id')::bigint object_id,s.ordinal
  FROM jsonb_array_elements(seeds) WITH ORDINALITY s(value,ordinal)),
 members(kind,member_type,member_id) AS (
  SELECT 'n'::text,s.type_id,s.object_id FROM seed_positions s
  UNION
  SELECT next_member.kind,next_member.member_type,next_member.member_id FROM members current_member
  CROSS JOIN LATERAL (
   -- Full observations use separate endpoint-index probes. Their output is
   -- canonically sorted after the visited-set union, so no unbounded sort is
   -- needed before the 1025-row refusal threshold.
   (SELECT 'e'::text kind,e.rel_type_id member_type,e.id member_id FROM truss.edge e
    WHERE current_member.kind='n' AND include_independent IS TRUE
     AND e.source_id=current_member.member_id AND e.source_type=current_member.member_type LIMIT 1025)
   UNION ALL
   (SELECT 'e'::text,e.rel_type_id,e.id FROM truss.edge e
    WHERE current_member.kind='n' AND include_independent IS TRUE
     AND e.target_id=current_member.member_id AND e.target_type=current_member.member_type LIMIT 1025)
   UNION ALL
   -- Partial observations enumerate only owned relation IDs before probing
   -- their source/target endpoint indexes. Unrelated independent degrees
   -- therefore do not enter a broad incident-edge scan.
   (SELECT 'e'::text,e.rel_type_id,e.id FROM
    (SELECT DISTINCT ep.rel_type_id FROM truss.rel_endpoint ep
     JOIN truss.rel_def selected_relation USING(rel_type_id)
     WHERE ep.source_type=current_member.member_type AND selected_relation.lifecycle='owned') owned_relation
    CROSS JOIN LATERAL (SELECT edge.id,edge.rel_type_id FROM truss.edge edge
     WHERE edge.source_id=current_member.member_id AND edge.source_type=current_member.member_type
      AND edge.rel_type_id=owned_relation.rel_type_id LIMIT 1025 OFFSET 0) e
    WHERE current_member.kind='n' AND include_independent IS NOT TRUE)
   UNION ALL
   (SELECT 'e'::text,e.rel_type_id,e.id FROM
    (SELECT DISTINCT ep.rel_type_id FROM truss.rel_endpoint ep
     JOIN truss.rel_def selected_relation USING(rel_type_id)
     WHERE ep.target_type=current_member.member_type AND selected_relation.lifecycle='owned') owned_relation
    CROSS JOIN LATERAL (SELECT edge.id,edge.rel_type_id FROM truss.edge edge
     WHERE edge.target_id=current_member.member_id AND edge.target_type=current_member.member_type
      AND edge.rel_type_id=owned_relation.rel_type_id LIMIT 1025 OFFSET 0) e
    WHERE current_member.kind='n' AND include_independent IS NOT TRUE)
   UNION ALL
   SELECT 'n'::text,endpoint.type_id,endpoint.object_id FROM truss.edge e
    JOIN truss.rel_def r ON r.rel_type_id=e.rel_type_id
    CROSS JOIN LATERAL (VALUES(e.source_type,e.source_id),(e.target_type,e.target_id)) endpoint(type_id,object_id)
    WHERE current_member.kind='e' AND e.id=current_member.member_id AND e.rel_type_id=current_member.member_type
     AND r.lifecycle='owned'
  ) next_member),
 bounded AS MATERIALIZED (SELECT * FROM members LIMIT 2049)
 SELECT coalesce(array_agg(b.member_type::text||':'||b.member_id::text
   ORDER BY coalesce(s.ordinal,2147483647),b.member_type,b.member_id) FILTER(WHERE b.kind='n'),'{}'::text[]),
  coalesce(array_agg(b.member_id::text ORDER BY b.member_id) FILTER(WHERE b.kind='e'),'{}'::text[])
 INTO node_keys,edge_keys FROM bounded b LEFT JOIN seed_positions s
  ON b.kind='n' AND s.type_id=b.member_type AND s.object_id=b.member_id;
 IF cardinality(node_keys)>1024 OR cardinality(edge_keys)>1024 THEN
  RAISE EXCEPTION 'bounded complete ownership component required' USING ERRCODE='54000';END IF;
 SELECT coalesce(jsonb_object_agg(n.key,n.ordinal-1),'{}'::jsonb) INTO node_positions
 FROM unnest(node_keys) WITH ORDINALITY n(key,ordinal);
 FOREACH node_key IN ARRAY node_keys LOOP
  selected_type:=split_part(node_key,':',1)::int;selected_id:=split_part(node_key,':',2)::bigint;
  SELECT to_jsonb(o) INTO STRICT image FROM truss.object o WHERE o.id=selected_id AND o.type_id=selected_type;
  used_bytes:=used_bytes+octet_length(convert_to(image::text,'UTF8'));
  IF used_bytes>4194304 THEN RAISE EXCEPTION 'bounded complete graph image required' USING ERRCODE='54000';END IF;
  node_images[selected_node]:=image;
  selected_node:=selected_node+1;
 END LOOP;
 FOR selected_type IN SELECT DISTINCT split_part(n.key,':',1)::int FROM unnest(node_keys) n(key) ORDER BY 1 LOOP
  SELECT to_jsonb(t) INTO STRICT definition FROM truss.type_def t WHERE t.type_id=selected_type;
  used_bytes:=used_bytes+octet_length(convert_to(definition::text,'UTF8'));
  IF used_bytes>4194304 THEN RAISE EXCEPTION 'bounded complete graph image required' USING ERRCODE='54000';END IF;
  type_images[cardinality(type_images)+1]:=definition;
 END LOOP;
 FOREACH edge_key IN ARRAY edge_keys LOOP
  SELECT to_jsonb(e) INTO STRICT image FROM truss.edge e WHERE e.id=edge_key::bigint;
  used_bytes:=used_bytes+octet_length(convert_to(image::text,'UTF8'));
  IF used_bytes>4194304 THEN RAISE EXCEPTION 'bounded complete graph image required' USING ERRCODE='54000';END IF;
  edge_images[cardinality(edge_images)+1]:=image;
 END LOOP;
 FOR selected_type IN SELECT DISTINCT (e.image->>'rel_type_id')::int FROM unnest(edge_images) e(image) ORDER BY 1 LOOP
  SELECT to_jsonb(r) INTO STRICT relation_image FROM truss.rel_def r WHERE r.rel_type_id=selected_type;
  IF relation_image->>'lifecycle' NOT IN ('owned','independent') OR relation_image->'retired_rev'<>'null'::jsonb THEN
   RAISE EXCEPTION 'supported current incident lifecycle required' USING ERRCODE='0A000';END IF;
  IF relation_image->>'lifecycle'='owned' AND (relation_image->'directed'<>'true'::jsonb
   OR relation_image->'composition'<>'false'::jsonb OR relation_image->'assoc_type_id'<>'null'::jsonb) THEN
   RAISE EXCEPTION 'selected parent to target ownership required' USING ERRCODE='0A000';END IF;
  used_bytes:=used_bytes+octet_length(convert_to(relation_image::text,'UTF8'));
  IF used_bytes>4194304 THEN RAISE EXCEPTION 'bounded complete graph image required' USING ERRCODE='54000';END IF;
  relation_images[cardinality(relation_images)+1]:=relation_image;
 END LOOP;
 SELECT coalesce(jsonb_object_agg(c.node_key,c.image),'{}'::jsonb) INTO nodes
 FROM unnest(node_keys,node_images) AS c(node_key,image);
 SELECT coalesce(jsonb_object_agg(c.edge_key,c.image),'{}'::jsonb) INTO edges
 FROM unnest(edge_keys,edge_images) AS c(edge_key,image);
 SELECT coalesce(jsonb_object_agg(t.image->>'type_id',t.image),'{}'::jsonb) INTO types FROM unnest(type_images) t(image);
 SELECT coalesce(jsonb_object_agg(r.image->>'rel_type_id',r.image),'{}'::jsonb) INTO relations FROM unnest(relation_images) r(image);
 WITH owned AS (
  SELECT e.image,row_number() OVER(ORDER BY (e.image->>'id')::bigint)-1 ordinal
  FROM unnest(edge_images) e(image) JOIN truss.rel_def r ON r.rel_type_id=(e.image->>'rel_type_id')::int WHERE r.lifecycle='owned')
 SELECT coalesce(jsonb_agg(jsonb_build_object('edge',o.ordinal,
   'source',(node_positions->>((o.image->>'source_type')||':'||(o.image->>'source_id')))::int,
   'target',(node_positions->>((o.image->>'target_type')||':'||(o.image->>'target_id')))::int) ORDER BY o.ordinal),'[]'::jsonb),
  coalesce(array_agg(o.image->>'id' ORDER BY o.ordinal),'{}'::text[])
 INTO local_edges,owned_edge_order FROM owned o;
 -- Independent endpoints and their roots are witnesses, not traversed nodes.
 WITH RECURSIVE witnesses(type_id,object_id) AS (
  SELECT endpoint.type_id,endpoint.object_id FROM unnest(edge_images) e(image)
   JOIN truss.rel_def r ON r.rel_type_id=(e.image->>'rel_type_id')::int
   CROSS JOIN LATERAL (VALUES((e.image->>'source_type')::int,(e.image->>'source_id')::bigint),
    ((e.image->>'target_type')::int,(e.image->>'target_id')::bigint)) endpoint(type_id,object_id)
   WHERE r.lifecycle='independent' AND NOT (node_positions ? (endpoint.type_id::text||':'||endpoint.object_id::text))
  UNION
  SELECT o.root_type,o.root_id FROM witnesses w JOIN truss.object o ON o.id=w.object_id AND o.type_id=w.type_id
   WHERE o.root_id IS NOT NULL AND NOT (node_positions ? (o.root_type::text||':'||o.root_id::text)))
 SELECT coalesce(array_agg(w.type_id::text||':'||w.object_id::text ORDER BY w.type_id,w.object_id),'{}'::text[])
 INTO boundary_keys FROM (SELECT * FROM witnesses LIMIT 257) w;
 IF cardinality(boundary_keys)>256 THEN RAISE EXCEPTION 'bounded boundary witnesses required' USING ERRCODE='54000';END IF;
 FOREACH node_key IN ARRAY boundary_keys LOOP
  selected_type:=split_part(node_key,':',1)::int;selected_id:=split_part(node_key,':',2)::bigint;
  SELECT jsonb_build_object('id',o.id,'type_id',o.type_id,'root_id',o.root_id,'root_type',o.root_type,'rev',o.rev,'ver',o.ver)
   INTO STRICT witness FROM truss.object o WHERE o.id=selected_id AND o.type_id=selected_type;
  SELECT to_jsonb(t) INTO STRICT definition FROM truss.type_def t WHERE t.type_id=selected_type;
  boundary_images[cardinality(boundary_images)+1]:=jsonb_build_object('object',witness,'definition',definition);
  used_bytes:=used_bytes+octet_length(convert_to(witness::text,'UTF8'))+octet_length(convert_to(definition::text,'UTF8'));
  IF used_bytes>4194304 THEN RAISE EXCEPTION 'bounded complete graph image required' USING ERRCODE='54000';END IF;
 END LOOP;
 SELECT coalesce(jsonb_object_agg(b.key,b.image),'{}'::jsonb) INTO boundary
 FROM unnest(boundary_keys,boundary_images) b(key,image);
 -- An aggregate root pointer without a connecting owned-edge path is corrupt
 -- membership, not permission to invent an edge or silently omit a cascade child.
 IF EXISTS(SELECT 1 FROM unnest(node_keys) n(node_key) JOIN truss.object o
   ON o.root_type=split_part(n.node_key,':',1)::int AND o.root_id=split_part(n.node_key,':',2)::bigint
   WHERE NOT (node_positions ? (o.type_id::text||':'||o.id::text)) LIMIT 1) THEN
  RAISE EXCEPTION 'complete stored aggregate membership correspondence required' USING ERRCODE='55000';
 END IF;
 projection:=truss.owned_forest_projection(cardinality(node_keys),local_edges);
 FOR entry IN SELECT value FROM jsonb_array_elements(projection) LOOP
  image:=nodes->node_keys[(entry->>'node')::int+1];
  IF entry->'root'='null'::jsonb THEN
   IF image->'root_id'<>'null'::jsonb OR image->'root_type'<>'null'::jsonb THEN RAISE EXCEPTION 'current rootless correspondence required' USING ERRCODE='55000';END IF;
  ELSE
   root_key:=node_keys[(entry->>'root')::int+1];
   IF (image->>'root_type')||':'||(image->>'root_id') IS DISTINCT FROM root_key THEN
    RAISE EXCEPTION 'current aggregate root correspondence required' USING ERRCODE='55000';END IF;
  END IF;
 END LOOP;
 result_json:=jsonb_build_object('catalogRevision',head,'nodeOrder',node_keys,'ownedEdgeOrder',owned_edge_order,'nodes',nodes,'edges',edges,
  'types',types,'relationships',relations,'boundary',boundary,'forest',projection);
 IF include_independent IS NOT TRUE THEN result_json:=result_json||jsonb_build_object('independentEdgesIncluded',false);END IF;
 IF octet_length(convert_to(result_json::text,'UTF8'))>4194304 THEN RAISE EXCEPTION 'bounded complete graph image result required' USING ERRCODE='54000';END IF;
 RETURN result_json;
END;
$function$

CREATE OR REPLACE FUNCTION truss.owned_object_values(selected_type integer, operation jsonb, prior_props jsonb, prior_retained jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE authored jsonb;removed jsonb;props jsonb;retained jsonb;removed_props text[];removed_retained text[];set_props jsonb;set_retained jsonb;
 property truss.prop_def%ROWTYPE;values_json jsonb;keys_json jsonb;result_json jsonb;
BEGIN
 IF jsonb_typeof(operation) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'explicit operation value projection required' USING ERRCODE='22023';END IF;
 IF octet_length(operation::text)>1048576 OR coalesce(octet_length(prior_props::text),0)+coalesce(octet_length(prior_retained::text),0)>1048576 THEN
  RAISE EXCEPTION 'bounded value simulation input required' USING ERRCODE='54000';END IF;
 IF NOT EXISTS(SELECT 1 FROM truss.type_def t WHERE t.type_id=selected_type AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL) THEN
  RAISE EXCEPTION 'current admitted Record required' USING ERRCODE='22023';END IF;
 IF operation->>'operation'='create_object' THEN
  IF prior_props IS NOT NULL OR prior_retained IS NOT NULL THEN RAISE EXCEPTION 'create has no prior image' USING ERRCODE='22023';END IF;
  authored:=operation->'values';removed:='[]';props:='{}';retained:='{}';
 ELSIF operation->>'operation'='update_object' THEN
  IF jsonb_typeof(prior_props) IS DISTINCT FROM 'object' OR (prior_retained IS NOT NULL AND jsonb_typeof(prior_retained) IS DISTINCT FROM 'object') THEN
   RAISE EXCEPTION 'complete simulated prior values required' USING ERRCODE='22023';END IF;
  authored:=operation->'set';removed:=operation->'unset';props:=prior_props;retained:=coalesce(prior_retained,'{}');
 ELSE RAISE EXCEPTION 'create or update value simulation required' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(authored) IS DISTINCT FROM 'array' OR jsonb_typeof(removed) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'explicit authored arrays required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(authored)>1024 OR jsonb_array_length(removed)>1024 THEN RAISE EXCEPTION 'bounded authored values required' USING ERRCODE='54000';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(authored) v WHERE v.value-ARRAY['name','value']<>'{}'::jsonb
   OR jsonb_typeof(v.value->'name') IS DISTINCT FROM 'string' OR octet_length(v.value->>'name') NOT BETWEEN 1 AND 4096
   OR truss.valid_flat_cell(v.value->'value') IS NOT TRUE)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(removed) v WHERE jsonb_typeof(v.value) IS DISTINCT FROM 'string' OR octet_length(v.value#>>'{}') NOT BETWEEN 1 AND 4096)
  OR jsonb_array_length(authored)<>(SELECT count(DISTINCT v.value->>'name') FROM jsonb_array_elements(authored) v)
  OR jsonb_array_length(removed)<>(SELECT count(DISTINCT v.value) FROM jsonb_array_elements(removed) v)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(authored) a JOIN jsonb_array_elements(removed) r ON a.value->>'name'=r.value#>>'{}') THEN
  RAISE EXCEPTION 'unique disjoint exact authored values required' USING ERRCODE='22023';END IF;
 -- Refuse unknown physical cells rather than silently dropping them while planning.
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(props) k WHERE NOT EXISTS(
   SELECT 1 FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL AND p.prop_id::text=k))
  OR EXISTS(SELECT 1 FROM jsonb_each(retained) e WHERE truss.valid_flat_cell(e.value) IS NOT TRUE) THEN
  RAISE EXCEPTION 'supported complete prior value representation required' USING ERRCODE='0A000';END IF;
 SELECT coalesce(array_agg(p.prop_id::text) FILTER(WHERE p.prop_id IS NOT NULL),'{}'::text[]),
  coalesce(array_agg(u.name) FILTER(WHERE p.prop_id IS NULL),'{}'::text[])
 INTO removed_props,removed_retained
 FROM jsonb_array_elements_text(removed) u(name)
 LEFT JOIN truss.prop_def p ON p.type_id=selected_type AND p.retired_rev IS NULL AND p.name=u.name;
 props:=props-removed_props;retained:=retained-removed_retained;
 SELECT coalesce(jsonb_object_agg(p.prop_id::text,truss.canonical_flat_cell(a.value->'value')) FILTER(WHERE p.prop_id IS NOT NULL),'{}'::jsonb),
  coalesce(jsonb_object_agg(a.value->>'name',truss.canonical_flat_cell(a.value->'value')) FILTER(WHERE p.prop_id IS NULL),'{}'::jsonb)
 INTO set_props,set_retained
 FROM jsonb_array_elements(authored) a(value)
 LEFT JOIN truss.prop_def p ON p.type_id=selected_type AND p.retired_rev IS NULL AND p.name=a.value->>'name';
 props:=props||set_props;retained:=retained||set_retained;
 FOR property IN SELECT p.* FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL LOOP
  IF truss.valid_property_definition(property) IS NOT TRUE THEN RAISE EXCEPTION 'supported exact property definition required' USING ERRCODE='0A000';END IF;
  IF NOT props ? property.prop_id::text THEN
   IF property.nullability='required' THEN RAISE EXCEPTION 'missing required value' USING ERRCODE='22023';END IF;
  ELSIF truss.valid_property_value(props->property.prop_id::text,property) IS NOT TRUE THEN
   RAISE EXCEPTION 'exact declared value required' USING ERRCODE='22023';END IF;
 END LOOP;
 IF octet_length(convert_to(jsonb_build_object('props',props,'retained',retained)::text,'UTF8'))>1048576 THEN
  RAISE EXCEPTION 'bounded complete object values required' USING ERRCODE='54000';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',v.name,'value',v.value) ORDER BY v.name COLLATE "C"),'[]'::jsonb) INTO values_json FROM (
  SELECT p.name,props->p.prop_id::text AS value FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL AND props ? p.prop_id::text
  UNION ALL SELECT key,value FROM jsonb_each(retained)) v;
 SELECT coalesce(jsonb_agg(jsonb_build_object('keyNumber',k.key_num::text,'keyId',k.key_id,'names',
  (SELECT jsonb_agg(p.name ORDER BY i.ord) FROM unnest(k.prop_ids) WITH ORDINALITY i(prop_id,ord)
   JOIN truss.prop_def p ON p.type_id=k.type_id AND p.prop_id=i.prop_id)) ORDER BY k.key_num),'[]'::jsonb)
  INTO keys_json FROM truss.key_def k WHERE k.type_id=selected_type AND k.retired_rev IS NULL;
 result_json:=jsonb_build_object('props',props,'retained',retained,'values',values_json,'keys',keys_json);
 IF octet_length(convert_to(result_json::text,'UTF8'))>4194304 THEN RAISE EXCEPTION 'bounded complete value simulation result required' USING ERRCODE='54000';END IF;
 RETURN result_json;
END;
$function$

CREATE OR REPLACE FUNCTION truss.page_edges(selected_document text, selected_module text, selected_relationship text, anchor jsonb, direction text, page_limit integer, maximum_bytes integer, original_cursor bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE relation truss.rel_def%ROWTYPE;selected truss.type_def%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;
 frozen record;anchor_object truss.object;anchor_root truss.object;anchor_root_definition truss.type_def;root_owner_buffer jsonb[]:=ARRAY[]::jsonb[];root_owners jsonb;edge_context jsonb;root_owner jsonb;
 context jsonb;continuation jsonb;cursor_value jsonb;candidate record;edge_value jsonb;lookahead jsonb;edge_buffer jsonb[]:=ARRAY[]::jsonb[];edges jsonb;edge_bytes bigint:=2;edge_item_bytes bigint;last_key text;last_id bigint;result bytea;revision int;
BEGIN
 PERFORM truss.runtime_person(false);
 IF page_limit IS NULL OR page_limit NOT BETWEEN 1 AND 1000 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 OR direction NOT IN ('outgoing','incoming') OR direction IS NULL THEN RAISE EXCEPTION 'bounded directed page required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'selected edge page runtime required' USING ERRCODE='0A000';END IF;
 SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 SELECT * INTO relation FROM truss.rel_def WHERE document_id=selected_document AND module=selected_module AND rel_id=selected_relationship AND retired_rev IS NULL;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF relation.lifecycle NOT IN ('independent','owned') OR NOT relation.directed OR relation.composition OR relation.assoc_type_id IS NOT NULL THEN RAISE EXCEPTION 'selected directed scalar relationship required' USING ERRCODE='0A000';END IF;
 selected:=truss.runtime_condition_type(anchor);
 IF NOT truss.runtime_can_read(selected.document_id,selected.module) THEN RETURN NULL;END IF;
 SELECT o AS object,ro AS root,rt AS root_definition INTO frozen FROM truss.object o
 LEFT JOIN truss.object ro ON ro.id=o.root_id AND ro.type_id=o.root_type
 LEFT JOIN truss.type_def rt ON rt.type_id=ro.type_id AND rt.retired_rev IS NULL
 WHERE o.id=(anchor->>'id')::bigint AND o.type_id=selected.type_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 anchor_object:=frozen.object;anchor_root:=frozen.root;anchor_root_definition:=frozen.root_definition;
 IF anchor_object.rev>revision THEN RAISE EXCEPTION 'anchor catalog changed' USING ERRCODE='55P03';END IF;
 IF anchor_object.root_id IS NOT NULL OR anchor_object.root_type IS NOT NULL THEN
  IF anchor_object.root_id IS NULL OR anchor_object.root_type IS NULL OR anchor_root.id IS NULL OR anchor_root_definition.type_id IS NULL
   OR anchor_root.root_id IS NOT NULL OR anchor_root.root_type IS NOT NULL
   OR anchor_root.id=anchor_object.id AND anchor_root.type_id=anchor_object.type_id
   OR anchor_root_definition.kind<>'record' OR anchor_root_definition.provisional THEN RAISE EXCEPTION 'current anchor aggregate root required' USING ERRCODE='55000';END IF;
  IF anchor_root.rev>revision OR anchor_root_definition.since_rev>revision THEN RAISE EXCEPTION 'anchor root catalog changed' USING ERRCODE='55P03';END IF;
  IF NOT truss.runtime_can_read(anchor_root_definition.document_id,anchor_root_definition.module) THEN RETURN NULL;END IF;
  root_owner_buffer:=array_append(root_owner_buffer,jsonb_build_object('documentId',anchor_root_definition.document_id,'moduleId',anchor_root_definition.module));
 END IF;
 context:=jsonb_build_object('profile','truss-python-edge-page/0.1','installationId',installation.installation_id::text,'releaseSha256',expected_digest,
  'catalogRevision',revision::text,'relationshipPin',truss.runtime_relationship_pin(relation.rel_type_id),'anchor',anchor,'direction',direction);
 IF original_cursor IS NOT NULL THEN
  IF octet_length(original_cursor) NOT BETWEEN 1 AND 65536 OR (convert_from(original_cursor,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'bounded exact edge cursor required' USING ERRCODE='22023';END IF;
  cursor_value:=convert_from(original_cursor,'UTF8')::jsonb;
  IF cursor_value-ARRAY['afterId','afterKey'] IS DISTINCT FROM context THEN RAISE EXCEPTION 'current edge cursor context required' USING ERRCODE='P1002';END IF;
  IF jsonb_typeof(cursor_value->'afterId') IS DISTINCT FROM 'string' OR cursor_value->>'afterId' !~ '^[1-9][0-9]{0,18}$'
   OR length(cursor_value->>'afterId')=19 AND (cursor_value->>'afterId') COLLATE "C">'9223372036854775807'
   OR jsonb_typeof(cursor_value->'afterKey') NOT IN ('string','null') OR NOT cursor_value ? 'afterKey' THEN RAISE EXCEPTION 'exact paired edge cursor required' USING ERRCODE='22023';END IF;
  last_id:=(cursor_value->>'afterId')::bigint;last_key:=cursor_value->>'afterKey';
 END IF;
 FOR candidate IN SELECT e.id,e.order_key,s.document_id source_document,s.module source_module,t.document_id target_document,t.module target_module FROM truss.edge e JOIN truss.type_def s ON s.type_id=e.source_type JOIN truss.type_def t ON t.type_id=e.target_type
  WHERE e.rel_type_id=relation.rel_type_id AND CASE direction WHEN 'outgoing' THEN e.source_id=(anchor->>'id')::bigint AND e.source_type=selected.type_id ELSE e.target_id=(anchor->>'id')::bigint AND e.target_type=selected.type_id END
   AND truss.runtime_can_read(s.document_id,s.module) AND truss.runtime_can_read(t.document_id,t.module)
   AND (original_cursor IS NULL OR last_key IS NULL AND e.order_key IS NULL AND e.id>last_id
    OR last_key IS NOT NULL AND (e.order_key IS NULL OR e.order_key COLLATE "C">last_key COLLATE "C" OR e.order_key=last_key AND e.id>last_id))
  ORDER BY e.order_key COLLATE "C" NULLS LAST,e.id LIMIT page_limit+1 LOOP
  edge_context:=truss.runtime_edge_read(selected_document,selected_module,selected_relationship,candidate.id,16777216,expected_release,expected_digest);
  edge_value:=edge_context->'edge';
  IF edge_value IS NULL THEN RAISE EXCEPTION 'edge page authority changed' USING ERRCODE='55P03';END IF;
  FOR root_owner IN SELECT value FROM jsonb_array_elements(edge_context->'rootOwners') LOOP
   root_owner_buffer:=array_append(root_owner_buffer,root_owner);
  END LOOP;
  IF edge_value->'identity'->>'id' IS DISTINCT FROM candidate.id::text OR edge_value->'identity'->>'typeId' IS DISTINCT FROM relation.rel_type_id::text
   OR (CASE direction WHEN 'outgoing' THEN edge_value->'source' ELSE edge_value->'target' END) IS DISTINCT FROM anchor
   OR edge_value->'orderKey'->>'text' IS DISTINCT FROM candidate.order_key THEN RAISE EXCEPTION 'edge page selection changed' USING ERRCODE='55P03';END IF;
  IF cardinality(edge_buffer)=page_limit THEN continuation:=context||jsonb_build_object('afterId',last_id::text,'afterKey',last_key);
   lookahead:=jsonb_build_object('sourceDocument',edge_value->'source'->'owner'->>'documentId','sourceModule',edge_value->'source'->'owner'->>'moduleId','targetDocument',edge_value->'target'->'owner'->>'documentId','targetModule',edge_value->'target'->'owner'->>'moduleId');EXIT;END IF;
  edge_item_bytes:=octet_length(edge_value::text);
  edge_bytes:=edge_bytes+edge_item_bytes+CASE WHEN cardinality(edge_buffer)>0 THEN 2 ELSE 0 END;
  IF edge_bytes>maximum_bytes THEN RAISE EXCEPTION 'bounded complete edge page required' USING ERRCODE='54000';END IF;
  edge_buffer:=array_append(edge_buffer,edge_value);last_id:=candidate.id;last_key:=candidate.order_key;
 END LOOP;
 edges:=to_jsonb(edge_buffer);IF edges IS NULL THEN edges:='[]'::jsonb;END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) INTO root_owners
  FROM (SELECT DISTINCT value FROM unnest(root_owner_buffer) AS roots(value)) unique_roots;
 IF octet_length(root_owners::text)>16777216 THEN RAISE EXCEPTION 'bounded edge page authority context required' USING ERRCODE='54000';END IF;
 FOR edge_value IN SELECT value FROM jsonb_array_elements(edges) LOOP
  IF NOT truss.runtime_can_read(edge_value->'source'->'owner'->>'documentId',edge_value->'source'->'owner'->>'moduleId') OR NOT truss.runtime_can_read(edge_value->'target'->'owner'->>'documentId',edge_value->'target'->'owner'->>'moduleId') THEN RAISE EXCEPTION 'current endpoint page reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF lookahead IS NOT NULL AND (NOT truss.runtime_can_read(lookahead->>'sourceDocument',lookahead->>'sourceModule') OR NOT truss.runtime_can_read(lookahead->>'targetDocument',lookahead->>'targetModule')) THEN RAISE EXCEPTION 'lookahead page authority changed' USING ERRCODE='55P03';END IF;
 IF NOT truss.runtime_can_read(selected_document,selected_module) OR NOT truss.runtime_can_read(selected.document_id,selected.module) THEN RAISE EXCEPTION 'current relationship and anchor page reader required' USING ERRCODE='42501';END IF;
 FOR root_owner IN SELECT value FROM jsonb_array_elements(root_owners) LOOP
  IF NOT truss.runtime_can_read(root_owner->>'documentId',root_owner->>'moduleId') THEN RAISE EXCEPTION 'current endpoint page root reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM revision THEN RAISE EXCEPTION 'edge page catalog changed' USING ERRCODE='55P03';END IF;
 result:=convert_to(jsonb_build_object('edges',edges,'catalogRevision',revision,'continuation',continuation)::text,'UTF8');
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'bounded complete edge page required' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.page_import_load_audit(filters jsonb, maximum_entries integer, original_cursor bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE actor oid;installation truss.catalog_runtime_installation%ROWTYPE;
 filter_sha text;cursor_value jsonb;frontier xid8;last_observed timestamptz;last_invocation uuid;
 candidate record;cursor_bytes bytea;owner jsonb;owners jsonb;entries jsonb;observed_chunks jsonb;
 source_row truss.runtime_import_load_chunk%ROWTYPE;visible_count int;expected_chunks int;state_value text;
 created_count int;skipped_count int;rejected_count int;observed_from timestamptz;observed_until timestamptz;
 release_check boolean;from_time timestamptz;until_time timestamptz;selected_owners jsonb;
BEGIN
 actor:=truss.runtime_person(false);
 IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a
   WHERE truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
  RAISE EXCEPTION 'current import audit enrollment required' USING ERRCODE='42501';END IF;
 IF filters IS NULL OR jsonb_typeof(filters) IS DISTINCT FROM 'object'
  OR filters-ARRAY['invocationId','loadId','nativeActorOid','documentId','moduleId','observedAtFrom','observedAtUntil']<>'{}'::jsonb
  OR maximum_entries IS NULL OR maximum_entries NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'bounded import audit listing required' USING ERRCODE='22023';END IF;
 IF filters ? 'invocationId' AND (jsonb_typeof(filters->'invocationId') IS DISTINCT FROM 'string'
  OR filters->>'invocationId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  OR filters ? 'loadId' AND (jsonb_typeof(filters->'loadId') IS DISTINCT FROM 'string'
   OR octet_length(filters->>'loadId') NOT BETWEEN 1 AND 4096)
  OR filters ? 'nativeActorOid' AND (jsonb_typeof(filters->'nativeActorOid') IS DISTINCT FROM 'string'
   OR filters->>'nativeActorOid' !~ '^[1-9][0-9]{0,9}$' OR (filters->>'nativeActorOid')::numeric>4294967295)
  OR (filters ? 'documentId') IS DISTINCT FROM (filters ? 'moduleId')
  OR filters ? 'documentId' IS NOT TRUE OR filters ? 'moduleId' IS NOT TRUE
  OR filters ? 'documentId' AND (jsonb_typeof(filters->'documentId') IS DISTINCT FROM 'string'
   OR octet_length(filters->>'documentId') NOT BETWEEN 1 AND 4096
   OR jsonb_typeof(filters->'moduleId') IS DISTINCT FROM 'string'
   OR octet_length(filters->>'moduleId') NOT BETWEEN 1 AND 4096)
  OR filters ? 'observedAtFrom' AND (jsonb_typeof(filters->'observedAtFrom') IS DISTINCT FROM 'string'
   OR filters->>'observedAtFrom' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$')
  OR filters ? 'observedAtUntil' AND (jsonb_typeof(filters->'observedAtUntil') IS DISTINCT FROM 'string'
   OR filters->>'observedAtUntil' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$') THEN
  RAISE EXCEPTION 'canonical import audit listing filters required' USING ERRCODE='22023';END IF;
 IF filters ? 'observedAtFrom' OR filters ? 'observedAtUntil' THEN
  BEGIN
   from_time:=CASE WHEN filters ? 'observedAtFrom' THEN (filters->>'observedAtFrom')::timestamptz END;
   until_time:=CASE WHEN filters ? 'observedAtUntil' THEN (filters->>'observedAtUntil')::timestamptz END;
  EXCEPTION WHEN SQLSTATE '22007' OR SQLSTATE '22008' THEN
   RAISE EXCEPTION 'canonical import audit time filters required' USING ERRCODE='22023';END;
  IF from_time IS NOT NULL AND until_time IS NOT NULL AND from_time>=until_time THEN
   RAISE EXCEPTION 'ordered import audit observed-time range required' USING ERRCODE='22023';END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a
   WHERE a.document_id=filters->>'documentId' AND a.module=filters->>'moduleId'
    AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
  RAISE EXCEPTION 'qualified import audit module enrollment required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest
  OR pg_is_in_recovery() THEN RAISE EXCEPTION 'current import audit release required' USING ERRCODE='0A000';END IF;
 filter_sha:=encode(sha256(convert_to(filters::text,'UTF8')),'hex');
 frontier:=pg_catalog.pg_snapshot_xmin(pg_catalog.pg_current_snapshot());
 IF original_cursor IS NOT NULL THEN
  IF octet_length(original_cursor) NOT BETWEEN 1 AND 65536
   OR (convert_from(original_cursor,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
   RAISE EXCEPTION 'bounded exact import audit listing cursor required' USING ERRCODE='22023';END IF;
  cursor_value:=convert_from(original_cursor,'UTF8')::jsonb;
  IF cursor_value-ARRAY['profile','installationId','sourceEpoch','releaseId','releaseSha256','frontierXid',
       'filtersSha256','afterObservedAt','afterInvocationId']<>'{}'::jsonb
   OR cursor_value->>'profile' IS DISTINCT FROM 'truss-import-load-audit-cursor/0.2'
   OR cursor_value->>'installationId' IS DISTINCT FROM installation.installation_id::text
   OR cursor_value->>'sourceEpoch' IS DISTINCT FROM installation.source_epoch::text
   OR cursor_value->>'releaseId' IS DISTINCT FROM expected_release
   OR cursor_value->>'releaseSha256' IS DISTINCT FROM expected_digest
   OR cursor_value->>'filtersSha256' IS DISTINCT FROM filter_sha
   OR jsonb_typeof(cursor_value->'frontierXid') IS DISTINCT FROM 'string'
   OR cursor_value->>'frontierXid' !~ '^[1-9][0-9]{0,19}$'
   OR (cursor_value->>'frontierXid')::numeric>18446744073709551615
   OR jsonb_typeof(cursor_value->'afterObservedAt') IS DISTINCT FROM 'string'
   OR cursor_value->>'afterObservedAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
   OR jsonb_typeof(cursor_value->'afterInvocationId') IS DISTINCT FROM 'string'
   OR cursor_value->>'afterInvocationId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
   RAISE EXCEPTION 'current import audit listing cursor context required' USING ERRCODE='P1002';END IF;
  frontier:=(cursor_value->>'frontierXid')::xid8;
  BEGIN last_observed:=(cursor_value->>'afterObservedAt')::timestamptz;
  EXCEPTION WHEN SQLSTATE '22007' OR SQLSTATE '22008' THEN
   RAISE EXCEPTION 'canonical import audit cursor time required' USING ERRCODE='22023';END;
  last_invocation:=(cursor_value->>'afterInvocationId')::uuid;
  IF cursor_value IS DISTINCT FROM convert_from(truss.runtime_import_load_audit_cursor(
    installation.installation_id,installation.source_epoch,expected_release,expected_digest,
    frontier,filter_sha,last_observed,last_invocation),'UTF8')::jsonb
   OR frontier>pg_catalog.pg_snapshot_xmin(pg_catalog.pg_current_snapshot()) THEN
   RAISE EXCEPTION 'exact frozen import audit listing cursor required' USING ERRCODE='P1002';END IF;
 ELSE
  last_observed:='infinity'::timestamptz;last_invocation:='ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid;
 END IF;
 FOR candidate IN
  SELECT c.invocation_id,max(c.audit_observed_at) observed_until
   FROM truss.runtime_import_load_chunk c
   WHERE c.writer_xid<frontier
   GROUP BY c.invocation_id
   HAVING (original_cursor IS NULL OR (max(c.audit_observed_at),c.invocation_id)<(last_observed,last_invocation))
    AND (NOT filters ? 'documentId' OR bool_or(c.original_owners @> jsonb_build_array(
      jsonb_build_object('documentId',filters->>'documentId','moduleId',filters->>'moduleId'))))
    AND (from_time IS NULL OR max(c.audit_observed_at)>=from_time)
    AND (until_time IS NULL OR min(c.audit_observed_at)<until_time)
   ORDER BY max(c.audit_observed_at) DESC,c.invocation_id DESC
 LOOP
  SELECT * INTO STRICT source_row FROM truss.runtime_import_load_chunk c
   WHERE c.invocation_id=candidate.invocation_id AND c.writer_xid<frontier ORDER BY c.chunk_index LIMIT 1;
  -- Each invocation must retain one exact origin/input/owner/actor basis.
  IF EXISTS(SELECT 1 FROM truss.runtime_import_load_chunk c WHERE c.invocation_id=candidate.invocation_id
    AND c.writer_xid<frontier AND (c.load_id IS DISTINCT FROM source_row.load_id
     OR c.original_asserted_origin IS DISTINCT FROM source_row.original_asserted_origin
     OR c.asserted_origin_sha256 IS DISTINCT FROM source_row.asserted_origin_sha256
     OR c.input_sha256 IS DISTINCT FROM source_row.input_sha256 OR c.input_count IS DISTINCT FROM source_row.input_count
     OR c.total_chunks IS DISTINCT FROM source_row.total_chunks OR c.original_owners IS DISTINCT FROM source_row.original_owners
     OR c.owner_inventory_complete IS DISTINCT FROM source_row.owner_inventory_complete
     OR c.native_actor IS DISTINCT FROM source_row.native_actor OR c.native_actor_name IS DISTINCT FROM source_row.native_actor_name)) THEN
   RAISE EXCEPTION 'inconsistent retained import invocation' USING ERRCODE='P1010';END IF;
  IF source_row.owner_inventory_complete IS NOT TRUE THEN
   RAISE EXCEPTION 'complete original import owner inventory required' USING ERRCODE='42501';END IF;
  owners:=source_row.original_owners;
  IF jsonb_array_length(owners)=0 THEN PERFORM truss.runtime_person(true);END IF;
  FOR owner IN SELECT value FROM jsonb_array_elements(owners) LOOP
   IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=owner->>'documentId'
     AND a.module=owner->>'moduleId' AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
    RAISE EXCEPTION 'complete original load audit membership required' USING ERRCODE='42501';END IF;
  END LOOP;
  IF filters ? 'invocationId' AND candidate.invocation_id::text IS DISTINCT FROM filters->>'invocationId' THEN CONTINUE;END IF;
  IF filters ? 'loadId' AND source_row.load_id IS DISTINCT FROM filters->>'loadId' THEN CONTINUE;END IF;
  IF filters ? 'nativeActorOid' AND source_row.native_actor::text IS DISTINCT FROM filters->>'nativeActorOid' THEN CONTINUE;END IF;
  SELECT coalesce(jsonb_agg(c.chunk_index::text ORDER BY c.chunk_index),'[]'::jsonb),count(*),min(c.audit_observed_at),max(c.audit_observed_at)
   INTO observed_chunks,visible_count,observed_from,observed_until
   FROM truss.runtime_import_load_chunk c WHERE c.invocation_id=candidate.invocation_id AND c.writer_xid<frontier;
  expected_chunks:=source_row.total_chunks;
  state_value:=CASE WHEN visible_count=expected_chunks AND
   (SELECT count(DISTINCT c.chunk_index)=expected_chunks FROM truss.runtime_import_load_chunk c
    WHERE c.invocation_id=candidate.invocation_id AND c.writer_xid<frontier) THEN 'complete' ELSE 'partial' END;
  SELECT count(*) FILTER(WHERE e.value->>'outcome'='created'),
   count(*) FILTER(WHERE e.value->>'outcome'='skipped'),
   count(*) FILTER(WHERE e.value->>'outcome'='rejected')
   INTO created_count,skipped_count,rejected_count
   FROM truss.runtime_import_load_chunk c CROSS JOIN LATERAL jsonb_array_elements(c.entries) e(value)
   WHERE c.invocation_id=candidate.invocation_id AND c.writer_xid<frontier;
  SELECT coalesce(jsonb_agg(jsonb_build_object('chunkIndex',c.chunk_index::text,
     'observedAt',to_char(c.audit_observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
     'createdCount',(SELECT count(*) FROM jsonb_array_elements(c.entries) e(value) WHERE e.value->>'outcome'='created')::text,
     'skippedCount',(SELECT count(*) FROM jsonb_array_elements(c.entries) e(value) WHERE e.value->>'outcome'='skipped')::text,
     'rejectedCount',(SELECT count(*) FROM jsonb_array_elements(c.entries) e(value) WHERE e.value->>'outcome'='rejected')::text)
     ORDER BY c.chunk_index),'[]'::jsonb)
   INTO entries FROM truss.runtime_import_load_chunk c
   WHERE c.invocation_id=candidate.invocation_id AND c.writer_xid<frontier;
  IF jsonb_array_length(entries)>maximum_entries THEN RAISE EXCEPTION 'whole import audit invocation exceeds page limit' USING ERRCODE='54000';END IF;
  cursor_bytes:=truss.runtime_import_load_audit_cursor(installation.installation_id,installation.source_epoch,
    expected_release,expected_digest,frontier,filter_sha,candidate.observed_until,candidate.invocation_id);
  -- Freshly recheck the complete owner union before release.
  IF jsonb_array_length(owners)=0 THEN PERFORM truss.runtime_person(true);END IF;
  FOR owner IN SELECT value FROM jsonb_array_elements(owners) LOOP
   IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=owner->>'documentId'
     AND a.module=owner->>'moduleId' AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
    RAISE EXCEPTION 'load audit authority changed before listing release' USING ERRCODE='42501';END IF;
  END LOOP;
  PERFORM truss.runtime_person(false);
  RETURN convert_to(jsonb_build_object('outcome','summary','invocationId',candidate.invocation_id::text,
   'loadId',source_row.load_id,'assertedOriginSha256',source_row.asserted_origin_sha256,
   'nativeActorOid',source_row.native_actor::text,'nativeActorName',source_row.native_actor_name,
   'inputSha256',source_row.input_sha256,'inputCount',source_row.input_count::text,
   'totalChunks',expected_chunks::text,'observedChunkCount',visible_count::text,'observedChunks',observed_chunks,
   'state',state_value,'observedAtFrom',to_char(observed_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'observedAtUntil',to_char(observed_until AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'createdCount',created_count::text,'skippedCount',skipped_count::text,'rejectedCount',rejected_count::text,
   'chunks',entries,'nextPageCursor',convert_from(cursor_bytes,'UTF8')::jsonb)::text,'UTF8');
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a
   WHERE a.document_id=filters->>'documentId' AND a.module=filters->>'moduleId'
    AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
  RAISE EXCEPTION 'load audit module authority changed before empty-page release' USING ERRCODE='42501';END IF;
 PERFORM truss.runtime_person(false);
 RETURN convert_to('{"outcome":"end","nextPageCursor":null}'::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.page_objects(selected_document text, selected_module text, selected_record text, page_limit integer, maximum_bytes integer, original_cursor bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;selected_type truss.type_def%ROWTYPE;
 captured_revision int;source_pin record;cursor_value jsonb;after_id bigint:=0;candidate record;
 objects jsonb:='[]';lookahead_root_owner jsonb;object_bytes bytea;object_value jsonb;continuation jsonb;result bytea;counted int:=0;last_id bigint;
BEGIN
 PERFORM truss.runtime_person(false);
 IF selected_document IS NULL OR selected_module IS NULL OR selected_record IS NULL
  OR octet_length(selected_document) NOT BETWEEN 1 AND 4096 OR octet_length(selected_module) NOT BETWEEN 1 AND 4096
  OR octet_length(selected_record) NOT BETWEEN 1 AND 4096 OR page_limit IS NULL OR page_limit NOT BETWEEN 1 AND 1000
  OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN
  RAISE EXCEPTION 'bounded page selection and limits required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected object page runtime required' USING ERRCODE='0A000';END IF;
 IF current_setting('transaction_read_only')='on' THEN SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 ELSE SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;END IF;
 IF captured_revision<1 THEN RAISE EXCEPTION 'accepted page catalog required' USING ERRCODE='0A000';END IF;
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 SELECT * INTO selected_type FROM truss.type_def WHERE document_id=selected_document AND module=selected_module
  AND element=selected_record AND kind='record' AND NOT provisional AND retired_rev IS NULL AND since_rev<=captured_revision;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RETURN NULL;END IF;
 SELECT * INTO STRICT source_pin FROM truss.runtime_owned_definition_metadata('type',selected_type.type_id);
 IF original_cursor IS NOT NULL THEN
  IF octet_length(original_cursor) NOT BETWEEN 1 AND 65536 OR (convert_from(original_cursor,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
   RAISE EXCEPTION 'bounded original page cursor required' USING ERRCODE='22023';END IF;
  cursor_value:=convert_from(original_cursor,'UTF8')::jsonb;
  IF (SELECT count(*) FROM jsonb_object_keys(cursor_value))<>11 OR EXISTS(SELECT 1 FROM jsonb_each(cursor_value) e WHERE jsonb_typeof(e.value)<>'string')
   OR cursor_value-ARRAY['profile','installationId','sourceEpoch','releaseSha256','documentId','moduleId','recordId','typeId','definitionPin','catalogRevision','afterId']<>'{}'::jsonb
   OR cursor_value->>'documentId' IS DISTINCT FROM selected_document OR cursor_value->>'moduleId' IS DISTINCT FROM selected_module OR cursor_value->>'recordId' IS DISTINCT FROM selected_record
   OR jsonb_typeof(cursor_value->'afterId') IS DISTINCT FROM 'string' OR cursor_value->>'afterId' !~ '^[1-9][0-9]{0,18}$'
   OR (length(cursor_value->>'afterId')=19 AND (cursor_value->>'afterId') COLLATE "C">'9223372036854775807' COLLATE "C") THEN
   RAISE EXCEPTION 'exact page cursor selection required' USING ERRCODE='22023';END IF;
  IF cursor_value->>'profile' IS DISTINCT FROM 'truss-python-object-page/0.1'
   OR cursor_value->>'installationId' IS DISTINCT FROM installation.installation_id::text
   OR cursor_value->>'sourceEpoch' IS DISTINCT FROM installation.source_epoch::text
   OR cursor_value->>'releaseSha256' IS DISTINCT FROM installation.release_sha256
   OR cursor_value->>'typeId' IS DISTINCT FROM selected_type.type_id::text OR cursor_value->>'definitionPin' IS DISTINCT FROM source_pin.definition_pin
   OR cursor_value->>'catalogRevision' IS DISTINCT FROM captured_revision::text THEN
   RAISE EXCEPTION 'current page cursor context required' USING ERRCODE='P1002';END IF;
  after_id:=(cursor_value->>'afterId')::bigint;
 END IF;
 FOR candidate IN SELECT id FROM truss.object WHERE type_id=selected_type.type_id AND id>after_id ORDER BY id LIMIT page_limit+1 LOOP
  counted:=counted+1;
  IF counted>page_limit THEN
   object_bytes:=truss.get_object(selected_document,selected_module,selected_record,candidate.id,16777216,expected_release,expected_digest);
   IF object_bytes IS NULL THEN RAISE EXCEPTION 'page lookahead no longer admitted' USING ERRCODE='55P03';END IF;
   object_value:=convert_from(object_bytes,'UTF8')::jsonb;
   IF object_value->>'catalogRevision' IS DISTINCT FROM captured_revision::text THEN RAISE EXCEPTION 'catalog changed during page lookahead' USING ERRCODE='55P03';END IF;
   IF object_value->>'profile'='truss-python-logical-object/0.1' THEN lookahead_root_owner:=object_value->'root'->'owner';END IF;
   continuation:=jsonb_build_object('profile','truss-python-object-page/0.1','installationId',installation.installation_id::text,
    'sourceEpoch',installation.source_epoch::text,'releaseSha256',installation.release_sha256,'documentId',selected_document,
    'moduleId',selected_module,'recordId',selected_record,'typeId',selected_type.type_id::text,'definitionPin',source_pin.definition_pin,
    'catalogRevision',captured_revision::text,'afterId',last_id::text);
   IF octet_length(continuation::text)>65536 THEN RAISE EXCEPTION 'page cursor byte limit exceeded' USING ERRCODE='54000';END IF;
   EXIT;
  END IF;
  object_bytes:=truss.get_object(selected_document,selected_module,selected_record,candidate.id,maximum_bytes,expected_release,expected_digest);
  IF object_bytes IS NULL THEN RAISE EXCEPTION 'page observation no longer admitted' USING ERRCODE='55P03';END IF;
  object_value:=convert_from(object_bytes,'UTF8')::jsonb;
  IF object_value->>'catalogRevision' IS DISTINCT FROM captured_revision::text THEN RAISE EXCEPTION 'catalog changed during page observation' USING ERRCODE='55P03';END IF;
  objects:=objects||jsonb_build_array(object_value);last_id:=candidate.id;
  IF octet_length(objects::text)>maximum_bytes THEN RAISE EXCEPTION 'complete page byte limit exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 PERFORM truss.runtime_person(false);
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RAISE EXCEPTION 'current page reader required' USING ERRCODE='42501';END IF;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN RAISE EXCEPTION 'catalog changed during page observation' USING ERRCODE='55P03';END IF;
 result:=convert_to(jsonb_build_object('profile','truss-python-object-page/0.1','catalogRevision',captured_revision,'objects',objects,'continuation',continuation)::text,'UTF8');
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'complete page byte limit exceeded' USING ERRCODE='54000';END IF;
 IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RAISE EXCEPTION 'current buffered page interpretation reader required' USING ERRCODE='42501';END IF;
 FOR object_value IN SELECT value FROM jsonb_array_elements(objects) LOOP
  IF object_value->>'profile'='truss-python-logical-object/0.1' AND NOT truss.runtime_can_read(
   object_value->'root'->'owner'->>'documentId',object_value->'root'->'owner'->>'moduleId') THEN
   RAISE EXCEPTION 'current buffered aggregate root reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF lookahead_root_owner IS NOT NULL AND NOT truss.runtime_can_read(lookahead_root_owner->>'documentId',lookahead_root_owner->>'moduleId') THEN
  RAISE EXCEPTION 'current lookahead aggregate root reader required' USING ERRCODE='42501';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.person_runtime_status(expected_release text, expected_digest text, expected_layout jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE actor oid;installation truss.catalog_runtime_installation%ROWTYPE;revision int;catalog_state text;
 selected_document text;selected_module text;
BEGIN
 actor:=truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.catalog_runtime_installation WHERE singleton;
 IF installation.release_id IS DISTINCT FROM expected_release
  OR installation.release_sha256 IS DISTINCT FROM expected_digest
  OR installation.layout_profile IS DISTINCT FROM expected_layout THEN
  RETURN convert_to('{"outcome":"status","installation":"incompatible","catalog":"unknown"}','UTF8');
 END IF;
 SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 IF revision=0 THEN catalog_state:='empty';
 ELSE
  SELECT m.document_id,m.module INTO selected_document,selected_module FROM truss.module_access m
   WHERE truss.runtime_can_read(m.document_id,m.module)
    OR truss.runtime_audit_role_member(actor,pg_catalog.to_regrole(m.writer_role))
    OR EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=m.document_id
     AND a.module=m.module AND truss.runtime_audit_role_member(actor,a.auditor_oid))
   ORDER BY m.document_id,m.module LIMIT 1;
  IF selected_document IS NULL OR selected_module IS NULL THEN
   RAISE EXCEPTION 'current enrolled module reader required' USING ERRCODE='42501';END IF;
  IF NOT (truss.runtime_can_read(selected_document,selected_module)
   OR EXISTS(SELECT 1 FROM truss.module_access m WHERE m.document_id=selected_document AND m.module=selected_module
    AND truss.runtime_audit_role_member(actor,pg_catalog.to_regrole(m.writer_role)))
   OR EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=selected_document
    AND a.module=selected_module AND truss.runtime_audit_role_member(actor,a.auditor_oid))) THEN
   RAISE EXCEPTION 'current enrolled module reader required' USING ERRCODE='42501';END IF;
  catalog_state:='accepted';
 END IF;
 IF truss.runtime_person(false) IS DISTINCT FROM actor THEN
  RAISE EXCEPTION 'current status person required' USING ERRCODE='42501';END IF;
 RETURN convert_to(jsonb_build_object('outcome','status','installation','compatible',
  'catalog',catalog_state)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.prepare_group(original_records bytea, original_relationships bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE context jsonb;records jsonb;relationships jsonb;entry jsonb;reference bytea;types jsonb:='[]';rels jsonb:='[]';revision int;
BEGIN
 IF original_records IS NULL OR octet_length(original_records) NOT BETWEEN 2 AND 65536
  OR original_relationships IS NULL OR octet_length(original_relationships) NOT BETWEEN 2 AND 65536 THEN
  RAISE EXCEPTION 'bounded group preparation required' USING ERRCODE='54000';END IF;
 IF (convert_from(original_records,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE
  OR (convert_from(original_relationships,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN
  RAISE EXCEPTION 'unique original JSON members required' USING ERRCODE='22023';END IF;
 records:=convert_from(original_records,'UTF8')::jsonb;relationships:=convert_from(original_relationships,'UTF8')::jsonb;
 IF jsonb_array_length(records) NOT BETWEEN 0 AND 128 OR jsonb_array_length(relationships) NOT BETWEEN 0 AND 128 THEN
  RAISE EXCEPTION 'bounded named record set required' USING ERRCODE='54000';END IF;
 context:=convert_from(truss.group_context(expected_release,expected_digest),'UTF8')::jsonb;
 SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 FOR entry IN SELECT value FROM jsonb_array_elements(records) LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry-ARRAY['documentId','moduleId','recordId']<>'{}'::jsonb
   OR jsonb_typeof(entry->'documentId') IS DISTINCT FROM 'string' OR jsonb_typeof(entry->'moduleId') IS DISTINCT FROM 'string'
   OR jsonb_typeof(entry->'recordId') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'qualified record name required' USING ERRCODE='22023';END IF;
  reference:=truss.group_type_reference(entry->>'documentId',entry->>'moduleId',entry->>'recordId',expected_release,expected_digest);
  types:=types||jsonb_build_array(CASE WHEN reference IS NULL THEN 'null'::jsonb ELSE convert_from(reference,'UTF8')::jsonb END);
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(relationships) LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry-ARRAY['documentId','moduleId','relationshipId']<>'{}'::jsonb
   OR jsonb_typeof(entry->'documentId') IS DISTINCT FROM 'string' OR jsonb_typeof(entry->'moduleId') IS DISTINCT FROM 'string'
   OR jsonb_typeof(entry->'relationshipId') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'qualified relationship name required' USING ERRCODE='22023';END IF;
  reference:=truss.group_relationship_reference(entry->>'documentId',entry->>'moduleId',entry->>'relationshipId',expected_release,expected_digest);
  rels:=rels||jsonb_build_array(CASE WHEN reference IS NULL THEN 'null'::jsonb ELSE convert_from(reference,'UTF8')::jsonb END);
 END LOOP;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM revision THEN
  RAISE EXCEPTION 'catalog changed during group preparation' USING ERRCODE='55P03';END IF;
 RETURN convert_to(jsonb_build_object('catalogRevision',revision::text,'context',context,'types',types,'relationships',rels)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.preview_group_conditions(original_input bytea, original_documents bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE input jsonb;documents jsonb;truth jsonb;actor oid;current_revision int;
 current_installation truss.catalog_runtime_installation%ROWTYPE;
BEGIN
 actor:=truss.runtime_person(false);
 IF original_input IS NULL OR octet_length(original_input)<1
  OR original_documents IS NULL OR octet_length(original_documents)<1 THEN
  RAISE EXCEPTION 'bounded original condition preview required' USING ERRCODE='22023';END IF;
 IF octet_length(original_input)>1048576 OR octet_length(original_documents)>4194304 THEN
  RAISE EXCEPTION 'condition preview source exceeds limits' USING ERRCODE='54000';END IF;
 IF (convert_from(original_input,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
  OR (convert_from(original_documents,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN
  RAISE EXCEPTION 'unique original condition preview JSON required' USING ERRCODE='22023';END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;documents:=convert_from(original_documents,'UTF8')::jsonb;
 IF jsonb_typeof(documents) IS DISTINCT FROM 'array' OR jsonb_array_length(documents)<1 THEN
  RAISE EXCEPTION 'original condition documents required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(documents)>512 THEN
  RAISE EXCEPTION 'original condition documents exceed limits' USING ERRCODE='54000';END IF;
 IF EXISTS(
  SELECT 1 FROM jsonb_array_elements(documents) d
   WHERE jsonb_typeof(d.value) IS DISTINCT FROM 'object'
    OR d.value-ARRAY['documentId','sourceText']<>'{}'::jsonb
    OR jsonb_typeof(d.value->'documentId') IS DISTINCT FROM 'string'
    OR octet_length(d.value->>'documentId') NOT BETWEEN 1 AND 4096
    OR jsonb_typeof(d.value->'sourceText') IS DISTINCT FROM 'string')
  OR jsonb_array_length(documents)<>(SELECT count(DISTINCT d.value->>'documentId') FROM jsonb_array_elements(documents) d) THEN
  RAISE EXCEPTION 'complete unique original preview documents required' USING ERRCODE='22023';END IF;
 -- The helper is one STABLE SQL statement: every metadata/source/data read and
 -- the reported snapshot token therefore share exactly one MVCC basis.
 SELECT truss.runtime_preview_truth_snapshot(input,documents,expected_release,expected_digest) INTO STRICT truth;
 PERFORM truss.runtime_preview_recheck_authority(truth->'inventory',actor);
 SELECT * INTO STRICT current_installation FROM truss.catalog_runtime_installation WHERE singleton;
 SELECT rev INTO STRICT current_revision FROM truss.schema_head WHERE id=1;
 IF current_installation.release_id IS DISTINCT FROM truth->>'releaseId'
  OR current_installation.release_sha256 IS DISTINCT FROM truth->>'releaseSha256'
  OR current_installation.source_epoch::text IS DISTINCT FROM truth->>'sourceEpoch'
  OR current_revision::text IS DISTINCT FROM truth->>'catalogRevision' THEN
  RAISE EXCEPTION 'observed preview basis changed before release' USING ERRCODE='55P03';END IF;
 IF truss.runtime_person(false) IS DISTINCT FROM actor THEN RAISE EXCEPTION 'current preview person required' USING ERRCODE='42501';END IF;
 RETURN convert_to(jsonb_build_object('outcome','observed','conditions',truth->'conditions',
  'basis',jsonb_build_object('catalogRevision',truth->'catalogRevision','snapshot',truth->'snapshot',
   'sourceEpoch',truth->'sourceEpoch','releaseId',truth->'releaseId','releaseSha256',truth->'releaseSha256',
   'layoutProfile',truth->'layoutProfile'))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.process_import_chunk(original_input bytea, original_documents bytea, invocation_id uuid, chunk_index integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE input jsonb;documents jsonb;context jsonb;group_context jsonb;source_map jsonb;selected record;record jsonb;metadata jsonb;
 payload_bytes bytea;payload jsonb;operation jsonb;group_input jsonb;applied jsonb;created jsonb;state text;code text;
 outcomes jsonb[]:='{}';original_records jsonb[]:='{}';counted int;chunk_size int;total_chunks int;budget_rows int;input_digest text;
 origin jsonb;selected_outcome jsonb;result jsonb;source_at text;
 batch_operations jsonb:='[]';batch_sources jsonb:='[]';batch_records jsonb[]:='{}';batch_outcomes jsonb[]:='{}';batch_done boolean:=false;batch_index int:=0;
BEGIN
 context:=convert_from(truss.batched_import_context(expected_release,expected_digest),'UTF8')::jsonb;
 IF original_input IS NULL OR octet_length(original_input)>8388608 OR original_documents IS NULL OR octet_length(original_documents)>4194304 THEN RAISE EXCEPTION 'bounded original import required' USING ERRCODE='54000';END IF;
 IF (convert_from(original_input,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE OR (convert_from(original_documents,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'unique original import required' USING ERRCODE='22023';END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;documents:=convert_from(original_documents,'UTF8')::jsonb;
 IF input-ARRAY['interfaceVersion','layoutProfile','importProfile','valueProfile','catalog','loadId','assertedOrigin','records','chunkSize']<>'{}'::jsonb
  OR input->>'interfaceVersion' IS DISTINCT FROM 'truss-batched-import-input/0.1.0'
  OR input->'layoutProfile' IS DISTINCT FROM context->'layoutProfile' OR input->'importProfile' IS DISTINCT FROM context->'importProfile'
  OR input->'valueProfile' IS DISTINCT FROM context->'valueProfile' OR input->'catalog' IS DISTINCT FROM context->'catalog'
  OR jsonb_typeof(input->'records') IS DISTINCT FROM 'array' OR jsonb_array_length(input->'records')>1024
  OR jsonb_typeof(input->'chunkSize') IS DISTINCT FROM 'string' OR input->>'chunkSize' !~ '^[1-9][0-9]{0,2}$'
  OR (input->>'chunkSize')::int>128 OR jsonb_typeof(input->'loadId') IS DISTINCT FROM 'string' OR octet_length(input->>'loadId') NOT BETWEEN 1 AND 4096
  OR jsonb_typeof(input->'assertedOrigin') IS DISTINCT FROM 'object' OR input->'assertedOrigin'->>'kind' IS DISTINCT FROM 'map'
  OR jsonb_typeof(input->'assertedOrigin'->'entries') IS DISTINCT FROM 'array'
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e WHERE e.value->>'key'='x-load-id' OR e.value->'value'->>'kind' NOT IN ('null','string'))
  OR (SELECT count(*)<>count(DISTINCT e.value->>'key') FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e)
  THEN RAISE EXCEPTION 'selected original chunk profile required' USING ERRCODE='22023';END IF;
 IF (input->'assertedOrigin')-ARRAY['kind','entries']<>'{}'::jsonb
  OR jsonb_array_length(input->'assertedOrigin'->'entries')>1024
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e WHERE
   jsonb_typeof(e.value) IS DISTINCT FROM 'object' OR e.value-ARRAY['key','value']<>'{}'::jsonb
   OR jsonb_typeof(e.value->'key') IS DISTINCT FROM 'string' OR jsonb_typeof(e.value->'value') IS DISTINCT FROM 'object'
   OR (e.value->'value')-ARRAY['kind','text']<>'{}'::jsonb
   OR (e.value->'value'->>'kind' IN ('null','string')) IS NOT TRUE
   OR e.value->'value'->>'kind'='null' AND e.value->'value' ? 'text'
   OR e.value->'value'->>'kind'='string' AND jsonb_typeof(e.value->'value'->'text') IS DISTINCT FROM 'string') THEN
  RAISE EXCEPTION 'closed original asserted origin required' USING ERRCODE='22023';END IF;
 origin:=jsonb_set(input->'assertedOrigin','{entries}',(input->'assertedOrigin'->'entries')||jsonb_build_array(jsonb_build_object('key','x-load-id','value',jsonb_build_object('kind','string','text',input->>'loadId'))));
 IF octet_length((input->'assertedOrigin')::text)>1048576 OR octet_length(origin::text)>1048576 THEN
  RAISE EXCEPTION 'bounded original asserted origin required' USING ERRCODE='54000';END IF;
 chunk_size:=(input->>'chunkSize')::int;counted:=jsonb_array_length(input->'records');total_chunks:=greatest(1,(counted+chunk_size-1)/chunk_size);
 IF invocation_id IS NULL OR chunk_index IS NULL OR chunk_index<0 OR chunk_index>=total_chunks THEN RAISE EXCEPTION 'derived original chunk required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(documents)>512 OR EXISTS(SELECT 1 FROM jsonb_array_elements(documents) d WHERE d.value-ARRAY['documentId','sourceText']<>'{}'::jsonb OR jsonb_typeof(d.value->'sourceText') IS DISTINCT FROM 'string')
  OR (SELECT count(*)<>count(DISTINCT d.value->>'documentId') FROM jsonb_array_elements(documents) d) THEN RAISE EXCEPTION 'complete unique original documents required' USING ERRCODE='22023';END IF;
 SELECT coalesce(jsonb_object_agg(d.value->>'documentId',d.value->>'sourceText'),'{}') INTO source_map FROM jsonb_array_elements(documents) d;
 -- Byte/hash admission precedes identity routing, including skipped records.
 -- Payload interpretation remains after the native live/reserved-identity skip.
 FOR record IN SELECT value FROM jsonb_array_elements(input->'records') LOOP
  IF jsonb_typeof(record) IS DISTINCT FROM 'object' OR record-ARRAY['kind','identity','payload','payloadProfile']<>'{}'::jsonb
   OR (record->>'kind' IN ('object','edge')) IS NOT TRUE OR record->'payloadProfile' IS DISTINCT FROM context->'importPayloadProfile'
   OR jsonb_typeof(record->'payload') IS DISTINCT FROM 'object' OR (record->'payload')-ARRAY['identity','bytesBase64','sha256']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed original import record required' USING ERRCODE='22023';END IF;
  payload_bytes:=decode(record->'payload'->>'bytesBase64','base64');
  IF record->'payload'->>'identity' IS DISTINCT FROM record->'payload'->>'sha256' OR payload_bytes IS NULL OR octet_length(payload_bytes) NOT BETWEEN 1 AND 1048576 OR encode(sha256(payload_bytes),'hex') IS DISTINCT FROM record->'payload'->>'sha256' THEN RAISE EXCEPTION 'original payload byte integrity required' USING ERRCODE='22023';END IF;
 END LOOP;
 -- Only finished transactions below every active snapshot are eligible; cleanup
 -- is bounded independently of this call's admitted work.
 DELETE FROM truss.runtime_import_budget WHERE writer_xid IN
  (SELECT writer_xid FROM truss.runtime_import_budget WHERE writer_xid<pg_snapshot_xmin(pg_current_snapshot()) ORDER BY writer_xid LIMIT 128);
 INSERT INTO truss.runtime_import_budget VALUES(pg_current_xact_id(),least(chunk_size,greatest(0,counted-chunk_index*chunk_size)),octet_length(original_input)+octet_length(original_documents))
 ON CONFLICT(writer_xid) DO UPDATE SET records=truss.runtime_import_budget.records+EXCLUDED.records,submitted_bytes=truss.runtime_import_budget.submitted_bytes+EXCLUDED.submitted_bytes
 WHERE truss.runtime_import_budget.records+EXCLUDED.records<=4096 AND truss.runtime_import_budget.submitted_bytes+EXCLUDED.submitted_bytes<=268435456;
 GET DIAGNOSTICS budget_rows=ROW_COUNT;IF budget_rows<>1 THEN RAISE EXCEPTION 'cumulative import work budget exceeded' USING ERRCODE='54000';END IF;
 group_context:=convert_from(truss.group_context(expected_release,expected_digest),'UTF8')::jsonb;
 -- Independent new rootless objects can share the existing set-based group
 -- writer. A contained eligibility/constraint failure falls through to the
 -- original per-record semantics; stale admission, resource, cancellation and
 -- transaction-retry failures are never retried here.
 IF least(chunk_size,greatest(0,counted-chunk_index*chunk_size))>1 THEN
  BEGIN
   FOR selected IN SELECT value AS record,(ordinality-1)::int AS input_index FROM jsonb_array_elements(input->'records') WITH ORDINALITY
    ORDER BY (value->>'kind'='edge'),ordinality OFFSET chunk_index*chunk_size LIMIT chunk_size LOOP
    record:=selected.record;
    IF record->>'kind' IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'independent object run required' USING ERRCODE='TRB01';END IF;
    metadata:=convert_from(truss.import_object_identity(convert_to((record->'identity')::text,'UTF8'),convert_to(source_map->>(record->'identity'->'type'->'owner'->>'documentId'),'UTF8'),NULL,expected_release,expected_digest),'UTF8')::jsonb;
    IF metadata->>'state'='skipped' THEN RAISE EXCEPTION 'per-record skip precedence required' USING ERRCODE='TRB01';END IF;
    operation:=truss.runtime_import_operation(record,metadata);
    batch_operations:=batch_operations||jsonb_build_array(operation);
    batch_records:=array_append(batch_records,jsonb_build_object('inputIndex',selected.input_index::text,'record',record));
    batch_sources:=batch_sources||jsonb_build_array(jsonb_build_object('operationIndex',batch_index,
     'originalRecordBase64',replace(encode(convert_to(record::text,'UTF8'),'base64'),E'\n','')));
    batch_index:=batch_index+1;
   END LOOP;
   group_input:=jsonb_build_object('interfaceVersion','truss-group-input/0.1.0','layoutProfile',group_context->'layoutProfile','mutationProfile',group_context->'mutationProfile','valueProfile',group_context->'valueProfile','catalog',jsonb_build_object('selection','current'),'preconditions','[]'::jsonb,'operations',batch_operations,'assertedOrigin',origin);
   IF octet_length(group_input::text)>4194304 THEN RAISE EXCEPTION 'per-record envelope required' USING ERRCODE='TRB01';END IF;
   applied:=convert_from(truss.apply_group(convert_to(group_input::text,'UTF8'),original_documents,convert_to('{"state":"none"}','UTF8'),expected_release,expected_digest),'UTF8')::jsonb;
   IF applied->>'outcome'<>'success' THEN
    state:=CASE WHEN applied->>'outcome'='failed' THEN coalesce(applied->>'nativeState','22023') WHEN applied->>'reason'='resource' THEN '54000' WHEN applied->>'reason'='observation' THEN '55P03' ELSE '0A000' END;
    RAISE EXCEPTION 'independent import group refused' USING ERRCODE=state;
   END IF;
   PERFORM truss.runtime_owned_import_record_sources((applied->>'attemptId')::uuid,batch_sources,input->>'loadId');
   FOR batch_index IN 0..array_length(batch_records,1)-1 LOOP
    created:=applied->'semantic'->'results'->batch_index;
    batch_outcomes:=array_append(batch_outcomes,jsonb_build_object('inputIndex',batch_records[batch_index+1]->>'inputIndex',
     'outcome','created','identity',created->'identity','version',created->>'version','groupAttemptId',applied->>'attemptId'));
   END LOOP;
   original_records:=batch_records;outcomes:=batch_outcomes;batch_done:=true;
  EXCEPTION WHEN SQLSTATE 'TRB01' OR SQLSTATE '22023' OR SQLSTATE '23505' OR SQLSTATE '42501' OR SQLSTATE '0A000' OR SQLSTATE 'P1004' OR SQLSTATE 'P1005' THEN
   -- This entire block's database effects have rolled back. Nothing from the
   -- rejected group may enter the original-record/outcome/provenance report.
   batch_done:=false;
  END;
 END IF;
 IF NOT batch_done THEN
 FOR selected IN SELECT value AS record,(ordinality-1)::int AS input_index FROM jsonb_array_elements(input->'records') WITH ORDINALITY
  ORDER BY (value->>'kind'='edge'),ordinality OFFSET chunk_index*chunk_size LIMIT chunk_size LOOP
  record:=selected.record;original_records:=array_append(original_records,jsonb_build_object('inputIndex',selected.input_index::text,'record',record));
  code:=NULL;
  BEGIN
   IF record->'payloadProfile' IS DISTINCT FROM context->'importPayloadProfile' THEN RAISE EXCEPTION 'selected payload profile required' USING ERRCODE='0A000';END IF;
   IF record->>'kind'='object' THEN
    metadata:=convert_from(truss.import_object_identity(convert_to((record->'identity')::text,'UTF8'),convert_to(source_map->>(record->'identity'->'type'->'owner'->>'documentId'),'UTF8'),NULL,expected_release,expected_digest),'UTF8')::jsonb;
   ELSIF record->>'kind'='edge' THEN metadata:=convert_from(truss.import_edge_identity(convert_to((record->'identity')::text,'UTF8'),expected_release,expected_digest),'UTF8')::jsonb;
   ELSE RAISE EXCEPTION 'object or edge import required' USING ERRCODE='22023';END IF;
   IF metadata->>'state'='skipped' THEN
    selected_outcome:=jsonb_build_object('inputIndex',selected.input_index::text,'outcome','skipped','reason',metadata->>'reason');
    IF metadata ? 'identity' THEN selected_outcome:=selected_outcome||jsonb_build_object('identity',metadata->'identity');END IF;
   ELSE
    code:='invalid_payload';
    operation:=truss.runtime_import_operation(record,metadata);
    group_input:=jsonb_build_object('interfaceVersion','truss-group-input/0.1.0','layoutProfile',group_context->'layoutProfile','mutationProfile',group_context->'mutationProfile','valueProfile',group_context->'valueProfile','catalog',jsonb_build_object('selection','current'),'preconditions','[]'::jsonb,'operations',jsonb_build_array(operation),'assertedOrigin',origin);
    code:=NULL;
    applied:=convert_from(truss.apply_group(convert_to(group_input::text,'UTF8'),original_documents,convert_to('{"state":"none"}','UTF8'),expected_release,expected_digest),'UTF8')::jsonb;
    IF applied->>'outcome'<>'success' THEN
     state:=CASE WHEN applied->>'outcome'='failed' THEN applied->>'nativeState' WHEN applied->>'reason'='resource' THEN '54000' WHEN applied->>'reason'='observation' THEN '55P03' ELSE '0A000' END;
     IF state IS NULL THEN state:='22023';END IF;RAISE EXCEPTION 'import record refused' USING ERRCODE=state;
    END IF;
    created:=applied->'semantic'->'results'->0;
    PERFORM truss.import_record_source((applied->>'attemptId')::uuid,convert_to(record::text,'UTF8'),input->>'loadId');
    selected_outcome:=jsonb_build_object('inputIndex',selected.input_index::text,'outcome','created','identity',created->'identity','version',created->>'version','groupAttemptId',applied->>'attemptId');
   END IF;
  EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '23505' OR SQLSTATE '42501' OR SQLSTATE '0A000' OR SQLSTATE 'P1004' OR SQLSTATE 'P1005' THEN
   GET STACKED DIAGNOSTICS state=RETURNED_SQLSTATE;
   code:=coalesce(code,CASE state WHEN '22023' THEN 'invalid' WHEN '23505' THEN 'conflict' WHEN '42501' THEN 'unauthorized' WHEN '0A000' THEN 'unsupported_profile' WHEN 'P1004' THEN 'missing_endpoint' ELSE 'dependencies' END);
   selected_outcome:=jsonb_build_object('inputIndex',selected.input_index::text,'outcome','rejected','code',code);
  END;
  outcomes:=array_append(outcomes,selected_outcome);
 END LOOP;
 END IF;
 FOR selected IN SELECT r.value AS original,o.value AS result FROM unnest(original_records) r(value) JOIN unnest(outcomes) o(value) ON r.value->>'inputIndex'=o.value->>'inputIndex' LOOP
  IF selected.result->>'outcome' IN ('created','skipped') THEN PERFORM truss.import_report_record_authority(convert_to(jsonb_build_object('originalIdentity',selected.original->'record'->'identity','outcomeIdentity',selected.result->'identity')::text,'UTF8'),selected.original->'record'->>'kind',expected_release,expected_digest);END IF;
 END LOOP;
 IF convert_from(truss.batched_import_context(expected_release,expected_digest),'UTF8')::jsonb IS DISTINCT FROM context THEN RAISE EXCEPTION 'original import context changed' USING ERRCODE='42501';END IF;
 input_digest:=encode(sha256(convert_to('truss-batched-import-input/0.1.0'||chr(10),'UTF8')||original_input),'hex');
 PERFORM truss.runtime_record_import_load(invocation_id,chunk_index,total_chunks,input->>'loadId',input->'assertedOrigin',input_digest,counted,input->'records',to_jsonb(original_records),to_jsonb(outcomes),expected_release,expected_digest);
 result:=jsonb_build_object('context',context,'outcomes',to_jsonb(outcomes),'hostTransactionId','truss-pending-transaction:'||(context->>'sourceEpoch')||':'||pg_current_xact_id()::text);
 IF octet_length(result::text)>8388608 THEN RAISE EXCEPTION 'bounded complete import report required' USING ERRCODE='54000';END IF;
 RETURN convert_to(result::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_binding(selected_documents jsonb, maximum_scan_rows integer, maximum_result_rows integer, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;captured_revision int;selected_document_id text;archived jsonb;content text;source jsonb;modules jsonb:='[]';pins jsonb:='[]';records jsonb:='[]';relationships jsonb:='[]';binding jsonb;result bytea;
BEGIN
 PERFORM truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'selected query release required' USING ERRCODE='0A000';END IF;
 IF maximum_scan_rows IS NULL OR maximum_scan_rows NOT BETWEEN 1 AND 10000 OR maximum_result_rows IS NULL OR maximum_result_rows NOT BETWEEN 1 AND 10000 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216
 OR jsonb_typeof(selected_documents) IS DISTINCT FROM 'array' OR jsonb_array_length(selected_documents) NOT BETWEEN 1 AND 32
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(selected_documents) v WHERE jsonb_typeof(v.value)<>'string')
 OR (SELECT count(DISTINCT v.value) FROM jsonb_array_elements(selected_documents) v)<>jsonb_array_length(selected_documents) THEN RAISE EXCEPTION 'bounded original document selection required' USING ERRCODE='22023';END IF;
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 FOR selected_document_id IN SELECT value FROM jsonb_array_elements_text(selected_documents) LOOP
  archived:=convert_from(truss.accepted_document(selected_document_id,maximum_bytes,expected_release,expected_digest),'UTF8')::jsonb;
  content:=convert_from(decode(archived->>'contentBase64','base64'),'UTF8');source:=content::jsonb;
  pins:=pins||jsonb_build_array(jsonb_build_object('documentId',selected_document_id,'revision',archived->>'documentRevision','sha256',archived->>'sha256'));
  modules:=modules||jsonb_build_array(jsonb_build_object('documentJson',content,'pin',jsonb_build_object('documentId',selected_document_id,'revision',archived->>'documentRevision','sha256',archived->>'sha256','umfVersion',source->>'umf'),
   'selectedModuleIds',(SELECT jsonb_agg(m.value->>'id' ORDER BY m.value->>'id') FROM jsonb_array_elements(source->'modules') m)));
  records:=records||coalesce((SELECT jsonb_agg(jsonb_build_object('identity',jsonb_build_object('documentId',t.document_id,'revision',archived->>'documentRevision','module',t.module,'element',t.element),'typeId',t.type_id::text,
    'keys',(SELECT coalesce(jsonb_agg(jsonb_build_object('keyId',k.key_id,'propertyIds',(SELECT jsonb_agg(p.prop_id::text ORDER BY p.n) FROM unnest(k.prop_ids) WITH ORDINALITY p(prop_id,n))) ORDER BY k.key_num),'[]') FROM truss.key_def k WHERE k.type_id=t.type_id AND k.retired_rev IS NULL),
    'fields',(SELECT coalesce(jsonb_agg(jsonb_build_object('identity',jsonb_build_object('documentId',t.document_id,'revision',archived->>'documentRevision','module',p.declaration_module,'element',p.element),'propertyId',p.prop_id::text) ORDER BY p.prop_id),'[]') FROM truss.prop_def p WHERE p.type_id=t.type_id AND p.retired_rev IS NULL)) ORDER BY t.type_id)
    FROM truss.type_def t WHERE t.document_id=selected_document_id AND t.retired_rev IS NULL AND NOT t.provisional AND t.kind='record'),'[]');
  relationships:=relationships||coalesce((SELECT jsonb_agg(jsonb_build_object('identity',jsonb_build_object('documentId',r.document_id,'revision',archived->>'documentRevision','module',r.module,'relationship',r.rel_id),
   'relationshipTypeId',r.rel_type_id::text,'sourceTypeId',e.source_type::text,'targetTypeId',e.target_type::text) ORDER BY r.rel_type_id)
   FROM truss.rel_def r JOIN truss.rel_endpoint e ON e.rel_type_id=r.rel_type_id WHERE r.document_id=selected_document_id AND r.retired_rev IS NULL AND r.lifecycle IN ('independent','owned') AND r.directed AND NOT r.composition AND r.assoc_type_id IS NULL
   AND (SELECT count(*) FROM truss.rel_endpoint ep WHERE ep.rel_type_id=r.rel_type_id)=1),'[]');
 END LOOP;
 binding:=jsonb_build_object('interfaceVersion','truss-runtime-binding/0.5','queryAbi',truss.query_abi(),'schema','truss','installationId',installation.installation_id::text,'releaseId',installation.release_id,'releaseSha256',installation.release_sha256,'catalogRevision',captured_revision,
 'documents',pins,'records',records,'relationships',relationships,'maximumScanRows',maximum_scan_rows,'maximumResultRows',maximum_result_rows,'maximumBytes',maximum_bytes);
 PERFORM truss.query_scope(binding);
 result:=convert_to(jsonb_build_object('binding',binding,'bindingJson',binding::text,'modules',modules,'actorOid',(SELECT oid::text FROM pg_roles WHERE rolname=session_user))::text,'UTF8');
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'query binding byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_binding_if_changed(selected_documents jsonb, maximum_scan_rows integer, maximum_result_rows integer, maximum_bytes integer, expected_release text, expected_digest text, validator text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;captured_revision int;actor oid;selected_document_id text;
 compiled record;dependency jsonb;pins jsonb:='[]';readers jsonb:='[]';current_validator text;bundle bytea;result bytea;
BEGIN
 actor:=truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected query release required' USING ERRCODE='0A000';END IF;
 IF maximum_scan_rows IS NULL OR maximum_scan_rows NOT BETWEEN 1 AND 10000 OR maximum_result_rows IS NULL OR maximum_result_rows NOT BETWEEN 1 AND 10000 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216
 OR jsonb_typeof(selected_documents) IS DISTINCT FROM 'array' OR jsonb_array_length(selected_documents) NOT BETWEEN 1 AND 32
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(selected_documents) v WHERE jsonb_typeof(v.value)<>'string')
 OR (SELECT count(DISTINCT v.value) FROM jsonb_array_elements(selected_documents) v)<>jsonb_array_length(selected_documents)
 OR validator IS NOT NULL AND validator !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'bounded original query validator request required' USING ERRCODE='22023';END IF;
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 FOR selected_document_id IN SELECT value FROM jsonb_array_elements_text(selected_documents) LOOP
  SELECT metadata->'pin' AS pin,metadata->'readers' AS readers INTO compiled
   FROM truss.runtime_document_schema WHERE rev=captured_revision AND doc_id=selected_document_id;
  IF NOT FOUND OR compiled.pin IS NULL OR jsonb_typeof(compiled.readers) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'current original query schema required' USING ERRCODE='0A000';END IF;
  pins:=pins||jsonb_build_array(compiled.pin);readers:=readers||compiled.readers;
 END LOOP;
 FOR dependency IN SELECT value FROM jsonb_array_elements(readers) LOOP
  IF NOT truss.runtime_can_read_qualified(dependency->>'documentId',dependency->>'moduleId',actor) THEN
   RAISE EXCEPTION 'complete current query reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 current_validator:=encode(sha256(convert_to(jsonb_build_object(
  'installation',installation.installation_id::text,'release',expected_release,'digest',expected_digest,
  'revision',captured_revision,'documents',pins,'person',actor::text,'sessionUser',session_user,
  'maximumScanRows',maximum_scan_rows,'maximumResultRows',maximum_result_rows,'maximumBytes',maximum_bytes)::text,'UTF8')),'hex');
 IF validator IS NOT NULL AND validator=current_validator THEN
  result:=convert_to(jsonb_build_object('outcome','unchanged','validator',current_validator)::text,'UTF8');
 ELSE
  bundle:=truss.query_binding(selected_documents,maximum_scan_rows,maximum_result_rows,maximum_bytes,expected_release,expected_digest);
  result:=convert_to(jsonb_build_object('outcome','snapshot','validator',current_validator,
   'bundle',convert_from(bundle,'UTF8')::jsonb)::text,'UTF8');
 END IF;
 -- Do not publish a warm hint after a role/dependency change during observation.
 IF truss.runtime_person(false) IS DISTINCT FROM actor OR captured_revision IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1) THEN
  RAISE EXCEPTION 'query basis changed during observation' USING ERRCODE='55P03';END IF;
 FOR dependency IN SELECT value FROM jsonb_array_elements(readers) LOOP
  IF NOT truss.runtime_can_read_qualified(dependency->>'documentId',dependency->>'moduleId',actor) THEN
   RAISE EXCEPTION 'complete current query reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'conditional query binding byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_complete_related_keys(value jsonb, maximum integer, key_arity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;item jsonb;
BEGIN
 IF maximum IS NULL OR maximum NOT BETWEEN 1 AND 100 OR key_arity IS NULL OR key_arity NOT BETWEEN 1 AND 128
  OR value IS NULL OR jsonb_typeof(value) IS DISTINCT FROM 'object' OR value-ARRAY['items','truncated']<>'{}'::jsonb
  OR jsonb_typeof(value->'items') IS DISTINCT FROM 'array' OR jsonb_typeof(value->'truncated') IS DISTINCT FROM 'boolean'
 THEN RAISE EXCEPTION 'exact complete relationship result required' USING ERRCODE='22023';END IF;
 IF value->'truncated'='true'::jsonb OR jsonb_array_length(value->'items')>maximum
 THEN RAISE EXCEPTION 'complete relationship cardinality exceeds bound' USING ERRCODE='54000';END IF;
 FOR item IN SELECT x.value FROM jsonb_array_elements(value->'items') x LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'array' OR jsonb_array_length(item)<>key_arity
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(item) component WHERE jsonb_typeof(component.value) NOT IN ('string','boolean'))
  THEN RAISE EXCEPTION 'exact authored key tuple required' USING ERRCODE='22023';END IF;
 END LOOP;
 IF key_arity=1 THEN
  SELECT coalesce(jsonb_agg(x.value->0 ORDER BY x.ordinality),'[]'::jsonb) INTO result
   FROM jsonb_array_elements(value->'items') WITH ORDINALITY x(value,ordinality);
 ELSE result:=value->'items';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_edges(binding jsonb, selected_relationship integer)
 RETURNS TABLE(id bigint, source_id bigint, target_id bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE relation truss.rel_def%ROWTYPE;edge_row truss.edge%ROWTYPE;source_object truss.object%ROWTYPE;target_object truss.object%ROWTYPE;row_count int:=0;byte_count bigint:=0;root_identity jsonb;roots jsonb:='{}';root_entry jsonb;
BEGIN
 PERFORM truss.query_scope(binding);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'relationships') r WHERE (r.value->>'relationshipTypeId')::int=selected_relationship) THEN RAISE EXCEPTION 'selected query relationship required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT relation FROM truss.rel_def r WHERE r.rel_type_id=selected_relationship AND r.retired_rev IS NULL;
 FOR edge_row IN SELECT * FROM truss.edge e WHERE e.rel_type_id=selected_relationship ORDER BY e.id LIMIT (binding->>'maximumScanRows')::int+1 LOOP
  row_count:=row_count+1;byte_count:=byte_count+octet_length(edge_row.props::text);
  IF row_count>(binding->>'maximumScanRows')::int OR byte_count>(binding->>'maximumBytes')::int THEN RAISE EXCEPTION 'bounded query edge source required' USING ERRCODE='54000';END IF;
  SELECT * INTO source_object FROM truss.object o WHERE o.id=edge_row.source_id AND o.type_id=edge_row.source_type;
  IF NOT FOUND THEN RAISE EXCEPTION 'query source endpoint missing' USING ERRCODE='55000';END IF;
  SELECT * INTO target_object FROM truss.object o WHERE o.id=edge_row.target_id AND o.type_id=edge_row.target_type;
  IF NOT FOUND OR edge_row.ver<=0 OR edge_row.rev>(binding->>'catalogRevision')::int OR source_object.ver<=0 OR target_object.ver<=0
   OR source_object.rev>(binding->>'catalogRevision')::int OR target_object.rev>(binding->>'catalogRevision')::int
   OR NOT EXISTS(SELECT 1 FROM truss.rel_endpoint e WHERE e.rel_type_id=selected_relationship AND e.source_type=edge_row.source_type AND e.target_type=edge_row.target_type) THEN
   RAISE EXCEPTION 'complete independent query endpoints required' USING ERRCODE='55000';END IF;
  FOR root_identity IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
   truss.query_object_root(binding,source_object),truss.query_object_root(binding,target_object))) WHERE value<>'null'::jsonb LOOP
   roots:=roots||jsonb_build_object((root_identity->>'typeId')||':'||(root_identity->>'id'),root_identity);
  END LOOP;
  IF byte_count+(CASE WHEN roots='{}'::jsonb THEN 0 ELSE octet_length(roots::text) END)>(binding->>'maximumBytes')::int THEN RAISE EXCEPTION 'bounded query root witnesses required' USING ERRCODE='54000';END IF;
  id:=edge_row.id;source_id:=edge_row.source_id;target_id:=edge_row.target_id;RETURN NEXT;
 END LOOP;
 FOR root_entry IN SELECT value FROM jsonb_each(roots) LOOP
  IF NOT truss.runtime_can_read(root_entry->'owner'->>'documentId',root_entry->'owner'->>'moduleId') THEN
   RAISE EXCEPTION 'current buffered query aggregate root reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 -- Buffer the complete validated edge bag before correlation and key predicates.
 PERFORM truss.query_scope(binding);
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_export_edges(binding jsonb, selected_relationship integer)
 RETURNS TABLE(id bigint, source_id bigint, target_id bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE relation truss.rel_def%ROWTYPE;edge_row truss.edge%ROWTYPE;source_object truss.object%ROWTYPE;target_object truss.object%ROWTYPE;
BEGIN
 PERFORM truss.query_scope(binding);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'relationships') r WHERE (r.value->>'relationshipTypeId')::int=selected_relationship) THEN RAISE EXCEPTION 'selected query relationship required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT relation FROM truss.rel_def r WHERE r.rel_type_id=selected_relationship AND r.retired_rev IS NULL;
 FOR edge_row IN SELECT * FROM truss.edge e WHERE e.rel_type_id=selected_relationship ORDER BY e.id LOOP
  IF octet_length(edge_row.props::text)>(binding->>'maximumBytes')::int THEN RAISE EXCEPTION 'bounded export edge row required' USING ERRCODE='54000';END IF;
  SELECT * INTO source_object FROM truss.object o WHERE o.id=edge_row.source_id AND o.type_id=edge_row.source_type;
  IF NOT FOUND THEN RAISE EXCEPTION 'query source endpoint missing' USING ERRCODE='55000';END IF;
  SELECT * INTO target_object FROM truss.object o WHERE o.id=edge_row.target_id AND o.type_id=edge_row.target_type;
  IF NOT FOUND OR edge_row.ver<=0 OR edge_row.rev>(binding->>'catalogRevision')::int OR source_object.ver<=0 OR target_object.ver<=0
   OR source_object.rev>(binding->>'catalogRevision')::int OR target_object.rev>(binding->>'catalogRevision')::int
   OR NOT EXISTS(SELECT 1 FROM truss.rel_endpoint e WHERE e.rel_type_id=selected_relationship AND e.source_type=edge_row.source_type AND e.target_type=edge_row.target_type) THEN
   RAISE EXCEPTION 'complete independent query endpoints required' USING ERRCODE='55000';END IF;
  PERFORM truss.query_object_root(binding,source_object);
  PERFORM truss.query_object_root(binding,target_object);
  id:=edge_row.id;source_id:=edge_row.source_id;target_id:=edge_row.target_id;RETURN NEXT;
 END LOOP;
 -- Complete selected-document admission covers every validated root owner.
 -- The complete edge bag is buffered under normal PostgreSQL work_mem/spill.
 PERFORM truss.query_scope(binding);
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_export_objects(binding jsonb, selected_type integer)
 RETURNS TABLE(id bigint, props jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE owner truss.type_def%ROWTYPE;object_row truss.object%ROWTYPE;property truss.prop_def%ROWTYPE;cell jsonb;
BEGIN
 PERFORM truss.query_scope(binding);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE (r.value->>'typeId')::int=selected_type) THEN RAISE EXCEPTION 'selected query record required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT owner FROM truss.type_def t WHERE t.type_id=selected_type AND t.retired_rev IS NULL;
 FOR property IN SELECT * FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL LOOP
  IF truss.valid_property_definition(property) IS NOT TRUE THEN RAISE EXCEPTION 'query value profile unavailable' USING ERRCODE='0A000';END IF;
 END LOOP;
 FOR object_row IN SELECT * FROM truss.object o WHERE o.type_id=selected_type ORDER BY o.id LOOP
  IF octet_length(object_row.props::text)>(binding->>'maximumBytes')::int THEN RAISE EXCEPTION 'bounded export source row required' USING ERRCODE='54000';END IF;
  PERFORM truss.query_object_root(binding,object_row);
  IF object_row.ver<=0 OR object_row.rev> (binding->>'catalogRevision')::int
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(object_row.props) k WHERE NOT EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL AND p.prop_id::text=k)) THEN RAISE EXCEPTION 'complete scalar source required' USING ERRCODE='0A000';END IF;
  FOR property IN SELECT * FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL LOOP
   cell:=object_row.props->property.prop_id::text;
   IF cell IS NULL THEN IF property.nullability='required' THEN RAISE EXCEPTION 'required query value missing' USING ERRCODE='55000';END IF;
   ELSIF truss.valid_property_value(cell,property) IS NOT TRUE THEN RAISE EXCEPTION 'malformed query scalar' USING ERRCODE='55000';
   ELSIF property.scalar_type IN ('integer','decimal') AND cell->>'kind'<>'null' AND truss.query_numeric_value(cell->>'text',property.scalar_type) IS NOT TRUE THEN RAISE EXCEPTION 'exact native numeric domain unavailable' USING ERRCODE='22003';END IF;
  END LOOP;
  id:=object_row.id;props:=object_row.props;RETURN NEXT;
 END LOOP;
 -- Every root owner is in the selected original documents. Rechecking every
 -- selected module covers those owners without retaining a root-sized map.
 -- PostgreSQL buffers the complete validated source; work_mem/spill applies.
 PERFORM truss.query_scope(binding);
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_export_page_objects(binding jsonb, selected_type integer, selected_key text)
 RETURNS TABLE(id bigint, props jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE key_definition truss.key_def%ROWTYPE;component truss.prop_def%ROWTYPE;row record;counted int:=0;
BEGIN
 PERFORM truss.query_scope(binding);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE (r.value->>'typeId')::int=selected_type) THEN RAISE EXCEPTION 'selected query record required' USING ERRCODE='42501';END IF;
 SELECT * INTO key_definition FROM truss.key_def k WHERE k.type_id=selected_type AND k.key_id=selected_key AND k.retired_rev IS NULL;
 IF NOT FOUND OR cardinality(key_definition.prop_ids) NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'bounded authored page key required' USING ERRCODE='0A000';END IF;
 FOR component IN SELECT p.* FROM unnest(key_definition.prop_ids) WITH ORDINALITY k(prop_id,n) JOIN truss.prop_def p ON p.prop_id=k.prop_id AND p.type_id=selected_type ORDER BY k.n LOOP
  counted:=counted+1;
  IF component.retired_rev IS NOT NULL OR component.scalar_type NOT IN ('string','boolean','integer','decimal') OR component.nullability<>'required' OR component.cardinality<>'one' OR component.home<>'json' OR NOT ((component.scalar_type IN ('string','boolean') AND coalesce(component.facets,'{}')='{}'::jsonb OR component.scalar_type='integer' AND (coalesce(component.facets,'{}')='{}'::jsonb OR component.facets='{"integerWidth":{"bits":64,"signed":true}}'::jsonb) OR component.scalar_type='decimal' AND truss.valid_decimal_facets(component.facets)) IS TRUE) THEN RAISE EXCEPTION 'required exact page key components required' USING ERRCODE='0A000';END IF;
 END LOOP;
 IF counted<>cardinality(key_definition.prop_ids) THEN RAISE EXCEPTION 'complete page key required' USING ERRCODE='55000';END IF;
 FOR row IN SELECT q.* FROM truss.query_export_objects(binding,selected_type) q LOOP
  id:=row.id;props:=row.props;RETURN NEXT;
 END LOOP;
 -- The preceding SRF validates the complete export source in this snapshot.
 -- Validated typed tuple equality matches emitted C-text/bool/numeric ROW.
 IF EXISTS(SELECT 1 FROM (SELECT (SELECT jsonb_agg(CASE property.scalar_type WHEN 'boolean' THEN o.props->property.prop_id::text->'value' WHEN 'integer' THEN to_jsonb((o.props->property.prop_id::text->>'text')::numeric) WHEN 'decimal' THEN to_jsonb((o.props->property.prop_id::text->>'text')::numeric) ELSE to_jsonb(o.props->property.prop_id::text->>'text') END ORDER BY p.n)
  FROM unnest(key_definition.prop_ids) WITH ORDINALITY p(prop_id,n) JOIN truss.prop_def property ON property.prop_id=p.prop_id AND property.type_id=selected_type) AS key_values
  FROM truss.object o WHERE o.type_id=selected_type) source GROUP BY source.key_values HAVING count(*)>1) THEN
  RAISE EXCEPTION 'unique authored page key required' USING ERRCODE='55000';END IF;
 PERFORM truss.query_scope(binding);
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_numeric_value(token text, family text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE mantissa text;exponent_text text;exponent_value int:=0;fraction_length int;coefficient text;scale_value int;magnitude int;
BEGIN
 IF token IS NULL OR family IS NULL OR octet_length(token)>1048576 THEN RETURN false;END IF;
 IF family='integer' THEN
  IF token !~ '^-?(0|[1-9][0-9]*)$' OR length(ltrim(ltrim(token,'-'),'0'))>131072 THEN RETURN false;END IF;
 ELSIF family='decimal' THEN
  IF token !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?([eE][+-]?[0-9]+)?$' THEN RETURN false;END IF;
  exponent_text:=substring(token from '[eE]([+-]?[0-9]+)$');
  IF exponent_text IS NOT NULL THEN
   IF length(exponent_text)>7 THEN RETURN false;END IF;
   exponent_value:=exponent_text::int;
  END IF;
  mantissa:=regexp_replace(ltrim(token,'-'),'[eE].*$','');
  fraction_length:=length(split_part(mantissa,'.',2));
  coefficient:=ltrim(replace(mantissa,'.',''),'0');
  scale_value:=fraction_length-exponent_value;
  magnitude:=length(coefficient)-scale_value;
  IF greatest(scale_value,0)>16383 OR magnitude>131072 THEN RETURN false;END IF;
 ELSE RETURN false;END IF;
 -- The lexical bounds prevent any implicit scale reduction at native input.
 RETURN pg_input_is_valid(token,'pg_catalog.numeric');
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_object_attribution(binding jsonb, selected_type integer, selected_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE object_row truss.object%ROWTYPE;owner truss.type_def%ROWTYPE;
 registration truss.catalog_registration_request%ROWTYPE;rebound truss.runtime_catalog_rebind_transition%ROWTYPE;
 writer xid8;asserted jsonb;history_profile text;
 attempt truss.runtime_object_attempt%ROWTYPE;selected_transition_id bigint;transition_attempt_id uuid;transition_operation_index int;transition_writer_xid xid8;transition_before_object jsonb;transition_after_object jsonb;transition_journal jsonb;
 physical truss.journal%ROWTYPE;item jsonb;event jsonb;original bytea;actor text;
 created_actor text;updated_actor text;selected_version bigint;events int;used_bytes bigint:=0;
 creation truss.runtime_create_group%ROWTYPE;member jsonb;journals jsonb;expected_actor text;after_image jsonb;
 source_row truss.record_source%ROWTYPE;source_ledger truss.runtime_import_source%ROWTYPE;
 import_record jsonb;import_payload bytea;payload_value jsonb;expected_source jsonb;source_entry jsonb;
 root_identity jsonb;historical_image jsonb;historical_ownership jsonb;owned_mutation boolean;atomic_creation boolean;creation_attempt uuid;operation jsonb;result jsonb;input_header jsonb;event_group jsonb;semantic_events jsonb;event_refs jsonb;legacy_events jsonb[];legacy_event_refs jsonb[];epoch text;
BEGIN
 PERFORM truss.query_scope(binding);
 SELECT source_epoch::text INTO STRICT epoch FROM truss.catalog_runtime_installation;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE (r.value->>'typeId')::int=selected_type)
 THEN RAISE EXCEPTION 'selected entity metadata scope required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT owner FROM truss.type_def WHERE type_id=selected_type AND retired_rev IS NULL;
 SELECT * INTO STRICT object_row FROM truss.object WHERE id=selected_id AND type_id=selected_type;
 root_identity:=truss.query_object_root(binding,object_row);
 FOR selected_version IN SELECT DISTINCT v FROM unnest(ARRAY[1::bigint,object_row.ver::bigint]) v LOOP
  expected_actor:=NULL;registration.registration_id:=NULL;result:=NULL;transition_journal:=NULL;journals:=NULL;owned_mutation:=false;atomic_creation:=false;
  IF selected_version=1 THEN
   -- Modern creations have an indexed, immutable transition coordinate.
   SELECT a.* INTO attempt FROM truss.runtime_object_transition t
    JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
    WHERE t.object_id=selected_id AND t.type_id=selected_type AND t.before_object IS NULL AND a.complete;
   IF NOT FOUND THEN
   SELECT a.* INTO STRICT attempt FROM truss.runtime_object_attempt a WHERE a.complete
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(a.results) r
     WHERE r.value->>'operation'='create_object' AND r.value->'identity'->>'id'=selected_id::text
      AND r.value->'identity'->>'typeId'=selected_type::text);
   END IF;
   IF attempt.context->'creationTransitionProfile'='{"identity":"truss-unified-create-transition","version":"0.2","sha256":"073782e2517f2a7e26c8d6479c6266ececf68963681ccfb6a380e9cd16f2e11b"}'::jsonb THEN
    SELECT t.transition_id,t.attempt_id,t.operation_index,t.writer_xid,t.before_object,t.after_object
     INTO STRICT selected_transition_id,transition_attempt_id,transition_operation_index,transition_writer_xid,transition_before_object,transition_after_object
     FROM truss.runtime_object_transition t
     WHERE t.attempt_id=attempt.id AND t.object_id=selected_id AND t.type_id=selected_type AND t.before_object IS NULL;
    IF attempt.context->'mutationProfile'=truss.runtime_owned_profile() THEN
     SELECT p.plan->'operation',p.result,p.plan->>'actorName' INTO STRICT operation,result,expected_actor FROM truss.runtime_owned_operation p
      WHERE p.attempt_id=attempt.id AND p.operation_index=transition_operation_index AND p.writer_xid=attempt.writer_xid;
    ELSE
    operation:=convert_from(attempt.input_bytes,'UTF8')::jsonb->'operations'->transition_operation_index;
    result:=attempt.results->transition_operation_index;
    SELECT t.journal INTO STRICT transition_journal FROM truss.runtime_object_transition t WHERE t.transition_id=selected_transition_id;
    END IF;
    IF transition_writer_xid IS DISTINCT FROM attempt.writer_xid OR attempt.next_index<=transition_operation_index
     OR attempt.result_count<>attempt.next_index
     OR operation->>'operation' IS DISTINCT FROM 'create_object' OR result->>'operation' IS DISTINCT FROM 'create_object'
     OR result->>'outcome' IS DISTINCT FROM 'created' OR result->>'version' IS DISTINCT FROM '1'
     OR result->'identity'->>'id' IS DISTINCT FROM selected_id::text OR result->'identity'->>'typeId' IS DISTINCT FROM selected_type::text
     OR result->'identity'->>'definitionPin' IS DISTINCT FROM operation->>'typeDefinitionPin'
     OR transition_after_object->>'id' IS DISTINCT FROM selected_id::text
     OR transition_after_object->>'type_id' IS DISTINCT FROM selected_type::text
     OR transition_after_object->>'ver' IS DISTINCT FROM '1' THEN
     RAISE EXCEPTION 'completed atomic creation attribution required' USING ERRCODE='55000';END IF;
    creation_attempt:=attempt.id;journals:=transition_journal;after_image:=transition_after_object;atomic_creation:=true;
    owned_mutation:=attempt.context->'mutationProfile'=truss.runtime_owned_profile();
    IF owned_mutation AND nullif(expected_actor,'') IS NULL
    THEN RAISE EXCEPTION 'original creation actor required' USING ERRCODE='55000';END IF;
   ELSIF attempt.context->'creationTransitionProfile' IS NULL OR attempt.context->'creationTransitionProfile'=
    '{"identity":"truss-unified-create-transition","version":"0.1","sha256":"765d7def5e677dba5d3ed5cdc841b1aa43eb2f4a493f1d2603ff3698536a5396"}'::jsonb THEN
   SELECT g.* INTO STRICT creation FROM truss.runtime_create_group g
    CROSS JOIN LATERAL jsonb_array_elements(g.expected_members) m
    WHERE m.value->'object'->>'id'=selected_id::text AND m.value->'object'->>'type_id'=selected_type::text;
   SELECT m.value INTO STRICT member FROM jsonb_array_elements(creation.expected_members) m
    WHERE m.value->'object'->>'id'=selected_id::text AND m.value->'object'->>'type_id'=selected_type::text;
   SELECT a.* INTO STRICT attempt FROM truss.runtime_object_attempt a
    WHERE a.complete AND a.writer_xid=creation.writer_xid AND a.actor_oid=creation.actor_oid
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(a.results) r
      WHERE r.value->>'operation'='create_object' AND r.value->'identity'->>'id'=selected_id::text
       AND r.value->'identity'->>'typeId'=selected_type::text);
   creation_attempt:=attempt.id;
   journals:=jsonb_build_array(member->'journal');after_image:=member->'object';expected_actor:=creation.actor_name;
   ELSE RAISE EXCEPTION 'known original creation attribution profile required' USING ERRCODE='55000';END IF;
   input_header:=CASE WHEN attempt.context ? 'originalAssertedOrigin'
    THEN jsonb_build_object('assertedOrigin',attempt.context->'originalAssertedOrigin','mutationProfile',attempt.context->'mutationProfile')
    ELSE convert_from(attempt.input_bytes,'UTF8')::jsonb END;
   writer:=attempt.writer_xid;asserted:=input_header->'assertedOrigin';history_profile:=CASE WHEN input_header->'mutationProfile'=truss.runtime_owned_profile() THEN 'truss-native-owned-create/0.1' ELSE 'truss-native-scalar-create/0.2' END;
  ELSE
   SELECT * INTO rebound FROM truss.runtime_catalog_rebind_transition t WHERE t.object_id=selected_id AND t.type_id=selected_type AND (t.after_object->>'ver')::bigint=selected_version;
   IF FOUND THEN
    SELECT * INTO STRICT registration FROM truss.catalog_registration_request r WHERE r.registration_id=rebound.registration_id;
    IF registration.writer_xid IS DISTINCT FROM rebound.writer_xid OR registration.actor_oid IS DISTINCT FROM rebound.actor_oid OR registration.revision IS DISTINCT FROM rebound.revision THEN RAISE EXCEPTION 'original catalog attribution source required' USING ERRCODE='55000';END IF;
    PERFORM truss.catalog_rebind_transition_reader(rebound);
    journals:=rebound.journal;after_image:=rebound.after_object;expected_actor:=registration.actor_name;
    writer:=registration.writer_xid;asserted:=convert_from(registration.origin_bytes,'UTF8')::jsonb;history_profile:=truss.catalog_rebind_profile(rebound.journal);
   ELSE
   SELECT t.transition_id,t.attempt_id,t.operation_index,t.writer_xid,t.before_object,t.after_object
    INTO STRICT selected_transition_id,transition_attempt_id,transition_operation_index,transition_writer_xid,transition_before_object,transition_after_object
    FROM truss.runtime_object_transition t
    WHERE t.object_id=selected_id AND t.type_id=selected_type AND (t.after_object->>'ver')::bigint=selected_version;
   SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=transition_attempt_id;
   IF NOT attempt.complete OR attempt.writer_xid IS DISTINCT FROM transition_writer_xid
    OR attempt.next_index<=transition_operation_index OR attempt.result_count<>attempt.next_index
   THEN RAISE EXCEPTION 'complete original attribution attempt required' USING ERRCODE='55000';END IF;
   input_header:=CASE WHEN attempt.context ? 'originalAssertedOrigin'
    THEN jsonb_build_object('assertedOrigin',attempt.context->'originalAssertedOrigin','mutationProfile',attempt.context->'mutationProfile')
    ELSE convert_from(attempt.input_bytes,'UTF8')::jsonb END;
   owned_mutation:=input_header->'mutationProfile'=truss.runtime_owned_profile();
   IF owned_mutation THEN
    SELECT p.plan->'operation',p.result,p.plan->>'actorName' INTO STRICT operation,result,expected_actor FROM truss.runtime_owned_operation p
     WHERE p.attempt_id=attempt.id AND p.operation_index=transition_operation_index AND p.writer_xid=attempt.writer_xid;
   ELSE
    operation:=input_header->'operations'->transition_operation_index;result:=attempt.results->transition_operation_index;
    IF operation IS NULL THEN operation:=convert_from(attempt.input_bytes,'UTF8')::jsonb->'operations'->transition_operation_index;END IF;
   END IF;
   IF owned_mutation THEN
    IF operation->>'operation' IS DISTINCT FROM 'update_object' OR result->>'operation' IS DISTINCT FROM 'update_object'
     OR result->>'outcome' IS DISTINCT FROM 'changed'
     OR transition_after_object->>'id' IS DISTINCT FROM selected_id::text
     OR transition_after_object->>'type_id' IS DISTINCT FROM selected_type::text
     OR transition_after_object->>'ver' IS DISTINCT FROM selected_version::text OR nullif(expected_actor,'') IS NULL
    THEN RAISE EXCEPTION 'original owned update attribution required' USING ERRCODE='55000';END IF;
   ELSIF operation->>'operation' IS DISTINCT FROM 'update_object' OR result->>'operation' IS DISTINCT FROM 'update_object'
    OR result->>'outcome' IS DISTINCT FROM 'changed' OR result->>'version' IS DISTINCT FROM selected_version::text
    OR result->'identity'->>'id' IS DISTINCT FROM selected_id::text OR result->'identity'->>'typeId' IS DISTINCT FROM selected_type::text
   THEN RAISE EXCEPTION 'original changed attribution result required' USING ERRCODE='55000';END IF;
   IF NOT owned_mutation THEN SELECT t.journal INTO STRICT transition_journal FROM truss.runtime_object_transition t WHERE t.transition_id=selected_transition_id;END IF;
   journals:=transition_journal;after_image:=transition_after_object;
   writer:=attempt.writer_xid;asserted:=input_header->'assertedOrigin';history_profile:=CASE WHEN owned_mutation THEN 'truss-native-owned-mutation/0.1' ELSE 'truss-native-scalar-mutation/0.1' END;
   END IF;
  END IF;
  IF selected_version=object_row.ver AND (after_image->>'id' IS DISTINCT FROM object_row.id::text
   OR after_image->>'type_id' IS DISTINCT FROM object_row.type_id::text OR after_image->>'ver' IS DISTINCT FROM object_row.ver::text)
  THEN RAISE EXCEPTION 'current entity attribution identity differs' USING ERRCODE='55000';END IF;
  -- Original attribution can depend on roots that no longer own this object.
  -- Their original identities must be covered by final selected-scope checks.
  FOR historical_image IN SELECT value FROM jsonb_array_elements(jsonb_build_array(after_image,
   CASE WHEN owned_mutation THEN transition_before_object ELSE NULL END)) WHERE value<>'null'::jsonb LOOP
   historical_ownership:=truss.runtime_object_ownership_at(historical_image);
   IF historical_ownership->>'state'='owned' THEN
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'documents') d JOIN truss.schema_doc archive
     ON archive.doc_id=d.value->>'documentId' AND archive.doc_revision=d.value->>'revision' AND archive.content_sha256=d.value->>'sha256'
     WHERE archive.doc_id=historical_ownership->'root'->'owner'->>'documentId' AND archive.rev<=(binding->>'catalogRevision')::int
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(archive.document::jsonb->'modules') m
       WHERE m.value->>'id'=historical_ownership->'root'->'owner'->>'moduleId')) THEN
     RAISE EXCEPTION 'historical attribution root document must be selected for query' USING ERRCODE='0A000';END IF;
    PERFORM truss.runtime_history_ownership(jsonb_build_object('identity',jsonb_build_object('id',selected_id::text,'typeId',selected_type::text),
     'catalogRevision',historical_image->>'rev','ownership',historical_ownership));
   END IF;
  END LOOP;
  actor:=NULL;events:=0;event_group:=NULL;semantic_events:='[]';event_refs:='[]';legacy_events:='{}';legacy_event_refs:='{}';
  IF owned_mutation OR registration.registration_id IS NOT NULL THEN
   actor:=expected_actor;
   IF nullif(actor,'') IS NULL THEN RAISE EXCEPTION 'immutable attribution actor required' USING ERRCODE='55000';END IF;
   IF selected_version=1 THEN created_actor:=actor;END IF;
   IF selected_version=object_row.ver THEN updated_actor:=actor;END IF;
  ELSE
  FOR item IN SELECT value FROM jsonb_array_elements(journals) LOOP
   events:=events+1;used_bytes:=used_bytes+octet_length(item::text);
   IF events>128 OR used_bytes>(binding->>'maximumBytes')::bigint THEN RAISE EXCEPTION 'bounded attribution evidence required' USING ERRCODE='54000';END IF;
   SELECT * INTO STRICT physical FROM truss.journal WHERE xid=(item->>'xid')::xid8 AND seq=(item->>'seq')::bigint;
   IF physical IS DISTINCT FROM jsonb_populate_record(NULL::truss.journal,item) OR physical.entity_kind<>'o' OR physical.entity_id<>selected_id
    OR physical.entity_type<>selected_type OR physical.ver<>selected_version OR physical.xid<>writer
   THEN RAISE EXCEPTION 'original attribution journal correspondence required' USING ERRCODE='55000';END IF;
   original:=decode(physical.new_value->>'bytesBase64','base64');
   IF physical.new_value IS DISTINCT FROM truss.runtime_exact_wrapper('event',original)
    OR (convert_from(original,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
   THEN RAISE EXCEPTION 'original attribution event required' USING ERRCODE='55000';END IF;
   event:=convert_from(original,'UTF8')::jsonb;
   IF event->>'interfaceVersion' IS DISTINCT FROM 'truss-history-event/0.2.0-proposal'
    OR event->>'sourceEpoch' IS DISTINCT FROM epoch
    OR event->>'historyProfile' IS DISTINCT FROM history_profile
    OR physical.op IS DISTINCT FROM (CASE event->>'operation' WHEN 'property' THEN 'update' ELSE event->>'operation' END)
    OR physical.prop_id IS DISTINCT FROM (event->>'propertyId')::int
    OR event->'origin'->'asserted' IS DISTINCT FROM asserted
    OR event->>'xid' IS DISTINCT FROM physical.xid::text OR event->>'seq' IS DISTINCT FROM physical.seq::text
    OR event->>'eventVersion' IS DISTINCT FROM selected_version::text OR event->>'eventCatalogRevision' IS DISTINCT FROM physical.rev::text
    OR event->'identity'->>'id' IS DISTINCT FROM selected_id::text OR event->'identity'->>'typeId' IS DISTINCT FROM selected_type::text
    OR event->'identity'->'owner' IS DISTINCT FROM jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module)
    OR physical.origin IS DISTINCT FROM truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8'))
    OR nullif(event->'origin'->>'databaseRole','') IS NULL
   THEN RAISE EXCEPTION 'original attribution identity and origin required' USING ERRCODE='55000';END IF;
   IF actor IS NOT NULL AND actor IS DISTINCT FROM event->'origin'->>'databaseRole'
   THEN RAISE EXCEPTION 'one actor per attribution version required' USING ERRCODE='55000';END IF;
   IF event_group IS NULL THEN event_group:=event->'mutationGroup';
   ELSIF event_group IS DISTINCT FROM event->'mutationGroup' THEN RAISE EXCEPTION 'one original attribution group required' USING ERRCODE='55000';END IF;
   legacy_events[cardinality(legacy_events)+1]:=event-'mutationGroup';
   legacy_event_refs[cardinality(legacy_event_refs)+1]:=jsonb_build_object('sourceEpoch',epoch,'historyProfile',event->>'historyProfile','xid',physical.xid::text,'seq',physical.seq::text);
   actor:=event->'origin'->>'databaseRole';
   IF expected_actor IS NOT NULL AND actor IS DISTINCT FROM expected_actor
   THEN RAISE EXCEPTION 'original creation actor correspondence required' USING ERRCODE='55000';END IF;
   IF selected_version=1 AND event->>'operation'<>'create'
   THEN RAISE EXCEPTION 'original creation attribution required' USING ERRCODE='55000';END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(v ORDER BY n),'[]'::jsonb) INTO semantic_events FROM unnest(legacy_events) WITH ORDINALITY e(v,n);
  SELECT coalesce(jsonb_agg(v ORDER BY n),'[]'::jsonb) INTO event_refs FROM unnest(legacy_event_refs) WITH ORDINALITY e(v,n);
  IF event_group IS DISTINCT FROM jsonb_build_object('profile','truss-history-group/0.1.0','eventCount',events::text,'orderedEventDigest',encode(sha256(convert_to(semantic_events::text,'UTF8')),'hex'))
   OR selected_version>1 AND result->'events' IS DISTINCT FROM event_refs
  THEN RAISE EXCEPTION 'complete original attribution event group required' USING ERRCODE='55000';END IF;
  IF events=0 THEN RAISE EXCEPTION 'missing attribution events' USING ERRCODE='55000';END IF;
  IF selected_version=1 THEN created_actor:=actor;END IF;
  IF selected_version=object_row.ver THEN updated_actor:=actor;END IF;
  END IF;
 END LOOP;
 SELECT * INTO source_row FROM truss.record_source WHERE entity_kind='o' AND entity_id=selected_id;
 SELECT * INTO source_ledger FROM truss.runtime_import_source WHERE entity_kind='o' AND entity_id=selected_id;
 IF (source_row.entity_id IS NULL) IS DISTINCT FROM (source_ledger.entity_id IS NULL)
 THEN RAISE EXCEPTION 'original import source linkage required' USING ERRCODE='55000';END IF;
 IF source_ledger.entity_id IS NOT NULL THEN
  SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=source_ledger.group_attempt_id;
  IF attempt.context->'mutationProfile'=truss.runtime_owned_profile() THEN
   -- Modern source rows were admitted with the atomic group. Resolve their
   -- indexed result without decoding the entire group or replaying its payload.
   SELECT p.result INTO STRICT result FROM truss.runtime_owned_operation p
    WHERE p.attempt_id=attempt.id AND p.operation_index=source_ledger.operation_index
     AND p.writer_xid=source_ledger.writer_xid;
  ELSE result:=attempt.results->source_ledger.operation_index;END IF;
  IF attempt.id IS DISTINCT FROM creation_attempt OR NOT attempt.complete OR attempt.writer_xid IS DISTINCT FROM source_ledger.writer_xid
   OR source_ledger.operation_index<0 OR source_ledger.operation_index>=attempt.next_index
   OR result->>'outcome' IS DISTINCT FROM 'created'
   OR result->'identity'->>'id' IS DISTINCT FROM selected_id::text
   OR result->'identity'->>'typeId' IS DISTINCT FROM selected_type::text
   OR result->'identity'->'owner' IS DISTINCT FROM jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module)
  THEN RAISE EXCEPTION 'original import creation linkage required' USING ERRCODE='55000';END IF;
  -- Keep the historical scalar-import qualification separate. Modern trusted
  -- imports read their immutable source facts directly, including owned roots.
  IF attempt.context->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
  IF attempt.next_index<>1 OR source_ledger.operation_index<>0 THEN
   RAISE EXCEPTION 'legacy singleton import creation required' USING ERRCODE='55000';END IF;
  import_record:=convert_from(source_ledger.original_record,'UTF8')::jsonb;
  import_payload:=decode(import_record->'payload'->>'bytesBase64','base64');
  IF encode(sha256(import_payload),'hex') IS DISTINCT FROM import_record->'payload'->>'sha256'
   OR (convert_from(import_payload,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
  THEN RAISE EXCEPTION 'original import payload required' USING ERRCODE='55000';END IF;
  payload_value:=convert_from(import_payload,'UTF8')::jsonb;expected_source:='{}'::jsonb;
  input_header:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
  operation:=input_header->'operations'->source_ledger.operation_index;
  IF import_record->>'kind' IS DISTINCT FROM 'object' OR payload_value->>'kind' IS DISTINCT FROM 'object'
   OR operation->>'operation' IS DISTINCT FROM 'create_object'
   OR operation->>'typeDefinitionPin' IS DISTINCT FROM import_record->'identity'->'type'->>'definitionPin'
   OR operation->'values' IS DISTINCT FROM payload_value->'values' OR operation->'ownership' IS DISTINCT FROM payload_value->'ownership'
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(input_header->'assertedOrigin'->'entries') e
    WHERE e.value->>'key'='x-load-id' AND e.value->'value'=jsonb_build_object('kind','string','text',source_row.load_id))
  THEN RAISE EXCEPTION 'original import payload and creation correspondence required' USING ERRCODE='55000';END IF;
  IF payload_value->'source' IS NOT NULL THEN
   SELECT coalesce(jsonb_object_agg(source_entry->>'key',CASE source_entry->'value'->>'kind'
     WHEN 'string' THEN source_entry->'value'->'text' WHEN 'null' THEN 'null'::jsonb
     WHEN 'boolean' THEN source_entry->'value'->'value' ELSE source_entry->'value' END ORDER BY ordinal),'{}'::jsonb)
    INTO expected_source FROM jsonb_array_elements(payload_value->'source'->'entries') WITH ORDINALITY s(source_entry,ordinal);
  END IF;
  IF source_row.source IS DISTINCT FROM expected_source THEN RAISE EXCEPTION 'original import source facts required' USING ERRCODE='55000';END IF;
  END IF;
 END IF;
 PERFORM truss.query_scope(binding);
 IF root_identity IS NOT NULL AND NOT truss.runtime_can_read(root_identity->'owner'->>'documentId',root_identity->'owner'->>'moduleId') THEN RAISE EXCEPTION 'current attribution aggregate root reader required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('_version',object_row.ver::text,'_created_by',created_actor,'_updated_by',updated_actor,
  '_original_author',source_row.source->'author','_original_at',source_row.source->'at');
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_object_load_id(binding jsonb, selected_type integer, selected_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE selected_load text;current_object truss.object%ROWTYPE;root_identity jsonb;
BEGIN
 -- Prove the complete original creation/current attribution, immutable import
 -- ledger, payload and load-origin correspondence in this statement snapshot.
 PERFORM truss.query_object_attribution(binding,selected_type,selected_id);
 SELECT load_id INTO selected_load FROM truss.record_source
  WHERE entity_kind='o' AND entity_id=selected_id;
 SELECT * INTO STRICT current_object FROM truss.object WHERE id=selected_id AND type_id=selected_type;
 root_identity:=truss.query_object_root(binding,current_object);
 PERFORM truss.query_scope(binding);
 IF root_identity IS NOT NULL AND NOT truss.runtime_can_read(root_identity->'owner'->>'documentId',root_identity->'owner'->>'moduleId') THEN RAISE EXCEPTION 'current metadata aggregate root reader required' USING ERRCODE='42501';END IF;
 -- A proved ordinary creation has JSON null, never a SQL NULL result carrier.
 RETURN jsonb_build_object('_load_id',selected_load);
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_object_root(binding jsonb, object_row truss.object)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE root_row truss.object;root_type truss.type_def;pin record;captured_revision int:=(binding->>'catalogRevision')::int;
BEGIN
 IF object_row.ver<=0 OR object_row.rev>captured_revision THEN RAISE EXCEPTION 'current query object required' USING ERRCODE='55000';END IF;
 IF object_row.root_id IS NULL AND object_row.root_type IS NULL THEN RETURN NULL;END IF;
 IF object_row.root_id IS NULL OR object_row.root_type IS NULL OR object_row.root_id<=0
  OR object_row.root_id=object_row.id AND object_row.root_type=object_row.type_id THEN
  RAISE EXCEPTION 'complete query aggregate root required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT root_row FROM truss.object WHERE id=object_row.root_id AND type_id=object_row.root_type;
 SELECT * INTO STRICT root_type FROM truss.type_def WHERE type_id=root_row.type_id AND retired_rev IS NULL AND NOT provisional AND kind='record';
 IF root_row.root_id IS NOT NULL OR root_row.root_type IS NOT NULL OR root_row.ver<=0 THEN
  RAISE EXCEPTION 'rootless query aggregate root required' USING ERRCODE='55000';END IF;
 IF root_row.rev>captured_revision OR root_type.since_rev>captured_revision THEN RAISE EXCEPTION 'catalog changed during query root observation' USING ERRCODE='55P03';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'documents') d JOIN truss.schema_doc archive
  ON archive.doc_id=d.value->>'documentId' AND archive.doc_revision=d.value->>'revision' AND archive.content_sha256=d.value->>'sha256'
  WHERE archive.doc_id=root_type.document_id AND archive.rev<=captured_revision
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(archive.document::jsonb->'modules') m WHERE m.value->>'id'=root_type.module)) THEN RAISE EXCEPTION 'aggregate root document must be selected for query' USING ERRCODE='0A000';END IF;
 IF NOT truss.runtime_can_read(root_type.document_id,root_type.module) THEN RAISE EXCEPTION 'current query aggregate root reader required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',root_row.type_id,NULL,captured_revision);
 RETURN jsonb_build_object('id',root_row.id::text,'typeId',root_row.type_id::text,'definitionPin',pin.definition_pin,
  'owner',jsonb_build_object('documentId',root_type.document_id,'moduleId',root_type.module));
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_object_times(binding jsonb, selected_type integer, selected_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE current_object truss.object%ROWTYPE;root_identity jsonb;
BEGIN
 -- Establish original creation/current-version attribution and exact current image
 -- in this statement snapshot, including the caller's pending writes.
 PERFORM truss.query_object_attribution(binding,selected_type,selected_id);
 SELECT * INTO STRICT current_object FROM truss.object WHERE id=selected_id AND type_id=selected_type;
 IF NOT isfinite(current_object.created_at) OR NOT isfinite(current_object.updated_at)
  OR current_object.created_at<'0001-01-01 00:00:00+00'::timestamptz
  OR current_object.created_at>='10000-01-01 00:00:00+00'::timestamptz
  OR current_object.updated_at<'0001-01-01 00:00:00+00'::timestamptz
  OR current_object.updated_at>='10000-01-01 00:00:00+00'::timestamptz
 THEN RAISE EXCEPTION 'finite supported object timestamps required' USING ERRCODE='0A000';END IF;
 SELECT * INTO STRICT current_object FROM truss.object WHERE id=selected_id AND type_id=selected_type;
 root_identity:=truss.query_object_root(binding,current_object);
 PERFORM truss.query_scope(binding);
 IF root_identity IS NOT NULL AND NOT truss.runtime_can_read(root_identity->'owner'->>'documentId',root_identity->'owner'->>'moduleId') THEN RAISE EXCEPTION 'current metadata aggregate root reader required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object(
  '_created_at',to_char(current_object.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  '_updated_at',to_char(current_object.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_objects(binding jsonb, selected_type integer)
 RETURNS TABLE(id bigint, props jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE owner truss.type_def%ROWTYPE;object_row truss.object%ROWTYPE;selected_row record;numeric_properties jsonb;numeric_valid boolean;
 row_count int:=0;byte_count bigint:=0;root_identity jsonb;roots jsonb:='{}';root_entry jsonb;
BEGIN
 PERFORM truss.query_scope(binding);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE (r.value->>'typeId')::int=selected_type) THEN RAISE EXCEPTION 'selected query record required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT owner FROM truss.type_def t WHERE t.type_id=selected_type AND t.retired_rev IS NULL;
 SELECT coalesce(jsonb_agg(jsonb_build_object('propertyId',p.prop_id::text,'scalarType',p.scalar_type) ORDER BY p.prop_id),'[]'::jsonb)
 INTO numeric_properties FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL AND p.scalar_type IN ('integer','decimal');
 FOR selected_row IN
  SELECT o AS object_row,NOT EXISTS(
   SELECT 1 FROM jsonb_array_elements(numeric_properties) f
   CROSS JOIN LATERAL (SELECT o.props->(f.value->>'propertyId') AS cell) selected_cell
   WHERE selected_cell.cell IS NOT NULL AND selected_cell.cell<>'{"kind":"null"}'::jsonb
    AND truss.query_numeric_value(selected_cell.cell->>'text',f.value->>'scalarType') IS NOT TRUE
  ) AS numeric_valid
  FROM truss.object o WHERE o.type_id=selected_type ORDER BY o.id LIMIT (binding->>'maximumScanRows')::int+1 LOOP
  object_row:=selected_row.object_row;numeric_valid:=selected_row.numeric_valid;
  row_count:=row_count+1;byte_count:=byte_count+octet_length(object_row.props::text);
  IF row_count>(binding->>'maximumScanRows')::int OR byte_count>(binding->>'maximumBytes')::int THEN RAISE EXCEPTION 'bounded query source required' USING ERRCODE='54000';END IF;
  root_identity:=truss.query_object_root(binding,object_row);
  IF root_identity IS NOT NULL THEN roots:=roots||jsonb_build_object((root_identity->>'typeId')||':'||(root_identity->>'id'),root_identity);END IF;
  IF byte_count+(CASE WHEN roots='{}'::jsonb THEN 0 ELSE octet_length(roots::text) END)>(binding->>'maximumBytes')::int THEN RAISE EXCEPTION 'bounded query root witnesses required' USING ERRCODE='54000';END IF;
  IF object_row.ver<=0 OR object_row.rev> (binding->>'catalogRevision')::int THEN RAISE EXCEPTION 'complete scalar source required' USING ERRCODE='0A000';END IF;
  IF NOT numeric_valid THEN RAISE EXCEPTION 'exact native numeric domain unavailable' USING ERRCODE='22003';END IF;
  id:=object_row.id;props:=object_row.props;RETURN NEXT;
 END LOOP;
 FOR root_entry IN SELECT value FROM jsonb_each(roots) LOOP
  IF NOT truss.runtime_can_read(root_entry->'owner'->>'documentId',root_entry->'owner'->>'moduleId') THEN
   RAISE EXCEPTION 'current buffered query aggregate root reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 -- PL/pgSQL buffers this complete validated source before caller predicates run.
 PERFORM truss.query_scope(binding);
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_page_objects(binding jsonb, selected_type integer, selected_key text)
 RETURNS TABLE(id bigint, props jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE key_definition truss.key_def%ROWTYPE;component truss.prop_def%ROWTYPE;row record;counted int:=0;
BEGIN
 PERFORM truss.query_scope(binding);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE (r.value->>'typeId')::int=selected_type) THEN RAISE EXCEPTION 'selected query record required' USING ERRCODE='42501';END IF;
 SELECT * INTO key_definition FROM truss.key_def k WHERE k.type_id=selected_type AND k.key_id=selected_key AND k.retired_rev IS NULL;
 IF NOT FOUND OR cardinality(key_definition.prop_ids) NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'bounded authored page key required' USING ERRCODE='0A000';END IF;
 FOR component IN SELECT p.* FROM unnest(key_definition.prop_ids) WITH ORDINALITY k(prop_id,n) JOIN truss.prop_def p ON p.prop_id=k.prop_id AND p.type_id=selected_type ORDER BY k.n LOOP
  counted:=counted+1;
  IF component.retired_rev IS NOT NULL OR component.scalar_type NOT IN ('string','boolean','integer','decimal') OR component.nullability<>'required' OR component.cardinality<>'one' OR component.home<>'json' OR NOT ((component.scalar_type IN ('string','boolean') AND coalesce(component.facets,'{}')='{}'::jsonb OR component.scalar_type='integer' AND (coalesce(component.facets,'{}')='{}'::jsonb OR component.facets='{"integerWidth":{"bits":64,"signed":true}}'::jsonb) OR component.scalar_type='decimal' AND truss.valid_decimal_facets(component.facets)) IS TRUE) THEN RAISE EXCEPTION 'required exact page key components required' USING ERRCODE='0A000';END IF;
 END LOOP;
 IF counted<>cardinality(key_definition.prop_ids) THEN RAISE EXCEPTION 'complete page key required' USING ERRCODE='55000';END IF;
 FOR row IN SELECT q.* FROM truss.query_objects(binding,selected_type) q LOOP
  id:=row.id;props:=row.props;RETURN NEXT;
 END LOOP;
 -- The preceding SRF validates and bounds the complete source in this snapshot.
 -- Validated typed tuple equality matches emitted C-text/bool/numeric ROW.
 IF EXISTS(SELECT 1 FROM (SELECT (SELECT jsonb_agg(CASE property.scalar_type WHEN 'boolean' THEN o.props->property.prop_id::text->'value' WHEN 'integer' THEN to_jsonb((o.props->property.prop_id::text->>'text')::numeric) WHEN 'decimal' THEN to_jsonb((o.props->property.prop_id::text->>'text')::numeric) ELSE to_jsonb(o.props->property.prop_id::text->>'text') END ORDER BY p.n)
  FROM unnest(key_definition.prop_ids) WITH ORDINALITY p(prop_id,n) JOIN truss.prop_def property ON property.prop_id=p.prop_id AND property.type_id=selected_type) AS key_values
  FROM truss.object o WHERE o.type_id=selected_type) source GROUP BY source.key_values HAVING count(*)>1) THEN
  RAISE EXCEPTION 'unique authored page key required' USING ERRCODE='55000';END IF;
 PERFORM truss.query_scope(binding);
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_scope(binding jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;selected_document jsonb;selected_record jsonb;selected_field jsonb;source truss.schema_doc%ROWTYPE;owner truss.type_def%ROWTYPE;property truss.prop_def%ROWTYPE;module jsonb;selected_relation jsonb;relation truss.rel_def%ROWTYPE;selected_key jsonb;key_definition truss.key_def%ROWTYPE;current_actor oid;compiled jsonb;
BEGIN
 current_actor:=truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF jsonb_typeof(binding) IS DISTINCT FROM 'object' OR binding->>'interfaceVersion' IS DISTINCT FROM 'truss-runtime-binding/0.5'
 OR binding->'queryAbi' IS DISTINCT FROM truss.query_abi()
 OR binding-ARRAY['interfaceVersion','queryAbi','schema','installationId','releaseId','releaseSha256','catalogRevision','documents','records','relationships','maximumScanRows','maximumResultRows','maximumBytes']<>'{}'::jsonb
 OR binding->>'schema' IS DISTINCT FROM 'truss' OR binding->>'installationId' IS DISTINCT FROM installation.installation_id::text
 OR binding->>'releaseId' IS DISTINCT FROM installation.release_id OR binding->>'releaseSha256' IS DISTINCT FROM installation.release_sha256
 OR installation.release_id<>'truss-catalog-runtime/0.72-candidate' OR (binding->>'catalogRevision')::int IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1)
 OR binding->>'maximumResultRows' IS NULL OR (binding->>'maximumResultRows')::int NOT BETWEEN 1 AND 10000 OR binding->>'maximumScanRows' IS NULL OR binding->>'maximumBytes' IS NULL OR (binding->>'maximumScanRows')::int NOT BETWEEN 1 AND 10000 OR (binding->>'maximumBytes')::int NOT BETWEEN 1 AND 16777216
 OR octet_length(binding::text)>4194304 OR jsonb_typeof(binding->'documents') IS DISTINCT FROM 'array' OR jsonb_array_length(binding->'documents') NOT BETWEEN 1 AND 32
 OR jsonb_typeof(binding->'relationships') IS DISTINCT FROM 'array' OR jsonb_array_length(binding->'relationships')>1024
 OR jsonb_typeof(binding->'records') IS DISTINCT FROM 'array' OR jsonb_array_length(binding->'records') NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'selected query context required' USING ERRCODE='0A000';END IF;
 IF jsonb_array_length(binding->'documents')=1 THEN
  SELECT metadata INTO compiled FROM truss.runtime_document_schema
   WHERE rev=(binding->>'catalogRevision')::int AND doc_id=binding->'documents'->0->>'documentId';
  IF compiled->'pin'=binding->'documents'->0 AND compiled->'records'=binding->'records'
   AND compiled->'relationships'=binding->'relationships' AND compiled->'closed'='true'::jsonb AND compiled->'itemsValid'='true'::jsonb THEN
   FOR selected_document IN SELECT value FROM jsonb_array_elements(compiled->'readers') LOOP
    IF NOT truss.runtime_can_read_qualified(selected_document->>'documentId',selected_document->>'moduleId',current_actor) THEN
     RAISE EXCEPTION 'complete selected_document reader required' USING ERRCODE='42501';END IF;
   END LOOP;
   RETURN;
  END IF;
 END IF;
 FOR selected_document IN SELECT value FROM jsonb_array_elements(binding->'documents') LOOP
  SELECT * INTO source FROM truss.schema_doc d WHERE d.doc_id=selected_document->>'documentId' AND d.rev<= (binding->>'catalogRevision')::int ORDER BY d.rev DESC LIMIT 1;
  IF NOT FOUND OR source.doc_revision IS DISTINCT FROM selected_document->>'revision' OR source.content_sha256 IS DISTINCT FROM selected_document->>'sha256' THEN RAISE EXCEPTION 'original query source changed' USING ERRCODE='55P03';END IF;
  -- Full original source bytes are supplied only under complete selected_document scope.
  FOR module IN SELECT value FROM jsonb_array_elements(source.document::jsonb->'modules') LOOP
   IF NOT truss.runtime_can_read(source.doc_id,module->>'id') THEN RAISE EXCEPTION 'complete selected_document reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
 FOR selected_record IN SELECT value FROM jsonb_array_elements(binding->'records') LOOP
  SELECT * INTO owner FROM truss.type_def t WHERE t.type_id=(selected_record->>'typeId')::int AND t.retired_rev IS NULL AND NOT t.provisional AND t.kind='record';
  IF NOT FOUND OR owner.document_id IS DISTINCT FROM selected_record->'identity'->>'documentId' OR owner.module IS DISTINCT FROM selected_record->'identity'->>'module' OR owner.element IS DISTINCT FROM selected_record->'identity'->>'element'
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'documents') d WHERE d.value->>'documentId'=owner.document_id AND d.value->>'revision'=selected_record->'identity'->>'revision')
   OR NOT truss.runtime_can_read(owner.document_id,owner.module) THEN RAISE EXCEPTION 'accepted authorized query record required' USING ERRCODE='42501';END IF;
  IF jsonb_typeof(selected_record->'fields') IS DISTINCT FROM 'array' OR jsonb_array_length(selected_record->'fields')<>(SELECT count(*) FROM truss.prop_def p WHERE p.type_id=owner.type_id AND p.retired_rev IS NULL)
   OR (SELECT count(DISTINCT f.value->>'propertyId') FROM jsonb_array_elements(selected_record->'fields') f)<>jsonb_array_length(selected_record->'fields') THEN RAISE EXCEPTION 'complete property mapping required' USING ERRCODE='0A000';END IF;
  IF truss.runtime_object_values_readable(owner.type_id) IS NOT TRUE THEN RAISE EXCEPTION 'current query interpretation reader required' USING ERRCODE='42501';END IF;
  FOR selected_field IN SELECT value FROM jsonb_array_elements(selected_record->'fields') LOOP
   SELECT * INTO property FROM truss.prop_def p WHERE p.type_id=owner.type_id AND p.prop_id=(selected_field->>'propertyId')::int AND p.retired_rev IS NULL;
   IF NOT FOUND OR property.element IS DISTINCT FROM selected_field->'identity'->>'element' OR property.declaration_module IS DISTINCT FROM selected_field->'identity'->>'module'
    OR selected_field->'identity'->>'documentId' IS DISTINCT FROM owner.document_id OR selected_field->'identity'->>'revision' IS DISTINCT FROM selected_record->'identity'->>'revision'
    OR NOT truss.runtime_can_read(owner.document_id,property.declaration_module) THEN RAISE EXCEPTION 'accepted authorized property mapping required' USING ERRCODE='42501';END IF;
  END LOOP;
  IF jsonb_typeof(selected_record->'keys') IS DISTINCT FROM 'array' OR jsonb_array_length(selected_record->'keys')<>(SELECT count(*) FROM truss.key_def k WHERE k.type_id=owner.type_id AND k.retired_rev IS NULL)
   OR (SELECT count(DISTINCT k.value->>'keyId') FROM jsonb_array_elements(selected_record->'keys') k)<>jsonb_array_length(selected_record->'keys') THEN RAISE EXCEPTION 'complete current key mapping required' USING ERRCODE='0A000';END IF;
  FOR selected_key IN SELECT value FROM jsonb_array_elements(selected_record->'keys') LOOP
   SELECT * INTO key_definition FROM truss.key_def k WHERE k.type_id=owner.type_id AND k.key_id=selected_key->>'keyId' AND k.retired_rev IS NULL;
   IF NOT FOUND OR selected_key->'propertyIds' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(p.prop_id::text ORDER BY p.n),'[]') FROM unnest(key_definition.prop_ids) WITH ORDINALITY p(prop_id,n)) THEN
    RAISE EXCEPTION 'exact ordered native key mapping required' USING ERRCODE='55000';END IF;
  END LOOP;
 END LOOP;
 FOR selected_relation IN SELECT value FROM jsonb_array_elements(binding->'relationships') LOOP
  SELECT * INTO relation FROM truss.rel_def r WHERE r.rel_type_id=(selected_relation->>'relationshipTypeId')::int AND r.retired_rev IS NULL;
  IF NOT FOUND OR relation.document_id IS DISTINCT FROM selected_relation->'identity'->>'documentId' OR relation.module IS DISTINCT FROM selected_relation->'identity'->>'module'
   OR relation.rel_id IS DISTINCT FROM selected_relation->'identity'->>'relationship' OR relation.lifecycle NOT IN ('independent','owned') OR NOT relation.directed OR relation.composition OR relation.assoc_type_id IS NOT NULL
   OR NOT truss.runtime_can_read(relation.document_id,relation.module)
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'documents') d WHERE d.value->>'documentId'=relation.document_id AND d.value->>'revision'=selected_relation->'identity'->>'revision')
   OR (SELECT count(*) FROM truss.rel_endpoint e WHERE e.rel_type_id=relation.rel_type_id)<>1
   OR NOT EXISTS(SELECT 1 FROM truss.rel_endpoint e WHERE e.rel_type_id=relation.rel_type_id AND e.source_type=(selected_relation->>'sourceTypeId')::int AND e.target_type=(selected_relation->>'targetTypeId')::int)
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE r.value->>'typeId'=selected_relation->>'sourceTypeId')
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE r.value->>'typeId'=selected_relation->>'targetTypeId') THEN
   RAISE EXCEPTION 'accepted authorized relationship mapping required' USING ERRCODE='42501';END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.query_timestamp_instant_key(token text, profile text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE calendar date;whole_seconds bigint;offset_text text;offset_minutes int:=0;fraction text;
BEGIN
 IF profile IS DISTINCT FROM 'umf-rfc3339-exact-instant/1.0.0' THEN
  RAISE EXCEPTION 'selected exact instant profile required' USING ERRCODE='22023';END IF;
 IF token IS NULL THEN RETURN NULL;END IF;
 IF octet_length(token)>1048576 OR token !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?([Zz]|[+-][0-9]{2}:[0-9]{2})$'
  OR substring(token,1,4)::int=0 OR substring(token,12,2)::int>23 OR substring(token,15,2)::int>59 OR substring(token,18,2)::int>59 THEN
  RAISE EXCEPTION 'selected exact instant token required' USING ERRCODE='22023';END IF;
 calendar:=make_date(substring(token,1,4)::int,substring(token,6,2)::int,substring(token,9,2)::int);
 IF lower(right(token,1))<>'z' THEN
  offset_text:=right(token,6);
  IF substring(offset_text,2,2)::int>23 OR substring(offset_text,5,2)::int>59 THEN
   RAISE EXCEPTION 'selected exact instant offset required' USING ERRCODE='22023';END IF;
  offset_minutes:=(substring(offset_text,2,2)::int*60+substring(offset_text,5,2)::int)
   * CASE WHEN left(offset_text,1)='-' THEN -1 ELSE 1 END;
 END IF;
 whole_seconds:=(calendar-DATE '1970-01-01')::bigint*86400
  +substring(token,12,2)::int*3600+substring(token,15,2)::int*60+substring(token,18,2)::int-offset_minutes*60;
 fraction:=CASE WHEN substring(token,20,1)='.' THEN substring(token,21,length(token)-20-CASE WHEN lower(right(token,1))='z' THEN 1 ELSE 6 END) ELSE '' END;
 RETURN jsonb_build_array(whole_seconds::text,rtrim(fraction,'0'));
END;
$function$

CREATE OR REPLACE FUNCTION truss.reached(original_position bytea, maximum_evidence_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET bytea_output TO 'hex'
AS $function$
DECLARE locator jsonb;installation truss.catalog_runtime_installation%ROWTYPE;receipt truss.request_receipt%ROWTYPE;
 attempt truss.runtime_object_attempt%ROWTYPE;payload jsonb;included boolean;observed_receipt record;
BEGIN
 PERFORM truss.runtime_person(false);
 IF pg_is_in_recovery() THEN RETURN convert_to('{"outcome":"unavailable","reason":"epoch_profile"}','UTF8');END IF;
 IF current_setting('transaction_read_only')<>'on' THEN RAISE EXCEPTION 'read-only receipt observation required' USING ERRCODE='0A000';END IF;
 IF original_position IS NULL OR octet_length(original_position) NOT BETWEEN 1 AND 16384 OR maximum_evidence_bytes IS NULL OR maximum_evidence_bytes NOT BETWEEN 1 AND 16777216 THEN
  RETURN convert_to('{"outcome":"unavailable","reason":"resource"}','UTF8');END IF;
 IF (convert_from(original_position,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RETURN convert_to('{"outcome":"unavailable","reason":"invalid_token"}','UTF8');END IF;
 locator:=convert_from(original_position,'UTF8')::jsonb;
 IF locator-ARRAY['interfaceVersion','positionProfile','installationId','sourceEpoch','receiptStorageRowId','writerXid']<>'{}'::jsonb
  OR locator->>'interfaceVersion' IS DISTINCT FROM 'truss-receipt-position/0.1.0'
  OR jsonb_typeof(locator->'receiptStorageRowId') IS DISTINCT FROM 'string' OR locator->>'receiptStorageRowId' !~ '^[1-9][0-9]{0,18}$'
  OR length(locator->>'receiptStorageRowId')=19 AND (locator->>'receiptStorageRowId') COLLATE "C">'9223372036854775807' THEN
  RETURN convert_to('{"outcome":"unavailable","reason":"invalid_token"}','UTF8');END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest
  OR locator->>'installationId' IS DISTINCT FROM installation.installation_id::text OR locator->>'sourceEpoch' IS DISTINCT FROM installation.source_epoch::text
  OR locator->'positionProfile' IS DISTINCT FROM truss.runtime_group_profiles()->'positionProfile' THEN RETURN convert_to('{"outcome":"unavailable","reason":"epoch_profile"}','UTF8');END IF;
 -- Admit original retained scope before any receipt-derived disclosure.
 SELECT * INTO attempt FROM truss.runtime_object_attempt WHERE receipt_id=(locator->>'receiptStorageRowId')::bigint;
 -- A well-formed token whose rows are not in this snapshot is not yet included.
 -- Rollback leaves it that way; the caller supplies its own wait bound.
 IF NOT FOUND THEN RETURN convert_to('{"outcome":"unavailable","reason":"not_yet"}','UTF8');END IF;
 IF attempt.position_bytes IS DISTINCT FROM original_position THEN RETURN convert_to('{"outcome":"unavailable","reason":"observation_integrity"}','UTF8');END IF;
 IF NOT truss.runtime_receipt_can_read(attempt.id) THEN RETURN convert_to('{"outcome":"unavailable","reason":"observation_integrity"}','UTF8');END IF;
 -- Receipt and snapshot come from one original native statement.
 SELECT r AS receipt_row,pg_visible_in_snapshot(r.original_writer_xid,pg_current_snapshot()) AS is_included
  INTO observed_receipt FROM truss.request_receipt r WHERE storage_row_id=attempt.receipt_id;
 IF NOT FOUND THEN RETURN truss.runtime_receipt_refusal(attempt.id,'retention');END IF;
 receipt:=observed_receipt.receipt_row;included:=observed_receipt.is_included;
 IF receipt.payload_state<>'complete' THEN RETURN truss.runtime_receipt_refusal(attempt.id,'retention');END IF;
 IF octet_length(attempt.input_bytes)+octet_length(receipt.original_receipt_bytes)+octet_length(original_position)>maximum_evidence_bytes THEN RETURN truss.runtime_receipt_refusal(attempt.id,'resource');END IF;
 payload:=convert_from(receipt.original_receipt_bytes,'UTF8')::jsonb;
 IF payload->>'profile' IS DISTINCT FROM 'truss-object-group-receipt/0.1' THEN RETURN truss.runtime_receipt_refusal(attempt.id,'epoch_profile');END IF;
 IF payload->>'attemptId' IS DISTINCT FROM attempt.id::text THEN RETURN convert_to('{"outcome":"unavailable","reason":"observation_integrity"}','UTF8');END IF;
 IF NOT attempt.complete OR receipt.original_writer_xid IS NOT DISTINCT FROM pg_current_xact_id_if_assigned()
  OR attempt.receipt_id IS DISTINCT FROM receipt.storage_row_id OR attempt.writer_xid IS DISTINCT FROM receipt.original_writer_xid
  OR receipt.namespace_identity_utf8 IS DISTINCT FROM convert_to(attempt.context->>'authorizedScopeIdentity','UTF8')
  OR receipt.request_id_utf8 IS DISTINCT FROM convert_to(convert_from(attempt.request_bytes,'UTF8')::jsonb->'identity'->>'requestId','UTF8')
  OR receipt.lifecycle_generation<>0 OR receipt.payload_state IS DISTINCT FROM 'complete'
  OR receipt.expired_identity_bytes IS NOT NULL OR receipt.expiry_writer_xid IS NOT NULL OR receipt.expiry_writer_context_bytes IS NOT NULL
  OR attempt.expected_receipt IS NOT NULL AND to_jsonb(receipt) IS DISTINCT FROM attempt.expected_receipt
  OR attempt.expected_receipt IS NULL AND convert_from(attempt.input_bytes,'UTF8')::jsonb->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile()
  OR attempt.position_bytes IS DISTINCT FROM original_position
  OR original_position IS DISTINCT FROM truss.runtime_receipt_position(attempt.context,receipt.storage_row_id,receipt.original_writer_xid)
  OR decode(payload->>'inputBase64','base64') IS DISTINCT FROM attempt.input_bytes
  OR payload->'semantic' IS DISTINCT FROM jsonb_build_object('interfaceVersion','truss-group-result/0.1.0','executedCatalogRevision',payload->'semantic'->>'executedCatalogRevision',
    'layoutProfile',convert_from(attempt.input_bytes,'UTF8')::jsonb->'layoutProfile','mutationProfile',convert_from(attempt.input_bytes,'UTF8')::jsonb->'mutationProfile','results',attempt.results,'aliases',attempt.aliases) THEN
  RETURN convert_to('{"outcome":"unavailable","reason":"observation_integrity"}','UTF8');END IF;
 IF NOT truss.runtime_receipt_can_read(attempt.id) THEN RETURN convert_to('{"outcome":"unavailable","reason":"observation_integrity"}','UTF8');END IF;
 IF included IS NOT TRUE THEN RETURN convert_to('{"outcome":"unavailable","reason":"not_yet"}','UTF8');END IF;
 RETURN convert_to(jsonb_build_object('outcome','available','included',included,'comparisonProfile',attempt.context->'positionProfile')::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.read_feed(selected_consumer text, maximum_facts integer, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE prior bytea;frontier numeric;result bytea;captured_revision int;
BEGIN
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 captured_revision:=(SELECT rev FROM truss.schema_head WHERE id=1);
 -- No xid assignment or row locks in read-only polling.
 frontier:=pg_snapshot_xmin(pg_current_snapshot())::text::numeric;
 SELECT checkpoint_bytes INTO STRICT prior FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer;
 result:=truss.runtime_feed_page(selected_consumer,prior,frontier,maximum_facts,maximum_bytes);
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 IF captured_revision IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1)
 OR prior IS DISTINCT FROM (SELECT checkpoint_bytes FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer) THEN
  RAISE EXCEPTION 'feed context changed' USING ERRCODE='55P03';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.read_history(selection jsonb, cursor_bytes bytea, selected_version bigint, maximum_events integer, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE entity jsonb;frontier xid8;captured_revision int;after_xid xid8:='0';after_seq bigint:=0;cursor jsonb;
 first_event truss.journal%ROWTYPE;items jsonb;item jsonb;event jsonb;result bytea;next_cursor jsonb;record_image jsonb;deleted boolean:=false;
BEGIN
 IF maximum_events IS NULL OR maximum_events NOT BETWEEN 1 AND 65536 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216
 OR selected_version IS NOT NULL AND selected_version<1 THEN RAISE EXCEPTION 'bounded history request required' USING ERRCODE='22023';END IF;
 entity:=truss.runtime_history_entity(selection,expected_release,expected_digest);
 captured_revision:=(SELECT rev FROM truss.schema_head WHERE id=1);frontier:=pg_snapshot_xmin(pg_current_snapshot());
 IF cursor_bytes IS NOT NULL THEN
  IF selected_version IS NOT NULL OR octet_length(cursor_bytes) NOT BETWEEN 1 AND 16384 OR (convert_from(cursor_bytes,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
   RAISE EXCEPTION 'exact page cursor required' USING ERRCODE='22023';END IF;
  cursor:=convert_from(cursor_bytes,'UTF8')::jsonb;
  IF cursor-ARRAY['profile','entity','afterXid','afterSeq']<>'{}'::jsonb OR cursor->>'profile' IS DISTINCT FROM 'truss-native-history-cursor/0.1' OR cursor->'entity' IS DISTINCT FROM entity
  OR jsonb_typeof(cursor->'afterXid') IS DISTINCT FROM 'string' OR jsonb_typeof(cursor->'afterSeq') IS DISTINCT FROM 'string'
  OR cursor->>'afterXid' !~ '^(0|[1-9][0-9]{0,19})$' OR cursor->>'afterSeq' !~ '^(0|[1-9][0-9]{0,18})$' THEN RAISE EXCEPTION 'current scoped history cursor required' USING ERRCODE='22023';END IF;
  after_xid:=(cursor->>'afterXid')::xid8;after_seq:=(cursor->>'afterSeq')::bigint;
 END IF;
 SELECT * INTO first_event FROM truss.journal j WHERE j.entity_kind=(CASE entity->>'kind' WHEN 'object' THEN 'o' ELSE 'e' END)::char(1)
  AND j.entity_id=(entity->>'id')::bigint AND j.entity_type=(entity->>'typeId')::int AND j.xid<frontier
  AND (selected_version IS NOT NULL AND j.ver=selected_version OR selected_version IS NULL AND (j.xid,j.seq)>(after_xid,after_seq)) ORDER BY j.xid,j.seq LIMIT 1;
 IF NOT FOUND THEN
  IF selected_version IS NOT NULL THEN RAISE EXCEPTION 'requested retained history unavailable' USING ERRCODE='P1010';END IF;
  result:=convert_to(jsonb_build_object('outcome','page','events','[]'::jsonb,'safeWatermarkXid',frontier::text)::text,'UTF8');
 ELSE
  items:=truss.runtime_history_group(entity,first_event.xid,first_event.ver,maximum_events,maximum_bytes);
  IF selected_version IS NULL THEN
   IF (first_event.xid,(items->0->>'seq')::bigint)<=(after_xid,after_seq) THEN RAISE EXCEPTION 'complete group cursor required' USING ERRCODE='22023';END IF;
   next_cursor:=jsonb_build_object('profile','truss-native-history-cursor/0.1','entity',entity,'afterXid',first_event.xid::text,'afterSeq',items->-1->>'seq');
   result:=convert_to(jsonb_build_object('outcome','page','events',items,'safeWatermarkXid',frontier::text,
    'cursorBase64',replace(encode(convert_to(next_cursor::text,'UTF8'),'base64'),chr(10),''))::text,'UTF8');
  ELSE
   FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
    event:=convert_from(decode(item->>'contentBase64','base64'),'UTF8')::jsonb;
    IF event->>'operation' IN ('create','metadata','delete') THEN
     IF record_image IS NOT NULL THEN RAISE EXCEPTION 'one complete version witness required' USING ERRCODE='55000';END IF;
     deleted:=event->>'operation'='delete';record_image:=CASE WHEN deleted THEN event->'before' ELSE event->'after' END;
     result:=convert_to(jsonb_build_object('outcome',CASE WHEN deleted THEN 'deleted' ELSE 'record' END,'version',selected_version::text,
      'recordBase64',replace(encode(convert_to(record_image::text,'UTF8'),'base64'),chr(10),''),'event',item)::text,'UTF8');
    END IF;
   END LOOP;
   IF record_image IS NULL THEN RAISE EXCEPTION 'complete retained version witness unavailable' USING ERRCODE='P1010';END IF;
  END IF;
  -- Recheck every original group dependency immediately before publication.
  PERFORM truss.runtime_history_group(entity,first_event.xid,first_event.ver,maximum_events,maximum_bytes);
 END IF;
 PERFORM truss.runtime_history_entity(selection,expected_release,expected_digest);
 IF captured_revision IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1) THEN RAISE EXCEPTION 'history catalog changed' USING ERRCODE='55P03';END IF;
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'whole history output exceeds byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.read_import_load_chunk(selected_invocation uuid, selected_chunk integer, page_limit integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE actor oid;installation truss.catalog_runtime_installation%ROWTYPE;selected truss.runtime_import_load_chunk%ROWTYPE;
 item jsonb;owner jsonb;chunks jsonb;state_value text;all_count int;
 created_count int;skipped_count int;rejected_count int;load_created int;load_skipped int;load_rejected int;
BEGIN
 actor:=truss.runtime_person(false);
 IF selected_invocation IS NULL OR selected_chunk IS NULL OR selected_chunk<0 OR page_limit IS NULL OR page_limit NOT BETWEEN 1 AND 128 THEN
  RAISE EXCEPTION 'bounded import audit page required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'current import audit release required' USING ERRCODE='0A000';END IF;
 SELECT * INTO selected FROM truss.runtime_import_load_chunk c WHERE c.invocation_id=selected_invocation
  AND c.chunk_index=selected_chunk AND c.writer_xid<>pg_current_xact_id();
 -- Hide whether an unqualified invocation/chunk identifier exists.
 IF NOT FOUND THEN RAISE EXCEPTION 'qualified import audit scope unavailable' USING ERRCODE='42501';END IF;
 IF selected.owner_inventory_complete IS NOT TRUE THEN
  RAISE EXCEPTION 'complete original load owner inventory required' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(selected.original_owners)=0 THEN
  -- An admitted empty load has no module scope from which to derive an audit
  -- role, so only an enrolled installation registrar may inspect its metadata.
  PERFORM truss.runtime_person(true);
 END IF;
 FOR owner IN SELECT value FROM jsonb_array_elements(selected.original_owners) LOOP
  IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=owner->>'documentId'
    AND a.module=owner->>'moduleId' AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
   RAISE EXCEPTION 'complete original load audit membership required' USING ERRCODE='42501';END IF;
 END LOOP;
 SELECT count(*),coalesce(jsonb_agg(chunk_index::text ORDER BY chunk_index),'[]'::jsonb) INTO all_count,chunks
  FROM truss.runtime_import_load_chunk WHERE invocation_id=selected_invocation AND writer_xid<>pg_current_xact_id();
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(selected.entries) e GROUP BY e.value->>'inputIndex' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate original load index refused' USING ERRCODE='55000';END IF;
 IF jsonb_array_length(selected.entries)>page_limit THEN RAISE EXCEPTION 'whole load chunk exceeds page limit' USING ERRCODE='54000';END IF;
 state_value:=CASE WHEN all_count=selected.total_chunks AND
  (SELECT count(DISTINCT chunk_index)=selected.total_chunks FROM truss.runtime_import_load_chunk
    WHERE invocation_id=selected_invocation AND writer_xid<>pg_current_xact_id()) THEN 'complete' ELSE 'partial' END;
 SELECT count(*) FILTER(WHERE e.value->>'outcome'='created'),
  count(*) FILTER(WHERE e.value->>'outcome'='skipped'),
  count(*) FILTER(WHERE e.value->>'outcome'='rejected')
  INTO created_count,skipped_count,rejected_count FROM jsonb_array_elements(selected.entries) e(value);
 IF state_value='complete' THEN
  SELECT count(*) FILTER(WHERE e.value->>'outcome'='created'),
   count(*) FILTER(WHERE e.value->>'outcome'='skipped'),
   count(*) FILTER(WHERE e.value->>'outcome'='rejected')
   INTO load_created,load_skipped,load_rejected
   FROM truss.runtime_import_load_chunk c CROSS JOIN LATERAL jsonb_array_elements(c.entries) e(value)
   WHERE c.invocation_id=selected_invocation AND c.writer_xid<>pg_current_xact_id();
 END IF;
 -- Freshly check the full authority union immediately before disclosure.
 FOR owner IN SELECT value FROM jsonb_array_elements(selected.original_owners) LOOP
  IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=owner->>'documentId'
   AND a.module=owner->>'moduleId' AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
   RAISE EXCEPTION 'load audit authority changed before release' USING ERRCODE='42501';END IF;
 END LOOP;
 IF jsonb_array_length(selected.original_owners)=0 THEN
  -- Repeat the registrar-only empty-scope admission at the disclosure edge;
  -- the earlier check may have preceded a same-transaction role revocation.
  PERFORM truss.runtime_person(true);
 END IF;
 PERFORM truss.runtime_person(false);
 RETURN convert_to(jsonb_build_object('outcome','page','invocationId',selected.invocation_id::text,
  'loadId',selected.load_id,'assertedOriginSha256',selected.asserted_origin_sha256,'nativeActor',selected.native_actor::text,
  'observedAt',to_char(selected.audit_observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'createdCount',created_count::text,
  'skippedCount',skipped_count::text,'rejectedCount',rejected_count::text,
  'loadCreatedCount',CASE WHEN state_value='complete' THEN load_created::text ELSE NULL END,
  'loadSkippedCount',CASE WHEN state_value='complete' THEN load_skipped::text ELSE NULL END,
  'loadRejectedCount',CASE WHEN state_value='complete' THEN load_rejected::text ELSE NULL END,
  'inputSha256',selected.input_sha256,'inputCount',selected.input_count::text,
  'totalChunks',selected.total_chunks::text,'observedChunks',chunks,'state',state_value,
  'entries',selected.entries,'nextChunk',CASE WHEN selected.chunk_index+1<selected.total_chunks
    THEN (selected.chunk_index+1)::text ELSE NULL END)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.read_mutation_group_audit(selected_attempt uuid, maximum_events integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE actor oid;installation truss.catalog_runtime_installation%ROWTYPE;
 attempt truss.runtime_object_attempt%ROWTYPE;owner_union jsonb:='[]'::jsonb;
 owner jsonb;transition_row record;physical truss.journal%ROWTYPE;resolved jsonb;
 entry jsonb;event jsonb;original bytea;image jsonb;member jsonb;schema_metadata jsonb;
 property_context jsonb;event_pin text;image_revision int;image_type int;operation_index int;
 event_count int:=0;byte_count int:=0;entries jsonb:='[]'::jsonb;operation_entries jsonb;
 edge_context jsonb;endpoint jsonb;operation_name text;actor_name text;group_action text;
 plan_row record;owner_candidate jsonb;owner_count int;scope_entry jsonb;image_map jsonb;
BEGIN
 actor:=truss.runtime_person(false);
 IF selected_attempt IS NULL OR maximum_events IS NULL OR maximum_events NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'bounded complete mutation group required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest
  OR pg_is_in_recovery() THEN RAISE EXCEPTION 'selected retained mutation audit required' USING ERRCODE='0A000';END IF;
 SELECT * INTO attempt FROM truss.runtime_object_attempt a WHERE a.id=selected_attempt AND a.complete
  AND a.writer_xid<pg_catalog.pg_snapshot_xmin(pg_catalog.pg_current_snapshot());
 IF NOT FOUND THEN RAISE EXCEPTION 'committed complete mutation group required' USING ERRCODE='P0002';END IF;
 IF attempt.context->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
  RAISE EXCEPTION 'retained mutation audit profile unsupported' USING ERRCODE='0A000';END IF;
 IF attempt.next_index<1 OR attempt.result_count<>attempt.next_index
  OR (SELECT count(*) FROM truss.runtime_owned_operation o WHERE o.attempt_id=attempt.id
      AND o.writer_xid=attempt.writer_xid AND o.result IS NOT NULL)<>attempt.next_index THEN
  RAISE EXCEPTION 'complete retained operation census required' USING ERRCODE='P1010';END IF;
 IF octet_length(attempt.input_bytes)>1048576 THEN RAISE EXCEPTION 'retained mutation input too large' USING ERRCODE='54000';END IF;
 -- Preserve the actor captured by the native attempt even if its login role
 -- was later renamed or removed. No role-name lookup is part of audit identity.
 SELECT min(p.plan->>'actorName'),count(DISTINCT p.plan->>'actorName') INTO actor_name,owner_count
  FROM truss.runtime_owned_operation p WHERE p.attempt_id=attempt.id AND p.writer_xid=attempt.writer_xid;
 IF actor_name IS NULL OR owner_count<>1 THEN RAISE EXCEPTION 'retained native actor name unavailable' USING ERRCODE='P1010';END IF;
 IF jsonb_typeof(attempt.context->'originalAssertedOrigin'->'entries')='array'
  AND (SELECT count(*)=1 FROM jsonb_array_elements(attempt.context->'originalAssertedOrigin'->'entries') e
       WHERE e.value->>'key'='x-action')
  AND (SELECT count(*)=1 FROM jsonb_array_elements(attempt.context->'originalAssertedOrigin'->'entries') e
       WHERE e.value->>'key'='x-action' AND e.value->'value'->>'kind'='string'
        AND jsonb_typeof(e.value->'value'->'text')='string'
        AND octet_length(e.value->'value'->>'text') BETWEEN 1 AND 4096) THEN
  SELECT e.value->'value'->>'text' INTO group_action
   FROM jsonb_array_elements(attempt.context->'originalAssertedOrigin'->'entries') e WHERE e.value->>'key'='x-action';
 END IF;

 -- Retained plans cover unchanged operations that have no journal row. These
 -- plans are immutable witnesses; every owner-shaped item is conservatively
 -- included, and all exact property-reader dependencies are added from the
 -- image's own retained catalog revision.
 FOR plan_row IN SELECT p.operation_index,p.plan,p.result FROM truss.runtime_owned_operation p
  WHERE p.attempt_id=attempt.id AND p.writer_xid=attempt.writer_xid ORDER BY p.operation_index LOOP
  IF plan_row.operation_index<0 OR plan_row.operation_index>=attempt.next_index
   OR plan_row.plan->>'profile' IS DISTINCT FROM 'truss-owned-operation-plan/0.2'
   OR plan_row.plan->'operationIndex' IS DISTINCT FROM to_jsonb(plan_row.operation_index)
   OR plan_row.plan->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile()
   OR plan_row.result IS NULL THEN RAISE EXCEPTION 'complete immutable operation plan required' USING ERRCODE='P1010';END IF;
  owner_count:=0;
  FOR owner_candidate IN SELECT jsonb_path_query(plan_row.plan,
   '$.** ? (@.documentId.type() == "string" && @.moduleId.type() == "string")') LOOP
   IF octet_length(owner_candidate->>'documentId') NOT BETWEEN 1 AND 4096
    OR octet_length(owner_candidate->>'moduleId') NOT BETWEEN 1 AND 4096 THEN
    RAISE EXCEPTION 'bounded operation-plan owner required' USING ERRCODE='P1010';END IF;
   owner_union:=owner_union||jsonb_build_array(jsonb_build_object(
    'documentId',owner_candidate->>'documentId','moduleId',owner_candidate->>'moduleId'));
   owner_count:=owner_count+1;
  END LOOP;
  IF owner_count=0 THEN RAISE EXCEPTION 'complete operation-plan owner scope required' USING ERRCODE='P1010';END IF;
  FOR image_map IN SELECT value FROM (VALUES(plan_row.plan->'beforeNodes'),(plan_row.plan->'afterNodes')) x(value)
   WHERE jsonb_typeof(value)='object' LOOP
   FOR image IN SELECT n.value->'image' FROM jsonb_each(image_map) n(key,value)
    WHERE jsonb_typeof(n.value->'image')='object' LOOP
    image_revision:=(image->>'rev')::int;image_type:=(image->>'type_id')::int;
    IF image_revision IS NULL OR image_type IS NULL THEN RAISE EXCEPTION 'retained image catalog coordinate required' USING ERRCODE='P1010';END IF;
    SELECT s.metadata INTO STRICT schema_metadata FROM truss.runtime_type_schema s
     WHERE s.rev=image_revision AND s.type_id=image_type;
    IF jsonb_typeof(schema_metadata->'propertyAccess') IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'retained type property scope unavailable' USING ERRCODE='P1010';END IF;
    FOR scope_entry IN SELECT value FROM jsonb_each(schema_metadata->'propertyAccess') LOOP
     IF (scope_entry->>'itemsValid')::boolean IS NOT TRUE OR jsonb_typeof(scope_entry->'readers') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'retained property readers unavailable' USING ERRCODE='P1010';END IF;
     FOR owner_candidate IN SELECT value FROM jsonb_array_elements(scope_entry->'readers') LOOP
      IF jsonb_typeof(owner_candidate) IS DISTINCT FROM 'object'
       OR jsonb_typeof(owner_candidate->'documentId') IS DISTINCT FROM 'string'
       OR jsonb_typeof(owner_candidate->'moduleId') IS DISTINCT FROM 'string' THEN
       RAISE EXCEPTION 'retained property owner unavailable' USING ERRCODE='P1010';END IF;
      owner_union:=owner_union||jsonb_build_array(owner_candidate);
     END LOOP;
    END LOOP;
   END LOOP;
  END LOOP;
 END LOOP;

 FOR transition_row IN
  SELECT t.operation_index,t.writer_xid,'object'::text AS kind,t.object_id AS entity_id,
   t.type_id AS entity_type,t.journal
   FROM truss.runtime_object_transition t WHERE t.attempt_id=attempt.id AND t.writer_xid=attempt.writer_xid
  UNION ALL
  SELECT t.operation_index,t.writer_xid,'edge'::text,t.edge_id,t.rel_type_id,t.journal
   FROM truss.runtime_edge_transition t WHERE t.attempt_id=attempt.id AND t.writer_xid=attempt.writer_xid
  ORDER BY operation_index,kind,entity_id
 LOOP
  event_count:=event_count+1;
  IF event_count>maximum_events THEN RAISE EXCEPTION 'whole mutation group exceeds audit event limit' USING ERRCODE='54000';END IF;
  IF transition_row.kind='edge' THEN
   SELECT t.endpoint_ownership INTO edge_context FROM truss.runtime_edge_transition t
    WHERE t.attempt_id=attempt.id AND t.operation_index=transition_row.operation_index
     AND t.writer_xid=attempt.writer_xid AND t.edge_id=transition_row.entity_id AND t.rel_type_id=transition_row.entity_type;
   IF edge_context IS NULL OR
    (jsonb_typeof(edge_context->'before') IS DISTINCT FROM 'object' AND jsonb_typeof(edge_context->'before') IS DISTINCT FROM 'null') OR
    (jsonb_typeof(edge_context->'after') IS DISTINCT FROM 'object' AND jsonb_typeof(edge_context->'after') IS DISTINCT FROM 'null') THEN
    RAISE EXCEPTION 'retained endpoint ownership unavailable' USING ERRCODE='P1010';END IF;
   FOR endpoint IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
     edge_context->'before'->'source',edge_context->'before'->'target',
     edge_context->'after'->'source',edge_context->'after'->'target')) WHERE value<>'null'::jsonb LOOP
    owner:=endpoint->'identity'->'owner';
    IF jsonb_typeof(owner) IS DISTINCT FROM 'object' OR owner-ARRAY['documentId','moduleId']<>'{}'::jsonb THEN
     RAISE EXCEPTION 'retained endpoint identity owner unavailable' USING ERRCODE='P1010';END IF;
    owner_union:=owner_union||jsonb_build_array(owner);
    IF endpoint->'ownership'->>'state'='owned' THEN
     owner:=endpoint->'ownership'->'root'->'owner';
     IF jsonb_typeof(owner) IS DISTINCT FROM 'object' OR owner-ARRAY['documentId','moduleId']<>'{}'::jsonb THEN
      RAISE EXCEPTION 'retained endpoint root owner unavailable' USING ERRCODE='P1010';END IF;
     owner_union:=owner_union||jsonb_build_array(owner);
    ELSIF endpoint->'ownership'->>'state' IS DISTINCT FROM 'rootless' THEN
     RAISE EXCEPTION 'retained endpoint ownership state unavailable' USING ERRCODE='P1010';END IF;
   END LOOP;
  END IF;
  IF jsonb_typeof(transition_row.journal) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'retained group journal unavailable' USING ERRCODE='P1010';END IF;
  resolved:=truss.runtime_owned_journal_materialize(transition_row.journal);
  FOR entry IN SELECT value FROM jsonb_array_elements(resolved) LOOP
   IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry-ARRAY['seq','at','xid','entity_kind','entity_id','entity_type','ver','op','prop_id','old_value','new_value','rev','origin']<>'{}'::jsonb THEN
    RAISE EXCEPTION 'closed retained journal row required' USING ERRCODE='55000';END IF;
   physical:=jsonb_populate_record(NULL::truss.journal,entry);
   byte_count:=byte_count+octet_length(physical.new_value::text)+octet_length(physical.origin::text);
   IF byte_count>4194304 THEN RAISE EXCEPTION 'whole mutation group audit exceeds byte limit' USING ERRCODE='54000';END IF;
   IF physical.xid IS DISTINCT FROM attempt.writer_xid OR physical.entity_id IS DISTINCT FROM transition_row.entity_id
    OR physical.entity_type IS DISTINCT FROM transition_row.entity_type
    OR physical.entity_kind IS DISTINCT FROM (CASE WHEN transition_row.kind='object' THEN 'o'::char(1) ELSE 'e'::char(1) END)
    OR physical.new_value->>'component' IS DISTINCT FROM 'event' THEN
    RAISE EXCEPTION 'retained journal transition correspondence required' USING ERRCODE='55000';END IF;
   BEGIN
    original:=decode(physical.new_value->>'bytesBase64','base64');
    IF physical.new_value IS DISTINCT FROM truss.runtime_exact_wrapper('event',original)
     OR (convert_from(original,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
     RAISE EXCEPTION 'exact retained event required' USING ERRCODE='55000';END IF;
    event:=convert_from(original,'UTF8')::jsonb;
   EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'retained event unavailable' USING ERRCODE='P1010';END;
   IF event->>'interfaceVersion' IS DISTINCT FROM 'truss-history-event/0.2.0-proposal'
   OR (event->>'historyProfile' IN ('truss-native-scalar-create/0.2','truss-native-owned-create/0.1',
     'truss-native-scalar-mutation/0.1','truss-native-owned-mutation/0.1',
     'truss-native-edge-mutation/0.1','truss-native-owned-edge-mutation/0.1')) IS NOT TRUE
    OR event->>'sourceEpoch' IS DISTINCT FROM installation.source_epoch::text
    OR event->>'xid' IS DISTINCT FROM physical.xid::text OR event->>'seq' IS DISTINCT FROM physical.seq::text
    OR event->>'eventVersion' IS DISTINCT FROM physical.ver::text
    OR event->>'eventCatalogRevision' IS DISTINCT FROM physical.rev::text
    OR event->'identity'->>'id' IS DISTINCT FROM physical.entity_id::text
    OR event->'identity'->>'typeId' IS DISTINCT FROM physical.entity_type::text
    OR physical.op IS DISTINCT FROM (CASE event->>'operation' WHEN 'property' THEN 'update' ELSE event->>'operation' END)
    OR physical.prop_id IS DISTINCT FROM (event->>'propertyId')::int
    OR physical.origin IS DISTINCT FROM truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8')) THEN
    RAISE EXCEPTION 'retained event provenance unavailable' USING ERRCODE='55000';END IF;
   IF transition_row.kind='object' THEN
    SELECT s.metadata->>'typePin' INTO event_pin FROM truss.runtime_type_schema s
     WHERE s.rev=physical.rev AND s.type_id=physical.entity_type;
   ELSE event_pin:=truss.runtime_relationship_pin(physical.entity_type,physical.rev);END IF;
   IF event_pin IS NULL OR event->'identity'->>'definitionPin' IS DISTINCT FROM event_pin THEN
    RAISE EXCEPTION 'retained event definition pin unavailable' USING ERRCODE='P1010';END IF;
   owner:=event->'identity'->'owner';
   IF jsonb_typeof(owner) IS DISTINCT FROM 'object' OR owner-ARRAY['documentId','moduleId']<>'{}'::jsonb
    OR jsonb_typeof(owner->'documentId') IS DISTINCT FROM 'string' OR jsonb_typeof(owner->'moduleId') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'complete retained entity owner required' USING ERRCODE='P1010';END IF;
   owner_union:=owner_union||jsonb_build_array(owner);
   IF event->>'operation' IN ('create','metadata','delete') THEN
    FOR image IN SELECT value FROM jsonb_array_elements(jsonb_build_array(event->'before',event->'after'))
     WHERE value IS NOT NULL AND value<>'null'::jsonb LOOP
     image_revision:=(image->>'catalogRevision')::int;image_type:=(image->'identity'->>'typeId')::int;
     owner:=image->'identity'->'owner';
     IF jsonb_typeof(owner) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'retained image owner unavailable' USING ERRCODE='P1010';END IF;
     owner_union:=owner_union||jsonb_build_array(owner);
     IF image->'ownership'->>'state'='owned' THEN
      owner:=image->'ownership'->'root'->'owner';
      IF jsonb_typeof(owner) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'retained root owner unavailable' USING ERRCODE='P1010';END IF;
      owner_union:=owner_union||jsonb_build_array(owner);
     END IF;
     IF transition_row.kind='edge' THEN
      FOR endpoint IN SELECT value FROM jsonb_array_elements(jsonb_build_array(image->'source',image->'target')) LOOP
       owner:=endpoint->'owner';
       IF jsonb_typeof(owner) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'retained edge endpoint owner unavailable' USING ERRCODE='P1010';END IF;
       owner_union:=owner_union||jsonb_build_array(owner);
      END LOOP;
     END IF;
     FOR member IN SELECT value FROM jsonb_array_elements(image->'properties') LOOP
      SELECT s.metadata INTO STRICT schema_metadata FROM truss.runtime_type_schema s WHERE s.rev=image_revision AND s.type_id=image_type;
      property_context:=schema_metadata->'propertyAccess'->(member->>'propertyId');
      event_pin:=schema_metadata->'propertyPins'->>(member->>'propertyId');
      IF event_pin IS DISTINCT FROM member->>'definitionPin' OR property_context IS NULL
       OR (property_context->>'itemsValid')::boolean IS NOT TRUE OR jsonb_typeof(property_context->'readers') IS DISTINCT FROM 'array' THEN
       RAISE EXCEPTION 'retained property scope unavailable' USING ERRCODE='P1010';END IF;
      FOR owner IN SELECT value FROM jsonb_array_elements(property_context->'readers') LOOP
       owner_union:=owner_union||jsonb_build_array(owner);
      END LOOP;
     END LOOP;
    END LOOP;
   ELSIF event->>'operation' IN ('property','rebind') THEN
    SELECT s.metadata INTO STRICT schema_metadata FROM truss.runtime_type_schema s
     WHERE s.rev=physical.rev AND s.type_id=physical.entity_type;
    event_pin:=CASE WHEN event->>'operation'='rebind' THEN event->>'afterDefinitionPin' ELSE event->>'definitionPin' END;
    property_context:=schema_metadata->'propertyAccess'->physical.prop_id::text;
    IF schema_metadata->'propertyPins'->>physical.prop_id::text IS DISTINCT FROM event_pin OR property_context IS NULL
     OR (property_context->>'itemsValid')::boolean IS NOT TRUE OR jsonb_typeof(property_context->'readers') IS DISTINCT FROM 'array' THEN
     RAISE EXCEPTION 'retained property delta scope unavailable' USING ERRCODE='P1010';END IF;
    FOR owner IN SELECT value FROM jsonb_array_elements(property_context->'readers') LOOP owner_union:=owner_union||jsonb_build_array(owner);END LOOP;
   ELSE RAISE EXCEPTION 'retained operation profile unsupported' USING ERRCODE='0A000';END IF;
   entries:=entries||jsonb_build_array(jsonb_build_object('operationIndex',transition_row.operation_index::text,
    'entityKind',transition_row.kind,'entityId',transition_row.entity_id::text,'entityType',transition_row.entity_type::text,
    'operation',event->>'operation','observedAt',to_char(physical.at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  END LOOP;
 END LOOP;
 -- A completed unchanged operation has no event row. Its sealed plan/result
 -- is still a retained native observation, with a timestamp captured when the
 -- attempt row was created. Never manufacture an audit time at read time.
 FOR plan_row IN SELECT p.operation_index,p.plan,p.result FROM truss.runtime_owned_operation p
  WHERE p.attempt_id=attempt.id AND p.writer_xid=attempt.writer_xid ORDER BY p.operation_index LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(entries) e
   WHERE e.value->>'operationIndex'=plan_row.operation_index::text) THEN
   IF attempt.audit_observed_at IS NULL THEN RAISE EXCEPTION 'no-op attempt observation unavailable' USING ERRCODE='P1010';END IF;
   operation_name:=plan_row.result->>'operation';
   image:=plan_row.result->'identity';
   IF operation_name NOT IN ('create_object','update_object','delete_object','create_edge','update_edge','delete_edge')
    OR jsonb_typeof(image) IS DISTINCT FROM 'object'
    OR jsonb_typeof(image->'id') IS DISTINCT FROM 'string'
    OR jsonb_typeof(image->'typeId') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'no-op retained identity unavailable' USING ERRCODE='P1010';END IF;
   entries:=entries||jsonb_build_array(jsonb_build_object('operationIndex',plan_row.operation_index::text,
    'entityKind',CASE WHEN operation_name LIKE '%_edge' THEN 'edge' ELSE 'object' END,
    'entityId',image->>'id','entityType',image->>'typeId','operation',operation_name,
    'observedAt',to_char(attempt.audit_observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  END IF;
 END LOOP;
 IF jsonb_array_length(entries)=0 THEN RAISE EXCEPTION 'retained group has no supported operation evidence' USING ERRCODE='P1010';END IF;
 IF jsonb_array_length(entries)>maximum_events THEN RAISE EXCEPTION 'whole group exceeds audit page limit' USING ERRCODE='54000';END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'documentId',value->>'moduleId'),'[]'::jsonb) INTO owner_union
  FROM (SELECT DISTINCT value FROM jsonb_array_elements(owner_union)) owners;
 IF jsonb_array_length(owner_union)>4096 THEN RAISE EXCEPTION 'complete audit owner union exceeds limit' USING ERRCODE='54000';END IF;
 FOR owner IN SELECT value FROM jsonb_array_elements(owner_union) LOOP
  IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=owner->>'documentId'
   AND a.module=owner->>'moduleId' AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
   RAISE EXCEPTION 'complete mutation group audit membership required' USING ERRCODE='42501';END IF;
 END LOOP;
 -- Recheck every original owner after constructing the whole-group projection.
 FOR owner IN SELECT value FROM jsonb_array_elements(owner_union) LOOP
  IF NOT EXISTS(SELECT 1 FROM truss.runtime_import_audit_access a WHERE a.document_id=owner->>'documentId'
   AND a.module=owner->>'moduleId' AND truss.runtime_audit_role_member(actor,a.auditor_oid)) THEN
   RAISE EXCEPTION 'mutation group audit authority changed before release' USING ERRCODE='42501';END IF;
 END LOOP;
 PERFORM truss.runtime_person(false);
 RETURN convert_to(jsonb_build_object('outcome','page','attemptId',attempt.id::text,
  'nativeActorOid',attempt.actor_oid::text,'nativeActorName',actor_name,'assertedAction',group_action,'writerXid',attempt.writer_xid::text,
  'observedAt',to_char(attempt.audit_observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'ownerScopes',owner_union,
  'operationCount',attempt.next_index::text,'eventCount',jsonb_array_length(entries)::text,'entries',entries)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.reader_catalog(maximum_count integer, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;captured_revision int;modules jsonb:='[]';owner record;module jsonb;encoded bytea;definition_count int:=0;dependency record;
BEGIN
 PERFORM truss.runtime_person(false);
 IF maximum_count IS NULL OR maximum_count NOT BETWEEN 1 AND 65536 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN RAISE EXCEPTION 'bounded catalog limits required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'selected runtime required' USING ERRCODE='0A000';END IF;
 IF current_setting('transaction_read_only')='on' THEN
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 ELSE
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 END IF;
 IF captured_revision<1 THEN RAISE EXCEPTION 'accepted catalog required' USING ERRCODE='0A000';END IF;
 FOR owner IN SELECT d.doc_id,d.rev AS source_catalog_revision,d.doc_revision,d.content_sha256,m.value->>'id' AS module_id
  FROM truss.schema_doc d CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m(value)
  WHERE d.rev<=captured_revision AND d.rev=(SELECT max(latest.rev) FROM truss.schema_doc latest WHERE latest.doc_id=d.doc_id AND latest.rev<=captured_revision) ORDER BY d.doc_id COLLATE "C",m.value->>'id' COLLATE "C" LOOP
  IF NOT truss.runtime_can_read(owner.doc_id,owner.module_id) THEN CONTINUE;END IF;
  module:=jsonb_build_object('documentId',owner.doc_id,'moduleId',owner.module_id,'documentRevision',owner.doc_revision,'documentSha256',owner.content_sha256,'sourceCatalogRevision',owner.source_catalog_revision,
   'types',(SELECT coalesce(jsonb_agg(jsonb_build_object('typeId',t.type_id,'recordId',t.element,'kind',t.kind,'provisional',t.provisional) ORDER BY t.type_id),'[]') FROM truss.type_def t WHERE t.document_id=owner.doc_id AND t.module=owner.module_id AND t.retired_rev IS NULL),
   'properties',(SELECT coalesce(jsonb_agg(jsonb_build_object('propertyId',p.prop_id,'typeId',p.type_id,'fieldId',p.element,'name',p.name,'scalarType',p.scalar_type,'nullability',p.nullability,'cardinality',p.cardinality,'itemDefinition',p.item-'declaration') ORDER BY p.prop_id),'[]') FROM truss.prop_def p JOIN truss.type_def t USING(type_id) WHERE t.document_id=owner.doc_id AND t.module=owner.module_id AND t.retired_rev IS NULL AND p.retired_rev IS NULL AND truss.runtime_can_read(t.document_id,p.declaration_module) AND (p.cardinality NOT IN ('array','map') OR truss.runtime_item_chain_readable(p.item))),
   'keys',(SELECT coalesce(jsonb_agg(jsonb_build_object('typeId',k.type_id,'keyId',k.key_id,'keyNumber',k.key_num,'propertyIds',k.prop_ids,'primary',k.is_primary) ORDER BY k.type_id,k.key_num),'[]') FROM truss.key_def k JOIN truss.type_def t USING(type_id) WHERE t.document_id=owner.doc_id AND t.module=owner.module_id AND t.retired_rev IS NULL AND k.retired_rev IS NULL AND NOT EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.prop_id=ANY(k.prop_ids) AND NOT truss.runtime_can_read(t.document_id,p.declaration_module))),
   'relationships',(SELECT coalesce(jsonb_agg(jsonb_build_object('relationshipId',r.rel_type_id,'authoredId',r.rel_id,'name',r.name,'sourceMin',r.source_min,'sourceMax',r.source_max,'targetMin',r.target_min,'targetMax',r.target_max,'directed',r.directed,
      'endpoints',(SELECT jsonb_agg(jsonb_build_object('sourceType',e.source_type,'targetType',e.target_type) ORDER BY e.source_type,e.target_type) FROM truss.rel_endpoint e WHERE e.rel_type_id=r.rel_type_id)) ORDER BY r.rel_type_id),'[]') FROM truss.rel_def r
    WHERE r.document_id=owner.doc_id AND r.module=owner.module_id AND r.retired_rev IS NULL
    AND NOT EXISTS(SELECT 1 FROM truss.rel_endpoint e JOIN truss.type_def s ON s.type_id=e.source_type JOIN truss.type_def t ON t.type_id=e.target_type WHERE e.rel_type_id=r.rel_type_id AND (NOT truss.runtime_can_read(s.document_id,s.module) OR NOT truss.runtime_can_read(t.document_id,t.module)))
    AND NOT EXISTS(SELECT 1 FROM truss.rel_endpoint e JOIN truss.key_def k ON k.type_id=e.target_type AND k.key_id=r.target_key JOIN truss.type_def t ON t.type_id=k.type_id JOIN truss.prop_def p ON p.prop_id=ANY(k.prop_ids) WHERE e.rel_type_id=r.rel_type_id AND NOT truss.runtime_can_read(t.document_id,p.declaration_module))
    AND (r.assoc_type_id IS NULL OR EXISTS(SELECT 1 FROM truss.type_def a WHERE a.type_id=r.assoc_type_id AND truss.runtime_can_read(a.document_id,a.module)))));
  definition_count:=definition_count+1+jsonb_array_length(module->'types')+jsonb_array_length(module->'properties')+jsonb_array_length(module->'keys')+jsonb_array_length(module->'relationships');
  IF definition_count>maximum_count THEN RAISE EXCEPTION 'catalog count limit' USING ERRCODE='54000';END IF;
  modules:=modules||jsonb_build_array(module);
  IF octet_length(modules::text)>maximum_bytes THEN RAISE EXCEPTION 'catalog byte limit' USING ERRCODE='54000';END IF;
 END LOOP;
 -- Membership may have changed while the projection was assembled.
 FOR module IN SELECT value FROM jsonb_array_elements(modules) LOOP
  IF NOT truss.runtime_can_read(module->>'documentId',module->>'moduleId') THEN RAISE EXCEPTION 'current reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 -- Recheck every dependency actually used in the buffered projection, even if
 -- that owner was revoked before its own module was visited and emitted.
 FOR dependency IN
  SELECT DISTINCT document_id,module_id FROM (
   SELECT t.document_id,p.declaration_module AS module_id
    FROM jsonb_array_elements(modules) m CROSS JOIN LATERAL jsonb_array_elements(m.value->'properties') f
    JOIN truss.prop_def p ON p.prop_id=(f.value->>'propertyId')::int JOIN truss.type_def t USING(type_id)
   UNION
   SELECT node.value->>'documentId',node.value->'reference'->>'module'
    FROM jsonb_array_elements(modules) m CROSS JOIN LATERAL jsonb_array_elements(m.value->'properties') f
    JOIN truss.prop_def p ON p.prop_id=(f.value->>'propertyId')::int
    CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(p.item)||coalesce(p.item->'descendants','[]'::jsonb)) node
    WHERE p.cardinality IN ('array','map')
   UNION
   SELECT t.document_id,p.declaration_module
    FROM jsonb_array_elements(modules) m CROSS JOIN LATERAL jsonb_array_elements(m.value->'keys') k
    JOIN truss.type_def t ON t.type_id=(k.value->>'typeId')::int
    CROSS JOIN LATERAL jsonb_array_elements_text(k.value->'propertyIds') f JOIN truss.prop_def p ON p.prop_id=f.value::int
   UNION
   SELECT t.document_id,t.module
    FROM jsonb_array_elements(modules) m CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') r
    JOIN truss.rel_endpoint e ON e.rel_type_id=(r.value->>'relationshipId')::int
    JOIN truss.type_def t ON t.type_id IN(e.source_type,e.target_type)
   UNION
   SELECT t.document_id,t.module
    FROM jsonb_array_elements(modules) m CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') r
    JOIN truss.rel_def d ON d.rel_type_id=(r.value->>'relationshipId')::int JOIN truss.type_def t ON t.type_id=d.assoc_type_id
   UNION
   SELECT t.document_id,p.declaration_module
    FROM jsonb_array_elements(modules) m CROSS JOIN LATERAL jsonb_array_elements(m.value->'relationships') r
    JOIN truss.rel_def d ON d.rel_type_id=(r.value->>'relationshipId')::int JOIN truss.rel_endpoint e ON e.rel_type_id=d.rel_type_id
    JOIN truss.key_def k ON k.type_id=e.target_type AND k.key_id=d.target_key
    JOIN truss.type_def t ON t.type_id=k.type_id JOIN truss.prop_def p ON p.prop_id=ANY(k.prop_ids)
  ) used_owners LOOP
  IF NOT truss.runtime_can_read(dependency.document_id,dependency.module_id) THEN RAISE EXCEPTION 'current dependency reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 PERFORM truss.runtime_person(false);
 encoded:=convert_to(jsonb_build_object('catalogRevision',captured_revision,'layoutProfile',installation.layout_profile,'modules',modules)::text,'UTF8');
 IF octet_length(encoded)>maximum_bytes THEN RAISE EXCEPTION 'catalog byte limit' USING ERRCODE='54000';END IF;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN
  RAISE EXCEPTION 'catalog changed during reader observation' USING ERRCODE='55P03';END IF;
 RETURN encoded;
END;
$function$

CREATE OR REPLACE FUNCTION truss.reader_catalog_if_changed(maximum_count integer, maximum_bytes integer, expected_release text, expected_digest text, validator text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;captured_revision int;actor oid;captured_actor oid;
 effective_policies jsonb;captured_policies jsonb;native_context jsonb;captured_native_context jsonb;
 scope_digest bytea;current_validator text;catalog_bytes bytea;response_bytes bytea;
BEGIN
 actor:=truss.runtime_person(false);
 IF maximum_count IS NULL OR maximum_count NOT BETWEEN 1 AND 65536 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216
  OR validator IS NOT NULL AND (octet_length(validator) NOT BETWEEN 1 AND 4096 OR validator !~ '^[0-9a-f]{64}$') THEN
  RAISE EXCEPTION 'bounded catalog validator request required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected runtime required' USING ERRCODE='0A000';END IF;
 IF current_setting('transaction_read_only')='on' THEN
  SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 ELSE
  SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 END IF;
 IF captured_revision<1 THEN RAISE EXCEPTION 'accepted catalog required' USING ERRCODE='0A000';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_array(p.document_id,p.module,truss.runtime_can_read_qualified(p.document_id,p.module,actor))
   ORDER BY p.document_id COLLATE "C",p.module COLLATE "C"),'[]'::jsonb)
 INTO effective_policies FROM truss.module_access p;
 WITH RECURSIVE memberships(role_oid) AS (
  SELECT actor UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid
 ), role_states(active_oid,privilege_oid) AS (
  SELECT actor,actor UNION
  SELECT CASE WHEN m.admin_option OR (m.set_option AND s.active_oid=s.privilege_oid) THEN m.roleid ELSE s.active_oid END,m.roleid
   FROM pg_auth_members m JOIN role_states s ON m.member=s.privilege_oid
   WHERE m.inherit_option OR m.admin_option OR (m.set_option AND s.active_oid=s.privilege_oid)
 ) SELECT jsonb_build_object(
  'effectiveMemberships',(SELECT coalesce(jsonb_agg(role_oid::text ORDER BY role_oid),'[]'::jsonb) FROM memberships),
  'roleStates',(SELECT coalesce(jsonb_agg(jsonb_build_array(active_oid::text,privilege_oid::text) ORDER BY active_oid,privilege_oid),'[]'::jsonb) FROM role_states),
  'nativeRoleFlags',(SELECT coalesce(jsonb_agg(jsonb_build_array(r.oid::text,r.rolname,r.rolcanlogin,r.rolsuper,r.rolcreaterole,r.rolcreatedb,r.rolreplication,r.rolbypassrls,r.rolinherit)
    ORDER BY r.oid),'[]'::jsonb) FROM pg_roles r WHERE r.oid IN(SELECT role_oid FROM memberships) OR r.oid IN(installation.owner_oid,installation.registrar_oid)),
  'transactionIsolation',current_setting('transaction_isolation'),
  'transactionReadOnly',current_setting('transaction_read_only'),
  'roleSetting',current_setting('role'),
  'currentUser',(SELECT oid::text FROM pg_roles WHERE rolname=current_user),
  'serverVersion',current_setting('server_version_num')) INTO native_context;
 PERFORM truss.runtime_person(false);
 captured_actor:=actor;captured_policies:=effective_policies;captured_native_context:=native_context;
 scope_digest:=sha256(convert_to(jsonb_build_object('installation',installation.installation_id::text,
   'release',installation.release_id,'releaseSha256',installation.release_sha256,'layoutProfile',installation.layout_profile,'revision',captured_revision,
   'actor',actor::text,'maximumCount',maximum_count,'maximumBytes',maximum_bytes,
   'effectivePolicies',effective_policies,'nativeContext',native_context)::text,'UTF8'));
 SELECT sha256(s.secret||scope_digest) INTO STRICT scope_digest FROM truss.reader_catalog_validator_secret s;
 current_validator:=encode(scope_digest,'hex');
 IF validator IS NOT NULL AND validator=current_validator THEN
  response_bytes:=convert_to(jsonb_build_object('outcome','unchanged','validator',current_validator)::text,'UTF8');
 ELSE
  catalog_bytes:=truss.reader_catalog(maximum_count,maximum_bytes,expected_release,expected_digest);
  response_bytes:=convert_to(jsonb_build_object('outcome','snapshot','validator',current_validator,
    'catalog',convert_from(catalog_bytes,'UTF8')::jsonb)::text,'UTF8');
  IF octet_length(response_bytes)>maximum_bytes THEN RAISE EXCEPTION 'conditional catalog byte limit' USING ERRCODE='54000';END IF;
 END IF;
 -- Re-read the whole authority basis immediately before either response. A
 -- valid person identity alone is insufficient after a membership or policy
 -- change while the projection was being assembled.
 actor:=truss.runtime_person(false);
 SELECT coalesce(jsonb_agg(jsonb_build_array(p.document_id,p.module,truss.runtime_can_read_qualified(p.document_id,p.module,actor))
   ORDER BY p.document_id COLLATE "C",p.module COLLATE "C"),'[]'::jsonb)
 INTO effective_policies FROM truss.module_access p;
 WITH RECURSIVE memberships(role_oid) AS (
  SELECT actor UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid
 ), role_states(active_oid,privilege_oid) AS (
  SELECT actor,actor UNION
  SELECT CASE WHEN m.admin_option OR (m.set_option AND s.active_oid=s.privilege_oid) THEN m.roleid ELSE s.active_oid END,m.roleid
   FROM pg_auth_members m JOIN role_states s ON m.member=s.privilege_oid
   WHERE m.inherit_option OR m.admin_option OR (m.set_option AND s.active_oid=s.privilege_oid)
 ) SELECT jsonb_build_object(
  'effectiveMemberships',(SELECT coalesce(jsonb_agg(role_oid::text ORDER BY role_oid),'[]'::jsonb) FROM memberships),
  'roleStates',(SELECT coalesce(jsonb_agg(jsonb_build_array(active_oid::text,privilege_oid::text) ORDER BY active_oid,privilege_oid),'[]'::jsonb) FROM role_states),
  'nativeRoleFlags',(SELECT coalesce(jsonb_agg(jsonb_build_array(r.oid::text,r.rolname,r.rolcanlogin,r.rolsuper,r.rolcreaterole,r.rolcreatedb,r.rolreplication,r.rolbypassrls,r.rolinherit)
    ORDER BY r.oid),'[]'::jsonb) FROM pg_roles r WHERE r.oid IN(SELECT role_oid FROM memberships) OR r.oid IN(installation.owner_oid,installation.registrar_oid)),
  'transactionIsolation',current_setting('transaction_isolation'),
  'transactionReadOnly',current_setting('transaction_read_only'),
  'roleSetting',current_setting('role'),
  'currentUser',(SELECT oid::text FROM pg_roles WHERE rolname=current_user),
  'serverVersion',current_setting('server_version_num')) INTO native_context;
 IF actor IS DISTINCT FROM captured_actor OR effective_policies IS DISTINCT FROM captured_policies
  OR native_context IS DISTINCT FROM captured_native_context
  OR (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN
  RAISE EXCEPTION 'catalog authority changed during conditional reader observation' USING ERRCODE='55P03';END IF;
 PERFORM truss.runtime_person(false);
 RETURN response_bytes;
END;
$function$

CREATE OR REPLACE FUNCTION truss.reconcile_feed_ack(selected_consumer text, prior bytea, target bytea, feed_sha text, destination text, request_sha text, publication text, receipt bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE selected jsonb;stored truss.runtime_feed_ack_receipt%ROWTYPE;c truss.runtime_feed_consumer%ROWTYPE;answer text;
BEGIN
 IF current_setting('transaction_read_only')<>'on' OR pg_current_xact_id_if_assigned() IS NOT NULL
 THEN RAISE EXCEPTION 'read-only unassigned transaction required for ACK reconciliation' USING ERRCODE='0A000';END IF;
 selected:=truss.feed_ack_receipt_binding(selected_consumer,prior,target,feed_sha,destination,request_sha,publication,receipt,expected_release,expected_digest);
 SELECT * INTO STRICT c FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer;
 SELECT * INTO stored FROM truss.runtime_feed_ack_receipt WHERE registration_id=c.registration_id
 AND prior_sha256=encode(sha256(prior),'hex') AND target_sha256=encode(sha256(target),'hex');
 answer:=CASE WHEN NOT FOUND THEN 'missing' WHEN stored.prior_bytes=prior AND stored.target_bytes=target AND stored.binding=selected AND stored.receipt_bytes=receipt THEN 'matched' ELSE 'conflicting' END;
 IF c.checkpoint_bytes IS DISTINCT FROM truss.runtime_feed_cursor(selected_consumer,convert_from(c.checkpoint_bytes,'UTF8')::jsonb->>'nextXid')
 OR answer<>'missing' AND (convert_from(c.checkpoint_bytes,'UTF8')::jsonb->>'nextXid')::numeric<(convert_from(stored.target_bytes,'UTF8')::jsonb->>'nextXid')::numeric
 THEN RAISE EXCEPTION 'ACK receipt checkpoint integrity required' USING ERRCODE='55000';END IF;
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 IF c.registration_id IS DISTINCT FROM (SELECT registration_id FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer)
 THEN RAISE EXCEPTION 'ACK receipt registration changed' USING ERRCODE='55P03';END IF;
 RETURN convert_to(jsonb_build_object('outcome',answer,'checkpointBase64',replace(encode(c.checkpoint_bytes,'base64'),chr(10),''),
 'binding',stored.binding,'priorBase64',replace(encode(stored.prior_bytes,'base64'),chr(10),''),'nextBase64',replace(encode(stored.target_bytes,'base64'),chr(10),''),
 'receiptBase64',replace(encode(stored.receipt_bytes,'base64'),chr(10),''))::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.registrar_status(expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;actor oid;is_registrar boolean;
BEGIN
 actor:=truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected runtime required' USING ERRCODE='0A000';END IF;
 WITH RECURSIVE memberships(role_oid) AS (
  SELECT actor UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
 SELECT coalesce(bool_or(role_oid=installation.registrar_oid),false) INTO is_registrar FROM memberships;
 PERFORM truss.runtime_person(false);
 RETURN convert_to(jsonb_build_object('registrar',is_registrar)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.render_logical_object(current_object truss.object, selected_type truss.type_def, properties truss.prop_def[], has_row_home boolean, definition_pin text, captured_revision integer, maximum_bytes integer, expected_release text, expected_digest text, root_identity jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE scalar_copy truss.object; rendered jsonb;result bytea;
BEGIN
 IF current_object.root_id IS NULL AND current_object.root_type IS NULL THEN
  IF root_identity IS NOT NULL THEN RAISE EXCEPTION 'rootless observation required' USING ERRCODE='55000';END IF;
  RETURN truss.render_scalar_object(current_object,selected_type,properties,has_row_home,definition_pin,captured_revision,maximum_bytes,expected_release,expected_digest);
 END IF;
 IF current_object.root_id IS NULL OR current_object.root_type IS NULL OR current_object.root_id<=0
  OR root_identity IS NULL OR root_identity->>'id' IS DISTINCT FROM current_object.root_id::text
  OR root_identity->>'typeId' IS DISTINCT FROM current_object.root_type::text THEN
  RAISE EXCEPTION 'complete frozen ownership required' USING ERRCODE='55000';END IF;
 scalar_copy:=current_object;scalar_copy.root_id:=NULL;scalar_copy.root_type:=NULL;
 rendered:=convert_from(truss.render_scalar_object(scalar_copy,selected_type,properties,has_row_home,definition_pin,captured_revision,maximum_bytes,expected_release,expected_digest),'UTF8')::jsonb;
 result:=convert_to((rendered||jsonb_build_object('profile','truss-python-logical-object/0.1','root',root_identity))::text,'UTF8');
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'object output budget exceeded' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.render_scalar_object(current_object truss.object, selected_type truss.type_def, properties truss.prop_def[], has_row_home boolean, definition_pin text, captured_revision integer, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE property truss.prop_def;cell jsonb;values_json jsonb:='[]';retained_json jsonb:='[]';result bytea;
BEGIN
 IF current_object.rev>captured_revision THEN
  RAISE EXCEPTION 'catalog changed during object observation' USING ERRCODE='55P03';END IF;
 IF octet_length(current_object.props::text)+coalesce(octet_length(current_object.retained::text),0)>maximum_bytes THEN
  RAISE EXCEPTION 'object output budget exceeded' USING ERRCODE='54000'; END IF;
 IF current_object.root_id IS NOT NULL OR current_object.ver<=0 OR current_object.rev<selected_type.since_rev OR current_object.rev>captured_revision OR selected_type.since_rev>captured_revision
 OR NOT isfinite(current_object.created_at) OR NOT isfinite(current_object.updated_at)
 OR current_object.created_at<'0001-01-01 00:00:00+00'::timestamptz OR current_object.created_at>='10000-01-01 00:00:00+00'::timestamptz
 OR current_object.updated_at<'0001-01-01 00:00:00+00'::timestamptz OR current_object.updated_at>='10000-01-01 00:00:00+00'::timestamptz
 OR has_row_home
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(current_object.props) k WHERE NOT EXISTS(
   SELECT 1 FROM unnest(properties) p WHERE p.prop_id::text=k)) THEN
  RAISE EXCEPTION 'unsupported complete object representation' USING ERRCODE='0A000'; END IF;
 FOREACH property IN ARRAY properties LOOP
  IF truss.valid_property_definition(property) IS NOT TRUE OR property.since_rev>captured_revision THEN
   RAISE EXCEPTION 'unsupported property profile' USING ERRCODE='0A000'; END IF;
  IF NOT current_object.props ? property.prop_id::text THEN
   IF property.nullability='required' THEN RAISE EXCEPTION 'missing required property' USING ERRCODE='55000'; END IF;
   CONTINUE;
  END IF;
  cell:=current_object.props->property.prop_id::text;
  IF truss.valid_property_value(cell,property) IS NOT TRUE THEN RAISE EXCEPTION 'malformed exact logical value' USING ERRCODE='55000';END IF;
  cell:=truss.logical_flat_cell(cell);
  values_json:=values_json||jsonb_build_array(jsonb_build_array(property.name,cell));
 END LOOP;
 FOR cell IN SELECT jsonb_build_array(key,value) FROM jsonb_each(coalesce(current_object.retained,'{}'::jsonb)) ORDER BY key COLLATE "C" LOOP
  cell:=jsonb_build_array(cell->0,truss.logical_flat_cell(cell->1));
  retained_json:=retained_json||jsonb_build_array(cell);
 END LOOP;
 result:=convert_to(jsonb_build_object('profile','truss-python-scalar-object/0.4','releaseId',expected_release,
 'releaseSha256',expected_digest,'documentId',selected_type.document_id,'moduleId',selected_type.module,'recordId',selected_type.element,
 'id',current_object.id::text,'typeId',current_object.type_id::text,
 'definitionPin',definition_pin,'version',current_object.ver::text,
 'catalogRevision',captured_revision::text,'recordRevision',current_object.rev::text,
 'createdAt',to_char(current_object.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
 'updatedAt',to_char(current_object.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
 'values',values_json,'retained',retained_json)::text,'UTF8');
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'object output budget exceeded' USING ERRCODE='54000'; END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.reread_feed(selected_consumer text, expected_prior bytea, target bytea, payload_sha256 text, maximum_facts integer, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE target_json jsonb;frontier numeric;result bytea;envelope jsonb;captured_revision int;
BEGIN
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 captured_revision:=(SELECT rev FROM truss.schema_head WHERE id=1);
 IF target IS NULL OR octet_length(target) NOT BETWEEN 1 AND 16384 OR payload_sha256 IS NULL OR payload_sha256 !~ '^[0-9a-f]{64}$'
 OR (convert_from(target,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
  RAISE EXCEPTION 'exact delivered boundary required' USING ERRCODE='22023';END IF;
 target_json:=convert_from(target,'UTF8')::jsonb;
 IF jsonb_typeof(target_json->'nextXid') IS DISTINCT FROM 'string' OR target_json->>'nextXid' !~ '^(0|[1-9][0-9]{0,19})$' THEN
  RAISE EXCEPTION 'exact delivered position required' USING ERRCODE='22023';END IF;
 frontier:=(target_json->>'nextXid')::numeric;
 IF frontier>pg_snapshot_xmin(pg_current_snapshot())::text::numeric THEN
  RAISE EXCEPTION 'committed interval required' USING ERRCODE='55000';END IF;
 result:=truss.runtime_feed_page(selected_consumer,expected_prior,frontier,maximum_facts,maximum_bytes);
 envelope:=convert_from(result,'UTF8')::jsonb;
 IF decode(envelope->>'nextBase64','base64') IS DISTINCT FROM target OR envelope->>'sha256' IS DISTINCT FROM payload_sha256 THEN
  RAISE EXCEPTION 'original complete retained interval required' USING ERRCODE='55000';END IF;
 PERFORM truss.runtime_feed_authorize(selected_consumer,expected_release,expected_digest);
 IF captured_revision IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1) THEN
  RAISE EXCEPTION 'feed context changed' USING ERRCODE='55P03';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_can_read_qualified(document_id text, module_id text, qualified_actor oid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
DECLARE person oid;policy truss.module_access%ROWTYPE;
BEGIN
 person:=qualified_actor;
 IF current_setting('transaction_read_only')='on' THEN
 SELECT * INTO policy FROM truss.module_access p WHERE p.document_id=runtime_can_read_qualified.document_id AND p.module=module_id;
 ELSE
 SELECT * INTO policy FROM truss.module_access p WHERE p.document_id=runtime_can_read_qualified.document_id AND p.module=module_id FOR SHARE NOWAIT;
 END IF;
 IF NOT FOUND THEN RETURN false; END IF;
 RETURN EXISTS(WITH RECURSIVE memberships(role_oid) AS (
  SELECT person UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
  SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid WHERE r.rolname::text IN(policy.reader_role,policy.writer_role));
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_capture_feed_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE writer xid8;installation truss.catalog_runtime_installation%ROWTYPE;configuration jsonb;retained jsonb;
BEGIN
 -- Installed carriers expose their writer directly. Do not serialize the full
 -- journal event merely to extract its xid; extension carriers retain the
 -- original named-field path.
 IF TG_ARGV[0]='xid' THEN writer:=NEW.xid;
 ELSIF TG_ARGV[0]='writer_xid' THEN writer:=NEW.writer_xid;
 ELSE writer:=(to_jsonb(NEW)->>TG_ARGV[0])::xid8;
 END IF;
 IF writer IS DISTINCT FROM pg_current_xact_id() THEN RAISE EXCEPTION 'current feed fact writer required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 configuration:=jsonb_build_object('releaseId',installation.release_id,'releaseSha256',installation.release_sha256,
  'layoutProfile',installation.layout_profile,'preparationConfiguration',installation.preparation_configuration,
  'settings',(SELECT jsonb_object_agg(key,value) FROM truss.setting));
 SELECT t.configuration INTO retained FROM truss.runtime_feed_transaction_configuration t WHERE t.writer_xid=writer;
 IF FOUND THEN
  IF retained IS DISTINCT FROM configuration THEN RAISE EXCEPTION 'stable feed writer configuration required' USING ERRCODE='55000';END IF;
 ELSE
  INSERT INTO truss.runtime_feed_transaction_configuration VALUES(writer,configuration);
  SELECT t.configuration INTO retained FROM truss.runtime_feed_transaction_configuration t WHERE t.writer_xid=writer;
  IF NOT FOUND OR retained IS DISTINCT FROM configuration THEN RAISE EXCEPTION 'original feed writer configuration required' USING ERRCODE='55000';END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_condition_inventory(input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE conditions jsonb:=coalesce(input->'preconditions','[]');condition jsonb;selected truss.type_def%ROWTYPE;other truss.type_def%ROWTYPE;
 last_target jsonb;last_target_type truss.type_def%ROWTYPE;last_target_valid boolean:=false;
 relation truss.rel_def%ROWTYPE;property truss.prop_def%ROWTYPE;key_row truss.key_def%ROWTYPE;component record;owner record;
 inventory jsonb;inventory_entries jsonb[]:='{}';entry jsonb;objects jsonb;scopes jsonb;scope_entries jsonb[];scope_entry jsonb;identity jsonb;bound text;index int:=0;
BEGIN
 IF jsonb_typeof(conditions) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'condition array required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(conditions)>(CASE WHEN input->'mutationProfile'=truss.runtime_owned_profile() THEN 3072 ELSE 128 END) THEN
  RAISE EXCEPTION 'condition count exceeds selected profile' USING ERRCODE='54000';END IF;
 IF jsonb_array_length(conditions)<>(SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(conditions)) THEN RAISE EXCEPTION 'unique condition IDs required' USING ERRCODE='22023';END IF;
 FOR condition IN SELECT value FROM jsonb_array_elements(conditions) LOOP
  IF jsonb_typeof(condition->'id') IS DISTINCT FROM 'string' OR octet_length(condition->>'id') NOT BETWEEN 1 AND 1024
   OR jsonb_typeof(condition->'reason') IS DISTINCT FROM 'string' OR octet_length(condition->>'reason')>4096 THEN RAISE EXCEPTION 'caller condition ID/reason required' USING ERRCODE='22023';END IF;
  objects:='[]';scope_entries:='{}';entry:=jsonb_build_object('index',index,'condition',condition);
  IF condition->>'condition' IN ('object_exists','property_equals') THEN
   IF condition-(CASE condition->>'condition' WHEN 'object_exists' THEN ARRAY['condition','id','reason','target'] ELSE ARRAY['condition','id','reason','target','name','value'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'closed object condition required' USING ERRCODE='22023';END IF;
   -- Repeated exact targets share immutable type metadata within this one
   -- inventory pass. Full identity equality retains the ID/owner/pin checks;
   -- authority is still checked for every condition below.
   IF last_target_valid AND last_target IS NOT DISTINCT FROM condition->'target' THEN selected:=last_target_type;
   ELSE
    selected:=truss.runtime_condition_type(condition->'target');last_target:=condition->'target';last_target_type:=selected;last_target_valid:=true;
   END IF;
   objects:=jsonb_build_array(condition->'target');
   scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module);
   IF condition->>'condition'='property_equals' THEN
    IF jsonb_typeof(condition->'name') IS DISTINCT FROM 'string' OR octet_length(condition->>'name') NOT BETWEEN 1 AND 4096 OR truss.valid_flat_cell(condition->'value') IS NOT TRUE THEN RAISE EXCEPTION 'exact scalar property equality required' USING ERRCODE='22023';END IF;
    SELECT * INTO property FROM truss.prop_def p WHERE p.type_id=selected.type_id AND p.name=condition->>'name' AND p.retired_rev IS NULL;
    IF FOUND THEN entry:=entry||jsonb_build_object('propertyId',property.prop_id::text);
     scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',property.declaration_module);
     IF property.cardinality IN ('array','map') THEN
      FOR scope_entry IN SELECT jsonb_build_object('documentId',node.value->>'documentId','moduleId',node.value->'reference'->>'module')
       FROM jsonb_array_elements(jsonb_build_array(property.item)||coalesce(property.item->'descendants','[]'::jsonb)) WITH ORDINALITY node(value,ordinality)
       ORDER BY node.ordinality LOOP
       scope_entries[cardinality(scope_entries)+1]:=scope_entry;
      END LOOP;
     END IF;
    END IF;
   END IF;
  ELSIF condition->>'condition'='key_absent' THEN
   IF condition-ARRAY['condition','id','reason','typeDefinitionPin','keyId','values']<>'{}'::jsonb OR jsonb_typeof(condition->'values') IS DISTINCT FROM 'array'
    OR jsonb_array_length(condition->'values') NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'closed key condition required' USING ERRCODE='22023';END IF;
   WITH pinned AS MATERIALIZED (
    SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
    WHERE definition_pin=condition->>'typeDefinitionPin' AND kind='element' AND key_id='')
   SELECT t.* INTO selected FROM pinned p JOIN truss.type_def t
    ON t.definition_rev=p.rev AND t.definition_doc_ord=p.ord AND t.definition_document_id=p.doc_id
     AND t.module=p.module_id AND t.element=p.element_id
    WHERE NOT t.provisional AND t.retired_rev IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'known predicate type required' USING ERRCODE='22023';END IF;
   SELECT * INTO key_row FROM truss.key_def WHERE type_id=selected.type_id AND key_id=condition->>'keyId' AND retired_rev IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'known predicate key required' USING ERRCODE='22023';END IF;
   IF cardinality(key_row.prop_ids)<>jsonb_array_length(condition->'values') OR EXISTS(SELECT 1 FROM jsonb_array_elements(condition->'values') v WHERE v.value->>'kind' NOT IN ('string','integer','decimal','boolean','binary') OR truss.valid_scalar_cell(v.value,NULL,false) IS NOT TRUE) THEN RAISE EXCEPTION 'complete exact key values required' USING ERRCODE='22023';END IF;
   scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module);
   FOR component IN SELECT p.*,i.ord AS component_ordinal FROM unnest(key_row.prop_ids) WITH ORDINALITY i(prop_id,ord) JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=selected.type_id ORDER BY i.ord LOOP
    IF component.scalar_type NOT IN ('string','integer','decimal','boolean','binary') OR component.nullability IS DISTINCT FROM 'required' OR component.retired_rev IS NOT NULL THEN RAISE EXCEPTION 'supported string key required' USING ERRCODE='0A000';END IF;
    IF truss.valid_scalar_property(condition->'values'->(component.component_ordinal::int-1),component.scalar_type,false,component.facets) IS NOT TRUE THEN RAISE EXCEPTION 'exact declared condition key cell required' USING ERRCODE='22023';END IF;
    scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',component.declaration_module);
   END LOOP;
   entry:=entry||jsonb_build_object('typeId',selected.type_id::text,'documentId',selected.document_id,'moduleId',selected.module,'recordId',selected.element,'keyId',key_row.key_id,'keyNumber',key_row.key_num::text,'values',condition->'values');
  ELSIF condition->>'condition' IN ('relationship_absent','relationship_count') THEN
   -- Select the exact source pin before joining native coordinates. Evaluating
   -- the pin function for every unrelated relationship made bounded condition
   -- batches grow with the complete catalog instead of their selected pins.
   WITH pinned AS MATERIALIZED (
    SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
    WHERE definition_pin=condition->>'relationshipDefinitionPin' AND kind='relationship' AND key_id='')
   SELECT r.* INTO relation FROM pinned p JOIN truss.rel_def r
    ON r.definition_rev=p.rev AND r.definition_doc_ord=p.ord AND r.definition_document_id=p.doc_id
     AND r.module=p.module_id AND r.rel_id=p.element_id
    WHERE r.retired_rev IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'known predicate relationship required' USING ERRCODE='22023';END IF;
   scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module);
   FOR owner IN SELECT DISTINCT t.document_id,t.module FROM truss.rel_endpoint e JOIN truss.type_def t ON t.type_id=e.source_type OR t.type_id=e.target_type WHERE e.rel_type_id=relation.rel_type_id LOOP
    scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module);
   END LOOP;
   entry:=entry||jsonb_build_object('relationshipId',relation.rel_type_id::text);
   IF condition->>'condition'='relationship_absent' THEN
    IF condition-ARRAY['condition','id','reason','relationshipDefinitionPin','source','target']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed relationship condition required' USING ERRCODE='22023';END IF;
    selected:=truss.runtime_condition_type(condition->'source');other:=truss.runtime_condition_type(condition->'target');
    IF NOT EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND source_type=selected.type_id AND target_type=other.type_id) THEN RAISE EXCEPTION 'admitted relationship endpoint types required' USING ERRCODE='22023';END IF;
    objects:=jsonb_build_array(condition->'source',condition->'target');
   ELSE
    IF condition-ARRAY['condition','id','reason','relationshipDefinitionPin','anchor','direction','minimum','maximum']<>'{}'::jsonb OR coalesce(condition->>'direction','') NOT IN ('outgoing','incoming') OR jsonb_typeof(condition->'minimum') IS DISTINCT FROM 'string' OR (condition ? 'maximum' AND jsonb_typeof(condition->'maximum') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'closed relationship count required' USING ERRCODE='22023';END IF;
    selected:=truss.runtime_condition_type(condition->'anchor');objects:=jsonb_build_array(condition->'anchor');
    IF NOT EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND (condition->>'direction'='outgoing' AND source_type=selected.type_id OR condition->>'direction'='incoming' AND target_type=selected.type_id)) THEN RAISE EXCEPTION 'admitted count anchor required' USING ERRCODE='22023';END IF;
    FOREACH bound IN ARRAY ARRAY[condition->>'minimum',CASE WHEN condition ? 'maximum' THEN condition->>'maximum' ELSE '9223372036854775807' END] LOOP
     IF bound IS NULL OR bound !~ '^(0|[1-9][0-9]{0,18})$' OR length(bound)=19 AND bound COLLATE "C">'9223372036854775807' THEN RAISE EXCEPTION 'exact bounded counts required' USING ERRCODE='22023';END IF;
    END LOOP;
    IF condition ? 'maximum' AND (condition->>'minimum')::bigint>(condition->>'maximum')::bigint THEN RAISE EXCEPTION 'ordered count bounds required' USING ERRCODE='22023';END IF;
   END IF;
  ELSE RAISE EXCEPTION 'known condition required' USING ERRCODE='22023';END IF;
  SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO scopes FROM unnest(scope_entries) WITH ORDINALITY s(value,ord);
  FOR owner IN SELECT DISTINCT value->>'documentId' AS document_id,value->>'moduleId' AS module_id FROM jsonb_array_elements(scopes) LOOP
   IF NOT truss.runtime_can_read(owner.document_id,owner.module_id) THEN RAISE EXCEPTION 'current predicate owner read authority required' USING ERRCODE='42501';END IF;
  END LOOP;
  inventory_entries[cardinality(inventory_entries)+1]:=entry||jsonb_build_object('objects',objects,'scopes',scopes);index:=index+1;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO inventory FROM unnest(inventory_entries) WITH ORDINALITY i(value,ord);
 RETURN inventory;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_condition_inventory_preview(input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE conditions jsonb:=coalesce(input->'preconditions','[]');condition jsonb;selected truss.type_def%ROWTYPE;other truss.type_def%ROWTYPE;
 last_target jsonb;last_target_type truss.type_def%ROWTYPE;last_target_valid boolean:=false;
 relation truss.rel_def%ROWTYPE;property truss.prop_def%ROWTYPE;key_row truss.key_def%ROWTYPE;component record;owner record;pin text;
 inventory jsonb;inventory_entries jsonb[]:='{}';entry jsonb;objects jsonb;scopes jsonb;scope_entries jsonb[];scope_entry jsonb;identity jsonb;bound text;index int:=0;
BEGIN
