 IF jsonb_array_length(conditions)<>(SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(conditions)) THEN RAISE EXCEPTION 'unique condition IDs required' USING ERRCODE='22023';END IF;
 FOR condition IN SELECT value FROM jsonb_array_elements(conditions) LOOP
  IF jsonb_typeof(condition->'id') IS DISTINCT FROM 'string' OR octet_length(condition->>'id') NOT BETWEEN 1 AND 1024
   OR jsonb_typeof(condition->'reason') IS DISTINCT FROM 'string' OR octet_length(condition->>'reason')>4096 THEN RAISE EXCEPTION 'caller condition ID/reason required' USING ERRCODE='22023';END IF;
  objects:='[]';scope_entries:='{}';entry:=jsonb_build_object('index',index,'condition',condition);
  IF condition->>'condition' IN ('object_exists','property_equals') THEN
   IF condition-(CASE condition->>'condition' WHEN 'object_exists' THEN ARRAY['condition','id','reason','target'] ELSE ARRAY['condition','id','reason','target','name','value'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'closed object condition required' USING ERRCODE='22023';END IF;
   -- Repeated exact targets share immutable type metadata within this one
   -- inventory pass. Full identity equality retains the ID/owner/pin checks;
   -- authority is still checked for every condition below.
   IF last_target_valid AND last_target IS NOT DISTINCT FROM condition->'target' THEN selected:=last_target_type;
   ELSE
    selected:=truss.runtime_condition_type_preview(condition->'target');last_target:=condition->'target';last_target_type:=selected;last_target_valid:=true;
   END IF;
   objects:=jsonb_build_array(condition->'target');
   scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module);
   IF condition->>'condition'='property_equals' THEN
    IF jsonb_typeof(condition->'name') IS DISTINCT FROM 'string' OR octet_length(condition->>'name') NOT BETWEEN 1 AND 4096 OR truss.valid_flat_cell(condition->'value') IS NOT TRUE THEN RAISE EXCEPTION 'exact scalar property equality required' USING ERRCODE='22023';END IF;
    SELECT * INTO property FROM truss.prop_def p WHERE p.type_id=selected.type_id AND p.name=condition->>'name' AND p.retired_rev IS NULL;
    IF FOUND THEN entry:=entry||jsonb_build_object('propertyId',property.prop_id::text);
     scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',property.declaration_module);
     IF property.cardinality IN ('array','map') THEN
      FOR scope_entry IN SELECT jsonb_build_object('documentId',node.value->>'documentId','moduleId',node.value->'reference'->>'module')
       FROM jsonb_array_elements(jsonb_build_array(property.item)||coalesce(property.item->'descendants','[]'::jsonb)) WITH ORDINALITY node(value,ordinality)
       ORDER BY node.ordinality LOOP
       scope_entries[cardinality(scope_entries)+1]:=scope_entry;
      END LOOP;
     END IF;
    END IF;
   END IF;
  ELSIF condition->>'condition'='key_absent' THEN
   IF condition-ARRAY['condition','id','reason','typeDefinitionPin','keyId','values']<>'{}'::jsonb OR jsonb_typeof(condition->'values') IS DISTINCT FROM 'array'
    OR jsonb_array_length(condition->'values') NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'closed key condition required' USING ERRCODE='22023';END IF;
   WITH pinned AS MATERIALIZED (
    SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
    WHERE definition_pin=condition->>'typeDefinitionPin' AND kind='element' AND key_id='')
   SELECT t.* INTO selected FROM pinned p JOIN truss.type_def t
    ON t.definition_rev=p.rev AND t.definition_doc_ord=p.ord AND t.definition_document_id=p.doc_id
     AND t.module=p.module_id AND t.element=p.element_id
    WHERE NOT t.provisional AND t.retired_rev IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'known predicate type required' USING ERRCODE='22023';END IF;
   SELECT * INTO key_row FROM truss.key_def WHERE type_id=selected.type_id AND key_id=condition->>'keyId' AND retired_rev IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'known predicate key required' USING ERRCODE='22023';END IF;
   IF cardinality(key_row.prop_ids)<>jsonb_array_length(condition->'values') OR EXISTS(SELECT 1 FROM jsonb_array_elements(condition->'values') v WHERE v.value->>'kind' NOT IN ('string','integer','decimal','boolean','binary') OR truss.valid_scalar_cell(v.value,NULL,false) IS NOT TRUE) THEN RAISE EXCEPTION 'complete exact key values required' USING ERRCODE='22023';END IF;
   SELECT d.definition_pin INTO STRICT pin FROM truss.runtime_definition_source d
    WHERE d.rev=key_row.definition_rev AND d.ord=key_row.definition_doc_ord AND d.doc_id=key_row.definition_document_id
     AND d.module_id=selected.module AND d.element_id=selected.element AND d.kind='key' AND d.key_id=key_row.key_id;
   entry:=entry||jsonb_build_object('keyDefinitionPin',pin);
   scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module);
   FOR component IN SELECT p.*,i.ord AS component_ordinal FROM unnest(key_row.prop_ids) WITH ORDINALITY i(prop_id,ord) JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=selected.type_id ORDER BY i.ord LOOP
    IF component.scalar_type NOT IN ('string','integer','decimal','boolean','binary') OR component.nullability IS DISTINCT FROM 'required' OR component.retired_rev IS NOT NULL THEN RAISE EXCEPTION 'supported string key required' USING ERRCODE='0A000';END IF;
    IF truss.valid_scalar_property(condition->'values'->(component.component_ordinal::int-1),component.scalar_type,false,component.facets) IS NOT TRUE THEN RAISE EXCEPTION 'exact declared condition key cell required' USING ERRCODE='22023';END IF;
    scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',selected.document_id,'moduleId',component.declaration_module);
   END LOOP;
   entry:=entry||jsonb_build_object('typeId',selected.type_id::text,'documentId',selected.document_id,'moduleId',selected.module,'recordId',selected.element,'keyId',key_row.key_id,'keyNumber',key_row.key_num::text,'values',condition->'values');
  ELSIF condition->>'condition' IN ('relationship_absent','relationship_count') THEN
   -- Select the exact source pin before joining native coordinates. Evaluating
   -- the pin function for every unrelated relationship made bounded condition
   -- batches grow with the complete catalog instead of their selected pins.
   WITH pinned AS MATERIALIZED (
    SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
    WHERE definition_pin=condition->>'relationshipDefinitionPin' AND kind='relationship' AND key_id='')
   SELECT r.* INTO relation FROM pinned p JOIN truss.rel_def r
    ON r.definition_rev=p.rev AND r.definition_doc_ord=p.ord AND r.definition_document_id=p.doc_id
     AND r.module=p.module_id AND r.rel_id=p.element_id
    WHERE r.retired_rev IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'known predicate relationship required' USING ERRCODE='22023';END IF;
   scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module);
   FOR owner IN SELECT DISTINCT t.document_id,t.module FROM truss.rel_endpoint e JOIN truss.type_def t ON t.type_id=e.source_type OR t.type_id=e.target_type WHERE e.rel_type_id=relation.rel_type_id LOOP
    scope_entries[cardinality(scope_entries)+1]:=jsonb_build_object('documentId',owner.document_id,'moduleId',owner.module);
   END LOOP;
   entry:=entry||jsonb_build_object('relationshipId',relation.rel_type_id::text);
   IF condition->>'condition'='relationship_absent' THEN
    IF condition-ARRAY['condition','id','reason','relationshipDefinitionPin','source','target']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed relationship condition required' USING ERRCODE='22023';END IF;
    selected:=truss.runtime_condition_type_preview(condition->'source');other:=truss.runtime_condition_type_preview(condition->'target');
    IF NOT EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND source_type=selected.type_id AND target_type=other.type_id) THEN RAISE EXCEPTION 'admitted relationship endpoint types required' USING ERRCODE='22023';END IF;
    objects:=jsonb_build_array(condition->'source',condition->'target');
   ELSE
    IF condition-ARRAY['condition','id','reason','relationshipDefinitionPin','anchor','direction','minimum','maximum']<>'{}'::jsonb OR coalesce(condition->>'direction','') NOT IN ('outgoing','incoming') OR jsonb_typeof(condition->'minimum') IS DISTINCT FROM 'string' OR (condition ? 'maximum' AND jsonb_typeof(condition->'maximum') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'closed relationship count required' USING ERRCODE='22023';END IF;
    selected:=truss.runtime_condition_type_preview(condition->'anchor');objects:=jsonb_build_array(condition->'anchor');
    IF NOT EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND (condition->>'direction'='outgoing' AND source_type=selected.type_id OR condition->>'direction'='incoming' AND target_type=selected.type_id)) THEN RAISE EXCEPTION 'admitted count anchor required' USING ERRCODE='22023';END IF;
    FOREACH bound IN ARRAY ARRAY[condition->>'minimum',CASE WHEN condition ? 'maximum' THEN condition->>'maximum' ELSE '9223372036854775807' END] LOOP
     IF bound IS NULL OR bound !~ '^(0|[1-9][0-9]{0,18})$' OR length(bound)=19 AND bound COLLATE "C">'9223372036854775807' THEN RAISE EXCEPTION 'exact bounded counts required' USING ERRCODE='22023';END IF;
    END LOOP;
    IF condition ? 'maximum' AND (condition->>'minimum')::bigint>(condition->>'maximum')::bigint THEN RAISE EXCEPTION 'ordered count bounds required' USING ERRCODE='22023';END IF;
   END IF;
  ELSE RAISE EXCEPTION 'known condition required' USING ERRCODE='22023';END IF;
  SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO scopes FROM unnest(scope_entries) WITH ORDINALITY s(value,ord);
  FOR owner IN SELECT DISTINCT value->>'documentId' AS document_id,value->>'moduleId' AS module_id FROM jsonb_array_elements(scopes) LOOP
   IF NOT truss.runtime_can_read(owner.document_id,owner.module_id) THEN RAISE EXCEPTION 'current predicate owner read authority required' USING ERRCODE='42501';END IF;
  END LOOP;
  inventory_entries[cardinality(inventory_entries)+1]:=entry||jsonb_build_object('objects',objects,'scopes',scopes);index:=index+1;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO inventory FROM unnest(inventory_entries) WITH ORDINALITY i(value,ord);
 RETURN inventory;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_condition_key_tuple_preview(selected_type integer, selected_key smallint, cells jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE compiled jsonb;current_revision int;
BEGIN
 SELECT rev INTO STRICT current_revision FROM truss.schema_head WHERE id=1;
 SELECT metadata->'keyCodecs'->selected_key::text INTO compiled FROM truss.runtime_type_schema
  WHERE rev=current_revision AND type_id=selected_type
   AND NOT EXISTS(SELECT 1 FROM truss.schema_rev newer WHERE newer.rev>current_revision);
 IF compiled IS NULL THEN RAISE EXCEPTION 'selected compiled key codec required' USING ERRCODE='0A000';END IF;
 RETURN truss.runtime_owned_key_tuple_in_metadata(selected_type,selected_key,cells,compiled);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_condition_type(identity jsonb)
 RETURNS truss.type_def
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE selected truss.type_def%ROWTYPE;pin record;type_number text;object_number text;
BEGIN
 type_number:=identity->>'typeId';object_number:=identity->>'id';
 IF jsonb_typeof(identity) IS DISTINCT FROM 'object' OR identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb
 OR jsonb_typeof(identity->'typeId') IS DISTINCT FROM 'string' OR jsonb_typeof(identity->'id') IS DISTINCT FROM 'string'
 OR jsonb_typeof(identity->'definitionPin') IS DISTINCT FROM 'string'
 OR type_number !~ '^[1-9][0-9]{0,9}$' OR length(type_number)=10 AND type_number COLLATE "C">'2147483647'
 OR object_number !~ '^[1-9][0-9]{0,18}$' OR length(object_number)=19 AND object_number COLLATE "C">'9223372036854775807' THEN
  RAISE EXCEPTION 'qualified exact condition identity required' USING ERRCODE='22023';END IF;
 SELECT * INTO selected FROM truss.type_def WHERE type_id=type_number::int AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'known condition type required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',selected.type_id);
 IF identity->>'definitionPin' IS DISTINCT FROM pin.definition_pin OR identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module) THEN
  RAISE EXCEPTION 'current qualified condition definition required' USING ERRCODE='22023';END IF;
 RETURN selected;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_condition_type_preview(identity jsonb)
 RETURNS truss.type_def
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE selected truss.type_def%ROWTYPE;pin text;type_number text;object_number text;
BEGIN
 type_number:=identity->>'typeId';object_number:=identity->>'id';
 IF jsonb_typeof(identity) IS DISTINCT FROM 'object' OR identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb
 OR jsonb_typeof(identity->'typeId') IS DISTINCT FROM 'string' OR jsonb_typeof(identity->'id') IS DISTINCT FROM 'string'
 OR jsonb_typeof(identity->'definitionPin') IS DISTINCT FROM 'string'
 OR type_number !~ '^[1-9][0-9]{0,9}$' OR length(type_number)=10 AND type_number COLLATE "C">'2147483647'
 OR object_number !~ '^[1-9][0-9]{0,18}$' OR length(object_number)=19 AND object_number COLLATE "C">'9223372036854775807' THEN
  RAISE EXCEPTION 'qualified exact condition identity required' USING ERRCODE='22023';END IF;
 SELECT * INTO selected FROM truss.type_def WHERE type_id=type_number::int AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'known condition type required' USING ERRCODE='22023';END IF;
 SELECT d.definition_pin INTO STRICT pin FROM truss.runtime_definition_source d
  WHERE d.rev=selected.definition_rev AND d.ord=selected.definition_doc_ord AND d.doc_id=selected.definition_document_id
   AND d.module_id=selected.module AND d.element_id=selected.element AND d.kind='element' AND d.key_id='';
 IF identity->>'definitionPin' IS DISTINCT FROM pin OR identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module) THEN
  RAISE EXCEPTION 'current qualified condition definition required' USING ERRCODE='22023';END IF;
 RETURN selected;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_create_transition_validate_qualified(selected_transition bigint, qualified_actor oid, prepared_input jsonb DEFAULT NULL::jsonb, source_bytes bytea DEFAULT NULL::bytea, prepared_attempt truss.runtime_object_attempt DEFAULT NULL::truss.runtime_object_attempt, compiled_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE transition truss.runtime_object_transition%ROWTYPE;attempt truss.runtime_object_attempt%ROWTYPE;
 member truss.runtime_create_member%ROWTYPE;creation truss.runtime_create_group%ROWTYPE;
 input jsonb;operation jsonb;result jsonb;expected jsonb;semantic jsonb;keys jsonb;key_expected jsonb;
 actual jsonb;generation bigint;entry jsonb;event jsonb;identity jsonb;original_origin jsonb;
BEGIN
 SELECT * INTO STRICT transition FROM truss.runtime_object_transition WHERE transition_id=selected_transition;
 IF prepared_attempt.id IS NOT NULL THEN
   IF prepared_attempt.id IS DISTINCT FROM transition.attempt_id THEN RAISE EXCEPTION 'original checked attempt required' USING ERRCODE='55000';END IF;
   attempt:=prepared_attempt;
  ELSE SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=transition.attempt_id;END IF;
 IF prepared_input IS NOT NULL AND (source_bytes IS NULL OR source_bytes IS DISTINCT FROM attempt.input_bytes) THEN
  RAISE EXCEPTION 'original checked creation input required' USING ERRCODE='55000';END IF;
 IF attempt.context->'creationTransitionProfile'='{"identity":"truss-unified-create-transition","version":"0.2","sha256":"073782e2517f2a7e26c8d6479c6266ececf68963681ccfb6a380e9cd16f2e11b"}'::jsonb THEN
  IF transition.before_object IS NOT NULL OR transition.after_object IS NULL
   OR transition.writer_xid IS DISTINCT FROM attempt.writer_xid OR attempt.writer_xid IS DISTINCT FROM pg_current_xact_id()
   OR attempt.actor_oid IS DISTINCT FROM qualified_actor
   OR transition.operation_index<0 OR transition.operation_index>=attempt.next_index
   OR jsonb_array_length(attempt.results)<>attempt.next_index OR jsonb_array_length(transition.journal)<>1 THEN
   RAISE EXCEPTION 'current atomic create transition required' USING ERRCODE='55000';END IF;
  input:=coalesce(prepared_input,convert_from(attempt.input_bytes,'UTF8')::jsonb);operation:=input->'operations'->transition.operation_index;
  result:=attempt.results->transition.operation_index;identity:=result->'identity';entry:=transition.journal->0;
  event:=convert_from(decode(entry->'new_value'->>'bytesBase64','base64'),'UTF8')::jsonb;
  original_origin:=jsonb_build_object('asserted',input->'assertedOrigin','databaseRole',session_user::text);
  IF operation->>'operation' IS DISTINCT FROM 'create_object' OR result->>'operation' IS DISTINCT FROM 'create_object'
   OR result->>'outcome' IS DISTINCT FROM 'created' OR result->>'version' IS DISTINCT FROM '1'
   OR identity->>'id' IS DISTINCT FROM transition.object_id::text OR identity->>'typeId' IS DISTINCT FROM transition.type_id::text
   OR identity->>'definitionPin' IS DISTINCT FROM operation->>'typeDefinitionPin'
   OR transition.after_object->>'id' IS DISTINCT FROM transition.object_id::text
   OR transition.after_object->>'type_id' IS DISTINCT FROM transition.type_id::text
   OR transition.after_object->>'ver' IS DISTINCT FROM '1'
   OR input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile()
   OR transition.after_object-ARRAY['created_at','updated_at'] IS DISTINCT FROM
    truss.runtime_owned_object_image(attempt.id,transition.operation_index,'create:'||transition.operation_index::text,'after',NULL,attempt)
   OR event->>'operation' IS DISTINCT FROM 'create' OR event->'identity' IS DISTINCT FROM identity
   OR event->'origin' IS DISTINCT FROM original_origin
   OR event->'after' IS DISTINCT FROM (CASE WHEN compiled_metadata IS NULL
    THEN truss.runtime_object_history(transition.after_object,identity)
    ELSE truss.runtime_owned_history_record_in_metadata(transition.after_object,identity,compiled_metadata) END)
   OR entry->>'entity_kind' IS DISTINCT FROM 'o' OR entry->>'entity_id' IS DISTINCT FROM transition.object_id::text
   OR entry->>'entity_type' IS DISTINCT FROM transition.type_id::text OR entry->>'xid' IS DISTINCT FROM attempt.writer_xid::text
   OR entry->>'ver' IS DISTINCT FROM '1' OR entry->>'op' IS DISTINCT FROM 'create'
   OR result->'events' IS DISTINCT FROM jsonb_build_array(jsonb_build_object('sourceEpoch',event->>'sourceEpoch',
    'historyProfile',event->>'historyProfile','xid',event->>'xid','seq',event->>'seq')) THEN
   RAISE EXCEPTION 'atomic create result, image and journal correspondence required' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(j) INTO actual FROM truss.journal j WHERE j.at=(entry->>'at')::timestamptz AND j.seq=(entry->>'seq')::bigint;
  IF actual IS DISTINCT FROM entry THEN RAISE EXCEPTION 'actual create journal required' USING ERRCODE='55000';END IF;
  PERFORM truss.runtime_history_group_qualified(jsonb_build_object('kind','object','id',identity->>'id','typeId',identity->>'typeId',
   'documentId',identity->'owner'->>'documentId','moduleId',identity->'owner'->>'moduleId',
   'sourceEpoch',attempt.context->>'sourceEpoch'),attempt.writer_xid,1,1,16777216,qualified_actor);
  FOR key_expected IN SELECT value FROM jsonb_array_elements(transition.after_keys) LOOP
   SELECT convert_from(r.original_reservation_bytes,'UTF8')::jsonb INTO STRICT actual
    FROM truss.object_key_reservation_bucket r
    -- Generated hashes route the lookup; original bytes establish equality.
    WHERE r.namespace_sha256=decode(substring(key_expected->>'namespace_sha256' FROM 3),'hex')
     AND r.key_sha256=decode(substring(key_expected->>'key_sha256' FROM 3),'hex')
     AND r.namespace_bytes=decode(substring(key_expected->>'namespace_bytes' FROM 3),'hex')
     AND r.key_bytes=decode(substring(key_expected->>'key_bytes' FROM 3),'hex');
   IF actual->>'objectId' IS DISTINCT FROM transition.object_id::text OR actual->>'typeId' IS DISTINCT FROM transition.type_id::text
    OR actual->>'keyNumber' IS DISTINCT FROM key_expected->>'key_num'
    OR decode(actual->>'contextBase64','base64') IS DISTINCT FROM decode(substring(key_expected->>'original_context_bytes' FROM 3),'hex') THEN
    RAISE EXCEPTION 'permanent create key reservation required' USING ERRCODE='55000';END IF;
  END LOOP;
  RETURN;
 END IF;

 IF attempt.context->'creationTransitionProfile' IS DISTINCT FROM '{"identity":"truss-unified-create-transition","version":"0.1","sha256":"765d7def5e677dba5d3ed5cdc841b1aa43eb2f4a493f1d2603ff3698536a5396"}'::jsonb
  OR transition.before_object IS NOT NULL OR transition.after_object IS NULL OR transition.journal IS DISTINCT FROM '[]'::jsonb
  OR attempt.writer_xid IS DISTINCT FROM transition.writer_xid OR attempt.writer_xid IS DISTINCT FROM pg_current_xact_id()
  OR attempt.actor_oid IS DISTINCT FROM qualified_actor
  OR transition.operation_index<0 OR transition.operation_index>=attempt.next_index
  OR jsonb_array_length(attempt.results)<>attempt.next_index THEN
  RAISE EXCEPTION 'original native creation transition profile and progress required' USING ERRCODE='55000';END IF;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
 operation:=input->'operations'->transition.operation_index;result:=attempt.results->transition.operation_index;
 SELECT * INTO STRICT member FROM truss.runtime_create_member
  WHERE object_id=transition.object_id AND type_id=transition.type_id;
 SELECT * INTO STRICT creation FROM truss.runtime_create_group WHERE group_id=member.group_id;
 expected:=creation.expected_members->0;semantic:=convert_from(creation.semantic_bytes,'UTF8')::jsonb;
 IF member.operation_index<>0 OR jsonb_array_length(creation.expected_members)<>1
  OR creation.writer_xid IS DISTINCT FROM attempt.writer_xid OR creation.actor_oid IS DISTINCT FROM attempt.actor_oid
  OR creation.actor_name IS DISTINCT FROM session_user::text
  OR creation.original_document_bytes IS DISTINCT FROM attempt.documents_bytes
  OR creation.original_input_bytes IS DISTINCT FROM convert_to(jsonb_set(input-'preconditions','{operations}',jsonb_build_array(operation))::text,'UTF8')
  OR creation.original_key_bytes IS DISTINCT FROM convert_to('[]','UTF8') OR creation.receipt_storage_row_id IS NOT NULL
  OR operation->>'operation' IS DISTINCT FROM 'create_object' OR result->>'operation' IS DISTINCT FROM 'create_object'
  OR result->>'outcome' IS DISTINCT FROM 'created' OR result->>'version' IS DISTINCT FROM '1'
  OR result->'identity'->>'id' IS DISTINCT FROM transition.object_id::text
  OR result->'identity'->>'typeId' IS DISTINCT FROM transition.type_id::text
  OR semantic->'results' IS DISTINCT FROM jsonb_build_array(result)
  OR semantic->'mutationProfile' IS DISTINCT FROM input->'mutationProfile'
  OR semantic->'layoutProfile' IS DISTINCT FROM input->'layoutProfile'
  OR transition.after_object IS DISTINCT FROM expected->'object'
  OR transition.after_object->>'ver' IS DISTINCT FROM '1'
  OR transition.after_object->>'id' IS DISTINCT FROM transition.object_id::text
  OR transition.after_object->>'type_id' IS DISTINCT FROM transition.type_id::text THEN
  RAISE EXCEPTION 'exact original inner and outer creation correspondence required' USING ERRCODE='55000';END IF;
 IF input->'mutationProfile'=truss.runtime_owned_profile() AND
  transition.after_object-ARRAY['created_at','updated_at'] IS DISTINCT FROM
   truss.runtime_owned_object_image(attempt.id,transition.operation_index,'create:'||transition.operation_index::text,'after',NULL,attempt) THEN
  RAISE EXCEPTION 'original owned creation plan and physical image required' USING ERRCODE='55000';END IF;
 SELECT coalesce(jsonb_agg(k.value->'membership' ORDER BY (k.value->'membership'->>'key_num')::int),'[]'::jsonb)
  INTO keys FROM jsonb_array_elements(expected->'keys') k;
 IF transition.after_keys IS DISTINCT FROM keys THEN RAISE EXCEPTION 'original creation key image required' USING ERRCODE='55000';END IF;
 -- Validate original reservations even if later same-transaction changes/deletes
 -- have superseded the original live key memberships and object image.
 FOR key_expected IN SELECT value FROM jsonb_array_elements(expected->'keys') LOOP
  SELECT to_jsonb(r) INTO actual FROM truss.object_key_reservation_bucket r
   WHERE storage_row_id=(key_expected->'reservation'->>'storage_row_id')::bigint;
  SELECT g.generation INTO generation FROM truss.key_bucket_guard g
   WHERE namespace_sha256=decode(substring(key_expected->'membership'->>'namespace_sha256' FROM 3),'hex')
    AND key_sha256=decode(substring(key_expected->'membership'->>'key_sha256' FROM 3),'hex');
  IF actual IS DISTINCT FROM key_expected->'reservation' OR generation IS NULL
   OR generation<(key_expected->>'generation')::bigint THEN
   RAISE EXCEPTION 'original creation reservation and generation required' USING ERRCODE='55000';END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_create_validate_group(selected_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE group_row truss.runtime_create_group%ROWTYPE;actual_receipt jsonb;semantic jsonb;entry jsonb;member record;
BEGIN
 SELECT * INTO STRICT group_row FROM truss.runtime_create_group WHERE group_id=selected_group;
 semantic:=convert_from(group_row.semantic_bytes,'UTF8')::jsonb;
 IF group_row.writer_xid<>pg_current_xact_id() OR group_row.actor_name<>session_user::text OR group_row.actor_oid IS DISTINCT FROM (SELECT oid FROM pg_roles WHERE rolname=session_user)
 OR jsonb_array_length(semantic->'results')<>jsonb_array_length(group_row.expected_members)
 OR (SELECT count(*) FROM truss.runtime_create_member WHERE group_id=selected_group)<>jsonb_array_length(group_row.expected_members) THEN
  RAISE EXCEPTION 'complete actual create group required' USING ERRCODE='55000'; END IF;
 IF group_row.receipt_storage_row_id IS NOT NULL THEN
  SELECT to_jsonb(r) INTO actual_receipt FROM truss.request_receipt r WHERE storage_row_id=group_row.receipt_storage_row_id;
  IF actual_receipt IS DISTINCT FROM group_row.expected_receipt THEN
   RAISE EXCEPTION 'exact durable group receipt required' USING ERRCODE='55000'; END IF;
 END IF;
 -- Caller-controlled settings cannot authorize skipping integrity checks.
 IF (SELECT coalesce(jsonb_agg(to_jsonb(j) ORDER BY j.at,j.seq),'[]'::jsonb)
     FROM truss.journal j WHERE j.xid=group_row.writer_xid)
 IS DISTINCT FROM (SELECT coalesce(jsonb_agg(e.value ORDER BY (e.value->>'at')::timestamptz,(e.value->>'seq')::bigint),'[]'::jsonb) FROM (
     SELECT e.value->'journal' AS value FROM truss.runtime_create_group g CROSS JOIN LATERAL jsonb_array_elements(g.expected_members) e(value) WHERE g.writer_xid=group_row.writer_xid
     UNION ALL SELECT j.value FROM truss.runtime_object_transition t CROSS JOIN LATERAL jsonb_array_elements(truss.runtime_owned_journal_materialize(t.journal)) j WHERE t.writer_xid=group_row.writer_xid
     UNION ALL SELECT j.value FROM truss.runtime_catalog_rebind_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j WHERE t.writer_xid=group_row.writer_xid
     UNION ALL SELECT j.value FROM truss.runtime_edge_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j WHERE t.writer_xid=group_row.writer_xid) e) THEN
  RAISE EXCEPTION 'complete transaction create journal required' USING ERRCODE='55000'; END IF;
 FOR member IN SELECT * FROM truss.runtime_create_member WHERE group_id=selected_group ORDER BY operation_index LOOP
  entry:=semantic->'results'->member.operation_index;
  IF (entry->'identity'->>'id')::bigint<>member.object_id OR (entry->'identity'->>'typeId')::int<>member.type_id THEN
   RAISE EXCEPTION 'ordered native group result required' USING ERRCODE='55000'; END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_create_validate_member(selected_id bigint, selected_type integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE member truss.runtime_create_member%ROWTYPE;group_row truss.runtime_create_group%ROWTYPE;
 expected jsonb;actual_object jsonb;actual_journal jsonb;key_expected jsonb;actual_key jsonb;actual_reservation jsonb;current_generation bigint;
BEGIN
 SELECT * INTO STRICT member FROM truss.runtime_create_member WHERE object_id=selected_id AND type_id=selected_type;
 SELECT * INTO STRICT group_row FROM truss.runtime_create_group WHERE group_id=member.group_id;
 IF group_row.writer_xid<>pg_current_xact_id() OR group_row.actor_name<>session_user::text OR group_row.actor_oid IS DISTINCT FROM (SELECT oid FROM pg_roles WHERE rolname=session_user) THEN
  RAISE EXCEPTION 'current actual group member required' USING ERRCODE='55000'; END IF;
 expected:=group_row.expected_members->member.operation_index;
 IF (SELECT count(*) FROM truss.runtime_object_transition t
  WHERE t.object_id=selected_id AND t.type_id=selected_type AND t.writer_xid=group_row.writer_xid
   AND t.before_object IS NULL)<>1 THEN
  RAISE EXCEPTION 'one original outer creation transition required' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM truss.runtime_object_transition WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id()) OR EXISTS(SELECT 1 FROM truss.runtime_catalog_rebind_transition WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id()) OR EXISTS(SELECT 1 FROM truss.runtime_catalog_key_backfill WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id()) THEN
  PERFORM truss.runtime_object_validate(selected_id,selected_type);
  SELECT to_jsonb(j) INTO actual_journal FROM truss.journal j WHERE j.at=(expected->'journal'->>'at')::timestamptz AND j.seq=(expected->'journal'->>'seq')::bigint;
  IF actual_journal IS DISTINCT FROM expected->'journal' THEN RAISE EXCEPTION 'original creation journal required' USING ERRCODE='55000';END IF;
  FOR key_expected IN SELECT value FROM jsonb_array_elements(expected->'keys') LOOP
   SELECT to_jsonb(r) INTO actual_reservation FROM truss.object_key_reservation_bucket r WHERE storage_row_id=(key_expected->'reservation'->>'storage_row_id')::bigint;
   IF actual_reservation IS DISTINCT FROM key_expected->'reservation' THEN RAISE EXCEPTION 'original creation reservation required' USING ERRCODE='55000';END IF;
   SELECT generation INTO current_generation FROM truss.key_bucket_guard
    WHERE namespace_sha256=decode(substring(key_expected->'membership'->>'namespace_sha256' FROM 3),'hex')
     AND key_sha256=decode(substring(key_expected->'membership'->>'key_sha256' FROM 3),'hex');
   IF current_generation IS NULL OR current_generation<(key_expected->>'generation')::bigint THEN
    RAISE EXCEPTION 'original creation key generation required' USING ERRCODE='55000';END IF;
  END LOOP;
  RETURN;
 END IF;
 IF (expected->'object'->>'id')::bigint<>selected_id OR (expected->'object'->>'type_id')::int<>selected_type THEN
  RAISE EXCEPTION 'exact operation member required' USING ERRCODE='55000'; END IF;
 SELECT to_jsonb(o) INTO actual_object FROM truss.object o WHERE id=selected_id AND type_id=selected_type;
 IF actual_object IS DISTINCT FROM expected->'object' THEN
  RAISE EXCEPTION 'complete created object changed or missing' USING ERRCODE='55000'; END IF;
 SELECT to_jsonb(j) INTO actual_journal FROM truss.journal j WHERE j.at=(expected->'journal'->>'at')::timestamptz
  AND j.seq=(expected->'journal'->>'seq')::bigint;
 IF actual_journal IS DISTINCT FROM expected->'journal' OR (SELECT count(*) FROM truss.journal WHERE entity_kind='o' AND entity_id=selected_id AND entity_type=selected_type AND xid=group_row.writer_xid)<>1 THEN
  RAISE EXCEPTION 'complete create journal changed or missing' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM truss.object_key_bucket WHERE object_id=selected_id AND type_id=selected_type)
  <>jsonb_array_length(expected->'keys') THEN
  RAISE EXCEPTION 'complete created key membership required' USING ERRCODE='55000'; END IF;
 FOR key_expected IN SELECT value FROM jsonb_array_elements(expected->'keys') LOOP
  SELECT to_jsonb(k) INTO actual_key FROM truss.object_key_bucket k WHERE storage_row_id=(key_expected->'membership'->>'storage_row_id')::bigint;
  SELECT to_jsonb(r) INTO actual_reservation FROM truss.object_key_reservation_bucket r WHERE storage_row_id=(key_expected->'reservation'->>'storage_row_id')::bigint;
  SELECT generation INTO current_generation FROM truss.key_bucket_guard WHERE namespace_sha256=decode(substring(actual_key->>'namespace_sha256' FROM 3),'hex') AND key_sha256=decode(substring(actual_key->>'key_sha256' FROM 3),'hex');
  IF current_generation IS NULL OR current_generation<(key_expected->>'generation')::bigint OR actual_key IS DISTINCT FROM key_expected->'membership' OR actual_reservation IS DISTINCT FROM key_expected->'reservation'
   OR NOT truss.verify_object_string_key(selected_id,selected_type,(actual_key->>'key_num')::smallint,
     decode(substring(convert_from(decode(substring(actual_key->>'key_bytes' FROM 3),'hex'),'UTF8') FROM 22),'hex')) THEN
   RAISE EXCEPTION 'exact created key or reservation required' USING ERRCODE='55000'; END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_current_installation()
 RETURNS SETOF truss.catalog_runtime_installation
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;
BEGIN
 SELECT * INTO STRICT installation FROM truss.catalog_runtime_installation;
 RETURN NEXT installation;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_edge_authorize(selected_attempt uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE entry jsonb;selected_transition bigint;completed boolean;context jsonb;revision text;current_actor oid;
BEGIN
 SELECT complete INTO STRICT completed FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 current_actor:=truss.runtime_person(false);
 FOR context,revision IN SELECT DISTINCT i.value,t.endpoint_ownership->>'captureCatalogRevision' FROM truss.runtime_edge_transition t
  CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(t.endpoint_ownership->'before'->'source',t.endpoint_ownership->'before'->'target',
   t.endpoint_ownership->'after'->'source',t.endpoint_ownership->'after'->'target')) i
  WHERE t.attempt_id=selected_attempt AND i.value<>'null'::jsonb LOOP
  IF NOT truss.runtime_can_read_qualified(context->'identity'->'owner'->>'documentId',context->'identity'->'owner'->>'moduleId',current_actor) THEN
   RAISE EXCEPTION 'original endpoint context reader required' USING ERRCODE='42501';END IF;
  PERFORM truss.runtime_history_ownership_qualified(jsonb_build_object('identity',context->'identity','catalogRevision',revision,'ownership',context->'ownership'),current_actor);
 END LOOP;
 FOR entry IN SELECT DISTINCT i.value FROM truss.runtime_edge_transition t
  CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(t.old_source,t.old_target,t.source_identity,t.target_identity)) i
  WHERE t.attempt_id=selected_attempt AND i.value<>'null'::jsonb LOOP
  IF NOT truss.runtime_can_read_qualified(entry->'owner'->>'documentId',entry->'owner'->>'moduleId',current_actor) THEN RAISE EXCEPTION 'original endpoint reader required' USING ERRCODE='42501';END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_edge_effect(attempt_id uuid, operation_index integer, metadata jsonb, effect_operation text, advance boolean, qualified_actor oid DEFAULT NULL::oid, prepared_input jsonb DEFAULT NULL::jsonb, source_bytes bytea DEFAULT NULL::bytea)
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;operation jsonb;input jsonb;row_image truss.edge%ROWTYPE;
 identity jsonb;before_image jsonb;after_image jsonb;before_record jsonb;after_record jsonb;result jsonb;event jsonb;
 installation truss.catalog_runtime_installation%ROWTYPE;journal truss.journal%ROWTYPE;event_refs jsonb;revision int;version bigint;entry jsonb;ownership_context jsonb;selected_history text;current_actor oid;changed_rows bigint;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id;
 current_actor:=coalesce(qualified_actor,truss.runtime_person(false));
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM current_actor
  OR attempt.complete OR attempt.next_index IS DISTINCT FROM operation_index THEN
  RAISE EXCEPTION 'current original edge effect progress required' USING ERRCODE='55000';END IF;
 IF attempt.context->'mutationProfile'=truss.runtime_owned_profile() THEN
  SELECT p.plan->'operation' INTO STRICT operation FROM truss.runtime_owned_operation p
   WHERE p.attempt_id=attempt.id AND p.operation_index=runtime_edge_effect.operation_index;
  input:=jsonb_build_object('mutationProfile',attempt.context->'mutationProfile','assertedOrigin',attempt.context->'originalAssertedOrigin');
 ELSE
  input:=coalesce(prepared_input,convert_from(attempt.input_bytes,'UTF8')::jsonb);operation:=input->'operations'->operation_index;
 END IF;
 IF effect_operation IS NULL OR effect_operation NOT IN ('create_edge','update_edge','delete_edge') OR advance IS NULL THEN
  RAISE EXCEPTION 'explicit native edge effect required' USING ERRCODE='55000';END IF;
 IF input->'mutationProfile'=truss.runtime_owned_profile() THEN
  IF advance THEN RAISE EXCEPTION 'owned parent alone advances original progress' USING ERRCODE='55000';END IF;
 ELSE
  IF NOT advance OR effect_operation IS DISTINCT FROM operation->>'operation' OR metadata ? 'ownedReference' THEN
   RAISE EXCEPTION 'original independent edge operation required' USING ERRCODE='55000';END IF;
 END IF;
 selected_history:=CASE WHEN input->'mutationProfile'=truss.runtime_owned_profile() THEN 'truss-native-owned-edge-mutation/0.1' ELSE 'truss-native-edge-mutation/0.1' END;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 before_image:=nullif(metadata->'prior','null'::jsonb);identity:=metadata->'identity';
 ownership_context:=jsonb_build_object('profile','truss-edge-endpoint-ownership/0.1','captureCatalogRevision',revision::text,
  'before',CASE WHEN before_image IS NULL THEN NULL ELSE jsonb_build_object('source',truss.runtime_endpoint_ownership(metadata->'oldSource',revision),'target',truss.runtime_endpoint_ownership(metadata->'oldTarget',revision)) END,
  'after',NULL);
 IF effect_operation='create_edge' THEN
  row_image.id:=nextval('truss.id_seq');row_image.rel_type_id:=(metadata->>'typeId')::int;row_image.props:='{}';
  row_image.ver:=1;row_image.created_at:=clock_timestamp();
  identity:=jsonb_build_object('id',row_image.id::text,'typeId',row_image.rel_type_id::text,'definitionPin',operation->>'relationshipDefinitionPin',
   'owner',jsonb_build_object('documentId',metadata->>'documentId','moduleId',metadata->>'moduleId'));
 ELSE row_image:=jsonb_populate_record(NULL::truss.edge,before_image);END IF;
 IF effect_operation='update_edge' AND row_image.source_id::text=metadata->'source'->>'id'
  AND row_image.source_type::text=metadata->'source'->>'typeId' AND row_image.target_id::text=metadata->'target'->>'id'
  AND row_image.target_type::text=metadata->'target'->>'typeId' AND coalesce(row_image.retained,'{}')=metadata->'retained'
  AND row_image.order_key IS NOT DISTINCT FROM metadata->'orderKey'->>'text' THEN
  result:=jsonb_build_object('outcome','unchanged','operation','update_edge','identity',identity,'version',row_image.ver::text,'events','[]'::jsonb);
  ownership_context:=jsonb_set(ownership_context,'{after}',CASE WHEN effect_operation='delete_edge' THEN 'null'::jsonb ELSE jsonb_build_object('source',truss.runtime_endpoint_ownership(metadata->'source',revision),'target',truss.runtime_endpoint_ownership(metadata->'target',revision)) END);
  INSERT INTO truss.runtime_edge_transition(attempt_id,operation_index,writer_xid,edge_id,rel_type_id,before_edge,after_edge,journal,old_source,old_target,source_identity,target_identity,endpoint_ownership)
   VALUES(attempt_id,operation_index,attempt.writer_xid,row_image.id,row_image.rel_type_id,before_image,before_image,'[]'::jsonb,metadata->'oldSource',metadata->'oldTarget',metadata->'source',metadata->'target',ownership_context);
 ELSE
  IF before_image IS NOT NULL THEN
   IF row_image.ver=9223372036854775807 THEN RAISE EXCEPTION 'edge version exhausted' USING ERRCODE='54000';END IF;
   before_record:=truss.runtime_edge_history(before_image,identity,metadata->'oldSource',metadata->'oldTarget');row_image.ver:=row_image.ver+1;
  END IF;
  version:=row_image.ver;row_image.rev:=revision;row_image.updated_at:=clock_timestamp();
  IF before_image IS NOT NULL AND (effect_operation='delete_edge' OR metadata->'source' IS DISTINCT FROM metadata->'oldSource' OR metadata->'target' IS DISTINCT FROM metadata->'oldTarget') THEN
   INSERT INTO truss.key_tombstone(entity_kind,type_id,key_num,k,entity_id,ver) VALUES('e',row_image.rel_type_id,0,truss.runtime_edge_business_key(row_image.rel_type_id,metadata->'oldSource',metadata->'oldTarget'),row_image.id,version) ON CONFLICT DO NOTHING;
  END IF;
  row_image.source_id:=(metadata->'source'->>'id')::bigint;row_image.source_type:=(metadata->'source'->>'typeId')::int;
  row_image.target_id:=(metadata->'target'->>'id')::bigint;row_image.target_type:=(metadata->'target'->>'typeId')::int;
  row_image.retained:=nullif(metadata->'retained','{}'::jsonb);row_image.order_key:=metadata->'orderKey'->>'text';
  IF effect_operation='delete_edge' THEN
   DELETE FROM truss.edge WHERE id=row_image.id AND rel_type_id=row_image.rel_type_id AND ver=(before_image->>'ver')::bigint;
   GET DIAGNOSTICS changed_rows=ROW_COUNT;
   IF changed_rows<>1 THEN RAISE EXCEPTION 'original edge version required' USING ERRCODE='55000';END IF;
   event:=jsonb_build_object('operation','delete','before',before_record);
  ELSE
   after_image:=to_jsonb(row_image);after_record:=truss.runtime_edge_history(after_image,identity,metadata->'source',metadata->'target');
   IF before_image IS NULL THEN
    INSERT INTO truss.edge SELECT (row_image).*;
    GET DIAGNOSTICS changed_rows=ROW_COUNT;
    IF changed_rows<>1 THEN RAISE EXCEPTION 'one original edge creation required' USING ERRCODE='55000';END IF;
    event:=jsonb_build_object('operation','create','after',after_record);
   ELSE
    UPDATE truss.edge SET source_id=row_image.source_id,source_type=row_image.source_type,target_id=row_image.target_id,target_type=row_image.target_type,
     retained=row_image.retained,order_key=row_image.order_key,rev=row_image.rev,ver=row_image.ver,updated_at=row_image.updated_at WHERE id=row_image.id AND rel_type_id=row_image.rel_type_id AND ver=(before_image->>'ver')::bigint;
    GET DIAGNOSTICS changed_rows=ROW_COUNT;
    IF changed_rows<>1 THEN RAISE EXCEPTION 'original edge version required' USING ERRCODE='55000';END IF;
    event:=jsonb_build_object('operation','metadata','before',before_record,'after',after_record);
   END IF;
  END IF;
  event:=event||jsonb_build_object('interfaceVersion','truss-history-event/0.2.0-proposal','sourceEpoch',installation.source_epoch::text,
   'historyProfile',selected_history,'xid',attempt.writer_xid::text,'seq',nextval('truss.journal_seq')::text,
   'identity',identity,'eventVersion',version::text,'eventCatalogRevision',revision::text,
   'origin',jsonb_build_object('asserted',input->'assertedOrigin','databaseRole',session_user::text));
  event:=event||jsonb_build_object('mutationGroup',jsonb_build_object('profile','truss-history-group/0.1.0','eventCount','1',
   'orderedEventDigest',encode(sha256(convert_to(jsonb_build_array(event)::text,'UTF8')),'hex')));
  journal.seq:=(event->>'seq')::bigint;journal.at:=clock_timestamp();journal.xid:=attempt.writer_xid;journal.entity_kind:='e';journal.entity_id:=row_image.id;
  journal.entity_type:=row_image.rel_type_id;journal.ver:=version;journal.op:=event->>'operation';journal.prop_id:=NULL;journal.old_value:=NULL;
  journal.new_value:=truss.runtime_exact_wrapper('event',convert_to(event::text,'UTF8'));journal.rev:=revision;
  journal.origin:=truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8'));
  INSERT INTO truss.journal SELECT (journal).*;
  ownership_context:=jsonb_set(ownership_context,'{after}',CASE WHEN effect_operation='delete_edge' THEN 'null'::jsonb ELSE jsonb_build_object('source',truss.runtime_endpoint_ownership(metadata->'source',revision),'target',truss.runtime_endpoint_ownership(metadata->'target',revision)) END);
  INSERT INTO truss.runtime_edge_transition(attempt_id,operation_index,writer_xid,edge_id,rel_type_id,before_edge,after_edge,journal,old_source,old_target,source_identity,target_identity,endpoint_ownership)
   VALUES(attempt_id,operation_index,attempt.writer_xid,row_image.id,row_image.rel_type_id,before_image,after_image,jsonb_build_array(to_jsonb(journal)),
    metadata->'oldSource',metadata->'oldTarget',metadata->'source',metadata->'target',ownership_context);
  event_refs:=jsonb_build_array(jsonb_build_object('sourceEpoch',installation.source_epoch::text,'historyProfile',selected_history,'xid',attempt.writer_xid::text,'seq',journal.seq::text));
  IF effect_operation='create_edge' THEN result:=jsonb_build_object('outcome','created','operation','create_edge','identity',identity,'version',version::text,'events',event_refs);
   IF operation ? 'alias' THEN result:=result||jsonb_build_object('alias',operation->>'alias');END IF;
  ELSIF effect_operation='update_edge' THEN result:=jsonb_build_object('outcome','changed','operation','update_edge','identity',identity,'version',version::text,'events',event_refs);
  ELSE result:=jsonb_build_object('outcome','deleted','operation','delete_edge','identity',identity,'deletionVersion',version::text,
   'deleted',jsonb_build_array(jsonb_build_object('identity',identity,'deletionVersion',version::text)),'events',event_refs);END IF;
 END IF;
 -- The legacy route settles itself; owned groups settle distinct authority once.
 IF advance THEN
 current_actor:=truss.runtime_person(false);
 PERFORM truss.runtime_module_writer_qualified(metadata->>'documentId',metadata->>'moduleId',current_actor);
 FOR entry IN SELECT value FROM jsonb_array_elements(jsonb_build_array(metadata->'oldSource',metadata->'oldTarget',metadata->'source',metadata->'target')) WHERE value<>'null'::jsonb LOOP
  IF NOT truss.runtime_can_read_qualified(entry->'owner'->>'documentId',entry->'owner'->>'moduleId',current_actor) THEN RAISE EXCEPTION 'endpoint reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 END IF;
 IF advance THEN
 UPDATE truss.runtime_object_attempt SET next_index=next_index+1,results=results||jsonb_build_array(result),
  aliases=aliases||CASE WHEN effect_operation='create_edge' AND operation ? 'alias' THEN jsonb_build_array(jsonb_build_object('alias',operation->>'alias','identity',identity)) ELSE '[]'::jsonb END WHERE id=attempt_id;
 END IF;
 RETURN convert_to(result::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_edge_endpoint(reference jsonb, attempt_id uuid, operation_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;operations jsonb;identity jsonb;selected truss.type_def%ROWTYPE;object_row truss.object%ROWTYPE;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id;
 operations:=convert_from(attempt.input_bytes,'UTF8')::jsonb->'operations';
 IF reference->>'state'='stored' AND reference-ARRAY['state','identity']='{}'::jsonb THEN identity:=reference->'identity';
 ELSIF reference->>'state'='alias' AND reference-ARRAY['state','alias']='{}'::jsonb THEN
  IF (SELECT count(*) FROM jsonb_array_elements(operations) WITH ORDINALITY o(value,ord)
   WHERE ord<=operation_index AND value->>'operation'='create_object' AND value->>'alias'=reference->>'alias')<>1 THEN
   RAISE EXCEPTION 'prior object endpoint alias required' USING ERRCODE='22023';END IF;
  SELECT value->'identity' INTO STRICT identity FROM jsonb_array_elements(attempt.aliases) WHERE value->>'alias'=reference->>'alias';
 ELSE RAISE EXCEPTION 'qualified object endpoint required' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(identity->'typeId') IS DISTINCT FROM 'string' OR jsonb_typeof(identity->'definitionPin') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'exact object endpoint identity required' USING ERRCODE='22023';END IF;
 selected:=truss.runtime_condition_type(identity);IF NOT truss.runtime_can_read(selected.document_id,selected.module) THEN RAISE EXCEPTION 'endpoint reader required' USING ERRCODE='42501';END IF;
 SELECT * INTO object_row FROM truss.object WHERE id=(identity->>'id')::bigint AND type_id=selected.type_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'endpoint absent' USING ERRCODE='P1004';END IF;
 IF object_row.root_id IS NOT NULL THEN
  RAISE EXCEPTION 'rootless endpoint required' USING ERRCODE='0A000';END IF;
 RETURN identity;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_edge_history(image jsonb, identity jsonb, source_identity jsonb, target_identity jsonb, interpretation_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE selected_revision int:=coalesce(interpretation_revision,(image->>'rev')::int);pin record;
BEGIN
 identity:=jsonb_set(identity,'{definitionPin}',to_jsonb(truss.runtime_relationship_pin((image->>'rel_type_id')::int,selected_revision)));
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',(source_identity->>'typeId')::int,NULL,selected_revision);
 source_identity:=jsonb_set(source_identity,'{definitionPin}',to_jsonb(pin.definition_pin));
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',(target_identity->>'typeId')::int,NULL,selected_revision);
 target_identity:=jsonb_set(target_identity,'{definitionPin}',to_jsonb(pin.definition_pin));
 RETURN jsonb_build_object('interfaceVersion','truss-history-record/0.1.0','kind','edge','identity',identity,
  'recordVersion',image->>'ver','catalogRevision',image->>'rev',
  'createdAt',to_char((image->>'created_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'updatedAt',to_char((image->>'updated_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'properties','[]'::jsonb,'retained',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',key,'value',value) ORDER BY key COLLATE "C"),'[]'::jsonb)
    FROM jsonb_each(coalesce(nullif(image->'retained','null'::jsonb),'{}'))),
  'source',source_identity,'target',target_identity,'orderKey',CASE WHEN image->>'order_key' IS NULL THEN '{"state":"null"}'::jsonb ELSE jsonb_build_object('state','text','text',image->>'order_key') END);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_edge_metadata(attempt_id uuid, operation_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;operation jsonb;relation truss.rel_def%ROWTYPE;
 identity jsonb;prior truss.edge%ROWTYPE;source_identity jsonb;target_identity jsonb;old_source jsonb;old_target jsonb;
 values jsonb;retained jsonb;set_retained jsonb;unset_names text[];order_key jsonb;endpoint truss.type_def%ROWTYPE;pin record;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id FOR UPDATE NOWAIT;
 IF attempt.writer_xid<>pg_current_xact_id() OR attempt.actor_oid<>truss.runtime_person(false) OR attempt.complete OR attempt.next_index<>operation_index THEN
  RAISE EXCEPTION 'current ordered edge attempt required' USING ERRCODE='55000';END IF;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;operation:=input->'operations'->operation_index;
 IF operation->>'operation'<>'create_edge' AND ((operation->'target'->>'state'='stored' AND (operation->'target')-ARRAY['state','identity']<>'{}'::jsonb)
  OR (operation->'target'->>'state'='alias' AND ((operation->'target')-ARRAY['state','alias']<>'{}'::jsonb OR jsonb_typeof(operation->'target'->'alias') IS DISTINCT FROM 'string'))) THEN
  RAISE EXCEPTION 'closed exact edge reference required' USING ERRCODE='22023';END IF;
 relation:=truss.runtime_operation_relationship(operation,input->'operations',operation_index);
 PERFORM truss.runtime_module_writer(relation.document_id,relation.module);
 IF relation.lifecycle<>'independent' OR NOT relation.directed OR relation.composition OR relation.assoc_type_id IS NOT NULL THEN
  RAISE EXCEPTION 'directed independent relationship required' USING ERRCODE='0A000';END IF;
 IF operation->>'operation'='create_edge' THEN
  IF operation-ARRAY['operation','relationshipDefinitionPin','source','target','values','orderKey','alias']<>'{}'::jsonb
   OR operation ? 'alias' AND (jsonb_typeof(operation->'alias') IS DISTINCT FROM 'string' OR octet_length(operation->>'alias') NOT BETWEEN 1 AND 1024) THEN
   RAISE EXCEPTION 'closed edge create required' USING ERRCODE='22023';END IF;
  retained:='{}';values:=operation->'values';order_key:=operation->'orderKey';
  source_identity:=truss.runtime_edge_endpoint(operation->'source',attempt_id,operation_index);
  target_identity:=truss.runtime_edge_endpoint(operation->'target',attempt_id,operation_index);
 ELSE
  IF operation->'target'->>'state'='stored' THEN identity:=operation->'target'->'identity';
  ELSE SELECT value->'identity' INTO STRICT identity FROM jsonb_array_elements(attempt.aliases) WHERE value->>'alias'=operation->'target'->>'alias';END IF;
  SELECT * INTO prior FROM truss.edge WHERE id=(identity->>'id')::bigint AND rel_type_id=relation.rel_type_id FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'edge absent' USING ERRCODE='P1004';END IF;
  IF operation ? 'expectedVersion' AND (jsonb_typeof(operation->'expectedVersion') IS DISTINCT FROM 'string' OR operation->>'expectedVersion' IS DISTINCT FROM prior.ver::text) THEN
   RAISE EXCEPTION 'expected edge version failed' USING ERRCODE='P1003';END IF;
  SELECT * INTO STRICT endpoint FROM truss.type_def WHERE type_id=prior.source_type;
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',endpoint.type_id);
  old_source:=jsonb_build_object('id',prior.source_id::text,'typeId',prior.source_type::text,'definitionPin',pin.definition_pin,'owner',jsonb_build_object('documentId',endpoint.document_id,'moduleId',endpoint.module));
  SELECT * INTO STRICT endpoint FROM truss.type_def WHERE type_id=prior.target_type;
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',endpoint.type_id);
  old_target:=jsonb_build_object('id',prior.target_id::text,'typeId',prior.target_type::text,'definitionPin',pin.definition_pin,'owner',jsonb_build_object('documentId',endpoint.document_id,'moduleId',endpoint.module));
  source_identity:=truss.runtime_edge_endpoint(jsonb_build_object('state','stored','identity',old_source),attempt_id,operation_index);
  target_identity:=truss.runtime_edge_endpoint(jsonb_build_object('state','stored','identity',old_target),attempt_id,operation_index);
  IF prior.props<>'{}'::jsonb THEN RAISE EXCEPTION 'untyped retained edge values required' USING ERRCODE='0A000';END IF;
  retained:=coalesce(prior.retained,'{}');order_key:=CASE WHEN prior.order_key IS NULL THEN '{"state":"null"}'::jsonb ELSE jsonb_build_object('state','text','text',prior.order_key) END;
  IF operation->>'operation'='delete_edge' THEN
   IF operation-ARRAY['operation','target','expectedVersion']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed edge delete required' USING ERRCODE='22023';END IF;
   values:='[]';
  ELSE
   IF operation-ARRAY['operation','target','set','unset','expectedVersion','endpointChange','orderKeyChange']<>'{}'::jsonb
    OR jsonb_typeof(operation->'unset') IS DISTINCT FROM 'array' OR jsonb_array_length(operation->'unset')>1024
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(operation->'unset') u WHERE jsonb_typeof(value) IS DISTINCT FROM 'string' OR octet_length(value#>>'{}') NOT BETWEEN 1 AND 4096)
    OR jsonb_array_length(operation->'unset')<>(SELECT count(DISTINCT value) FROM jsonb_array_elements(operation->'unset')) THEN
    RAISE EXCEPTION 'closed bounded edge update required' USING ERRCODE='22023';END IF;
   values:=operation->'set';
   SELECT coalesce(array_agg(value#>>'{}'),'{}'::text[]) INTO unset_names FROM jsonb_array_elements(operation->'unset');
   retained:=retained-unset_names;
   IF operation ? 'endpointChange' THEN
    IF (operation->'endpointChange')-ARRAY['source','target']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed endpoint change required' USING ERRCODE='22023';END IF;
    source_identity:=truss.runtime_edge_endpoint(operation->'endpointChange'->'source',attempt_id,operation_index);
    target_identity:=truss.runtime_edge_endpoint(operation->'endpointChange'->'target',attempt_id,operation_index);
   END IF;
   IF operation ? 'orderKeyChange' THEN order_key:=operation->'orderKeyChange';END IF;
  END IF;
 END IF;
 IF jsonb_typeof(values) IS DISTINCT FROM 'array' OR jsonb_array_length(values)>1024
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(values) v WHERE value-ARRAY['name','value']<>'{}'::jsonb
   OR jsonb_typeof(value->'name') IS DISTINCT FROM 'string' OR octet_length(value->>'name') NOT BETWEEN 1 AND 4096 OR truss.valid_scalar_cell(value->'value') IS NOT TRUE)
  OR jsonb_array_length(values)<>(SELECT count(DISTINCT value->>'name') FROM jsonb_array_elements(values))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(values) v JOIN jsonb_array_elements(coalesce(operation->'unset','[]')) u ON v.value->>'name'=u.value#>>'{}') THEN
  RAISE EXCEPTION 'unique disjoint exact edge values required' USING ERRCODE='22023';END IF;
 SELECT coalesce(jsonb_object_agg(v.value->>'name',truss.canonical_flat_cell(v.value->'value')),'{}'::jsonb)
  INTO set_retained FROM jsonb_array_elements(values) v;
 retained:=retained||set_retained;
 IF (order_key='{"state":"null"}'::jsonb OR order_key->>'state'='text' AND jsonb_typeof(order_key->'text')='string'
  AND order_key-ARRAY['state','text']='{}'::jsonb AND octet_length(order_key->>'text')<=4096) IS NOT TRUE THEN
  RAISE EXCEPTION 'exact bounded order key required' USING ERRCODE='22023';END IF;
 PERFORM truss.runtime_lock_edge_business_key(truss.runtime_edge_business_key(relation.rel_type_id,source_identity,target_identity));
 IF old_source IS NOT NULL THEN PERFORM truss.runtime_lock_edge_business_key(truss.runtime_edge_business_key(relation.rel_type_id,old_source,old_target));END IF;
 IF NOT EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND source_type=(source_identity->>'typeId')::int AND target_type=(target_identity->>'typeId')::int) THEN
  RAISE EXCEPTION 'admitted endpoint pair required' USING ERRCODE='22023';END IF;
 IF octet_length(convert_to(retained::text,'UTF8'))>1048576 THEN RAISE EXCEPTION 'bounded edge values required' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module,'typeId',relation.rel_type_id::text,
  'identity',identity,'prior',CASE WHEN prior.id IS NULL THEN NULL ELSE to_jsonb(prior) END,
  'source',source_identity,'target',target_identity,'oldSource',old_source,'oldTarget',old_target,
  'retained',retained,'orderKey',order_key,'keys','[]'::jsonb,'values','[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_edge_read(selected_document text, selected_module text, selected_relationship text, selected_id bigint, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE relation truss.rel_def%ROWTYPE;edge_row truss.edge%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;
 source_identity jsonb;target_identity jsonb;endpoint truss.type_def%ROWTYPE;frozen record;entry jsonb;obj jsonb;root_row jsonb;root_def jsonb;root_owners jsonb:='[]';pin record;identity jsonb;result bytea;captured_revision int;
BEGIN
 PERFORM truss.runtime_person(false);
 IF selected_id IS NULL OR selected_id<1 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN RAISE EXCEPTION 'bounded edge selection required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'selected edge runtime required' USING ERRCODE='0A000';END IF;
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 IF NOT truss.runtime_can_read(selected_document,selected_module) THEN RETURN NULL;END IF;
 SELECT * INTO relation FROM truss.rel_def WHERE document_id=selected_document AND module=selected_module AND rel_id=selected_relationship AND retired_rev IS NULL;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Freeze the edge, endpoint rows and their aggregate roots in one statement snapshot.
 SELECT e AS edge,s AS source,t AS target,st AS source_definition,tt AS target_definition,
  sr AS source_root,tr AS target_root,srt AS source_root_definition,trt AS target_root_definition
 INTO frozen FROM truss.edge e
 JOIN truss.object s ON s.id=e.source_id AND s.type_id=e.source_type
 JOIN truss.object t ON t.id=e.target_id AND t.type_id=e.target_type
 JOIN truss.type_def st ON st.type_id=s.type_id AND st.retired_rev IS NULL
 JOIN truss.type_def tt ON tt.type_id=t.type_id AND tt.retired_rev IS NULL
 LEFT JOIN truss.object sr ON sr.id=s.root_id AND sr.type_id=s.root_type
 LEFT JOIN truss.object tr ON tr.id=t.root_id AND tr.type_id=t.root_type
 LEFT JOIN truss.type_def srt ON srt.type_id=sr.type_id AND srt.retired_rev IS NULL
 LEFT JOIN truss.type_def trt ON trt.type_id=tr.type_id AND trt.retired_rev IS NULL
 WHERE e.id=selected_id AND e.rel_type_id=relation.rel_type_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 edge_row:=frozen.edge;
 IF relation.lifecycle NOT IN ('independent','owned') OR NOT relation.directed OR relation.composition OR relation.assoc_type_id IS NOT NULL OR edge_row.props<>'{}'::jsonb THEN RAISE EXCEPTION 'selected directed scalar edge required' USING ERRCODE='0A000';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
  jsonb_build_object('object',to_jsonb(frozen.source),'definition',to_jsonb(frozen.source_definition),'root',to_jsonb(frozen.source_root),'rootDefinition',to_jsonb(frozen.source_root_definition)),
  jsonb_build_object('object',to_jsonb(frozen.target),'definition',to_jsonb(frozen.target_definition),'root',to_jsonb(frozen.target_root),'rootDefinition',to_jsonb(frozen.target_root_definition)))) LOOP
  obj:=entry->'object';endpoint:=jsonb_populate_record(NULL::truss.type_def,entry->'definition');
  IF endpoint.kind<>'record' OR endpoint.provisional OR (obj->>'rev')::int>captured_revision OR endpoint.since_rev>captured_revision THEN RAISE EXCEPTION 'current endpoint catalog required' USING ERRCODE='55P03';END IF;
  IF NOT truss.runtime_can_read(endpoint.document_id,endpoint.module) THEN RETURN NULL;END IF;
  IF obj->>'root_id' IS NOT NULL OR obj->>'root_type' IS NOT NULL THEN
   root_row:=entry->'root';root_def:=entry->'rootDefinition';
   IF obj->>'root_id' IS NULL OR obj->>'root_type' IS NULL OR root_row->>'id' IS NULL OR root_def->>'type_id' IS NULL
    OR root_row->>'root_id' IS NOT NULL OR root_row->>'root_type' IS NOT NULL
    OR root_row->>'id'=obj->>'id' AND root_row->>'type_id'=obj->>'type_id'
    OR root_def->>'kind'<>'record' OR (root_def->>'provisional')::boolean THEN RAISE EXCEPTION 'current endpoint aggregate root required' USING ERRCODE='55000';END IF;
   IF (root_row->>'rev')::int>captured_revision OR (root_def->>'since_rev')::int>captured_revision THEN RAISE EXCEPTION 'endpoint root catalog changed' USING ERRCODE='55P03';END IF;
   IF NOT truss.runtime_can_read(root_def->>'document_id',root_def->>'module') THEN RETURN NULL;END IF;
   root_owners:=root_owners||jsonb_build_array(jsonb_build_object('documentId',root_def->>'document_id','moduleId',root_def->>'module'));
  END IF;
 END LOOP;
 endpoint:=frozen.source_definition;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',endpoint.type_id);
 source_identity:=jsonb_build_object('id',edge_row.source_id::text,'typeId',endpoint.type_id::text,'definitionPin',pin.definition_pin,'owner',jsonb_build_object('documentId',endpoint.document_id,'moduleId',endpoint.module));
 endpoint:=frozen.target_definition;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',endpoint.type_id);
 target_identity:=jsonb_build_object('id',edge_row.target_id::text,'typeId',endpoint.type_id::text,'definitionPin',pin.definition_pin,'owner',jsonb_build_object('documentId',endpoint.document_id,'moduleId',endpoint.module));
 identity:=jsonb_build_object('id',edge_row.id::text,'typeId',relation.rel_type_id::text,'definitionPin',truss.runtime_relationship_pin(relation.rel_type_id),'owner',jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module));
 result:=convert_to((truss.runtime_edge_history(to_jsonb(edge_row),identity,source_identity,target_identity,captured_revision)||jsonb_build_object('executedCatalogRevision',captured_revision::text))::text,'UTF8');
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'bounded complete edge required' USING ERRCODE='54000';END IF;
 IF NOT truss.runtime_can_read(relation.document_id,relation.module) OR NOT truss.runtime_can_read(source_identity->'owner'->>'documentId',source_identity->'owner'->>'moduleId')
  OR NOT truss.runtime_can_read(target_identity->'owner'->>'documentId',target_identity->'owner'->>'moduleId') THEN RAISE EXCEPTION 'current edge reader required' USING ERRCODE='42501';END IF;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN RAISE EXCEPTION 'edge catalog changed' USING ERRCODE='55P03';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(root_owners) LOOP
  IF NOT truss.runtime_can_read(entry->>'documentId',entry->>'moduleId') THEN RAISE EXCEPTION 'current endpoint root reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN jsonb_build_object('edge',convert_from(result,'UTF8')::jsonb,'rootOwners',root_owners);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_endpoint_ownership(identity jsonb, captured_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE endpoint truss.object%ROWTYPE;root_object truss.object%ROWTYPE;endpoint_type truss.type_def%ROWTYPE;root_type truss.type_def%ROWTYPE;pin record;ownership jsonb;
BEGIN
 IF captured_revision<1 OR (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN
  RAISE EXCEPTION 'current ownership observation revision required' USING ERRCODE='55P03';END IF;
 IF identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb OR jsonb_typeof(identity->'owner') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'exact endpoint identity required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT endpoint_type FROM truss.type_def WHERE type_id=(identity->>'typeId')::int AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',endpoint_type.type_id,NULL,captured_revision);
 IF identity->>'definitionPin' IS DISTINCT FROM pin.definition_pin OR identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',endpoint_type.document_id,'moduleId',endpoint_type.module) THEN
  RAISE EXCEPTION 'original endpoint definition correspondence required' USING ERRCODE='22023';END IF;
 IF NOT truss.runtime_can_read(endpoint_type.document_id,endpoint_type.module) THEN RAISE EXCEPTION 'endpoint reader required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT endpoint FROM truss.object WHERE id=(identity->>'id')::bigint AND type_id=endpoint_type.type_id;
 IF (endpoint.root_id IS NULL) IS DISTINCT FROM (endpoint.root_type IS NULL) THEN RAISE EXCEPTION 'complete root pair required' USING ERRCODE='55000';END IF;
 ownership:='{"state":"rootless"}';
 IF endpoint.root_id IS NOT NULL THEN
  SELECT * INTO STRICT root_type FROM truss.type_def WHERE type_id=endpoint.root_type AND kind='record' AND NOT provisional AND retired_rev IS NULL;
  IF NOT truss.runtime_can_read(root_type.document_id,root_type.module) THEN RAISE EXCEPTION 'aggregate root reader required' USING ERRCODE='42501';END IF;
  SELECT * INTO STRICT root_object FROM truss.object WHERE id=endpoint.root_id AND type_id=endpoint.root_type;
  IF root_object.root_id IS NOT NULL OR root_object.root_type IS NOT NULL OR root_object.id=endpoint.id AND root_object.type_id=endpoint.type_id THEN
   RAISE EXCEPTION 'live rootless aggregate root required' USING ERRCODE='22023';END IF;
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',root_type.type_id,NULL,captured_revision);
  ownership:=jsonb_build_object('state','owned','root',jsonb_build_object('id',root_object.id::text,'typeId',root_type.type_id::text,'definitionPin',pin.definition_pin,
    'owner',jsonb_build_object('documentId',root_type.document_id,'moduleId',root_type.module)));
 END IF;
 RETURN jsonb_build_object('identity',identity,'ownership',ownership);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_evaluate_preconditions(input jsonb, original_keys bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE evaluated jsonb;failures jsonb;
BEGIN
 evaluated:=truss.runtime_evaluate_preconditions_core(input,original_keys,true);
 failures:=evaluated->'failures';
 IF failures<>'[]'::jsonb THEN
  RAISE EXCEPTION 'caller preconditions failed' USING ERRCODE='P1006',DETAIL=jsonb_build_object('outcome','failed','code','precondition_failed','failures',failures)::text;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_evaluate_preconditions_core(input jsonb, original_keys bytea, lock_state boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE inventory jsonb;entry jsonb;condition jsonb;owner record;target record;current_object truss.object%ROWTYPE;key_tuples bytea[];key_tuple bytea;
 installation truss.catalog_runtime_installation%ROWTYPE;pin record;ns bytea;transport bytea;tuple_bytes bytea;values_text text[];key_facets jsonb;observed record;passed boolean;counted bigint;
 failure_buffer jsonb[]:=ARRAY[]::jsonb[];condition_buffer jsonb[]:=ARRAY[]::jsonb[];failures jsonb;receipt jsonb;scope jsonb;
BEGIN
 IF lock_state IS NULL THEN RAISE EXCEPTION 'explicit precondition mode required' USING ERRCODE='22023';END IF;
 inventory:=truss.runtime_condition_inventory(input);
 IF original_keys IS NULL OR octet_length(original_keys) NOT BETWEEN 1 AND 8388608 OR (convert_from(original_keys,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'original predicate key inventory required' USING ERRCODE='22023';END IF;
 IF convert_from(original_keys,'UTF8')::jsonb<>'[]'::jsonb THEN RAISE EXCEPTION 'client predicate key encoding is no longer accepted' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(inventory)>0 THEN key_tuples:=array_fill(NULL::bytea,ARRAY[jsonb_array_length(inventory)]);ELSE key_tuples:=ARRAY[]::bytea[];END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 -- Acquire the complete object cut before evaluating any predicate.
 IF lock_state THEN
  FOR target IN SELECT DISTINCT (o.value->>'id')::bigint AS id,(o.value->>'typeId')::int AS type_id FROM jsonb_array_elements(inventory) e CROSS JOIN LATERAL jsonb_array_elements(e.value->'objects') o ORDER BY id,type_id LOOP
   PERFORM 1 FROM truss.object WHERE id=target.id AND type_id=target.type_id FOR UPDATE NOWAIT;
  END LOOP;
 END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(inventory) WHERE value->'condition'->>'condition'='key_absent' LOOP
  tuple_bytes:=truss.derive_catalog_key_tuple((entry->>'typeId')::int,(entry->>'keyNumber')::smallint,entry->'values');
  key_tuples[(entry->>'index')::int+1]:=tuple_bytes;
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',(entry->>'typeId')::int,(entry->>'keyNumber')::int);
  ns:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,'sourceEpoch',installation.source_epoch::text,
   'typeId',entry->>'typeId','keyNumber',entry->>'keyNumber','definitionPin',pin.definition_pin,'encoding','umf-key-tuple-v1')::text,'UTF8');
  transport:=convert_to('umf-key-tuple-v1:hex:'||encode(tuple_bytes,'hex'),'UTF8');
  IF lock_state THEN PERFORM truss.lock_string_key_bucket(ns,transport);END IF;
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(inventory) LOOP
  condition:=entry->'condition';passed:=false;
  IF condition->>'condition' IN ('object_exists','property_equals') THEN
   SELECT * INTO current_object FROM truss.object WHERE id=(condition->'target'->>'id')::bigint AND type_id=(condition->'target'->>'typeId')::int;
   IF FOUND THEN
    IF condition->>'condition'='object_exists' THEN passed:=true;
    ELSIF entry ? 'propertyId' THEN passed:=current_object.props ? (entry->>'propertyId') AND current_object.props->(entry->>'propertyId')=truss.canonical_flat_cell(condition->'value');
    ELSE passed:=coalesce(current_object.retained,'{}') ? (condition->>'name') AND current_object.retained->(condition->>'name')=truss.canonical_flat_cell(condition->'value');END IF;
   END IF;
  ELSIF condition->>'condition'='key_absent' THEN
   key_tuple:=key_tuples[(entry->>'index')::int+1];
   IF key_tuple IS NULL THEN RAISE EXCEPTION 'precondition key tuple missing' USING ERRCODE='55000';END IF;
   SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',(entry->>'typeId')::int,(entry->>'keyNumber')::int);
   ns:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,'sourceEpoch',installation.source_epoch::text,
    'typeId',entry->>'typeId','keyNumber',entry->>'keyNumber','definitionPin',pin.definition_pin,'encoding','umf-key-tuple-v1')::text,'UTF8');
   transport:=convert_to('umf-key-tuple-v1:hex:'||encode(key_tuple,'hex'),'UTF8');
   IF lock_state THEN
    SELECT * INTO STRICT observed FROM truss.lock_string_key_bucket(ns,transport);
    passed:=cardinality(observed.member_ids)=0; -- Live absence; reservations remain an independent write rule.
   ELSE
    -- Advisory preview observes exact full bytes in the routed bucket without
    -- creating a generation row, taking an advisory lock or reserving a key.
    passed:=cardinality(truss.runtime_peek_string_key_bucket(ns,transport))=0;
   END IF;
  ELSIF condition->>'condition'='relationship_absent' THEN
   passed:=EXISTS(SELECT 1 FROM truss.object WHERE id=(condition->'source'->>'id')::bigint AND type_id=(condition->'source'->>'typeId')::int)
    AND EXISTS(SELECT 1 FROM truss.object WHERE id=(condition->'target'->>'id')::bigint AND type_id=(condition->'target'->>'typeId')::int)
    AND NOT EXISTS(SELECT 1 FROM truss.edge WHERE rel_type_id=(entry->>'relationshipId')::int AND source_id=(condition->'source'->>'id')::bigint AND source_type=(condition->'source'->>'typeId')::int AND target_id=(condition->'target'->>'id')::bigint AND target_type=(condition->'target'->>'typeId')::int);
  ELSE
   IF EXISTS(SELECT 1 FROM truss.object WHERE id=(condition->'anchor'->>'id')::bigint AND type_id=(condition->'anchor'->>'typeId')::int) THEN
    -- Keep predicate witnesses bounded and each endpoint probe indexable.
    IF condition->>'direction'='outgoing' THEN
     SELECT count(*) INTO counted FROM (
      SELECT 1 FROM truss.edge WHERE rel_type_id=(entry->>'relationshipId')::int
       AND source_id=(condition->'anchor'->>'id')::bigint AND source_type=(condition->'anchor'->>'typeId')::int
      LIMIT CASE WHEN NOT condition ? 'maximum' OR (condition->>'maximum')::bigint=9223372036854775807 THEN (condition->>'minimum')::bigint ELSE (condition->>'maximum')::bigint+1 END
     ) matching_edges;
    ELSE
     SELECT count(*) INTO counted FROM (
      SELECT 1 FROM truss.edge WHERE rel_type_id=(entry->>'relationshipId')::int
       AND target_id=(condition->'anchor'->>'id')::bigint AND target_type=(condition->'anchor'->>'typeId')::int
      LIMIT CASE WHEN NOT condition ? 'maximum' OR (condition->>'maximum')::bigint=9223372036854775807 THEN (condition->>'minimum')::bigint ELSE (condition->>'maximum')::bigint+1 END
     ) matching_edges;
    END IF;
    passed:=counted>=(condition->>'minimum')::bigint AND (NOT condition ? 'maximum' OR counted<=(condition->>'maximum')::bigint);
   END IF;
  END IF;
  condition_buffer:=array_append(condition_buffer,jsonb_build_object('conditionId',condition->>'id','rule',condition->>'condition','passed',passed IS TRUE));
  IF passed IS NOT TRUE THEN failure_buffer:=array_append(failure_buffer,jsonb_build_object('conditionId',condition->>'id','reason',condition->>'reason','rule',condition->>'condition'));END IF;
 END LOOP;
 -- A lost predicate authority never returns a partial or complete failure list.
 PERFORM truss.runtime_condition_inventory(input);
 failures:=to_jsonb(failure_buffer);
 RETURN jsonb_build_object('conditions',to_jsonb(condition_buffer),'failures',failures);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_evaluate_preconditions_preview(input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE inventory jsonb;entry jsonb;condition jsonb;owner record;target record;current_object truss.object%ROWTYPE;key_tuples bytea[];key_tuple bytea;
 installation truss.catalog_runtime_installation%ROWTYPE;pin record;ns bytea;transport bytea;tuple_bytes bytea;values_text text[];key_facets jsonb;observed record;passed boolean;counted bigint;
 failure_buffer jsonb[]:=ARRAY[]::jsonb[];condition_buffer jsonb[]:=ARRAY[]::jsonb[];failures jsonb;receipt jsonb;scope jsonb;
BEGIN
 inventory:=truss.runtime_condition_inventory_preview(input);
 IF jsonb_array_length(inventory)>0 THEN key_tuples:=array_fill(NULL::bytea,ARRAY[jsonb_array_length(inventory)]);ELSE key_tuples:=ARRAY[]::bytea[];END IF;
 SELECT * INTO STRICT installation FROM truss.catalog_runtime_installation WHERE singleton;
 FOR entry IN SELECT value FROM jsonb_array_elements(inventory) WHERE value->'condition'->>'condition'='key_absent' LOOP
  tuple_bytes:=truss.runtime_condition_key_tuple_preview((entry->>'typeId')::int,(entry->>'keyNumber')::smallint,entry->'values');
  key_tuples[(entry->>'index')::int+1]:=tuple_bytes;
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(inventory) LOOP
  condition:=entry->'condition';passed:=false;
  IF condition->>'condition' IN ('object_exists','property_equals') THEN
   SELECT * INTO current_object FROM truss.object WHERE id=(condition->'target'->>'id')::bigint AND type_id=(condition->'target'->>'typeId')::int;
   IF FOUND THEN
    IF condition->>'condition'='object_exists' THEN passed:=true;
    ELSIF entry ? 'propertyId' THEN passed:=current_object.props ? (entry->>'propertyId') AND current_object.props->(entry->>'propertyId')=truss.canonical_flat_cell(condition->'value');
    ELSE passed:=coalesce(current_object.retained,'{}') ? (condition->>'name') AND current_object.retained->(condition->>'name')=truss.canonical_flat_cell(condition->'value');END IF;
   END IF;
  ELSIF condition->>'condition'='key_absent' THEN
   key_tuple:=key_tuples[(entry->>'index')::int+1];
   IF key_tuple IS NULL THEN RAISE EXCEPTION 'precondition key tuple missing' USING ERRCODE='55000';END IF;
   ns:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,'sourceEpoch',installation.source_epoch::text,
    'typeId',entry->>'typeId','keyNumber',entry->>'keyNumber','definitionPin',entry->>'keyDefinitionPin','encoding','umf-key-tuple-v1')::text,'UTF8');
   transport:=convert_to('umf-key-tuple-v1:hex:'||encode(key_tuple,'hex'),'UTF8');
   passed:=cardinality(truss.runtime_peek_string_key_bucket(ns,transport))=0;
  ELSIF condition->>'condition'='relationship_absent' THEN
   passed:=EXISTS(SELECT 1 FROM truss.object WHERE id=(condition->'source'->>'id')::bigint AND type_id=(condition->'source'->>'typeId')::int)
    AND EXISTS(SELECT 1 FROM truss.object WHERE id=(condition->'target'->>'id')::bigint AND type_id=(condition->'target'->>'typeId')::int)
    AND NOT EXISTS(SELECT 1 FROM truss.edge WHERE rel_type_id=(entry->>'relationshipId')::int AND source_id=(condition->'source'->>'id')::bigint AND source_type=(condition->'source'->>'typeId')::int AND target_id=(condition->'target'->>'id')::bigint AND target_type=(condition->'target'->>'typeId')::int);
  ELSE
   IF EXISTS(SELECT 1 FROM truss.object WHERE id=(condition->'anchor'->>'id')::bigint AND type_id=(condition->'anchor'->>'typeId')::int) THEN
    -- Keep predicate witnesses bounded and each endpoint probe indexable.
    IF condition->>'direction'='outgoing' THEN
     SELECT count(*) INTO counted FROM (
      SELECT 1 FROM truss.edge WHERE rel_type_id=(entry->>'relationshipId')::int
       AND source_id=(condition->'anchor'->>'id')::bigint AND source_type=(condition->'anchor'->>'typeId')::int
      LIMIT CASE WHEN NOT condition ? 'maximum' OR (condition->>'maximum')::bigint=9223372036854775807 THEN (condition->>'minimum')::bigint ELSE (condition->>'maximum')::bigint+1 END
     ) matching_edges;
    ELSE
     SELECT count(*) INTO counted FROM (
      SELECT 1 FROM truss.edge WHERE rel_type_id=(entry->>'relationshipId')::int
       AND target_id=(condition->'anchor'->>'id')::bigint AND target_type=(condition->'anchor'->>'typeId')::int
      LIMIT CASE WHEN NOT condition ? 'maximum' OR (condition->>'maximum')::bigint=9223372036854775807 THEN (condition->>'minimum')::bigint ELSE (condition->>'maximum')::bigint+1 END
     ) matching_edges;
    END IF;
    passed:=counted>=(condition->>'minimum')::bigint AND (NOT condition ? 'maximum' OR counted<=(condition->>'maximum')::bigint);
   END IF;
  END IF;
  condition_buffer:=array_append(condition_buffer,jsonb_build_object('conditionId',condition->>'id','rule',condition->>'condition','passed',passed IS TRUE));
  IF passed IS NOT TRUE THEN failure_buffer:=array_append(failure_buffer,jsonb_build_object('conditionId',condition->>'id','reason',condition->>'reason','rule',condition->>'condition'));END IF;
 END LOOP;
 -- A lost predicate authority never returns a partial or complete failure list.
 PERFORM truss.runtime_condition_inventory_preview(input);
 failures:=to_jsonb(failure_buffer);
 RETURN jsonb_build_object('conditions',to_jsonb(condition_buffer),'failures',failures);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_feed_authorize(selected_consumer text, expected_release text, expected_digest text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE person oid;consumer truss.runtime_feed_consumer%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;owner record;
BEGIN
 person:=truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest
 OR pg_is_in_recovery() THEN RAISE EXCEPTION 'selected authority feed profile required' USING ERRCODE='0A000';END IF;
 SELECT * INTO consumer FROM truss.runtime_feed_consumer WHERE consumer_id=selected_consumer;
 IF NOT FOUND OR NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
  SELECT person UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
  SELECT 1 FROM memberships WHERE role_oid=consumer.reader_oid) THEN
  RAISE EXCEPTION 'authorized feed consumer required' USING ERRCODE='42501';END IF;
 -- This is a complete database feed, not a role-filtered change stream.
 -- Every module in every disclosed historical document must be readable.
 FOR owner IN SELECT DISTINCT d.doc_id,m.value->>'id' AS module_id FROM truss.schema_doc d
  CROSS JOIN LATERAL jsonb_array_elements(d.document::jsonb->'modules') m LOOP
  IF NOT truss.runtime_can_read(owner.doc_id,owner.module_id) THEN
   RAISE EXCEPTION 'complete source authority required' USING ERRCODE='42501';END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_feed_capture_configuration_statement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE row_count bigint; configuration jsonb; writer xid8:=pg_current_xact_id();
BEGIN
 IF TG_TABLE_NAME='journal' THEN
  SELECT count(*) INTO row_count FROM inserted_rows;
  IF row_count>0 AND EXISTS(SELECT 1 FROM inserted_rows WHERE xid IS DISTINCT FROM writer) THEN
   RAISE EXCEPTION 'current feed fact writer required' USING ERRCODE='55000';END IF;
 ELSE
  SELECT count(*) INTO row_count FROM inserted_rows;
  IF row_count>0 AND EXISTS(SELECT 1 FROM inserted_rows WHERE writer_xid IS DISTINCT FROM writer) THEN
   RAISE EXCEPTION 'current feed fact writer required' USING ERRCODE='55000';END IF;
 END IF;
 IF row_count>0 THEN
  configuration:=truss.runtime_feed_current_configuration();
  PERFORM truss.runtime_feed_retain_configuration(writer,configuration);
 END IF;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_feed_capture_edge_reservations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE row_count bigint; inserted_count bigint; writer xid8:=pg_current_xact_id();
BEGIN
 SELECT count(*) INTO row_count FROM inserted_rows;
 IF row_count=0 THEN
  RETURN NULL;
 END IF;
 INSERT INTO truss.runtime_feed_reservation(writer_xid,kind,original_row)
 SELECT writer,'edge_key',to_jsonb(r) FROM inserted_rows r ORDER BY r.at,r.type_id,r.key_num,r.k,r.entity_id;
 GET DIAGNOSTICS inserted_count=ROW_COUNT;
 IF inserted_count IS DISTINCT FROM row_count THEN RAISE EXCEPTION 'complete edge reservation feed required' USING ERRCODE='55000';END IF;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_feed_capture_object_reservations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE row_count bigint; inserted_count bigint;
BEGIN
 SELECT count(*) INTO row_count FROM inserted_rows;
 IF row_count=0 THEN
  RETURN NULL;
 END IF;
 WITH parsed AS MATERIALIZED (
  SELECT r.storage_row_id,(convert_from(r.original_reservation_bytes,'UTF8')::jsonb->>'xid')::xid8 AS writer_xid,to_jsonb(r) AS original_row
  FROM inserted_rows r ORDER BY r.storage_row_id)
 INSERT INTO truss.runtime_feed_reservation(writer_xid,kind,original_row)
 SELECT writer_xid,'object_key',original_row FROM parsed WHERE writer_xid=pg_current_xact_id() ORDER BY storage_row_id;
 GET DIAGNOSTICS inserted_count=ROW_COUNT;
 IF inserted_count IS DISTINCT FROM row_count THEN RAISE EXCEPTION 'original reservation writer required' USING ERRCODE='55000';END IF;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_feed_page(selected_consumer text, prior_bytes bytea, frontier numeric, maximum_facts integer, maximum_bytes integer)
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE prior jsonb;lower_xid numeric;writer xid8;next_xid numeric;changes jsonb;sources jsonb;reservations jsonb;
 revisions jsonb;prerequisites jsonb;maximum_revision int;payload bytea;result bytea;next_cursor bytea;count_facts bigint;
BEGIN
 IF maximum_facts IS NULL OR maximum_facts NOT BETWEEN 1 AND 65536 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216
 OR prior_bytes IS NULL OR octet_length(prior_bytes) NOT BETWEEN 1 AND 16384 THEN RAISE EXCEPTION 'bounded feed request required' USING ERRCODE='22023';END IF;
 IF (convert_from(prior_bytes,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'exact feed cursor required' USING ERRCODE='22023';END IF;
 prior:=convert_from(prior_bytes,'UTF8')::jsonb;
 IF jsonb_typeof(prior->'nextXid') IS DISTINCT FROM 'string' OR prior->>'nextXid' !~ '^(0|[1-9][0-9]{0,19})$' THEN RAISE EXCEPTION 'exact feed position required' USING ERRCODE='22023';END IF;
 lower_xid:=(prior->>'nextXid')::numeric;
 IF prior_bytes IS DISTINCT FROM truss.runtime_feed_cursor(selected_consumer,lower_xid::text) OR lower_xid>frontier THEN
  RAISE EXCEPTION 'current source cursor required' USING ERRCODE='55000';END IF;
 SELECT x INTO writer FROM (
  SELECT xid AS x FROM truss.journal WHERE xid>=lower_xid::text::xid8 AND xid<frontier::text::xid8
  UNION SELECT writer_xid FROM truss.catalog_registration_request WHERE writer_xid>=lower_xid::text::xid8 AND writer_xid<frontier::text::xid8
  UNION SELECT writer_xid FROM truss.runtime_import_source WHERE writer_xid>=lower_xid::text::xid8 AND writer_xid<frontier::text::xid8
  UNION SELECT writer_xid FROM truss.runtime_feed_reservation WHERE writer_xid>=lower_xid::text::xid8 AND writer_xid<frontier::text::xid8 ) required ORDER BY x LIMIT 1;
 next_xid:=CASE WHEN writer IS NULL THEN frontier ELSE writer::text::numeric+1 END;
 count_facts:=(SELECT count(*) FROM truss.journal WHERE xid=writer)+(SELECT count(*) FROM truss.runtime_import_source WHERE writer_xid=writer)
  +(SELECT count(*) FROM truss.runtime_feed_reservation WHERE writer_xid=writer)+(SELECT count(*) FROM truss.catalog_registration_request WHERE writer_xid=writer);
 IF count_facts>maximum_facts THEN RAISE EXCEPTION 'whole feed transaction exceeds fact limit' USING ERRCODE='54000';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(j) ORDER BY j.seq),'[]') INTO changes FROM truss.journal j WHERE xid=writer;
 SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY l.entity_kind,l.entity_id),'[]') INTO sources
  FROM truss.runtime_import_source l JOIN truss.record_source s USING(entity_kind,entity_id) WHERE l.writer_xid=writer;
 SELECT coalesce(jsonb_agg(jsonb_build_object('kind',kind,'row',original_row) ORDER BY reservation_id),'[]') INTO reservations FROM truss.runtime_feed_reservation WHERE writer_xid=writer;
 SELECT coalesce(jsonb_agg(truss.runtime_feed_revision(r.rev) ORDER BY r.rev),'[]') INTO revisions
  FROM truss.schema_rev r JOIN truss.catalog_registration_request q ON q.revision=r.rev WHERE q.writer_xid=writer;
 SELECT max(rev) INTO maximum_revision FROM (
  SELECT rev FROM truss.journal WHERE xid=writer UNION SELECT revision FROM truss.catalog_registration_request WHERE writer_xid=writer) dependencies;
 -- Earlier xids may observe a catalog revision produced by a later xid.
 -- Attach the real retained prerequisites; this does not advance their writer.
 SELECT coalesce(jsonb_agg(truss.runtime_feed_revision(r.rev) ORDER BY r.rev),'[]') INTO prerequisites
  FROM truss.schema_rev r WHERE r.rev<=maximum_revision;
 count_facts:=count_facts+jsonb_array_length(prerequisites);
 IF count_facts>maximum_facts THEN RAISE EXCEPTION 'whole feed prerequisites exceed fact limit' USING ERRCODE='54000';END IF;
 next_cursor:=truss.runtime_feed_cursor(selected_consumer,next_xid::text);
 payload:=convert_to(jsonb_build_object('interfaceVersion','truss-native-feed/0.1','prior',prior,'next',convert_from(next_cursor,'UTF8')::jsonb,
  'writerXid',writer::text,'configuration',coalesce((SELECT t.configuration FROM truss.runtime_feed_transaction_configuration t WHERE t.writer_xid=writer),jsonb_build_object('releaseId',(SELECT release_id FROM truss.catalog_runtime_installation),
   'releaseSha256',(SELECT release_sha256 FROM truss.catalog_runtime_installation),
   'layoutProfile',(SELECT layout_profile FROM truss.catalog_runtime_installation),
   'preparationConfiguration',(SELECT preparation_configuration FROM truss.catalog_runtime_installation),'settings',(SELECT original_settings FROM truss.runtime_feed_configuration))),
  'catalogPrerequisites',prerequisites,'revisions',revisions,'changes',changes,'sources',sources,'reservations',reservations)::text,'UTF8');
 IF octet_length(payload)>maximum_bytes THEN RAISE EXCEPTION 'whole feed transaction exceeds byte limit' USING ERRCODE='54000';END IF;
 result:=convert_to(jsonb_build_object('outcome',CASE WHEN writer IS NULL THEN 'empty_interval' ELSE 'transaction' END,
  'consumerId',selected_consumer,'registrationId',prior->>'registrationId','writerXid',writer::text,'safeWatermarkXid',frontier::text,
  'priorBase64',replace(encode(prior_bytes,'base64'),chr(10),''),'nextBase64',replace(encode(next_cursor,'base64'),chr(10),''),
  'payloadBase64',replace(encode(payload,'base64'),chr(10),''),'sha256',encode(sha256(payload),'hex'))::text,'UTF8');
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'whole feed envelope exceeds byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_feed_retain_configuration(writer xid8, configuration jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE retained jsonb;
BEGIN
 SELECT t.configuration INTO retained FROM truss.runtime_feed_transaction_configuration t WHERE t.writer_xid=writer;
 IF FOUND THEN
  IF retained IS DISTINCT FROM configuration THEN RAISE EXCEPTION 'stable feed writer configuration required' USING ERRCODE='55000';END IF;
 ELSE
  INSERT INTO truss.runtime_feed_transaction_configuration VALUES(writer,configuration);
  SELECT t.configuration INTO retained FROM truss.runtime_feed_transaction_configuration t WHERE t.writer_xid=writer;
  IF NOT FOUND OR retained IS DISTINCT FROM configuration THEN RAISE EXCEPTION 'original feed writer configuration required' USING ERRCODE='55000';END IF;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_feed_revision(selected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE original_report bytea;expected_hash bytea;result jsonb;
BEGIN
 IF selected_revision>0 THEN
  SELECT r.report_bytes,q.report_sha256 INTO STRICT original_report,expected_hash
   FROM truss.catalog_acceptance_report r JOIN truss.catalog_registration_request q ON q.revision=r.rev WHERE r.rev=selected_revision;
  IF sha256(original_report) IS DISTINCT FROM expected_hash THEN RAISE EXCEPTION 'original accepted report required' USING ERRCODE='55000';END IF;
 END IF;
 SELECT jsonb_build_object('revision',r.rev::text,'record',to_jsonb(r),'documents',
  (SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.ord),'[]') FROM truss.schema_doc d WHERE d.rev=r.rev),
  'reportBytesBase64',CASE WHEN original_report IS NOT NULL THEN replace(encode(original_report,'base64'),chr(10),'') END,
  'reportSha256',encode(expected_hash,'hex')) INTO STRICT result FROM truss.schema_rev r WHERE r.rev=selected_revision;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_graph_validate_object_qualified(selected_id bigint, selected_type integer, refresh_markers boolean, qualified_actor oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
DECLARE phase int;relation truss.rel_def%ROWTYPE;owner record;outgoing bigint;incoming bigint;expected jsonb;actual jsonb;
BEGIN
  PERFORM 1 FROM truss.object WHERE id=selected_id AND type_id=selected_type FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RETURN;END IF;
  FOR phase IN 1..2 LOOP
   FOR owner IN
    WITH selected_relations AS MATERIALIZED (
     SELECT DISTINCT rel_type_id FROM truss.rel_endpoint WHERE source_type=selected_type OR target_type=selected_type),
    active_relations AS MATERIALIZED (
     SELECT r.rel_type_id,r.document_id,r.module FROM selected_relations s JOIN truss.rel_def r USING(rel_type_id)
     WHERE r.retired_rev IS NULL),
    dependencies AS (
     SELECT document_id,module AS module_id FROM active_relations
     UNION ALL SELECT t.document_id,t.module FROM active_relations r
      JOIN truss.rel_endpoint e USING(rel_type_id) JOIN truss.type_def t ON t.type_id IN(e.source_type,e.target_type))
    SELECT DISTINCT document_id,module_id FROM dependencies
   LOOP
    IF NOT truss.runtime_can_read_qualified(owner.document_id,owner.module_id,qualified_actor) THEN RAISE EXCEPTION 'complete relationship and endpoint count reader required' USING ERRCODE='42501';END IF;
   END LOOP;
   IF phase=1 THEN
  FOR relation IN SELECT r.* FROM (
   SELECT DISTINCT rel_type_id FROM truss.rel_endpoint WHERE source_type=selected_type OR target_type=selected_type
  ) selected JOIN truss.rel_def r USING(rel_type_id) WHERE r.retired_rev IS NULL ORDER BY r.rel_type_id LOOP
   -- A threshold verdict needs only minimum witnesses or maximum + 1 rows.
   outgoing:=NULL;incoming:=NULL;
   IF (relation.target_min>0 OR relation.target_max IS NOT NULL)
    AND EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND source_type=selected_type) THEN
    SELECT count(*) INTO outgoing FROM (
     SELECT 1 FROM truss.edge WHERE rel_type_id=relation.rel_type_id AND source_id=selected_id AND source_type=selected_type
     LIMIT CASE WHEN relation.target_max IS NULL THEN relation.target_min::bigint ELSE relation.target_max::bigint+1 END
    ) matching_edges;
    IF outgoing<relation.target_min OR relation.target_max IS NOT NULL AND outgoing>relation.target_max THEN RAISE EXCEPTION 'outgoing multiplicity failed' USING ERRCODE='P1005';END IF;
   END IF;
   IF (relation.source_min>0 OR relation.source_max IS NOT NULL)
    AND EXISTS(SELECT 1 FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id AND target_type=selected_type) THEN
    SELECT count(*) INTO incoming FROM (
     SELECT 1 FROM truss.edge WHERE rel_type_id=relation.rel_type_id AND target_id=selected_id AND target_type=selected_type
     LIMIT CASE WHEN relation.source_max IS NULL THEN relation.source_min::bigint ELSE relation.source_max::bigint+1 END
    ) matching_edges;
    IF incoming<relation.source_min OR relation.source_max IS NOT NULL AND incoming>relation.source_max THEN RAISE EXCEPTION 'incoming multiplicity failed' USING ERRCODE='P1005';END IF;
   END IF;
   SELECT coalesce(jsonb_agg(v ORDER BY v->>'side'),'[]'::jsonb) INTO expected FROM (
    SELECT jsonb_build_object('rel_type_id',relation.rel_type_id,'side','s','endpoint_id',selected_id,'edge_id',id) v FROM truss.edge
     WHERE relation.target_max=1 AND rel_type_id=relation.rel_type_id AND source_id=selected_id AND source_type=selected_type
    UNION ALL SELECT jsonb_build_object('rel_type_id',relation.rel_type_id,'side','t','endpoint_id',selected_id,'edge_id',id) FROM truss.edge
     WHERE relation.source_max=1 AND rel_type_id=relation.rel_type_id AND target_id=selected_id AND target_type=selected_type) markers;
   IF refresh_markers THEN
    DELETE FROM truss.edge_limit WHERE rel_type_id=relation.rel_type_id AND endpoint_id=selected_id;
    INSERT INTO truss.edge_limit SELECT (jsonb_populate_record(NULL::truss.edge_limit,value)).* FROM jsonb_array_elements(expected);
   END IF;
   SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.side),'[]'::jsonb) INTO actual FROM truss.edge_limit m WHERE m.rel_type_id=relation.rel_type_id AND m.endpoint_id=selected_id;
   IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'exact final multiplicity markers required' USING ERRCODE='55000';END IF;
  END LOOP;
   END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_history_entity(selection jsonb, expected_release text, expected_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;selected_type int;
BEGIN
 PERFORM truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest
 OR pg_is_in_recovery() THEN RAISE EXCEPTION 'selected retained authority history required' USING ERRCODE='0A000';END IF;
 IF selection-ARRAY['kind','documentId','moduleId','definitionId','id']<>'{}'::jsonb
 OR (selection->>'kind' IN ('object','edge')) IS NOT TRUE
 OR jsonb_typeof(selection->'id') IS DISTINCT FROM 'string' OR selection->>'id' !~ '^[1-9][0-9]{0,18}$'
 OR length(selection->>'id')=19 AND (selection->>'id') COLLATE "C">'9223372036854775807'
 OR NOT EXISTS(SELECT 1 FROM jsonb_each(selection) WHERE key='documentId' AND jsonb_typeof(value)='string' AND octet_length(value#>>'{}') BETWEEN 1 AND 4096)
 OR NOT EXISTS(SELECT 1 FROM jsonb_each(selection) WHERE key='moduleId' AND jsonb_typeof(value)='string' AND octet_length(value#>>'{}') BETWEEN 1 AND 4096)
 OR NOT EXISTS(SELECT 1 FROM jsonb_each(selection) WHERE key='definitionId' AND jsonb_typeof(value)='string' AND octet_length(value#>>'{}') BETWEEN 1 AND 4096) THEN
  RAISE EXCEPTION 'bounded qualified history entity required' USING ERRCODE='22023';END IF;
 IF NOT truss.runtime_can_read(selection->>'documentId',selection->>'moduleId') THEN RAISE EXCEPTION 'current history owner reader required' USING ERRCODE='42501';END IF;
 IF selection->>'kind'='object' THEN
  SELECT type_id INTO selected_type FROM truss.type_def WHERE document_id=selection->>'documentId' AND module=selection->>'moduleId' AND element=selection->>'definitionId'
   AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 ELSE
  SELECT rel_type_id INTO selected_type FROM truss.rel_def WHERE document_id=selection->>'documentId' AND module=selection->>'moduleId' AND rel_id=selection->>'definitionId' AND retired_rev IS NULL;
 END IF;
 IF selected_type IS NULL THEN RAISE EXCEPTION 'retained entity definition unavailable' USING ERRCODE='P1010';END IF;
 RETURN selection||jsonb_build_object('typeId',selected_type::text,'installationId',installation.installation_id::text,
  'sourceEpoch',installation.source_epoch::text,'releaseSha256',installation.release_sha256);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_history_group_qualified(entity jsonb, writer xid8, version bigint, maximum_events integer, maximum_bytes integer, qualified_actor oid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE physical truss.journal%ROWTYPE;original bytea;event jsonb;items jsonb:='[]';semantic jsonb:='[]';group_pin jsonb;
 count_events int:=0;size int:=0;expected_pin text;
 schema_metadata jsonb;property_pins jsonb;property_access jsonb;property_context jsonb;property_pin text;event_property_pin text;reader jsonb;property_type_pin text;
 property_revision int;property_type int;
 item_buffer jsonb[]:='{}';semantic_buffer jsonb[]:='{}';edge_context jsonb;endpoint_context jsonb;edge_readers_checked boolean:=false;
BEGIN
 FOR physical IN SELECT * FROM truss.journal j WHERE j.entity_kind=(CASE entity->>'kind' WHEN 'object' THEN 'o' ELSE 'e' END)::char(1)
  AND j.entity_id=(entity->>'id')::bigint AND j.entity_type=(entity->>'typeId')::int AND j.xid=writer AND j.ver=version ORDER BY j.seq LIMIT maximum_events+1 LOOP
  count_events:=count_events+1;
  IF count_events>maximum_events THEN RAISE EXCEPTION 'whole history group exceeds event limit' USING ERRCODE='54000';END IF;
  size:=size+octet_length(physical.new_value::text)+octet_length(physical.origin::text);
  IF size>maximum_bytes THEN RAISE EXCEPTION 'whole history group exceeds byte limit' USING ERRCODE='54000';END IF;
  original:=decode(physical.new_value->>'bytesBase64','base64');
  IF physical.new_value IS DISTINCT FROM truss.runtime_exact_wrapper('event',original)
  OR (convert_from(original,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'original exact history wrapper required' USING ERRCODE='55000';END IF;
  event:=convert_from(original,'UTF8')::jsonb;
  IF event->>'interfaceVersion' IS DISTINCT FROM 'truss-history-event/0.2.0-proposal'
  OR (event->>'historyProfile' IN ('truss-native-scalar-create/0.2','truss-native-owned-create/0.1','truss-native-scalar-mutation/0.1','truss-native-owned-mutation/0.1','truss-native-edge-mutation/0.1','truss-native-owned-edge-mutation/0.1','truss-native-catalog-rebind/0.1','truss-native-catalog-rebind/0.2','truss-native-catalog-rebind/0.3','truss-native-catalog-rebind/0.4')) IS NOT TRUE
  OR event->>'sourceEpoch' IS DISTINCT FROM entity->>'sourceEpoch' OR event->>'xid' IS DISTINCT FROM physical.xid::text
  OR event->>'seq' IS DISTINCT FROM physical.seq::text OR event->>'eventVersion' IS DISTINCT FROM physical.ver::text
  OR event->>'eventCatalogRevision' IS DISTINCT FROM physical.rev::text
  OR event->'identity'->>'id' IS DISTINCT FROM entity->>'id' OR event->'identity'->>'typeId' IS DISTINCT FROM entity->>'typeId'
  OR event->'identity'->'owner' IS DISTINCT FROM jsonb_build_object('documentId',entity->>'documentId','moduleId',entity->>'moduleId')
  OR physical.op IS DISTINCT FROM (CASE event->>'operation' WHEN 'property' THEN 'update' ELSE event->>'operation' END)
  OR physical.prop_id IS DISTINCT FROM (event->>'propertyId')::int
  OR physical.origin IS DISTINCT FROM truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8')) THEN
   RAISE EXCEPTION 'physical and semantic history correspondence required' USING ERRCODE='55000';END IF;
  -- The canonical producer already settled the transition. Only the original
  -- edge endpoint/root policy is additional to the public history images.
  IF event->>'historyProfile'='truss-native-owned-edge-mutation/0.1' AND NOT edge_readers_checked THEN
   SELECT t.endpoint_ownership INTO STRICT edge_context FROM truss.runtime_edge_transition t
    WHERE t.edge_id=physical.entity_id AND t.rel_type_id=physical.entity_type AND t.writer_xid=writer
     AND CASE WHEN t.after_edge IS NULL THEN (t.before_edge->>'ver')::bigint+1 ELSE (t.after_edge->>'ver')::bigint END=version;
   FOR endpoint_context IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
    edge_context->'before'->'source',edge_context->'before'->'target',edge_context->'after'->'source',edge_context->'after'->'target'))
    WHERE value<>'null'::jsonb LOOP
    IF NOT truss.runtime_can_read_qualified(endpoint_context->'identity'->'owner'->>'documentId',endpoint_context->'identity'->'owner'->>'moduleId',qualified_actor) THEN
     RAISE EXCEPTION 'current original endpoint reader required' USING ERRCODE='42501';END IF;
    PERFORM truss.runtime_history_ownership_qualified(jsonb_build_object('identity',endpoint_context->'identity',
     'catalogRevision',edge_context->>'captureCatalogRevision','ownership',endpoint_context->'ownership'),qualified_actor);
   END LOOP;
   edge_readers_checked:=true;
  END IF;
  IF entity->>'kind'='object' THEN
   IF property_pins IS NULL OR property_revision IS DISTINCT FROM physical.rev OR property_type IS DISTINCT FROM physical.entity_type THEN
    -- One detoast per revision/type; permissions below remain live per reader.
    SELECT s.metadata||'{}'::jsonb INTO STRICT schema_metadata FROM truss.runtime_type_schema s
     WHERE s.rev=physical.rev AND s.type_id=physical.entity_type;
    property_type_pin:=schema_metadata->>'typePin';property_pins:=schema_metadata->'propertyPins';property_access:=schema_metadata->'propertyAccess';
    schema_metadata:=NULL;
    property_revision:=physical.rev;property_type:=physical.entity_type;
   END IF;
   expected_pin:=property_type_pin;
  ELSE expected_pin:=truss.runtime_relationship_pin(physical.entity_type,physical.rev);END IF;
  IF expected_pin IS NULL OR event->'identity'->>'definitionPin' IS DISTINCT FROM expected_pin THEN RAISE EXCEPTION 'original event interpretation required' USING ERRCODE='55000';END IF;
  IF event->>'operation' IN ('property','rebind') THEN
   IF event->>'operation'='rebind' AND
    (event->>'historyProfile' IN ('truss-native-catalog-rebind/0.1','truss-native-catalog-rebind/0.2','truss-native-catalog-rebind/0.3','truss-native-catalog-rebind/0.4')) IS NOT TRUE THEN
    RAISE EXCEPTION 'original catalog rebind profile required' USING ERRCODE='55000';END IF;
   IF property_pins IS NULL OR property_revision IS DISTINCT FROM physical.rev OR property_type IS DISTINCT FROM physical.entity_type THEN
    SELECT s.metadata||'{}'::jsonb INTO STRICT schema_metadata FROM truss.runtime_type_schema s
     WHERE s.rev=physical.rev AND s.type_id=physical.entity_type;
    property_pins:=schema_metadata->'propertyPins';property_access:=schema_metadata->'propertyAccess';schema_metadata:=NULL;
    property_revision:=physical.rev;property_type:=physical.entity_type;
   END IF;
   event_property_pin:=CASE WHEN event->>'operation'='rebind' THEN event->>'afterDefinitionPin' ELSE event->>'definitionPin' END;
   property_pin:=property_pins->>physical.prop_id::text;property_context:=property_access->physical.prop_id::text;
   IF property_pin IS DISTINCT FROM event_property_pin OR property_context IS NULL
    OR (property_context->>'itemsValid')::boolean IS NOT TRUE OR jsonb_typeof(property_context->'readers') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'original property interpretation required' USING ERRCODE='55000';END IF;
   FOR reader IN SELECT value FROM jsonb_array_elements(property_context->'readers') LOOP
    IF NOT truss.runtime_can_read_qualified(reader->>'documentId',reader->>'moduleId',qualified_actor) THEN
     RAISE EXCEPTION 'current historical property/item reader required' USING ERRCODE='42501';END IF;
   END LOOP;
  ELSIF event->>'operation'='create' THEN PERFORM truss.runtime_history_image_qualified(event->'after',entity,version,qualified_actor);
  ELSIF event->>'operation'='metadata' THEN
   PERFORM truss.runtime_history_image_qualified(event->'before',entity,version-1,qualified_actor);PERFORM truss.runtime_history_image_qualified(event->'after',entity,version,qualified_actor);
  ELSIF event->>'operation'='delete' THEN PERFORM truss.runtime_history_image_qualified(event->'before',entity,version-1,qualified_actor);
  ELSE RAISE EXCEPTION 'supported retained event required' USING ERRCODE='0A000';END IF;
  IF group_pin IS NULL THEN group_pin:=event->'mutationGroup';
  ELSIF group_pin IS DISTINCT FROM event->'mutationGroup' THEN RAISE EXCEPTION 'one complete mutation group required' USING ERRCODE='55000';END IF;
  semantic_buffer:=array_append(semantic_buffer,event-'mutationGroup');
  item_buffer:=array_append(item_buffer,jsonb_build_object('contentBase64',replace(encode(original,'base64'),chr(10),''),'sha256',encode(sha256(original),'hex'),
   'writerXid',physical.xid::text,'seq',physical.seq::text,'version',physical.ver::text));
 END LOOP;
 semantic:=to_jsonb(semantic_buffer);items:=to_jsonb(item_buffer);
 IF count_events=0 THEN RAISE EXCEPTION 'retained history unavailable' USING ERRCODE='P1010';END IF;
 IF group_pin IS DISTINCT FROM jsonb_build_object('profile','truss-history-group/0.1.0','eventCount',count_events::text,'orderedEventDigest',encode(sha256(convert_to(semantic::text,'UTF8')),'hex')) THEN
  RAISE EXCEPTION 'complete original history group digest required' USING ERRCODE='55000';END IF;
 RETURN items;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_history_image_qualified(image jsonb, entity jsonb, expected_version bigint, qualified_actor oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE revision int;pin text;member jsonb;endpoint jsonb;endpoint_pin record;
 schema_metadata jsonb;property_pins jsonb;property_access jsonb;property_context jsonb;property_pin text;property_id int;reader jsonb;
BEGIN
 IF image->>'interfaceVersion' IS DISTINCT FROM 'truss-history-record/0.1.0' OR image->>'kind' IS DISTINCT FROM entity->>'kind'
 OR image->'identity'->>'id' IS DISTINCT FROM entity->>'id' OR image->'identity'->>'typeId' IS DISTINCT FROM entity->>'typeId'
 OR image->'identity'->'owner' IS DISTINCT FROM jsonb_build_object('documentId',entity->>'documentId','moduleId',entity->>'moduleId')
 OR image->>'recordVersion' IS DISTINCT FROM expected_version::text THEN RAISE EXCEPTION 'original complete history image required' USING ERRCODE='55000';END IF;
 revision:=(image->>'catalogRevision')::int;
 IF entity->>'kind'='object' THEN
  -- Force one detoast, then retain only flat property maps for this image.
  SELECT s.metadata||'{}'::jsonb INTO STRICT schema_metadata FROM truss.runtime_type_schema s
   WHERE s.rev=revision AND s.type_id=(entity->>'typeId')::int;
  pin:=schema_metadata->>'typePin';property_pins:=schema_metadata->'propertyPins';property_access:=schema_metadata->'propertyAccess';
  schema_metadata:=NULL;
 ELSE pin:=truss.runtime_relationship_pin((entity->>'typeId')::int,revision);END IF;
 IF pin IS NULL OR image->'identity'->>'definitionPin' IS DISTINCT FROM pin THEN RAISE EXCEPTION 'original image interpretation required' USING ERRCODE='55000';END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(image->'properties') LOOP
  property_id:=(member->>'propertyId')::int;
  IF property_pins IS NULL THEN
   -- Project flat local maps once; repeated helper calls would detoast the
   -- complete stored type metadata again for every property in this image.
   SELECT s.metadata||'{}'::jsonb INTO STRICT schema_metadata FROM truss.runtime_type_schema s
    WHERE s.rev=revision AND s.type_id=(entity->>'typeId')::int;
   property_pins:=schema_metadata->'propertyPins';property_access:=schema_metadata->'propertyAccess';schema_metadata:=NULL;
  END IF;
  property_pin:=property_pins->>property_id::text;property_context:=property_access->property_id::text;
  IF property_pin IS DISTINCT FROM member->>'definitionPin' OR property_context IS NULL
   OR (property_context->>'itemsValid')::boolean IS NOT TRUE OR jsonb_typeof(property_context->'readers') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'original property interpretation required' USING ERRCODE='55000';END IF;
  FOR reader IN SELECT value FROM jsonb_array_elements(property_context->'readers') LOOP
   IF NOT truss.runtime_can_read_qualified(reader->>'documentId',reader->>'moduleId',qualified_actor) THEN
    RAISE EXCEPTION 'current historical property/item reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
 IF entity->>'kind'='object' THEN PERFORM truss.runtime_history_ownership_qualified(image,qualified_actor);END IF;
 IF entity->>'kind'='edge' THEN
  FOR endpoint IN SELECT value FROM jsonb_array_elements(jsonb_build_array(image->'source',image->'target')) LOOP
   SELECT * INTO STRICT endpoint_pin FROM truss.runtime_owned_definition_metadata('type',(endpoint->>'typeId')::int,NULL,revision);
   IF endpoint->>'definitionPin' IS DISTINCT FROM endpoint_pin.definition_pin OR endpoint->'owner' IS DISTINCT FROM jsonb_build_object('documentId',endpoint_pin.document_id,'moduleId',endpoint_pin.module_id) THEN
    RAISE EXCEPTION 'original endpoint interpretation required' USING ERRCODE='55000';END IF;
   IF NOT truss.runtime_can_read_qualified(endpoint_pin.document_id,endpoint_pin.module_id,qualified_actor) THEN RAISE EXCEPTION 'current historical endpoint reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_history_ownership_qualified(image jsonb, qualified_actor oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE ownership jsonb:=image->'ownership';root jsonb;pin record;revision int;
BEGIN
 IF ownership='{"state":"rootless"}'::jsonb THEN RETURN;END IF;
 IF ownership->>'state' IS DISTINCT FROM 'owned' OR ownership-ARRAY['state','root']<>'{}'::jsonb
  OR jsonb_typeof(ownership->'root') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'original explicit ownership selection required' USING ERRCODE='55000';END IF;
 root:=ownership->'root';revision:=(image->>'catalogRevision')::int;
 IF root-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb
  OR jsonb_typeof(root->'id') IS DISTINCT FROM 'string' OR root->>'id' !~ '^[1-9][0-9]{0,18}$'
  OR length(root->>'id')=19 AND (root->>'id') COLLATE "C">'9223372036854775807'
  OR jsonb_typeof(root->'typeId') IS DISTINCT FROM 'string' OR root->>'typeId' !~ '^[1-9][0-9]{0,9}$'
  OR (root->>'typeId')::bigint>2147483647
  OR root->>'id'=image->'identity'->>'id' AND root->>'typeId'=image->'identity'->>'typeId'
  OR revision IS NULL OR revision<1 THEN
  RAISE EXCEPTION 'exact historical aggregate root required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',(root->>'typeId')::int,NULL,revision);
 IF root->>'definitionPin' IS DISTINCT FROM pin.definition_pin
  OR root->'owner' IS DISTINCT FROM jsonb_build_object('documentId',pin.document_id,'moduleId',pin.module_id) THEN
  RAISE EXCEPTION 'original aggregate root interpretation required' USING ERRCODE='55000';END IF;
 IF NOT truss.runtime_can_read_qualified(pin.document_id,pin.module_id,qualified_actor) THEN
  RAISE EXCEPTION 'current historical root reader required' USING ERRCODE='42501';END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_history_property_qualified(selected_type integer, property_id integer, revision integer, definition_pin text, qualified_actor oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE access jsonb;pin text;reader jsonb;
BEGIN
 SELECT s.metadata->'propertyPins'->>property_id::text,s.metadata->'propertyAccess'->property_id::text
  INTO STRICT pin,access FROM truss.runtime_type_schema s WHERE s.rev=revision AND s.type_id=selected_type;
 IF pin IS DISTINCT FROM definition_pin OR access IS NULL OR (access->>'itemsValid')::boolean IS NOT TRUE
  OR jsonb_typeof(access->'readers') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'original property interpretation required' USING ERRCODE='55000';END IF;
 FOR reader IN SELECT value FROM jsonb_array_elements(access->'readers') LOOP
  IF NOT truss.runtime_can_read_qualified(reader->>'documentId',reader->>'moduleId',qualified_actor) THEN
   RAISE EXCEPTION 'current historical property/item reader required' USING ERRCODE='42501';END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_import_operation(record jsonb, metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE payload_bytes bytea;payload jsonb;operation jsonb;source_at text;
BEGIN
    payload_bytes:=decode(record->'payload'->>'bytesBase64','base64');
    IF octet_length(payload_bytes) NOT BETWEEN 1 AND 1048576 OR encode(sha256(payload_bytes),'hex') IS DISTINCT FROM record->'payload'->>'sha256'
     OR (convert_from(payload_bytes,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'original payload integrity required' USING ERRCODE='22023';END IF;
    payload:=convert_from(payload_bytes,'UTF8')::jsonb;
    IF payload->>'interfaceVersion' IS DISTINCT FROM 'truss-import-payload/0.1.0' OR payload->>'kind' IS DISTINCT FROM record->>'kind' THEN RAISE EXCEPTION 'exact original payload required' USING ERRCODE='22023';END IF;
    IF jsonb_typeof(payload->'values') IS DISTINCT FROM 'array'
     OR jsonb_array_length(payload->'values')>1024
     OR (SELECT count(*)<>count(DISTINCT v.value->>'name') FROM jsonb_array_elements(payload->'values') v)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'values') v WHERE jsonb_typeof(v.value) IS DISTINCT FROM 'object'
      OR v.value-ARRAY['name','value']<>'{}'::jsonb OR jsonb_typeof(v.value->'name') IS DISTINCT FROM 'string') THEN
     RAISE EXCEPTION 'unique original authored values required' USING ERRCODE='22023';END IF;
    IF record->>'kind'='object' THEN
     IF payload-ARRAY['interfaceVersion','kind','values','ownership','source']<>'{}'::jsonb
      OR payload->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(metadata->'primaryFields') f WHERE NOT EXISTS(
       SELECT 1 FROM jsonb_array_elements(payload->'values') v WHERE v.value->>'name'=f.value->>'name' AND v.value->'value'=f.value->'value')) THEN
      RAISE EXCEPTION 'original primary field/payload agreement required' USING ERRCODE='22023';END IF;
    ELSIF payload-ARRAY['interfaceVersion','kind','values','orderKey','source']<>'{}'::jsonb
     OR payload->'orderKey' IS DISTINCT FROM '{"state":"null"}'::jsonb AND
      (jsonb_typeof(payload->'orderKey') IS DISTINCT FROM 'object' OR (payload->'orderKey')-ARRAY['state','text']<>'{}'::jsonb
       OR payload->'orderKey'->>'state' IS DISTINCT FROM 'text' OR jsonb_typeof(payload->'orderKey'->'text') IS DISTINCT FROM 'string') THEN
     RAISE EXCEPTION 'closed original edge payload required' USING ERRCODE='22023';END IF;
    IF payload ? 'source' AND (jsonb_typeof(payload->'source') IS DISTINCT FROM 'object'
     OR (payload->'source')-ARRAY['kind','entries']<>'{}'::jsonb OR payload->'source'->>'kind' IS DISTINCT FROM 'map'
     OR jsonb_typeof(payload->'source'->'entries') IS DISTINCT FROM 'array'
     OR (SELECT count(*)<>count(DISTINCT e.value->>'key') FROM jsonb_array_elements(payload->'source'->'entries') e)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'source'->'entries') e WHERE e.value-ARRAY['key','value']<>'{}'::jsonb
      OR jsonb_typeof(e.value->'key') IS DISTINCT FROM 'string' OR e.value->>'key' IN ('author','at','system') AND
       (e.value->'value'->>'kind' IN ('string','null')) IS NOT TRUE)) THEN
     RAISE EXCEPTION 'closed original source fields required' USING ERRCODE='22023';END IF;
    SELECT e.value->'value'->>'text' INTO source_at FROM jsonb_array_elements(coalesce(payload->'source'->'entries','[]'::jsonb)) e WHERE e.value->>'key'='at' AND e.value->'value'->>'kind'='string';
    IF source_at IS NOT NULL THEN
     BEGIN PERFORM truss.query_timestamp_instant_key(source_at,'umf-rfc3339-exact-instant/1.0.0');
     EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'selected source.at exact instant required' USING ERRCODE='22023';END;
    END IF;
    IF record->>'kind'='object' THEN operation:=jsonb_build_object('operation','create_object','typeDefinitionPin',metadata->>'definitionPin','values',payload->'values','ownership',payload->'ownership');
    ELSE operation:=jsonb_build_object('operation','create_edge','relationshipDefinitionPin',record->'identity'->>'relationshipDefinitionPin','source',jsonb_build_object('state','stored','identity',record->'identity'->'source'),'target',jsonb_build_object('state','stored','identity',record->'identity'->'target'),'values',payload->'values','orderKey',payload->'orderKey');END IF;
    RETURN operation;
    EXCEPTION WHEN SQLSTATE '22021' OR SQLSTATE '22P05' OR SQLSTATE '22P02' THEN
     RAISE EXCEPTION 'eligible original payload encoding required' USING ERRCODE='22023';
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_import_source_commit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE ledger truss.runtime_import_source%ROWTYPE;attempt truss.runtime_object_attempt%ROWTYPE;actual jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolsuper) THEN RETURN NULL;END IF;
 SELECT * INTO STRICT ledger FROM truss.runtime_import_source WHERE entity_kind=NEW.entity_kind AND entity_id=NEW.entity_id;
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=ledger.group_attempt_id;
 IF ledger.writer_xid<>pg_current_xact_id() OR attempt.writer_xid<>ledger.writer_xid OR attempt.actor_oid<>truss.runtime_person(false) OR NOT attempt.complete
  OR ledger.operation_index<0 OR ledger.operation_index>=attempt.next_index
  OR attempt.results->ledger.operation_index->>'outcome'<>'created' OR attempt.results->ledger.operation_index->'identity'->>'id'<>ledger.entity_id::text
  OR (convert_from(ledger.original_record,'UTF8')::jsonb->'payloadProfile' IS DISTINCT FROM truss.runtime_import_profiles()->'ownedImportPayloadProfile'
   AND (ledger.operation_index<>0 OR attempt.next_index<>1)) THEN RAISE EXCEPTION 'original pending import creation required' USING ERRCODE='55000';END IF;
 SELECT to_jsonb(s) INTO actual FROM truss.record_source s WHERE entity_kind=ledger.entity_kind AND entity_id=ledger.entity_id;
 IF actual IS DISTINCT FROM ledger.expected_source THEN RAISE EXCEPTION 'immutable exact original import source required' USING ERRCODE='55000';END IF;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_item_chain_readable_qualified(item jsonb, qualified_actor oid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE node jsonb;
BEGIN
 IF truss.valid_item_chain(item) IS NOT TRUE THEN RETURN false;END IF;
 FOR node IN SELECT value FROM jsonb_array_elements(jsonb_build_array(item)||coalesce(item->'descendants','[]'::jsonb)) LOOP
  IF truss.runtime_can_read_qualified(node->>'documentId',node->'reference'->>'module',qualified_actor) IS NOT TRUE THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_lineage_bytes(category text, document_id text, module_id text, element_id text)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE d text:=truss.runtime_lineage_quote(document_id); m text:=truss.runtime_lineage_quote(module_id);
 e text:=truss.runtime_lineage_quote(element_id); payload text; profile text;
BEGIN
 IF category='record' THEN
  profile:='truss-type-lineage/0.1.0'; payload:='['||d||','||m||','||e||']';
 ELSIF category='authored' THEN
  profile:='truss-relationship-lineage-bytes/0.1.0';
  payload:='{"category":"authored","relationship":{"document":'||d||',"element":'||e||',"module":'||m||'}}';
 ELSE RAISE EXCEPTION 'unsupported lineage category' USING ERRCODE='22023'; END IF;
 RETURN convert_to('truss-canonical/0.1.0'||chr(10)||profile||chr(10)||payload,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_lineage_quote(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result text := '"'; ch text; point int; i int;
BEGIN
 IF value IS NULL OR octet_length(value) NOT BETWEEN 1 AND 65536 THEN
  RAISE EXCEPTION 'bounded original identity required' USING ERRCODE='22023';
 END IF;
 FOR i IN 1..length(value) LOOP
  ch:=substr(value,i,1); point:=ascii(ch);
  IF point<32 THEN result:=result || chr(92) || 'u00' || lpad(to_hex(point),2,'0');
  ELSIF ch='"' OR ch=chr(92) THEN result:=result || chr(92) || ch;
  ELSE result:=result || ch; END IF;
 END LOOP;
 RETURN result || '"';
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_lock_edge_business_key(key text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF key IS NULL OR octet_length(key)>65536 THEN RAISE EXCEPTION 'bounded exact edge identity required' USING ERRCODE='22023';END IF;
 IF NOT pg_try_advisory_xact_lock(('x'||substr(encode(sha256(convert_to('edge-import-route:'||key,'UTF8')),'hex'),1,16))::bit(64)::bigint) THEN RAISE EXCEPTION 'edge identity in flight' USING ERRCODE='55P03';END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_module_writer_qualified(selected_document text, selected_module text, qualified_actor oid)
 RETURNS oid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE person oid;policy truss.module_access%ROWTYPE;
BEGIN
 person:=qualified_actor;
 SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module FOR SHARE NOWAIT;
 IF NOT FOUND OR NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
  SELECT person UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
  SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid WHERE r.rolname::text=policy.writer_role) THEN
  RAISE EXCEPTION 'current qualified module writer required' USING ERRCODE='42501'; END IF;
 RETURN person;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_mutation_audit_attempt_matches(selected_attempt uuid, selected_filters jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;identity_found boolean;action_value text;from_time timestamptz;until_time timestamptz;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 IF selected_filters ? 'attemptId' AND selected_filters->>'attemptId' IS DISTINCT FROM attempt.id::text THEN RETURN false;END IF;
 IF selected_filters ? 'nativeActorOid' AND selected_filters->>'nativeActorOid' IS DISTINCT FROM attempt.actor_oid::text THEN RETURN false;END IF;
 IF selected_filters ? 'assertedAction' THEN
  IF jsonb_typeof(attempt.context->'originalAssertedOrigin'->'entries')='array'
   AND (SELECT count(*)=1 FROM jsonb_array_elements(attempt.context->'originalAssertedOrigin'->'entries') e WHERE e.value->>'key'='x-action')
   AND (SELECT count(*)=1 FROM jsonb_array_elements(attempt.context->'originalAssertedOrigin'->'entries') e
     WHERE e.value->>'key'='x-action' AND e.value->'value'->>'kind'='string'
      AND jsonb_typeof(e.value->'value'->'text')='string'
      AND octet_length(e.value->'value'->>'text') BETWEEN 1 AND 4096) THEN
   SELECT e.value->'value'->>'text' INTO action_value
    FROM jsonb_array_elements(attempt.context->'originalAssertedOrigin'->'entries') e WHERE e.value->>'key'='x-action';
  END IF;
  IF action_value COLLATE pg_catalog."C" IS DISTINCT FROM (selected_filters->>'assertedAction') COLLATE pg_catalog."C" THEN RETURN false;END IF;
 END IF;
 IF selected_filters ? 'entityId' OR selected_filters ? 'entityType' THEN
  IF truss.runtime_mutation_audit_identity_matches(attempt.id,selected_filters) IS NOT TRUE THEN RETURN false;END IF;
 END IF;
 IF selected_filters ? 'entityKey' AND
   truss.runtime_mutation_audit_key_matches(attempt.id,selected_filters->'entityKey') IS NOT TRUE THEN RETURN false;END IF;
 BEGIN
  from_time:=CASE WHEN selected_filters ? 'observedAtFrom' THEN (selected_filters->>'observedAtFrom')::timestamptz END;
  until_time:=CASE WHEN selected_filters ? 'observedAtUntil' THEN (selected_filters->>'observedAtUntil')::timestamptz END;
 EXCEPTION WHEN SQLSTATE '22007' OR SQLSTATE '22008' THEN
  RAISE EXCEPTION 'canonical mutation audit timestamp required' USING ERRCODE='22023';
 END;
 IF from_time IS NOT NULL OR until_time IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM truss.runtime_object_transition t
    CROSS JOIN LATERAL jsonb_array_elements(t.journal) j(value)
    WHERE t.attempt_id=attempt.id AND t.writer_xid=attempt.writer_xid
     AND (from_time IS NULL OR (j.value->>'at')::timestamptz>=from_time)
     AND (until_time IS NULL OR (j.value->>'at')::timestamptz<until_time))
   AND NOT EXISTS(SELECT 1 FROM truss.runtime_edge_transition t
    CROSS JOIN LATERAL jsonb_array_elements(t.journal) j(value)
    WHERE t.attempt_id=attempt.id AND t.writer_xid=attempt.writer_xid
     AND (from_time IS NULL OR (j.value->>'at')::timestamptz>=from_time)
     AND (until_time IS NULL OR (j.value->>'at')::timestamptz<until_time))
   AND NOT (EXISTS(SELECT 1 FROM truss.runtime_owned_operation p
    WHERE p.attempt_id=attempt.id AND p.writer_xid=attempt.writer_xid
     AND NOT EXISTS(SELECT 1 FROM truss.runtime_object_transition t
      CROSS JOIN LATERAL jsonb_array_elements(t.journal) j(value)
      WHERE t.attempt_id=attempt.id AND t.operation_index=p.operation_index AND t.writer_xid=attempt.writer_xid)
     AND NOT EXISTS(SELECT 1 FROM truss.runtime_edge_transition t
      CROSS JOIN LATERAL jsonb_array_elements(t.journal) j(value)
      WHERE t.attempt_id=attempt.id AND t.operation_index=p.operation_index AND t.writer_xid=attempt.writer_xid))
    AND attempt.audit_observed_at IS NOT NULL
    AND (from_time IS NULL OR attempt.audit_observed_at>=from_time)
    AND (until_time IS NULL OR attempt.audit_observed_at<until_time)) THEN RETURN false;END IF;
 END IF;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_mutation_audit_identity_matches(selected_attempt uuid, selected_filters jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;operation_row record;plan jsonb;map_row record;
 reference text;identity jsonb;kind text;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 FOR operation_row IN SELECT p.operation_index FROM truss.runtime_owned_operation p
  WHERE p.attempt_id=attempt.id AND p.writer_xid=attempt.writer_xid ORDER BY p.operation_index LOOP
  plan:=truss.runtime_owned_plan(attempt.id,operation_row.operation_index);
  FOR map_row IN SELECT * FROM (VALUES
    ('object',plan->'beforeNodes'),('object',plan->'afterNodes'),
    ('edge',plan->'beforeEdges'),('edge',plan->'afterEdges')) m(kind,value)
   WHERE jsonb_typeof(value)='object' LOOP
   kind:=map_row.kind;
   FOR reference IN SELECT key FROM jsonb_each(map_row.value) LOOP
    identity:=truss.runtime_owned_identity(attempt.id,operation_row.operation_index,reference,kind,plan,attempt);
    IF (NOT selected_filters ? 'entityId' OR identity->>'id'=selected_filters->>'entityId')
      AND (NOT selected_filters ? 'entityType' OR identity->>'typeId'=selected_filters->>'entityType')
      AND (NOT selected_filters ? 'documentId' OR
       (identity->'owner'->>'documentId'=selected_filters->>'documentId'
        AND identity->'owner'->>'moduleId'=selected_filters->>'moduleId')) THEN
     RETURN true;
    END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_mutation_audit_key_matches(selected_attempt uuid, key_filter jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;operation_row record;image_map jsonb;node record;
 operation_plan jsonb;image jsonb;identity jsonb;revision int;type_number int;key_number smallint;basis jsonb;
 key_definition truss.key_def%ROWTYPE;definition_pin text;codec jsonb;cells jsonb;provided_tuple bytea;stored_tuple bytea;
 type_definition truss.type_def%ROWTYPE;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 type_number:=(key_filter->>'typeId')::int;key_number:=(key_filter->>'keyNumber')::smallint;
 FOR operation_row IN SELECT p.operation_index FROM truss.runtime_owned_operation p
  WHERE p.attempt_id=attempt.id AND p.writer_xid=attempt.writer_xid LOOP
  operation_plan:=truss.runtime_owned_plan(attempt.id,operation_row.operation_index);
  FOR image_map IN SELECT value FROM (VALUES(operation_plan->'beforeNodes'),
       (operation_plan->'afterNodes')) x(value) WHERE jsonb_typeof(value)='object' LOOP
   FOR node IN SELECT value FROM jsonb_each(image_map) LOOP
    image:=node.value->'image';identity:=node.value->'identity';
    IF image IS NULL OR identity IS NULL OR image->>'type_id' IS DISTINCT FROM type_number::text
     OR identity->'owner' IS DISTINCT FROM jsonb_build_object(
       'documentId',key_filter->>'documentId','moduleId',key_filter->>'moduleId') THEN CONTINUE;END IF;
    revision:=(image->>'rev')::int;
    basis:=truss.catalog_all_expected_records(revision);
    SELECT k.* INTO key_definition FROM jsonb_populate_recordset(NULL::truss.key_def,basis->'key_def') k
     WHERE k.type_id=type_number AND k.key_num=key_number;
    IF NOT FOUND THEN CONTINUE;END IF;
    SELECT t.* INTO type_definition FROM jsonb_populate_recordset(NULL::truss.type_def,basis->'type_def') t
     WHERE t.type_id=type_number;
    IF NOT FOUND THEN RAISE EXCEPTION 'retained key owner definition unavailable' USING ERRCODE='P1010';END IF;
    SELECT d.definition_pin INTO definition_pin FROM truss.runtime_definition_source d
     WHERE d.rev=key_definition.definition_rev AND d.ord=key_definition.definition_doc_ord
      AND d.doc_id=key_definition.definition_document_id AND d.module_id=type_definition.module
      AND d.element_id=type_definition.element AND d.kind='key' AND d.key_id=key_definition.key_id;
    IF definition_pin IS DISTINCT FROM key_filter->>'definitionPin' THEN CONTINUE;END IF;
    SELECT s.metadata->'keyCodecs'->key_number::text INTO codec FROM truss.runtime_type_schema s
     WHERE s.rev=revision AND s.type_id=type_number;
    IF codec IS NULL THEN RAISE EXCEPTION 'retained key codec unavailable' USING ERRCODE='P1010';END IF;
    SELECT jsonb_agg(image->'props'->component.prop_id::text ORDER BY component.ordinality)
     INTO cells FROM unnest(key_definition.prop_ids) WITH ORDINALITY component(prop_id,ordinality);
    IF cells IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(cells) c WHERE c.value IS NULL OR c.value='null'::jsonb) THEN CONTINUE;END IF;
    provided_tuple:=truss.runtime_owned_key_tuple_in_metadata(type_number,key_number,key_filter->'values',codec);
    stored_tuple:=truss.runtime_owned_key_tuple_in_metadata(type_number,key_number,cells,codec);
    IF stored_tuple=provided_tuple THEN RETURN true;END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_object_attempt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' OR OLD.complete THEN RAISE EXCEPTION 'settled attempt immutable' USING ERRCODE='55000';END IF;
 IF ROW(OLD.id,OLD.writer_xid,OLD.actor_oid)
  IS DISTINCT FROM ROW(NEW.id,NEW.writer_xid,NEW.actor_oid)
 THEN RAISE EXCEPTION 'original attempt immutable' USING ERRCODE='55000';END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_object_commit_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;actual jsonb;expected jsonb;endpoint record;selected_edge bigint;selected_relation int;journal_kind text;journal_id bigint;journal_type int;current_actor oid;journal_problem boolean;expected_count bigint;distinct_expected bigint;actual_count bigint;owned_resource_kind text;owned_resource_type int;owner_document text;owner_module text;
BEGIN
 -- One fresh actor per constraint-trigger event. Resource authorization stays
 -- live below; this identity is never retained across events or commands.
 -- A completed native attempt owns its exact transition callback. Its mandatory
 -- attempt constraint performs the single current-authority/effect settlement;
 -- legacy and catalog-owned transitions retain their row validator.
 IF TG_TABLE_NAME IN ('runtime_object_transition','runtime_edge_transition') THEN
  IF EXISTS(SELECT 1 FROM truss.runtime_object_attempt a WHERE a.id=NEW.attempt_id
    AND a.writer_xid=pg_current_xact_id() AND a.complete
    AND a.context->'mutationProfile'=truss.runtime_owned_profile()) THEN
   IF TG_TABLE_NAME='runtime_object_transition' THEN
    owned_resource_kind:='object';owned_resource_type:=NEW.type_id;
   ELSE
    owned_resource_kind:='edge';owned_resource_type:=NEW.rel_type_id;
   END IF;
  END IF;
 END IF;
 -- For an entity INSERT/UPDATE, tie the queued row image to the owned transition
 -- header. A later same-owner legacy/rebind write has a different version or
 -- catalog revision and must keep the ordinary row/graph/journal checks.
 IF TG_TABLE_NAME='object' AND TG_OP IN ('INSERT','UPDATE') THEN
  IF EXISTS(
   SELECT 1 FROM truss.runtime_object_transition t JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
   WHERE t.writer_xid=pg_current_xact_id() AND t.object_id=NEW.id AND t.type_id=NEW.type_id
    AND t.after_object->>'id'=NEW.id::text AND t.after_object->>'type_id'=NEW.type_id::text
    AND t.after_object->>'ver'=NEW.ver::text AND t.after_object->>'rev'=NEW.rev::text
    AND t.after_object->'root_id'=coalesce(to_jsonb(NEW.root_id),'null'::jsonb)
    AND t.after_object->'root_type'=coalesce(to_jsonb(NEW.root_type),'null'::jsonb)
    AND a.writer_xid=pg_current_xact_id() AND a.complete
    AND a.context->'mutationProfile'=truss.runtime_owned_profile()) THEN
   owned_resource_kind:='object';owned_resource_type:=NEW.type_id;
  END IF;
 END IF;
 -- Deleted objects are attributed to the owned deletion's before header.
 IF TG_TABLE_NAME='object' AND TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM truss.runtime_object_transition t JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
   WHERE t.writer_xid=pg_current_xact_id() AND t.object_id=OLD.id AND t.type_id=OLD.type_id
    AND t.after_object IS NULL AND t.before_object->>'ver'=OLD.ver::text AND t.before_object->>'rev'=OLD.rev::text
    AND t.before_object->'root_id'=coalesce(to_jsonb(OLD.root_id),'null'::jsonb)
    AND t.before_object->'root_type'=coalesce(to_jsonb(OLD.root_type),'null'::jsonb)
    AND a.writer_xid=pg_current_xact_id() AND a.complete AND a.context->'mutationProfile'=truss.runtime_owned_profile()) THEN
   owned_resource_kind:='object';owned_resource_type:=OLD.type_id;
  END IF;
 END IF;
 -- Match each queued edge header to its completed owned effect. Later legacy
 -- writes have a different header and retain their legacy validator.
 IF TG_TABLE_NAME='edge' THEN
  IF TG_OP='DELETE' THEN
   IF EXISTS(SELECT 1 FROM truss.runtime_edge_transition t JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
    WHERE t.writer_xid=pg_current_xact_id() AND t.edge_id=OLD.id AND t.rel_type_id=OLD.rel_type_id
     AND t.after_edge IS NULL AND t.before_edge->>'ver'=OLD.ver::text AND t.before_edge->>'rev'=OLD.rev::text
     AND t.before_edge->>'source_id'=OLD.source_id::text AND t.before_edge->>'target_id'=OLD.target_id::text
     AND t.before_edge->>'source_type'=OLD.source_type::text AND t.before_edge->>'target_type'=OLD.target_type::text
     AND a.writer_xid=pg_current_xact_id() AND a.complete AND a.context->'mutationProfile'=truss.runtime_owned_profile()) THEN
    owned_resource_kind:='edge';owned_resource_type:=OLD.rel_type_id;
   END IF;
  ELSE
   IF EXISTS(SELECT 1 FROM truss.runtime_edge_transition t JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
    WHERE t.writer_xid=pg_current_xact_id() AND t.edge_id=NEW.id AND t.rel_type_id=NEW.rel_type_id
     AND t.after_edge->>'ver'=NEW.ver::text AND t.after_edge->>'rev'=NEW.rev::text
     AND t.after_edge->>'source_id'=NEW.source_id::text AND t.after_edge->>'target_id'=NEW.target_id::text
     AND t.after_edge->>'source_type'=NEW.source_type::text AND t.after_edge->>'target_type'=NEW.target_type::text
     AND a.writer_xid=pg_current_xact_id() AND a.complete AND a.context->'mutationProfile'=truss.runtime_owned_profile()) THEN
    owned_resource_kind:='edge';owned_resource_type:=NEW.rel_type_id;
   END IF;
  END IF;
 END IF;
 -- A completed owned callback still rechecks current caller identity and writer
 -- authority for the row's exact owning module before taking its cheap path.
 IF owned_resource_type IS NOT NULL THEN
  -- The completed attempt already passed full actor qualification. Refresh
  -- only direct session safety flags and the exact module-writer membership;
  -- do not rescan installation privileges and every catalog table per row.
  SELECT r.oid INTO current_actor FROM pg_roles r
   WHERE r.rolname=session_user AND current_setting('role')='none' AND r.rolcanlogin
    AND NOT r.rolsuper AND NOT r.rolcreaterole AND NOT r.rolcreatedb AND NOT r.rolreplication AND NOT r.rolbypassrls;
  IF NOT FOUND THEN RAISE EXCEPTION 'current qualified module writer required' USING ERRCODE='42501';END IF;
  IF owned_resource_kind='object' THEN
   SELECT document_id,module INTO STRICT owner_document,owner_module FROM truss.type_def WHERE type_id=owned_resource_type;
  ELSE
   SELECT document_id,module INTO STRICT owner_document,owner_module FROM truss.rel_def WHERE rel_type_id=owned_resource_type;
  END IF;
  PERFORM truss.runtime_module_writer_qualified(owner_document,owner_module,current_actor);
  RETURN NULL;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolsuper) THEN RETURN NULL;END IF;
 -- A completed owned attempt requalifies actor and dependencies once in its
 -- mandatory settlement. Issue current identity here only for the legacy paths.
 IF TG_TABLE_NAME IN ('object','runtime_object_transition','runtime_catalog_rebind_transition','runtime_catalog_key_backfill','edge','runtime_edge_transition') THEN
  current_actor:=truss.runtime_person(false);END IF;
 IF TG_TABLE_NAME='runtime_object_attempt' THEN
  SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=NEW.id;
  IF NOT attempt.complete OR attempt.writer_xid<>pg_current_xact_id() OR attempt.actor_oid<>truss.runtime_person(false)
   OR attempt.next_index<>jsonb_array_length(convert_from(attempt.input_bytes,'UTF8')::jsonb->'operations')
   OR jsonb_array_length(attempt.results)<>attempt.next_index THEN RAISE EXCEPTION 'complete current mutation attempt required' USING ERRCODE='55000';END IF;
  IF convert_from(attempt.input_bytes,'UTF8')::jsonb->'mutationProfile'=truss.runtime_owned_profile() THEN PERFORM truss.runtime_owned_group_validate(attempt.id,false);END IF;
  IF attempt.receipt_id IS NOT NULL THEN
   SELECT * INTO STRICT endpoint FROM truss.request_receipt r WHERE storage_row_id=attempt.receipt_id;
   IF attempt.expected_receipt IS NOT NULL THEN
    IF to_jsonb(endpoint) IS DISTINCT FROM attempt.expected_receipt THEN RAISE EXCEPTION 'exact original group receipt required' USING ERRCODE='55000';END IF;
   ELSIF convert_from(attempt.input_bytes,'UTF8')::jsonb->'mutationProfile'=truss.runtime_owned_profile() THEN
    IF endpoint.storage_row_id IS DISTINCT FROM attempt.receipt_id OR endpoint.namespace_identity_utf8 IS DISTINCT FROM convert_to(attempt.context->>'authorizedScopeIdentity','UTF8')
     OR endpoint.request_id_utf8 IS DISTINCT FROM convert_to(convert_from(attempt.request_bytes,'UTF8')::jsonb->'identity'->>'requestId','UTF8')
     OR endpoint.original_writer_xid IS DISTINCT FROM attempt.writer_xid OR endpoint.lifecycle_generation<>0
     OR endpoint.payload_state IS DISTINCT FROM 'complete' OR endpoint.original_receipt_bytes IS NULL
     OR endpoint.expired_identity_bytes IS NOT NULL OR endpoint.expiry_writer_xid IS NOT NULL OR endpoint.expiry_writer_context_bytes IS NOT NULL THEN
     RAISE EXCEPTION 'exact original group receipt header required' USING ERRCODE='55000';END IF;
   ELSE RAISE EXCEPTION 'original receipt binding required' USING ERRCODE='55000';END IF;
   IF attempt.position_bytes IS DISTINCT FROM truss.runtime_receipt_position(attempt.context,attempt.receipt_id,attempt.writer_xid) THEN RAISE EXCEPTION 'exact original receipt position required' USING ERRCODE='55000';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='object' THEN
  IF TG_OP='DELETE' THEN PERFORM truss.runtime_owned_row_validate_qualified(OLD.id,OLD.type_id,current_actor);ELSE PERFORM truss.runtime_owned_row_validate_qualified(NEW.id,NEW.type_id,current_actor);END IF;
 ELSIF TG_TABLE_NAME IN ('runtime_object_transition','runtime_catalog_rebind_transition','runtime_catalog_key_backfill') THEN PERFORM truss.runtime_owned_row_validate_qualified(NEW.object_id,NEW.type_id,current_actor);
 ELSIF TG_TABLE_NAME='edge' THEN
  IF TG_OP='DELETE' THEN PERFORM truss.runtime_owned_edge_validate_in_input_qualified(OLD.id,OLD.rel_type_id,NULL,NULL,NULL,current_actor);ELSE PERFORM truss.runtime_owned_edge_validate_in_input_qualified(NEW.id,NEW.rel_type_id,NULL,NULL,NULL,current_actor);END IF;
 ELSIF TG_TABLE_NAME='runtime_edge_transition' THEN PERFORM truss.runtime_owned_edge_validate_in_input_qualified(NEW.edge_id,NEW.rel_type_id,NULL,NULL,NULL,current_actor);
 ELSE RAISE EXCEPTION 'registered mutation commit event required' USING ERRCODE='55000';END IF;
 -- Attempt and catalog settlement still validate the complete affected graph.
 -- Row events recheck every endpoint they can change, avoiding a complete
 -- transaction scan for each row. No validation cache survives later writes.
 IF TG_TABLE_NAME='runtime_object_attempt' THEN
  IF attempt.context->'mutationProfile'=truss.runtime_owned_profile() THEN
   PERFORM truss.runtime_owned_graph_validate_attempt(attempt.id,false);
   RETURN NULL;
  ELSE PERFORM truss.runtime_graph_validate(false);END IF;
 ELSIF TG_TABLE_NAME='object' THEN
  -- Values/version/timestamps cannot change topology or multiplicity. Every
  -- actual edge/ownership/catalog change still queues its own structural check.
  IF TG_OP='DELETE' THEN PERFORM truss.runtime_graph_validate_object_qualified(OLD.id,OLD.type_id,false,current_actor);
  ELSIF TG_OP<>'UPDATE' OR ROW(OLD.id,OLD.type_id,OLD.root_id,OLD.root_type,OLD.rev)
    IS DISTINCT FROM ROW(NEW.id,NEW.type_id,NEW.root_id,NEW.root_type,NEW.rev) THEN
   PERFORM truss.runtime_graph_validate_object_qualified(NEW.id,NEW.type_id,false,current_actor);END IF;
 ELSIF TG_TABLE_NAME='runtime_object_transition' THEN
  IF (NEW.before_object-ARRAY['props','retained','ver','created_at','updated_at'])
    IS DISTINCT FROM (NEW.after_object-ARRAY['props','retained','ver','created_at','updated_at']) THEN
   PERFORM truss.runtime_graph_validate_object_qualified(NEW.object_id,NEW.type_id,false,current_actor);END IF;
 ELSIF TG_TABLE_NAME IN ('runtime_catalog_rebind_transition','runtime_catalog_key_backfill') THEN
  PERFORM truss.runtime_graph_validate_object_qualified(NEW.object_id,NEW.type_id,false,current_actor);
 ELSE
  -- Include old and new endpoints of every transition for this edge in this
  -- transaction, including retargets and deletion. Final-edge endpoints alone
  -- would miss a formerly connected object's minimum multiplicity.
  IF TG_TABLE_NAME='runtime_edge_transition' THEN selected_edge:=NEW.edge_id;selected_relation:=NEW.rel_type_id;
  ELSIF TG_OP='DELETE' THEN selected_edge:=OLD.id;selected_relation:=OLD.rel_type_id;
  ELSE selected_edge:=NEW.id;selected_relation:=NEW.rel_type_id;END IF;
  FOR endpoint IN SELECT DISTINCT (i.value->>'id')::bigint id,(i.value->>'typeId')::int type_id
   FROM truss.runtime_edge_transition t
   CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(t.old_source,t.old_target,t.source_identity,t.target_identity)) i
   WHERE t.writer_xid=pg_current_xact_id() AND i.value<>'null'::jsonb
    AND t.edge_id=selected_edge
    AND t.rel_type_id=selected_relation
  LOOP
   PERFORM truss.runtime_graph_validate_object_qualified(endpoint.id,endpoint.type_id,false,current_actor);
  END LOOP;
 END IF;
 -- Ordinary entity events compare the complete journal for their typed owner.
 -- Mandatory attempt, catalog and legacy settlement keep transaction closure.
 IF TG_TABLE_NAME='object' THEN
  journal_kind:='o';
  IF TG_OP='DELETE' THEN journal_id:=OLD.id;journal_type:=OLD.type_id;
  ELSE journal_id:=NEW.id;journal_type:=NEW.type_id;END IF;
 ELSIF TG_TABLE_NAME='runtime_object_transition' THEN
  journal_kind:='o';journal_id:=NEW.object_id;journal_type:=NEW.type_id;
 ELSIF TG_TABLE_NAME='edge' THEN
  journal_kind:='e';
  IF TG_OP='DELETE' THEN journal_id:=OLD.id;journal_type:=OLD.rel_type_id;
  ELSE journal_id:=NEW.id;journal_type:=NEW.rel_type_id;END IF;
 ELSIF TG_TABLE_NAME='runtime_edge_transition' THEN
  journal_kind:='e';journal_id:=NEW.edge_id;journal_type:=NEW.rel_type_id;
 END IF;
 -- Match each claim to its indexed physical row without aggregating event
 -- payloads. Keep entity and transaction statements separate so generic plans
 -- retain the entity index instead of scanning the whole xid for every object.
 IF journal_kind IS NOT NULL THEN
  WITH expected(value) AS MATERIALIZED (
   SELECT g.expected_members->m.operation_index->'journal'
   FROM truss.runtime_create_member m JOIN truss.runtime_create_group g USING(group_id)
   WHERE g.writer_xid=pg_current_xact_id() AND journal_kind='o' AND m.object_id=journal_id AND m.type_id=journal_type
   UNION ALL SELECT j.value FROM truss.runtime_object_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j
   WHERE t.writer_xid=pg_current_xact_id() AND journal_kind='o' AND t.object_id=journal_id AND t.type_id=journal_type
   UNION ALL SELECT j.value FROM truss.runtime_catalog_rebind_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j
   WHERE t.writer_xid=pg_current_xact_id() AND journal_kind='o' AND t.object_id=journal_id AND t.type_id=journal_type
   UNION ALL SELECT j.value FROM truss.runtime_edge_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j
   WHERE t.writer_xid=pg_current_xact_id() AND journal_kind='e' AND t.edge_id=journal_id AND t.rel_type_id=journal_type)
  SELECT count(*),count(DISTINCT ROW((e.value->>'at')::timestamptz,(e.value->>'seq')::bigint)),
   coalesce(bool_or((p.physical).seq IS NULL OR CASE WHEN e.value ? 'referenceProfile'
    THEN e.value IS DISTINCT FROM truss.runtime_owned_journal_reference(p.physical)
    ELSE e.value IS DISTINCT FROM to_jsonb(p.physical) END),false)
  INTO expected_count,distinct_expected,journal_problem
  FROM expected e LEFT JOIN LATERAL (
   SELECT j physical FROM truss.journal j WHERE j.at=(e.value->>'at')::timestamptz AND j.seq=(e.value->>'seq')::bigint
    AND j.xid=pg_current_xact_id() AND j.entity_kind=journal_kind AND j.entity_id=journal_id AND j.entity_type=journal_type OFFSET 0) p ON true;
  SELECT count(*) INTO actual_count FROM truss.journal j WHERE j.xid=pg_current_xact_id() AND j.entity_kind=journal_kind AND j.entity_id=journal_id AND j.entity_type=journal_type;
 ELSE
  WITH expected(value) AS MATERIALIZED (
   SELECT g.expected_members->m.operation_index->'journal'
   FROM truss.runtime_create_member m JOIN truss.runtime_create_group g USING(group_id)
   WHERE g.writer_xid=pg_current_xact_id()
   UNION ALL SELECT j.value FROM truss.runtime_object_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j
   WHERE t.writer_xid=pg_current_xact_id()
   UNION ALL SELECT j.value FROM truss.runtime_catalog_rebind_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j
   WHERE t.writer_xid=pg_current_xact_id()
   UNION ALL SELECT j.value FROM truss.runtime_edge_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j
   WHERE t.writer_xid=pg_current_xact_id())
  SELECT count(*),count(DISTINCT ROW((e.value->>'at')::timestamptz,(e.value->>'seq')::bigint)),
   coalesce(bool_or((p.physical).seq IS NULL OR CASE WHEN e.value ? 'referenceProfile'
    THEN e.value IS DISTINCT FROM truss.runtime_owned_journal_reference(p.physical)
    ELSE e.value IS DISTINCT FROM to_jsonb(p.physical) END),false)
  INTO expected_count,distinct_expected,journal_problem
  FROM expected e LEFT JOIN LATERAL (
   SELECT j physical FROM truss.journal j WHERE j.at=(e.value->>'at')::timestamptz AND j.seq=(e.value->>'seq')::bigint
    AND j.xid=pg_current_xact_id() OFFSET 0) p ON true;
  SELECT count(*) INTO actual_count FROM truss.journal j WHERE j.xid=pg_current_xact_id();
 END IF;
 IF journal_problem OR expected_count<>distinct_expected OR expected_count<>actual_count THEN
  RAISE EXCEPTION 'complete mutation journal required' USING ERRCODE='55000';END IF;
 RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_object_history(object_image jsonb, identity jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE properties jsonb:='[]';property_items jsonb[]:='{}';retained jsonb;property truss.prop_def%ROWTYPE;pin record;basis jsonb;written_revision int:=(object_image->>'rev')::int;compiled jsonb;
BEGIN
 SELECT metadata-'propertyAccess' INTO compiled FROM truss.runtime_type_schema
  WHERE rev=written_revision AND type_id=(object_image->>'type_id')::int;
 IF FOUND AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(object_image->'props') n(name)
  WHERE NOT ((compiled->'propertyPins') ? n.name)) THEN
  RETURN truss.runtime_owned_history_record_in_metadata(object_image,identity,compiled);
 END IF;
 SELECT CASE WHEN written_revision=(SELECT rev FROM truss.schema_head WHERE id=1)
  AND NOT EXISTS(SELECT 1 FROM truss.schema_rev WHERE rev>written_revision)
 THEN jsonb_build_object(
   'type_def',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM truss.type_def t WHERE t.type_id=(object_image->>'type_id')::int),
   'prop_def',(SELECT coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) FROM truss.prop_def p WHERE p.type_id=(object_image->>'type_id')::int)) END INTO basis;
 IF basis IS NULL THEN basis:=truss.catalog_all_expected_records(written_revision);END IF;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata_in_basis('type',(object_image->>'type_id')::int,NULL,written_revision,basis);
 identity:=jsonb_set(identity,'{definitionPin}',to_jsonb(pin.definition_pin));
 FOR property IN SELECT * FROM jsonb_populate_recordset(NULL::truss.prop_def,basis->'prop_def') p WHERE p.type_id=(object_image->>'type_id')::int ORDER BY prop_id LOOP
  IF object_image->'props' ? property.prop_id::text THEN
   SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata_in_basis('property',property.type_id,property.prop_id,written_revision,basis);
   property_items[cardinality(property_items)+1]:=jsonb_build_object('propertyId',property.prop_id::text,'definitionPin',pin.definition_pin,'value',object_image->'props'->property.prop_id::text);
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(item ORDER BY ord),'[]'::jsonb) INTO properties FROM unnest(property_items) WITH ORDINALITY p(item,ord);
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',key,'value',value) ORDER BY key COLLATE "C"),'[]'::jsonb) INTO retained FROM jsonb_each(coalesce(nullif(object_image->'retained','null'::jsonb),'{}'));
 RETURN jsonb_build_object('interfaceVersion','truss-history-record/0.1.0','kind','object','identity',identity,
  'recordVersion',object_image->>'ver','catalogRevision',object_image->>'rev',
  'createdAt',to_char((object_image->>'created_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'updatedAt',to_char((object_image->>'updated_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'properties',properties,'retained',retained,'ownership',truss.runtime_object_ownership_at(object_image));
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_object_metadata(attempt_id uuid, operation_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;operation jsonb;selected truss.type_def%ROWTYPE;identity jsonb;prior truss.object%ROWTYPE;
 property truss.prop_def%ROWTYPE;entry jsonb;props jsonb;retained jsonb;values jsonb;keys jsonb;unset_property_ids text[];unset_retained_names text[];set_props jsonb;set_retained jsonb;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id FOR UPDATE NOWAIT;
 IF attempt.writer_xid<>pg_current_xact_id() OR attempt.actor_oid<>truss.runtime_person(false) OR attempt.complete OR attempt.next_index<>operation_index THEN
  RAISE EXCEPTION 'current ordered attempt required' USING ERRCODE='55000';END IF;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;operation:=input->'operations'->operation_index;
 IF operation->>'operation' IN ('create_edge','update_edge','delete_edge') THEN RETURN truss.runtime_edge_metadata(attempt_id,operation_index);END IF;
 selected:=truss.runtime_operation_type(operation,input->'operations',operation_index);PERFORM truss.runtime_module_writer(selected.document_id,selected.module);
 IF operation->>'operation'='create_object' THEN
  -- Reject malformed key cells natively before calling the external UMF
  -- producer, so caller input failures remain GroupFailed rather than host errors.
  IF jsonb_typeof(operation->'values') IS DISTINCT FROM 'array' OR jsonb_array_length(operation->'values')>1024 THEN RAISE EXCEPTION 'bounded authored create values required' USING ERRCODE='22023';END IF;
  FOR property IN SELECT DISTINCT p.* FROM truss.key_def k CROSS JOIN LATERAL unnest(k.prop_ids) i(prop_id)
   JOIN truss.prop_def p ON p.type_id=k.type_id AND p.prop_id=i.prop_id WHERE k.type_id=selected.type_id AND k.retired_rev IS NULL LOOP
   IF property.scalar_type NOT IN ('string','integer','decimal','boolean','binary') OR property.scalar_type IS NULL
    OR property.nullability IS DISTINCT FROM 'required' OR property.cardinality IS DISTINCT FROM 'one' OR property.home IS DISTINCT FROM 'json'
    OR property.retired_rev IS NOT NULL OR (property.scalar_type='decimal' AND (truss.valid_decimal_facets(property.facets)) IS DISTINCT FROM TRUE) THEN
    RAISE EXCEPTION 'supported required scalar key property required' USING ERRCODE='0A000';END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(operation->'values') v WHERE v.value->>'name'=property.name)<>1 THEN RAISE EXCEPTION 'complete unique key values required' USING ERRCODE='22023';END IF;
   SELECT v.value->'value' INTO entry FROM jsonb_array_elements(operation->'values') v WHERE v.value->>'name'=property.name;
   IF truss.valid_scalar_property(entry,property.scalar_type,false,property.facets) IS NOT TRUE THEN RAISE EXCEPTION 'exact declared key cell required' USING ERRCODE='22023';END IF;
  END LOOP;
  RETURN convert_from(truss.group_create_metadata(convert_to(jsonb_set(input-'preconditions','{operations}',jsonb_build_array(operation))::text,'UTF8'),attempt.documents_bytes,
   (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation())),'UTF8')::jsonb->0
   ||jsonb_build_object('values',operation->'values');
 END IF;
 IF operation->'target'->>'state'='stored' THEN identity:=operation->'target'->'identity';
 ELSE SELECT value->'identity' INTO STRICT identity FROM jsonb_array_elements(attempt.aliases) WHERE value->>'alias'=operation->'target'->>'alias';END IF;
 SELECT * INTO prior FROM truss.object WHERE id=(identity->>'id')::bigint AND type_id=selected.type_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'target absent' USING ERRCODE='P1004';END IF;
 IF prior.root_id IS NOT NULL THEN RAISE EXCEPTION 'rootless scalar object required' USING ERRCODE='0A000';END IF;
 IF operation ? 'expectedVersion' AND (jsonb_typeof(operation->'expectedVersion') IS DISTINCT FROM 'string' OR operation->>'expectedVersion' IS DISTINCT FROM prior.ver::text) THEN
  RAISE EXCEPTION 'expected version failed' USING ERRCODE='P1003';END IF;
 IF operation->>'operation'='delete_object' THEN
  IF operation-ARRAY['operation','target','expectedVersion']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed delete required' USING ERRCODE='22023';END IF;
  IF EXISTS(SELECT 1 FROM truss.edge WHERE source_id=prior.id AND source_type=prior.type_id OR target_id=prior.id AND target_type=prior.type_id)
   OR EXISTS(SELECT 1 FROM truss.object WHERE root_id=prior.id AND root_type=prior.type_id) THEN RAISE EXCEPTION 'delete dependencies exist' USING ERRCODE='P1005';END IF;
  RETURN jsonb_build_object('typeId',selected.type_id::text,'documentId',selected.document_id,'moduleId',selected.module,'recordId',selected.element,
   'identity',identity,'prior',to_jsonb(prior),'keys','[]'::jsonb,'values','[]'::jsonb);
 END IF;
 IF operation-ARRAY['operation','target','set','unset','expectedVersion']<>'{}'::jsonb OR jsonb_typeof(operation->'set') IS DISTINCT FROM 'array'
 OR jsonb_typeof(operation->'unset') IS DISTINCT FROM 'array' OR jsonb_array_length(operation->'set')>1024 OR jsonb_array_length(operation->'unset')>1024 THEN
  RAISE EXCEPTION 'closed bounded scalar update required' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(operation->'set') s WHERE s.value-ARRAY['name','value']<>'{}'::jsonb
  OR jsonb_typeof(s.value->'name') IS DISTINCT FROM 'string' OR octet_length(s.value->>'name') NOT BETWEEN 1 AND 4096 OR truss.valid_flat_cell(s.value->'value') IS NOT TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(operation->'unset') u WHERE jsonb_typeof(u.value) IS DISTINCT FROM 'string' OR octet_length(u.value#>>'{}') NOT BETWEEN 1 AND 4096)
 OR jsonb_array_length(operation->'set')<>(SELECT count(DISTINCT s.value->>'name') FROM jsonb_array_elements(operation->'set') s)
 OR jsonb_array_length(operation->'unset')<>(SELECT count(DISTINCT u.value) FROM jsonb_array_elements(operation->'unset') u)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(operation->'set') s JOIN jsonb_array_elements(operation->'unset') u ON s.value->>'name'=u.value#>>'{}') THEN
  RAISE EXCEPTION 'unique disjoint update names required' USING ERRCODE='22023';END IF;
 props:=prior.props;retained:=coalesce(prior.retained,'{}');
 SELECT coalesce(array_agg(p.prop_id::text) FILTER(WHERE p.prop_id IS NOT NULL),'{}'::text[]),
  coalesce(array_agg(u.value#>>'{}') FILTER(WHERE p.prop_id IS NULL),'{}'::text[])
 INTO unset_property_ids,unset_retained_names
 FROM jsonb_array_elements(operation->'unset') u(value)
 LEFT JOIN truss.prop_def p ON p.type_id=selected.type_id AND p.name=u.value#>>'{}' AND p.retired_rev IS NULL;
 props:=props-unset_property_ids;retained:=retained-unset_retained_names;
 SELECT coalesce(jsonb_object_agg(p.prop_id::text,truss.canonical_flat_cell(s.value->'value')) FILTER(WHERE p.prop_id IS NOT NULL),'{}'::jsonb),
  coalesce(jsonb_object_agg(s.value->>'name',truss.canonical_flat_cell(s.value->'value')) FILTER(WHERE p.prop_id IS NULL),'{}'::jsonb)
 INTO set_props,set_retained
 FROM jsonb_array_elements(operation->'set') s(value)
 LEFT JOIN truss.prop_def p ON p.type_id=selected.type_id AND p.name=s.value->>'name' AND p.retired_rev IS NULL;
 props:=props||set_props;retained:=retained||set_retained;
 FOR property IN SELECT * FROM truss.prop_def WHERE type_id=selected.type_id AND retired_rev IS NULL LOOP
  IF truss.valid_property_definition(property) IS NOT TRUE THEN
   RAISE EXCEPTION 'supported scalar definition required' USING ERRCODE='0A000';END IF;
  IF NOT props ? property.prop_id::text THEN
   IF property.nullability='required' THEN RAISE EXCEPTION 'missing required value' USING ERRCODE='22023';END IF;
  ELSIF truss.valid_property_value(props->property.prop_id::text,property) IS NOT TRUE THEN RAISE EXCEPTION 'exact family required' USING ERRCODE='22023';END IF;
 END LOOP;
 IF octet_length(convert_to(jsonb_build_object('props',props,'retained',retained)::text,'UTF8'))>1048576 THEN RAISE EXCEPTION 'bounded object values required' USING ERRCODE='54000';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',v.name,'value',v.value) ORDER BY v.name COLLATE "C"),'[]'::jsonb) INTO values FROM (
  SELECT p.name,props->p.prop_id::text AS value FROM truss.prop_def p WHERE p.type_id=selected.type_id AND p.retired_rev IS NULL AND props ? p.prop_id::text
  UNION ALL SELECT key,value FROM jsonb_each(retained)) v;
 SELECT coalesce(jsonb_agg(jsonb_build_object('keyNumber',k.key_num::text,'keyId',k.key_id,'names',
  (SELECT jsonb_agg(p.name ORDER BY i.ord) FROM unnest(k.prop_ids) WITH ORDINALITY i(prop_id,ord) JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=k.type_id)) ORDER BY k.key_num),'[]'::jsonb)
 INTO keys FROM truss.key_def k WHERE k.type_id=selected.type_id AND k.retired_rev IS NULL;
 RETURN jsonb_build_object('typeId',selected.type_id::text,'documentId',selected.document_id,'moduleId',selected.module,'recordId',selected.element,
  'identity',identity,'prior',to_jsonb(prior),'props',props,'retained',retained,'keys',keys,'values',values);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_object_ownership_at(object_image jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE revision int;root_id bigint;root_type int;pin record;
BEGIN
 IF jsonb_typeof(object_image) IS DISTINCT FROM 'object'
  OR NOT (object_image ?& ARRAY['id','type_id','root_id','root_type','rev']) THEN
  RAISE EXCEPTION 'original complete object root fields required' USING ERRCODE='55000';END IF;
 IF (object_image->'root_id'='null'::jsonb) IS DISTINCT FROM (object_image->'root_type'='null'::jsonb) THEN
  RAISE EXCEPTION 'complete original root pair required' USING ERRCODE='55000';END IF;
 IF object_image->'root_id'='null'::jsonb THEN RETURN '{"state":"rootless"}'::jsonb;END IF;
 revision:=(object_image->>'rev')::int;root_id:=(object_image->>'root_id')::bigint;root_type:=(object_image->>'root_type')::int;
 IF revision IS NULL OR revision<1 OR root_id IS NULL OR root_id<1 OR root_type IS NULL OR root_type<1
  OR root_id=(object_image->>'id')::bigint AND root_type=(object_image->>'type_id')::int THEN
  RAISE EXCEPTION 'original aggregate root identity required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',root_type,NULL,revision);
 RETURN jsonb_build_object('state','owned','root',jsonb_build_object('id',root_id::text,
  'typeId',root_type::text,'definitionPin',pin.definition_pin,
  'owner',jsonb_build_object('documentId',pin.document_id,'moduleId',pin.module_id)));
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_object_update_keys(object_id bigint, selected_type integer, desired_props jsonb, original_keys bytea, attempt_id uuid, operation_index integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;key_definition truss.key_def%ROWTYPE;component record;values_text text[];value_cell_buffer jsonb[];values_cells jsonb;
 keys jsonb;key_input jsonb;tuple_bytes bytea;owner_receipt jsonb;pin record;ns bytea;transport bytea;planned_buffer jsonb[]:=ARRAY[]::jsonb[];planned jsonb;entry jsonb;
 old truss.object_key_bucket%ROWTYPE;members bigint[];reservations bigint[];observed record;unchanged boolean;route record;
BEGIN
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF original_keys IS NULL OR octet_length(original_keys) NOT BETWEEN 1 AND 8388608 OR (convert_from(original_keys,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN
  RAISE EXCEPTION 'bounded original key inventory required' USING ERRCODE='22023';END IF;
 keys:=convert_from(original_keys,'UTF8')::jsonb;
 IF keys<>'[]'::jsonb THEN RAISE EXCEPTION 'client key encoding is no longer accepted' USING ERRCODE='22023';END IF;
 FOR key_definition IN SELECT * FROM truss.key_def WHERE type_id=selected_type AND retired_rev IS NULL ORDER BY key_num LOOP
  values_text:=ARRAY[]::text[];value_cell_buffer:=ARRAY[]::jsonb[];
  FOR component IN SELECT p.* FROM unnest(key_definition.prop_ids) WITH ORDINALITY i(prop_id,ord) JOIN truss.prop_def p ON p.prop_id=i.prop_id AND p.type_id=selected_type ORDER BY i.ord LOOP
   IF component.scalar_type NOT IN ('string','integer','decimal','boolean','binary') OR component.nullability IS DISTINCT FROM 'required'
    OR truss.valid_scalar_property(desired_props->component.prop_id::text,component.scalar_type,false,component.facets) IS NOT TRUE THEN
    RAISE EXCEPTION 'required exact key components required' USING ERRCODE='0A000';END IF;
   value_cell_buffer:=array_append(value_cell_buffer,desired_props->component.prop_id::text);
  END LOOP;
  values_cells:=to_jsonb(value_cell_buffer);
  IF values_cells IS NULL THEN values_cells:='[]'::jsonb;END IF;
  tuple_bytes:=truss.derive_catalog_key_tuple(selected_type,key_definition.key_num,values_cells);
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',selected_type,key_definition.key_num);
  ns:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,
   'sourceEpoch',installation.source_epoch::text,'typeId',selected_type::text,'keyNumber',key_definition.key_num::text,
   'definitionPin',pin.definition_pin,'encoding','umf-key-tuple-v1')::text,'UTF8');
  transport:=convert_to('umf-key-tuple-v1:hex:'||encode(tuple_bytes,'hex'),'UTF8');
  SELECT * INTO STRICT old FROM truss.object_key_bucket k WHERE k.object_id=runtime_object_update_keys.object_id AND k.type_id=selected_type AND k.key_num=key_definition.key_num;
  planned_buffer:=array_append(planned_buffer,jsonb_build_object('keyNumber',key_definition.key_num,'ns',encode(ns,'hex'),'transport',encode(transport,'hex'),
   'oldId',old.storage_row_id,'oldNs',encode(old.namespace_bytes,'hex'),'oldTransport',encode(old.key_bytes,'hex')));
 END LOOP;
 planned:=to_jsonb(planned_buffer);
 IF planned IS NULL THEN planned:='[]'::jsonb;END IF;
 FOR route IN SELECT DISTINCT routes.ns,routes.transport FROM (
  SELECT decode(value->>'ns','hex') ns,decode(value->>'transport','hex') transport FROM jsonb_array_elements(planned)
  UNION ALL SELECT decode(value->>'oldNs','hex'),decode(value->>'oldTransport','hex') FROM jsonb_array_elements(planned)) routes
  ORDER BY routes.ns,routes.transport LOOP PERFORM truss.lock_string_key_bucket(route.ns,route.transport);END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(planned) LOOP
  ns:=decode(entry->>'ns','hex');transport:=decode(entry->>'transport','hex');
  unchanged:=entry->>'ns'=entry->>'oldNs' AND entry->>'transport'=entry->>'oldTransport';
  SELECT * INTO STRICT observed FROM truss.lock_string_key_bucket(ns,transport);
  IF unchanged THEN
   IF cardinality(observed.member_ids)<>1 OR observed.member_ids[1]<>(entry->>'oldId')::bigint THEN RAISE EXCEPTION 'owned unchanged key required' USING ERRCODE='55000';END IF;
   CONTINUE;
  END IF;
  IF cardinality(observed.member_ids)>0 OR cardinality(observed.reservation_ids)>0 THEN RAISE EXCEPTION 'key allocated or reserved' USING ERRCODE='23505';END IF;
  DELETE FROM truss.object_key_bucket WHERE storage_row_id=(entry->>'oldId')::bigint;
  UPDATE truss.key_bucket_guard SET generation=generation+1 WHERE namespace_sha256=sha256(decode(entry->>'oldNs','hex')) AND key_sha256=sha256(decode(entry->>'oldTransport','hex'));
  INSERT INTO truss.object_key_bucket(type_id,key_num,object_id,namespace_bytes,key_bytes,original_context_bytes)
  VALUES(selected_type,(entry->>'keyNumber')::smallint,object_id,ns,transport,
   convert_to(jsonb_build_object('profile','truss-updated-key-context/0.2','attemptId',attempt_id::text,'operationIndex',operation_index::text,
    'objectId',object_id::text,'xid',pg_current_xact_id()::text,'derivation','postgresql-umf-key-tuple-v1')::text,'UTF8'));
  INSERT INTO truss.object_key_reservation_bucket(namespace_bytes,key_bytes,original_reservation_bytes) VALUES(ns,transport,
   convert_to(jsonb_build_object('profile','truss-updated-key-reservation/0.1','attemptId',attempt_id::text,'operationIndex',operation_index::text,
    'objectId',object_id::text,'typeId',selected_type::text,'keyNumber',entry->>'keyNumber','xid',pg_current_xact_id()::text)::text,'UTF8'));
  UPDATE truss.key_bucket_guard SET generation=generation+1 WHERE namespace_sha256=sha256(ns) AND key_sha256=sha256(transport);
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_object_values_readable_qualified(selected_type integer, qualified_actor oid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE selected truss.type_def;dependency record;compiled_readers jsonb;
BEGIN
 SELECT s.value_readers INTO compiled_readers FROM truss.runtime_type_schema s
  JOIN truss.type_def t ON t.type_id=s.type_id WHERE s.rev=(SELECT rev FROM truss.schema_head WHERE id=1)
   AND s.type_id=selected_type AND s.valid_properties AND t.kind='record' AND t.retired_rev IS NULL;
 IF FOUND THEN
  FOR dependency IN SELECT value->>'documentId' document_id,value->>'moduleId' module FROM jsonb_array_elements(compiled_readers) LOOP
   IF truss.runtime_can_read_qualified(dependency.document_id,dependency.module,qualified_actor) IS NOT TRUE THEN RETURN false;END IF;
  END LOOP;
  RETURN true;
 END IF;
 SELECT * INTO selected FROM truss.type_def WHERE type_id=selected_type AND kind='record' AND retired_rev IS NULL;
 IF NOT FOUND THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL AND p.cardinality IN ('array','map') AND truss.valid_item_chain(p.item) IS NOT TRUE) THEN RETURN false;END IF;
 FOR dependency IN
  SELECT selected.document_id AS document_id,selected.module AS module
  UNION
  SELECT p.definition_document_id AS document_id,p.declaration_module AS module FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL
  UNION
  SELECT node.value->>'documentId',node.value->'reference'->>'module' FROM truss.prop_def p CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(p.item)||coalesce(p.item->'descendants','[]'::jsonb)) node WHERE p.type_id=selected_type AND p.retired_rev IS NULL AND p.cardinality IN ('array','map')
 LOOP
  IF truss.runtime_can_read_qualified(dependency.document_id,dependency.module,qualified_actor) IS NOT TRUE THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_operation_owner(operation jsonb, operations jsonb, operation_index integer)
 RETURNS TABLE(document_id text, module text, definition_rev integer, definition_doc_ord integer, definition_document_id text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE object_type truss.type_def%ROWTYPE;relationship truss.rel_def%ROWTYPE;
BEGIN
 IF operation->>'operation' IN ('create_object','update_object','delete_object') THEN
  object_type:=truss.runtime_operation_type(operation,operations,operation_index);
  RETURN QUERY SELECT object_type.document_id,object_type.module,object_type.definition_rev,object_type.definition_doc_ord,object_type.definition_document_id;
 ELSE
  relationship:=truss.runtime_operation_relationship(operation,operations,operation_index);
  RETURN QUERY SELECT relationship.document_id,relationship.module,relationship.definition_rev,relationship.definition_doc_ord,relationship.definition_document_id;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_operation_relationship(operation jsonb, operations jsonb, operation_index integer)
 RETURNS truss.rel_def
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE pin text;identity jsonb;creation jsonb;selected truss.rel_def%ROWTYPE;
BEGIN
 IF operation->>'operation'='create_edge' THEN pin:=operation->>'relationshipDefinitionPin';
 ELSIF operation->>'operation' IN ('update_edge','delete_edge') THEN
  IF operation->'target'->>'state'='stored' THEN
   identity:=operation->'target'->'identity';pin:=identity->>'definitionPin';
  ELSIF operation->'target'->>'state'='alias' THEN
   IF jsonb_typeof(operations)='object' THEN
    creation:=operations->(operation->'target'->>'alias');
    IF creation->>'operation' IS DISTINCT FROM 'create_edge' OR (creation->>'operationIndex')::int>=operation_index THEN
     RAISE EXCEPTION 'one prior edge alias required' USING ERRCODE='22023';END IF;
   ELSE
    IF (SELECT count(*) FROM jsonb_array_elements(operations) WITH ORDINALITY x(value,ord)
     WHERE ord<=operation_index AND value->>'operation'='create_edge' AND value->>'alias'=operation->'target'->>'alias')<>1 THEN
     RAISE EXCEPTION 'one prior edge alias required' USING ERRCODE='22023';END IF;
    SELECT value INTO STRICT creation FROM jsonb_array_elements(operations) WITH ORDINALITY x(value,ord)
     WHERE ord<=operation_index AND value->>'operation'='create_edge' AND value->>'alias'=operation->'target'->>'alias';
   END IF;
   pin:=creation->>'relationshipDefinitionPin';
  ELSE RAISE EXCEPTION 'stored or prior edge alias target required' USING ERRCODE='22023';END IF;
 ELSE RAISE EXCEPTION 'selected edge operation required' USING ERRCODE='22023';END IF;
 -- Resolve the exact pin before joining source coordinates. Without this
 -- boundary a cold catalog plan can scan every relationship and repeatedly
 -- probe all source rows from the same document for each candidate.
 WITH pinned AS MATERIALIZED (
  SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
  WHERE definition_pin=pin AND kind='relationship' AND key_id='')
 SELECT r.* INTO STRICT selected FROM pinned p JOIN truss.rel_def r
  ON r.definition_rev=p.rev AND r.definition_doc_ord=p.ord AND r.definition_document_id=p.doc_id
   AND r.module=p.module_id AND r.rel_id=p.element_id
  WHERE r.retired_rev IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'accepted relationship pin required' USING ERRCODE='22023';END IF;
 IF identity IS NOT NULL AND (jsonb_typeof(identity->'typeId') IS DISTINCT FROM 'string'
  OR jsonb_typeof(identity->'definitionPin') IS DISTINCT FROM 'string'
  OR identity->>'typeId' IS DISTINCT FROM selected.rel_type_id::text
  OR identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module)
  OR identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb
  OR jsonb_typeof(identity->'id') IS DISTINCT FROM 'string' OR identity->>'id' !~ '^[1-9][0-9]{0,18}$'
  OR length(identity->>'id')=19 AND (identity->>'id') COLLATE "C">'9223372036854775807') THEN
  RAISE EXCEPTION 'qualified exact edge identity required' USING ERRCODE='22023';END IF;
 RETURN selected;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_application_values(selected_type integer, operation_index integer, prepared jsonb, prior_props jsonb, prior_retained jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE patch jsonb;props jsonb;retained jsonb;result jsonb;removed_props text[];removed_retained text[];
BEGIN
 patch:=prepared;
 IF patch->'operationIndex' IS DISTINCT FROM to_jsonb(operation_index)
  OR patch->>'typeId' IS DISTINCT FROM selected_type::text
  OR jsonb_typeof(patch->'propsSet') IS DISTINCT FROM 'object'
  OR jsonb_typeof(patch->'retainedSet') IS DISTINCT FROM 'object'
  OR jsonb_typeof(patch->'propsUnset') IS DISTINCT FROM 'array'
  OR jsonb_typeof(patch->'retainedUnset') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'exact application prepared value inventory required' USING ERRCODE='55000';END IF;
 SELECT coalesce(array_agg(value),ARRAY[]::text[]) INTO removed_props FROM jsonb_array_elements_text(patch->'propsUnset');
 SELECT coalesce(array_agg(value),ARRAY[]::text[]) INTO removed_retained FROM jsonb_array_elements_text(patch->'retainedUnset');
 props:=(coalesce(prior_props,'{}'::jsonb)-removed_props)||(patch->'propsSet');
 retained:=(coalesce(prior_retained,'{}'::jsonb)-removed_retained)||(patch->'retainedSet');
 result:=jsonb_build_object('props',props,'retained',retained);
 IF octet_length(convert_to(result::text,'UTF8'))>1048576 THEN
  RAISE EXCEPTION 'bounded complete object values required' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_capture_application(selected_attempt uuid, application_prepared jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE observed_operation_count int;input_operations jsonb;
 attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;locked jsonb;
 inventory jsonb;entry jsonb;prepared_plans jsonb[];owner record;selected_type int;relation truss.rel_def%ROWTYPE;endpoint_owner record;retained_bytes bigint:=0;current_actor oid;
 original_projection_problem boolean;compact_updates boolean;application_operations jsonb;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt FOR UPDATE NOWAIT;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
 input_operations:=input->'operations';
 current_actor:=truss.runtime_person(false);
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id()
  OR attempt.actor_oid IS DISTINCT FROM current_actor OR attempt.complete
  OR attempt.next_index<>0 OR attempt.results<>'[]'::jsonb OR attempt.aliases<>'[]'::jsonb
  OR attempt.context->'mutationProfile' IS DISTINCT FROM input->'mutationProfile'
  OR input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile()
  OR EXISTS(SELECT 1 FROM truss.runtime_owned_operation WHERE attempt_id=selected_attempt) THEN
  RAISE EXCEPTION 'original unused owned attempt required' USING ERRCODE='55000';END IF;
 -- The admitted entry already holds the graph gate and table locks.
 locked:=truss.runtime_owned_input_scope(input);
 -- All component objects and relationships can participate in reparent/cascade;
 -- outside independent endpoints are read witnesses only.
 FOR owner IN SELECT document_id,module_id FROM (SELECT DISTINCT document_id,module_id FROM (
  SELECT value->>'document_id' document_id,value->>'module' module_id FROM jsonb_each(locked->'types')
  UNION ALL SELECT value->>'document_id',value->>'module' FROM jsonb_each(locked->'relationships')
 ) owners) distinct_owners ORDER BY document_id COLLATE "C",module_id COLLATE "C" LOOP
  PERFORM truss.runtime_module_writer_qualified(owner.document_id,owner.module_id,current_actor);
 END LOOP;
 FOR owner IN SELECT document_id,module_id FROM (SELECT DISTINCT value->'definition'->>'document_id' document_id,
  value->'definition'->>'module' module_id FROM jsonb_each(locked->'boundary')) distinct_owners
  ORDER BY document_id COLLATE "C",module_id COLLATE "C" LOOP
  IF NOT truss.runtime_can_read_qualified(owner.document_id,owner.module_id,current_actor) THEN
   RAISE EXCEPTION 'current outside endpoint reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 -- Implicit descendant values and zero-edge multiplicity checks require the
 -- same original readers as explicit operations, before graph exclusion.
 FOR selected_type IN SELECT type_id FROM (
  SELECT DISTINCT (value->>'type_id')::int type_id FROM jsonb_each(locked->'types')
  -- Stored update/delete targets are already in locked.types; alias targets
  -- come from the CREATE pins below. Original reference admission remains in
  -- input_scope and the ordered planner, so this type-set pass adds no new type.
  -- This is a type set, not operation admission. Resolve each exact CREATE pin
  -- once using its first original operation; all per-operation admission,
  -- execution and settlement checks remain on their original paths.
  UNION SELECT (truss.runtime_owned_operation_type_qualified(value,input_operations,(ordinal-1)::int,current_actor)).type_id
   FROM (SELECT DISTINCT ON ((value->>'typeDefinitionPin') COLLATE "C") value,ordinal
    FROM jsonb_array_elements(input_operations) WITH ORDINALITY o(value,ordinal)
    WHERE value->>'operation'='create_object'
    ORDER BY (value->>'typeDefinitionPin') COLLATE "C",ordinal) creations
 ) affected_types ORDER BY type_id LOOP
  IF truss.runtime_object_values_readable_qualified(selected_type,current_actor) IS NOT TRUE THEN
   RAISE EXCEPTION 'complete affected property and item readers required' USING ERRCODE='42501';END IF;
  FOR relation IN WITH selected_relations AS MATERIALIZED (
   SELECT DISTINCT rel_type_id FROM truss.rel_endpoint WHERE source_type=selected_type OR target_type=selected_type)
   SELECT r.* FROM selected_relations s JOIN truss.rel_def r USING(rel_type_id)
   WHERE r.retired_rev IS NULL ORDER BY r.rel_type_id LOOP
   IF relation.source_min=0 AND relation.source_max IS NULL AND relation.target_min=0 AND relation.target_max IS NULL THEN CONTINUE;END IF;
   IF NOT truss.runtime_can_read_qualified(relation.document_id,relation.module,current_actor) THEN
    RAISE EXCEPTION 'counted relationship reader required' USING ERRCODE='42501';END IF;
   FOR endpoint_owner IN SELECT DISTINCT t.document_id,t.module FROM truss.rel_endpoint e
    JOIN truss.type_def t ON t.type_id IN(e.source_type,e.target_type) WHERE e.rel_type_id=relation.rel_type_id LOOP
    IF NOT truss.runtime_can_read_qualified(endpoint_owner.document_id,endpoint_owner.module,current_actor) THEN
     RAISE EXCEPTION 'counted relationship endpoint reader required' USING ERRCODE='42501';END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 inventory:=truss.runtime_owned_prepare_application(input,locked,application_prepared);
 PERFORM truss.runtime_owned_key_preflight(inventory);
 -- The shared original scope owns one before snapshot. Trusted independent
 -- updates need only scalar plan custody and their exact mapped patch after
 -- preflight; the producer binds actual rows and emits the full transition.
 compact_updates:=application_prepared IS NOT NULL
  AND locked->'independentEndpointScope'='true'::jsonb
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(input_operations) o
   WHERE o.value->>'operation' IS DISTINCT FROM 'update_object'
    OR o.value->'target'->>'state' IS DISTINCT FROM 'stored' OR o.value ? 'ownershipChange')
  AND (SELECT count(DISTINCT value->>'primary') FROM jsonb_array_elements(inventory->'operations'))=jsonb_array_length(input_operations)
  AND NOT EXISTS(SELECT 1 FROM jsonb_each(locked->'nodes') n
   WHERE n.value->'root_id' IS DISTINCT FROM 'null'::jsonb OR n.value->'root_type' IS DISTINCT FROM 'null'::jsonb
    OR n.value->'rev' IS DISTINCT FROM inventory->'catalogRevision');
 application_operations:=application_prepared->'operations';
 -- Retain all immutable plans with one INSERT, preserving exact row images.
 WITH selected_plans AS MATERIALIZED (
  SELECT CASE WHEN compact_updates THEN v.value||jsonb_build_object(
   'compactProfile','truss-application-value-plan/0.1',
   'applicationPatch',application_operations->(v.value->>'operationIndex')::int,
   'desiredImageSha256',encode(sha256(convert_to(((v.value->'afterNodes'->(v.value->>'primary')->'image')-ARRAY['created_at','updated_at']||
    jsonb_build_object('id',(v.value->'afterNodes'->(v.value->>'primary')->'identity'->>'id')::bigint,
     'root_id',NULL,'root_type',NULL))::text,'UTF8')),'hex'),
   'beforeNodes',(SELECT jsonb_object_agg(n.key,jsonb_set(n.value,'{image}',(n.value->'image')-ARRAY['props','retained'])) FROM jsonb_each(v.value->'beforeNodes') n),
   'afterNodes',(SELECT jsonb_object_agg(n.key,jsonb_set(n.value,'{image}',(n.value->'image')-ARRAY['props','retained'])) FROM jsonb_each(v.value->'afterNodes') n))
   ELSE v.value END value
  FROM jsonb_array_elements(inventory->'operations') v),
 plans AS MATERIALIZED (
  SELECT value||jsonb_build_object('actorName',session_user::text,'mutationProfile',input->'mutationProfile',
   'catalogRevision',inventory->'catalogRevision')||CASE WHEN value->>'operationIndex'='0'
    THEN jsonb_build_object('initialScope',inventory->'initialScope') ELSE '{}'::jsonb END plan
  FROM selected_plans)
 SELECT sum(octet_length(convert_to(plan::text,'UTF8'))),
  array_agg(plan ORDER BY (plan->>'operationIndex')::int)
 INTO retained_bytes,prepared_plans FROM plans;
 IF retained_bytes>33554432 THEN RAISE EXCEPTION 'bounded retained whole group inventory required' USING ERRCODE='54000';END IF;
 INSERT INTO truss.runtime_owned_operation(attempt_id,operation_index,writer_xid,plan)
 SELECT attempt.id,(p.plan->>'operationIndex')::int,attempt.writer_xid,p.plan
 FROM unnest(prepared_plans) WITH ORDINALITY p(plan,ordinal) ORDER BY p.ordinal;
 GET DIAGNOSTICS observed_operation_count=ROW_COUNT;
 IF observed_operation_count<>cardinality(prepared_plans) THEN
  RAISE EXCEPTION 'complete prepared operation insert required' USING ERRCODE='55000';END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_create_batch(selected_attempt uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;
 input jsonb;objects jsonb;keys jsonb;journals jsonb;transitions jsonb;
 dictionary jsonb:='{}';namespaces jsonb:='{}';metadata jsonb;
 dictionary_keys text[]:=ARRAY[]::text[];dictionary_values jsonb[]:=ARRAY[]::jsonb[];
 codec_keys text[]:=ARRAY[]::text[];codec_values jsonb[]:=ARRAY[]::jsonb[];
 namespace_keys text[]:=ARRAY[]::text[];namespace_values jsonb[]:=ARRAY[]::jsonb[];map_count int;
 selected_type int;definition record;pin record;type_pin text;property_pins jsonb;property_order jsonb;head_revision int;
 group_id uuid:=gen_random_uuid();actor oid;counted int;total int;compiled_namespace bytea;route record;
 slot_results jsonb;
 codecs jsonb:='{}';codec jsonb;codec_bytes bigint:=2;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt FOR UPDATE NOWAIT;
 actor:=truss.runtime_person(false);input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
 total:=jsonb_array_length(input->'operations');
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM actor
  OR attempt.complete OR attempt.next_index<>0 OR attempt.results<>'[]'::jsonb OR attempt.aliases<>'[]'::jsonb
  OR input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile()
  OR total NOT BETWEEN 1 AND 1024 OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'operations') o
   WHERE o.value->>'operation' IS DISTINCT FROM 'create_object'
    OR o.value->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb)
  OR (SELECT count(*) FROM truss.runtime_owned_operation WHERE attempt_id=selected_attempt)<>total
  OR EXISTS(SELECT 1 FROM truss.runtime_owned_operation p WHERE p.attempt_id=selected_attempt AND
   (p.writer_xid IS DISTINCT FROM attempt.writer_xid OR p.result IS NOT NULL
    OR p.plan->>'primary' IS DISTINCT FROM 'create:'||p.operation_index::text
    OR (p.plan->'beforeNodes') ? (p.plan->>'primary') OR p.plan->'beforeEdges'<>'{}'::jsonb
    OR p.plan->'afterEdges'<>'{}'::jsonb
    OR p.plan->'afterNodes'->(p.plan->>'primary')->'root' IS DISTINCT FROM 'null'::jsonb)) THEN
  RAISE EXCEPTION 'independent original rootless create batch required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF (SELECT value FROM truss.setting WHERE key='key_reuse') IS DISTINCT FROM '"forbid"'::jsonb
  OR (SELECT value FROM truss.setting WHERE key='journal_mode') IS DISTINCT FROM '"engine"'::jsonb THEN
  RAISE EXCEPTION 'selected engine key/history settings required' USING ERRCODE='0A000';END IF;
 SELECT rev INTO STRICT head_revision FROM truss.schema_head WHERE id=1;
 -- Catalog interpretation is compiled once per type, not once per object.
 FOR selected_type IN SELECT DISTINCT (p.plan->'afterNodes'->(p.plan->>'primary')->'image'->>'type_id')::int
  FROM truss.runtime_owned_operation p WHERE p.attempt_id=selected_attempt LOOP
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',selected_type);
  type_pin:=pin.definition_pin;
  PERFORM truss.runtime_module_writer_qualified(pin.document_id,pin.module_id,actor);
  IF NOT truss.runtime_object_values_readable_qualified(selected_type,actor) THEN
   RAISE EXCEPTION 'current property and item readers required' USING ERRCODE='42501';END IF;
  SELECT s.metadata INTO STRICT metadata FROM truss.runtime_type_schema s
   WHERE s.rev=head_revision AND s.type_id=selected_type;
  IF metadata->>'typeId' IS DISTINCT FROM selected_type::text
   OR metadata->>'revision' IS DISTINCT FROM head_revision::text
   OR metadata->>'typePin' IS DISTINCT FROM type_pin THEN
   RAISE EXCEPTION 'current compiled create schema required' USING ERRCODE='55000';END IF;
  property_pins:=metadata->'propertyPins';property_order:=metadata->'propertyOrder';
  map_count:=cardinality(dictionary_keys)+1;
  dictionary_keys[map_count]:=selected_type::text;
  dictionary_values[map_count]:=jsonb_build_object('typeId',selected_type::text,
   'revision',head_revision::text,'typePin',type_pin,'propertyOrder',property_order,'propertyPins',property_pins);
  FOR definition IN SELECT * FROM truss.key_def WHERE type_id=selected_type AND retired_rev IS NULL ORDER BY key_num LOOP
   SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',selected_type,definition.key_num);
   -- The current, exactly bound type schema above already owns this codec.
   -- Avoid resolving the same owner/key/schema again for every key.
   codec:=metadata->'keyCodecs'->definition.key_num::text;
   IF codec IS NULL THEN
    codec:=truss.runtime_owned_key_codec_metadata(selected_type,definition.key_num);
   END IF;
   IF codec_bytes+octet_length(convert_to(codec::text,'UTF8'))+32<=4194304 THEN
    map_count:=cardinality(codec_keys)+1;
    codec_keys[map_count]:=selected_type::text||':'||definition.key_num::text;
    codec_values[map_count]:=codec;
    codec_bytes:=codec_bytes+octet_length(convert_to(codec::text,'UTF8'))+32;
   END IF;
   compiled_namespace:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,
    'sourceEpoch',installation.source_epoch::text,'typeId',selected_type::text,'keyNumber',definition.key_num::text,
    'definitionPin',pin.definition_pin,'encoding','umf-key-tuple-v1')::text,'UTF8');
   map_count:=cardinality(namespace_keys)+1;
   namespace_keys[map_count]:=selected_type::text||':'||definition.key_num::text;
   namespace_values[map_count]:=to_jsonb(encode(compiled_namespace,'hex'));
  END LOOP;
 END LOOP;
 -- Assemble each wide lookup map once after its inputs have been collected.
 -- Repeated jsonb concatenation recopies the growing map for every distinct type.
 SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) INTO dictionary
  FROM unnest(dictionary_keys,dictionary_values) AS entries(k,v);
 SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) INTO codecs
  FROM unnest(codec_keys,codec_values) AS entries(k,v);
 SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) INTO namespaces
  FROM unnest(namespace_keys,namespace_values) AS entries(k,v);
 WITH allocated AS MATERIALIZED (
  SELECT p.operation_index,p.plan->'operation' operation,
   p.plan->'afterNodes'->(p.plan->>'primary') state,nextval('truss.id_seq') id,clock_timestamp() created_at
  FROM truss.runtime_owned_operation p WHERE p.attempt_id=selected_attempt ORDER BY p.operation_index),
 rows AS (
  SELECT operation_index,operation,jsonb_build_object('id',id,'type_id',(state->'image'->>'type_id')::int,
   'root_id',NULL,'root_type',NULL,'rev',(state->'image'->>'rev')::int,'ver',1,
   'props',state->'image'->'props','retained',nullif(state->'image'->'retained','{}'::jsonb),
   'created_at',created_at,'updated_at',created_at) image,
   (state->'identity')||jsonb_build_object('id',id::text) identity FROM allocated)
 SELECT jsonb_agg(jsonb_build_object('index',operation_index,'operation',operation,'object',image,'identity',identity) ORDER BY operation_index)
 INTO objects FROM rows;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(objects) o WHERE (o.value->'object'->>'id')::bigint<=0) THEN
  RAISE EXCEPTION 'positive native object ids required' USING ERRCODE='54000';END IF;
 -- The trusted producer submits each canonical image once. Constraints and
 -- the versioned object identity govern storage; count the actual INSERT rows
 -- to detect a suppressed/missing insert without serializing the full rows
 -- back into JSON and reading them a second time.
 INSERT INTO truss.object SELECT r.* FROM jsonb_array_elements(objects) o
  CROSS JOIN LATERAL jsonb_populate_record(NULL::truss.object,o.value->'object') r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>total THEN RAISE EXCEPTION 'complete batch object insert required' USING ERRCODE='55000';END IF;
 -- Key expansion needs three object scalars, not a copy of its full image
 -- and authored operation for every key and every materialized stage.
 WITH cells AS MATERIALIZED (
  SELECT (o.value->>'index')::int operation_index,(o.value->'object'->>'id')::bigint object_id,
   (o.value->'object'->>'type_id')::int type_id,
   k.key_num,decode(namespaces->>((o.value->'object'->>'type_id')||':'||k.key_num::text),'hex') namespace,
   truss.runtime_owned_key_tuple_in_metadata(k.type_id,k.key_num,
    (SELECT jsonb_agg(o.value->'object'->'props'->i.prop_id::text ORDER BY i.ordinal)
     FROM unnest(k.prop_ids) WITH ORDINALITY i(prop_id,ordinal)),
    coalesce(codecs->(k.type_id::text||':'||k.key_num::text),truss.runtime_owned_key_codec_metadata(k.type_id,k.key_num))) tuple
  FROM jsonb_array_elements(objects) o JOIN truss.key_def k ON k.type_id=(o.value->'object'->>'type_id')::int AND k.retired_rev IS NULL),
 encoded AS MATERIALIZED (
  SELECT *,convert_to('umf-key-tuple-v1:hex:'||encode(tuple,'hex'),'UTF8') transport,
   convert_to(jsonb_build_object('profile','truss-created-key-context/0.2','groupId',group_id::text,
    'sourceEpoch',installation.source_epoch::text,'xid',attempt.writer_xid::text,'actorOid',actor::text,
    'actor',session_user::text,'operationIndex',operation_index::text,'derivation','postgresql-umf-key-tuple-v1')::text,'UTF8') context
  FROM cells),
 rows AS (
  SELECT to_jsonb(operation_index) index,jsonb_build_object('storage_row_id',nextval('truss.key_storage_row_seq'),
   'type_id',type_id,'key_num',key_num,'object_id',object_id,
   'namespace_bytes',namespace,'key_bytes',transport,'original_context_bytes',context,
   'namespace_sha256',sha256(namespace),'key_sha256',sha256(transport)) membership,
   jsonb_build_object('storage_row_id',nextval('truss.key_storage_row_seq'),'namespace_bytes',namespace,'key_bytes',transport,
    'namespace_sha256',sha256(namespace),'key_sha256',sha256(transport),
    'original_reservation_bytes',convert_to(jsonb_build_object('profile','truss-created-key-reservation/0.1',
     'groupId',group_id::text,'sourceEpoch',installation.source_epoch::text,'xid',attempt.writer_xid::text,
     'objectId',object_id::text,'typeId',type_id::text,'keyNumber',key_num::text,
     'contextBase64',replace(encode(context,'base64'),chr(10),''))::text,'UTF8')) reservation
  FROM encoded)
 SELECT coalesce(jsonb_agg(to_jsonb(rows) ORDER BY (index#>>'{}')::int,(membership->>'key_num')::int),'[]'::jsonb) INTO keys FROM rows;
 -- Key preflight already observed these exact bytes under the held writer
 -- gate. No ordinary caller can interleave membership/reservation writes.
 INSERT INTO truss.object_key_bucket(storage_row_id,type_id,key_num,object_id,namespace_bytes,key_bytes,original_context_bytes)
 SELECT r.storage_row_id,r.type_id,r.key_num,r.object_id,r.namespace_bytes,r.key_bytes,r.original_context_bytes
 FROM jsonb_array_elements(keys) o CROSS JOIN LATERAL jsonb_populate_record(NULL::truss.object_key_bucket,o.value->'membership') r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>jsonb_array_length(keys) THEN RAISE EXCEPTION 'complete batch key membership required' USING ERRCODE='55000';END IF;
 INSERT INTO truss.object_key_reservation_bucket(storage_row_id,namespace_bytes,key_bytes,original_reservation_bytes)
 SELECT r.storage_row_id,r.namespace_bytes,r.key_bytes,r.original_reservation_bytes
 FROM jsonb_array_elements(keys) o CROSS JOIN LATERAL jsonb_populate_record(NULL::truss.object_key_reservation_bucket,o.value->'reservation') r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>jsonb_array_length(keys) THEN RAISE EXCEPTION 'complete batch key reservation required' USING ERRCODE='55000';END IF;
 UPDATE truss.key_bucket_guard g SET generation=g.generation+r.advances
 FROM (SELECT k.namespace_sha256,k.key_sha256,count(*) advances FROM jsonb_array_elements(keys) o
  CROSS JOIN LATERAL jsonb_populate_record(NULL::truss.object_key_bucket,o.value->'membership') k
  GROUP BY k.namespace_sha256,k.key_sha256) r WHERE g.namespace_sha256=r.namespace_sha256 AND g.key_sha256=r.key_sha256;
 WITH events AS MATERIALIZED (
  SELECT o.value object,nextval('truss.journal_seq') seq,clock_timestamp() at,
   truss.runtime_owned_history_record_in_metadata(o.value->'object',o.value->'identity',dictionary->(o.value->'object'->>'type_id')) image
  FROM jsonb_array_elements(objects) o),
 payloads AS MATERIALIZED (
  SELECT *,jsonb_build_object('interfaceVersion','truss-history-event/0.2.0-proposal','sourceEpoch',installation.source_epoch::text,
   'historyProfile','truss-native-owned-create/0.1','xid',attempt.writer_xid::text,'seq',seq::text,'identity',object->'identity',
   'eventVersion','1','eventCatalogRevision',object->'object'->>'rev','operation','create','after',image,
   'origin',jsonb_build_object('asserted',input->'assertedOrigin','databaseRole',session_user::text)) event FROM events),
 grouped AS (
  SELECT *,event||jsonb_build_object('mutationGroup',jsonb_build_object('profile','truss-history-group/0.1.0',
   'eventCount','1','orderedEventDigest',encode(sha256(convert_to(jsonb_build_array(event)::text,'UTF8')),'hex'))) payload FROM payloads)
 SELECT jsonb_agg(jsonb_build_object('index',object->'index','journal',jsonb_build_object('seq',seq,'at',at,'xid',attempt.writer_xid::text,
  'entity_kind','o','entity_id',(object->'object'->>'id')::bigint,'entity_type',(object->'object'->>'type_id')::int,
  'ver',1,'op','create','prop_id',NULL,'old_value',NULL,'rev',(object->'object'->>'rev')::int,
  'new_value',truss.runtime_exact_wrapper('event',convert_to(payload::text,'UTF8')),
  'origin',truss.runtime_exact_wrapper('origin',convert_to((payload->'origin')::text,'UTF8')))) ORDER BY seq) INTO journals FROM grouped;
 INSERT INTO truss.journal SELECT r.* FROM jsonb_array_elements(journals) o
  CROSS JOIN LATERAL jsonb_populate_record(NULL::truss.journal,o.value->'journal') r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>jsonb_array_length(journals) THEN RAISE EXCEPTION 'complete batch journal append required' USING ERRCODE='55000';END IF;
 SELECT jsonb_agg(jsonb_build_object('attempt_id',attempt.id,'operation_index',(o.value->>'index')::int,
  'writer_xid',attempt.writer_xid::text,'object_id',(o.value->'object'->>'id')::bigint,'type_id',(o.value->'object'->>'type_id')::int,
  'before_object',NULL,'after_object',o.value->'object','after_keys','[]'::jsonb,
  'journal',jsonb_build_array(j.value->'journal')) ORDER BY (o.value->>'index')::int) INTO transitions
 FROM jsonb_array_elements(objects) o JOIN jsonb_array_elements(journals) j ON (j.value->>'index')::int=(o.value->>'index')::int;
 INSERT INTO truss.runtime_object_transition(attempt_id,operation_index,writer_xid,object_id,type_id,before_object,after_object,after_keys,journal)
 SELECT r.attempt_id,r.operation_index,r.writer_xid,r.object_id,r.type_id,r.before_object,r.after_object,r.after_keys,r.journal
 FROM jsonb_populate_recordset(NULL::truss.runtime_object_transition,transitions) r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>total THEN RAISE EXCEPTION 'complete batch transitions required' USING ERRCODE='55000';END IF;
 WITH slots AS (
  SELECT (o.value->>'index')::int index,jsonb_build_object('operation','create_object','outcome','created','identity',o.value->'identity','version','1',
   'events',jsonb_build_array(jsonb_build_object('sourceEpoch',installation.source_epoch::text,'historyProfile','truss-native-owned-create/0.1',
    'xid',attempt.writer_xid::text,'seq',j.value->'journal'->>'seq')))
   ||CASE WHEN (o.value->'operation') ? 'alias' THEN jsonb_build_object('alias',o.value->'operation'->>'alias') ELSE '{}'::jsonb END result
  FROM jsonb_array_elements(objects) o JOIN jsonb_array_elements(journals) j ON j.value->'index'=o.value->'index')
 SELECT jsonb_object_agg(index::text,result) INTO slot_results FROM slots;
 UPDATE truss.runtime_owned_operation p SET result=slot_results->p.operation_index::text
 WHERE p.attempt_id=selected_attempt AND p.result IS NULL AND slot_results ? p.operation_index::text;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>total THEN RAISE EXCEPTION 'complete sealed batch result slots required' USING ERRCODE='55000';END IF;
 UPDATE truss.runtime_object_attempt SET next_index=total WHERE id=selected_attempt AND next_index=0 AND NOT complete;
 IF NOT FOUND THEN RAISE EXCEPTION 'one batch progress advance required' USING ERRCODE='55000';END IF;
 -- Settlement retains current authority, result/effect custody and final native
 -- state. Canonical returned rows above already bind the immutable payloads.
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_definition_metadata_in_basis(selected_kind text, selected_type integer, selected_number integer, historical_revision integer, basis jsonb)
 RETURNS TABLE(definition_pin text, original_fragment bytea, original_pointer text, document_id text, module_id text, element_id text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE source_kind text;source_revision int;source_ordinal int;source_document text;source_key text; archive record; native_type truss.type_def%ROWTYPE;
 source_module text;source_element text;module_json json;document_lookup jsonb;module_lookup jsonb;element_lookup jsonb;module_index int;element_json json;element_index int;
 key_json json;key_index int;fragment json;pointer text;pin_input text;
BEGIN
 IF historical_revision IS NULL THEN
  SELECT * INTO STRICT native_type FROM truss.type_def WHERE type_id=selected_type AND NOT provisional AND retired_rev IS NULL;
 ELSE
  IF basis IS NULL THEN RAISE EXCEPTION 'resolved historical catalog required' USING ERRCODE='22023'; END IF;
  SELECT * INTO STRICT native_type FROM jsonb_populate_recordset(NULL::truss.type_def,basis->'type_def') t WHERE t.type_id=selected_type;
 END IF;
 IF selected_kind='type' THEN
  source_kind:=native_type.definition_source_kind;source_revision:=native_type.definition_rev;
  source_ordinal:=native_type.definition_doc_ord;source_document:=native_type.definition_document_id;
  source_module:=native_type.module;source_element:=native_type.element;
 ELSIF selected_kind='property' THEN
  IF historical_revision IS NULL THEN
   SELECT p.definition_source_kind,p.definition_rev,p.definition_doc_ord,p.definition_document_id,p.declaration_module,p.element INTO STRICT source_kind,source_revision,source_ordinal,source_document,source_module,source_element FROM truss.prop_def p WHERE p.type_id=selected_type AND p.prop_id=selected_number AND p.retired_rev IS NULL;
  ELSE
   SELECT p.definition_source_kind,p.definition_rev,p.definition_doc_ord,p.definition_document_id,p.declaration_module,p.element INTO STRICT source_kind,source_revision,source_ordinal,source_document,source_module,source_element FROM jsonb_populate_recordset(NULL::truss.prop_def,basis->'prop_def') p WHERE p.type_id=selected_type AND p.prop_id=selected_number;
  END IF;
 ELSIF selected_kind='key' THEN
  IF historical_revision IS NULL THEN
   SELECT k.definition_source_kind,k.definition_rev,k.definition_doc_ord,k.definition_document_id,k.key_id INTO STRICT source_kind,source_revision,source_ordinal,source_document,source_key FROM truss.key_def k WHERE k.type_id=selected_type AND k.key_num=selected_number AND k.retired_rev IS NULL;
  ELSE
   SELECT k.definition_source_kind,k.definition_rev,k.definition_doc_ord,k.definition_document_id,k.key_id INTO STRICT source_kind,source_revision,source_ordinal,source_document,source_key FROM jsonb_populate_recordset(NULL::truss.key_def,basis->'key_def') k WHERE k.type_id=selected_type AND k.key_num=selected_number;
  END IF;
  source_module:=native_type.module;source_element:=native_type.element;
 ELSE RAISE EXCEPTION 'supported definition kind required' USING ERRCODE='22023'; END IF;
 IF source_kind<>'accepted_document' OR source_revision<1 THEN
  RAISE EXCEPTION 'original accepted definition source required' USING ERRCODE='0A000'; END IF;
 SELECT d.definition_pin,NULL::bytea,d.pointer INTO STRICT definition_pin,original_fragment,original_pointer
 FROM truss.runtime_definition_source d WHERE d.rev=source_revision AND d.ord=source_ordinal
  AND d.doc_id=source_document AND d.module_id=source_module AND d.element_id=source_element
  AND d.kind=CASE WHEN selected_kind='key' THEN 'key' ELSE 'element' END
  AND d.key_id=coalesce(source_key,'');
 document_id:=native_type.document_id;module_id:=native_type.module;element_id:=native_type.element;
 RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_edge_create_batch(selected_attempt uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;installation truss.catalog_runtime_installation%ROWTYPE;
 input jsonb;edges jsonb;journals jsonb;transitions jsonb;
 endpoints jsonb;contexts jsonb;actor oid;total int;counted int;revision int;owner record;
 slot_results jsonb;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt FOR UPDATE NOWAIT;
 actor:=truss.runtime_person(false);input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;total:=jsonb_array_length(input->'operations');
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM actor
  OR attempt.complete OR attempt.next_index<>0 OR attempt.results<>'[]'::jsonb OR attempt.aliases<>'[]'::jsonb
  OR input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile()
  OR total NOT BETWEEN 1 AND 1024 OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'operations') o
   WHERE o.value->>'operation' IS DISTINCT FROM 'create_edge'
    OR o.value->'source'->>'state' IS DISTINCT FROM 'stored' OR o.value->'target'->>'state' IS DISTINCT FROM 'stored')
  OR (SELECT count(*) FROM truss.runtime_owned_operation WHERE attempt_id=selected_attempt)<>total THEN
  RAISE EXCEPTION 'independent original edge create batch required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 FOR owner IN SELECT DISTINCT r.* FROM truss.runtime_owned_operation p JOIN truss.rel_def r
  ON r.rel_type_id=(p.plan->'afterEdges'->(p.plan->>'primary')->'identity'->>'typeId')::int
  WHERE p.attempt_id=selected_attempt LOOP
  IF owner.lifecycle<>'independent' OR NOT owner.directed OR owner.composition OR owner.assoc_type_id IS NOT NULL OR owner.retired_rev IS NOT NULL THEN
   RAISE EXCEPTION 'selected independent relationship required' USING ERRCODE='0A000';END IF;
  PERFORM truss.runtime_module_writer_qualified(owner.document_id,owner.module,actor);
 END LOOP;
 -- Resolve each distinct stored endpoint/root context once before edge writes.
 WITH endpoint_refs AS MATERIALIZED (
  SELECT p.operation_index,p.plan,v.reference FROM truss.runtime_owned_operation p
   CROSS JOIN LATERAL (VALUES(p.plan->'afterEdges'->(p.plan->>'primary')->>'source'),
    (p.plan->'afterEdges'->(p.plan->>'primary')->>'target')) v(reference)
  WHERE p.attempt_id=selected_attempt),
 selected AS (SELECT DISTINCT ON(reference) reference,operation_index,plan FROM endpoint_refs ORDER BY reference,operation_index)
 SELECT jsonb_object_agg(reference,truss.runtime_owned_identity(selected_attempt,operation_index,reference,'object',plan,attempt)) INTO endpoints FROM selected;
 SELECT jsonb_object_agg(key,truss.runtime_endpoint_ownership(value,revision)) INTO contexts FROM jsonb_each(endpoints);
 WITH planned AS MATERIALIZED (
  SELECT p.operation_index,p.plan->'operation' operation,p.plan->'afterEdges'->(p.plan->>'primary') state,
   nextval('truss.id_seq') id,clock_timestamp() created_at FROM truss.runtime_owned_operation p
  WHERE p.attempt_id=selected_attempt ORDER BY p.operation_index),
 images AS (
  SELECT *,state->'image'||jsonb_build_object('id',id,
   'source_id',(endpoints->(state->>'source')->>'id')::bigint,'source_type',(endpoints->(state->>'source')->>'typeId')::int,
   'target_id',(endpoints->(state->>'target')->>'id')::bigint,'target_type',(endpoints->(state->>'target')->>'typeId')::int,
   'order_key',state->'orderKey'->>'text','created_at',created_at,'updated_at',created_at) image,
   state->'identity'||jsonb_build_object('id',id::text) identity FROM planned)
 SELECT jsonb_agg(jsonb_build_object('index',operation_index,'operation',operation,'edge',image,'identity',identity,
  'source',endpoints->(state->>'source'),'target',endpoints->(state->>'target'),
  'endpointOwnership',jsonb_build_object('profile','truss-edge-endpoint-ownership/0.1','captureCatalogRevision',revision::text,
   'before',NULL,'after',jsonb_build_object('source',contexts->(state->>'source'),'target',contexts->(state->>'target'))))
  ORDER BY operation_index) INTO edges FROM images;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(edges) e WHERE (e.value->'edge'->>'id')::bigint<=0) THEN
  RAISE EXCEPTION 'positive native edge ids required' USING ERRCODE='54000';END IF;
 PERFORM truss.runtime_lock_edge_business_key(routes.k) FROM (
  SELECT truss.runtime_edge_business_key((value->'edge'->>'rel_type_id')::int,value->'source',value->'target') k
  FROM jsonb_array_elements(edges)) routes ORDER BY routes.k COLLATE "C";
 INSERT INTO truss.edge SELECT r.* FROM jsonb_array_elements(edges) e
  CROSS JOIN LATERAL jsonb_populate_record(NULL::truss.edge,e.value->'edge') r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>total THEN RAISE EXCEPTION 'complete batch edge insert required' USING ERRCODE='55000';END IF;
 WITH allocated AS MATERIALIZED (
  SELECT value edge,nextval('truss.journal_seq') seq,clock_timestamp() at FROM jsonb_array_elements(edges)),
 events AS MATERIALIZED (
  SELECT *,jsonb_build_object('interfaceVersion','truss-history-event/0.2.0-proposal','sourceEpoch',installation.source_epoch::text,
   'historyProfile','truss-native-owned-edge-mutation/0.1','xid',attempt.writer_xid::text,'seq',seq::text,'identity',edge->'identity',
   'eventVersion','1','eventCatalogRevision',revision::text,'operation','create',
   'after',truss.runtime_edge_history(edge->'edge',edge->'identity',edge->'source',edge->'target'),
   'origin',jsonb_build_object('asserted',input->'assertedOrigin','databaseRole',session_user::text)) event FROM allocated),
 grouped AS (
  SELECT *,event||jsonb_build_object('mutationGroup',jsonb_build_object('profile','truss-history-group/0.1.0','eventCount','1',
   'orderedEventDigest',encode(sha256(convert_to(jsonb_build_array(event)::text,'UTF8')),'hex'))) payload FROM events)
 SELECT jsonb_agg(jsonb_build_object('index',edge->'index','journal',jsonb_build_object('seq',seq,'at',at,'xid',attempt.writer_xid::text,
  'entity_kind','e','entity_id',(edge->'edge'->>'id')::bigint,'entity_type',(edge->'edge'->>'rel_type_id')::int,
  'ver',1,'op','create','prop_id',NULL,'old_value',NULL,'rev',revision,
  'new_value',truss.runtime_exact_wrapper('event',convert_to(payload::text,'UTF8')),
  'origin',truss.runtime_exact_wrapper('origin',convert_to((payload->'origin')::text,'UTF8')))) ORDER BY seq) INTO journals FROM grouped;
 INSERT INTO truss.journal SELECT r.* FROM jsonb_array_elements(journals) e
  CROSS JOIN LATERAL jsonb_populate_record(NULL::truss.journal,e.value->'journal') r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>jsonb_array_length(journals) THEN RAISE EXCEPTION 'complete batch edge journal append required' USING ERRCODE='55000';END IF;
 SELECT jsonb_agg(jsonb_build_object('attempt_id',attempt.id,'operation_index',(e.value->>'index')::int,'writer_xid',attempt.writer_xid::text,
  'edge_id',(e.value->'edge'->>'id')::bigint,'rel_type_id',(e.value->'edge'->>'rel_type_id')::int,'before_edge',NULL,'after_edge',e.value->'edge',
  'journal',jsonb_build_array(j.value->'journal'),'old_source',NULL,'old_target',NULL,
  'source_identity',e.value->'source','target_identity',e.value->'target','endpoint_ownership',e.value->'endpointOwnership')
  ORDER BY (e.value->>'index')::int) INTO transitions
 FROM jsonb_array_elements(edges) e JOIN jsonb_array_elements(journals) j ON (j.value->>'index')::int=(e.value->>'index')::int;
 INSERT INTO truss.runtime_edge_transition(attempt_id,operation_index,writer_xid,edge_id,rel_type_id,before_edge,after_edge,journal,old_source,old_target,source_identity,target_identity,endpoint_ownership)
 SELECT r.attempt_id,r.operation_index,r.writer_xid,r.edge_id,r.rel_type_id,r.before_edge,r.after_edge,r.journal,r.old_source,r.old_target,r.source_identity,r.target_identity,r.endpoint_ownership
 FROM jsonb_populate_recordset(NULL::truss.runtime_edge_transition,transitions) r;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>total THEN RAISE EXCEPTION 'complete batch edge transitions required' USING ERRCODE='55000';END IF;
 WITH slots AS (
  SELECT (e.value->>'index')::int index,jsonb_build_object('operation','create_edge','outcome','created','identity',e.value->'identity','version','1',
   'events',jsonb_build_array(jsonb_build_object('sourceEpoch',installation.source_epoch::text,'historyProfile','truss-native-owned-edge-mutation/0.1',
    'xid',attempt.writer_xid::text,'seq',j.value->'journal'->>'seq')))
   ||CASE WHEN (e.value->'operation') ? 'alias' THEN jsonb_build_object('alias',e.value->'operation'->>'alias') ELSE '{}'::jsonb END result
  FROM jsonb_array_elements(edges) e JOIN jsonb_array_elements(journals) j ON (j.value->>'index')::int=(e.value->>'index')::int)
 SELECT jsonb_object_agg(index::text,result) INTO slot_results FROM slots;
 UPDATE truss.runtime_owned_operation p SET result=slot_results->p.operation_index::text
 WHERE p.attempt_id=selected_attempt AND p.result IS NULL AND slot_results ? p.operation_index::text;
 GET DIAGNOSTICS counted=ROW_COUNT;
 IF counted<>total THEN RAISE EXCEPTION 'complete sealed edge batch results required' USING ERRCODE='55000';END IF;
 UPDATE truss.runtime_object_attempt SET next_index=total WHERE id=selected_attempt AND next_index=0 AND NOT complete;
 IF NOT FOUND THEN RAISE EXCEPTION 'one batch edge progress advance required' USING ERRCODE='55000';END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_edge_effect_selection(selected_attempt uuid, selected_index integer, metadata jsonb, effect_operation text, qualified_actor oid DEFAULT NULL::oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE plan jsonb;reference text:=metadata->>'ownedReference';prior jsonb;desired jsonb;derived_operation text;original_operation text;
BEGIN
 plan:=truss.runtime_owned_plan(selected_attempt,selected_index);prior:=plan->'beforeEdges'->reference;desired:=plan->'afterEdges'->reference;
 original_operation:=plan->'operation'->>'operation';
 derived_operation:=CASE WHEN prior IS NULL THEN 'create_edge' WHEN desired->'deleted'='true'::jsonb THEN 'delete_edge' ELSE 'update_edge' END;
 IF desired IS NULL OR prior->'deleted'='true'::jsonb OR effect_operation IS DISTINCT FROM derived_operation
  OR (original_operation='delete_object' AND (derived_operation<>'delete_edge' OR prior IS NULL))
  OR (original_operation<>'delete_object' AND (original_operation IS DISTINCT FROM derived_operation OR reference IS DISTINCT FROM plan->>'primary'))
  OR metadata IS DISTINCT FROM truss.runtime_owned_edge_metadata(selected_attempt,selected_index,reference,qualified_actor) THEN
  RAISE EXCEPTION 'original planned edge effect required' USING ERRCODE='55000';END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_edge_image(selected_attempt uuid, selected_index integer, reference text, phase text, prepared_plan jsonb DEFAULT NULL::jsonb, prepared_attempt truss.runtime_object_attempt DEFAULT NULL::truss.runtime_object_attempt)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE plan jsonb;state jsonb;identity jsonb;source_identity jsonb;target_identity jsonb;
BEGIN
 IF phase IS NULL OR phase NOT IN ('before','after') THEN RAISE EXCEPTION 'explicit edge image phase required' USING ERRCODE='55000';END IF;
 plan:=coalesce(prepared_plan,truss.runtime_owned_plan(selected_attempt,selected_index));state:=jsonb_extract_path(plan,phase||'Edges',reference);
 IF state IS NULL OR state->'deleted'='true'::jsonb THEN RETURN NULL;END IF;
 identity:=truss.runtime_owned_identity(selected_attempt,selected_index,reference,'edge',plan,prepared_attempt);
 source_identity:=truss.runtime_owned_identity(selected_attempt,selected_index,state->>'source','object',plan,prepared_attempt);
 target_identity:=truss.runtime_owned_identity(selected_attempt,selected_index,state->>'target','object',plan,prepared_attempt);
 RETURN ((state->'image')-ARRAY['created_at','updated_at'])||jsonb_build_object('id',(identity->>'id')::bigint,
  'source_id',(source_identity->>'id')::bigint,'source_type',(source_identity->>'typeId')::int,
  'target_id',(target_identity->>'id')::bigint,'target_type',(target_identity->>'typeId')::int,
  'order_key',state->'orderKey'->>'text');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_edge_metadata(selected_attempt uuid, selected_index integer, reference text, qualified_actor oid DEFAULT NULL::oid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;plan jsonb;prior jsonb;desired jsonb;identity jsonb;physical jsonb;
 source_identity jsonb;target_identity jsonb;old_source jsonb;old_target jsonb;endpoint_identity jsonb;
 endpoint_reference text;relation truss.rel_def%ROWTYPE;current_actor oid;new_key text;old_key text;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 current_actor:=coalesce(qualified_actor,truss.runtime_person(false));
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM current_actor
  OR attempt.complete OR attempt.next_index IS DISTINCT FROM selected_index THEN
  RAISE EXCEPTION 'current original owned effect required' USING ERRCODE='55000';END IF;
 plan:=truss.runtime_owned_plan(selected_attempt,selected_index);prior:=plan->'beforeEdges'->reference;desired:=plan->'afterEdges'->reference;
 IF desired IS NULL OR prior->'deleted'='true'::jsonb THEN RAISE EXCEPTION 'original live edge effect required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT relation FROM truss.rel_def WHERE rel_type_id=(desired->'identity'->>'typeId')::int AND retired_rev IS NULL;
 PERFORM truss.runtime_module_writer_qualified(relation.document_id,relation.module,current_actor);
 IF relation.lifecycle NOT IN ('independent','owned') OR NOT relation.directed OR relation.composition OR relation.assoc_type_id IS NOT NULL THEN
  RAISE EXCEPTION 'selected owned or independent relationship required' USING ERRCODE='0A000';END IF;
 IF prior IS NOT NULL THEN
  identity:=truss.runtime_owned_identity(selected_attempt,selected_index,reference,'edge',plan,attempt);
  SELECT to_jsonb(e) INTO STRICT physical FROM truss.edge e WHERE id=(identity->>'id')::bigint AND rel_type_id=relation.rel_type_id;
  IF physical->>'ver' IS DISTINCT FROM prior->'image'->>'ver' THEN
   RAISE EXCEPTION 'original planned edge version required' USING ERRCODE='55000';END IF;
  old_source:=truss.runtime_owned_identity(selected_attempt,selected_index,prior->>'source','object',plan,attempt);
  old_target:=truss.runtime_owned_identity(selected_attempt,selected_index,prior->>'target','object',plan,attempt);
 END IF;
 source_identity:=truss.runtime_owned_identity(selected_attempt,selected_index,desired->>'source','object',plan,attempt);
 target_identity:=truss.runtime_owned_identity(selected_attempt,selected_index,desired->>'target','object',plan,attempt);
 FOR endpoint_reference IN SELECT DISTINCT value#>>'{}' FROM jsonb_array_elements(jsonb_build_array(
  desired->'source',desired->'target',prior->'source',prior->'target')) WHERE value<>'null'::jsonb LOOP
  endpoint_identity:=truss.runtime_owned_identity(selected_attempt,selected_index,endpoint_reference,'object',plan,attempt);
  IF NOT truss.runtime_can_read_qualified(endpoint_identity->'owner'->>'documentId',endpoint_identity->'owner'->>'moduleId',current_actor) THEN
   RAISE EXCEPTION 'original endpoint reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 new_key:=truss.runtime_edge_business_key(relation.rel_type_id,source_identity,target_identity);
 PERFORM truss.runtime_lock_edge_business_key(new_key);
 IF old_source IS NOT NULL THEN
  old_key:=truss.runtime_edge_business_key(relation.rel_type_id,old_source,old_target);
  IF old_key IS DISTINCT FROM new_key THEN PERFORM truss.runtime_lock_edge_business_key(old_key);END IF;
 END IF;
 RETURN jsonb_build_object('ownedReference',reference,'documentId',relation.document_id,'moduleId',relation.module,'typeId',relation.rel_type_id::text,
  'identity',identity,'prior',physical,'source',source_identity,'target',target_identity,'oldSource',old_source,'oldTarget',old_target,
  'retained',coalesce(nullif(desired->'image'->'retained','null'::jsonb),'{}'::jsonb),'orderKey',desired->'orderKey','keys','[]'::jsonb,'values','[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_edge_transition_validate_qualified(selected_transition bigint, authorize_read boolean, qualified_actor oid, prepared_input jsonb DEFAULT NULL::jsonb, source_bytes bytea DEFAULT NULL::bytea, prepared_attempt truss.runtime_object_attempt DEFAULT NULL::truss.runtime_object_attempt)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE transition truss.runtime_edge_transition%ROWTYPE;attempt truss.runtime_object_attempt%ROWTYPE;
 plan jsonb;reference text;candidate text;candidate_state jsonb;catalog_revision jsonb;identity jsonb;prior jsonb;desired jsonb;expected_context jsonb;
 before_context jsonb;after_context jsonb;context jsonb;previous_image jsonb;has_previous boolean;
 expected_mode text;original_mode text;expected_version bigint;journal jsonb;event jsonb;matches int:=0;current_actor oid;
BEGIN
 IF authorize_read IS NULL THEN RAISE EXCEPTION 'explicit validation authority mode required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT transition FROM truss.runtime_edge_transition WHERE transition_id=selected_transition;
 IF prepared_attempt.id IS NOT NULL THEN
  IF prepared_attempt.id IS DISTINCT FROM transition.attempt_id THEN RAISE EXCEPTION 'original checked attempt required' USING ERRCODE='55000';END IF;
  attempt:=prepared_attempt;
 ELSE SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=transition.attempt_id;END IF;
 IF prepared_input IS NOT NULL AND (source_bytes IS NULL OR source_bytes IS DISTINCT FROM attempt.input_bytes) THEN
  RAISE EXCEPTION 'original checked transition input required' USING ERRCODE='55000';END IF;
 -- Only group settlement supplies the original attempt and input after its
 -- complete immutable result-slot census. Per-step and history calls recount.
 current_actor:=coalesce(qualified_actor,truss.runtime_person(false));
 IF attempt.writer_xid IS DISTINCT FROM transition.writer_xid OR transition.operation_index<0 OR transition.operation_index>=attempt.next_index
  OR (CASE WHEN NOT authorize_read AND prepared_attempt.id IS NOT NULL AND prepared_input IS NOT NULL
   THEN attempt.next_index ELSE (SELECT count(*) FROM truss.runtime_owned_operation p WHERE p.attempt_id=attempt.id AND p.result IS NOT NULL) END)<>attempt.next_index
  OR (authorize_read AND NOT attempt.complete)
  OR (NOT authorize_read AND (attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM current_actor)) THEN
  RAISE EXCEPTION 'original completed edge operation progress required' USING ERRCODE='55000';END IF;
 plan:=truss.runtime_owned_plan(attempt.id,transition.operation_index);
 catalog_revision:=plan->'catalogRevision';
 FOR candidate,candidate_state IN SELECT key,value FROM jsonb_each(plan->'afterEdges') LOOP
  identity:=truss.runtime_owned_identity(attempt.id,transition.operation_index,candidate,'edge',
   jsonb_build_object('catalogRevision',catalog_revision,'afterEdges',jsonb_build_object(candidate,candidate_state)),attempt);
  IF identity->>'id'=transition.edge_id::text AND identity->>'typeId'=transition.rel_type_id::text THEN
   reference:=candidate;matches:=matches+1;END IF;
 END LOOP;
 IF matches<>1 THEN RAISE EXCEPTION 'one original edge plan member required' USING ERRCODE='55000';END IF;
 prior:=plan->'beforeEdges'->reference;desired:=plan->'afterEdges'->reference;
 expected_mode:=CASE WHEN prior IS NULL THEN 'create_edge' WHEN desired->'deleted'='true'::jsonb THEN 'delete_edge' ELSE 'update_edge' END;
 original_mode:=plan->'operation'->>'operation';
 IF prior->'deleted'='true'::jsonb
  OR (original_mode='delete_object' AND expected_mode<>'delete_edge')
  OR (original_mode<>'delete_object' AND (original_mode IS DISTINCT FROM expected_mode OR reference IS DISTINCT FROM plan->>'primary'))
  OR transition.before_edge-ARRAY['created_at','updated_at'] IS DISTINCT FROM truss.runtime_owned_edge_image(attempt.id,transition.operation_index,reference,'before',plan,attempt)
  OR transition.after_edge-ARRAY['created_at','updated_at'] IS DISTINCT FROM truss.runtime_owned_edge_image(attempt.id,transition.operation_index,reference,'after',plan,attempt) THEN
  RAISE EXCEPTION 'original edge plan and transition images required' USING ERRCODE='55000';END IF;
 -- Exact physical prestate chains back to the original captured scope, including
 -- timestamps, rather than being reconstructed from the semantic projection.
 SELECT after_edge INTO previous_image FROM truss.runtime_edge_transition
  WHERE attempt_id=attempt.id AND edge_id=transition.edge_id AND rel_type_id=transition.rel_type_id
   AND operation_index<transition.operation_index ORDER BY operation_index DESC LIMIT 1;
 has_previous:=FOUND;
 IF NOT has_previous THEN
  SELECT jsonb_extract_path(p.plan,'initialScope','edges',transition.edge_id::text) INTO STRICT previous_image
   FROM truss.runtime_owned_operation p WHERE p.attempt_id=attempt.id AND p.operation_index=0;
 END IF;
 IF transition.before_edge IS DISTINCT FROM previous_image THEN RAISE EXCEPTION 'original physical edge prestate chain required' USING ERRCODE='55000';END IF;
 IF prior IS NOT NULL THEN
  before_context:=jsonb_build_object('source',truss.runtime_owned_endpoint_at(attempt.id,transition.operation_index,prior->>'source','before',plan,attempt),
   'target',truss.runtime_owned_endpoint_at(attempt.id,transition.operation_index,prior->>'target','before',plan,attempt));
 END IF;
 IF desired->'deleted'='false'::jsonb THEN
  after_context:=jsonb_build_object('source',truss.runtime_owned_endpoint_at(attempt.id,transition.operation_index,desired->>'source','after',plan,attempt),
   'target',truss.runtime_owned_endpoint_at(attempt.id,transition.operation_index,desired->>'target','after',plan,attempt));
 END IF;
 expected_context:=jsonb_build_object('profile','truss-edge-endpoint-ownership/0.1','captureCatalogRevision',plan->>'catalogRevision',
  'before',before_context,'after',after_context);
 IF transition.endpoint_ownership IS DISTINCT FROM expected_context
  OR nullif(transition.old_source,'null'::jsonb) IS DISTINCT FROM before_context->'source'->'identity'
  OR nullif(transition.old_target,'null'::jsonb) IS DISTINCT FROM before_context->'target'->'identity'
  OR transition.source_identity IS DISTINCT FROM truss.runtime_owned_identity(attempt.id,transition.operation_index,desired->>'source','object',plan,attempt)
  OR transition.target_identity IS DISTINCT FROM truss.runtime_owned_identity(attempt.id,transition.operation_index,desired->>'target','object',plan,attempt) THEN
  RAISE EXCEPTION 'original endpoint and aggregate root context required' USING ERRCODE='55000';END IF;
 IF transition.before_edge IS NOT DISTINCT FROM transition.after_edge THEN
  IF transition.journal<>'[]'::jsonb THEN RAISE EXCEPTION 'unchanged edge has no journal' USING ERRCODE='55000';END IF;
 ELSE
  IF jsonb_array_length(transition.journal)<>1 THEN RAISE EXCEPTION 'one complete original edge event required' USING ERRCODE='55000';END IF;
  journal:=transition.journal->0;event:=convert_from(decode(journal->'new_value'->>'bytesBase64','base64'),'UTF8')::jsonb;
  expected_version:=CASE WHEN expected_mode='delete_edge' THEN (transition.before_edge->>'ver')::bigint+1 ELSE (transition.after_edge->>'ver')::bigint END;
  IF event->>'historyProfile' IS DISTINCT FROM 'truss-native-owned-edge-mutation/0.1'
   OR event->>'operation' IS DISTINCT FROM (CASE expected_mode WHEN 'create_edge' THEN 'create' WHEN 'delete_edge' THEN 'delete' ELSE 'metadata' END)
   OR event->>'eventVersion' IS DISTINCT FROM expected_version::text
   OR event->'identity' IS DISTINCT FROM truss.runtime_owned_identity(attempt.id,transition.operation_index,reference,'edge',plan,attempt) THEN
   RAISE EXCEPTION 'original owned edge event required' USING ERRCODE='55000';END IF;
 END IF;
 IF authorize_read THEN
  FOR context IN SELECT value FROM jsonb_array_elements(jsonb_build_array(before_context->'source',before_context->'target',after_context->'source',after_context->'target')) WHERE value<>'null'::jsonb LOOP
   IF NOT truss.runtime_can_read_qualified(context->'identity'->'owner'->>'documentId',context->'identity'->'owner'->>'moduleId',current_actor) THEN
    RAISE EXCEPTION 'current original endpoint reader required' USING ERRCODE='42501';END IF;
   PERFORM truss.runtime_history_ownership_qualified(jsonb_build_object('identity',context->'identity','catalogRevision',plan->>'catalogRevision','ownership',context->'ownership'),current_actor);
  END LOOP;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_edge_validate_in_input_qualified(selected_id bigint, selected_type integer, prepared_input jsonb, source_bytes bytea, prepared_attempt truss.runtime_object_attempt, qualified_actor oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE latest truss.runtime_edge_transition%ROWTYPE;actual jsonb;entry jsonb;selected_transition bigint;transition_attempt_id uuid;current_actor oid;owner record;
BEGIN
 SELECT * INTO latest FROM truss.runtime_edge_transition WHERE edge_id=selected_id AND rel_type_id=selected_type AND writer_xid=pg_current_xact_id() ORDER BY transition_id DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'registered current edge mutation required' USING ERRCODE='55000';END IF;
 current_actor:=qualified_actor;
 IF NOT EXISTS(SELECT 1 FROM truss.runtime_object_attempt WHERE id=latest.attempt_id AND writer_xid=latest.writer_xid AND actor_oid=current_actor) THEN
  RAISE EXCEPTION 'registered current edge mutation required' USING ERRCODE='55000';END IF;
 -- Row/transition events remain queued after an early attempt-constraint flush.
 SELECT document_id,module INTO STRICT owner FROM truss.rel_def WHERE rel_type_id=selected_type;
 PERFORM truss.runtime_module_writer_qualified(owner.document_id,owner.module,current_actor);
 FOR selected_transition,transition_attempt_id IN SELECT t.transition_id,t.attempt_id FROM truss.runtime_edge_transition t JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
  WHERE t.edge_id=selected_id AND t.rel_type_id=selected_type AND t.writer_xid=pg_current_xact_id()
   AND a.context->'mutationProfile'=truss.runtime_owned_profile() LOOP
  -- The sole non-NULL caller is object_group_finish, after its complete
  -- runtime_edge_authorize pass following marker refresh. That pass already
  -- reconstructed every current-attempt transition, including ordinal bounds.
  -- This loop has no writes. Keep current module and physical checks here;
  -- standalone calls and other attempts still reconstruct their transitions.
  -- Mandatory owned-group finish and commit reconstruction remain independent.
  IF prepared_attempt.id IS NULL OR transition_attempt_id IS DISTINCT FROM prepared_attempt.id THEN
   PERFORM truss.runtime_owned_edge_transition_validate(selected_transition,false,current_actor);
  END IF;
 END LOOP;
 SELECT to_jsonb(e) INTO actual FROM truss.edge e WHERE id=selected_id AND rel_type_id=selected_type;
 IF actual IS DISTINCT FROM latest.after_edge THEN RAISE EXCEPTION 'exact final edge required' USING ERRCODE='55000';END IF;
 FOR entry IN SELECT j.value FROM truss.runtime_edge_transition t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j WHERE t.edge_id=selected_id AND t.rel_type_id=selected_type AND t.writer_xid=pg_current_xact_id() LOOP
  SELECT to_jsonb(j) INTO actual FROM truss.journal j WHERE j.at=(entry->>'at')::timestamptz AND j.seq=(entry->>'seq')::bigint;
  IF actual IS DISTINCT FROM entry THEN RAISE EXCEPTION 'exact edge journal required' USING ERRCODE='55000';END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_endpoint_at(selected_attempt uuid, selected_index integer, reference text, phase text, prepared_plan jsonb DEFAULT NULL::jsonb, prepared_attempt truss.runtime_object_attempt DEFAULT NULL::truss.runtime_object_attempt)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE plan jsonb;state jsonb;identity jsonb;ownership jsonb;root_identity jsonb;
BEGIN
 IF phase IS NULL OR phase NOT IN ('before','after') THEN RAISE EXCEPTION 'explicit endpoint phase required' USING ERRCODE='55000';END IF;
 plan:=coalesce(prepared_plan,truss.runtime_owned_plan(selected_attempt,selected_index));state:=jsonb_extract_path(plan,phase||'Nodes',reference);
 IF state IS NULL OR state->'deleted'='true'::jsonb THEN RAISE EXCEPTION 'original live endpoint context required' USING ERRCODE='55000';END IF;
 identity:=truss.runtime_owned_identity(selected_attempt,selected_index,reference,'object',plan,prepared_attempt);ownership:='{"state":"rootless"}'::jsonb;
 IF state->>'root' IS NOT NULL THEN
  root_identity:=truss.runtime_owned_identity(selected_attempt,selected_index,state->>'root','object',plan,prepared_attempt);
  ownership:=jsonb_build_object('state','owned','root',root_identity);
 END IF;
 RETURN jsonb_build_object('identity',identity,'ownership',ownership);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_group_step_in_input(attempt_id uuid, operation_index integer, original_keys bytea, original_input bytea, parsed_input jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
<<ordered_group_step>>
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;operation jsonb;metadata jsonb;raw jsonb;result jsonb;identity jsonb;
 old_image jsonb;new_image jsonb;object_row truss.object%ROWTYPE;keys jsonb;entry jsonb;property truss.prop_def%ROWTYPE;pin record;
 events jsonb:='[]';event_refs jsonb:='[]';journals jsonb:='[]';event jsonb;journal truss.journal%ROWTYPE;event_digest text;native_state text;
 current_actor oid;revision int;version bigint;installation truss.catalog_runtime_installation%ROWTYPE;before_record jsonb;after_record jsonb;
BEGIN
 current_actor:=truss.runtime_person(false);
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id;
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM current_actor OR attempt.complete OR attempt.next_index IS DISTINCT FROM operation_index THEN RAISE EXCEPTION 'current ordered object attempt required' USING ERRCODE='55000';END IF;
 input:=parsed_input;operation:=jsonb_extract_path(input,'operations',operation_index::text);
 IF input->'mutationProfile'=truss.runtime_owned_profile() AND operation->>'operation'<>'create_object' THEN
  RETURN truss.runtime_owned_step(attempt_id,operation_index,input,attempt.input_bytes,current_actor);
 END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 IF operation->>'operation'='create_object' THEN
  raw:=convert_from(truss.apply_create_group_qualified(convert_to(((input-ARRAY['preconditions','operations'])||jsonb_build_object('operations',jsonb_build_array(operation)))::text,'UTF8'),attempt.documents_bytes,
   original_keys,convert_to('{"state":"none"}','UTF8'),installation.release_id,installation.release_sha256,current_actor,attempt_id,original_input,input),'UTF8')::jsonb;
  IF raw->>'outcome'<>'success' THEN
   native_state:=coalesce(raw->>'nativeState',CASE raw->>'reason' WHEN 'resource' THEN '54000' WHEN 'observation' THEN '55P03' ELSE '0A000' END);
   RAISE EXCEPTION 'create operation refused' USING ERRCODE=native_state;
  END IF;
  result:=raw->'semantic'->'results'->0;
  -- The leaf advances the indexed slot and ordinal atomically. Group finish
  -- performs the one complete inventory check; no immediate progress readback.
  RETURN convert_to(result::text,'UTF8');
 END IF;
 metadata:=truss.runtime_object_metadata(attempt_id,operation_index);
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=attempt_id;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;operation:=input->'operations'->operation_index;
 IF operation->>'operation' IN ('create_edge','update_edge','delete_edge') THEN RETURN truss.runtime_edge_step(attempt_id,operation_index,metadata);END IF;
 identity:=metadata->'identity';old_image:=metadata->'prior';
 object_row:=(jsonb_populate_record(NULL::truss.object,old_image));
 IF operation->>'operation'='update_object' AND object_row.props IS NOT DISTINCT FROM metadata->'props' AND coalesce(object_row.retained,'{}') IS NOT DISTINCT FROM metadata->'retained' THEN
  result:=jsonb_build_object('outcome','unchanged','operation','update_object','identity',identity,'version',object_row.ver::text,'events','[]'::jsonb);
 ELSE
  IF object_row.ver=9223372036854775807 THEN RAISE EXCEPTION 'record version exhausted' USING ERRCODE='54000';END IF;
  version:=object_row.ver+1;before_record:=truss.runtime_object_history(old_image,identity);
  IF operation->>'operation'='update_object' THEN
   PERFORM truss.runtime_object_update_keys(object_row.id,object_row.type_id,metadata->'props',original_keys,attempt_id,operation_index);
   object_row.props:=metadata->'props';object_row.retained:=nullif(metadata->'retained','{}'::jsonb);object_row.rev:=revision;object_row.ver:=version;object_row.updated_at:=clock_timestamp();new_image:=to_jsonb(object_row);
   UPDATE truss.object SET props=object_row.props,retained=object_row.retained,rev=object_row.rev,ver=object_row.ver,updated_at=object_row.updated_at WHERE id=object_row.id AND type_id=object_row.type_id;
   after_record:=truss.runtime_object_history(new_image,identity);
   FOR property IN SELECT * FROM truss.prop_def WHERE type_id=object_row.type_id AND retired_rev IS NULL ORDER BY prop_id LOOP
    IF old_image->'props'->property.prop_id::text IS DISTINCT FROM object_row.props->property.prop_id::text THEN
     SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('property',object_row.type_id,property.prop_id);
     events:=events||jsonb_build_array(jsonb_build_object('operation','property','propertyId',property.prop_id::text,'definitionPin',pin.definition_pin,
      'before',CASE WHEN old_image->'props' ? property.prop_id::text THEN jsonb_build_object('present',true,'value',old_image->'props'->property.prop_id::text) ELSE '{"present":false}'::jsonb END,
      'after',CASE WHEN object_row.props ? property.prop_id::text THEN jsonb_build_object('present',true,'value',object_row.props->property.prop_id::text) ELSE '{"present":false}'::jsonb END));
    END IF;
   END LOOP;
   events:=events||jsonb_build_array(jsonb_build_object('operation','metadata','before',before_record,'after',after_record));
  ELSE
   FOR entry IN SELECT to_jsonb(k) FROM truss.object_key_bucket k WHERE k.object_id=object_row.id AND k.type_id=object_row.type_id LOOP
    PERFORM truss.lock_string_key_bucket(decode(substring(entry->>'namespace_bytes' FROM 3),'hex'),decode(substring(entry->>'key_bytes' FROM 3),'hex'));
    UPDATE truss.key_bucket_guard SET generation=generation+1 WHERE namespace_sha256=decode(substring(entry->>'namespace_sha256' FROM 3),'hex') AND key_sha256=decode(substring(entry->>'key_sha256' FROM 3),'hex');
   END LOOP;
   DELETE FROM truss.object WHERE id=object_row.id AND type_id=object_row.type_id;new_image:=NULL;
   events:=jsonb_build_array(jsonb_build_object('operation','delete','before',before_record));
  END IF;
  FOR index IN 0..jsonb_array_length(events)-1 LOOP
   event:=events->index;event:=event||jsonb_build_object('interfaceVersion','truss-history-event/0.2.0-proposal','sourceEpoch',installation.source_epoch::text,
    'historyProfile','truss-native-scalar-mutation/0.1','xid',attempt.writer_xid::text,'seq',nextval('truss.journal_seq')::text,
    'identity',identity,'eventVersion',version::text,'eventCatalogRevision',revision::text,'origin',jsonb_build_object('asserted',input->'assertedOrigin','databaseRole',session_user::text));
   events:=jsonb_set(events,ARRAY[index::text],event);
  END LOOP;
  event_digest:=encode(sha256(convert_to(events::text,'UTF8')),'hex');
  FOR event IN SELECT value FROM jsonb_array_elements(events) LOOP
   event:=event||jsonb_build_object('mutationGroup',jsonb_build_object('profile','truss-history-group/0.1.0','eventCount',jsonb_array_length(events)::text,'orderedEventDigest',event_digest));
   journal.seq:=(event->>'seq')::bigint;journal.at:=clock_timestamp();journal.xid:=attempt.writer_xid;journal.entity_kind:='o';journal.entity_id:=object_row.id;journal.entity_type:=object_row.type_id;
   journal.ver:=version;journal.op:=CASE event->>'operation' WHEN 'property' THEN 'update' ELSE event->>'operation' END;journal.prop_id:=(event->>'propertyId')::int;
   journal.old_value:=NULL;journal.new_value:=truss.runtime_exact_wrapper('event',convert_to(event::text,'UTF8'));journal.rev:=revision;
   journal.origin:=truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8'));
   INSERT INTO truss.journal SELECT (jsonb_populate_record(NULL::truss.journal,to_jsonb(journal))).*;
   journals:=journals||jsonb_build_array(to_jsonb(journal));event_refs:=event_refs||jsonb_build_array(jsonb_build_object('sourceEpoch',installation.source_epoch::text,'historyProfile','truss-native-scalar-mutation/0.1','xid',attempt.writer_xid::text,'seq',journal.seq::text));
  END LOOP;
  SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY k.key_num),'[]'::jsonb) INTO keys FROM truss.object_key_bucket k WHERE k.object_id=object_row.id AND k.type_id=object_row.type_id;
  INSERT INTO truss.runtime_object_transition(attempt_id,operation_index,writer_xid,object_id,type_id,before_object,after_object,after_keys,journal)
  VALUES(attempt_id,operation_index,attempt.writer_xid,object_row.id,object_row.type_id,old_image,new_image,keys,journals);
  IF operation->>'operation'='update_object' THEN result:=jsonb_build_object('outcome','changed','operation','update_object','identity',identity,'version',version::text,'events',event_refs);
  ELSE result:=jsonb_build_object('outcome','deleted','operation','delete_object','identity',identity,'deletionVersion',version::text,
   'deleted',jsonb_build_array(jsonb_build_object('identity',identity,'deletionVersion',version::text)),'events',event_refs);END IF;
 END IF;
 UPDATE truss.runtime_object_attempt SET next_index=next_index+1,results=results||jsonb_build_array(result) WHERE id=attempt_id;
 PERFORM truss.runtime_module_writer(metadata->>'documentId',metadata->>'moduleId');
 RETURN convert_to(result::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_identity(selected_attempt uuid, selected_index integer, reference text, entity_kind text, prepared_plan jsonb DEFAULT NULL::jsonb, prepared_attempt truss.runtime_object_attempt DEFAULT NULL::truss.runtime_object_attempt)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE plan jsonb;state jsonb;identity jsonb;attempt truss.runtime_object_attempt%ROWTYPE;
 creation_index int;result jsonb;creation_plan jsonb;operation jsonb;witness jsonb;pin record;
BEGIN
 IF entity_kind NOT IN ('object','edge') OR entity_kind IS NULL OR reference IS NULL THEN
  RAISE EXCEPTION 'explicit original entity reference required' USING ERRCODE='55000';END IF;
 plan:=coalesce(prepared_plan,truss.runtime_owned_plan(selected_attempt,selected_index));
 state:=coalesce(jsonb_extract_path(plan,CASE entity_kind WHEN 'object' THEN 'afterNodes' ELSE 'afterEdges' END,reference),
  jsonb_extract_path(plan,CASE entity_kind WHEN 'object' THEN 'beforeNodes' ELSE 'beforeEdges' END,reference));
 IF state IS NULL AND entity_kind='object' AND reference LIKE 'stored:%' THEN
  SELECT jsonb_extract_path(p.plan,'initialScope','boundary',substring(reference FROM 8)) INTO witness
   FROM truss.runtime_owned_operation p WHERE p.attempt_id=selected_attempt AND p.operation_index=0;
  IF witness IS NOT NULL THEN
   SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',(witness->'object'->>'type_id')::int,NULL,(plan->>'catalogRevision')::int);
   state:=jsonb_build_object('identity',jsonb_build_object('id',witness->'object'->>'id','typeId',witness->'object'->>'type_id',
    'definitionPin',pin.definition_pin,'owner',jsonb_build_object('documentId',pin.document_id,'moduleId',pin.module_id)));
  END IF;
 END IF;
 IF state IS NULL THEN RAISE EXCEPTION 'original operation member required' USING ERRCODE='55000';END IF;
 identity:=state->'identity';
 IF reference LIKE 'stored:%' THEN
  IF reference IS DISTINCT FROM 'stored:'||(identity->>'typeId')||':'||(identity->>'id') THEN
   RAISE EXCEPTION 'original stored identity correspondence required' USING ERRCODE='55000';END IF;
 ELSIF reference ~ '^create:(0|[1-9][0-9]{0,2}|10[01][0-9]|102[0-3])$' THEN
  creation_index:=substring(reference FROM 8)::int;
  IF prepared_attempt.id IS NOT NULL THEN
   IF prepared_attempt.id IS DISTINCT FROM selected_attempt THEN RAISE EXCEPTION 'original checked attempt required' USING ERRCODE='55000';END IF;
   attempt:=prepared_attempt;
  ELSE SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;END IF;
  IF creation_index>selected_index OR creation_index>=attempt.next_index THEN
   RAISE EXCEPTION 'prior original create progress required' USING ERRCODE='55000';END IF;
  SELECT p.result,p.plan INTO STRICT result,creation_plan FROM truss.runtime_owned_operation p
   WHERE p.attempt_id=selected_attempt AND p.operation_index=creation_index AND p.writer_xid=attempt.writer_xid;
  IF result IS NULL THEN RAISE EXCEPTION 'sealed original create result required' USING ERRCODE='55000';END IF;
  -- The sealed result and immutable source plan are the same original slot.
  -- Keep the standalone plan reader's checks after the result refusal.
  IF creation_index<0
   OR creation_plan->>'profile' IS DISTINCT FROM 'truss-owned-operation-plan/0.2'
   OR creation_plan->'operationIndex' IS DISTINCT FROM to_jsonb(creation_index)
   OR creation_plan->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
   RAISE EXCEPTION 'original owned operation correspondence required' USING ERRCODE='55000';END IF;
  operation:=creation_plan->'operation';
  IF result->>'operation' IS DISTINCT FROM 'create_'||entity_kind
   OR operation->>'operation' IS DISTINCT FROM result->>'operation'
   OR result->>'outcome' IS DISTINCT FROM 'created'
   OR (result->'identity')-'id' IS DISTINCT FROM identity-'id'
   OR jsonb_typeof(result->'identity'->'id') IS DISTINCT FROM 'string'
   OR result->'identity'->>'id' !~ '^[1-9][0-9]{0,18}$'
   OR length(result->'identity'->>'id')=19 AND result->'identity'->>'id' COLLATE "C">'9223372036854775807' THEN
   RAISE EXCEPTION 'genuine original create result required' USING ERRCODE='55000';END IF;
  identity:=result->'identity';
 ELSE RAISE EXCEPTION 'original stored or create reference required' USING ERRCODE='55000';END IF;
 RETURN identity;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_import_record_source(selected_attempt uuid, selected_index integer, original_record bytea, load_id text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;operations jsonb;results jsonb;owned_profile_matches boolean;load_id_asserted boolean;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 IF NOT attempt.complete OR attempt.writer_xid<>pg_current_xact_id() OR attempt.actor_oid<>truss.runtime_person(false) THEN
  RAISE EXCEPTION 'current complete import attempt required' USING ERRCODE='55000';END IF;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
 operations:=input->'operations';results:=attempt.results;
 owned_profile_matches:=input->'mutationProfile' IS NOT DISTINCT FROM truss.runtime_owned_profile();
 load_id_asserted:=EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e
  WHERE e.value->>'key'='x-load-id' AND e.value->'value'=jsonb_build_object('kind','string','text',load_id));
 RETURN truss.runtime_owned_import_record_source_checked(attempt.id,attempt.next_index,attempt.writer_xid,
  operations->selected_index,results->selected_index,owned_profile_matches,load_id_asserted,selected_index,original_record,load_id);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_import_record_source_checked(checked_attempt uuid, checked_next_index integer, checked_writer_xid xid8, checked_operation jsonb, checked_result jsonb, owned_profile_matches boolean, load_id_asserted boolean, selected_index integer, original_record bytea, load_id text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE selected_attempt uuid:=checked_attempt;record jsonb;payload bytea;value jsonb;operation jsonb:=checked_operation;result jsonb:=checked_result;source_value jsonb:='{}';source_invalid boolean;component_invalid boolean;expected_source jsonb;source_row truss.record_source%ROWTYPE;kind char(1);metadata jsonb;selected_type truss.type_def%ROWTYPE;owned_selection boolean;root_identity jsonb;resolved_source_identity jsonb;resolved_target_identity jsonb;source_entity_id bigint;inserted_rows int;
BEGIN
 IF selected_index IS NULL OR selected_index<0 OR selected_index>=checked_next_index THEN RAISE EXCEPTION 'current complete indexed import group required' USING ERRCODE='55000';END IF;
 IF original_record IS NULL OR octet_length(original_record) NOT BETWEEN 1 AND 2097152 OR (convert_from(original_record,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
  OR load_id IS NULL OR octet_length(load_id) NOT BETWEEN 1 AND 4096 THEN RAISE EXCEPTION 'bounded original import record/load required' USING ERRCODE='22023';END IF;
 record:=convert_from(original_record,'UTF8')::jsonb;payload:=decode(record->'payload'->>'bytesBase64','base64');
 IF record-ARRAY['kind','identity','payload','payloadProfile']<>'{}'::jsonb OR (record->>'kind' IN ('object','edge')) IS NOT TRUE THEN RAISE EXCEPTION 'closed import record required' USING ERRCODE='22023';END IF;
 IF octet_length(payload) NOT BETWEEN 1 AND 1048576 OR (convert_from(payload,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'bounded unique original payload required' USING ERRCODE='22023';END IF;
 value:=convert_from(payload,'UTF8')::jsonb;
 owned_selection:=record->'payloadProfile'=truss.runtime_import_profiles()->'ownedImportPayloadProfile';
 -- Indexed rootless object batches use the same original scalar payload. Only
 -- the indexed batch facade reaches this form; the legacy one-record facade
 -- retains its one-operation check. All payload/key/actual-root checks below
 -- still apply to the exact selected native operation and result.
 IF owned_selection IS NOT TRUE AND (selected_index<>0 OR checked_next_index<>1)
  AND (owned_profile_matches IS TRUE AND record->>'kind'='object'
   AND operation->>'operation'='create_object' AND operation->'ownership'='{"state":"rootless"}'::jsonb) IS NOT TRUE THEN
  RAISE EXCEPTION 'legacy one-create import group required' USING ERRCODE='0A000';END IF;

 IF (record->'payloadProfile' IS DISTINCT FROM truss.runtime_import_profiles()->'ownedImportPayloadProfile'
  AND record->'payloadProfile' IS DISTINCT FROM truss.runtime_import_profiles()->'importPayloadProfile'
  AND NOT ((record->'payloadProfile'='{"identity":"truss-scalar-import-payload","version":"0.2","sha256":"45180a79836394b3c3c945cfe908b67e3a45ab3c81362f052b12ae45e7042281"}'::jsonb
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value->'values') v WHERE truss.valid_flat_cell(v.value->'value') IS NOT TRUE)
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value->'values') v
    CROSS JOIN LATERAL jsonb_array_elements(CASE v.value->'value'->>'kind' WHEN 'sequence' THEN v.value->'value'->'items' WHEN 'map' THEN v.value->'value'->'entries' ELSE '[]'::jsonb END) child
    WHERE truss.valid_scalar_cell(CASE v.value->'value'->>'kind' WHEN 'map' THEN child.value->'value' ELSE child.value END) IS NOT TRUE)) IS TRUE)
  AND NOT ((record->'payloadProfile'='{"identity":"truss-scalar-import-payload","version":"0.1","sha256":"bc7624102bf13a1f87d5382be8d7d02007c49f1775dbca14489a650d7d7ec2ed"}'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value->'values') v WHERE truss.valid_scalar_cell(v.value->'value') IS NOT TRUE)) IS TRUE)) OR encode(sha256(payload),'hex') IS DISTINCT FROM record->'payload'->>'sha256'
  OR octet_length(payload) NOT BETWEEN 1 AND 1048576 OR (convert_from(payload,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'exact original profiled payload required' USING ERRCODE='22023';END IF;
 IF owned_selection AND owned_profile_matches IS NOT TRUE THEN RAISE EXCEPTION 'owned import group profile required' USING ERRCODE='0A000';END IF;
 IF value-ARRAY['interfaceVersion','kind','values','source',CASE record->>'kind' WHEN 'object' THEN 'ownership' ELSE 'orderKey' END]<>'{}'::jsonb THEN RAISE EXCEPTION 'closed profiled import payload required' USING ERRCODE='22023';END IF;
 IF (record->>'kind' IN ('object','edge')) IS NOT TRUE OR value->>'interfaceVersion' IS DISTINCT FROM (CASE WHEN owned_selection THEN 'truss-owned-import-payload/0.1.0' ELSE 'truss-import-payload/0.1.0' END) OR value->>'kind' IS DISTINCT FROM record->>'kind' OR result->>'outcome'<>'created'
  OR load_id_asserted IS NOT TRUE THEN
  RAISE EXCEPTION 'original import creation/load origin required' USING ERRCODE='22023';END IF;
 IF record->>'kind'='object' THEN
  kind:='o';
  IF operation->>'operation'<>'create_object' OR operation->>'typeDefinitionPin' IS DISTINCT FROM record->'identity'->'type'->>'definitionPin'
   OR operation->'values' IS DISTINCT FROM value->'values' OR NOT owned_selection AND operation->'ownership' IS DISTINCT FROM value->'ownership' THEN RAISE EXCEPTION 'original object payload creation required' USING ERRCODE='22023';END IF;
  SELECT * INTO STRICT selected_type FROM truss.type_def WHERE type_id=(result->'identity'->>'typeId')::int;
  metadata:=convert_from(truss.import_key_selection(selected_type.document_id,selected_type.module,selected_type.element,
   (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation())),'UTF8')::jsonb;
  IF (record->'identity')-ARRAY['operation','type','keyNumber','keyDefinitionPin','keyEncodingProfile','components']<>'{}'::jsonb OR record->'identity'->>'operation' IS DISTINCT FROM 'object_key' OR jsonb_typeof(record->'identity'->'components') IS DISTINCT FROM 'array' OR record->'identity'->'type' IS DISTINCT FROM metadata->'type' OR record->'identity'->>'keyNumber' IS DISTINCT FROM metadata->>'keyNumber'
   OR record->'identity'->>'keyDefinitionPin' IS DISTINCT FROM metadata->>'keyDefinitionPin' OR (record->'identity'->'keyEncodingProfile' IS DISTINCT FROM metadata->'keyEncodingProfile' AND NOT ((record->'identity'->'keyEncodingProfile'='{"identity":"truss-selected-umf-string-key","version":"0.1","sha256":"07e1b99b22803e55a378f8068a6b80454b7581129c66eabcb117545746a16625"}'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(record->'identity'->'components') c WHERE c.value->'value'->>'kind' IS DISTINCT FROM 'string')) IS TRUE))
   OR jsonb_array_length(record->'identity'->'components') IS DISTINCT FROM jsonb_array_length(metadata->'components') THEN RAISE EXCEPTION 'actual complete import primary key required' USING ERRCODE='22023';END IF;
  WITH value_rows AS MATERIALIZED (
   SELECT v.value AS authored_value,v.ordinality
   FROM jsonb_array_elements(value->'values') WITH ORDINALITY v(value,ordinality)
  ), values_by_name AS MATERIALIZED (
   SELECT jsonb_object_agg(authored_value->>'name',authored_value->'value')
    FILTER(WHERE jsonb_typeof(authored_value->'name')='string') AS value_map FROM value_rows
  ), components AS MATERIALIZED (
   SELECT c.value AS component,c.ordinality,
    metadata->'components'->((c.ordinality-1)::int) AS metadata_field
   FROM jsonb_array_elements(record->'identity'->'components') WITH ORDINALITY c(value,ordinality)
  ), component_checks AS (
   SELECT (component-ARRAY['propertyId','definitionPin','value']<>'{}'::jsonb
    OR jsonb_typeof(component->'propertyId') IS DISTINCT FROM 'string'
    OR jsonb_typeof(component->'definitionPin') IS DISTINCT FROM 'string'
    OR truss.valid_scalar_cell(component->'value',NULL,false) IS NOT TRUE
    OR component->>'propertyId' IS DISTINCT FROM metadata_field->>'propertyId'
    OR component->>'definitionPin' IS DISTINCT FROM metadata_field->>'definitionPin'
    OR value_map->(metadata_field->>'name') IS DISTINCT FROM component->'value') AS invalid
   FROM components CROSS JOIN values_by_name
  )
  SELECT coalesce(bool_or(invalid),false)
    OR (SELECT count(*)<>count(DISTINCT authored_value->>'name') FROM value_rows)
   INTO component_invalid FROM component_checks;
  IF component_invalid THEN RAISE EXCEPTION 'original primary field/payload agreement required' USING ERRCODE='22023';END IF;
 ELSE
  kind:='e';
  IF operation->>'operation'<>'create_edge' OR operation->>'relationshipDefinitionPin' IS DISTINCT FROM record->'identity'->>'relationshipDefinitionPin'
   OR NOT owned_selection AND (operation->'source' IS DISTINCT FROM jsonb_build_object('state','stored','identity',record->'identity'->'source') OR operation->'target' IS DISTINCT FROM jsonb_build_object('state','stored','identity',record->'identity'->'target'))
   OR operation->'values' IS DISTINCT FROM value->'values' OR operation->'orderKey' IS DISTINCT FROM value->'orderKey' THEN RAISE EXCEPTION 'original edge payload creation required' USING ERRCODE='22023';END IF;
 END IF;
 -- The granted source-registration facade enforces the same selected import
 -- subset itself; calling the Python identity preflight is not authority.
 IF owned_selection THEN
  IF kind='o' THEN
   IF value->'ownership'='{"state":"rootless"}'::jsonb THEN root_identity:=NULL;
   ELSIF value->'ownership'->>'state'='owned' AND (value->'ownership')-ARRAY['state','root']='{}'::jsonb THEN
    root_identity:=truss.runtime_owned_import_reference(convert_to((value->'ownership'->'root')::text,'UTF8'),
     (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation()))->'identity';
    root_identity:=nullif(root_identity,'null'::jsonb);
    IF root_identity IS NULL THEN RAISE EXCEPTION 'live imported aggregate root required' USING ERRCODE='22023';END IF;
   ELSE RAISE EXCEPTION 'explicit original imported ownership required' USING ERRCODE='22023';END IF;
   IF operation->'ownership'->>'state' IS DISTINCT FROM value->'ownership'->>'state' OR NOT EXISTS(
    SELECT 1 FROM truss.object o WHERE o.id=(result->'identity'->>'id')::bigint AND o.type_id=(result->'identity'->>'typeId')::int
     AND o.root_id IS NOT DISTINCT FROM (root_identity->>'id')::bigint
     AND o.root_type IS NOT DISTINCT FROM (root_identity->>'typeId')::int) THEN
    RAISE EXCEPTION 'original imported ownership correspondence required' USING ERRCODE='55000';END IF;
  ELSE
   resolved_source_identity:=truss.runtime_owned_import_reference(convert_to((record->'identity'->'source')::text,'UTF8'),
    (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation()))->'identity';
   resolved_target_identity:=truss.runtime_owned_import_reference(convert_to((record->'identity'->'target')::text,'UTF8'),
    (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation()))->'identity';
   resolved_source_identity:=nullif(resolved_source_identity,'null'::jsonb);resolved_target_identity:=nullif(resolved_target_identity,'null'::jsonb);
   IF resolved_source_identity IS NULL OR resolved_target_identity IS NULL OR NOT EXISTS(
    SELECT 1 FROM truss.runtime_edge_transition t WHERE t.attempt_id=selected_attempt AND t.operation_index=selected_index
     AND t.before_edge IS NULL AND t.edge_id=(result->'identity'->>'id')::bigint AND t.rel_type_id=(result->'identity'->>'typeId')::int
     AND t.source_identity IS NOT DISTINCT FROM resolved_source_identity AND t.target_identity IS NOT DISTINCT FROM resolved_target_identity) THEN
    RAISE EXCEPTION 'original imported endpoint correspondence required' USING ERRCODE='55000';END IF;
  END IF;
 ELSIF kind='o' THEN
  IF operation->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb OR NOT EXISTS(
   SELECT 1 FROM truss.object o WHERE o.id=(result->'identity'->>'id')::bigint AND o.type_id=(result->'identity'->>'typeId')::int
    AND o.root_id IS NULL AND o.root_type IS NULL) THEN
   RAISE EXCEPTION 'original rootless object source profile required' USING ERRCODE='0A000';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM truss.edge e JOIN truss.rel_def r ON r.rel_type_id=e.rel_type_id
   JOIN truss.object source_object ON source_object.id=e.source_id AND source_object.type_id=e.source_type
   JOIN truss.object target_object ON target_object.id=e.target_id AND target_object.type_id=e.target_type
   WHERE e.id=(result->'identity'->>'id')::bigint AND e.rel_type_id=(result->'identity'->>'typeId')::int
    AND r.lifecycle='independent' AND source_object.root_id IS NULL AND source_object.root_type IS NULL
    AND target_object.root_id IS NULL AND target_object.root_type IS NULL)
   OR NOT EXISTS(SELECT 1 FROM truss.runtime_edge_transition t WHERE t.attempt_id=selected_attempt AND t.operation_index=0
    AND t.edge_id=(result->'identity'->>'id')::bigint AND t.rel_type_id=(result->'identity'->>'typeId')::int
    AND t.before_edge IS NULL AND t.endpoint_ownership->'after'->'source'->'ownership'='{"state":"rootless"}'::jsonb
    AND t.endpoint_ownership->'after'->'target'->'ownership'='{"state":"rootless"}'::jsonb) THEN
   RAISE EXCEPTION 'original rootless independent edge source profile required' USING ERRCODE='0A000';END IF;
 END IF;
 IF value ? 'source' THEN
  IF (value->'source')-ARRAY['kind','entries']<>'{}'::jsonb OR value->'source'->>'kind' IS DISTINCT FROM 'map' OR jsonb_typeof(value->'source'->'entries') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'exact source map required' USING ERRCODE='22023';END IF;
  WITH source_entries AS MATERIALIZED (
   SELECT e.value AS source_entry,e.ordinal
   FROM jsonb_array_elements(value->'source'->'entries') WITH ORDINALITY e(value,ordinal)
  ), projected AS (
   SELECT se.source_entry,se.ordinal,se.source_entry->>'key' AS source_key,
    CASE se.source_entry->'value'->>'kind' WHEN 'string' THEN se.source_entry->'value'->'text' WHEN 'null' THEN 'null'::jsonb WHEN 'boolean' THEN se.source_entry->'value'->'value' ELSE se.source_entry->'value' END AS cell_source_value,
    (se.source_entry-ARRAY['key','value']<>'{}'::jsonb OR jsonb_typeof(se.source_entry->'key') IS DISTINCT FROM 'string'
     OR octet_length(se.source_entry->>'key') NOT BETWEEN 1 AND 4096 OR truss.valid_scalar_cell(se.source_entry->'value') IS NOT TRUE
     OR se.source_entry->>'key' IN ('author','at','system') AND se.source_entry->'value'->>'kind' NOT IN ('string','null')) AS invalid
   FROM source_entries se
  )
  SELECT coalesce(bool_or(projected.invalid),false) OR count(projected.source_key)<>count(DISTINCT projected.source_key),
   coalesce(jsonb_object_agg(projected.source_key,projected.cell_source_value ORDER BY projected.ordinal)
    FILTER(WHERE projected.source_key IS NOT NULL),'{}'::jsonb)
   INTO source_invalid,source_value FROM projected;
  IF source_invalid THEN RAISE EXCEPTION 'lossless unique scalar source facts required' USING ERRCODE='22023';END IF;
 END IF;
 source_entity_id:=(result->'identity'->>'id')::bigint;
 INSERT INTO truss.record_source(entity_kind,entity_id,load_id,source) VALUES(kind,source_entity_id,load_id,source_value) RETURNING * INTO source_row;
 GET DIAGNOSTICS inserted_rows=ROW_COUNT;
 IF inserted_rows<>1 THEN RAISE EXCEPTION 'one imported source row required' USING ERRCODE='55000';END IF;
 expected_source:=to_jsonb(source_row);
 -- Preserve imported_at in the scalar result; the immutable row is the
 -- canonical source fact, so the compatibility ledger column stays empty.
 INSERT INTO truss.runtime_import_source(entity_kind,entity_id,group_attempt_id,writer_xid,original_record,expected_source,operation_index)
 VALUES(kind,source_entity_id,selected_attempt,checked_writer_xid,original_record,'{}'::jsonb,selected_index);
 PERFORM truss.runtime_module_writer(result->'identity'->'owner'->>'documentId',result->'identity'->'owner'->>'moduleId');
 RETURN convert_to(expected_source::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_import_record_sources(selected_attempt uuid, records jsonb, load_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;operations jsonb;results jsonb;owned_profile_matches boolean;load_id_asserted boolean;entry jsonb;encoded text;original_record bytea;selected_index int;record_count int;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 IF NOT attempt.complete OR attempt.writer_xid<>pg_current_xact_id() OR attempt.actor_oid<>truss.runtime_person(false)
  OR records IS NULL OR jsonb_typeof(records) IS DISTINCT FROM 'array'
  OR octet_length(records::text)>16777216 OR load_id IS NULL OR octet_length(load_id) NOT BETWEEN 1 AND 4096 THEN
  RAISE EXCEPTION 'bounded current completed import source batch required' USING ERRCODE='22023';END IF;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
 operations:=input->'operations';results:=attempt.results;
 owned_profile_matches:=input->'mutationProfile' IS NOT DISTINCT FROM truss.runtime_owned_profile();
 load_id_asserted:=EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e
  WHERE e.value->>'key'='x-load-id' AND e.value->'value'=jsonb_build_object('kind','string','text',load_id));
 record_count:=jsonb_array_length(records);
 IF record_count NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'bounded nonempty import source batch required' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(records) r WHERE jsonb_typeof(r.value) IS DISTINCT FROM 'object'
  OR r.value-ARRAY['operationIndex','originalRecordBase64']<>'{}'::jsonb
  OR jsonb_typeof(r.value->'operationIndex') IS DISTINCT FROM 'number'
  OR (r.value->>'operationIndex') !~ '^(0|[1-9][0-9]{0,2}|10[01][0-9]|102[0-3])$'
  OR jsonb_typeof(r.value->'originalRecordBase64') IS DISTINCT FROM 'string'
  OR octet_length(r.value->>'originalRecordBase64') NOT BETWEEN 4 AND 2796204) THEN
  RAISE EXCEPTION 'exact bounded ordered import source batch entries required' USING ERRCODE='22023';END IF;
 IF (SELECT count(DISTINCT (r.value->>'operationIndex')::int) FROM jsonb_array_elements(records) r)<>record_count
  OR EXISTS(SELECT 1 FROM (SELECT (r.value->>'operationIndex')::int selected_index,
    lag((r.value->>'operationIndex')::int) OVER(ORDER BY r.ordinal) previous_index
   FROM jsonb_array_elements(records) WITH ORDINALITY r(value,ordinal)) ordered
   WHERE ordered.previous_index IS NOT NULL AND ordered.selected_index<=ordered.previous_index)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(records) r
   WHERE (r.value->>'operationIndex')::int>=attempt.next_index) THEN
  RAISE EXCEPTION 'unique input-ordered completed import indexes required' USING ERRCODE='22023';END IF;
 FOR entry IN SELECT r.value FROM jsonb_array_elements(records) WITH ORDINALITY r(value,ordinal) ORDER BY r.ordinal LOOP
  selected_index:=(entry->>'operationIndex')::int;encoded:=entry->>'originalRecordBase64';
  original_record:=decode(encoded,'base64');
  IF octet_length(original_record) NOT BETWEEN 1 AND 2097152 THEN
   RAISE EXCEPTION 'bounded original import record required' USING ERRCODE='22023';END IF;
  PERFORM truss.runtime_owned_import_record_source_checked(attempt.id,attempt.next_index,attempt.writer_xid,
   operations->selected_index,results->selected_index,owned_profile_matches,load_id_asserted,selected_index,original_record,load_id);
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_import_reference(original_identity bytea, expected_release text, expected_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE identity jsonb;selected truss.type_def%ROWTYPE;key_row truss.key_def%ROWTYPE;pin record;
 component record;supplied jsonb;values_json jsonb;values_buffer jsonb[]:=ARRAY[]::jsonb[];found_bytes bytea;found_object jsonb;context jsonb;
BEGIN
 -- Selection needs current custody/configuration and the key profile, not a
 -- reconstruction/hash of the complete catalog bundle for every record.
 PERFORM truss.group_context(expected_release,expected_digest);
 IF (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='key_reuse') IS DISTINCT FROM '"forbid"'::jsonb OR (SELECT selected_setting.value FROM truss.setting selected_setting WHERE selected_setting.key='journal_mode') IS DISTINCT FROM '"engine"'::jsonb THEN
  RAISE EXCEPTION 'installed engine/forbid import policy required' USING ERRCODE='0A000';END IF;
 context:=truss.runtime_import_profiles();
 IF original_identity IS NULL OR octet_length(original_identity) NOT BETWEEN 1 AND 1048576
  OR (convert_from(original_identity,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN
  RAISE EXCEPTION 'bounded exact primary reference required' USING ERRCODE='22023';END IF;
 identity:=convert_from(original_identity,'UTF8')::jsonb;
 IF identity-ARRAY['operation','type','keyNumber','keyDefinitionPin','keyEncodingProfile','components']<>'{}'::jsonb
  OR identity->>'operation' IS DISTINCT FROM 'object_key'
  OR jsonb_typeof(identity->'components') IS DISTINCT FROM 'array'
  OR jsonb_typeof(identity->'type'->'typeId') IS DISTINCT FROM 'string'
  OR identity->'type'->>'typeId' !~ '^[1-9][0-9]{0,9}$'
  OR length(identity->'type'->>'typeId')=10 AND (identity->'type'->>'typeId') COLLATE "C">'2147483647' THEN
  RAISE EXCEPTION 'closed original primary reference required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT selected FROM truss.type_def WHERE type_id=(identity->'type'->>'typeId')::int
  AND kind='record' AND NOT provisional AND retired_rev IS NULL;
 SELECT * INTO STRICT key_row FROM truss.key_def WHERE type_id=selected.type_id AND is_primary AND retired_rev IS NULL;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',selected.type_id);
 IF identity->'type' IS DISTINCT FROM jsonb_build_object('typeId',selected.type_id::text,'definitionPin',pin.definition_pin,
    'owner',jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module))
  OR identity->>'keyNumber' IS DISTINCT FROM key_row.key_num::text
  OR identity->'keyEncodingProfile' IS DISTINCT FROM context->'importKeyProfile'
  OR jsonb_array_length(identity->'components') IS DISTINCT FROM cardinality(key_row.prop_ids) THEN
  RAISE EXCEPTION 'current qualified primary reference required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',selected.type_id,key_row.key_num);
 IF identity->>'keyDefinitionPin' IS DISTINCT FROM pin.definition_pin THEN
  RAISE EXCEPTION 'current original primary definition required' USING ERRCODE='22023';END IF;
 FOR component IN SELECT p.*,i.n FROM unnest(key_row.prop_ids) WITH ORDINALITY i(prop_id,n)
  JOIN truss.prop_def p ON p.type_id=selected.type_id AND p.prop_id=i.prop_id ORDER BY i.n LOOP
  supplied:=identity->'components'->(component.n::int-1);
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('property',selected.type_id,component.prop_id);
  IF supplied-ARRAY['propertyId','definitionPin','value']<>'{}'::jsonb
   OR supplied->>'propertyId' IS DISTINCT FROM component.prop_id::text
   OR supplied->>'definitionPin' IS DISTINCT FROM pin.definition_pin THEN
   RAISE EXCEPTION 'original ordered primary component required' USING ERRCODE='22023';END IF;
  values_buffer:=array_append(values_buffer,supplied->'value');
 END LOOP;
 values_json:=to_jsonb(values_buffer);
 found_bytes:=truss.lookup_string_key(selected.document_id,selected.module,selected.element,key_row.key_id,
  NULL,convert_to(values_json::text,'UTF8'),NULL,1048576,expected_release,expected_digest);
 IF found_bytes IS NULL THEN RETURN jsonb_build_object('identity',NULL,'keyIdentity',jsonb_build_array(selected.type_id,key_row.key_num,encode(truss.derive_catalog_key_tuple(selected.type_id,key_row.key_num,values_json),'hex'))::text);END IF;
 found_object:=convert_from(found_bytes,'UTF8')::jsonb;
 RETURN jsonb_build_object('identity',jsonb_build_object('id',found_object->>'id','typeId',found_object->>'typeId',
  'definitionPin',found_object->>'definitionPin','owner',identity->'type'->'owner'),
  'keyIdentity',jsonb_build_array(selected.type_id,key_row.key_num,encode(truss.derive_catalog_key_tuple(selected.type_id,key_row.key_num,values_json),'hex'))::text);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_input_scope(input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE operation jsonb;object_references jsonb;reference jsonb;identity jsonb;selected_operation jsonb;
 selected_ordinal int;selected_relation truss.rel_def%ROWTYPE;topology_batch boolean;has_edge_operations boolean;
 seeds jsonb;seed_items jsonb[]:='{}';seed jsonb;lean_nodes jsonb;lean_types jsonb;lean_order jsonb;lean_forest jsonb;lean_count int;stored_edge truss.edge%ROWTYPE;reference_type truss.type_def%ROWTYPE;current_actor oid;
 selected_edge_images jsonb[]:='{}';partial_scope jsonb;selected_edges jsonb;selected_relations jsonb;seed_types int[];
BEGIN
 IF jsonb_typeof(input->'operations') IS DISTINCT FROM 'array'
  OR jsonb_array_length(input->'operations') NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'bounded original operations required' USING ERRCODE='22023';END IF;
 FOR operation IN SELECT value FROM jsonb_array_elements(input->'operations') LOOP
  object_references:='[]';
  IF operation->>'operation' IN ('update_edge','delete_edge') THEN
   reference:=operation->'target';
   IF reference->>'state'='stored' THEN
    identity:=reference->'identity';
    SELECT * INTO stored_edge FROM truss.edge
     WHERE id=(identity->>'id')::bigint AND rel_type_id=(identity->>'typeId')::int;
    IF NOT FOUND THEN RAISE EXCEPTION 'target edge absent' USING ERRCODE='P1004';END IF;
    selected_edge_images:=array_append(selected_edge_images,jsonb_build_object('edge',to_jsonb(stored_edge)));
    -- Native witnesses stay separate from all caller-authored references.
    FOR seed IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
     jsonb_build_object('id',stored_edge.source_id::text,'typeId',stored_edge.source_type::text),
     jsonb_build_object('id',stored_edge.target_id::text,'typeId',stored_edge.target_type::text))) LOOP
     seed_items:=array_append(seed_items,seed);
    END LOOP;
   END IF;
  ELSIF operation->>'operation' IN ('update_object','delete_object') THEN
   object_references:=object_references||jsonb_build_array(operation->'target');
  END IF;
  IF operation->>'operation'='create_edge' THEN
   object_references:=object_references||jsonb_build_array(operation->'source',operation->'target');END IF;
  IF operation ? 'endpointChange' THEN
   object_references:=object_references||jsonb_build_array(operation->'endpointChange'->'source',operation->'endpointChange'->'target');END IF;
  IF operation->'ownership'->>'state'='owned' THEN
   object_references:=object_references||jsonb_build_array(operation->'ownership'->'root');END IF;
  IF operation->'ownershipChange'->>'state'='owned' THEN
   object_references:=object_references||jsonb_build_array(operation->'ownershipChange'->'root');END IF;
  FOR reference IN SELECT value FROM jsonb_array_elements(object_references) LOOP
   IF reference->>'state'='stored' THEN
    IF reference-ARRAY['state','identity']<>'{}'::jsonb THEN
     RAISE EXCEPTION 'closed caller object reference required' USING ERRCODE='22023';END IF;
    identity:=reference->'identity';reference_type:=truss.runtime_condition_type(identity);
    IF current_actor IS NULL THEN current_actor:=truss.runtime_person(false);END IF;
    IF NOT truss.runtime_can_read_qualified(reference_type.document_id,reference_type.module,current_actor) THEN
     RAISE EXCEPTION 'selected object reference reader required' USING ERRCODE='42501';END IF;
    IF NOT EXISTS(
     SELECT 1 FROM truss.object WHERE id=(identity->>'id')::bigint AND type_id=reference_type.type_id) THEN
     RAISE EXCEPTION 'target object absent' USING ERRCODE='P1004';END IF;
    seed:=jsonb_build_object('id',identity->'id','typeId',identity->'typeId');
    seed_items:=array_append(seed_items,seed);
   END IF;
  END LOOP;
 END LOOP;
 -- Deduplicate once, preserving the original first-discovery order. Every
 -- authored reference above is still independently validated and authorized.
 SELECT coalesce(jsonb_agg(seed_value ORDER BY first_ordinal),'[]'::jsonb) INTO seeds
 FROM (SELECT item seed_value,min(ordinality) first_ordinal
  FROM unnest(seed_items) WITH ORDINALITY entries(item,ordinality) GROUP BY item) distinct_seeds;
 SELECT coalesce(array_agg(DISTINCT (value->>'typeId')::int),'{}'::int[]) INTO seed_types
 FROM jsonb_array_elements(seeds);
 -- Topology-preserving groups retain the owned closure and exact selected
 -- independent edge beforeimages, omitting unrelated independent rows.
 SELECT coalesce(bool_and(CASE
   WHEN value->>'operation'='create_object' THEN value->'ownership'->>'state'='rootless'
     AND NOT (value ? 'ownershipChange')
   WHEN value->>'operation'='update_object' THEN NOT (value ? 'ownershipChange')
   WHEN value->>'operation' IN ('create_edge','update_edge','delete_edge') THEN true
   ELSE false END),false),
  coalesce(bool_or(value->>'operation' IN ('create_edge','update_edge','delete_edge')),false)
 INTO topology_batch,has_edge_operations FROM jsonb_array_elements(input->'operations');
 IF topology_batch AND has_edge_operations THEN
  FOR selected_operation,selected_ordinal IN
   SELECT selected.operation,selected.operation_ordinal FROM (
    SELECT DISTINCT ON (CASE WHEN o.value->>'operation'='create_edge'
      THEN o.value->>'relationshipDefinitionPin' ELSE o.value->'target'->'identity'->>'definitionPin' END)
     o.value operation,(o.ordinality-1)::int operation_ordinal,
     CASE WHEN o.value->>'operation'='create_edge'
      THEN o.value->>'relationshipDefinitionPin' ELSE o.value->'target'->'identity'->>'definitionPin' END pin
    FROM jsonb_array_elements(input->'operations') WITH ORDINALITY o(value,ordinality)
    WHERE o.value->>'operation'='create_edge'
     OR o.value->>'operation' IN ('update_edge','delete_edge') AND o.value->'target'->>'state'='stored'
    ORDER BY CASE WHEN o.value->>'operation'='create_edge'
      THEN o.value->>'relationshipDefinitionPin' ELSE o.value->'target'->'identity'->>'definitionPin' END,o.ordinality
   ) selected ORDER BY selected.operation_ordinal
  LOOP
   selected_relation:=truss.runtime_operation_relationship(selected_operation,input->'operations',selected_ordinal);
   IF selected_relation.lifecycle IS DISTINCT FROM 'independent' THEN
    topology_batch:=false;EXIT;
   END IF;
  END LOOP;
 END IF;
 IF topology_batch THEN
  IF NOT EXISTS(
    SELECT 1 FROM (
     SELECT seed_type.type_id FROM unnest(seed_types) seed_type(type_id)
      JOIN truss.rel_endpoint ep ON ep.source_type=seed_type.type_id
      JOIN truss.rel_def r USING(rel_type_id) WHERE r.retired_rev IS NULL AND r.lifecycle='owned'
     UNION ALL
     SELECT seed_type.type_id FROM unnest(seed_types) seed_type(type_id)
      JOIN truss.rel_endpoint ep ON ep.target_type=seed_type.type_id
      JOIN truss.rel_def r USING(rel_type_id) WHERE r.retired_rev IS NULL AND r.lifecycle='owned'
    ) seed_owned_relations)
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(seeds) s JOIN truss.object o
    ON o.id=(s.value->>'id')::bigint AND o.type_id=(s.value->>'typeId')::int
    WHERE o.root_id IS NOT NULL OR o.root_type IS NOT NULL) THEN
  SELECT count(*),coalesce(jsonb_agg(to_jsonb(o.type_id::text||':'||o.id::text) ORDER BY s.ordinality),'[]'::jsonb),
   coalesce(jsonb_object_agg(o.type_id::text||':'||o.id::text,to_jsonb(o)),'{}'::jsonb),
   coalesce(jsonb_object_agg(t.type_id::text,to_jsonb(t)),'{}'::jsonb),
   coalesce(jsonb_agg(jsonb_build_object('node',s.ordinality-1,'parent',NULL,'root',NULL,'incomingEdges','[]'::jsonb) ORDER BY s.ordinality),'[]'::jsonb)
   INTO lean_count,lean_order,lean_nodes,lean_types,lean_forest
   FROM jsonb_array_elements(seeds) WITH ORDINALITY s JOIN truss.object o
    ON o.id=(s.value->>'id')::bigint AND o.type_id=(s.value->>'typeId')::int
   JOIN truss.type_def t ON t.type_id=o.type_id;
  IF lean_count<>jsonb_array_length(seeds) OR lean_count>2048
   OR octet_length(lean_nodes::text)+octet_length(lean_types::text)>16777216 THEN
   RAISE EXCEPTION 'bounded complete explicit rootless rows required' USING ERRCODE='54000';END IF;
  partial_scope:=jsonb_build_object('catalogRevision',(SELECT rev FROM truss.schema_head WHERE id=1),
   'independentEndpointScope',true,'independentEdgesIncluded',false,
   'nodeOrder',lean_order,'ownedEdgeOrder','[]'::jsonb,'nodes',lean_nodes,'edges','{}'::jsonb,
   'types',lean_types,'relationships','{}'::jsonb,'boundary','{}'::jsonb,'forest',lean_forest);
  ELSE
   partial_scope:=truss.owned_graph_scope(seeds,false);
  END IF;
  IF cardinality(selected_edge_images)>0 THEN
   WITH selected AS MATERIALIZED (
    SELECT DISTINCT ON ((entry->'edge'->>'id')::bigint) entry->'edge' edge_image
    FROM unnest(selected_edge_images) entries(entry)
    ORDER BY (entry->'edge'->>'id')::bigint), maps AS MATERIALIZED (
    SELECT edge_image,r.rel_type_id::text rel_key,to_jsonb(r) relation_image
    FROM selected JOIN truss.rel_def r ON r.rel_type_id=(edge_image->>'rel_type_id')::int)
   SELECT coalesce((SELECT jsonb_object_agg(edge_image->>'id',edge_image) FROM maps), '{}'::jsonb),
    coalesce((SELECT jsonb_object_agg(rel_key,relation_image) FROM (SELECT DISTINCT ON (rel_key) rel_key,relation_image FROM maps ORDER BY rel_key) relations),'{}'::jsonb)
    INTO selected_edges,selected_relations;
   IF (SELECT count(*) FROM jsonb_each(partial_scope->'edges'))+
      (SELECT count(*) FROM jsonb_each(selected_edges))>1024 THEN
    RAISE EXCEPTION 'bounded complete ownership component required' USING ERRCODE='54000';END IF;
   partial_scope:=partial_scope||jsonb_build_object(
    'edges',(partial_scope->'edges')||selected_edges,
    'relationships',(partial_scope->'relationships')||selected_relations);
  END IF;
  IF octet_length(convert_to(partial_scope::text,'UTF8'))>(CASE WHEN partial_scope->'independentEndpointScope'='true'::jsonb THEN 16777216 ELSE 4194304 END) THEN
   RAISE EXCEPTION 'bounded complete graph image result required' USING ERRCODE='54000';END IF;
  RETURN partial_scope;
 END IF;
 -- The scope observer checks exact native ranges and complete membership.
 RETURN truss.owned_graph_scope(seeds,true);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_journal_materialize(entries jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE entry jsonb;physical truss.journal%ROWTYPE;resolved jsonb[]:='{}';
BEGIN
 IF jsonb_typeof(entries) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'original transition journal array required' USING ERRCODE='55000';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
  IF entry ? 'referenceProfile' THEN
   IF entry->>'referenceProfile' IS DISTINCT FROM 'truss-native-journal-reference/0.1'
    OR jsonb_typeof(entry->'at') IS DISTINCT FROM 'string'
    OR jsonb_typeof(entry->'seq') IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION 'original typed journal reference required' USING ERRCODE='55000';END IF;
   BEGIN
    SELECT * INTO physical FROM truss.journal j WHERE j.at=(entry->>'at')::timestamptz AND j.seq=(entry->>'seq')::bigint;
   EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'original typed journal reference required' USING ERRCODE='55000';
   END;
   IF NOT FOUND THEN RAISE EXCEPTION 'retained physical history unavailable' USING ERRCODE='P1010';END IF;
   IF entry IS DISTINCT FROM truss.runtime_owned_journal_reference(physical) THEN
    RAISE EXCEPTION 'exact original journal reference required' USING ERRCODE='55000';END IF;
   resolved:=array_append(resolved,to_jsonb(physical));
  ELSE resolved:=array_append(resolved,entry);END IF;
 END LOOP;
 RETURN to_jsonb(resolved);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_key_codec_metadata(selected_type integer, selected_key smallint, planned_basis jsonb DEFAULT NULL::jsonb, checked_cells jsonb DEFAULT NULL::jsonb, require_cells boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE definition truss.key_def%ROWTYPE;owner truss.type_def%ROWTYPE;property truss.prop_def%ROWTYPE;archive truss.schema_doc%ROWTYPE;
 record_source jsonb;key_source jsonb;field_source jsonb;reference jsonb;facets jsonb:='[]';fields jsonb:='[]';component int;position int:=0;compiled jsonb;
BEGIN
 IF planned_basis IS NULL THEN
  SELECT * INTO STRICT owner FROM truss.type_def WHERE type_id=selected_type AND kind='record' AND NOT provisional AND retired_rev IS NULL;
  SELECT * INTO STRICT definition FROM truss.key_def WHERE type_id=selected_type AND key_num=selected_key AND retired_rev IS NULL;
  -- Current immutable metadata was compiled once from the same original
  -- latest-document key/Field objects. Native identity and current key checks
  -- above remain live; old installations and planned catalogs use the original
  -- source reconstruction below.
  SELECT s.metadata->'keyCodecs'->selected_key::text INTO compiled FROM truss.runtime_type_schema s
   WHERE s.rev=(SELECT rev FROM truss.schema_head WHERE id=1) AND s.type_id=selected_type
    AND NOT EXISTS(SELECT 1 FROM truss.schema_rev newer WHERE newer.rev>s.rev);
  IF compiled IS NOT NULL THEN
   IF require_cells AND (jsonb_typeof(checked_cells) IS DISTINCT FROM 'array'
    OR jsonb_array_length(checked_cells)<>cardinality(definition.prop_ids)) THEN
    RAISE EXCEPTION 'qualified ordered key definition required' USING ERRCODE='22023';END IF;
   RETURN compiled;
  END IF;
  SELECT * INTO STRICT archive FROM truss.schema_doc WHERE doc_id=owner.document_id ORDER BY rev DESC LIMIT 1;
 ELSE
  SELECT * INTO STRICT owner FROM jsonb_populate_recordset(NULL::truss.type_def,planned_basis->'type_def') t WHERE t.type_id=selected_type;
  SELECT * INTO STRICT definition FROM jsonb_populate_recordset(NULL::truss.key_def,planned_basis->'key_def') k WHERE k.type_id=selected_type AND k.key_num=selected_key;
  SELECT * INTO STRICT archive FROM jsonb_populate_recordset(NULL::truss.schema_doc,planned_basis->'schema_doc') d WHERE d.doc_id=owner.document_id ORDER BY d.rev DESC LIMIT 1;
 END IF;
 SELECT e.value INTO STRICT record_source FROM jsonb_array_elements(archive.document::jsonb->'modules') m
  CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') e WHERE m.value->>'id'=owner.module AND e.value->>'id'=owner.element;
 SELECT value INTO STRICT key_source FROM jsonb_array_elements(record_source->'keys') WHERE value->>'id'=definition.key_id;
 IF key_source-ARRAY['id','name','fields','primary']<>'{}'::jsonb OR jsonb_array_length(key_source->'fields')<>cardinality(definition.prop_ids)
  OR require_cells AND (jsonb_typeof(checked_cells) IS DISTINCT FROM 'array' OR jsonb_array_length(checked_cells)<>cardinality(definition.prop_ids)) THEN
  RAISE EXCEPTION 'qualified ordered key definition required' USING ERRCODE='22023';END IF;
 FOREACH component IN ARRAY definition.prop_ids LOOP
  IF planned_basis IS NULL THEN SELECT * INTO STRICT property FROM truss.prop_def WHERE type_id=selected_type AND prop_id=component AND retired_rev IS NULL;
  ELSE SELECT * INTO STRICT property FROM jsonb_populate_recordset(NULL::truss.prop_def,planned_basis->'prop_def') p WHERE p.type_id=selected_type AND p.prop_id=component;END IF;
  reference:=jsonb_build_object('module',property.declaration_module,'element',property.element);
  IF key_source->'fields'->position IS DISTINCT FROM reference OR NOT record_source->'members' @> jsonb_build_array(reference) THEN
   RAISE EXCEPTION 'original key component references required' USING ERRCODE='0A000';END IF;
  SELECT e.value INTO STRICT field_source FROM jsonb_array_elements(archive.document::jsonb->'modules') m
   CROSS JOIN LATERAL jsonb_array_elements(m.value->'elements') e WHERE m.value->>'id'=property.declaration_module AND e.value->>'id'=property.element;
  IF field_source->>'scalarType' IS DISTINCT FROM property.scalar_type OR coalesce(field_source->'facets','{}') IS DISTINCT FROM coalesce(property.facets,'{}') THEN
   RAISE EXCEPTION 'native key domain must match accepted source' USING ERRCODE='55000';END IF;
  facets:=facets||jsonb_build_array(coalesce(property.facets,'{}'));fields:=fields||jsonb_build_array(field_source);position:=position+1;
 END LOOP;
 RETURN jsonb_build_object('profile','truss-native-key-codec-metadata/0.1','typeId',selected_type::text,'keyNumber',selected_key::text,
  'fields',fields,'facets',facets,'umfVersion',archive.umf_version);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_key_preflight(inventory jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;candidate jsonb;definition truss.key_def%ROWTYPE;
 component int;cells jsonb;before_cells jsonb;tuple_bytes bytea;namespace bytea;transport bytea;pin record;
 routes jsonb:='[]';lock_routes jsonb:='[]';entry jsonb;route record;observed record;member truss.object_key_bucket%ROWTYPE;
 reference text;unchanged boolean;
 namespaces jsonb:='{}';namespace_key text;namespace_hex text;codecs jsonb:='{}';codec jsonb;codec_bytes bigint:=2;
 route_items jsonb[]:='{}';lock_route_items jsonb[]:='{}';route_bytes bigint:=2;lock_route_bytes bigint:=2;
 metadata_keys text[]:='{}';namespace_values text[]:='{}';codec_keys text[]:='{}';codec_values jsonb[]:='{}';
 all_routes jsonb;route_observations jsonb;
BEGIN
 IF inventory->>'profile' IS DISTINCT FROM 'truss-owned-group-plan/0.1'
  OR (inventory->>'catalogRevision')::int IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1)
  OR (SELECT value FROM truss.setting WHERE key='key_reuse') IS DISTINCT FROM '"forbid"'::jsonb THEN
  RAISE EXCEPTION 'original current forbid-reuse inventory required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 -- Build immutable key metadata maps once per distinct selected type/key.
 -- Their entries do not depend on record values or authorization decisions.
 FOR definition IN
  WITH selected_types AS (
   SELECT DISTINCT (n.value->>'type_id')::int type_id FROM jsonb_each(inventory->'initialScope'->'nodes') n
   UNION SELECT (n.value->'image'->>'type_id')::int FROM jsonb_array_elements(inventory->'operations') p
    CROSS JOIN LATERAL jsonb_each(p.value->'afterNodes') n)
  SELECT k.* FROM selected_types t JOIN truss.key_def k USING(type_id) WHERE k.retired_rev IS NULL ORDER BY k.type_id,k.key_num
 LOOP
  namespace_key:=definition.type_id::text||':'||definition.key_num::text;
  codec:=truss.runtime_owned_key_codec_metadata(definition.type_id,definition.key_num);
  IF codec_bytes+octet_length(convert_to(codec::text,'UTF8'))+octet_length(namespace_key)+8<=4194304 THEN
   codec_keys[cardinality(codec_keys)+1]:=namespace_key;codec_values[cardinality(codec_values)+1]:=codec;
   codec_bytes:=codec_bytes+octet_length(convert_to(codec::text,'UTF8'))+octet_length(namespace_key)+8;
  END IF;
  SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('key',definition.type_id,definition.key_num);
  namespace:=convert_to(jsonb_build_object('profile','truss-string-key-namespace/0.2','installationId',installation.installation_id::text,
   'sourceEpoch',installation.source_epoch::text,'typeId',definition.type_id::text,'keyNumber',definition.key_num::text,
   'definitionPin',pin.definition_pin,'encoding','umf-key-tuple-v1')::text,'UTF8');
  metadata_keys[cardinality(metadata_keys)+1]:=namespace_key;namespace_values[cardinality(namespace_values)+1]:=encode(namespace,'hex');
 END LOOP;
 SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) INTO codecs FROM unnest(codec_keys,codec_values) m(key,value);
 SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) INTO namespaces FROM unnest(metadata_keys,namespace_values) m(key,value);
 FOR candidate IN SELECT value FROM (
  SELECT -1 ordinal,n.key reference,jsonb_build_object('phase','initial','reference','stored:'||n.key,'image',n.value) value
   FROM jsonb_each(inventory->'initialScope'->'nodes') n
  UNION ALL SELECT (p.value->>'operationIndex')::int,n.key,jsonb_build_object('phase','after','operationIndex',(p.value->>'operationIndex')::int,'reference',n.key,
   'image',n.value->'image','before',p.value->'beforeNodes'->n.key->'image')
   FROM jsonb_array_elements(inventory->'operations') p CROSS JOIN LATERAL jsonb_each(p.value->'afterNodes') n
   WHERE n.value->'deleted'='false'::jsonb AND n.value IS DISTINCT FROM p.value->'beforeNodes'->n.key
 ) candidates ORDER BY candidates.ordinal,candidates.reference COLLATE "C" LOOP
  FOR definition IN SELECT k.* FROM truss.key_def k WHERE k.type_id=(candidate->'image'->>'type_id')::int AND k.retired_rev IS NULL ORDER BY k.key_num LOOP
   SELECT jsonb_agg(candidate->'image'->'props'->i.prop_id::text ORDER BY i.ordinal),
    jsonb_agg(candidate->'before'->'props'->i.prop_id::text ORDER BY i.ordinal)
   INTO cells,before_cells FROM unnest(definition.prop_ids) WITH ORDINALITY i(prop_id,ordinal);
   namespace_key:=definition.type_id::text||':'||definition.key_num::text;
   codec:=coalesce(codecs->namespace_key,truss.runtime_owned_key_codec_metadata(definition.type_id,definition.key_num));
   tuple_bytes:=truss.runtime_owned_key_tuple_in_metadata(definition.type_id,definition.key_num,cells,codec);
   namespace:=decode(namespaces->>namespace_key,'hex');
   transport:=convert_to('umf-key-tuple-v1:hex:'||encode(tuple_bytes,'hex'),'UTF8');
   entry:=jsonb_build_object('phase',candidate->>'phase','operationIndex',candidate->'operationIndex','reference',candidate->>'reference',
    'objectId',candidate->'image'->>'id','typeId',definition.type_id,'keyNumber',definition.key_num,
    'namespace',encode(namespace,'hex'),'transport',encode(transport,'hex'),'tuple',encode(tuple_bytes,'hex'),
    -- Identical cells have already passed this exact derivation above.
    -- Keep the original before-image condition and derive unequal cells so
    -- canonical equivalence and invalid prior values retain their behavior.
    'unchanged',CASE WHEN candidate->'before' IS NOT NULL AND candidate->'before'<>'null'::jsonb
     THEN CASE WHEN before_cells=cells THEN true
      ELSE truss.runtime_owned_key_tuple_in_metadata(definition.type_id,definition.key_num,before_cells,codec)=tuple_bytes END
     ELSE false END);
   route_bytes:=route_bytes+octet_length(convert_to(entry::text,'UTF8'))+CASE WHEN cardinality(route_items)=0 THEN 0 ELSE 2 END;
   route_items:=array_append(route_items,entry);
   IF cardinality(route_items)>16384 OR route_bytes>16777216 THEN
    RAISE EXCEPTION 'bounded whole-group key footprint required' USING ERRCODE='54000';END IF;
  END LOOP;
 END LOOP;
 -- Retired definitions may still have original live memberships. Deletion
 -- touches these bytes too; include them without reinterpreting retired keys.
 FOR member IN
  WITH planned_routes AS MATERIALIZED (
   SELECT DISTINCT decode(r.value->>'namespace','hex') AS namespace_bytes,
    decode(r.value->>'transport','hex') AS key_bytes FROM unnest(route_items) r(value))
  SELECT k.* FROM truss.object_key_bucket k JOIN jsonb_each(inventory->'initialScope'->'nodes') n
   ON k.object_id=(n.value->>'id')::bigint AND k.type_id=(n.value->>'type_id')::int
  LEFT JOIN planned_routes p ON p.namespace_bytes=k.namespace_bytes AND p.key_bytes=k.key_bytes
  WHERE p.namespace_bytes IS NULL LOOP
  entry:=jsonb_build_object('namespace',encode(member.namespace_bytes,'hex'),'transport',encode(member.key_bytes,'hex'));
  lock_route_bytes:=lock_route_bytes+octet_length(convert_to(entry::text,'UTF8'))+CASE WHEN cardinality(lock_route_items)=0 THEN 0 ELSE 2 END;
  lock_route_items:=array_append(lock_route_items,entry);
  IF cardinality(lock_route_items)+cardinality(route_items)>16384 OR lock_route_bytes+route_bytes>16777216 THEN
   RAISE EXCEPTION 'bounded whole-group key footprint required' USING ERRCODE='54000';END IF;
 END LOOP;
 IF cardinality(lock_route_items)+cardinality(route_items)>16384 OR lock_route_bytes+route_bytes>16777216 THEN
  RAISE EXCEPTION 'bounded whole-group key footprint required' USING ERRCODE='54000';END IF;
 routes:=to_jsonb(route_items);lock_routes:=to_jsonb(lock_route_items);all_routes:=routes||lock_routes;
 -- The admitted entry holds the transaction-wide graph-writer gate. Scalar
 -- callers use that same gate; no second key-row lock pass is necessary.
 IF jsonb_array_length(all_routes)>0 THEN
  IF current_setting('transaction_isolation')<>'read committed' THEN
   RAISE EXCEPTION 'current key observation requires READ COMMITTED' USING ERRCODE='0A000';END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(all_routes) r
  WHERE octet_length(decode(r.value->>'namespace','hex')) NOT BETWEEN 1 AND 65536
   OR octet_length(decode(r.value->>'transport','hex')) NOT BETWEEN 1 AND 1048576
   OR convert_from(decode(r.value->>'transport','hex'),'UTF8') !~ '^umf-key-tuple-v1:hex:([0-9a-f]{2})+$') THEN
  RAISE EXCEPTION 'bounded original key routing bytes required' USING ERRCODE='22023';END IF;
 -- Build the distinct exact routes once. Creating absent zero-generation rows
 -- setwise is safe under the graph gate; the ordered guard read below verifies
 -- every route and takes each row lock exactly once.
 WITH exact_routes AS MATERIALIZED (
  SELECT DISTINCT decode(value->>'namespace','hex') namespace_bytes,decode(value->>'transport','hex') key_bytes
  FROM jsonb_array_elements(all_routes)), hashes AS MATERIALIZED (
  SELECT DISTINCT sha256(namespace_bytes) namespace_sha256,sha256(key_bytes) key_sha256 FROM exact_routes)
 INSERT INTO truss.key_bucket_guard(namespace_sha256,key_sha256,generation)
 SELECT h.namespace_sha256,h.key_sha256,0 FROM hashes h
 LEFT JOIN truss.key_bucket_guard g USING(namespace_sha256,key_sha256)
 WHERE g.namespace_sha256 IS NULL ORDER BY h.namespace_sha256,h.key_sha256
 ON CONFLICT(namespace_sha256,key_sha256) DO NOTHING;
 -- Generations below come from canonical indexed guard rows. Actual guard
 -- UPDATE statements acquire their own row locks under the held writer gate.
 -- One bounded scan per hash bucket computes collision-budget statistics;
 -- exact byte membership is aggregated separately for each original route.
 WITH exact_routes AS MATERIALIZED (
  SELECT DISTINCT decode(value->>'namespace','hex') namespace_bytes,decode(value->>'transport','hex') key_bytes
  FROM jsonb_array_elements(all_routes)), hashes AS MATERIALIZED (
  SELECT DISTINCT sha256(namespace_bytes) namespace_sha256,sha256(key_bytes) key_sha256 FROM exact_routes),
 stats AS MATERIALIZED (
  SELECT h.namespace_sha256,h.key_sha256,b.candidate_count,b.candidate_bytes
  FROM hashes h CROSS JOIN LATERAL (
   SELECT count(*) candidate_count,coalesce(sum(c.size),0) candidate_bytes FROM (
    (SELECT octet_length(g.namespace_bytes)::bigint+octet_length(g.key_bytes) size
     FROM truss.object_key_bucket g WHERE g.namespace_sha256=h.namespace_sha256 AND g.key_sha256=h.key_sha256 LIMIT 10001)
    UNION ALL
    (SELECT octet_length(g.namespace_bytes)::bigint+octet_length(g.key_bytes) size
     FROM truss.object_key_reservation_bucket g WHERE g.namespace_sha256=h.namespace_sha256 AND g.key_sha256=h.key_sha256 LIMIT 10001)
   ) c
  ) b),
 observed_routes AS (
  SELECT r.namespace_bytes,r.key_bytes,g.generation,s.candidate_count,s.candidate_bytes,
   m.member_rows,q.reservation_ids
  FROM exact_routes r JOIN stats s ON s.namespace_sha256=sha256(r.namespace_bytes)
   AND s.key_sha256=sha256(r.key_bytes)
  JOIN truss.key_bucket_guard g USING(namespace_sha256,key_sha256)
  -- Each aggregate is an indexed lookup for this exact route. Global grouped
  -- subqueries here can be reexecuted for each route when planner estimates
  -- for the JSON input are small, producing route-count-squared work.
  CROSS JOIN LATERAL (
   SELECT coalesce(jsonb_agg(jsonb_build_object('storage_row_id',m.storage_row_id,
    'object_id',m.object_id,'type_id',m.type_id,'key_num',m.key_num,
    'namespaceExact',true,'keyExact',true) ORDER BY m.storage_row_id),'[]'::jsonb) member_rows
   FROM truss.object_key_bucket m WHERE m.namespace_sha256=s.namespace_sha256
    AND m.key_sha256=s.key_sha256 AND m.namespace_bytes=r.namespace_bytes AND m.key_bytes=r.key_bytes
    AND s.candidate_count<=10000 AND s.candidate_bytes<=16777216
  ) m CROSS JOIN LATERAL (
   SELECT coalesce(jsonb_agg(q.storage_row_id ORDER BY q.storage_row_id),'[]'::jsonb) reservation_ids
   FROM truss.object_key_reservation_bucket q WHERE q.namespace_sha256=s.namespace_sha256
    AND q.key_sha256=s.key_sha256 AND q.namespace_bytes=r.namespace_bytes AND q.key_bytes=r.key_bytes
    AND s.candidate_count<=10000 AND s.candidate_bytes<=16777216
  ) q)
 SELECT coalesce(jsonb_object_agg(encode(namespace_bytes,'hex')||':'||encode(key_bytes,'hex'),
  jsonb_build_object('generation',generation,'candidateCount',candidate_count,'candidateBytes',candidate_bytes,
  'memberRows',coalesce(member_rows,'[]'::jsonb),'reservationIds',coalesce(reservation_ids,'[]'::jsonb))),'{}'::jsonb)
 INTO route_observations FROM observed_routes;
 -- Retired live memberships are locked/checked before current active routes,
 -- matching the former two-phase ordering. Their bytes are not reinterpreted.
 FOR route IN SELECT DISTINCT ON ((r.value->>'namespace') COLLATE "C",(r.value->>'transport') COLLATE "C") r.value entry,route_observations->((r.value->>'namespace')||':'||(r.value->>'transport')) observation
  FROM jsonb_array_elements(lock_routes) r
  ORDER BY (r.value->>'namespace') COLLATE "C",(r.value->>'transport') COLLATE "C" LOOP
  IF (route.observation->>'candidateCount')::bigint>10000 OR (route.observation->>'candidateBytes')::bigint>16777216 THEN
   RAISE EXCEPTION 'complete collision bucket exceeds limits' USING ERRCODE='54000';END IF;
  IF (route.observation->>'generation')::bigint=9223372036854775807 THEN
   RAISE EXCEPTION 'key guard generation exhausted' USING ERRCODE='54000';END IF;
 END LOOP;
 -- Preserve operation-order error selection while all exact bucket observations
 -- and guard locks are shared by every repeated route.
 FOR route IN SELECT r.value entry,
  lag(r.value->>'reference') OVER route_history previous_reference,
  lag(r.ordinality) OVER route_history previous_ordinal,
  route_observations->((r.value->>'namespace')||':'||(r.value->>'transport')) observation
  FROM jsonb_array_elements(routes) WITH ORDINALITY r(value,ordinality)
  WINDOW route_history AS (PARTITION BY (r.value->>'namespace') COLLATE "C",(r.value->>'transport') COLLATE "C" ORDER BY r.ordinality)
  ORDER BY r.ordinality LOOP
  entry:=route.entry;namespace:=decode(entry->>'namespace','hex');transport:=decode(entry->>'transport','hex');reference:=entry->>'reference';
  IF (route.observation->>'candidateCount')::bigint>10000 OR (route.observation->>'candidateBytes')::bigint>16777216 THEN
   RAISE EXCEPTION 'complete collision bucket exceeds limits' USING ERRCODE='54000';END IF;
  IF (route.observation->>'generation')::bigint=9223372036854775807 THEN
   RAISE EXCEPTION 'key guard generation exhausted' USING ERRCODE='54000';END IF;
  IF entry->>'phase'='initial' THEN
   IF jsonb_array_length(route.observation->'memberRows')<>1 THEN RAISE EXCEPTION 'one original live key member required' USING ERRCODE='55000';END IF;
   member:=jsonb_populate_record(NULL::truss.object_key_bucket,route.observation->'memberRows'->0);
   IF member.object_id::text IS DISTINCT FROM entry->>'objectId' OR member.type_id IS DISTINCT FROM (entry->>'typeId')::int
    OR member.key_num IS DISTINCT FROM (entry->>'keyNumber')::smallint
    OR route.observation->'memberRows'->0->>'namespaceExact' IS DISTINCT FROM 'true'
    OR route.observation->'memberRows'->0->>'keyExact' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'original key membership and values required' USING ERRCODE='55000';END IF;
  ELSIF entry->'unchanged'='true'::jsonb THEN
   IF route.previous_reference IS DISTINCT FROM reference THEN RAISE EXCEPTION 'original unchanged key owner required' USING ERRCODE='55000';END IF;
  ELSE
   IF route.previous_ordinal IS NOT NULL OR jsonb_array_length(route.observation->'memberRows')>0
    OR jsonb_array_length(route.observation->'reservationIds')>0 THEN
    RAISE EXCEPTION 'key already allocated or reserved' USING ERRCODE='23505',
     DETAIL=jsonb_build_object('operationIndex',entry->'operationIndex')::text;END IF;
  END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_object_effect(selected_attempt uuid, selected_index integer, reference text, prepared_input jsonb DEFAULT NULL::jsonb, qualified_actor oid DEFAULT NULL::oid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;plan jsonb;input jsonb;prior jsonb;desired jsonb;identity jsonb;
 object_row truss.object%ROWTYPE;old_image jsonb;new_image jsonb;expected_image jsonb;before_record jsonb;after_record jsonb;
 installation truss.catalog_runtime_installation%ROWTYPE;property truss.prop_def%ROWTYPE;pin record;changed_rows bigint;
 events jsonb:='[]';event_refs jsonb:='[]';journals jsonb:='[]';base_events jsonb[]:='{}'::jsonb[];final_events jsonb[]:='{}'::jsonb[];
 journal_items jsonb[]:='{}'::jsonb[];event_ref_items jsonb[]:='{}'::jsonb[];event jsonb;entry record;journal truss.journal%ROWTYPE;
 keys jsonb;version bigint;revision int;event_digest text;ordinal int;mode text;result jsonb;current_actor oid;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() THEN
  RAISE EXCEPTION 'current original object effect required' USING ERRCODE='55000';END IF;
 current_actor:=coalesce(qualified_actor,truss.runtime_person(false));
 IF attempt.actor_oid IS DISTINCT FROM current_actor
  OR attempt.complete OR attempt.next_index IS DISTINCT FROM selected_index THEN
  RAISE EXCEPTION 'current original object effect required' USING ERRCODE='55000';END IF;
 plan:=truss.runtime_owned_plan(selected_attempt,selected_index);
 input:=CASE WHEN attempt.context ? 'originalAssertedOrigin' THEN jsonb_build_object('assertedOrigin',attempt.context->'originalAssertedOrigin')
  ELSE coalesce(prepared_input,convert_from(attempt.input_bytes,'UTF8')::jsonb) END;
 prior:=plan->'beforeNodes'->reference;desired:=plan->'afterNodes'->reference;mode:=plan->'operation'->>'operation';
 IF mode NOT IN ('update_object','delete_object') OR prior IS NULL OR desired IS NULL OR prior->'deleted'='true'::jsonb
  OR (mode='update_object' AND desired->'deleted'='true'::jsonb)
  OR (mode='delete_object' AND desired->'deleted' IS DISTINCT FROM 'true'::jsonb)
  OR (reference IS DISTINCT FROM plan->>'primary' AND prior IS NOT DISTINCT FROM desired) THEN
  RAISE EXCEPTION 'original primary or affected descendant required' USING ERRCODE='55000';END IF;
 identity:=truss.runtime_owned_identity(selected_attempt,selected_index,reference,'object',plan,attempt);
 PERFORM truss.runtime_module_writer_qualified(identity->'owner'->>'documentId',identity->'owner'->>'moduleId',current_actor);
 IF NOT truss.runtime_object_values_readable_qualified((identity->>'typeId')::int,current_actor) THEN RAISE EXCEPTION 'current original property/item readers required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT object_row FROM truss.object WHERE id=(identity->>'id')::bigint AND type_id=(identity->>'typeId')::int FOR UPDATE NOWAIT;
 old_image:=to_jsonb(object_row);
 IF old_image->>'ver' IS DISTINCT FROM prior->'image'->>'ver' THEN
  RAISE EXCEPTION 'original planned object version required' USING ERRCODE='55000';END IF;
 IF prior IS NOT DISTINCT FROM desired THEN
  RETURN jsonb_build_object('outcome','unchanged','operation','update_object','identity',identity,'version',object_row.ver::text,'events','[]'::jsonb);
 END IF;
 IF object_row.ver=9223372036854775807 THEN RAISE EXCEPTION 'record version exhausted' USING ERRCODE='54000';END IF;
 version:=object_row.ver+1;revision:=(plan->>'catalogRevision')::int;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 before_record:=truss.runtime_object_history(old_image,identity);
 IF mode='update_object' THEN
  expected_image:=truss.runtime_owned_object_image(selected_attempt,selected_index,reference,'after',plan,attempt);
  IF expected_image->>'ver' IS DISTINCT FROM version::text THEN RAISE EXCEPTION 'one original version advance required' USING ERRCODE='55000';END IF;
  IF object_row.props IS DISTINCT FROM expected_image->'props' THEN
   PERFORM truss.runtime_object_update_keys(object_row.id,object_row.type_id,expected_image->'props',convert_to('[]','UTF8'),selected_attempt,selected_index);
  END IF;
  object_row.props:=expected_image->'props';object_row.retained:=nullif(expected_image->'retained','null'::jsonb);
  object_row.root_id:=(expected_image->>'root_id')::bigint;object_row.root_type:=(expected_image->>'root_type')::int;
  object_row.rev:=revision;object_row.ver:=version;object_row.updated_at:=clock_timestamp();
  UPDATE truss.object SET props=object_row.props,retained=object_row.retained,root_id=object_row.root_id,root_type=object_row.root_type,
   rev=object_row.rev,ver=object_row.ver,updated_at=object_row.updated_at
   WHERE id=object_row.id AND type_id=object_row.type_id AND ver=(old_image->>'ver')::bigint
   RETURNING to_jsonb(object) INTO new_image;
  GET DIAGNOSTICS changed_rows=ROW_COUNT;
  IF changed_rows<>1 THEN RAISE EXCEPTION 'original planned object update required' USING ERRCODE='55000';END IF;
  after_record:=truss.runtime_object_history(new_image,identity);
  FOR property IN SELECT * FROM truss.prop_def WHERE type_id=object_row.type_id AND retired_rev IS NULL ORDER BY prop_id LOOP
   IF old_image->'props'->property.prop_id::text IS DISTINCT FROM new_image->'props'->property.prop_id::text THEN
    SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('property',object_row.type_id,property.prop_id);
    base_events[cardinality(base_events)+1]:=jsonb_build_object('operation','property','propertyId',property.prop_id::text,'definitionPin',pin.definition_pin,
     'before',CASE WHEN old_image->'props' ? property.prop_id::text THEN jsonb_build_object('present',true,'value',old_image->'props'->property.prop_id::text) ELSE '{"present":false}'::jsonb END,
     'after',CASE WHEN new_image->'props' ? property.prop_id::text THEN jsonb_build_object('present',true,'value',new_image->'props'->property.prop_id::text) ELSE '{"present":false}'::jsonb END);
   END IF;
  END LOOP;
  base_events[cardinality(base_events)+1]:=jsonb_build_object('operation','metadata','before',before_record,'after',after_record);
 ELSE
  FOR entry IN SELECT k.namespace_bytes,k.key_bytes,k.namespace_sha256,k.key_sha256 FROM truss.object_key_bucket k
   WHERE k.object_id=object_row.id AND k.type_id=object_row.type_id ORDER BY k.namespace_bytes,k.key_bytes LOOP
   PERFORM truss.lock_string_key_bucket(entry.namespace_bytes,entry.key_bytes);
   UPDATE truss.key_bucket_guard SET generation=generation+1 WHERE namespace_sha256=entry.namespace_sha256 AND key_sha256=entry.key_sha256;
  END LOOP;
  DELETE FROM truss.object WHERE id=object_row.id AND type_id=object_row.type_id AND ver=(old_image->>'ver')::bigint;
  GET DIAGNOSTICS changed_rows=ROW_COUNT;
  IF changed_rows<>1 THEN RAISE EXCEPTION 'original planned deletion required' USING ERRCODE='55000';END IF;
  base_events[cardinality(base_events)+1]:=jsonb_build_object('operation','delete','before',before_record);
 END IF;
 FOR ordinal IN 1..cardinality(base_events) LOOP
  event:=base_events[ordinal];event:=event||jsonb_build_object('interfaceVersion','truss-history-event/0.2.0-proposal','sourceEpoch',installation.source_epoch::text,
   'historyProfile','truss-native-owned-mutation/0.1','xid',attempt.writer_xid::text,'seq',nextval('truss.journal_seq')::text,
   'identity',identity,'eventVersion',version::text,'eventCatalogRevision',revision::text,
   'origin',jsonb_build_object('asserted',input->'assertedOrigin','databaseRole',session_user::text));
  final_events[cardinality(final_events)+1]:=event;
 END LOOP;
 SELECT coalesce(jsonb_agg(item.value ORDER BY item.ordinality),'[]'::jsonb) INTO events
  FROM unnest(final_events) WITH ORDINALITY AS item(value,ordinality);
 event_digest:=encode(sha256(convert_to(events::text,'UTF8')),'hex');
 FOREACH event IN ARRAY final_events LOOP
  event:=event||jsonb_build_object('mutationGroup',jsonb_build_object('profile','truss-history-group/0.1.0','eventCount',jsonb_array_length(events)::text,'orderedEventDigest',event_digest));
  journal.seq:=(event->>'seq')::bigint;journal.at:=clock_timestamp();journal.xid:=attempt.writer_xid;journal.entity_kind:='o';journal.entity_id:=object_row.id;journal.entity_type:=object_row.type_id;
  journal.ver:=version;journal.op:=CASE event->>'operation' WHEN 'property' THEN 'update' ELSE event->>'operation' END;journal.prop_id:=(event->>'propertyId')::int;
  journal.old_value:=NULL;journal.new_value:=truss.runtime_exact_wrapper('event',convert_to(event::text,'UTF8'));journal.rev:=revision;
  journal.origin:=truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8'));
  INSERT INTO truss.journal SELECT (journal).*;
  journal_items[cardinality(journal_items)+1]:=to_jsonb(journal);
  event_ref_items[cardinality(event_ref_items)+1]:=jsonb_build_object('sourceEpoch',installation.source_epoch::text,'historyProfile','truss-native-owned-mutation/0.1','xid',attempt.writer_xid::text,'seq',journal.seq::text);
 END LOOP;
 SELECT coalesce(jsonb_agg(item.value ORDER BY item.ordinality),'[]'::jsonb) INTO journals
  FROM unnest(journal_items) WITH ORDINALITY AS item(value,ordinality);
 SELECT coalesce(jsonb_agg(item.value ORDER BY item.ordinality),'[]'::jsonb) INTO event_refs
  FROM unnest(event_ref_items) WITH ORDINALITY AS item(value,ordinality);
 -- Physical key rows are canonical; no duplicate expected-key image is retained.
 keys:='[]'::jsonb;
 INSERT INTO truss.runtime_object_transition(attempt_id,operation_index,writer_xid,object_id,type_id,before_object,after_object,after_keys,journal)
 VALUES(selected_attempt,selected_index,attempt.writer_xid,object_row.id,object_row.type_id,old_image,new_image,keys,journals);
 current_actor:=truss.runtime_person(false);
 PERFORM truss.runtime_module_writer_qualified(identity->'owner'->>'documentId',identity->'owner'->>'moduleId',current_actor);
 IF NOT truss.runtime_object_values_readable_qualified((identity->>'typeId')::int,current_actor) THEN RAISE EXCEPTION 'current final property/item readers required' USING ERRCODE='42501';END IF;
 IF mode='update_object' THEN RETURN jsonb_build_object('outcome','changed','operation','update_object','identity',identity,'version',version::text,'events',event_refs);END IF;
 RETURN jsonb_build_object('outcome','deleted','operation','delete_object','identity',identity,'deletionVersion',version::text,
  'deleted',jsonb_build_array(jsonb_build_object('identity',identity,'deletionVersion',version::text)),'events',event_refs);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_object_image(selected_attempt uuid, selected_index integer, reference text, phase text, prepared_plan jsonb DEFAULT NULL::jsonb, prepared_attempt truss.runtime_object_attempt DEFAULT NULL::truss.runtime_object_attempt)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE plan jsonb;state jsonb;identity jsonb;root_identity jsonb;root_reference text;
BEGIN
 IF phase IS NULL OR phase NOT IN ('before','after') THEN RAISE EXCEPTION 'explicit image phase required' USING ERRCODE='55000';END IF;
 plan:=coalesce(prepared_plan,truss.runtime_owned_plan(selected_attempt,selected_index));state:=jsonb_extract_path(plan,phase||'Nodes',reference);
 IF state IS NULL OR state->'deleted'='true'::jsonb THEN RETURN NULL;END IF;
 identity:=truss.runtime_owned_identity(selected_attempt,selected_index,reference,'object',plan,prepared_attempt);
 root_reference:=state->>'root';
 IF root_reference IS NOT NULL THEN root_identity:=truss.runtime_owned_identity(selected_attempt,selected_index,root_reference,'object',plan,prepared_attempt);END IF;
 RETURN ((state->'image')-ARRAY['created_at','updated_at'])||jsonb_build_object('id',(identity->>'id')::bigint,
  'root_id',(root_identity->>'id')::bigint,'root_type',(root_identity->>'typeId')::int);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_object_transition_validate_qualified(selected_transition bigint, authorize_read boolean, qualified_actor oid, prepared_input jsonb DEFAULT NULL::jsonb, source_bytes bytea DEFAULT NULL::bytea, prepared_attempt truss.runtime_object_attempt DEFAULT NULL::truss.runtime_object_attempt, compiled_history jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE transition truss.runtime_object_transition%ROWTYPE;attempt truss.runtime_object_attempt%ROWTYPE;
 plan jsonb;reference text;candidate text;identity jsonb;prior jsonb;desired jsonb;previous_image jsonb;
 original_mode text;expected_version bigint;matches int:=0;has_previous boolean;property truss.prop_def;pin record;expected_property_pin text;
 expected_events jsonb;expected_event_buffer jsonb[]:=ARRAY[]::jsonb[];expected_event jsonb;journal jsonb;event jsonb;ordinal int:=0;
 before_record jsonb;after_record jsonb;semantic_events jsonb;semantic_event_buffer jsonb[]:=ARRAY[]::jsonb[];group_pin jsonb;input jsonb;history_key text;history_metadata jsonb;completed_slots bigint;
BEGIN
 IF authorize_read IS NULL THEN RAISE EXCEPTION 'explicit object validation mode required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT transition FROM truss.runtime_object_transition WHERE transition_id=selected_transition;
 -- Independent updates retain versioned journal references. Resolve the sole
 -- physical payload owner before the unchanged semantic and wrapper checks.
 transition.journal:=truss.runtime_owned_journal_materialize(transition.journal);
 IF prepared_attempt.id IS NOT NULL THEN
   IF prepared_attempt.id IS DISTINCT FROM transition.attempt_id THEN RAISE EXCEPTION 'original checked attempt required' USING ERRCODE='55000';END IF;
   attempt:=prepared_attempt;
  ELSE SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=transition.attempt_id;END IF;
 IF prepared_input IS NOT NULL AND (source_bytes IS NULL OR source_bytes IS DISTINCT FROM attempt.input_bytes) THEN
  RAISE EXCEPTION 'original checked transition input required' USING ERRCODE='55000';END IF;
 -- Only the existing private settlement call supplies all checked context.
 -- Its complete immutable slot census is already closed by group_validate;
 -- standalone and history validation retain their independent census.
 IF NOT authorize_read AND prepared_attempt.id IS NOT NULL AND prepared_input IS NOT NULL AND compiled_history IS NOT NULL THEN
  completed_slots:=attempt.next_index;
 ELSE
  SELECT count(*) INTO completed_slots FROM truss.runtime_owned_operation p WHERE p.attempt_id=attempt.id AND p.result IS NOT NULL;
 END IF;
 IF attempt.writer_xid IS DISTINCT FROM transition.writer_xid OR transition.operation_index<0 OR transition.operation_index>=attempt.next_index
  OR completed_slots<>attempt.next_index OR (authorize_read AND NOT attempt.complete)
  OR (NOT authorize_read AND (attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM qualified_actor)) THEN
  RAISE EXCEPTION 'original completed object operation progress required' USING ERRCODE='55000';END IF;
 plan:=truss.runtime_owned_plan(attempt.id,transition.operation_index);
 FOR candidate IN SELECT key FROM jsonb_each(plan->'afterNodes') LOOP
  identity:=truss.runtime_owned_identity(attempt.id,transition.operation_index,candidate,'object',plan,attempt);
  IF identity->>'id'=transition.object_id::text AND identity->>'typeId'=transition.type_id::text THEN reference:=candidate;matches:=matches+1;END IF;
 END LOOP;
 IF matches<>1 THEN RAISE EXCEPTION 'one original object plan member required' USING ERRCODE='55000';END IF;
 identity:=truss.runtime_owned_identity(attempt.id,transition.operation_index,reference,'object',plan,attempt);
 prior:=plan->'beforeNodes'->reference;desired:=plan->'afterNodes'->reference;original_mode:=plan->'operation'->>'operation';
 IF transition.before_object IS NULL THEN
  IF original_mode IS DISTINCT FROM 'create_object' OR reference IS DISTINCT FROM plan->>'primary'
   OR transition.after_object-ARRAY['created_at','updated_at'] IS DISTINCT FROM truss.runtime_owned_object_image(attempt.id,transition.operation_index,reference,'after',plan,attempt) THEN
   RAISE EXCEPTION 'original object creation required' USING ERRCODE='55000';END IF;
  IF NOT authorize_read THEN
   IF compiled_history IS NOT NULL THEN
    history_key:=jsonb_build_array((transition.after_object->>'rev')::int,(transition.after_object->>'type_id')::int)::text;
    history_metadata:=compiled_history->history_key;
    IF history_metadata IS NULL THEN RAISE EXCEPTION 'complete compiled creation history required' USING ERRCODE='55000';END IF;
   END IF;
   PERFORM truss.runtime_create_transition_validate_qualified(selected_transition,qualified_actor,prepared_input,source_bytes,attempt,history_metadata);
  END IF;
  RETURN;
 END IF;
 input:=CASE WHEN authorize_read AND attempt.context ? 'originalAssertedOrigin'
  THEN jsonb_build_object('assertedOrigin',attempt.context->'originalAssertedOrigin')
  ELSE coalesce(prepared_input,convert_from(attempt.input_bytes,'UTF8')::jsonb) END;
 IF original_mode NOT IN ('update_object','delete_object') OR prior IS NULL OR desired IS NULL
  OR prior->'deleted'='true'::jsonb OR prior IS NOT DISTINCT FROM desired
  OR (original_mode='update_object' AND desired->'deleted' IS DISTINCT FROM 'false'::jsonb)
  OR (original_mode='delete_object' AND desired->'deleted' IS DISTINCT FROM 'true'::jsonb)
  OR transition.before_object-ARRAY['created_at','updated_at'] IS DISTINCT FROM truss.runtime_owned_object_image(attempt.id,transition.operation_index,reference,'before',plan,attempt)
  OR transition.after_object-ARRAY['created_at','updated_at'] IS DISTINCT FROM truss.runtime_owned_object_image(attempt.id,transition.operation_index,reference,'after',plan,attempt) THEN
  RAISE EXCEPTION 'original changed object plan and images required' USING ERRCODE='55000';END IF;
 SELECT after_object INTO previous_image FROM truss.runtime_object_transition WHERE attempt_id=attempt.id
  AND object_id=transition.object_id AND type_id=transition.type_id AND operation_index<transition.operation_index ORDER BY operation_index DESC LIMIT 1;
 has_previous:=FOUND;
 IF NOT has_previous THEN
  SELECT jsonb_extract_path(p.plan,'initialScope','nodes',transition.type_id::text||':'||transition.object_id::text) INTO STRICT previous_image
   FROM truss.runtime_owned_operation p WHERE p.attempt_id=attempt.id AND p.operation_index=0;
 END IF;
 IF transition.before_object IS DISTINCT FROM previous_image THEN RAISE EXCEPTION 'original physical object prestate chain required' USING ERRCODE='55000';END IF;
 expected_version:=(transition.before_object->>'ver')::bigint+1;
 IF compiled_history IS NULL THEN before_record:=truss.runtime_object_history(transition.before_object,identity);
 ELSE
  history_key:=jsonb_build_array((transition.before_object->>'rev')::int,(transition.before_object->>'type_id')::int)::text;
  history_metadata:=compiled_history->history_key;
  IF history_metadata IS NULL THEN RAISE EXCEPTION 'complete compiled history census required' USING ERRCODE='55000';END IF;
  before_record:=truss.runtime_owned_history_record_in_metadata(transition.before_object,identity,history_metadata);
 END IF;
 IF transition.after_object IS NOT NULL THEN
  IF transition.after_object->>'ver' IS DISTINCT FROM expected_version::text
   OR transition.after_object->'created_at' IS DISTINCT FROM transition.before_object->'created_at' THEN
   RAISE EXCEPTION 'one object version advance and original creation time required' USING ERRCODE='55000';END IF;
  IF compiled_history IS NULL THEN after_record:=truss.runtime_object_history(transition.after_object,identity);
 ELSE
  history_key:=jsonb_build_array((transition.after_object->>'rev')::int,(transition.after_object->>'type_id')::int)::text;
  history_metadata:=compiled_history->history_key;
  IF history_metadata IS NULL THEN RAISE EXCEPTION 'complete compiled history census required' USING ERRCODE='55000';END IF;
  after_record:=truss.runtime_owned_history_record_in_metadata(transition.after_object,identity,history_metadata);
 END IF;
  FOR property IN SELECT * FROM truss.prop_def WHERE type_id=transition.type_id AND since_rev<=(plan->>'catalogRevision')::int
   AND (retired_rev IS NULL OR retired_rev>(plan->>'catalogRevision')::int) ORDER BY prop_id LOOP
   IF transition.before_object->'props'->property.prop_id::text IS DISTINCT FROM transition.after_object->'props'->property.prop_id::text THEN
    -- The settlement dictionary was independently resolved for this invocation.
    -- Reuse only its exact type/revision/property pin; absent entries (including
    -- removals across revisions) retain the original STRICT reconstruction.
    IF compiled_history IS NOT NULL AND history_metadata->>'typeId'=transition.type_id::text
     AND history_metadata->>'revision'=plan->>'catalogRevision'
     AND jsonb_typeof(history_metadata->'propertyPins'->property.prop_id::text)='string' THEN
     expected_property_pin:=history_metadata->'propertyPins'->>property.prop_id::text;
    ELSE
     SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('property',transition.type_id,property.prop_id,(plan->>'catalogRevision')::int);
     expected_property_pin:=pin.definition_pin;
    END IF;
    expected_event_buffer:=array_append(expected_event_buffer,jsonb_build_object('operation','property','propertyId',property.prop_id::text,'definitionPin',expected_property_pin,
     'before',CASE WHEN transition.before_object->'props' ? property.prop_id::text THEN jsonb_build_object('present',true,'value',transition.before_object->'props'->property.prop_id::text) ELSE '{"present":false}'::jsonb END,
     'after',CASE WHEN transition.after_object->'props' ? property.prop_id::text THEN jsonb_build_object('present',true,'value',transition.after_object->'props'->property.prop_id::text) ELSE '{"present":false}'::jsonb END));
   END IF;
  END LOOP;
  expected_event_buffer:=array_append(expected_event_buffer,jsonb_build_object('operation','metadata','before',before_record,'after',after_record));
 ELSE expected_event_buffer:=array_append(expected_event_buffer,jsonb_build_object('operation','delete','before',before_record));END IF;
 expected_events:=to_jsonb(expected_event_buffer);
 IF jsonb_array_length(transition.journal)<>jsonb_array_length(expected_events) THEN RAISE EXCEPTION 'complete original object event inventory required' USING ERRCODE='55000';END IF;
 FOR journal IN SELECT value FROM jsonb_array_elements(transition.journal) LOOP
  event:=convert_from(decode(journal->'new_value'->>'bytesBase64','base64'),'UTF8')::jsonb;expected_event:=expected_events->ordinal;
  IF event-ARRAY['interfaceVersion','sourceEpoch','historyProfile','xid','seq','identity','eventVersion','eventCatalogRevision','origin','mutationGroup'] IS DISTINCT FROM expected_event
   OR event->>'historyProfile' IS DISTINCT FROM 'truss-native-owned-mutation/0.1' OR event->'identity' IS DISTINCT FROM identity
   OR event->>'eventVersion' IS DISTINCT FROM expected_version::text OR event->>'eventCatalogRevision' IS DISTINCT FROM plan->>'catalogRevision'
   OR event->>'xid' IS DISTINCT FROM attempt.writer_xid::text
   OR event->>'interfaceVersion' IS DISTINCT FROM 'truss-history-event/0.2.0-proposal'
   OR event->>'sourceEpoch' IS DISTINCT FROM attempt.context->>'sourceEpoch'
   OR event->'origin' IS DISTINCT FROM jsonb_build_object('asserted',input->'assertedOrigin','databaseRole',plan->>'actorName')
   OR event->>'seq' IS DISTINCT FROM journal->>'seq'
   OR journal->>'xid' IS DISTINCT FROM attempt.writer_xid::text OR journal->>'ver' IS DISTINCT FROM expected_version::text
   OR journal->>'rev' IS DISTINCT FROM plan->>'catalogRevision'
   OR journal->>'entity_kind' IS DISTINCT FROM 'o' OR journal->>'entity_id' IS DISTINCT FROM transition.object_id::text
   OR journal->>'entity_type' IS DISTINCT FROM transition.type_id::text
   OR journal->>'op' IS DISTINCT FROM (CASE event->>'operation' WHEN 'property' THEN 'update' ELSE event->>'operation' END)
   OR journal->'prop_id' IS DISTINCT FROM coalesce(to_jsonb((event->>'propertyId')::int),'null'::jsonb)
   OR journal->'new_value' IS DISTINCT FROM truss.runtime_exact_wrapper('event',convert_to(event::text,'UTF8'))
   OR journal->'origin' IS DISTINCT FROM truss.runtime_exact_wrapper('origin',convert_to((event->'origin')::text,'UTF8')) THEN
   RAISE EXCEPTION 'exact original owned object event required' USING ERRCODE='55000';END IF;
  IF group_pin IS NULL THEN group_pin:=event->'mutationGroup';
  ELSIF group_pin IS DISTINCT FROM event->'mutationGroup' THEN RAISE EXCEPTION 'one original owned event group required' USING ERRCODE='55000';END IF;
  semantic_event_buffer:=array_append(semantic_event_buffer,event-'mutationGroup');ordinal:=ordinal+1;
 END LOOP;
 semantic_events:=to_jsonb(semantic_event_buffer);
 IF group_pin IS DISTINCT FROM jsonb_build_object('profile','truss-history-group/0.1.0','eventCount',ordinal::text,
  'orderedEventDigest',encode(sha256(convert_to(semantic_events::text,'UTF8')),'hex')) THEN
  RAISE EXCEPTION 'complete original owned event group required' USING ERRCODE='55000';END IF;
 IF authorize_read THEN
  PERFORM truss.runtime_history_ownership(before_record);
  IF after_record IS NOT NULL THEN PERFORM truss.runtime_history_ownership(after_record);END IF;
 ELSE
  PERFORM truss.runtime_module_writer_qualified(identity->'owner'->>'documentId',identity->'owner'->>'moduleId',qualified_actor);
  IF NOT truss.runtime_object_values_readable_qualified(transition.type_id,qualified_actor) THEN RAISE EXCEPTION 'current original property readers required' USING ERRCODE='42501';END IF;
  PERFORM truss.runtime_history_ownership_qualified(before_record,qualified_actor);
  IF after_record IS NOT NULL THEN PERFORM truss.runtime_history_ownership_qualified(after_record,qualified_actor);END IF;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_object_value_delta(selected_type integer, operation jsonb, prior_props jsonb, prior_retained jsonb, selected_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE authored jsonb;removed jsonb;props jsonb;retained jsonb;removed_props text[];removed_retained text[];set_props jsonb;set_retained jsonb;
 property truss.prop_def%ROWTYPE;values_json jsonb;keys_json jsonb;result_json jsonb;validated_prior boolean;
BEGIN
 SELECT EXISTS(SELECT 1 FROM truss.object o
  JOIN truss.runtime_type_schema compiled ON compiled.rev=o.rev AND compiled.type_id=o.type_id
  WHERE o.id=selected_id AND o.type_id=selected_type AND o.rev=(SELECT rev FROM truss.schema_head WHERE id=1)
   AND o.props=prior_props AND o.retained IS NOT DISTINCT FROM prior_retained
   AND compiled.valid_properties)
 INTO validated_prior;
 IF NOT validated_prior THEN RETURN truss.owned_object_values(selected_type,operation,prior_props,prior_retained);END IF;
 IF jsonb_typeof(operation) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'explicit operation value projection required' USING ERRCODE='22023';END IF;
 IF octet_length(operation::text)>1048576 OR coalesce(octet_length(prior_props::text),0)+coalesce(octet_length(prior_retained::text),0)>1048576 THEN
  RAISE EXCEPTION 'bounded value simulation input required' USING ERRCODE='54000';END IF;
 IF NOT EXISTS(SELECT 1 FROM truss.type_def t WHERE t.type_id=selected_type AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL) THEN
  RAISE EXCEPTION 'current admitted Record required' USING ERRCODE='22023';END IF;
 IF operation->>'operation'='create_object' THEN
  IF prior_props IS NOT NULL OR prior_retained IS NOT NULL THEN RAISE EXCEPTION 'create has no prior image' USING ERRCODE='22023';END IF;
  authored:=operation->'values';removed:='[]';props:='{}';retained:='{}';
 ELSIF operation->>'operation'='update_object' THEN
  IF jsonb_typeof(prior_props) IS DISTINCT FROM 'object' OR (prior_retained IS NOT NULL AND jsonb_typeof(prior_retained) IS DISTINCT FROM 'object') THEN
   RAISE EXCEPTION 'complete simulated prior values required' USING ERRCODE='22023';END IF;
  authored:=operation->'set';removed:=operation->'unset';props:=prior_props;retained:=coalesce(prior_retained,'{}');
 ELSE RAISE EXCEPTION 'create or update value simulation required' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(authored) IS DISTINCT FROM 'array' OR jsonb_typeof(removed) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'explicit authored arrays required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(authored)>1024 OR jsonb_array_length(removed)>1024 THEN RAISE EXCEPTION 'bounded authored values required' USING ERRCODE='54000';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(authored) v WHERE v.value-ARRAY['name','value']<>'{}'::jsonb
   OR jsonb_typeof(v.value->'name') IS DISTINCT FROM 'string' OR octet_length(v.value->>'name') NOT BETWEEN 1 AND 4096
   OR truss.valid_flat_cell(v.value->'value') IS NOT TRUE)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(removed) v WHERE jsonb_typeof(v.value) IS DISTINCT FROM 'string' OR octet_length(v.value#>>'{}') NOT BETWEEN 1 AND 4096)
  OR jsonb_array_length(authored)<>(SELECT count(DISTINCT v.value->>'name') FROM jsonb_array_elements(authored) v)
  OR jsonb_array_length(removed)<>(SELECT count(DISTINCT v.value) FROM jsonb_array_elements(removed) v)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(authored) a JOIN jsonb_array_elements(removed) r ON a.value->>'name'=r.value#>>'{}') THEN
  RAISE EXCEPTION 'unique disjoint exact authored values required' USING ERRCODE='22023';END IF;
 SELECT coalesce(array_agg(p.prop_id::text) FILTER(WHERE p.prop_id IS NOT NULL),'{}'::text[]),
  coalesce(array_agg(u.name) FILTER(WHERE p.prop_id IS NULL),'{}'::text[])
 INTO removed_props,removed_retained
 FROM jsonb_array_elements_text(removed) u(name)
 LEFT JOIN truss.prop_def p ON p.type_id=selected_type AND p.retired_rev IS NULL AND p.name=u.name;
 props:=props-removed_props;retained:=retained-removed_retained;
 SELECT coalesce(jsonb_object_agg(p.prop_id::text,truss.canonical_flat_cell(a.value->'value')) FILTER(WHERE p.prop_id IS NOT NULL),'{}'::jsonb),
  coalesce(jsonb_object_agg(a.value->>'name',truss.canonical_flat_cell(a.value->'value')) FILTER(WHERE p.prop_id IS NULL),'{}'::jsonb)
 INTO set_props,set_retained
 FROM jsonb_array_elements(authored) a(value)
 LEFT JOIN truss.prop_def p ON p.type_id=selected_type AND p.retired_rev IS NULL AND p.name=a.value->>'name';
 props:=props||set_props;retained:=retained||set_retained;
 FOR property IN SELECT p.* FROM truss.prop_def p WHERE p.type_id=selected_type AND p.retired_rev IS NULL
  AND p.name IN (SELECT value->>'name' FROM jsonb_array_elements(authored) UNION SELECT value#>>'{}' FROM jsonb_array_elements(removed)) LOOP
  IF truss.valid_property_definition(property) IS NOT TRUE THEN RAISE EXCEPTION 'supported exact property definition required' USING ERRCODE='0A000';END IF;
  IF NOT props ? property.prop_id::text THEN
   IF property.nullability='required' THEN RAISE EXCEPTION 'missing required value' USING ERRCODE='22023';END IF;
  ELSIF truss.valid_property_value(props->property.prop_id::text,property) IS NOT TRUE THEN
   RAISE EXCEPTION 'exact declared value required' USING ERRCODE='22023';END IF;
 END LOOP;
 IF octet_length(convert_to(jsonb_build_object('props',props,'retained',retained)::text,'UTF8'))>1048576 THEN
  RAISE EXCEPTION 'bounded complete object values required' USING ERRCODE='54000';END IF;
 result_json:=jsonb_build_object('props',props,'retained',retained);
 RETURN result_json;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_operation_owner_qualified(operation jsonb, operations jsonb, operation_index integer, qualified_actor oid)
 RETURNS TABLE(document_id text, module text, definition_rev integer, definition_doc_ord integer, definition_document_id text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE object_type truss.type_def%ROWTYPE;relationship truss.rel_def%ROWTYPE;
BEGIN
 IF operation->>'operation' IN ('create_object','update_object','delete_object') THEN
  object_type:=truss.runtime_owned_operation_type_qualified(operation,operations,operation_index,qualified_actor);
  RETURN QUERY SELECT object_type.document_id,object_type.module,object_type.definition_rev,object_type.definition_doc_ord,object_type.definition_document_id;
 ELSE
  relationship:=truss.runtime_operation_relationship(operation,operations,operation_index);
  RETURN QUERY SELECT relationship.document_id,relationship.module,relationship.definition_rev,relationship.definition_doc_ord,relationship.definition_document_id;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_operation_type_qualified(operation jsonb, operations jsonb, operation_index integer, qualified_actor oid)
 RETURNS truss.type_def
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE pin text;identity jsonb;creation jsonb;selected truss.type_def%ROWTYPE;
BEGIN
 IF operation->>'operation'='create_object' THEN pin:=operation->>'typeDefinitionPin';
 ELSIF operation->>'operation' IN ('update_object','delete_object') THEN
  IF operation->'target'->>'state'='stored' THEN
   identity:=operation->'target'->'identity';pin:=identity->>'definitionPin';
  ELSIF operation->'target'->>'state'='alias' THEN
   IF jsonb_typeof(operations)='object' THEN
    creation:=operations->(operation->'target'->>'alias');
    IF creation->>'operation' IS DISTINCT FROM 'create_object' OR (creation->>'operationIndex')::int>=operation_index THEN
     RAISE EXCEPTION 'prior object alias required' USING ERRCODE='22023';END IF;
   ELSE
    SELECT value INTO STRICT creation FROM jsonb_array_elements(operations) WITH ORDINALITY x(value,ord)
     WHERE ord<=operation_index AND value->>'operation'='create_object' AND value->>'alias'=operation->'target'->>'alias';
   END IF;
   pin:=creation->>'typeDefinitionPin';
  ELSE RAISE EXCEPTION 'stored or prior alias target required' USING ERRCODE='22023';END IF;
 ELSE RAISE EXCEPTION 'selected object operation required' USING ERRCODE='0A000';END IF;
 -- Stored targets already carry their exact native type coordinate. Resolve
 -- that candidate before deriving pins for unrelated catalog records.
 IF identity IS NOT NULL THEN
  WITH pinned AS MATERIALIZED (
   SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
   WHERE definition_pin=pin AND kind='element' AND key_id='')
  SELECT t.* INTO selected FROM pinned p JOIN truss.type_def t
    ON t.definition_rev=p.rev AND t.definition_doc_ord=p.ord AND t.definition_document_id=p.doc_id
     AND t.module=p.module_id AND t.element=p.element_id
   WHERE t.type_id::text=identity->>'typeId'
    AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL;
 END IF;
 IF selected.type_id IS NULL THEN
  -- Preserve original CREATE/alias lookup and stored-identity refusal precedence.
  WITH pinned AS MATERIALIZED (
   SELECT rev,ord,doc_id,module_id,element_id FROM truss.runtime_definition_source
   WHERE definition_pin=pin AND kind='element' AND key_id='')
  SELECT t.* INTO STRICT selected FROM pinned p JOIN truss.type_def t
    ON t.definition_rev=p.rev AND t.definition_doc_ord=p.ord AND t.definition_document_id=p.doc_id
     AND t.module=p.module_id AND t.element=p.element_id
   WHERE t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL;
 END IF;
 IF identity IS NOT NULL AND (identity->>'typeId' IS DISTINCT FROM selected.type_id::text
  OR identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',selected.document_id,'moduleId',selected.module)
  OR identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb
  OR jsonb_typeof(identity->'id') IS DISTINCT FROM 'string' OR identity->>'id' !~ '^[1-9][0-9]{0,18}$'
  OR length(identity->>'id')=19 AND (identity->>'id') COLLATE "C">'9223372036854775807') THEN
  RAISE EXCEPTION 'qualified exact object identity required' USING ERRCODE='22023';END IF;
 IF NOT truss.runtime_object_values_readable_qualified(selected.type_id,qualified_actor) THEN RAISE EXCEPTION 'current property and item interpretation reader required' USING ERRCODE='42501';END IF;
 RETURN selected;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_plan(selected_attempt uuid, selected_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE original record;scope_image jsonb;before_state jsonb;after_state jsonb;after_image jsonb;reference text;
BEGIN
 SELECT plan INTO STRICT original FROM truss.runtime_owned_operation
  WHERE attempt_id=selected_attempt AND operation_index=selected_index;
 -- Both source bytes and prepared operations are immutable after capture.
 -- Full source correspondence is checked once at each group settlement.
 IF selected_index<0
  OR original.plan->>'profile' IS DISTINCT FROM 'truss-owned-operation-plan/0.2'
  OR original.plan->'operationIndex' IS DISTINCT FROM to_jsonb(selected_index)
  OR original.plan->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() THEN
  RAISE EXCEPTION 'original owned operation correspondence required' USING ERRCODE='55000';END IF;
 IF original.plan->>'compactProfile'='truss-application-value-plan/0.1' THEN
  -- Historical/general readers reconstruct the former virtual frame lazily.
  -- No-op updates have no transition; their one original scope image remains
  -- sufficient even if a later operation or catalog acceptance changed the row.
  reference:=original.plan->>'primary';
  before_state:=original.plan->'beforeNodes'->reference;after_state:=original.plan->'afterNodes'->reference;
  SELECT p.plan->'initialScope'->'nodes'->((before_state->'identity'->>'typeId')||':'||(before_state->'identity'->>'id'))
   INTO STRICT scope_image FROM truss.runtime_owned_operation p WHERE p.attempt_id=selected_attempt AND p.operation_index=0;
  IF scope_image IS NULL THEN RAISE EXCEPTION 'original compact update scope required' USING ERRCODE='55000';END IF;
  before_state:=jsonb_set(before_state,'{image}',scope_image-ARRAY['root_id','root_type','updated_at']);
  IF before_state->'image'->'ver' IS DISTINCT FROM after_state->'image'->'ver' THEN
   SELECT t.after_object INTO STRICT after_image FROM truss.runtime_object_transition t
    WHERE t.attempt_id=selected_attempt AND t.operation_index=selected_index;
   IF encode(sha256(convert_to((after_image-ARRAY['created_at','updated_at'])::text,'UTF8')),'hex')
    IS DISTINCT FROM original.plan->>'desiredImageSha256' THEN
    RAISE EXCEPTION 'original compact update desired image required' USING ERRCODE='55000';END IF;
  ELSE after_image:=scope_image;END IF;
  after_state:=jsonb_set(after_state,'{image}',after_image-ARRAY['root_id','root_type','updated_at']);
  original.plan:=jsonb_set(jsonb_set(original.plan,ARRAY['beforeNodes',reference],before_state),ARRAY['afterNodes',reference],after_state);
 END IF;
 RETURN original.plan;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_prepare_application(input jsonb, scope jsonb, application_prepared jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE input_operations jsonb;application_operations jsonb;
 nodes jsonb:='{}';edges jsonb:='{}';aliases jsonb:='{}';plans jsonb[]:='{}';
 node_order text[]:='{}';boundary_order text[]:='{}';entry record;selected text;source_ref text;target_ref text;root_ref text;
 operation jsonb;before_nodes jsonb;before_edges jsonb;state jsonb;descendant_state jsonb;prior jsonb;image jsonb;values_image jsonb;ownership jsonb;
 selected_type truss.type_def%ROWTYPE;relation truss.rel_def%ROWTYPE;pin record;identity jsonb;revision int;
 index int:=0;before_count int;descendants text[];descendant text;projection jsonb;deleted jsonb;local_owned jsonb;local_independent jsonb;
 unset_name text;authored jsonb;retained jsonb;order_key jsonb;selected_source_type int;selected_target_type int;plan jsonb;outgoing bigint;incoming bigint;
 retained_nodes text[];retained_edges text[];changed_nodes text[];changed_edges text[];full_node_refs text[];plans_bytes bigint:=2;current_actor oid;resolved_creates jsonb:='{}';
 alias_names text[]:='{}';alias_values text[]:='{}';duplicate_alias_index int;alias_operations jsonb:='{}';
 rootless_creates boolean;created_states jsonb[]:='{}';
 edge_creates boolean;created_edge_states jsonb[]:='{}';initial_edge_count int;edge_member_count int;
 value_updates boolean;updated_states jsonb[]:='{}';updated_references text[]:='{}';
 scope_node_states jsonb[]:='{}';scope_edge_states jsonb[]:='{}';
 scope_node_type int;scope_edge_type int;scope_edge_pin text;outgoing_counts jsonb;incoming_counts jsonb;
 indexed_workspace boolean:=false;workspace_name text;workspace_index_name text;multiplicity_failure text;
BEGIN
 current_actor:=truss.runtime_person(false);
 input_operations:=input->'operations';
 application_operations:=application_prepared->'operations';
 IF jsonb_typeof(input_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(input_operations) NOT BETWEEN 1 AND 1024
  OR jsonb_typeof(scope->'nodes') IS DISTINCT FROM 'object' OR jsonb_typeof(scope->'edges') IS DISTINCT FROM 'object'
  OR octet_length(convert_to(scope::text,'UTF8'))>(CASE WHEN scope->'independentEndpointScope'='true'::jsonb THEN 16777216 ELSE 4194304 END) THEN
  RAISE EXCEPTION 'complete bounded original group scope required' USING ERRCODE='54000';END IF;
 SELECT min(ordered_aliases.operation_index) INTO duplicate_alias_index FROM (
  SELECT valid_aliases.operation_index,row_number() OVER(PARTITION BY valid_aliases.alias_text COLLATE "C" ORDER BY valid_aliases.operation_index) duplicate_ordinal FROM (
   SELECT ordinal-1 operation_index,value->>'alias' alias_text FROM jsonb_array_elements(input_operations) WITH ORDINALITY operations(value,ordinal)
   WHERE value ? 'alias' AND jsonb_typeof(value->'alias')='string'
    AND octet_length(value->>'alias') BETWEEN 1 AND 1024
  ) valid_aliases
 ) ordered_aliases WHERE duplicate_ordinal=2;
 SELECT coalesce(jsonb_object_agg(alias_name,alias_operation),'{}'::jsonb) INTO alias_operations FROM (
  SELECT DISTINCT ON ((value->>'alias') COLLATE "C") value->>'alias' alias_name,
   jsonb_build_object('operation',value->>'operation','operationIndex',ordinal-1,
    'typeDefinitionPin',value->'typeDefinitionPin','relationshipDefinitionPin',value->'relationshipDefinitionPin') alias_operation
  FROM jsonb_array_elements(input_operations) WITH ORDINALITY operations(value,ordinal)
  WHERE jsonb_typeof(value->'alias')='string' AND octet_length(value->>'alias') BETWEEN 1 AND 1024
  ORDER BY (value->>'alias') COLLATE "C",ordinal
 ) original_aliases;
 -- Buffer independent new roots; no operation in this closed shape reads an
 -- earlier node. Keep the same ordered plans and complete final graph checks.
 rootless_creates:=coalesce(scope->'nodes'='{}'::jsonb AND scope->'edges'='{}'::jsonb
  AND scope->'boundary'='{}'::jsonb AND NOT EXISTS(
   SELECT 1 FROM jsonb_array_elements(input_operations) o
   WHERE o.value->>'operation' IS DISTINCT FROM 'create_object'
    OR o.value->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb),false);
 -- Pure edge creates cannot read an earlier newly-created edge. Buffer them
 -- and build the complete final map once, avoiding growing JSONB copies/counts.
 edge_creates:=NOT EXISTS(SELECT 1 FROM jsonb_array_elements(input_operations) o
  WHERE o.value->>'operation' IS DISTINCT FROM 'create_edge');
 -- Distinct stored rootless targets cannot observe one another's value edits.
 -- Keep ordinary validation in order; malformed shapes use the general path.
 value_updates:=NOT EXISTS(
  SELECT 1 FROM jsonb_array_elements(input_operations) o
  WHERE o.value->>'operation' IS DISTINCT FROM 'update_object'
   OR o.value ? 'ownershipChange'
   OR o.value->'target'->>'state' IS DISTINCT FROM 'stored'
   OR jsonb_typeof(o.value->'target'->'identity'->'typeId') IS DISTINCT FROM 'string'
   OR jsonb_typeof(o.value->'target'->'identity'->'id') IS DISTINCT FROM 'string')
  AND NOT EXISTS(SELECT 1 FROM jsonb_each(scope->'nodes') n
   WHERE n.value->'root_id' IS DISTINCT FROM 'null'::jsonb
    OR n.value->'root_type' IS DISTINCT FROM 'null'::jsonb)
  AND (SELECT count(*)=count(DISTINCT 'stored:'||(o.value->'target'->'identity'->>'typeId')||':'||(o.value->'target'->'identity'->>'id'))
   FROM jsonb_array_elements(input_operations) o);
 revision:=(scope->>'catalogRevision')::int;
 IF revision IS NULL OR revision<1 OR revision IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1) THEN
  RAISE EXCEPTION 'current admitted group catalog required' USING ERRCODE='55P03';END IF;
 WITH requested AS MATERIALIZED (
  SELECT DISTINCT (value->>'typeDefinitionPin') COLLATE "C" definition_pin FROM jsonb_array_elements(input_operations) operations(value)
  WHERE value->>'operation'='create_object' AND jsonb_typeof(value->'typeDefinitionPin')='string'
 ), matched AS MATERIALIZED (
  SELECT requested.definition_pin,matched_type.native_type,
   count(*) OVER(PARTITION BY requested.definition_pin) match_count
  FROM requested
  CROSS JOIN LATERAL (
   SELECT d.rev,d.ord,d.doc_id,d.module_id,d.element_id
   FROM truss.runtime_definition_source d
   WHERE d.definition_pin=requested.definition_pin COLLATE "C"
    AND d.kind='element' AND d.key_id=''
   OFFSET 0
  ) matched_source
  CROSS JOIN LATERAL (
   SELECT to_jsonb(t) native_type
   FROM truss.type_def t
   WHERE t.definition_rev=matched_source.rev
    AND t.definition_doc_ord=matched_source.ord
    AND t.definition_document_id=matched_source.doc_id
    AND t.module=matched_source.module_id
    AND t.element=matched_source.element_id
    AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL
   OFFSET 0
  ) matched_type
 )
 SELECT coalesce(jsonb_object_agg(definition_pin,native_type) FILTER(WHERE match_count=1),'{}'::jsonb)
  INTO resolved_creates FROM matched;
 FOR entry IN SELECT key,value FROM jsonb_each(scope->'nodes') ORDER BY (value->>'type_id')::int,(value->>'id')::bigint LOOP
  selected:='stored:'||entry.key;image:=entry.value;
  -- Ordered initial rows share immutable catalog meaning; permissions and
  -- per-object state are still checked on their original paths.
  IF scope_node_type IS NULL OR scope_node_type IS DISTINCT FROM (image->>'type_id')::int THEN
   SELECT * INTO STRICT pin FROM truss.runtime_owned_definition_metadata('type',(image->>'type_id')::int);
   scope_node_type:=(image->>'type_id')::int;
  END IF;
  identity:=jsonb_build_object('id',image->>'id','typeId',image->>'type_id','definitionPin',pin.definition_pin,
   'owner',jsonb_build_object('documentId',pin.document_id,'moduleId',pin.module_id));
  root_ref:=CASE WHEN image->'root_id'='null'::jsonb THEN NULL ELSE 'stored:'||(image->>'root_type')||':'||(image->>'root_id') END;
  scope_node_states:=array_append(scope_node_states,jsonb_build_object(selected,jsonb_build_object('identity',identity,'image',image-ARRAY['root_id','root_type','updated_at'],
   'root',root_ref,'deleted',false)));node_order:=array_append(node_order,selected);
 END LOOP;
 -- No initial member reads these maps while they are built. Materialize once
 -- instead of copying every previously captured member on each append.
 SELECT coalesce(jsonb_object_agg(member.key,member.value ORDER BY n.ordinal),'{}'::jsonb) INTO nodes
  FROM unnest(scope_node_states) WITH ORDINALITY n(state,ordinal) CROSS JOIN LATERAL jsonb_each(n.state) member;
 FOR entry IN SELECT key,value FROM jsonb_each(scope->'boundary') ORDER BY key COLLATE "C" LOOP
  boundary_order:=array_append(boundary_order,'stored:'||entry.key);
 END LOOP;
 FOR entry IN SELECT key,value FROM jsonb_each(scope->'edges') ORDER BY (value->>'rel_type_id')::int,(value->>'id')::bigint LOOP
  image:=entry.value;
  IF scope_edge_type IS NULL OR scope_edge_type IS DISTINCT FROM (image->>'rel_type_id')::int THEN
   SELECT * INTO STRICT relation FROM truss.rel_def WHERE rel_type_id=(image->>'rel_type_id')::int;
   scope_edge_pin:=truss.runtime_relationship_pin(relation.rel_type_id);
   scope_edge_type:=relation.rel_type_id;
  END IF;
  identity:=jsonb_build_object('id',image->>'id','typeId',image->>'rel_type_id','definitionPin',scope_edge_pin,
   'owner',jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module));
  selected:='stored:'||(image->>'rel_type_id')||':'||(image->>'id');
  scope_edge_states:=array_append(scope_edge_states,jsonb_build_object(selected,jsonb_build_object('identity',identity,'image',image-ARRAY['source_id','source_type','target_id','target_type','order_key','updated_at'],
   'source','stored:'||(image->>'source_type')||':'||(image->>'source_id'),
   'target','stored:'||(image->>'target_type')||':'||(image->>'target_id'),'lifecycle',relation.lifecycle,'deleted',false,
   'orderKey',CASE WHEN image->'order_key'='null'::jsonb THEN '{"state":"null"}'::jsonb ELSE jsonb_build_object('state','text','text',image->>'order_key') END)));
 END LOOP;
 SELECT coalesce(jsonb_object_agg(member.key,member.value ORDER BY e.ordinal),'{}'::jsonb) INTO edges
  FROM unnest(scope_edge_states) WITH ORDINALITY e(state,ordinal) CROSS JOIN LATERAL jsonb_each(e.state) member;
 SELECT count(*) INTO initial_edge_count FROM jsonb_each(edges);
 edge_member_count:=initial_edge_count;
 indexed_workspace:=NOT rootless_creates AND NOT value_updates AND NOT edge_creates;
 IF indexed_workspace THEN
  workspace_name:='truss_owned_plan_'||replace(gen_random_uuid()::text,'-','');
  workspace_index_name:=workspace_name||'_source_idx';
  EXECUTE format('CREATE TEMP TABLE %I (member_kind char(1) NOT NULL,member_ref text NOT NULL,member_ordinal integer NOT NULL,created_operation integer,before_operation integer,before_state jsonb,before_header_state jsonb,state jsonb,header_state jsonb,deleted boolean NOT NULL DEFAULT false,root_ref text,source_ref text,target_ref text,lifecycle text,PRIMARY KEY(member_kind,member_ref)) ON COMMIT DROP',workspace_name);
  EXECUTE format('CREATE INDEX %I ON pg_temp.%I(source_ref) WHERE member_kind=''e'' AND NOT deleted',workspace_index_name,workspace_name);
  workspace_index_name:=workspace_name||'_target_idx';
  EXECUTE format('CREATE INDEX %I ON pg_temp.%I(target_ref) WHERE member_kind=''e'' AND NOT deleted',workspace_index_name,workspace_name);
  EXECUTE format('INSERT INTO pg_temp.%I(member_kind,member_ref,member_ordinal,state,header_state,deleted,root_ref) SELECT ''n'',r.member_ref,r.ordinal::int,j.value,jsonb_set(j.value,''{image}'',(j.value->''image'')-ARRAY[''props'',''retained'']),coalesce((j.value->>''deleted'')::boolean,false),j.value->>''root'' FROM unnest($1::text[]) WITH ORDINALITY r(member_ref,ordinal) JOIN jsonb_each($2) j ON j.key=r.member_ref',workspace_name) USING node_order,nodes;
  EXECUTE format('INSERT INTO pg_temp.%I(member_kind,member_ref,member_ordinal,state,header_state,deleted,source_ref,target_ref,lifecycle) SELECT ''e'',key,row_number() OVER(ORDER BY key COLLATE "C")::int,value,jsonb_set(value,''{image}'',(value->''image'')-ARRAY[''props'',''retained'']),coalesce((value->>''deleted'')::boolean,false),value->>''source'',value->>''target'',value->>''lifecycle'' FROM jsonb_each($1)',workspace_name) USING edges;
  EXECUTE format('INSERT INTO pg_temp.%I(member_kind,member_ref,member_ordinal,state,header_state,deleted) SELECT ''b'',r.member_ref,r.ordinal::int,j.value,j.value,false FROM unnest($1::text[]) WITH ORDINALITY r(member_ref,ordinal) JOIN jsonb_each($2) j ON ''stored:''||j.key=r.member_ref',workspace_name) USING boundary_order,scope->'boundary';
  nodes:='{}'::jsonb;edges:='{}'::jsonb;aliases:='{}'::jsonb;
 END IF;
 FOR operation IN SELECT value FROM jsonb_array_elements(input_operations) LOOP
  IF indexed_workspace THEN before_nodes:='{}'::jsonb;before_edges:='{}'::jsonb;
  ELSE before_nodes:=nodes;before_edges:=edges;END IF;
  changed_nodes:=ARRAY[]::text[];changed_edges:=ARRAY[]::text[];
  IF application_prepared IS NOT NULL AND octet_length(operation::text)>1048576 THEN
   RAISE EXCEPTION 'bounded value simulation input required' USING ERRCODE='54000';END IF;
  IF operation ? 'alias' AND (jsonb_typeof(operation->'alias') IS DISTINCT FROM 'string'
   OR octet_length(operation->>'alias') NOT BETWEEN 1 AND 1024 OR duplicate_alias_index=index) THEN
   RAISE EXCEPTION 'unique bounded original alias required' USING ERRCODE='22023';END IF;
  IF operation->>'operation' IN ('create_object','update_object','delete_object') THEN
   IF operation->>'operation'='create_object' AND resolved_creates ? (operation->>'typeDefinitionPin') THEN
    selected_type:=jsonb_populate_record(NULL::truss.type_def,resolved_creates->(operation->>'typeDefinitionPin'));
    IF NOT truss.runtime_object_values_readable_qualified(selected_type.type_id,current_actor) THEN
     RAISE EXCEPTION 'current property and item interpretation reader required' USING ERRCODE='42501';END IF;
   ELSE
    -- Only alias resolution reads earlier operations; stored/create targets do not.
    selected_type:=truss.runtime_owned_operation_type_qualified(operation,
     CASE WHEN operation->'target'->>'state'='alias' THEN alias_operations END,index,current_actor);
   END IF;
   IF operation->>'operation'='create_object' THEN
    IF operation-ARRAY['operation','typeDefinitionPin','values','ownership','alias']<>'{}'::jsonb
     OR jsonb_typeof(operation->'ownership') IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'closed original object create required' USING ERRCODE='22023';END IF;
    IF cardinality(node_order)>=1024 THEN RAISE EXCEPTION 'bounded complete group objects required' USING ERRCODE='54000';END IF;
    selected:='create:'||index;node_order:=array_append(node_order,selected);
    IF application_prepared IS NOT NULL THEN
     values_image:=truss.runtime_owned_application_values(selected_type.type_id,index,application_operations->index,NULL,NULL);
    ELSE values_image:=truss.owned_object_values(selected_type.type_id,operation,NULL,NULL);END IF;
    state:=jsonb_build_object('identity',jsonb_build_object('id',NULL,'typeId',selected_type.type_id::text,
     'definitionPin',operation->>'typeDefinitionPin','owner',jsonb_build_object('documentId',selected_type.document_id,'moduleId',selected_type.module)),
     'image',jsonb_build_object('id',NULL,'type_id',selected_type.type_id,'props',values_image->'props',
      'retained',nullif(values_image->'retained','{}'::jsonb),'rev',revision,'ver',1),
     'createIndex',index,'root',NULL,'deleted',false);
    IF indexed_workspace THEN PERFORM truss.runtime_owned_workspace_insert(workspace_name,'n',selected,cardinality(node_order),index,state);END IF;
    ownership:=operation->'ownership';
   ELSE
    IF indexed_workspace THEN selected:=truss.runtime_owned_workspace_reference(operation->'target',workspace_name,'n',index);
     state:=truss.runtime_owned_workspace_state(workspace_name,'n',selected);
    ELSE selected:=truss.runtime_owned_reference(operation->'target',aliases,nodes);state:=truss.runtime_owned_workspace_state_or(workspace_name,'n',selected,nodes);END IF;
    IF state->'identity'->>'typeId' IS DISTINCT FROM selected_type.type_id::text THEN RAISE EXCEPTION 'original object reference type required' USING ERRCODE='22023';END IF;
    IF operation ? 'expectedVersion' AND (jsonb_typeof(operation->'expectedVersion') IS DISTINCT FROM 'string'
     OR operation->>'expectedVersion' IS DISTINCT FROM state->'image'->>'ver') THEN
     RAISE EXCEPTION 'expected object version failed' USING ERRCODE='P1003';END IF;
    ownership:=operation->'ownershipChange';
   END IF;
   IF operation->>'operation'='delete_object' THEN
    IF operation-ARRAY['operation','target','expectedVersion']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed object delete required' USING ERRCODE='22023';END IF;
     IF indexed_workspace THEN
      deleted:=truss.runtime_owned_workspace_delete_plan(workspace_name,selected);
     ELSE
      local_owned:=truss.runtime_owned_local_edges(edges,node_order,boundary_order,true);
      local_independent:=truss.runtime_owned_local_edges(edges,node_order,boundary_order,false);
      deleted:=truss.owned_delete_projection(cardinality(node_order),local_owned,local_independent,array_position(node_order,selected)-1);
     END IF;
    FOR entry IN SELECT value FROM jsonb_array_elements(deleted->'deletedNodes') LOOP
      descendant:=CASE WHEN indexed_workspace THEN entry.value#>>'{}' ELSE node_order[(entry.value#>>'{}')::int+1] END;
      state:=CASE WHEN indexed_workspace THEN truss.runtime_owned_workspace_state_or(workspace_name,'n',descendant,nodes) ELSE nodes->descendant END;
      IF (state->'image'->>'ver')::bigint=9223372036854775807 THEN RAISE EXCEPTION 'object version exhausted' USING ERRCODE='54000';END IF;
     changed_nodes:=array_append(changed_nodes,descendant);
      state:=jsonb_set(state,'{deleted}','true'::jsonb);
      nodes:=truss.runtime_owned_workspace_write(workspace_name,'n',descendant,index,state,nodes);
    END LOOP;
     IF indexed_workspace THEN
      FOR entry IN SELECT value FROM jsonb_array_elements_text(deleted->'deletedEdges') LOOP
       descendant:=entry.value;state:=truss.runtime_owned_workspace_state_or(workspace_name,'e',descendant,edges);
       IF (state->'image'->>'ver')::bigint=9223372036854775807 THEN RAISE EXCEPTION 'edge version exhausted' USING ERRCODE='54000';END IF;
       changed_edges:=array_append(changed_edges,descendant);state:=jsonb_set(state,'{deleted}','true'::jsonb);
       edges:=truss.runtime_owned_workspace_write(workspace_name,'e',descendant,index,state,edges);
      END LOOP;
     ELSE
      FOR entry IN SELECT key,value FROM jsonb_each(edges) WHERE value->'deleted'='false'::jsonb LOOP
       IF nodes->(entry.value->>'source')->'deleted'='true'::jsonb OR nodes->(entry.value->>'target')->'deleted'='true'::jsonb THEN
        IF (entry.value->'image'->>'ver')::bigint=9223372036854775807 THEN RAISE EXCEPTION 'edge version exhausted' USING ERRCODE='54000';END IF;
        changed_edges:=array_append(changed_edges,entry.key);edges:=jsonb_set(edges,ARRAY[entry.key,'deleted'],'true'::jsonb);
       END IF;
      END LOOP;
     END IF;
   ELSE
    IF operation->>'operation'='update_object' THEN
     IF operation-ARRAY['operation','target','set','unset','expectedVersion','ownershipChange']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed object update required' USING ERRCODE='22023';END IF;
     IF application_prepared IS NOT NULL AND state->'image'->>'rev'=revision::text THEN
      values_image:=truss.runtime_owned_application_values(selected_type.type_id,index,application_operations->index,
       state->'image'->'props',nullif(state->'image'->'retained','null'::jsonb));
     ELSE values_image:=truss.runtime_owned_object_value_delta(selected_type.type_id,operation,state->'image'->'props',nullif(state->'image'->'retained','null'::jsonb),(state->'image'->>'id')::bigint);END IF;
     state:=jsonb_set(state,'{image,props}',values_image->'props');
     state:=jsonb_set(state,'{image,retained}',coalesce(nullif(values_image->'retained','{}'::jsonb),'null'::jsonb));
    END IF;
    IF ownership IS NOT NULL THEN
     IF ownership='{"state":"rootless"}'::jsonb THEN root_ref:=NULL;
     ELSIF ownership->>'state'='owned' AND ownership-ARRAY['state','root']='{}'::jsonb THEN
      IF indexed_workspace THEN root_ref:=truss.runtime_owned_workspace_reference(ownership->'root',workspace_name,'n',index);
      ELSE root_ref:=truss.runtime_owned_reference(ownership->'root',aliases,nodes);END IF;
      IF root_ref=selected OR truss.runtime_owned_workspace_state_or(workspace_name,'n',root_ref,nodes,true)->'root'<>'null'::jsonb THEN RAISE EXCEPTION 'selected live rootless aggregate root required' USING ERRCODE='22023';END IF;
     ELSE RAISE EXCEPTION 'explicit exact ownership selection required' USING ERRCODE='22023';END IF;
     IF state->'root' IS DISTINCT FROM coalesce(to_jsonb(root_ref),'null'::jsonb) THEN
      IF indexed_workspace THEN descendants:=truss.runtime_owned_workspace_descendants(workspace_name,selected);
      ELSE
       descendants:=ARRAY[selected];
       LOOP
        before_count:=cardinality(descendants);
        SELECT array_agg(DISTINCT reference COLLATE "C" ORDER BY reference COLLATE "C") INTO descendants FROM (
         SELECT unnest(descendants) AS reference UNION ALL SELECT value->>'target' FROM jsonb_each(edges)
          WHERE value->'deleted'='false'::jsonb AND value->>'lifecycle'='owned' AND value->>'source'=ANY(descendants)) expanded;
        EXIT WHEN cardinality(descendants)=before_count;
       END LOOP;
      END IF;
      IF root_ref=ANY(descendants) THEN RAISE EXCEPTION 'aggregate root outside moved subtree required' USING ERRCODE='22023';END IF;
      FOR descendant IN SELECT unnest(descendants) LOOP
        IF descendant=selected THEN state:=jsonb_set(state,'{root}',coalesce(to_jsonb(root_ref),'null'::jsonb));
        ELSE changed_nodes:=array_append(changed_nodes,descendant);descendant_state:=truss.runtime_owned_workspace_state_or(workspace_name,'n',descendant,nodes);
         descendant_state:=jsonb_set(descendant_state,'{root}',coalesce(to_jsonb(coalesce(root_ref,selected)),'null'::jsonb));
         nodes:=truss.runtime_owned_workspace_write(workspace_name,'n',descendant,index,descendant_state,nodes);END IF;
      END LOOP;
     END IF;
    END IF;
    changed_nodes:=array_append(changed_nodes,selected);
    IF rootless_creates THEN created_states:=array_append(created_states,state);
    -- Ordinary updates install their final versioned member below; no-op
    -- updates already have that exact state in the working graph.
     ELSIF operation->>'operation'<>'update_object' OR operation ? 'ownershipChange' THEN
      nodes:=truss.runtime_owned_workspace_write(workspace_name,'n',selected,index,state,nodes);END IF;
    IF operation->>'operation'='update_object' AND NOT (operation ? 'ownershipChange') THEN
     IF state IS DISTINCT FROM truss.runtime_owned_workspace_state_at_or(workspace_name,'n',selected,index,true,before_nodes) THEN
      IF (state->'image'->>'ver')::bigint=9223372036854775807 THEN RAISE EXCEPTION 'object version exhausted' USING ERRCODE='54000';END IF;
      state:=jsonb_set(state,'{image,ver}',to_jsonb((state->'image'->>'ver')::bigint+1));
      IF value_updates THEN state:=jsonb_set(state,'{image,rev}',to_jsonb(revision));
