  SELECT 'final incoming multiplicity failed' FROM live_nodes n JOIN truss.rel_endpoint e ON e.target_type=n.type_id
   JOIN truss.rel_def r USING(rel_type_id) WHERE r.retired_rev IS NULL AND r.source_min>0
    AND coalesce((incoming_counts->>jsonb_build_array(r.rel_type_id::text,n.reference)::text)::bigint,0)<r.source_min)
 SELECT reason INTO multiplicity_failure FROM violations LIMIT 1;
 IF FOUND THEN RAISE EXCEPTION '%',multiplicity_failure USING ERRCODE='P1005';END IF;
 END IF;
 plan:=jsonb_build_object('profile','truss-owned-group-plan/0.1','catalogRevision',revision,
  'initialScope',scope,'operations',to_jsonb(plans),'aliases',aliases);
 IF octet_length(convert_to(plan::text,'UTF8'))>33554432 THEN RAISE EXCEPTION 'bounded complete group execution inventory required' USING ERRCODE='54000';END IF;
 IF indexed_workspace THEN EXECUTE format('DROP TABLE pg_temp.%I',workspace_name);END IF;
 RETURN plan;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_reference(reference jsonb, aliases jsonb, states jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE selected text;identity jsonb;state jsonb;
BEGIN
 IF jsonb_typeof(reference) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'explicit graph reference required' USING ERRCODE='22023';END IF;
 IF reference->>'state'='alias' THEN
  IF reference-ARRAY['state','alias']<>'{}'::jsonb OR jsonb_typeof(reference->'alias') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'closed prior alias required' USING ERRCODE='22023';END IF;
  selected:=aliases->> (reference->>'alias');
 ELSIF reference->>'state'='stored' THEN
  identity:=reference->'identity';
  IF reference-ARRAY['state','identity']<>'{}'::jsonb OR jsonb_typeof(identity) IS DISTINCT FROM 'object'
   OR identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb THEN
   RAISE EXCEPTION 'closed original stored reference required' USING ERRCODE='22023';END IF;
  selected:='stored:'||(identity->>'typeId')||':'||(identity->>'id');
 ELSE RAISE EXCEPTION 'stored or prior alias required' USING ERRCODE='22023';END IF;
 state:=states->selected;
 IF selected IS NULL OR state IS NULL THEN RAISE EXCEPTION 'existing reference of the correct kind required' USING ERRCODE='22023';END IF;
 IF state->'deleted'='true'::jsonb THEN RAISE EXCEPTION 'referenced graph member deleted' USING ERRCODE='P1004';END IF;
 IF identity IS NOT NULL AND identity IS DISTINCT FROM state->'identity' THEN
  RAISE EXCEPTION 'original qualified identity correspondence required' USING ERRCODE='22023';END IF;
 RETURN selected;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_request_documents(request truss.catalog_registration_request)
 RETURNS bytea
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result bytea;
BEGIN
 IF octet_length(request.document_bytes)>0 THEN RETURN request.document_bytes;END IF;
 SELECT convert_to(coalesce(jsonb_agg(jsonb_build_object('documentId',d.doc_id,'revision',d.doc_revision,
  'umfVersion',d.umf_version,'originalText',d.document,'validation',d.validation) ORDER BY d.ord),'[]'::jsonb)::text,'UTF8')
 INTO result FROM truss.schema_doc d WHERE d.rev=request.revision;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_retained_operation_frame(operation jsonb, result jsonb, original_revision text, original_basis jsonb, qualified_actor oid)
 RETURNS TABLE(document_id text, module text, historical_basis jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE identity jsonb;owner_document text;owner_module text;revision int;readers jsonb;dependency jsonb;
BEGIN
 identity:=result->'identity';
 IF result->>'operation' IS DISTINCT FROM operation->>'operation' OR jsonb_typeof(identity->'typeId') IS DISTINCT FROM 'string'
  THEN RAISE EXCEPTION 'retained operation identity required' USING ERRCODE='55000';END IF;
 IF operation->>'operation' IN ('create_object','update_object','delete_object') THEN
  SELECT t.document_id,t.module INTO STRICT owner_document,owner_module FROM truss.type_def t WHERE t.type_id=(identity->>'typeId')::int AND t.kind='record';
  revision:=original_revision::int;
  IF revision IS NULL OR revision<1 THEN RAISE EXCEPTION 'positive original executed revision required' USING ERRCODE='55000';END IF;
  SELECT s.value_readers INTO STRICT readers FROM truss.runtime_type_schema s
   WHERE s.rev=revision AND s.type_id=(identity->>'typeId')::int;
  FOR dependency IN SELECT value FROM jsonb_array_elements(readers) LOOP
   IF NOT truss.runtime_can_read_qualified(dependency->>'documentId',dependency->>'moduleId',qualified_actor) THEN
    RAISE EXCEPTION 'current retained property/item reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 ELSIF operation->>'operation' IN ('create_edge','update_edge','delete_edge') THEN
  SELECT r.document_id,r.module INTO STRICT owner_document,owner_module FROM truss.rel_def r WHERE r.rel_type_id=(identity->>'typeId')::int;
 ELSE RAISE EXCEPTION 'retained operation category required' USING ERRCODE='55000';END IF;
 IF identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',owner_document,'moduleId',owner_module) THEN
  RAISE EXCEPTION 'retained owner correspondence required' USING ERRCODE='55000';END IF;
 -- Preserve the private compatibility column without rebuilding a whole catalog.
 RETURN QUERY SELECT owner_document,owner_module,original_basis;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_row_validate_qualified(selected_id bigint, selected_type integer, qualified_actor oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
DECLARE latest record;rebind record;actual jsonb;keys jsonb;entry jsonb;current_actor oid;creation_transition bigint;owned_transition record;owner record;root_type int;physical_journal truss.journal%ROWTYPE;
BEGIN
 current_actor:=qualified_actor;
 -- Owned creation semantics settle with the complete group and mandatory
 -- attempt trigger. Keep the legacy creation path; current owned authority and
 -- actual row/key closure are independently checked below on every row event.
 FOR creation_transition IN SELECT t.transition_id FROM truss.runtime_object_transition t
  JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
  WHERE t.object_id=selected_id AND t.type_id=selected_type AND t.writer_xid=pg_current_xact_id()
   AND t.before_object IS NULL
   AND a.context->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile() LOOP
  PERFORM truss.runtime_create_transition_validate(creation_transition);
 END LOOP;
 -- Immutable transition semantics are checked at final group settlement and
 -- attempt commit. Row settlement independently rechecks current authority.
 FOR owned_transition IN
  SELECT t.operation_index,t.before_object,t.after_object,
   a.actor_oid AS original_actor,a.writer_xid AS original_writer,
   a.next_index AS original_next,
   CASE WHEN a.actor_oid IS NOT DISTINCT FROM current_actor
    AND a.writer_xid IS NOT DISTINCT FROM pg_current_xact_id()
    AND t.operation_index>=0 AND t.operation_index<a.next_index
    THEN a.result_count END AS original_result_count
  FROM truss.runtime_object_transition t JOIN truss.runtime_object_attempt a ON a.id=t.attempt_id
  WHERE t.object_id=selected_id AND t.type_id=selected_type AND t.writer_xid=pg_current_xact_id()
   AND a.context->'mutationProfile'=truss.runtime_owned_profile()
 LOOP
  IF owned_transition.original_actor IS DISTINCT FROM current_actor
   OR owned_transition.original_writer IS DISTINCT FROM pg_current_xact_id()
   OR owned_transition.operation_index<0 OR owned_transition.operation_index>=owned_transition.original_next
   OR owned_transition.original_result_count<>owned_transition.original_next THEN
   RAISE EXCEPTION 'original object operation progress and actor required' USING ERRCODE='55000';END IF;
  SELECT t.document_id,t.module INTO STRICT owner FROM truss.type_def t WHERE t.type_id=selected_type;
  PERFORM truss.runtime_module_writer_qualified(owner.document_id,owner.module,current_actor);
  IF NOT truss.runtime_object_values_readable_qualified(selected_type,current_actor) THEN RAISE EXCEPTION 'current original property readers required' USING ERRCODE='42501';END IF;
  FOR root_type IN SELECT DISTINCT (image->>'root_type')::int
   FROM jsonb_array_elements(jsonb_build_array(owned_transition.before_object,owned_transition.after_object)) images(image)
   WHERE image->>'root_type' IS NOT NULL LOOP
   SELECT t.document_id,t.module INTO STRICT owner FROM truss.type_def t WHERE t.type_id=root_type;
   IF NOT truss.runtime_can_read_qualified(owner.document_id,owner.module,current_actor) THEN RAISE EXCEPTION 'current historical root reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
 -- Later ordinary mutations cannot suppress original registration dependencies.
 FOR rebind IN SELECT * FROM truss.runtime_catalog_rebind_transition t WHERE t.object_id=selected_id AND t.type_id=selected_type AND t.writer_xid=pg_current_xact_id() LOOP
  IF rebind.actor_oid IS DISTINCT FROM current_actor OR NOT EXISTS(SELECT 1 FROM truss.catalog_registration_request r
   WHERE r.registration_id=rebind.registration_id AND r.revision=rebind.revision AND r.writer_xid=rebind.writer_xid
    AND r.actor_oid=current_actor AND r.actor_name=session_user::text) THEN RAISE EXCEPTION 'current original rebind registration required' USING ERRCODE='55000';END IF;
  PERFORM truss.runtime_module_writer((SELECT document_id FROM truss.type_def WHERE type_id=selected_type),(SELECT module FROM truss.type_def WHERE type_id=selected_type));
  PERFORM truss.catalog_rebind_transition_reader((SELECT t FROM truss.runtime_catalog_rebind_transition t WHERE t.transition_id=rebind.transition_id));
 END LOOP;
 FOR rebind IN SELECT * FROM truss.runtime_catalog_key_backfill t WHERE t.object_id=selected_id AND t.type_id=selected_type AND t.writer_xid=pg_current_xact_id() LOOP
  IF rebind.actor_oid IS DISTINCT FROM current_actor OR NOT EXISTS(SELECT 1 FROM truss.catalog_registration_request r
   WHERE r.registration_id=rebind.registration_id AND r.revision=rebind.revision AND r.writer_xid=rebind.writer_xid
    AND r.actor_oid=current_actor AND r.actor_name=session_user::text) THEN RAISE EXCEPTION 'current original key registration required' USING ERRCODE='55000';END IF;
  PERFORM truss.runtime_module_writer((SELECT document_id FROM truss.type_def WHERE type_id=selected_type),(SELECT module FROM truss.type_def WHERE type_id=selected_type));
  PERFORM truss.catalog_key_backfill_transition_reader((SELECT t FROM truss.runtime_catalog_key_backfill t WHERE t.transition_id=rebind.transition_id));
 END LOOP;
 SELECT * INTO latest FROM (
  SELECT transition_id,writer_xid,after_object,after_keys,attempt_id,NULL::uuid registration_id,'ordinary'::text transition_kind FROM truss.runtime_object_transition WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id()
  UNION ALL SELECT transition_id,writer_xid,after_object,after_keys,NULL::uuid,registration_id,'rebind'::text FROM truss.runtime_catalog_rebind_transition WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id()
  UNION ALL SELECT transition_id,writer_xid,object_image,after_keys,NULL::uuid,registration_id,'key_backfill'::text FROM truss.runtime_catalog_key_backfill WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id()) t ORDER BY transition_id DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'current registered object transition required' USING ERRCODE='55000';END IF;
 IF latest.registration_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM truss.catalog_registration_request r WHERE r.registration_id=latest.registration_id AND r.writer_xid=latest.writer_xid AND r.actor_oid=current_actor AND r.actor_name=session_user::text) THEN RAISE EXCEPTION 'current original registration owner required' USING ERRCODE='55000';END IF;
  PERFORM truss.runtime_module_writer((SELECT document_id FROM truss.type_def WHERE type_id=selected_type),(SELECT module FROM truss.type_def WHERE type_id=selected_type));
  IF latest.transition_kind='key_backfill' THEN
   PERFORM truss.catalog_key_backfill_transition_reader((SELECT t FROM truss.runtime_catalog_key_backfill t WHERE t.transition_id=latest.transition_id));
  ELSE PERFORM truss.catalog_rebind_transition_reader((SELECT t FROM truss.runtime_catalog_rebind_transition t WHERE t.transition_id=latest.transition_id));END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM truss.runtime_object_attempt WHERE id=latest.attempt_id AND writer_xid=latest.writer_xid AND actor_oid=current_actor) THEN RAISE EXCEPTION 'current mutation owner required' USING ERRCODE='55000';END IF;
 -- Current owned writes settle once at their mandatory attempt boundary.
 -- Their private transition carries no second physical key-row image.
 IF latest.transition_kind='ordinary' AND EXISTS(SELECT 1 FROM truss.runtime_object_attempt a
  WHERE a.id=latest.attempt_id AND a.complete AND a.context->'mutationProfile'=truss.runtime_owned_profile()) THEN RETURN;END IF;
 SELECT to_jsonb(o) INTO actual FROM truss.object o WHERE id=selected_id AND type_id=selected_type;
 SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY k.key_num),'[]'::jsonb) INTO keys FROM truss.object_key_bucket k WHERE k.object_id=selected_id AND k.type_id=selected_type;
 IF actual IS DISTINCT FROM latest.after_object OR keys IS DISTINCT FROM latest.after_keys THEN RAISE EXCEPTION 'exact final object/key state required' USING ERRCODE='55000';END IF;
 FOR entry IN SELECT j.value FROM (SELECT journal FROM truss.runtime_object_transition WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id() UNION ALL SELECT journal FROM truss.runtime_catalog_rebind_transition WHERE object_id=selected_id AND type_id=selected_type AND writer_xid=pg_current_xact_id()) t CROSS JOIN LATERAL jsonb_array_elements(t.journal) j LOOP
  SELECT * INTO physical_journal FROM truss.journal j WHERE j.at=(entry->>'at')::timestamptz AND j.seq=(entry->>'seq')::bigint;
  IF NOT FOUND OR (CASE WHEN entry ? 'referenceProfile'
   THEN entry IS DISTINCT FROM truss.runtime_owned_journal_reference(physical_journal)
   ELSE entry IS DISTINCT FROM to_jsonb(physical_journal) END) THEN
   RAISE EXCEPTION 'exact mutation journal required' USING ERRCODE='55000';END IF;
 END LOOP;
 -- Key encoding belongs to the trusted producer. Its exact checked rows are
 -- retained in after_keys and compared with current native membership above.
 -- Re-encoding every key at finish and again for each deferred row event repeats
 -- the producer's semantic work without adding a new relational guarantee.
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_step(selected_attempt uuid, selected_index integer, prepared_input jsonb DEFAULT NULL::jsonb, prepared_original bytea DEFAULT NULL::bytea, qualified_actor oid DEFAULT NULL::oid)
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
<<owned_step_body>>
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;plan jsonb;before_edges jsonb;before_nodes jsonb;mode text;entry record;prior jsonb;effect_mode text;
 primary_reference text;metadata jsonb;effect jsonb;primary_result jsonb;events jsonb:='[]';deleted jsonb:='[]';event_chunks jsonb[]:='{}'::jsonb[];deleted_chunks jsonb[]:='{}'::jsonb[];result jsonb;current_actor oid;changed_rows bigint;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt FOR UPDATE NOWAIT;
 current_actor:=coalesce(qualified_actor,truss.runtime_person(false));
 IF attempt.writer_xid IS DISTINCT FROM pg_current_xact_id() OR attempt.actor_oid IS DISTINCT FROM current_actor
  OR attempt.complete OR attempt.next_index IS DISTINCT FROM selected_index
  OR attempt.results<>'[]'::jsonb OR attempt.aliases<>'[]'::jsonb THEN
  RAISE EXCEPTION 'current ordered owned operation required' USING ERRCODE='55000';END IF;
 plan:=truss.runtime_owned_plan(selected_attempt,selected_index);mode:=plan->'operation'->>'operation';primary_reference:=plan->>'primary';
 IF mode NOT IN ('create_edge','update_edge','delete_edge','update_object','delete_object') THEN
  RAISE EXCEPTION 'selected original owned operation required' USING ERRCODE='55000';END IF;
 -- Cascade edges precede every endpoint deletion. No child effect advances the
 -- original attempt or adds a synthetic operation/result to its input.
 -- Extract each immutable before-map once; the final slot can contain the
 -- complete graph even when only one member changes.
 before_edges:=plan->'beforeEdges';
 FOR entry IN SELECT key,value FROM jsonb_each(plan->'afterEdges') e WHERE e.value IS DISTINCT FROM before_edges->e.key
  OR e.key=primary_reference AND mode='update_edge' ORDER BY key COLLATE "C" LOOP
  prior:=before_edges->entry.key;
  IF prior->'deleted'='true'::jsonb THEN CONTINUE;END IF;
  effect_mode:=CASE WHEN prior IS NULL THEN 'create_edge' WHEN entry.value->'deleted'='true'::jsonb THEN 'delete_edge' ELSE 'update_edge' END;
  metadata:=truss.runtime_owned_edge_metadata(selected_attempt,selected_index,entry.key,current_actor);
  effect:=convert_from(truss.runtime_edge_effect(selected_attempt,selected_index,metadata,effect_mode,false,current_actor,prepared_input,prepared_original),'UTF8')::jsonb;
  event_chunks[cardinality(event_chunks)+1]:=coalesce(effect->'events','[]'::jsonb);
  deleted_chunks[cardinality(deleted_chunks)+1]:=coalesce(effect->'deleted','[]'::jsonb);
  IF entry.key=primary_reference THEN primary_result:=effect;END IF;
 END LOOP;
 -- Aggregate-root FKs are immediate: remove nonroots before their root.
 before_nodes:=plan->'beforeNodes';
 FOR entry IN SELECT key,value FROM jsonb_each(plan->'afterNodes') n WHERE
  before_nodes ? n.key AND (n.value IS DISTINCT FROM before_nodes->n.key OR n.key=primary_reference AND mode='update_object')
  ORDER BY CASE WHEN before_nodes->n.key->'root'='null'::jsonb THEN 1 ELSE 0 END,key COLLATE "C" LOOP
  IF before_nodes->entry.key->'deleted'='true'::jsonb THEN CONTINUE;END IF;
  effect:=truss.runtime_owned_object_effect(selected_attempt,selected_index,entry.key,prepared_input,current_actor);
  event_chunks[cardinality(event_chunks)+1]:=coalesce(effect->'events','[]'::jsonb);
  deleted_chunks[cardinality(deleted_chunks)+1]:=coalesce(effect->'deleted','[]'::jsonb);
  IF entry.key=primary_reference THEN primary_result:=effect;END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(event.value ORDER BY chunk.ordinality,event.ordinality),'[]'::jsonb) INTO events
  FROM unnest(event_chunks) WITH ORDINALITY AS chunk(items,ordinality)
  CROSS JOIN LATERAL jsonb_array_elements(chunk.items) WITH ORDINALITY AS event(value,ordinality);
 SELECT coalesce(jsonb_agg(item.value ORDER BY chunk.ordinality,item.ordinality),'[]'::jsonb) INTO deleted
  FROM unnest(deleted_chunks) WITH ORDINALITY AS chunk(items,ordinality)
  CROSS JOIN LATERAL jsonb_array_elements(chunk.items) WITH ORDINALITY AS item(value,ordinality);
 IF primary_result IS NULL OR primary_result->>'operation' IS DISTINCT FROM mode THEN RAISE EXCEPTION 'one original primary result required' USING ERRCODE='55000';END IF;
 result:=jsonb_set(primary_result,'{events}',events);
 IF mode IN ('delete_object','delete_edge') THEN result:=jsonb_set(result,'{deleted}',deleted);END IF;
 IF octet_length(convert_to(result::text,'UTF8'))>16777216 THEN RAISE EXCEPTION 'bounded complete original result required' USING ERRCODE='54000';END IF;
 UPDATE truss.runtime_owned_operation p SET result=owned_step_body.result
  WHERE p.attempt_id=selected_attempt AND p.operation_index=selected_index
   AND p.writer_xid=attempt.writer_xid AND p.result IS NULL;
 GET DIAGNOSTICS changed_rows=ROW_COUNT;
 IF changed_rows<>1 THEN RAISE EXCEPTION 'one original owned result slot required' USING ERRCODE='55000';END IF;
 UPDATE truss.runtime_object_attempt a SET next_index=a.next_index+1
  WHERE a.id=selected_attempt AND a.writer_xid=attempt.writer_xid AND a.actor_oid=current_actor
   AND NOT a.complete AND a.next_index=selected_index AND a.results='[]'::jsonb AND a.aliases='[]'::jsonb;
 GET DIAGNOSTICS changed_rows=ROW_COUNT;
 IF changed_rows<>1 THEN RAISE EXCEPTION 'one ordered owned progress advance required' USING ERRCODE='55000';END IF;
 RETURN convert_to(result::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_aliases(workspace text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
 EXECUTE format('SELECT coalesce(jsonb_object_agg(member_ref,source_ref),''{}''::jsonb) FROM pg_temp.%I WHERE member_kind=''a''',workspace)
  INTO result;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_map(workspace text, member_kind character, operation_index integer, member_refs text[], before_image boolean DEFAULT false, full_payload_refs text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
 EXECUTE format('SELECT coalesce(jsonb_object_agg(w.member_ref,CASE WHEN $5 IS NULL OR full_payload.member_ref IS NOT NULL THEN CASE WHEN $4 AND w.before_operation=$3 THEN w.before_state ELSE w.state END ELSE CASE WHEN $4 AND w.before_operation=$3 THEN w.before_header_state ELSE w.header_state END END),''{}''::jsonb) FROM pg_temp.%I w LEFT JOIN unnest(coalesce($5,ARRAY[]::text[])) full_payload(member_ref) ON full_payload.member_ref=w.member_ref WHERE w.member_kind=$1 AND ($2 IS NULL OR w.member_ref=ANY($2)) AND (NOT $4 OR w.created_operation IS DISTINCT FROM $3)',workspace)
  INTO result USING member_kind,member_refs,operation_index,before_image,full_payload_refs;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_reference(reference jsonb, workspace text, member_kind character, operation_index integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE selected text;identity jsonb;selected_state jsonb;alias_operation int;
BEGIN
 IF jsonb_typeof(reference) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'explicit graph reference required' USING ERRCODE='22023';END IF;
 IF reference->>'state'='alias' THEN
  IF reference-ARRAY['state','alias']<>'{}'::jsonb OR jsonb_typeof(reference->'alias') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'closed prior alias required' USING ERRCODE='22023';END IF;
   EXECUTE format('SELECT source_ref,member_ordinal FROM pg_temp.%I WHERE member_kind=''a'' AND member_ref=$1',workspace)
   INTO selected,alias_operation USING reference->>'alias';
  IF selected IS NULL OR alias_operation>=operation_index THEN RAISE EXCEPTION 'existing reference of the correct kind required' USING ERRCODE='22023';END IF;
 ELSIF reference->>'state'='stored' THEN
  identity:=reference->'identity';
  IF reference-ARRAY['state','identity']<>'{}'::jsonb OR jsonb_typeof(identity) IS DISTINCT FROM 'object'
   OR identity-ARRAY['id','typeId','definitionPin','owner']<>'{}'::jsonb THEN
   RAISE EXCEPTION 'closed original stored reference required' USING ERRCODE='22023';END IF;
  selected:='stored:'||(identity->>'typeId')||':'||(identity->>'id');
 ELSE RAISE EXCEPTION 'stored or prior alias required' USING ERRCODE='22023';END IF;
 selected_state:=truss.runtime_owned_workspace_state(workspace,member_kind,selected,true);
 IF selected_state IS NULL THEN RAISE EXCEPTION 'existing reference of the correct kind required' USING ERRCODE='22023';END IF;
 IF selected_state->'deleted'='true'::jsonb THEN RAISE EXCEPTION 'referenced graph member deleted' USING ERRCODE='P1004';END IF;
 IF identity IS NOT NULL AND identity IS DISTINCT FROM selected_state->'identity' THEN
  RAISE EXCEPTION 'original qualified identity correspondence required' USING ERRCODE='22023';END IF;
 RETURN selected;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_state(workspace text, member_kind character, member_ref text, header_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
 EXECUTE format('SELECT CASE WHEN $3 THEN header_state ELSE state END FROM pg_temp.%I WHERE member_kind=$1 AND member_ref=$2',workspace) INTO result USING member_kind,member_ref,header_only;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_state_at(workspace text, member_kind character, member_ref text, operation_index integer, before_image boolean DEFAULT false, header_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
 EXECUTE format('SELECT CASE WHEN $4 AND created_operation=$3 THEN NULL WHEN $5 AND $4 AND before_operation=$3 THEN before_header_state WHEN $5 THEN header_state WHEN $4 AND before_operation=$3 THEN before_state ELSE state END FROM pg_temp.%I WHERE member_kind=$1 AND member_ref=$2',workspace)
  INTO result USING member_kind,member_ref,operation_index,before_image,header_only;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_state_at_or(workspace text, member_kind character, member_ref text, operation_index integer, before_image boolean, fallback_map jsonb, header_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
 IF workspace IS NULL THEN
  result:=fallback_map->member_ref;
  IF header_only AND result IS NOT NULL THEN RETURN jsonb_set(result,'{image}',((result->'image')-ARRAY['props','retained']));END IF;
  RETURN result;
 END IF;
 RETURN truss.runtime_owned_workspace_state_at(workspace,member_kind,member_ref,operation_index,before_image,header_only);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_state_or(workspace text, member_kind character, member_ref text, fallback_map jsonb, header_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
 IF workspace IS NULL THEN
  result:=fallback_map->member_ref;
  IF header_only AND result IS NOT NULL THEN RETURN jsonb_set(result,'{image}',((result->'image')-ARRAY['props','retained']));END IF;
  RETURN result;
 END IF;
 EXECUTE format('SELECT CASE WHEN $3 THEN header_state ELSE state END FROM pg_temp.%I WHERE member_kind=$1 AND member_ref=$2',workspace) INTO result USING member_kind,member_ref,header_only;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_owned_workspace_write(workspace text, member_kind character, member_ref text, operation_index integer, new_state jsonb, fallback_map jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF workspace IS NULL THEN RETURN coalesce(fallback_map,'{}'::jsonb)||jsonb_build_object(member_ref,new_state);END IF;
 PERFORM truss.runtime_owned_workspace_put(workspace,member_kind,member_ref,operation_index,new_state);
 RETURN fallback_map;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_peek_string_key_bucket(original_namespace bytea, canonical_key bytea)
 RETURNS bigint[]
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE namespace_route bytea;key_route bytea;candidate_count bigint;candidate_bytes bigint;members bigint[];
BEGIN
 IF original_namespace IS NULL OR octet_length(original_namespace) NOT BETWEEN 1 AND 65536
  OR canonical_key IS NULL OR octet_length(canonical_key) NOT BETWEEN 1 AND 1048576
  OR convert_from(canonical_key,'UTF8') !~ '^umf-key-tuple-v1:hex:([0-9a-f]{2})+$' THEN
  RAISE EXCEPTION 'bounded canonical key observation required' USING ERRCODE='22023';END IF;
 namespace_route:=sha256(original_namespace);key_route:=sha256(canonical_key);
 SELECT count(*),coalesce(sum(size),0) INTO candidate_count,candidate_bytes FROM (
  (SELECT octet_length(namespace_bytes)::bigint+octet_length(key_bytes) AS size
   FROM truss.object_key_bucket WHERE namespace_sha256=namespace_route AND key_sha256=key_route LIMIT 10001)
  UNION ALL
  (SELECT octet_length(namespace_bytes)::bigint+octet_length(key_bytes) AS size
   FROM truss.object_key_reservation_bucket WHERE namespace_sha256=namespace_route AND key_sha256=key_route LIMIT 10001)
 ) candidates;
 IF candidate_count>10000 OR candidate_bytes>16777216 THEN
  RAISE EXCEPTION 'complete collision bucket exceeds limits' USING ERRCODE='54000';END IF;
 SELECT coalesce(array_agg(storage_row_id ORDER BY storage_row_id),'{}'::bigint[]) INTO members
  FROM truss.object_key_bucket WHERE namespace_sha256=namespace_route AND key_sha256=key_route
   AND namespace_bytes=original_namespace AND key_bytes=canonical_key;
 RETURN members;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_preview_recheck_authority(inventory jsonb, qualified_actor oid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE entry jsonb;scope jsonb;
BEGIN
 IF jsonb_typeof(inventory) IS DISTINCT FROM 'array' OR qualified_actor IS NULL THEN
  RAISE EXCEPTION 'trusted preview inventory required' USING ERRCODE='55000';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(inventory) LOOP
  IF jsonb_typeof(entry->'scopes') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'complete preview scopes required' USING ERRCODE='55000';END IF;
  FOR scope IN SELECT value FROM jsonb_array_elements(entry->'scopes') LOOP
   IF jsonb_typeof(scope) IS DISTINCT FROM 'object'
    OR scope-ARRAY['documentId','moduleId']<>'{}'::jsonb
    OR jsonb_typeof(scope->'documentId') IS DISTINCT FROM 'string'
    OR jsonb_typeof(scope->'moduleId') IS DISTINCT FROM 'string'
    OR octet_length(scope->>'documentId') NOT BETWEEN 1 AND 4096
    OR octet_length(scope->>'moduleId') NOT BETWEEN 1 AND 4096 THEN
    RAISE EXCEPTION 'complete preview scope required' USING ERRCODE='55000';END IF;
   IF NOT truss.runtime_can_read_qualified(scope->>'documentId',scope->>'moduleId',qualified_actor) THEN
    RAISE EXCEPTION 'current preview owner read authority required' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_preview_truth_snapshot(input jsonb, documents jsonb, expected_release text, expected_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE selected truss.catalog_runtime_installation%ROWTYPE;inventory jsonb;observed jsonb;
 revision int;archive truss.schema_doc%ROWTYPE;original_source text;condition_entry jsonb;
BEGIN
 SELECT * INTO STRICT selected FROM truss.catalog_runtime_installation WHERE singleton;
 IF selected.release_id IS DISTINCT FROM expected_release OR selected.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected installed preview runtime required' USING ERRCODE='0A000';END IF;
 IF input-ARRAY['interfaceVersion','layoutProfile','mutationProfile','valueProfile','catalog','preconditions']<>'{}'::jsonb
  OR input->>'interfaceVersion' IS DISTINCT FROM 'truss-group-condition-preview/0.1.0'
  OR input->'catalog' IS DISTINCT FROM '{"selection":"current"}'::jsonb
  OR jsonb_typeof(input->'preconditions') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'selected current condition preview profile required' USING ERRCODE='0A000';END IF;
 IF jsonb_array_length(input->'preconditions')<1 THEN
  RAISE EXCEPTION 'nonempty condition preview required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(input->'preconditions')>3072 THEN
  RAISE EXCEPTION 'condition preview exceeds limits' USING ERRCODE='54000';END IF;
 IF input->'layoutProfile' IS DISTINCT FROM selected.layout_profile
  OR input->'mutationProfile' IS DISTINCT FROM truss.runtime_group_profiles()->'mutationProfile'
  OR input->'valueProfile' IS DISTINCT FROM truss.runtime_group_profiles()->'valueProfile' THEN
  RAISE EXCEPTION 'selected current condition preview profile required' USING ERRCODE='0A000';END IF;
 -- All catalog, source, and predicate reads below run under this one STABLE
 -- statement snapshot. Initial inventory keeps per-condition validation and
 -- authorization precedence; the VOLATILE wrapper rechecks the returned
 -- server-created scope inventory before exposing any result.
 inventory:=truss.runtime_condition_inventory_preview(input);
 FOR condition_entry IN SELECT value FROM jsonb_array_elements(input->'preconditions')
  WHERE value->>'condition'='key_absent' LOOP
  SELECT * INTO STRICT archive FROM truss.schema_doc
   WHERE doc_id=(SELECT selected_type.document_id FROM truss.type_def selected_type
    WHERE selected_type.type_id=(SELECT (entry.value->>'typeId')::int FROM jsonb_array_elements(inventory) entry
     WHERE entry.value->'condition'->>'id'=condition_entry->>'id'))
   ORDER BY rev DESC LIMIT 1;
  SELECT d.value->>'sourceText' INTO STRICT original_source FROM jsonb_array_elements(documents) d
   WHERE d.value->>'documentId'=archive.doc_id;
  IF convert_to(original_source,'UTF8') IS DISTINCT FROM convert_to(archive.document,'UTF8') THEN
   RAISE EXCEPTION 'exact original key condition source required' USING ERRCODE='22023';END IF;
 END LOOP;
 PERFORM truss.runtime_condition_inventory_preview(input);
 SELECT rev INTO STRICT revision FROM truss.schema_head WHERE id=1;
 IF revision<1 THEN RAISE EXCEPTION 'accepted preview catalog required' USING ERRCODE='0A000';END IF;
 observed:=truss.runtime_evaluate_preconditions_preview(input);
 RETURN jsonb_build_object('inventory',inventory,'conditions',observed->'conditions',
  'catalogRevision',revision::text,'snapshot',pg_current_snapshot()::text,
  'sourceEpoch',selected.source_epoch::text,'releaseId',selected.release_id,
  'releaseSha256',selected.release_sha256,'layoutProfile',selected.layout_profile);
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_receipt_can_read(selected_attempt uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;input jsonb;operation jsonb;owner record;entry jsonb;index int:=0;
 retained_result jsonb;identity jsonb;original_revision text;selected_revision text;current_actor oid;retained_frame record;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 IF attempt.context->'mutationProfile'=truss.runtime_owned_profile() THEN
  IF NOT attempt.complete THEN RETURN false;END IF;
  -- Read the retained indexed results and compiled historical dependencies once.
  -- Receipt/source observation must not decode the entire group for each member.
  FOR owner IN
   WITH selected_types AS MATERIALIZED (
    SELECT DISTINCT (p.plan->>'catalogRevision')::int rev,(p.result->'identity'->>'typeId')::int type_id
    FROM truss.runtime_owned_operation p WHERE p.attempt_id=selected_attempt
     AND p.result->>'operation' IN ('create_object','update_object','delete_object')),
   schemas AS MATERIALIZED (
    SELECT s.value_readers,s.type_id FROM selected_types t LEFT JOIN truss.runtime_type_schema s USING(rev,type_id)),
   dependencies AS (
    SELECT p.result->'identity'->'owner'->>'documentId' document_id,p.result->'identity'->'owner'->>'moduleId' module
    FROM truss.runtime_owned_operation p WHERE p.attempt_id=selected_attempt
    UNION ALL SELECT r.value->>'documentId',r.value->>'moduleId' FROM schemas s
     CROSS JOIN LATERAL jsonb_array_elements(s.value_readers) r
    UNION ALL SELECT NULL::text,NULL::text FROM schemas WHERE type_id IS NULL
    UNION ALL SELECT i.value->'owner'->>'documentId',i.value->'owner'->>'moduleId'
    FROM truss.runtime_edge_transition t CROSS JOIN LATERAL jsonb_array_elements(
     jsonb_build_array(t.old_source,t.old_target,t.source_identity,t.target_identity)) i
    WHERE t.attempt_id=selected_attempt AND i.value<>'null'::jsonb)
   SELECT DISTINCT document_id,module FROM dependencies
  LOOP
   IF owner.document_id IS NULL OR owner.module IS NULL OR NOT truss.runtime_can_read(owner.document_id,owner.module) THEN RETURN false;END IF;
  END LOOP;
  RETURN true;
 END IF;
 input:=convert_from(attempt.input_bytes,'UTF8')::jsonb;
 IF NOT attempt.complete OR attempt.result_count<>attempt.next_index THEN
  RAISE EXCEPTION 'complete retained operation required' USING ERRCODE='55000';END IF;
 current_actor:=truss.runtime_person(false);
 IF attempt.expected_receipt IS NOT NULL THEN
  original_revision:=(convert_from(decode(substr(attempt.expected_receipt->>'original_receipt_bytes',3),'hex'),'UTF8')::jsonb)->'semantic'->>'executedCatalogRevision';
 END IF;
 -- Legacy rows have no indexed operation ledger. Decode their bounded input
 -- once, then use the same retained frame with indexed revision/type readers.
 FOR retained_frame IN
  SELECT o.value original_operation,r.value original_result
  FROM jsonb_array_elements(input->'operations') WITH ORDINALITY o(value,ordinal)
  LEFT JOIN jsonb_array_elements(attempt.results) WITH ORDINALITY r(value,ordinal) USING(ordinal)
  ORDER BY o.ordinal
 LOOP
  operation:=retained_frame.original_operation;retained_result:=retained_frame.original_result;
  IF index>=attempt.next_index THEN RAISE EXCEPTION 'complete retained operation required' USING ERRCODE='55000';END IF;
  identity:=retained_result->'identity';selected_revision:=original_revision;
  IF selected_revision IS NULL AND operation->>'operation'='create_object' THEN
   IF attempt.context->'creationTransitionProfile'='{"identity":"truss-unified-create-transition","version":"0.2","sha256":"073782e2517f2a7e26c8d6479c6266ececf68963681ccfb6a380e9cd16f2e11b"}'::jsonb THEN
    SELECT t.after_object->>'rev' INTO STRICT selected_revision FROM truss.runtime_object_transition t
     WHERE t.attempt_id=attempt.id AND t.operation_index=index AND t.before_object IS NULL;
   ELSE
    SELECT g.expected_members->m.operation_index->'object'->>'rev' INTO STRICT selected_revision
     FROM truss.runtime_create_member m JOIN truss.runtime_create_group g ON g.group_id=m.group_id
     WHERE m.object_id=(identity->>'id')::bigint AND m.type_id=(identity->>'typeId')::int AND g.writer_xid=attempt.writer_xid;
   END IF;
  END IF;
  BEGIN
   SELECT * INTO STRICT owner FROM truss.runtime_owned_retained_operation_frame(operation,retained_result,selected_revision,NULL,current_actor);
  EXCEPTION WHEN insufficient_privilege THEN RETURN false;
  END;
  IF NOT truss.runtime_can_read_qualified(owner.document_id,owner.module,current_actor) THEN RETURN false;END IF;
  index:=index+1;
 END LOOP;
 FOR entry IN SELECT DISTINCT i.value FROM truss.runtime_edge_transition t
  CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(t.old_source,t.old_target,t.source_identity,t.target_identity)) i
  WHERE t.attempt_id=selected_attempt AND i.value<>'null'::jsonb LOOP
  IF NOT truss.runtime_can_read(entry->'owner'->>'documentId',entry->'owner'->>'moduleId') THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_receipt_refusal(selected_attempt uuid, reason text)
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF NOT truss.runtime_receipt_can_read(selected_attempt) THEN RETURN convert_to('{"outcome":"unavailable","reason":"observation_integrity"}','UTF8');END IF;
 RETURN convert_to(jsonb_build_object('outcome','unavailable','reason',reason)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_record_import_load(invocation uuid, chunk_no integer, total_no integer, selected_load_id text, origin_value jsonb, input_sha text, original_count integer, original_records jsonb, chunk_records jsonb, chunk_outcomes jsonb, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE actor oid;actor_name text;installation truss.catalog_runtime_installation%ROWTYPE;
 record_entry jsonb;record_value jsonb;outcome_entry jsonb;index_value text;kind_value text;
 owners jsonb:='[]'::jsonb;owner_entry jsonb;all_entries jsonb:='[]'::jsonb;identity_value jsonb;
 payload_digest text;payload_profile jsonb;group_attempt uuid;count_entries int;ordinal int:=0;
 origin_sha text;projected_identity jsonb;owner_inventory_complete boolean:=true;
 selected_type truss.type_def%ROWTYPE;selected_property truss.prop_def%ROWTYPE;type_metadata jsonb;
 prior truss.runtime_import_load_chunk%ROWTYPE;existing boolean;
BEGIN
 actor:=truss.runtime_person(false);
 SELECT r.rolname INTO actor_name FROM pg_catalog.pg_roles r WHERE r.oid=actor;
 IF actor_name IS NULL THEN RAISE EXCEPTION 'original native initiator name unavailable' USING ERRCODE='P1010';END IF;
 origin_sha:=encode(sha256(convert_to(origin_value::text,'UTF8')),'hex');
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest
  OR invocation IS NULL OR chunk_no IS NULL OR total_no IS NULL OR chunk_no<0 OR total_no NOT BETWEEN 1 AND 1024 OR chunk_no>=total_no
  OR selected_load_id IS NULL OR octet_length(selected_load_id) NOT BETWEEN 1 AND 4096
  OR origin_value IS NULL OR jsonb_typeof(origin_value) IS DISTINCT FROM 'object'
  OR input_sha IS NULL OR input_sha !~ '^[0-9a-f]{64}$'
  OR original_count IS NULL OR original_count NOT BETWEEN 0 AND 1024
  OR jsonb_typeof(original_records) IS DISTINCT FROM 'array'
  OR jsonb_array_length(original_records)<>original_count
  OR jsonb_typeof(chunk_records) IS DISTINCT FROM 'array'
  OR jsonb_typeof(chunk_outcomes) IS DISTINCT FROM 'array'
  OR jsonb_array_length(chunk_records)<>jsonb_array_length(chunk_outcomes)
  OR jsonb_array_length(chunk_records)>128 THEN
  RAISE EXCEPTION 'bounded exact original import load required' USING ERRCODE='22023';END IF;
 IF octet_length(convert_to(origin_value::text,'UTF8'))>1048576 THEN
  RAISE EXCEPTION 'original asserted import origin exceeds retained limit' USING ERRCODE='54000';END IF;

 -- Derive owner scope from every exact original record, including rejected or
 -- skipped records and siblings in later chunks. Unknown/malformed scope blocks
 -- audit rather than authorizing a partial prefix.
 FOR record_value IN SELECT value FROM jsonb_array_elements(original_records) LOOP
  BEGIN
  IF jsonb_typeof(record_value) IS DISTINCT FROM 'object' OR record_value-ARRAY['kind','identity','payload','payloadProfile']<>'{}'::jsonb
   OR record_value->>'kind' NOT IN ('object','edge') OR jsonb_typeof(record_value->'identity') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'complete original load identity required' USING ERRCODE='22023';END IF;
  kind_value:=record_value->>'kind';identity_value:=record_value->'identity';
  IF kind_value='object' THEN
   IF jsonb_typeof(identity_value->'type') IS DISTINCT FROM 'object'
    OR jsonb_typeof(identity_value->'type'->'typeId') IS DISTINCT FROM 'string'
    OR jsonb_typeof(identity_value->'type'->'definitionPin') IS DISTINCT FROM 'string'
    OR jsonb_typeof(identity_value->'type'->'owner') IS DISTINCT FROM 'object'
    OR identity_value->'type'->>'typeId' !~ '^[1-9][0-9]{0,9}$'
    OR length(identity_value->'type'->>'typeId')=10
      AND identity_value->'type'->>'typeId' COLLATE pg_catalog."C">'2147483647' THEN
    RAISE EXCEPTION 'complete original object owner required' USING ERRCODE='22023';END IF;
   owner_entry:=identity_value->'type'->'owner';
   IF owner_entry-ARRAY['documentId','moduleId']<>'{}'::jsonb OR jsonb_typeof(owner_entry->'documentId') IS DISTINCT FROM 'string'
    OR jsonb_typeof(owner_entry->'moduleId') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'complete qualified object owner required' USING ERRCODE='22023';END IF;
   SELECT t.* INTO selected_type FROM truss.type_def t JOIN truss.runtime_definition_source d
    ON d.rev=t.definition_rev AND d.ord=t.definition_doc_ord AND d.doc_id=t.definition_document_id
     AND d.module_id=t.module AND d.element_id=t.element AND d.kind='element' AND d.key_id=''
    WHERE t.type_id=(identity_value->'type'->>'typeId')::int AND t.kind='record' AND NOT t.provisional
     AND t.retired_rev IS NULL AND d.definition_pin=identity_value->'type'->>'definitionPin';
   IF NOT FOUND OR owner_entry IS DISTINCT FROM jsonb_build_object('documentId',selected_type.document_id,'moduleId',selected_type.module) THEN
    RAISE EXCEPTION 'exact original type owner required' USING ERRCODE='22023';END IF;
   owners:=owners||jsonb_build_array(owner_entry);
   -- Include all declaration/item owners reachable through this type. This is
   -- a conservative historical union and prevents metadata disclosure when an
   -- imported value depends on a hidden property module.
   FOR owner_entry IN SELECT DISTINCT jsonb_build_object('documentId',selected_type.document_id,'moduleId',p.declaration_module)
    FROM truss.prop_def p WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL LOOP
    owners:=owners||jsonb_build_array(owner_entry);
   END LOOP;
   FOR owner_entry IN SELECT DISTINCT jsonb_build_object('documentId',node.value->>'documentId',
     'moduleId',node.value->'reference'->>'module')
    FROM truss.prop_def p CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(p.item)||coalesce(p.item->'descendants','[]'::jsonb)) node(value)
    WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL AND node.value ? 'reference' LOOP
    IF owner_entry->>'documentId' IS NULL OR owner_entry->>'moduleId' IS NULL THEN
     RAISE EXCEPTION 'complete item owner required' USING ERRCODE='22023';END IF;
    owners:=owners||jsonb_build_array(owner_entry);
   END LOOP;
   SELECT s.metadata INTO type_metadata FROM truss.runtime_type_schema s
    WHERE s.rev=(SELECT rev FROM truss.schema_head WHERE id=1) AND s.type_id=selected_type.type_id;
   IF NOT FOUND OR jsonb_typeof(type_metadata->'propertyAccess') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'complete original object property scope required' USING ERRCODE='22023';END IF;
   FOR owner_entry IN SELECT reader.value FROM jsonb_each(type_metadata->'propertyAccess') property
    CROSS JOIN LATERAL jsonb_array_elements(property.value->'readers') reader(value) LOOP
    IF jsonb_typeof(owner_entry) IS DISTINCT FROM 'object' OR owner_entry-ARRAY['documentId','moduleId']<>'{}'::jsonb THEN
     RAISE EXCEPTION 'complete original object reader required' USING ERRCODE='22023';END IF;
    owners:=owners||jsonb_build_array(owner_entry);
   END LOOP;
  ELSE
   FOR ordinal IN 1..2 LOOP
    IF ordinal=1 THEN owner_entry:=identity_value->'source'->'owner';
    ELSE owner_entry:=identity_value->'target'->'owner';END IF;
    IF jsonb_typeof(owner_entry) IS DISTINCT FROM 'object' OR owner_entry-ARRAY['documentId','moduleId']<>'{}'::jsonb
     OR jsonb_typeof(owner_entry->'documentId') IS DISTINCT FROM 'string' OR jsonb_typeof(owner_entry->'moduleId') IS DISTINCT FROM 'string' THEN
     RAISE EXCEPTION 'complete edge endpoint owner required' USING ERRCODE='22023';END IF;
    IF ordinal=1 AND (jsonb_typeof(identity_value->'source'->'typeId') IS DISTINCT FROM 'string'
      OR identity_value->'source'->>'typeId' !~ '^[1-9][0-9]{0,9}$'
      OR length(identity_value->'source'->>'typeId')=10
       AND identity_value->'source'->>'typeId' COLLATE pg_catalog."C">'2147483647')
     OR ordinal=2 AND (jsonb_typeof(identity_value->'target'->'typeId') IS DISTINCT FROM 'string'
      OR identity_value->'target'->>'typeId' !~ '^[1-9][0-9]{0,9}$'
      OR length(identity_value->'target'->>'typeId')=10
       AND identity_value->'target'->>'typeId' COLLATE pg_catalog."C">'2147483647') THEN
     RAISE EXCEPTION 'bounded original edge endpoint type id required' USING ERRCODE='22023';END IF;
    IF ordinal=1 THEN SELECT t.* INTO selected_type FROM truss.type_def t JOIN truss.runtime_definition_source d
      ON d.rev=t.definition_rev AND d.ord=t.definition_doc_ord AND d.doc_id=t.definition_document_id AND d.module_id=t.module AND d.element_id=t.element
       AND d.kind='element' AND d.key_id='' WHERE t.type_id=(identity_value->'source'->'typeId')::int
       AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL AND d.definition_pin=identity_value->'source'->>'definitionPin';
    ELSE SELECT t.* INTO selected_type FROM truss.type_def t JOIN truss.runtime_definition_source d
      ON d.rev=t.definition_rev AND d.ord=t.definition_doc_ord AND d.doc_id=t.definition_document_id AND d.module_id=t.module AND d.element_id=t.element
       AND d.kind='element' AND d.key_id='' WHERE t.type_id=(identity_value->'target'->'typeId')::int
       AND t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL AND d.definition_pin=identity_value->'target'->>'definitionPin';END IF;
    IF NOT FOUND OR owner_entry IS DISTINCT FROM jsonb_build_object('documentId',selected_type.document_id,'moduleId',selected_type.module) THEN
     RAISE EXCEPTION 'exact original edge endpoint owner required' USING ERRCODE='22023';END IF;
    owners:=owners||jsonb_build_array(owner_entry);
    FOR owner_entry IN SELECT DISTINCT jsonb_build_object('documentId',selected_type.document_id,'moduleId',p.declaration_module)
     FROM truss.prop_def p WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL LOOP
     owners:=owners||jsonb_build_array(owner_entry);
    END LOOP;
    SELECT s.metadata INTO type_metadata FROM truss.runtime_type_schema s
     WHERE s.rev=(SELECT rev FROM truss.schema_head WHERE id=1) AND s.type_id=selected_type.type_id;
    IF NOT FOUND OR jsonb_typeof(type_metadata->'propertyAccess') IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'complete original endpoint property scope required' USING ERRCODE='22023';END IF;
    FOR owner_entry IN SELECT reader.value FROM jsonb_each(type_metadata->'propertyAccess') property
     CROSS JOIN LATERAL jsonb_array_elements(property.value->'readers') reader(value) LOOP
     IF jsonb_typeof(owner_entry) IS DISTINCT FROM 'object' OR owner_entry-ARRAY['documentId','moduleId']<>'{}'::jsonb THEN
      RAISE EXCEPTION 'complete original endpoint reader required' USING ERRCODE='22023';END IF;
     owners:=owners||jsonb_build_array(owner_entry);
    END LOOP;
   END LOOP;
   SELECT t.* INTO selected_type
    FROM truss.runtime_definition_source d JOIN truss.rel_def r
     ON r.definition_rev=d.rev AND r.definition_doc_ord=d.ord AND r.definition_document_id=d.doc_id
      AND r.module=d.module_id AND r.rel_id=d.element_id
    JOIN truss.type_def t ON t.type_id=r.assoc_type_id
    WHERE d.definition_pin=identity_value->>'relationshipDefinitionPin' AND d.kind='relationship'
     AND r.retired_rev IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'complete original relationship owner required' USING ERRCODE='22023';END IF;
   owner_entry:=jsonb_build_object('documentId',selected_type.document_id,'moduleId',selected_type.module);
   owners:=owners||jsonb_build_array(owner_entry);
   FOR owner_entry IN SELECT DISTINCT jsonb_build_object('documentId',selected_type.document_id,'moduleId',p.declaration_module)
    FROM truss.prop_def p WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL LOOP
    owners:=owners||jsonb_build_array(owner_entry);
   END LOOP;
   SELECT s.metadata INTO type_metadata FROM truss.runtime_type_schema s
    WHERE s.rev=(SELECT rev FROM truss.schema_head WHERE id=1) AND s.type_id=selected_type.type_id;
   IF NOT FOUND OR jsonb_typeof(type_metadata->'propertyAccess') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'complete original association property scope required' USING ERRCODE='22023';END IF;
   FOR owner_entry IN SELECT reader.value FROM jsonb_each(type_metadata->'propertyAccess') property
    CROSS JOIN LATERAL jsonb_array_elements(property.value->'readers') reader(value) LOOP
    IF jsonb_typeof(owner_entry) IS DISTINCT FROM 'object' OR owner_entry-ARRAY['documentId','moduleId']<>'{}'::jsonb THEN
     RAISE EXCEPTION 'complete original association reader required' USING ERRCODE='22023';END IF;
    owners:=owners||jsonb_build_array(owner_entry);
   END LOOP;
  END IF;
  EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '22P02' THEN
   owner_inventory_complete:=false;
  END;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'documentId',value->>'moduleId'),'[]'::jsonb) INTO owners
  FROM (SELECT DISTINCT value FROM jsonb_array_elements(owners)) unique_owner;
 IF jsonb_array_length(owners)>4096 THEN RAISE EXCEPTION 'load owner scope resource limit' USING ERRCODE='54000';END IF;

 FOR record_entry,outcome_entry IN SELECT r.value,o.value FROM jsonb_array_elements(chunk_records) WITH ORDINALITY r(value,ord)
  JOIN jsonb_array_elements(chunk_outcomes) WITH ORDINALITY o(value,ord) USING(ord) LOOP
  IF jsonb_typeof(record_entry) IS DISTINCT FROM 'object' OR record_entry-ARRAY['inputIndex','record']<>'{}'::jsonb
   OR jsonb_typeof(record_entry->'inputIndex') IS DISTINCT FROM 'string' OR jsonb_typeof(record_entry->'record') IS DISTINCT FROM 'object'
   OR jsonb_typeof(outcome_entry) IS DISTINCT FROM 'object' OR outcome_entry-ARRAY['inputIndex','outcome','groupAttemptId','identity','version','reason','code','path']<>'{}'::jsonb
   OR outcome_entry->>'inputIndex' IS DISTINCT FROM record_entry->>'inputIndex'
   OR outcome_entry->>'outcome' NOT IN ('created','skipped','rejected') THEN
   RAISE EXCEPTION 'exact chunk record and outcome pair required' USING ERRCODE='22023';END IF;
  index_value:=record_entry->>'inputIndex';
  IF index_value !~ '^(0|[1-9][0-9]{0,3})$' OR index_value::int>1023 OR index_value::int>=original_count THEN RAISE EXCEPTION 'canonical original load index required' USING ERRCODE='22023';END IF;
  record_value:=record_entry->'record';kind_value:=record_value->>'kind';identity_value:=record_value->'identity';
  payload_digest:=record_value->'payload'->>'sha256';payload_profile:=record_value->'payloadProfile';
  IF kind_value NOT IN ('object','edge') OR jsonb_typeof(identity_value) IS DISTINCT FROM 'object'
   OR jsonb_typeof(record_value->'payload') IS DISTINCT FROM 'object'
   OR jsonb_typeof(payload_profile) IS DISTINCT FROM 'object'
   OR payload_digest IS NULL OR payload_digest !~ '^[0-9a-f]{64}$'
   OR payload_profile-ARRAY['identity','version','sha256']<>'{}'::jsonb
   OR jsonb_typeof(payload_profile->'identity') IS DISTINCT FROM 'string' OR jsonb_typeof(payload_profile->'version') IS DISTINCT FROM 'string'
   OR jsonb_typeof(payload_profile->'sha256') IS DISTINCT FROM 'string' THEN
   owner_inventory_complete:=false;kind_value:='unknown';payload_digest:='';payload_profile:='{}'::jsonb;
   identity_value:=jsonb_build_object('kind','unknown');
  END IF;
  group_attempt:=NULL;
  IF outcome_entry->>'outcome'='created' THEN
   IF jsonb_typeof(outcome_entry->'groupAttemptId') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'created import attempt reference required' USING ERRCODE='22023';END IF;
   group_attempt:=(outcome_entry->>'groupAttemptId')::uuid;
   IF NOT EXISTS(SELECT 1 FROM truss.runtime_object_attempt a WHERE a.id=group_attempt AND a.complete)
    OR NOT EXISTS(SELECT 1 FROM truss.runtime_import_source s WHERE s.group_attempt_id=group_attempt) THEN
    RAISE EXCEPTION 'created native source ledger reference required' USING ERRCODE='22023';END IF;
  ELSIF outcome_entry ? 'groupAttemptId' THEN RAISE EXCEPTION 'only created outcomes have attempt reference' USING ERRCODE='22023';END IF;
  IF kind_value='object' THEN
   projected_identity:=jsonb_build_object('kind','object','typeId',identity_value->'type'->>'typeId',
    'definitionPin',identity_value->'type'->>'definitionPin','owner',identity_value->'type'->'owner',
    'keyNumber',identity_value->>'keyNumber','keyDefinitionPin',identity_value->>'keyDefinitionPin');
  ELSIF kind_value='edge' THEN
   projected_identity:=jsonb_build_object('kind','edge','relationshipDefinitionPin',identity_value->>'relationshipDefinitionPin',
    'source',jsonb_build_object('id',identity_value->'source'->>'id','typeId',identity_value->'source'->>'typeId',
     'definitionPin',identity_value->'source'->>'definitionPin','owner',identity_value->'source'->'owner'),
    'target',jsonb_build_object('id',identity_value->'target'->>'id','typeId',identity_value->'target'->>'typeId',
     'definitionPin',identity_value->'target'->>'definitionPin','owner',identity_value->'target'->'owner'));
  ELSE
   projected_identity:=jsonb_build_object('kind','unknown');
  END IF;
  all_entries:=all_entries||jsonb_build_array(jsonb_build_object(
   'inputIndex',index_value,'outcome',outcome_entry->>'outcome','recordKind',kind_value,
   'identity',projected_identity,'payloadProfile',payload_profile,'payloadSha256',payload_digest,
   'groupAttemptId',group_attempt));
 END LOOP;
 count_entries:=jsonb_array_length(all_entries);
 IF count_entries<>jsonb_array_length(chunk_records) THEN RAISE EXCEPTION 'complete chunk audit report required' USING ERRCODE='22023';END IF;
 SELECT * INTO prior FROM truss.runtime_import_load_chunk WHERE invocation_id=runtime_record_import_load.invocation
  ORDER BY chunk_index LIMIT 1;
  IF FOUND AND (prior.load_id IS DISTINCT FROM selected_load_id OR prior.original_asserted_origin IS DISTINCT FROM origin_value
  OR prior.asserted_origin_sha256 IS DISTINCT FROM origin_sha
  OR prior.input_sha256 IS DISTINCT FROM input_sha OR prior.input_count IS DISTINCT FROM original_count
  OR prior.total_chunks IS DISTINCT FROM total_no OR prior.native_actor IS DISTINCT FROM actor
  OR prior.native_actor_name IS DISTINCT FROM actor_name
  OR prior.original_owners IS DISTINCT FROM owners OR prior.owner_inventory_complete IS DISTINCT FROM owner_inventory_complete) THEN
  RAISE EXCEPTION 'conflicting original load invocation' USING ERRCODE='23505';END IF;
 SELECT * INTO prior FROM truss.runtime_import_load_chunk WHERE invocation_id=runtime_record_import_load.invocation
  AND chunk_index=chunk_no;
 IF FOUND THEN
  IF prior.total_chunks IS DISTINCT FROM total_no OR prior.load_id IS DISTINCT FROM selected_load_id
   OR prior.original_asserted_origin IS DISTINCT FROM origin_value
   OR prior.asserted_origin_sha256 IS DISTINCT FROM origin_sha OR prior.input_sha256 IS DISTINCT FROM input_sha
   OR prior.input_count IS DISTINCT FROM original_count OR prior.original_owners IS DISTINCT FROM owners
   OR prior.owner_inventory_complete IS DISTINCT FROM owner_inventory_complete
   OR prior.entries IS DISTINCT FROM all_entries OR prior.native_actor IS DISTINCT FROM actor
   OR prior.native_actor_name IS DISTINCT FROM actor_name THEN
   RAISE EXCEPTION 'conflicting repeated import load chunk' USING ERRCODE='23505';END IF;
 ELSE
  INSERT INTO truss.runtime_import_load_chunk(invocation_id,chunk_index,total_chunks,load_id,original_asserted_origin,asserted_origin_sha256,input_sha256,
   input_count,original_owners,owner_inventory_complete,entries,native_actor,native_actor_name,writer_xid)
  VALUES(invocation,chunk_no,total_no,selected_load_id,origin_value,origin_sha,input_sha,original_count,owners,owner_inventory_complete,all_entries,actor,actor_name,pg_current_xact_id());
 END IF;
 PERFORM truss.runtime_person(false);
 RETURN convert_to(jsonb_build_object('outcome','recorded','chunkIndex',chunk_no::text)::text,'UTF8');
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_relationship_pin(selected_relationship integer, historical_revision integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE relation truss.rel_def%ROWTYPE;archive truss.schema_doc%ROWTYPE;module_json json;fragment json;mi int;ri int;pointer text;original bytea;pin_input text;
BEGIN
 IF historical_revision IS NULL THEN
  SELECT * INTO STRICT relation FROM truss.rel_def WHERE rel_type_id=selected_relationship AND retired_rev IS NULL;
 ELSE
  SELECT r.* INTO relation FROM truss.rel_def r
   WHERE r.rel_type_id=selected_relationship
    AND historical_revision=(SELECT rev FROM truss.schema_head WHERE id=1)
    AND NOT EXISTS(SELECT 1 FROM truss.schema_rev WHERE rev>historical_revision);
  IF NOT FOUND THEN
   SELECT * INTO STRICT relation FROM jsonb_populate_recordset(NULL::truss.rel_def,truss.catalog_all_expected_records(historical_revision)->'rel_def') r WHERE r.rel_type_id=selected_relationship;
  END IF;
 END IF;
 SELECT d.definition_pin INTO STRICT pin_input FROM truss.runtime_definition_source d
 WHERE d.rev=relation.definition_rev AND d.ord=relation.definition_doc_ord AND d.doc_id=relation.definition_document_id
  AND d.module_id=relation.module AND d.element_id=relation.rel_id AND d.kind='relationship' AND d.key_id='';
 RETURN pin_input;
END;
$function$

CREATE OR REPLACE FUNCTION truss.runtime_retained_operation_owner(selected_attempt uuid, operation_index integer)
 RETURNS TABLE(document_id text, module text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE attempt truss.runtime_object_attempt%ROWTYPE;operation jsonb;result jsonb;identity jsonb;owner_document text;owner_module text;revision int;readers jsonb;dependency jsonb;current_actor oid;
BEGIN
 SELECT * INTO STRICT attempt FROM truss.runtime_object_attempt WHERE id=selected_attempt;
 IF NOT attempt.complete OR operation_index<0 OR operation_index>=attempt.next_index
  OR jsonb_array_length(attempt.results)<>attempt.next_index THEN RAISE EXCEPTION 'complete retained operation required' USING ERRCODE='55000';END IF;
 operation:=convert_from(attempt.input_bytes,'UTF8')::jsonb->'operations'->operation_index;
 result:=attempt.results->operation_index;identity:=result->'identity';
 IF result->>'operation' IS DISTINCT FROM operation->>'operation' OR jsonb_typeof(identity->'typeId') IS DISTINCT FROM 'string'
  THEN RAISE EXCEPTION 'retained operation identity required' USING ERRCODE='55000';END IF;
 IF operation->>'operation' IN ('create_object','update_object','delete_object') THEN
  SELECT t.document_id,t.module INTO STRICT owner_document,owner_module FROM truss.type_def t WHERE t.type_id=(identity->>'typeId')::int AND t.kind='record';
  IF attempt.expected_receipt IS NOT NULL THEN
   revision:=((convert_from(decode(substr(attempt.expected_receipt->>'original_receipt_bytes',3),'hex'),'UTF8')::jsonb)->'semantic'->>'executedCatalogRevision')::int;
  ELSIF attempt.context->'mutationProfile'=truss.runtime_owned_profile() AND operation->>'operation'<>'create_object' THEN
   SELECT (p.plan->>'catalogRevision')::int INTO STRICT revision FROM truss.runtime_owned_operation p
    WHERE p.attempt_id=attempt.id AND p.operation_index=runtime_retained_operation_owner.operation_index;
  END IF;
  IF attempt.expected_receipt IS NULL AND operation->>'operation'='create_object' THEN
   IF attempt.context->'creationTransitionProfile'='{"identity":"truss-unified-create-transition","version":"0.2","sha256":"073782e2517f2a7e26c8d6479c6266ececf68963681ccfb6a380e9cd16f2e11b"}'::jsonb THEN
    SELECT (t.after_object->>'rev')::int INTO STRICT revision FROM truss.runtime_object_transition t
     WHERE t.attempt_id=attempt.id AND t.operation_index=runtime_retained_operation_owner.operation_index AND t.before_object IS NULL;
   ELSE
   SELECT (g.expected_members->m.operation_index->'object'->>'rev')::int INTO STRICT revision FROM truss.runtime_create_member m JOIN truss.runtime_create_group g ON g.group_id=m.group_id WHERE m.object_id=(identity->>'id')::bigint AND m.type_id=(identity->>'typeId')::int AND g.writer_xid=attempt.writer_xid;
   END IF;
  END IF;
  IF revision IS NULL OR revision<1 THEN RAISE EXCEPTION 'positive original executed revision required' USING ERRCODE='55000';END IF;
  SELECT s.value_readers INTO STRICT readers FROM truss.runtime_type_schema s
   WHERE s.rev=revision AND s.type_id=(identity->>'typeId')::int;
  current_actor:=truss.runtime_person(false);
  FOR dependency IN SELECT value FROM jsonb_array_elements(readers) LOOP
   IF NOT truss.runtime_can_read_qualified(dependency->>'documentId',dependency->>'moduleId',current_actor) THEN
    RAISE EXCEPTION 'current retained property/item reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 ELSIF operation->>'operation' IN ('create_edge','update_edge','delete_edge') THEN
  SELECT r.document_id,r.module INTO STRICT owner_document,owner_module FROM truss.rel_def r WHERE r.rel_type_id=(identity->>'typeId')::int;
 ELSE RAISE EXCEPTION 'retained operation category required' USING ERRCODE='55000';END IF;
 IF identity->'owner' IS DISTINCT FROM jsonb_build_object('documentId',owner_document,'moduleId',owner_module) THEN
  RAISE EXCEPTION 'retained owner correspondence required' USING ERRCODE='55000';END IF;
 RETURN QUERY SELECT owner_document,owner_module;
END;
$function$

CREATE OR REPLACE FUNCTION truss.traverse_objects(start_identity jsonb, hops jsonb, maximum_objects integer, maximum_states integer, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation record;start_type truss.type_def;relation truss.rel_def;hop jsonb;relations int[]:=ARRAY[]::int[];directions text[]:=ARRAY[]::text[];
 captured_revision int;scope record;scope_types int[];types jsonb:='{}';properties_by_type jsonb:='{}';pins jsonb:='{}';properties truss.prop_def[];
 selected_type truss.type_def;observation record;frozen_object truss.object;frozen_root truss.object;root_definition truss.type_def;root_identity jsonb;root_owners jsonb:='{}';root_owner jsonb;objects jsonb:='[]';rendered bytea;result bytea;index int:=0;
BEGIN
 PERFORM truss.runtime_person(false);
 IF maximum_objects IS NULL OR maximum_objects NOT BETWEEN 1 AND 1000 OR maximum_states IS NULL OR maximum_states NOT BETWEEN 1 AND 10000
 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 OR hops IS NULL OR jsonb_typeof(hops) IS DISTINCT FROM 'array'
 OR jsonb_array_length(hops) NOT BETWEEN 1 AND 3 OR octet_length(hops::text)>65536 THEN RAISE EXCEPTION 'bounded traversal required' USING ERRCODE='22023';END IF;
 IF current_setting('transaction_read_only')='on' THEN SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 ELSE SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'selected runtime required' USING ERRCODE='0A000';END IF;
 start_type:=truss.runtime_condition_type(start_identity);scope_types:=ARRAY[start_type.type_id];
 FOR hop IN SELECT value FROM jsonb_array_elements(hops) LOOP
  IF jsonb_typeof(hop) IS DISTINCT FROM 'object' OR hop-ARRAY['relationship','direction']<>'{}'::jsonb OR hop->>'direction' NOT IN ('outgoing','incoming','both')
  OR hop->>'direction' IS NULL OR jsonb_typeof(hop->'relationship') IS DISTINCT FROM 'object'
  OR (hop->'relationship')-ARRAY['kind','definitionPin','owner','authoredIdentity','relationshipId']<>'{}'::jsonb
  OR hop->'relationship'->>'kind' IS DISTINCT FROM 'relationship'
  OR coalesce(hop->'relationship'->>'relationshipId','') !~ '^[1-9][0-9]{0,9}$'
  OR (hop->'relationship'->>'relationshipId')::numeric>2147483647 THEN RAISE EXCEPTION 'qualified traversal hop required' USING ERRCODE='22023';END IF;
  SELECT * INTO relation FROM truss.rel_def WHERE rel_type_id=(hop->'relationship'->>'relationshipId')::int AND retired_rev IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'current relationship required' USING ERRCODE='22023';END IF;
  IF hop->'relationship'->>'definitionPin' IS DISTINCT FROM truss.runtime_relationship_pin(relation.rel_type_id)
  OR hop->'relationship'->>'authoredIdentity' IS DISTINCT FROM relation.rel_id
  OR hop->'relationship'->'owner' IS DISTINCT FROM jsonb_build_object('documentId',relation.document_id,'moduleId',relation.module) THEN RAISE EXCEPTION 'current relationship pin required' USING ERRCODE='22023';END IF;
  IF relation.lifecycle NOT IN ('independent','owned') OR NOT relation.directed OR relation.assoc_type_id IS NOT NULL OR relation.composition THEN RAISE EXCEPTION 'directed traversal required' USING ERRCODE='0A000';END IF;
  IF NOT truss.runtime_can_read(relation.document_id,relation.module) THEN RETURN NULL;END IF;
  relations:=array_append(relations,relation.rel_type_id);directions:=array_append(directions,hop->>'direction');
  FOR scope IN SELECT source_type AS type_id FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id UNION SELECT target_type FROM truss.rel_endpoint WHERE rel_type_id=relation.rel_type_id LOOP scope_types:=array_append(scope_types,scope.type_id);END LOOP;
 END LOOP;
 -- Authorize the full declared expansion scope before observing any edge.
 FOR selected_type IN SELECT * FROM truss.type_def WHERE type_id=ANY(scope_types) LOOP
  IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RETURN NULL;END IF;
  FOR scope IN SELECT DISTINCT declaration_module FROM truss.prop_def WHERE type_id=selected_type.type_id AND retired_rev IS NULL LOOP
   IF NOT truss.runtime_can_read(selected_type.document_id,scope.declaration_module) THEN RETURN NULL;END IF;
  END LOOP;
  types:=types||jsonb_build_object(selected_type.type_id::text,to_jsonb(selected_type));
  properties_by_type:=properties_by_type||jsonb_build_object(selected_type.type_id::text,(SELECT coalesce(jsonb_agg(p ORDER BY p.prop_id),'[]') FROM truss.prop_def p WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL));
  pins:=pins||jsonb_build_object(selected_type.type_id::text,(SELECT definition_pin FROM truss.runtime_owned_definition_metadata('type',selected_type.type_id)));
 END LOOP;
 IF octet_length(types::text)+octet_length(properties_by_type::text)+octet_length(pins::text)>maximum_bytes THEN result:=convert_to('{"outcome":"limited","reason":"retained_bytes"}','UTF8');END IF;
 IF result IS NULL THEN
 -- This single data statement freezes existence, all edges, terminal objects
 -- and row-home facts. No volatile row reader is invoked during rendering.
 FOR observation IN
  WITH RECURSIVE expansion(depth,type_id,id,visited,cycle) AS (
   SELECT 0,o.type_id,o.id,ARRAY[o.type_id::text||':'||o.id::text],false FROM truss.object o WHERE o.type_id=start_type.type_id AND o.id=(start_identity->>'id')::bigint
   UNION ALL
   SELECT p.depth+1,n.type_id,n.id,array_append(p.visited,n.type_id::text||':'||n.id::text),n.type_id::text||':'||n.id::text=ANY(p.visited)
   FROM expansion p JOIN truss.edge e ON e.rel_type_id=relations[p.depth+1]
    AND ((directions[p.depth+1] IN ('outgoing','both') AND e.source_type=p.type_id AND e.source_id=p.id)
     OR (directions[p.depth+1] IN ('incoming','both') AND e.target_type=p.type_id AND e.target_id=p.id))
   CROSS JOIN LATERAL (SELECT e.target_type AS type_id,e.target_id AS id WHERE directions[p.depth+1] IN ('outgoing','both') AND e.source_type=p.type_id AND e.source_id=p.id
    UNION SELECT e.source_type,e.source_id WHERE directions[p.depth+1] IN ('incoming','both') AND e.target_type=p.type_id AND e.target_id=p.id) next
   JOIN truss.object n ON n.type_id=next.type_id AND n.id=next.id
   WHERE p.depth<array_length(relations,1) AND NOT p.cycle
  ), bounded AS MATERIALIZED (SELECT * FROM expansion LIMIT maximum_states+1),
  summary AS (SELECT count(*) AS states FROM bounded),nodes AS (
   SELECT type_id,id,bool_or(depth=array_length(relations,1) AND NOT cycle) AS terminal FROM bounded GROUP BY type_id,id)
  SELECT summary.states,n.terminal,o AS object,ro AS root,rt AS root_definition,
   false AS row_home
  FROM summary LEFT JOIN nodes n ON true LEFT JOIN truss.object o ON o.type_id=n.type_id AND o.id=n.id
  LEFT JOIN truss.object ro ON ro.type_id=o.root_type AND ro.id=o.root_id
  LEFT JOIN truss.type_def rt ON rt.type_id=ro.type_id AND rt.retired_rev IS NULL
  ORDER BY n.type_id,n.id
 LOOP
  IF observation.states>maximum_states THEN result:=convert_to('{"outcome":"limited","reason":"path_states"}','UTF8');END IF;
  IF observation.states=0 THEN result:=convert_to('{"outcome":"not_found"}','UTF8');EXIT;END IF;
  frozen_object:=observation.object;
  IF frozen_object.id IS NULL THEN RAISE EXCEPTION 'captured traversal object required' USING ERRCODE='55000';END IF;
  IF frozen_object.rev>captured_revision THEN RAISE EXCEPTION 'traversal object catalog changed' USING ERRCODE='55P03';END IF;
  frozen_root:=observation.root;root_definition:=observation.root_definition;root_identity:=NULL;
  IF frozen_object.root_id IS NOT NULL OR frozen_object.root_type IS NOT NULL THEN
   IF frozen_object.root_id IS NULL OR frozen_object.root_type IS NULL OR frozen_root.id IS NULL OR root_definition.type_id IS NULL
    OR frozen_root.root_id IS NOT NULL OR frozen_root.root_type IS NOT NULL
    OR frozen_root.id=frozen_object.id AND frozen_root.type_id=frozen_object.type_id
    OR root_definition.kind<>'record' OR root_definition.provisional THEN RAISE EXCEPTION 'captured traversal aggregate root required' USING ERRCODE='55000';END IF;
   IF frozen_root.rev>captured_revision OR root_definition.since_rev>captured_revision THEN RAISE EXCEPTION 'traversal root catalog changed' USING ERRCODE='55P03';END IF;
   IF NOT truss.runtime_can_read(root_definition.document_id,root_definition.module) THEN RETURN NULL;END IF;
   root_owner:=jsonb_build_object('documentId',root_definition.document_id,'moduleId',root_definition.module);
   root_owners:=root_owners||jsonb_build_object(root_owner::text,root_owner);
   IF octet_length(root_owners::text)>16777216 THEN RAISE EXCEPTION 'bounded traversal authority context required' USING ERRCODE='54000';END IF;
   root_identity:=jsonb_build_object('id',frozen_root.id::text,'typeId',frozen_root.type_id::text,
    'definitionPin',(SELECT d.definition_pin FROM truss.runtime_owned_definition_metadata('type',frozen_root.type_id) d),'owner',root_owner);
  END IF;
  IF NOT observation.terminal OR result IS NOT NULL THEN CONTINUE;END IF;
  index:=index+1;
  IF index>maximum_objects THEN result:=convert_to('{"outcome":"limited","reason":"result_limit"}','UTF8');CONTINUE;END IF;
  selected_type:=jsonb_populate_record(NULL::truss.type_def,types->frozen_object.type_id::text);
  SELECT coalesce(array_agg(p ORDER BY p.prop_id),ARRAY[]::truss.prop_def[]) INTO properties FROM jsonb_populate_recordset(NULL::truss.prop_def,properties_by_type->frozen_object.type_id::text) p;
  BEGIN
  rendered:=truss.render_logical_object(frozen_object,selected_type,properties,observation.row_home,pins->>frozen_object.type_id::text,captured_revision,maximum_bytes,expected_release,expected_digest,root_identity);
  EXCEPTION WHEN SQLSTATE '54000' THEN result:=convert_to('{"outcome":"limited","reason":"retained_bytes"}','UTF8');
  END;
  IF result IS NOT NULL THEN CONTINUE;END IF;
  objects:=objects||jsonb_build_array(convert_from(rendered,'UTF8')::jsonb);
  IF octet_length(objects::text)>maximum_bytes THEN result:=convert_to('{"outcome":"limited","reason":"retained_bytes"}','UTF8');END IF;
 END LOOP;
 END IF;
 FOR selected_type IN SELECT * FROM truss.type_def WHERE type_id=ANY(scope_types) LOOP
  IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RETURN NULL;END IF;
  FOR scope IN SELECT DISTINCT declaration_module FROM truss.prop_def WHERE type_id=selected_type.type_id AND retired_rev IS NULL LOOP IF NOT truss.runtime_can_read(selected_type.document_id,scope.declaration_module) THEN RETURN NULL;END IF;END LOOP;
 END LOOP;
 FOR relation IN SELECT * FROM truss.rel_def WHERE rel_type_id=ANY(relations) LOOP IF NOT truss.runtime_can_read(relation.document_id,relation.module) THEN RETURN NULL;END IF;END LOOP;
 FOR root_owner IN SELECT value FROM jsonb_each(root_owners) LOOP
  IF NOT truss.runtime_can_read(root_owner->>'documentId',root_owner->>'moduleId') THEN RETURN NULL;END IF;
 END LOOP;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN RAISE EXCEPTION 'catalog changed during traversal' USING ERRCODE='55P03';END IF;
 IF result IS NULL THEN result:=convert_to(jsonb_build_object('outcome','complete','catalogRevision',captured_revision::text,'objects',objects)::text,'UTF8');END IF;
 IF octet_length(result)>maximum_bytes THEN RETURN convert_to('{"outcome":"limited","reason":"retained_bytes"}','UTF8');END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.umf_key_coefficient(token text, scale integer, precision_limit integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE mantissa text;digits text;exponent_token text;exponent_value bigint:=0;shift bigint;negative boolean;
BEGIN
 IF token IS NULL OR octet_length(token)>1048576 OR token !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?([eE][+-]?[0-9]+)?$'
  OR scale IS NULL OR scale<0 THEN RAISE EXCEPTION 'exact bounded numeric key required' USING ERRCODE='22023';END IF;
 mantissa:=split_part(lower(token),'e',1);negative:=left(token,1)='-';
 digits:=ltrim(replace(ltrim(mantissa,'-'),'.',''),'0');
 IF digits='' THEN RETURN '0';END IF;
 exponent_token:=split_part(lower(token),'e',2);
 IF exponent_token<>'' THEN
  exponent_token:=ltrim(ltrim(exponent_token,'+-'),'0');
  IF length(exponent_token)>18 THEN RAISE EXCEPTION 'numeric key expansion outside domain' USING ERRCODE='22023';END IF;
  exponent_value:=CASE WHEN exponent_token='' THEN 0 ELSE exponent_token::bigint END;
  IF split_part(lower(token),'e',2) LIKE '-%' THEN exponent_value:=-exponent_value;END IF;
 END IF;
 shift:=scale::bigint-length(split_part(mantissa,'.',2))+exponent_value;
 IF shift<0 THEN
  IF -shift>length(digits)-length(rtrim(digits,'0')) THEN RAISE EXCEPTION 'numeric key would require rounding' USING ERRCODE='22023';END IF;
  digits:=left(digits,(length(digits)+shift)::int);
 ELSE
  IF length(digits)::bigint+shift>least(coalesce(precision_limit,1048576),1048576) THEN
   RAISE EXCEPTION 'numeric key expansion exceeds bound' USING ERRCODE='22023';END IF;
  digits:=digits||repeat('0',shift::int);
 END IF;
 IF precision_limit IS NOT NULL AND length(digits)>precision_limit THEN RAISE EXCEPTION 'numeric key exceeds precision' USING ERRCODE='22023';END IF;
 RETURN CASE WHEN negative THEN '-' ELSE '' END||digits;
END;
$function$

CREATE OR REPLACE FUNCTION truss.umf_key_field_values_valid(cells jsonb, fields jsonb, core text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE field jsonb;cell jsonb;literal jsonb;candidate jsonb;facet jsonb;expected bytea;matched boolean;position int:=0;token text;kind text;
BEGIN
 IF core IS DISTINCT FROM '0.10.0' OR jsonb_array_length(cells)<>jsonb_array_length(fields) THEN RETURN false;END IF;
 FOR field IN SELECT value FROM jsonb_array_elements(fields) LOOP
  cell:=cells->position;position:=position+1;kind:=field->>'scalarType';facet:=coalesce(field->'facets','{}');
  IF field->>'kind' IS DISTINCT FROM 'field' OR field->>'cardinality' IS DISTINCT FROM 'one'
   OR field->>'nullability' IS DISTINCT FROM 'required' OR cell->>'kind' IS DISTINCT FROM kind THEN RETURN false;END IF;
  token:=cell->>'text';
  IF core='0.10.0' AND kind IN ('integer','decimal') AND length(split_part(lower(token),'e',2))>32
   AND ltrim(replace(ltrim(split_part(lower(token),'e',1),'-'),'.',''),'0')<>'' THEN RETURN false;END IF;
  IF NOT field ? 'allowedValues' THEN CONTINUE;END IF;
  IF core<>'0.10.0' OR jsonb_typeof(field->'allowedValues') IS DISTINCT FROM 'array' THEN RETURN false;END IF;
  expected:=truss.encode_umf_scalar_key_tuple(jsonb_build_array(cell),jsonb_build_array(facet));matched:=false;
  FOR literal IN SELECT value FROM jsonb_array_elements(field->'allowedValues') LOOP
   CASE kind
    WHEN 'boolean' THEN candidate:=jsonb_build_object('kind',kind,'value',literal->'boolean');
    WHEN 'string' THEN candidate:=jsonb_build_object('kind',kind,'text',literal->'string');
    WHEN 'binary' THEN candidate:=jsonb_build_object('kind',kind,'text',replace(encode(decode(literal->>'binaryHex','hex'),'base64'),chr(10),''));
    WHEN 'integer' THEN candidate:=jsonb_build_object('kind',kind,'text',truss.umf_key_coefficient(literal->>'integerToken',0));
    WHEN 'decimal' THEN candidate:=jsonb_build_object('kind',kind,'text',literal->'decimalToken');
    ELSE RETURN false;
   END CASE;
   IF truss.encode_umf_scalar_key_tuple(jsonb_build_array(candidate),jsonb_build_array(facet))=expected THEN matched:=true;EXIT;END IF;
  END LOOP;
  IF NOT matched THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.umf_key_uleb128(number bigint)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result bytea:=''::bytea;digit int;
BEGIN
 IF number IS NULL OR number<0 THEN RAISE EXCEPTION 'unsigned key framing required' USING ERRCODE='22023';END IF;
 LOOP
  digit:=(number%128)::int;number:=number/128;
  result:=result||set_byte(decode('00','hex'),0,digit+CASE WHEN number>0 THEN 128 ELSE 0 END);
  EXIT WHEN number=0;
 END LOOP;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.umf_key_values(cells jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE cell jsonb;result jsonb:='[]';
BEGIN
 IF jsonb_typeof(cells) IS DISTINCT FROM 'array' OR jsonb_array_length(cells) NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'bounded key cells required' USING ERRCODE='22023';END IF;
 FOR cell IN SELECT value FROM jsonb_array_elements(cells) LOOP
  IF truss.valid_scalar_cell(cell,NULL,false) IS NOT TRUE OR cell->>'kind' NOT IN ('string','integer','decimal','boolean','binary') THEN RAISE EXCEPTION 'exact key family required' USING ERRCODE='22023';END IF;
  result:=result||jsonb_build_array(CASE cell->>'kind'
   WHEN 'string' THEN jsonb_build_object('string',cell->'text')
   WHEN 'integer' THEN jsonb_build_object('integerToken',cell->'text')
   WHEN 'decimal' THEN jsonb_build_object('decimalToken',cell->'text')
   WHEN 'boolean' THEN jsonb_build_object('boolean',cell->'value')
   WHEN 'binary' THEN jsonb_build_object('binaryHex',encode(decode(cell->>'text','base64'),'hex')) END);
 END LOOP;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.valid_decimal_facets(facets jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE precision_value numeric;scale_value numeric;
BEGIN
 IF jsonb_typeof(facets) IS DISTINCT FROM 'object' OR facets-ARRAY['precision','scale']<>'{}'::jsonb
  OR jsonb_typeof(facets->'precision') IS DISTINCT FROM 'number' OR jsonb_typeof(facets->'scale') IS DISTINCT FROM 'number' THEN RETURN false;END IF;
 precision_value:=(facets->>'precision')::numeric;scale_value:=(facets->>'scale')::numeric;
 RETURN precision_value=trunc(precision_value) AND scale_value=trunc(scale_value)
  AND precision_value BETWEEN 1 AND 2147483647 AND scale_value BETWEEN 0 AND precision_value;
END;
$function$

CREATE OR REPLACE FUNCTION truss.valid_flat_cell(cell jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE member jsonb;cell_node jsonb;entry jsonb;pending jsonb[];head int:=1;tail int:=1;depth int;count_nodes int:=0;
BEGIN
 IF cell IS NULL OR octet_length(cell::text)>1048576 THEN RETURN false;END IF;
 IF truss.valid_scalar_cell(cell) IS TRUE THEN RETURN true;END IF;
 pending:=array_fill(NULL::jsonb,ARRAY[4096]);pending[1]:=jsonb_build_object('cell',cell,'depth',0);
 WHILE head<=tail LOOP
  entry:=pending[head];pending[head]:=NULL;head:=head+1;cell_node:=entry->'cell';depth:=(entry->>'depth')::int;count_nodes:=count_nodes+1;
  IF depth>32 OR count_nodes>4096 THEN RETURN false;END IF;
  IF truss.valid_scalar_cell(cell_node) IS TRUE THEN CONTINUE;END IF;
  IF jsonb_typeof(cell_node) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
  IF cell_node->>'kind'='sequence' THEN
   IF cell_node-ARRAY['kind','items']<>'{}'::jsonb OR jsonb_typeof(cell_node->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(cell_node->'items')>1024 THEN RETURN false;END IF;
   FOR member IN SELECT value FROM jsonb_array_elements(cell_node->'items') LOOP
    IF tail>=4096 THEN RETURN false;END IF;tail:=tail+1;pending[tail]:=jsonb_build_object('cell',member,'depth',depth+1);
   END LOOP;
  ELSIF cell_node->>'kind'='map' THEN
   IF cell_node-ARRAY['kind','entries']<>'{}'::jsonb OR jsonb_typeof(cell_node->'entries') IS DISTINCT FROM 'array' OR jsonb_array_length(cell_node->'entries')>1024 THEN RETURN false;END IF;
   IF jsonb_array_length(cell_node->'entries')<>(SELECT count(DISTINCT value->>'key' COLLATE "C") FROM jsonb_array_elements(cell_node->'entries')) THEN RETURN false;END IF;
   FOR member IN SELECT value FROM jsonb_array_elements(cell_node->'entries') LOOP
    IF jsonb_typeof(member) IS DISTINCT FROM 'object' OR member-ARRAY['key','value']<>'{}'::jsonb OR jsonb_typeof(member->'key') IS DISTINCT FROM 'string' OR octet_length(member->>'key')>4096 THEN RETURN false;END IF;
    IF tail>=4096 THEN RETURN false;END IF;tail:=tail+1;pending[tail]:=jsonb_build_object('cell',member->'value','depth',depth+1);
   END LOOP;
  ELSE RETURN false;END IF;
  IF tail>4096 THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.valid_item_chain(item jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE nodes jsonb;node jsonb;declaration jsonb;seen jsonb:='[]';index_node int;family text;facets jsonb;
BEGIN
 IF item IS NULL OR jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(coalesce(item->'descendants','[]'::jsonb)) IS DISTINCT FROM 'array' THEN RETURN false;END IF;
 nodes:=jsonb_build_array(item)||coalesce(item->'descendants','[]'::jsonb);
 IF jsonb_array_length(nodes)>32 THEN RETURN false;END IF;
 FOR index_node IN 0..jsonb_array_length(nodes)-1 LOOP
  node:=nodes->index_node;declaration:=node->'declaration';family:=declaration->>'scalarType';facets:=declaration->'facets';
  IF jsonb_typeof(node->'reference') IS DISTINCT FROM 'object' OR seen @> jsonb_build_array(node->'reference')
   OR declaration->>'kind' IS DISTINCT FROM 'field' OR declaration->>'nullability' IS DISTINCT FROM 'required' THEN RETURN false;END IF;
  seen:=seen||jsonb_build_array(node->'reference');
  IF index_node=jsonb_array_length(nodes)-1 THEN
   IF declaration->>'cardinality' IS DISTINCT FROM 'one' OR family IS NULL OR family NOT IN ('string','integer','decimal','boolean','timestamp','binary','date') OR declaration ? 'itemType'
    OR truss.known_scalar_facets(family,facets) IS NOT TRUE THEN RETURN false;END IF;
  ELSE
   IF (declaration->>'cardinality' IN ('array','map')) IS NOT TRUE OR declaration ? 'scalarType' OR coalesce(facets,'{}')<>'{}'::jsonb
    OR declaration->'itemType' IS DISTINCT FROM nodes->(index_node+1)->'reference' THEN RETURN false;END IF;
  END IF;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.valid_property_definition(property truss.prop_def)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE example jsonb;
BEGIN
 IF property.cardinality IN ('array','map') THEN example:=CASE property.cardinality WHEN 'array' THEN '{"kind":"sequence","items":[]}'::jsonb ELSE '{"kind":"map","entries":[]}'::jsonb END;
 ELSIF property.scalar_type='boolean' THEN example:='{"kind":"boolean","value":false}'::jsonb;
 ELSE example:=jsonb_build_object('kind',property.scalar_type,'text',CASE property.scalar_type WHEN 'integer' THEN '0' WHEN 'decimal' THEN '0' WHEN 'date' THEN '2000-01-01' WHEN 'timestamp' THEN '2000-01-01T00:00:00Z' ELSE '' END);END IF;
 RETURN truss.valid_property_value(example,property) IS TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION truss.valid_property_value(cell jsonb, property truss.prop_def)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE nodes jsonb;node jsonb;member jsonb;entry jsonb;declaration jsonb;pending jsonb[];head int:=1;tail int:=0;index_node int;
BEGIN
 IF property.cardinality='one' THEN RETURN property.home='json' AND coalesce(property.scalar_type,'') IN ('string','integer','decimal','boolean','timestamp','binary','date') AND property.nullability IN ('required','absent-allowed') AND property.item IS NULL AND truss.valid_scalar_property(cell,property.scalar_type,property.nullability='absent-allowed',property.facets);END IF;
 IF property.cardinality NOT IN ('array','map') OR property.scalar_type IS NOT NULL OR property.home IS DISTINCT FROM 'json'
  OR property.nullability NOT IN ('required','absent-allowed') OR coalesce(property.facets,'{}')<>'{}'::jsonb OR truss.valid_item_chain(property.item) IS NOT TRUE THEN RETURN false;END IF;
 IF cell='{"kind":"null"}'::jsonb THEN RETURN property.nullability='absent-allowed';END IF;
 IF truss.valid_flat_cell(cell) IS NOT TRUE OR cell->>'kind' IS DISTINCT FROM (CASE property.cardinality WHEN 'array' THEN 'sequence' ELSE 'map' END) THEN RETURN false;END IF;
 nodes:=jsonb_build_array(property.item)||coalesce(property.item->'descendants','[]'::jsonb);
 pending:=array_fill(NULL::jsonb,ARRAY[4096]);
 FOR member IN SELECT CASE property.cardinality WHEN 'array' THEN value ELSE value->'value' END FROM jsonb_array_elements(CASE property.cardinality WHEN 'array' THEN cell->'items' ELSE cell->'entries' END) LOOP
  IF tail>=4096 THEN RETURN false;END IF;tail:=tail+1;pending[tail]:=jsonb_build_object('cell',member,'index',0);
 END LOOP;
 WHILE head<=tail LOOP
  entry:=pending[head];pending[head]:=NULL;head:=head+1;member:=entry->'cell';index_node:=(entry->>'index')::int;node:=nodes->index_node;declaration:=node->'declaration';
  IF declaration->>'cardinality'='one' THEN
   IF truss.valid_scalar_property(member,declaration->>'scalarType',false,declaration->'facets') IS NOT TRUE THEN RETURN false;END IF;
  ELSE
   IF member->>'kind' IS DISTINCT FROM (CASE declaration->>'cardinality' WHEN 'array' THEN 'sequence' ELSE 'map' END) THEN RETURN false;END IF;
   FOR member IN SELECT CASE declaration->>'cardinality' WHEN 'array' THEN value ELSE value->'value' END FROM jsonb_array_elements(CASE declaration->>'cardinality' WHEN 'array' THEN member->'items' ELSE member->'entries' END) LOOP
    IF tail>=4096 THEN RETURN false;END IF;tail:=tail+1;pending[tail]:=jsonb_build_object('cell',member,'index',index_node+1);
   END LOOP;
  END IF;
 END LOOP;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.valid_scalar_cell(cell jsonb, expected_family text DEFAULT NULL::text, allow_null boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE family text;token text;calendar date;offset_text text;
BEGIN
 IF cell IS NULL OR jsonb_typeof(cell)<>'object' THEN RETURN false;END IF;
 IF cell='{"kind":"null"}'::jsonb THEN RETURN allow_null;END IF;
 family:=cell->>'kind';
 IF expected_family IS NOT NULL AND family IS DISTINCT FROM expected_family THEN RETURN false;END IF;
 IF family='boolean' THEN RETURN jsonb_typeof(cell->'value')='boolean' AND cell=jsonb_build_object('kind',family,'value',cell->'value');END IF;
 IF family NOT IN ('string','integer','decimal','timestamp','binary','date') OR jsonb_typeof(cell->'text') IS DISTINCT FROM 'string'
  OR cell IS DISTINCT FROM jsonb_build_object('kind',family,'text',cell->'text') THEN RETURN false;END IF;
 token:=cell->>'text';
 IF octet_length(token)>1048576 THEN RETURN false;END IF;
 IF family='string' THEN RETURN true;
 ELSIF family='integer' THEN RETURN token ~ '^-?(0|[1-9][0-9]*)$';
 ELSIF family='decimal' THEN RETURN token ~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?([eE][+-]?[0-9]+)?$';
 ELSIF family='binary' THEN
  IF token !~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' THEN RETURN false;END IF;
  RETURN replace(encode(decode(token,'base64'),'base64'),chr(10),'')=token;
 ELSIF family='date' THEN
  IF token !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR substring(token,1,4)::int=0 THEN RETURN false;END IF;
  calendar:=make_date(substring(token,1,4)::int,substring(token,6,2)::int,substring(token,9,2)::int);
  RETURN true;
 ELSIF family='timestamp' THEN
  IF token !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?([Zz]|[+-][0-9]{2}:[0-9]{2})$'
   OR substring(token,1,4)::int=0 OR substring(token,12,2)::int>23 OR substring(token,15,2)::int>59 OR substring(token,18,2)::int>59 THEN RETURN false;END IF;
  calendar:=make_date(substring(token,1,4)::int,substring(token,6,2)::int,substring(token,9,2)::int);
  IF lower(right(token,1))<>'z' THEN
   offset_text:=right(token,6);
   IF substring(offset_text,2,2)::int>23 OR substring(offset_text,5,2)::int>59 THEN RETURN false;END IF;
  END IF;
  RETURN true;
 END IF;
 RETURN false;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR invalid_parameter_value THEN RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION truss.valid_scalar_property(cell jsonb, family text, allow_null boolean, facets jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE token text;limit_text text;mantissa text;exponent_token text;coefficient text;fraction_length int;shift bigint;trailing_zero_count int;exponent_value bigint:=0;maximum bigint;
BEGIN
 IF truss.valid_scalar_cell(cell,family,allow_null) IS NOT TRUE THEN RETURN false;END IF;
 IF facets IS NULL OR facets='{}'::jsonb THEN RETURN true;END IF;
 IF (family='string' AND facets#>>'{length,unit}'='unicode-scalar'
     OR family='binary' AND facets#>>'{length,unit}'='byte')
    AND truss.valid_length_facets(facets) THEN
  IF cell='{"kind":"null"}'::jsonb THEN RETURN allow_null;END IF;
  token:=cell->>'text';maximum:=(facets#>>'{length,max}')::numeric::bigint;
  IF family='binary' THEN RETURN octet_length(decode(token,'base64'))<=maximum;END IF;
  RETURN char_length(token)<=maximum;
 END IF;
 IF family='decimal' AND truss.valid_decimal_facets(facets) THEN
  IF cell='{"kind":"null"}'::jsonb THEN RETURN allow_null;END IF;
  token:=cell->>'text';mantissa:=split_part(lower(token),'e',1);
  fraction_length:=length(split_part(mantissa,'.',2));
  coefficient:=ltrim(replace(ltrim(mantissa,'-'),'.',''),'0');
  IF coefficient='' THEN RETURN true;END IF;
  exponent_token:=split_part(lower(token),'e',2);
  IF exponent_token<>'' THEN
   limit_text:=left(exponent_token,1);exponent_token:=ltrim(ltrim(exponent_token,'+-'),'0');
   IF length(exponent_token)>18 THEN RETURN false;END IF;
   exponent_value:=CASE WHEN exponent_token='' THEN 0 ELSE exponent_token::bigint END;
   IF limit_text='-' THEN exponent_value:=-exponent_value;END IF;
  END IF;
  shift:=(facets->>'scale')::numeric::bigint-fraction_length+exponent_value;
  trailing_zero_count:=length(coefficient)-length(rtrim(coefficient,'0'));
  -- Exact fixed-scale coefficient: no numeric typmod, casts or rounding.
  IF shift<0 AND -shift>trailing_zero_count THEN RETURN false;END IF;
  RETURN length(coefficient)+shift<=(facets->>'precision')::numeric::int;
 END IF;
 IF family IS DISTINCT FROM 'integer' OR facets IS DISTINCT FROM '{"integerWidth":{"bits":64,"signed":true}}'::jsonb THEN RETURN false;END IF;
 IF cell='{"kind":"null"}'::jsonb THEN RETURN allow_null;END IF;
 token:=cell->>'text';limit_text:='9223372036854775807';
 IF left(token,1)='-' THEN token:=substring(token,2);limit_text:='9223372036854775808';END IF;
 RETURN length(token)<19 OR (length(token)=19 AND token COLLATE pg_catalog."C"<=limit_text COLLATE pg_catalog."C");
END;
$function$

CREATE OR REPLACE FUNCTION truss.validate_batched_import_report(original_input bytea, original_outcomes bytea, original_context bytea, expected_release text, expected_digest text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE input jsonb;outcomes jsonb;context jsonb;item jsonb;record jsonb;
BEGIN
 IF octet_length(original_input)>8388608 OR octet_length(original_outcomes)>8388608 OR octet_length(original_context)>1048576 THEN RAISE EXCEPTION 'bounded original report required' USING ERRCODE='54000';END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;outcomes:=convert_from(original_outcomes,'UTF8')::jsonb;context:=convert_from(original_context,'UTF8')::jsonb;
 IF convert_from(truss.batched_import_context(expected_release,expected_digest),'UTF8')::jsonb IS DISTINCT FROM context THEN RAISE EXCEPTION 'original report context required' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(outcomes) LOOP
  IF item->>'outcome' IN ('created','skipped') THEN
   record:=input->'records'->(item->>'inputIndex')::int;
   PERFORM truss.import_report_record_authority(convert_to(jsonb_build_object('originalIdentity',record->'identity','outcomeIdentity',item->'identity')::text,'UTF8'),record->>'kind',expected_release,expected_digest);
  END IF;
 END LOOP;
 IF convert_from(truss.batched_import_context(expected_release,expected_digest),'UTF8')::jsonb IS DISTINCT FROM context THEN RAISE EXCEPTION 'original report authority changed' USING ERRCODE='42501';END IF;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION truss.verify_object_string_key(selected_object bigint, selected_type integer, selected_key smallint, tuple_bytes bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE object_row truss.object%ROWTYPE; key_row truss.key_def%ROWTYPE;
 component record;cell jsonb;actual_values text[]:=ARRAY[]::text[];counted int:=0;cells jsonb:='[]';key_facets jsonb:='[]';
BEGIN
 SELECT * INTO object_row FROM truss.object WHERE id=selected_object AND type_id=selected_type;
 IF NOT FOUND THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM truss.type_def WHERE type_id=selected_type
   AND kind='record' AND NOT provisional AND retired_rev IS NULL) THEN RETURN false; END IF;
 SELECT * INTO key_row FROM truss.key_def WHERE type_id=selected_type AND key_num=selected_key AND retired_rev IS NULL;
 IF NOT FOUND OR cardinality(key_row.prop_ids) NOT BETWEEN 1 AND 1024 THEN RETURN false; END IF;
 FOR component IN SELECT p.prop_id,p.scalar_type,p.retired_rev,p.home,p.cardinality,p.nullability,p.facets
  FROM unnest(key_row.prop_ids) WITH ORDINALITY k(prop_id,ord)
  JOIN truss.prop_def p ON p.prop_id=k.prop_id AND p.type_id=selected_type ORDER BY k.ord LOOP
  counted:=counted+1;
  IF component.scalar_type NOT IN ('string','integer','decimal','boolean','binary') OR component.retired_rev IS NOT NULL
   OR component.home IS DISTINCT FROM 'json' OR component.cardinality IS DISTINCT FROM 'one'
   OR component.nullability IS DISTINCT FROM 'required' THEN RETURN false; END IF;
  cell:=object_row.props->component.prop_id::text;
  IF truss.valid_scalar_property(cell,component.scalar_type,false,component.facets) IS NOT TRUE THEN RETURN false;END IF;
  cells:=cells||jsonb_build_array(cell);key_facets:=key_facets||jsonb_build_array(coalesce(component.facets,'{}'::jsonb));
 END LOOP;
 IF counted<>cardinality(key_row.prop_ids) THEN RETURN false; END IF;
 RETURN truss.verify_umf_scalar_key_tuple(tuple_bytes,cells,key_facets);
END;
$function$

CREATE OR REPLACE FUNCTION truss.verify_umf_string_key_tuple(tuple_bytes bytea, actual_values text[])
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE position int:=5;total int;component_count int;value_count int;
 number bigint;multiplier bigint;digit int;octet int;prefix_count int;
 field_value text;payload bytea;expected_length int;
BEGIN
 IF tuple_bytes IS NULL OR actual_values IS NULL OR array_ndims(actual_values) IS DISTINCT FROM 1
  OR array_lower(actual_values,1) IS DISTINCT FROM 1 THEN RETURN false; END IF;
 total:=octet_length(tuple_bytes);value_count:=cardinality(actual_values);
 IF total NOT BETWEEN 7 AND 1048576 OR value_count NOT BETWEEN 1 AND 1024
  OR substring(tuple_bytes FROM 1 FOR 5)<>convert_to('UMFK1','UTF8') THEN RETURN false; END IF;
 number:=0;multiplier:=1;prefix_count:=0;
 LOOP
  IF position>=total OR prefix_count>=3 THEN RETURN false; END IF;
  octet:=get_byte(tuple_bytes,position);position:=position+1;prefix_count:=prefix_count+1;
  digit:=octet & 127;number:=number+digit*multiplier;
  IF number>1024 THEN RETURN false; END IF;
  IF octet<128 THEN
   IF prefix_count>1 AND digit=0 THEN RETURN false; END IF;
   EXIT;
  END IF;
  multiplier:=multiplier*128;
 END LOOP;
 component_count:=number::int;
 IF component_count<>value_count THEN RETURN false; END IF;
 FOREACH field_value IN ARRAY actual_values LOOP
  IF field_value IS NULL OR octet_length(field_value)>1048576 OR position>=total OR get_byte(tuple_bytes,position)<>4 THEN RETURN false; END IF;
  position:=position+1;number:=0;multiplier:=1;prefix_count:=0;
  LOOP
   IF position>=total OR prefix_count>=3 THEN RETURN false; END IF;
   octet:=get_byte(tuple_bytes,position);position:=position+1;prefix_count:=prefix_count+1;
   digit:=octet & 127;number:=number+digit*multiplier;
   IF number>1048576 THEN RETURN false; END IF;
   IF octet<128 THEN
    IF prefix_count>1 AND digit=0 THEN RETURN false; END IF;
    EXIT;
   END IF;
   multiplier:=multiplier*128;
  END LOOP;
  payload:=convert_to(field_value,'UTF8');expected_length:=octet_length(payload);
  IF number<>expected_length OR number>total-position
   OR substring(tuple_bytes FROM position+1 FOR expected_length)<>payload THEN RETURN false; END IF;
  position:=position+expected_length;
 END LOOP;
 RETURN position=total;
END;
$function$

CREATE OR REPLACE FUNCTION truss.writer_schema_basis(original_input bytea, original_documents bytea, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE input jsonb;documents jsonb;ops jsonb;operation jsonb;actor oid;installation truss.catalog_runtime_installation%ROWTYPE;
 selected_revision int;registration uuid;required_types int[];records jsonb;declaration_count bigint;result_bytes bytea;
BEGIN
 IF original_input IS NULL OR octet_length(original_input) NOT BETWEEN 1 AND 1048576
  OR original_documents IS NULL OR octet_length(original_documents) NOT BETWEEN 1 AND 4194304
  OR (convert_from(original_input,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
  OR (convert_from(original_documents,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN RETURN NULL;END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;documents:=convert_from(original_documents,'UTF8')::jsonb;ops:=input->'operations';
 IF input->>'interfaceVersion'<>'truss-group-input/0.1.0' OR input->'catalog'<>'{"selection":"current"}'::jsonb
  OR input->'mutationProfile' IS DISTINCT FROM truss.runtime_owned_profile()
  OR jsonb_typeof(ops)<>'array' OR jsonb_array_length(ops) NOT BETWEEN 1 AND 1024 THEN RETURN NULL;END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN RETURN NULL;END IF;
 SELECT rev INTO STRICT selected_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 SELECT reg.registration_id INTO STRICT registration FROM truss.catalog_registration_request reg WHERE reg.revision=selected_revision;
 actor:=truss.runtime_person(false);
 FOR operation IN SELECT value FROM jsonb_array_elements(ops) LOOP
  IF operation->>'operation' IS NULL OR operation->>'operation' NOT IN ('create_object','update_object') OR operation ? 'ownershipChange' THEN RETURN NULL;END IF;
  IF operation->>'operation'='create_object' AND (operation->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb
   OR jsonb_typeof(operation->'typeDefinitionPin') IS DISTINCT FROM 'string') THEN RETURN NULL;END IF;
  IF operation->>'operation'='update_object' AND (operation->'target'->>'state' IS NULL OR operation->'target'->>'state' NOT IN ('stored','alias')
   OR operation->'target'->>'state'='stored' AND jsonb_typeof(operation->'target'->'identity') IS DISTINCT FROM 'object'
   OR operation->'target'->>'state'='alias' AND jsonb_typeof(operation->'target'->'alias') IS DISTINCT FROM 'string') THEN RETURN NULL;END IF;
 END LOOP;
 -- Resolve one representative per exact type pin / stored type identity. The
 -- native helper still owns identity rules, while duplicate operations avoid
 -- repeating source-pin derivation during cold cache construction.
 WITH indexed AS MATERIALIZED (
  SELECT value operation,(ordinality-1)::int operation_index
  FROM jsonb_array_elements(ops) WITH ORDINALITY o(value,ordinality)
 ), keyed AS MATERIALIZED (
  SELECT indexed.operation AS op_json,indexed.operation_index,
   CASE WHEN indexed.operation->>'operation'='create_object' THEN indexed.operation->>'typeDefinitionPin'
    WHEN indexed.operation->'target'->>'state'='stored' THEN indexed.operation->'target'->'identity'->>'definitionPin'
    ELSE (SELECT c.operation->>'typeDefinitionPin' FROM indexed c
     WHERE c.operation->>'operation'='create_object' AND c.operation->>'alias'=indexed.operation->'target'->>'alias'
      AND c.operation_index<indexed.operation_index ORDER BY c.operation_index LIMIT 1) END definition_pin,
   CASE WHEN indexed.operation->'target'->>'state'='stored' THEN indexed.operation->'target'->'identity'->>'typeId' END stored_type
  FROM indexed
 ), representatives AS MATERIALIZED (
  SELECT DISTINCT ON(definition_pin,stored_type) op_json,operation_index
  FROM keyed WHERE definition_pin IS NOT NULL ORDER BY definition_pin,stored_type,operation_index
 )
 SELECT coalesce(array_agg(DISTINCT q.type_id) FILTER(WHERE q.type_id IS NOT NULL),'{}'::int[]) INTO required_types
 FROM (SELECT (truss.runtime_owned_operation_type_qualified(r.op_json,ops,r.operation_index,actor)).type_id AS type_id
  FROM representatives r) q;
 IF cardinality(required_types)=0 THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM truss.type_def t JOIN unnest(required_types) r(type_id) USING(type_id)
  WHERE NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
    SELECT actor UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
   SELECT 1 FROM truss.module_access ma JOIN pg_roles r ON r.rolname::text=ma.writer_role
    JOIN memberships m ON m.role_oid=r.oid WHERE ma.document_id=t.document_id AND ma.module=t.module)) THEN RETURN NULL;END IF;
 -- The supplied source set must be an exact current snapshot. This query is
 -- set-based across documents, including documents unrelated to the selected
 -- operations, so a cold application cache has one stable revision boundary.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(documents) d
  LEFT JOIN LATERAL (SELECT sd.document FROM truss.schema_doc sd WHERE sd.doc_id=d.value->>'documentId' ORDER BY sd.rev DESC LIMIT 1) a ON true
  WHERE jsonb_typeof(d.value)<>'object' OR jsonb_typeof(d.value->'sourceText')<>'string'
   OR a.document IS NULL OR convert_to(d.value->>'sourceText','UTF8') IS DISTINCT FROM convert_to(a.document,'UTF8')) THEN RETURN NULL;END IF;
 WITH RECURSIVE memberships(role_oid) AS (
  SELECT actor UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid
 ), candidates AS MATERIALIZED (
  SELECT t.type_id,t.document_id,t.module,compiled.metadata->>'typePin' definition_pin
  FROM truss.type_def t JOIN truss.runtime_type_schema compiled ON compiled.rev=selected_revision AND compiled.type_id=t.type_id
  WHERE t.kind='record' AND NOT t.provisional AND t.retired_rev IS NULL
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(documents) d WHERE d.value->>'documentId'=t.document_id)
   AND truss.runtime_object_values_readable_qualified(t.type_id,actor)
   AND EXISTS(SELECT 1 FROM truss.module_access ma JOIN pg_roles r ON r.rolname::text=ma.writer_role
    JOIN memberships m ON m.role_oid=r.oid WHERE ma.document_id=t.document_id AND ma.module=t.module)
 ), properties AS MATERIALIZED (
  SELECT p.type_id,jsonb_agg(jsonb_build_object('name',p.name,'prop_id',p.prop_id,'home',p.home,
   'cardinality',p.cardinality,'nullability',p.nullability,'scalar_type',p.scalar_type,
   'facets',p.facets,'item',p.item) ORDER BY p.prop_id) rows
  FROM truss.prop_def p JOIN candidates c USING(type_id) WHERE p.retired_rev IS NULL GROUP BY p.type_id
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object('typeId',c.type_id::text,'definitionPin',c.definition_pin,
  'properties',coalesce(p.rows,'[]'::jsonb)) ORDER BY c.type_id),'[]'::jsonb)
 INTO records FROM candidates c LEFT JOIN properties p USING(type_id);
 SELECT coalesce(sum(jsonb_array_length(r.value->'properties')),0) INTO declaration_count
 FROM jsonb_array_elements(records) r;
 IF declaration_count>65536 THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM unnest(required_types) required(type_id)
  WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(records) r WHERE r.value->>'typeId'=required.type_id::text)) THEN RETURN NULL;END IF;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM selected_revision THEN RETURN NULL;END IF;
 result_bytes:=convert_to(jsonb_build_object('basis',jsonb_build_object('installationId',installation.installation_id::text,
  'releaseSha256',installation.release_sha256,'sourceEpoch',installation.source_epoch::text,'catalogRevision',selected_revision,'registrationId',registration::text,
  'documentsSha256',encode(sha256(original_documents),'hex')),'records',records)::text,'UTF8');
 IF octet_length(result_bytes)>16777216 THEN RETURN NULL;END IF;
 RETURN result_bytes;
EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '42501' OR SQLSTATE '0A000' OR SQLSTATE '54000' OR SQLSTATE '55P03' OR SQLSTATE 'P0002' THEN
 RETURN NULL;
END;
$function$
